insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('carnes_062', 'Entrecot con patatas fritas y salsa de queso azul', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 720, 46, 34, 44, 2, false, false, '{"lactosa"}', '[{"name":"Entrecot de ternera","amount":500,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de girasol","amount":400,"unit":"ml"},{"name":"Queso azul","amount":80,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes.","Secar los bastones de patata con un paño limpio para eliminar el exceso de humedad.","Calentar aceite de girasol en una sartén honda a 160 °C.","Freír los bastones de patata a 160 °C durante 6 min hasta que estén tiernos pero sin dorar.","Escurrir las patatas y reservar. Subir el aceite a 190 °C.","Freír de nuevo las patatas a 190 °C durante 3 min hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salar con sal.","Calentar nata para cocinar en un cazo a fuego suave.","Añadir queso azul troceado y mantequilla al cazo.","Remover a fuego suave hasta que el queso y la mantequilla se fundan y la salsa sea homogénea.","Retirar la salsa del fuego y reservar caliente.","Salpimentar entrecot de ternera por ambos lados con sal al gusto y pimienta negra.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar el entrecot 3 min por cada lado para un punto medio, ajustando según el punto deseado.","Retirar el entrecot de la plancha y dejar reposar 3 min para que los jugos se asienten.","Cortar el entrecot en lonchas.","Servir el entrecot en lonchas junto a las patatas fritas y la salsa de queso azul aparte o por encima."}', 'Entrecot con patatas fritas caseras y una cremosa salsa de queso azul.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina las patatas en la airfryer a 190°C por 20-25 min hasta que estén doradas y crujientes. Después, el entrecot a 200°C por 12-15 min, volteándolo a mitad para un sellado perfecto, mientras la salsa se prepara en un cazo aparte."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C y hornea las patatas con un poco de aceite durante 30-35 min, volteándolas a mitad. Mientras, sella el entrecot en una sartén y termínalo en el horno a 180°C por 10-15 min, preparando la salsa en un cazo aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_063', 'Steak frites con mantequilla de perejil', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 680, 40, 36, 40, 2, true, false, '{"lactosa"}', '[{"name":"Entrecot de ternera","amount":400,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de girasol","amount":400,"unit":"ml"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":3,"unit":"g"}]'::jsonb, '{"Sacar mantequilla de la nevera y dejar atemperar hasta que esté blanda.","Picar perejil fresco muy fino.","Rallar ajo.","Mezclar la mantequilla blanda con el perejil picado y el ajo rallado hasta obtener una pasta homogénea.","Formar un cilindro con la pasta de mantequilla envuelto en film transparente.","Refrigerar el cilindro de mantequilla hasta que esté firme.","Pelar patata y cortarlas en bastones uniformes.","Secar bien los bastones de patata con un paño limpio.","Calentar aceite de girasol en una olla a 160 °C a fuego medio.","Freír los bastones de patata a 160 °C hasta que estén tiernos pero sin color, unos 6 min.","Escurrir los bastones de patata sobre papel absorbente y reservar.","Subir el aceite a 190 °C a fuego fuerte.","Salpimentar entrecot de ternera por ambas caras con sal y pimienta negra.","Calentar plancha a fuego fuerte hasta que humee.","Freír de nuevo los bastones de patata a 190 °C durante 2-3 min hasta que estén dorados y crujientes.","Cocinar los entrecots en la plancha 2-3 min por cada lado, según el punto deseado.","Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","Retirar los entrecots de la plancha y reposar 2 min antes de emplatar.","Cortar unas rodajas del cilindro de mantequilla de perejil.","Colocar las rodajas de mantequilla de perejil sobre los entrecots calientes y dejar que se derritan.","Servir los entrecots junto a las patatas fritas."}', 'El clásico filete francés con patatas fritas y una mantequilla de perejil que se derrite encima.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara las patatas en la airfryer a 190°C durante 20-25 minutos, agitándolas. Luego, cocina el entrecot sazonado a 200°C por 10-15 minutos, volteándolo a mitad, para un resultado jugoso y con menos grasa."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Hornea las patatas cortadas en bastones con un poco de aceite a 200°C durante 35-40 minutos, dándoles la vuelta. El entrecot se puede sellar en sartén y terminar en el horno a 200°C por 10-15 minutos para un punto perfecto."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_064', 'Hamburguesa gourmet con cheddar curado y bacon', 'carnes', 'ternera', 'pan', ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 760, 42, 42, 46, 2, true, false, '{"gluten","lactosa","mostaza"}', '[{"name":"Carne picada de ternera","amount":350,"unit":"g"},{"name":"Pan de hamburguesa brioche","amount":2,"unit":"ud"},{"name":"Queso cheddar curado en lonchas","amount":60,"unit":"g"},{"name":"Bacon","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Mostaza","amount":15,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en aros finos.","Cortar tomate en rodajas y separar hojas de lechuga. Reservar.","Dividir carne picada de ternera en 2 porciones iguales y formar 2 hamburguesas.","Presionar el centro de cada hamburguesa con el pulgar para que no se abombe al cocinarse.","Salpimentar las hamburguesas por ambas caras con sal y pimienta negra.","Calentar sartén con aceite de oliva a fuego medio.","Sofreír la cebolla en aros a fuego medio hasta que esté dorada y caramelizada.","Retirar la cebolla caramelizada y reservar. Subir el fuego a fuerte.","Dorar bacon en tiras en la misma sartén a fuego fuerte hasta que esté crujiente.","Retirar el bacon crujiente y reservar. Limpiar la sartén con papel de cocina.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar las hamburguesas 3 min por el primer lado sin moverlas.","Dar la vuelta a las hamburguesas y colocar queso cheddar curado en lonchas encima de cada una.","Cocinar 2 min más hasta que el queso se funda y la carne esté al punto.","Retirar las hamburguesas y tostar pan de hamburguesa brioche por el interior en la misma plancha hasta que estén dorados.","Untar la base de cada pan con ketchup y mostaza.","Colocar la lechuga y las rodajas de tomate sobre la base untada.","Colocar la hamburguesa con el queso fundido, el bacon crujiente y la cebolla caramelizada. Cerrar con la tapa del pan."}', 'Hamburguesa gourmet de ternera con cheddar curado, bacon crujiente y cebolla caramelizada.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina el bacon a 180°C durante 8-10 min hasta que esté crujiente. Luego, las hamburguesas a 190°C por 12-15 min, añadiendo el queso los últimos 2 min para que se funda, y tuesta el pan brevemente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina el bacon en una rejilla y las hamburguesas en una bandeja durante 15-20 min, añadiendo el queso sobre las hamburguesas los últimos 5 min para que se gratine y funda, y tuesta el pan."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_065', 'Pollo frito crujiente con miel picante', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 570, 36, 38, 30, 2, false, false, '{"gluten","huevo","lactosa","soja"}', '[{"name":"Contramuslos de pollo deshuesados","amount":400,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Maicena","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Leche","amount":50,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Copos de guindilla","amount":3,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar contramuslos de pollo deshuesados en trozos de unos 4 cm.","Mezclar harina de trigo, maicena, pimentón dulce, ajo en polvo y sal en un bol hasta integrar.","Batir huevo con leche en otro bol hasta obtener una mezcla homogénea.","Pasar cada trozo de pollo por la mezcla de harina, luego por el huevo batido y de nuevo por la harina.","Presionar bien el rebozado sobre cada trozo para que se adhiera y reservar.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el pollo rebozado por tandas a 180 °C durante 5 min, hasta que esté dorado y crujiente.","Escurrir el pollo frito sobre papel absorbente y reservar.","Calentar miel, salsa de soja, copos de guindilla y zumo de lima en un cazo a fuego suave.","Remover la salsa sin parar durante 2 min hasta que espese ligeramente y retirar del fuego.","Verter la salsa caliente sobre el pollo frito y remover para que quede bien cubierto.","Servir de inmediato para conservar el crujiente del rebozado."}', 'Trozos de pollo rebozados y fritos hasta quedar crujientes, bañados en una salsa de miel picante brillante.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Prepara el pollo empanado y rocíalo ligeramente con aceite. Cocina en la airfryer a 190-200°C durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa de miel picante se prepara aparte."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Empana el pollo y colócalo en una rejilla sobre una bandeja de horno. Hornea a 200-220°C durante 30-35 minutos, volteando una vez, hasta que esté bien dorado y crujiente. Prepara la salsa mientras el pollo se hornea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_066', 'Costillas BBQ con salsa casera ahumada', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 145, 'normal', 'all', 600, 42, 22, 38, 2, true, true, '{"mostaza","soja","sulfitos"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Pimentón ahumado","amount":5,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Azúcar moreno","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra molida","amount":2,"unit":"g"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza","amount":10,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"}]'::jsonb, '{"Retirar la membrana posterior de costillar de cerdo tirando de una esquina con ayuda de papel de cocina.","Mezclar pimentón ahumado, ajo en polvo, azúcar moreno, sal y pimienta negra molida en un bol hasta obtener un adobo seco homogéneo.","Frotar el costillar por ambos lados con el adobo seco.","Refrigerar el costillar adobado en la nevera durante 30 min.","Precalentar el horno a 150 °C.","Mezclar tomate frito, vinagre de manzana, miel, mostaza y salsa de soja en un cazo.","Cocer la salsa a fuego suave hasta que espese ligeramente, unos 8 min.","Retirar la salsa del fuego y reservar.","Envolver el costillar en papel de aluminio y colocarlo en una bandeja.","Hornear el costillar envuelto a 150 °C durante 120 min, hasta que la carne esté muy tierna.","Retirar el costillar del horno y subir la temperatura a 220 °C.","Quitar el papel de aluminio y pincelar el costillar generosamente con la salsa reservada.","Hornear a 220 °C durante 7 min, hasta que la salsa empiece a lacarse.","Pincelar de nuevo con más salsa y hornear 6 min más, hasta conseguir una laca oscura y pegajosa.","Retirar el costillar del horno y dejar reposar 5 min antes de cortar.","Cortar el costillar entre hueso y hueso y servir con el resto de la salsa aparte."}', 'Costillar de cerdo cocinado lento hasta quedar tierno y glaseado con una salsa BBQ casera ahumada.', '[{"appliance":"horno","time":145,"difficulty":"normal","prepSummary":"Sazonar las costillas y hornear cubiertas a 130-150°C por 2 horas para tiernizar. Luego, destapar, subir a 180-200°C, untar con la salsa casera y hornear 20-30 min más hasta caramelizar."},{"appliance":"airfryer","time":60,"difficulty":"normal","prepSummary":"Cortar las costillas en porciones, sazonar y cocinar en la airfryer a 160°C durante 40-50 minutos, volteando a mitad. Luego, untar con la salsa casera y cocinar a 180°C por 10-15 minutos más hasta dorar y caramelizar."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Cocinar las costillas sazonadas en la olla express con un poco de líquido durante 25-30 minutos a presión para tiernizarlas. Finalizar en el horno o airfryer a 200°C, untando con la salsa casera, por 15-20 minutos hasta dorar y caramelizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_067', 'Milanesa de ternera con patatas fritas', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 720, 42, 55, 36, 2, true, false, '{"gluten","huevo"}', '[{"name":"Filete de ternera para milanesa","amount":350,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Harina de trigo","amount":40,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Perejil picado","amount":5,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 0,5 cm.","Secar los bastones de patata con un paño limpio hasta eliminar la humedad.","Calentar aceite de oliva en una sartén grande a fuego fuerte.","Freír los bastones de patata a fuego medio hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Mezclar pan rallado, ajo en polvo y perejil picado en un plato llano.","Batir huevo en un plato hondo hasta homogeneizar.","Poner harina de trigo en un tercer plato llano.","Salar filete de ternera para milanesa por ambos lados.","Pasar cada filete por harina, sacudiendo el exceso.","Sumergir cada filete enharinado en el huevo batido hasta cubrirlo bien.","Rebozar cada filete en la mezcla de pan rallado, presionando para que adhiera.","Calentar el aceite restante en sartén a fuego fuerte hasta que esté bien caliente.","Freír las milanesas a fuego medio-fuerte 3 min por el primer lado hasta que estén doradas.","Dar la vuelta a las milanesas y freír 3 min más hasta que estén doradas por el otro lado.","Escurrir las milanesas sobre papel absorbente.","Salar sal las patatas fritas reservadas.","Servir las milanesas calientes junto a las patatas fritas."}', 'Filete de ternera empanado y frito, crujiente por fuera y jugoso por dentro, con patatas fritas.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Prepara las patatas con un poco de aceite y sal, cocínalas en la airfryer a 190°C durante 20-25 minutos, agitándolas a mitad. Luego, las milanesas, rociadas con aceite, a 190°C durante 15-18 minutos, volteándolas para un dorado uniforme y crujiente."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Dispón las patatas y las milanesas (ligeramente rociadas con aceite) en bandejas separadas. Hornea las patatas por 30-40 minutos y las milanesas por 20-25 minutos, volteando ambos a mitad de cocción para un resultado dorado y crujiente con menos gras"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_068', 'Filete a la pimienta verde flambeado', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 460, 34, 4, 34, 2, false, true, '{"lactosa","sulfitos"}', '[{"name":"Filete de solomillo de ternera","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Pimienta verde en grano","amount":20,"unit":"g"},{"name":"Brandy","amount":40,"unit":"ml"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":50,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Retirar filete de solomillo de ternera de la nevera y dejar atemperar 15 min antes de cocinar.","Escurrir pimienta verde en grano y machacar ligeramente la mitad con el dorso de un cuchillo.","Salpimentar los filetes con sal por ambas caras justo antes de cocinar.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego fuerte.","Marcar los filetes 2 min por cada lado hasta que estén dorados por fuera y rosados por dentro.","Retirar los filetes a un plato y reservar los jugos que hayan quedado en la sartén.","Retirar la sartén del fuego y añadir brandy.","Flambear con cuidado acercando una llama hasta que el brandy arda y dejar que la llama se apague sola.","Volver a poner la sartén a fuego medio y añadir la pimienta verde machacada y el resto de la pimienta.","Añadir caldo de carne y dejar reducir 1 min hasta que el líquido se evapore ligeramente.","Incorporar nata para cocinar y la mantequilla restante, removiendo para integrar.","Cocer a fuego medio 3 min, removiendo de vez en cuando, hasta que la salsa espese y nape la cuchara.","Devolver los filetes a la sartén con los jugos reservados y napar con la salsa.","Calentar 1 min a fuego suave hasta que los filetes estén calientes sin sobrecocer.","Servir los filetes en el plato con la salsa de pimienta verde por encima."}', 'Filete de ternera flambeado con brandy y napado en una cremosa salsa de pimienta verde.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_069', 'Carpaccio de ternera con parmesano y rúcula', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 285, 26, 2, 19, 2, false, false, '{"lactosa"}', '[{"name":"Solomillo de ternera","amount":250,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal en escamas","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Envolver solomillo de ternera en film transparente bien prieto y congelar hasta que esté firme pero no duro.","Laminar el solomillo semicongelado en láminas lo más finas posible con un cuchillo bien afilado.","Disponer las láminas de carne en un plato grande, superponiéndolas ligeramente hasta cubrir toda la superficie.","Lavar y escurrir rúcula.","Rallar queso parmesano en virutas con un pelador.","Mezclar aceite de oliva virgen extra con zumo de limón en un bol pequeño hasta integrar.","Repartir la rúcula sobre la carne.","Distribuir las virutas de queso parmesano por encima.","Aliñar con la mezcla de aceite de oliva virgen extra y zumo de limón.","Terminar con sal en escamas y pimienta negra recién molida al gusto, y servir enseguida."}', 'Láminas finas de solomillo de ternera crudo con virutas de parmesano, rúcula y aceite de oliva.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Sella el solomillo entero en la airfryer a 200°C durante 6-8 minutos, girándolo a mitad, para crear una fina costra exterior. Enfríalo rápidamente en el congelador (15-20 min) para facilitar el laminado muy fino y luego monta el carpaccio."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a máxima potencia con la función grill. Sella el solomillo 3-4 minutos por cada lado hasta dorar ligeramente la superficie. Refrigera en el congelador (15-20 min) para un corte más fácil, luego lamina muy fino y emplata el carpaccio."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('carnes_070', 'Tartar de solomillo al cuchillo', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 360, 28, 3, 26, 2, false, false, '{"huevo","mostaza","pescado","sulfitos"}', '[{"name":"Solomillo de ternera","amount":300,"unit":"g"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Pepinillos en vinagre","amount":20,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa Perrins","amount":10,"unit":"ml"},{"name":"Tabasco","amount":2,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar solomillo de ternera en dados muy pequeños a cuchillo, sin picadora, para conservar la textura.","Picar alcaparras finamente.","Picar pepinillos en vinagre finamente.","Picar cebolleta finamente.","Mezclar en un bol la carne picada con las alcaparras, los pepinillos y la cebolleta.","Añadir mostaza de dijon, salsa perrins y tabasco sobre la mezcla.","Añadir aceite de oliva virgen extra, sal y pimienta negra.","Remover bien hasta integrar todos los ingredientes de forma homogénea.","Rectificar el punto de sal, pimienta y tabasco al gusto.","Colocar un aro de emplatar sobre cada plato y rellenar con el tartar, compactando y alisando la superficie.","Retirar el aro con cuidado, hacer un hueco en el centro y disponer yema de huevo encima antes de servir."}', 'Solomillo de ternera picado a cuchillo y aliñado a mano, coronado con una yema de huevo cruda.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_071', 'Albóndigas en salsa de almendras y azafrán', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 50, 'normal', 'all', 410, 28, 20, 24, 2, true, true, '{"gluten","huevo","frutos_secos","sulfitos"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil picado","amount":3,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Almendra molida","amount":30,"unit":"g"},{"name":"Hebras de azafrán","amount":1,"unit":"g"},{"name":"Caldo de carne","amount":250,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar ajo fino y dividirlo en dos mitades iguales.","Picar cebolla en brunoise fina.","Mezclar carne picada de ternera, pan rallado, huevo, la mitad del ajo picado, perejil picado y sal en un bol.","Amasar la mezcla con las manos hasta que todos los ingredientes queden bien integrados.","Formar albóndigas del tamaño de una nuez con las manos húmedas.","Pasar cada albóndiga por harina de trigo, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego medio.","Dorar las albóndigas en tandas hasta que estén selladas por todos los lados.","Retirar las albóndigas de la cazuela y reservar en un plato.","Sofreír la cebolla picada y la mitad restante del ajo en el mismo aceite a fuego medio.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne, almendra molida y hebras de azafrán y remover bien para integrar.","Incorporar las albóndigas reservadas a la cazuela y tapar.","Cocer a fuego suave durante 20 min, hasta que la salsa espese y las albóndigas estén hechas por dentro.","Probar la salsa y rectificar de sal al gusto.","Servir las albóndigas bien calientes con la salsa de almendras y azafrán por encima."}', 'Albóndigas de ternera guisadas en una salsa dorada de almendra molida y azafrán.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Las albóndigas se hornean primero a 200°C durante 15-20 minutos para dorarlas. Luego, se prepara la salsa en una cazuela apta para horno, se incorporan las albóndigas y se cocina a fuego lento en el horno a 180°C hasta que la salsa espese y los sabores se integren."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"La Thermomix mezcla los ingredientes de las albóndigas y prepara la salsa sofriendo la cebolla y cociendo a la perfección con las almendras y el azafrán. Las albóndigas se pueden cocinar en el Varoma al vapor mientras se hace la salsa o añadir directamente al vaso para el cocinad"},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dora las albóndigas y sofríe la cebolla en la olla express. Luego, añade el resto de ingredientes de la salsa, incorpora las albóndigas y cocina a presión durante 10-15 minutos desde que sube la válvula para una cocción rápida y profunda de todos los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_072', 'Pollo asado entero con limón y hierbas', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 90, 'facil', 'all', 465, 45, 3, 30, 2, true, true, '{"lactosa"}', '[{"name":"Pollo entero","amount":900,"unit":"g"},{"name":"Limón","amount":2,"unit":"ud"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Secar pollo entero por dentro y por fuera con papel de cocina.","Picar ajo fino.","Cortar 1 ud de limón en cuartos.","Mezclar el ajo picado con aceite de oliva, mantequilla, sal y pimienta negra hasta obtener una pasta homogénea.","Untar el pollo seco por fuera con la pasta de ajo y mantequilla.","Introducir los dedos bajo la piel de la pechuga con cuidado y untar también por debajo con la pasta restante.","Meter los cuartos de limón, romero fresco y tomillo fresco dentro de la cavidad del pollo.","Colocar el pollo en una fuente de horno con la pechuga hacia arriba.","Exprimir el segundo limón por encima del pollo.","Hornear 80 min a 200 °C, regando el pollo con sus propios jugos cada 20 min, hasta que la piel esté dorada y el jugo salga claro al pinchar el muslo.","Retirar el pollo del horno y dejar reposar 10 min sobre la fuente antes de trinchar.","Trinchar el pollo y servir con los jugos de la fuente por encima."}', 'Pollo entero asado al horno con limón, ajo y hierbas aromáticas hasta quedar dorado y jugoso.', '[{"appliance":"horno","time":90,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Unta el pollo con la mezcla de mantequilla, hierbas, sal y pimienta, rellena con limón y ajo, y asa durante 90 minutos, regando ocasionalmente para una piel dorada y crujiente."},{"appliance":"airfryer","time":55,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Unta el pollo y cocina durante 45-55 minutos, volteándolo a mitad de cocción y subiendo a 200°C los últimos 10 minutos para una piel extra crujiente y jugosidad interior."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_073', 'Muslos de pollo al horno con miel y mostaza', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 50, 'facil', 'all', 425, 34, 18, 24, 2, true, true, '{"mostaza"}', '[{"name":"Muslos de pollo","amount":500,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo muy fino.","Mezclar miel, mostaza de dijon, el ajo picado, aceite de oliva, pimentón dulce, sal y pimienta negra en un bol hasta obtener una salsa homogénea.","Colocar muslos de pollo en una bandeja de horno con la piel hacia arriba.","Untar los muslos de pollo con la salsa de miel y mostaza por todos los lados, cubriendo bien la piel.","Hornear a 200 °C durante 35 min.","Subir la temperatura del horno a 220 °C.","Pincelar los muslos con el jugo acumulado en la bandeja.","Hornear a 220 °C durante 10 min, hasta que la piel esté dorada, brillante y pegajosa.","Reposar los muslos en la bandeja durante 5 min antes de servir.","Servir los muslos de pollo con el jugo de la bandeja por encima."}', 'Muslos de pollo al horno glaseados con una mezcla de miel y mostaza hasta quedar pegajosos y dorados.', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Precalienta el horno a 190-200°C. Hornea los muslos marinados durante 45-50 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una salsa caramelizada."},{"appliance":"airfryer","time":28,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Cocina los muslos marinados durante 25-30 minutos, volteándolos a mitad de cocción y pincelando con más salsa para asegurar un exterior crujiente y jugoso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_074', 'Secreto ibérico con patatas fritas y mojo picón', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 700, 38, 42, 42, 2, false, false, '{"sulfitos"}', '[{"name":"Secreto ibérico","amount":400,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Vinagre de vino","amount":15,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes.","Secar los bastones de patata con papel de cocina hasta que no quede humedad.","Calentar aceite de oliva en una sartén honda a fuego medio hasta que esté caliente.","Freír los bastones de patata hasta que estén dorados y tiernos, unos 10 min.","Cortar pimiento rojo en trozos grandes y pelar ajo.","Triturar el pimiento rojo y el ajo con pimentón picante, comino molido, vinagre de vino y sal hasta obtener una pasta.","Añadir aceite de oliva virgen extra en hilo fino mientras se tritura hasta obtener una salsa fina y homogénea.","Escurrir las patatas fritas sobre papel de cocina y salar al gusto.","Salar secreto ibérico y dejar atemperar fuera de la nevera.","Calentar plancha a fuego fuerte hasta que humee ligeramente.","Marcar el secreto ibérico por un lado hasta que esté dorado, unos 3 min.","Dar la vuelta al secreto ibérico y marcar por el otro lado hasta que esté dorado y jugoso por dentro, unos 3 min.","Retirar el secreto ibérico de la plancha y dejar reposar.","Cortar el secreto ibérico en lonchas en sentido transversal a la fibra.","Servir las lonchas de secreto ibérico con las patatas fritas y el mojo picón aparte."}', 'Secreto ibérico a la plancha servido con patatas fritas y un mojo picón intenso.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina el secreto y las patatas en la airfryer a 190°C. Las patatas tardarán unos 20-25 min y el secreto 15-20 min, dándoles la vuelta a mitad para un dorado uniforme. El mojo se prepara aparte en batidora."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea las patatas en una bandeja con un poco de aceite durante 30-40 min. Añade el secreto a la misma bandeja o en otra para los últimos 20-25 min, hasta que esté dorado y jugoso. El mojo se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_075', 'Solomillo a la pimienta con patatas paja', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 720, 38, 38, 46, 2, false, false, '{"lactosa","sulfitos"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Pimienta negra en grano","amount":15,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":40,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarlas en juliana muy fina con mandolina.","Secar bien las patatas con un paño limpio para eliminar el exceso de humedad.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salpimentar con sal.","Machacar pimienta negra en grano ligeramente con el dorso de un cuchillo.","Salar solomillo de ternera y presionar la pimienta machacada por ambas caras.","Calentar mantequilla en sartén a fuego fuerte hasta que empiece a espumar.","Dorar los solomillos 2 min por cada cara hasta alcanzar el punto deseado.","Retirar los solomillos de la sartén y reservar en un plato.","Retirar la sartén del fuego y añadir brandy con cuidado; flamear inclinando la sartén.","Añadir caldo de carne cuando se apague la llama y remover a fuego medio.","Incorporar nata para cocinar y cocer a fuego medio hasta que la salsa espese.","Devolver los solomillos a la sartén y calentar 1 min hasta que estén bien integrados.","Servir los solomillos napados con la salsa de pimienta y acompañados de las patatas paja."}', 'Solomillo de ternera a la pimienta con una salsa cremosa de brandy y nata, acompañado de patatas paja crujientes.', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Prepara el solomillo sazonado y cocínalo en la airfryer a 190°C unos 12-15 minutos, volteando a mitad, para un punto jugoso. Las patatas paja se cortan muy finas, se rocían con poco aceite y se hacen en la airfryer a 180°C en tandas, removiendo frecuentemente, hasta que estén cru"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_076', 'Redondo de ternera mechado', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 100, 'normal', 'all', 390, 44, 8, 20, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Redondo de ternera","amount":450,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":50,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar fino cebolla y ajo.","Pelar y cortar zanahoria en rodajas finas.","Abrir redondo de ternera en forma de libro con un cuchillo, dejándolo plano.","Salpimentar la carne por dentro con sal y pimienta negra.","Cubrir la superficie interior con jamón cocido en lonchas extendiéndolas bien.","Colocar huevo cocido entero en el centro a lo largo.","Enrollar la carne sobre sí misma envolviendo el relleno y atar con hilo de cocina.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar el redondo por todos los lados hasta que esté sellado y con color uniforme.","Retirar el redondo y reservar. Bajar el fuego a medio.","Sofreír la cebolla, el ajo y la zanahoria en la misma cazuela hasta que estén tiernos.","Añadir vino blanco y remover hasta que evapore el alcohol.","Incorporar caldo de carne y volver a colocar el redondo en la cazuela.","Tapar y cocer a fuego suave hasta que la carne esté tierna, dando la vuelta a mitad.","Retirar el redondo de la cazuela y dejar reposar sobre una tabla.","Triturar la salsa de la cazuela hasta que quede fina y homogénea.","Retirar el hilo de cocina y cortar el redondo en lonchas de grosor uniforme.","Servir las lonchas en el plato napadas con la salsa triturada."}', 'Redondo de ternera relleno de jamón y huevo cocido, guisado y cortado en lonchas finas.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sella el redondo en una sartén y luego pásalo a una cazuela de horno con las verduras, el vino y el caldo. Cocina a 160-180°C durante 90-120 minutos hasta que esté muy tierno, logrando una carne jugosa y una salsa rica."},{"appliance":"olla_express","time":75,"difficulty":"normal","prepSummary":"Sella el redondo directamente en la olla express. Añade las verduras, el vino y el caldo, y cocina a alta presión durante 30-40 minutos. Obtendrás una carne extremadamente tierna y una salsa concentrada en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_077', 'Carne mechada con puré y salsa de su jugo', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 110, 'normal', 'all', 500, 38, 32, 24, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Carne para mechar (morcillo de ternera)","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino tinto","amount":75,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Leche","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en brunoise fina.","Pelar y picar zanahoria en trozos pequeños.","Pelar y picar ajo fino.","Salpimentar carne para mechar (morcillo de ternera) por todos los lados con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar la carne por todos los lados hasta que esté sellada y con color uniforme. Retirar y reservar.","Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela durante 8 min, hasta que estén tiernos.","Añadir tomate triturado y sofreír 3 min, removiendo hasta que pierda el agua.","Verter vino tinto y llevar a ebullición hasta que el alcohol evapore, unos 3 min.","Devolver la carne a la cazuela y añadir caldo de carne. Tapar y cocer a fuego suave 90 min, hasta que la carne esté muy tierna.","Pelar y cortar patata en trozos regulares.","Hervir agua con sal en un cazo y cocer las patatas troceadas 20 min, hasta que estén tiernas.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","Escurrir las patatas cocidas y triturarlas en el mismo cazo.","Añadir la leche caliente y mantequilla al puré y mezclar hasta obtener una textura fina y homogénea.","Retirar la carne de la cazuela y desmecharla con 2 tenedores en tiras finas.","Triturar la salsa de la cazuela con un batidor de mano hasta obtener una salsa lisa.","Devolver la carne desmechada a la cazuela con la salsa triturada y remover hasta integrar bien.","Servir una base de puré de patata en el plato y disponer la carne mechada con su salsa por encima."}', 'Carne de ternera mechada hasta deshacerse, servida sobre puré de patata con su propia salsa reducida.', '[{"appliance":"horno","time":150,"difficulty":"normal","prepSummary":"Sellaremos la carne y sofreiremos las verduras en una olla apta para horno en la encimera. Luego, añadiremos los líquidos y cocinaremos tapado en el horno a 160°C durante unas 2.5 horas hasta que la carne esté muy tierna. El puré se hará aparte."},{"appliance":"thermomix","time":160,"difficulty":"normal","prepSummary":"Dorar la carne en una sartén aparte. En la Thermomix, sofreír las verduras, añadir la carne y los líquidos, y cocinar a baja velocidad y temperatura (aprox. 100°C, giro inverso) durante 90-120 minutos hasta que la carne esté tierna. La salsa se triturará y el puré se preparará en"},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Dorar la carne y sofreír las verduras en la olla a presión abierta. Añadir los líquidos, cerrar y cocinar a presión durante 40-50 minutos. Tras liberar la presión, la carne estará muy tierna y la salsa lista, pudiendo reducirse si se desea. El puré se hará aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_078', 'Estofado de carrilleras con boniato', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 120, 'normal', 'invierno', 440, 34, 30, 20, 2, true, true, '{"sulfitos"}', '[{"name":"Carrilleras de cerdo","amount":400,"unit":"g"},{"name":"Boniato","amount":250,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en brunoise fina.","Pelar y picar zanahoria en brunoise fina.","Picar ajo fino.","Pelar boniato y cortarlo en dados grandes.","Salpimentar carrilleras de cerdo por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar las carrilleras de cerdo en la cazuela hasta que estén selladas por todos los lados.","Retirar las carrilleras de cerdo de la cazuela y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla picada, la zanahoria picada y el ajo picado en la misma cazuela hasta que estén tiernos.","Añadir tomate triturado y sofreír hasta que pierda el agua y se concentre.","Verter vino tinto y subir el fuego hasta que se evapore el alcohol y el líquido reduzca a la mitad.","Devolver las carrilleras de cerdo reservadas a la cazuela.","Añadir caldo de carne y laurel.","Tapar la cazuela y cocer a fuego suave durante 60 min.","Añadir el boniato en dados a la cazuela y remover con suavidad para integrarlo.","Tapar de nuevo y cocer a fuego suave hasta que el boniato esté tierno y las carrilleras se deshagan.","Retirar el laurel de la cazuela.","Probar el estofado y rectificar de sal si fuera necesario.","Servir el estofado bien caliente en platos hondos con el boniato integrado en la salsa."}', 'Carrilleras de cerdo guisadas a fuego lento con boniato hasta quedar melosas.', '[{"appliance":"horno","time":180,"difficulty":"normal","prepSummary":"Sella las carrilleras en una olla apta para horno, sofríe las verduras, añade el resto de ingredientes y cocina tapado en el horno precalentado a 160°C durante 2.5-3 horas hasta que la carne se deshaga."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Dora la carne en la Thermomix, sofríe las verduras, incorpora el resto de ingredientes y programa 90-100 minutos a 100°C o Varoma, giro inverso y velocidad cuchara, hasta obtener una carne muy tierna."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Sella las carrilleras y sofríe las verduras en la olla a presión. Añade los líquidos y el resto de ingredientes, cierra la olla y cocina durante 45-50 minutos desde que sube la válvula para una carne increíblemente tierna."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_079', 'Pollo al limón estilo asiático', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 560, 34, 48, 26, 2, true, false, '{"huevo","soja","sesamo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Zumo de limón","amount":60,"unit":"ml"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Caldo de pollo","amount":80,"unit":"ml"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en trozos de bocado de unos 3 cm.","Batir huevo en un bol y añadir los trozos de pollo.","Dejar marinar el pollo en el huevo batido durante 5 min.","Rallar jengibre fresco y ajo finamente. Reservar.","Escurrir el exceso de huevo de los trozos de pollo.","Rebozar los trozos de pollo en maicena hasta cubrirlos bien. Sacudir el exceso.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el pollo rebozado por tandas en el aceite caliente durante 4 min, hasta que esté dorado y crujiente.","Escurrir el pollo frito sobre papel absorbente. Reservar.","Mezclar en un cazo zumo de limón, azúcar, salsa de soja y caldo de pollo.","Añadir el jengibre y el ajo rallados al cazo con la mezcla de limón.","Calentar la salsa a fuego medio, removiendo, hasta que espese ligeramente, unos 4 min.","Verter la salsa caliente sobre el pollo frito y remover para que quede bien impregnado.","Espolvorear sésamo tostado por encima y servir enseguida."}', 'Trozos de pollo rebozados y fritos, bañados en una salsa agridulce de limón al estilo asiático.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Empaniza el pollo y rocíalo con un poco de aceite. Cocínalo en la airfryer a 190°C durante 15-20 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa se prepara en un cazo aparte y se mezcla con el pollo al final para mantener la textura."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Hornea el pollo empanizado a 200°C durante 20-25 minutos, volteándolo a mitad de cocción, para que quede dorado. Un truco es usar una rejilla sobre una bandeja para que el aire circule y el pollo quede más crujiente. La salsa se elabora en un cazo aparte y se añade al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_080', 'Alitas de pollo glaseadas al ajo y miel', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 45, 'facil', 'all', 470, 32, 22, 28, 2, true, true, '{"soja"}', '[{"name":"Alitas de pollo","amount":600,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo muy fino.","Mezclar en un bol miel, el ajo picado, salsa de soja, aceite de oliva, pimentón dulce, sal y pimienta negra.","Añadir alitas de pollo al bol y remover hasta que queden impregnadas por todos lados.","Dejar marinar las alitas 15 min a temperatura ambiente.","Colocar las alitas en una bandeja de horno con papel vegetal, separadas entre sí.","Hornear 25 min, dando la vuelta a las alitas en el minuto 12.","Pincelar las alitas con el jugo recogido en la bandeja.","Subir la temperatura del horno a 220 °C.","Hornear 8 min más, hasta que las alitas estén doradas, brillantes y pegajosas.","Reposar las alitas 3 min fuera del horno antes de servir.","Servir las alitas directamente en la bandeja o en un plato, con el glaseado restante por encima."}', 'Alitas de pollo al horno glaseadas con ajo y miel hasta quedar pegajosas y doradas.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Marinar las alitas y hornear a 190-200°C durante 40-45 minutos. Voltéalas a mitad de cocción y pincela con la salsa en los últimos 15 minutos para un glaseado uniforme y dorado."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Marinar las alitas. Cocinar en la airfryer a 190°C durante 25-30 minutos, volteando cada 8-10 minutos. Pincela con la salsa en las últimas pasadas para un glaseado crujiente y delicioso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_081', 'Ternera a la jardinera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 80, 'normal', 'all', 405, 34, 26, 18, 2, true, true, '{"sulfitos"}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Judía verde","amount":80,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":50,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar carne de ternera para guisar en trozos de bocado.","Picar cebolla y ajo fino.","Cortar zanahoria, patata y judía verde en dados o trozos similares.","Salpimentar la carne de ternera con sal y pimienta negra.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee.","Dorar la carne en la cazuela por todos los lados hasta que esté sellada y dorada.","Retirar la carne y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla y el ajo picados en la misma cazuela hasta que estén blandos.","Añadir tomate triturado y sofreír hasta que pierda el agua y se concentre.","Verter vino blanco y remover hasta que se evapore el alcohol.","Devolver la carne a la cazuela y añadir caldo de carne. Tapar y cocer a fuego suave.","Añadir la zanahoria y la patata cortadas a la cazuela y cocer tapado a fuego suave.","Incorporar la judía verde y guisantes y cocer hasta que las verduras estén tiernas.","Probar y rectificar de sal al gusto.","Servir bien caliente en plato hondo o fuente."}', 'Guiso de ternera con zanahoria, judía verde, guisantes y patata en una salsa ligera de tomate.', '[{"appliance":"horno","time":85,"difficulty":"normal","prepSummary":"Se doran la carne y las verduras en una olla apta para horno, se añade el resto de ingredientes y se cocina tapado en el horno a 170-180°C durante 60-70 minutos, logrando una cocción uniforme y una carne muy tierna."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras, dora la carne (en dos tandas si es necesario) y luego guisa todos los ingredientes a 95-100°C, velocidad cuchara y giro inverso, durante 60-70 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Dora la carne y sofríe las verduras en la olla, añade el resto de ingredientes y cocina a presión durante 25-30 minutos desde que sube la válvula, logrando una carne muy tierna y un guiso con todo el sabor en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_082', 'Pincho moruno con patatas fritas y alioli', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 685, 34, 42, 42, 2, true, false, '{"huevo"}', '[{"name":"Carne de cerdo en dados (aguja o secreto)","amount":400,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Cúrcuma","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva (para freír)","amount":400,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sal","amount":6,"unit":"g"}]'::jsonb, '{"Mezclar pimentón dulce, comino molido, ajo en polvo y cúrcuma en un bol hasta integrar.","Añadir aceite de oliva, zumo de limón y sal al bol y mezclar hasta obtener una pasta homogénea.","Incorporar carne de cerdo en dados (aguja o secreto) al bol y remover hasta que todos los dados queden bien cubiertos.","Tapar el bol y refrigerar hasta que la carne haya marinado al menos 30 min.","Pelar patata y cortar en bastones uniformes de unos 1 cm de grosor.","Secar los bastones de patata con papel de cocina para eliminar el exceso de humedad.","Machacar o picar fino ajo hasta obtener una pasta muy fina.","Colocar huevo y el ajo picado en el vaso de la batidora. Añadir una pizca de sal.","Triturar con la batidora a velocidad baja, añadiendo aceite de oliva en hilo muy fino y constante.","Continuar añadiendo el aceite de oliva (para freír) en hilo hasta que el alioli emulsione y espese. Reservar en frío.","Calentar el aceite de oliva (para freír) restante en una sartén profunda a fuego fuerte hasta que alcance 180 °C.","Freír los bastones de patata en tandas durante 8 min, hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel de cocina y salar ligeramente. Reservar.","Ensartar la carne marinada en brochetas, distribuyendo los dados de forma uniforme.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Dorar los pinchos 3 min por cada lado, hasta que estén tostados por fuera y jugosos por dentro.","Servir los pinchos junto a las patatas fritas y el alioli aparte."}', 'Brochetas de cerdo marinadas con especias moriscas, servidas con patatas fritas y alioli casero.', '[{"appliance":"airfryer","time":50,"difficulty":"facil","prepSummary":"Los pinchos se cocinan a 190°C durante 18-20 minutos, volteándolos a mitad para un dorado uniforme. Las patatas se hacen a 180°C durante 20-25 minutos, rociadas con un poco de aceite y removiendo varias veces."},{"appliance":"horno","time":65,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina los pinchos con función grill durante 20-25 minutos, dándoles la vuelta. Las patatas, cortadas en bastones y con poco aceite, se asan a 200°C durante 30-40 minutos hasta que estén tiernas y doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_083', 'Chuletillas de cordero a la brasa con romero', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 420, 32, 1, 32, 2, true, true, '{}', '[{"name":"Chuletillas de cordero","amount":500,"unit":"g"},{"name":"Romero fresco","amount":5,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Sacar chuletillas de cordero de la nevera y dejar atemperar a temperatura ambiente.","Picar romero fresco fino y reservar.","Machacar ajo hasta obtener una pasta.","Mezclar el ajo machacado con aceite de oliva y el romero picado en un bol.","Untar las chuletillas con la mezcla de ajo y romero por ambos lados.","Añadir sal y pimienta negra por ambos lados de las chuletillas.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar las chuletillas sobre la plancha y cocinar hasta que se doren, unos 2-3 min por cada lado.","Retirar las chuletillas de la plancha y dejar reposar para que los jugos se asienten.","Servir las chuletillas bien calientes con un poco de romero fresco por encima."}', 'Chuletillas de cordero a la brasa aromatizadas con ajo y romero fresco.', '[{"appliance":"airfryer","time":16,"difficulty":"facil","prepSummary":"Prepara las chuletillas con el romero, ajo, aceite, sal y pimienta. Precalienta la airfryer a 200°C y cocina las chuletillas durante 16 minutos, dándoles la vuelta a mitad para un dorado uniforme y jugoso."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Marina las chuletillas con los ingredientes. Precalienta el horno a 220°C (con función grill si es posible) y hornea durante 22 minutos, dándoles la vuelta a mitad para un buen sellado y que queden tiernas por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_084', 'Cordero asado con patatas panadera', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 100, 'normal', 'all', 560, 42, 26, 32, 2, true, true, '{}', '[{"name":"Paletilla de cordero","amount":700,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Manteca de cerdo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":6,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Pelar patata y cortarlas en rodajas finas de unos 3 mm.","Pelar cebolla y cortarla en juliana fina.","Pelar ajo y machacarlo hasta formar una pasta.","Extender las patatas y la cebolla en una fuente de horno formando una cama uniforme.","Salpimentar las patatas y la cebolla con sal y pimienta negra.","Regar las patatas y la cebolla con aceite de oliva.","Untar paletilla de cordero con manteca de cerdo y el ajo machacado por toda la superficie.","Salpimentar la paletilla por ambas caras.","Colocar la paletilla sobre la cama de patatas y cebolla y añadir laurel.","Verter vino blanco y 50 ml de agua en el fondo de la fuente.","Hornear la fuente en el centro del horno a 180 °C durante 85 min, regando con los jugos cada 25 min.","Comprobar que la piel está dorada y crujiente y la carne muy tierna antes de retirar del horno.","Retirar la fuente del horno y dejar reposar la paletilla 10 min sin tapar.","Trinchar la paletilla y servir con las patatas panadera bien empapadas en el jugo de la fuente."}', 'Pierna de cordero asada al horno sobre una cama de patatas panadera empapadas en su jugo.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Sazona la paletilla y colócala sobre una cama de patatas y cebolla laminadas con ajo y laurel. Riega con vino blanco y aceite, y asa durante 100 minutos, dando la vuelta a la carne a mitad de cocción para un dorado uniforme."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_085', 'Cinta de lomo rellena de ciruelas y piñones', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 75, 'normal', 'all', 445, 38, 14, 26, 2, true, true, '{"frutos_secos","sulfitos"}', '[{"name":"Cinta de lomo de cerdo abierta en libro","amount":500,"unit":"g"},{"name":"Ciruelas pasas sin hueso","amount":50,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Bacon en lonchas","amount":50,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":75,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Extender cinta de lomo de cerdo abierta en libro sobre la mesa y salpimentar por dentro con sal y pimienta negra.","Repartir ciruelas pasas sin hueso y piñones de forma uniforme sobre la carne.","Enrollar la carne sobre sí misma apretando bien para que el relleno quede compacto en el interior.","Cubrir el rollo con bacon en lonchas, solapando cada loncha con la anterior.","Atar el rollo con hilo de cocina dando vueltas cada 2 cm para que mantenga la forma durante el horneado.","Calentar aceite de oliva en una sartén a fuego fuerte hasta que humee ligeramente.","Dorar el rollo en la sartén por todos los lados hasta que el bacon esté dorado y crujiente.","Colocar el rollo en una fuente de horno y añadir vino blanco y caldo de carne en la base.","Hornear a 180 °C durante 40 min, regando el rollo con los jugos de la fuente cada 15 min.","Retirar la fuente del horno y dejar reposar el rollo 10 min sin cortar para que los jugos se redistribuyan.","Retirar el hilo de cocina con unas tijeras con cuidado de no romper el rollo.","Cortar el rollo en rodajas de unos 2 cm con un cuchillo bien afilado.","Servir las rodajas regadas con la salsa de la fuente."}', 'Cinta de lomo enrollada y rellena de ciruelas pasas y piñones, asada al horno.', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Rellena y ata el lomo, séllalo en una sartén y luego ásalo en el horno a 180°C, regándolo con el vino y el caldo para una carne jugosa y una salsa deliciosa."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Sella el lomo relleno y luego cocínalo en la airfryer a 170°C durante unos 50-60 minutos, girándolo a mitad y añadiendo un poco de líquido para evitar que se seque."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora el lomo relleno en la olla a presión, luego añade el vino y el caldo y cocina a fuego medio durante 30-35 minutos desde que sube la válvula para una carne muy tierna y una salsa concentrada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_086', 'Pollo relleno de jamón y queso', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 620, 46, 32, 34, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Pechuga de pollo","amount":400,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":80,"unit":"g"},{"name":"Queso para fundir en lonchas","amount":80,"unit":"g"},{"name":"Harina de trigo","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Abrir pechuga de pollo en forma de libro con un cuchillo, sin llegar a cortar del todo.","Salpimentar el interior de cada pechuga con sal y pimienta negra.","Colocar jamón cocido en lonchas sobre el interior de cada pechuga.","Colocar queso para fundir en lonchas sobre el jamón.","Cerrar cada pechuga sobre el relleno y sujetar con un palillo si es necesario.","Batir huevo en un bol hasta que esté homogéneo.","Disponer harina de trigo y pan rallado en platos separados.","Pasar cada pechuga rellena por la harina de trigo, cubriéndola bien por todos los lados.","Pasar a continuación cada pechuga por el huevo batido, asegurando que quede bien empapada.","Rebozar cada pechuga con el pan rallado, presionando ligeramente para que se adhiera.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Freír las pechugas rellenas 5 min por el primer lado, hasta que estén doradas.","Dar la vuelta a las pechugas y freír 5 min por el otro lado, hasta que estén doradas y el queso fundido.","Escurrir las pechugas sobre papel absorbente y retirar los palillos.","Cortar cada pechuga por la mitad y servir para mostrar el relleno fundido."}', 'Pechuga de pollo rellena de jamón y queso, empanada y frita hasta que el queso funde por dentro.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Prepara el pollo relleno y empanado. Cocina en la airfryer a 190°C durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Empana el pollo relleno y hornéalo a 200°C durante 30-35 minutos, girando a mitad, hasta que esté bien dorado y el queso fundido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_087', 'Filetes empanados con patatas fritas', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 660, 36, 52, 34, 2, true, false, '{"gluten","huevo"}', '[{"name":"Filetes de lomo de cerdo","amount":350,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Harina de trigo","amount":30,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":400,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Secar bien los bastones de patata con papel absorbente para que queden crujientes al freír.","Salpimentar filetes de lomo de cerdo por ambos lados con sal y pimienta negra.","Batir huevo en un bol hondo hasta que la yema y la clara estén bien integradas.","Extender harina de trigo en un plato llano y pan rallado en otro plato llano.","Pasar cada filete por la harina, sacudir el exceso, sumergir en el huevo batido y cubrir con el pan rallado.","Presionar bien el pan rallado sobre cada filete para que quede una capa uniforme y compacta.","Calentar aceite de oliva en sartén grande a fuego fuerte hasta que alcance unos 180 °C.","Freír los filetes empanados 2 min por cada lado, hasta que estén bien dorados.","Retirar los filetes y escurrir sobre papel absorbente. Reservar en un lugar cálido.","Freír los bastones de patata en el mismo aceite a fuego fuerte, hasta que estén dorados y crujientes.","Retirar las patatas fritas y escurrir sobre papel absorbente. Salar al gusto.","Servir los filetes empanados calientes junto con las patatas fritas en el mismo plato."}', 'Filetes de lomo empanados y fritos, servidos con patatas fritas caseras.', '[{"appliance":"airfryer","time":45,"difficulty":"facil","prepSummary":"Prepara los filetes empanados y las patatas cortadas en bastones. Cocina las patatas en la airfryer a 190°C durante 20-25 minutos, agitándolas, y luego los filetes a 190°C por 12-15 minutos, dándoles la vuelta a mitad, para un resultado crujiente y menos graso."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara los filetes empanados y las patatas cortadas en bastones. Hornea ambos en una bandeja con un poco de aceite a 200°C durante 25-30 minutos, volteando a mitad, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_088', 'Carne guisada con champiñones y vino blanco', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 70, 'facil', 'all', 440, 32, 14, 28, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Carne de ternera para guisar","amount":400,"unit":"g"},{"name":"Champiñones","amount":250,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Harina de trigo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar carne de ternera para guisar en trozos de bocado uniformes.","Salpimentar la carne con sal y pimienta negra por todos los lados.","Enharinar la carne con harina de trigo, sacudiendo el exceso.","Picar cebolla en brunoise fina.","Picar ajo fino.","Laminar champiñones en láminas de unos 4 mm.","Calentar aceite de oliva en una cazuela a fuego fuerte hasta que humee ligeramente.","Dorar la carne por todos los lados hasta que esté sellada y tome color dorado.","Retirar la carne de la cazuela y reservar en un plato.","Sofreír la cebolla picada y el ajo picado en la misma cazuela a fuego medio hasta que estén blandos.","Añadir los champiñones laminados y saltear a fuego medio hasta que suelten su agua y se doren.","Verter vino blanco y remover hasta que el alcohol se evapore y el líquido reduzca a la mitad.","Devolver la carne reservada a la cazuela.","Añadir caldo de carne, tapar y cocer a fuego suave hasta que la carne esté muy tierna.","Añadir nata para cocinar y remover hasta que la salsa espese ligeramente.","Probar y rectificar de sal antes de retirar del fuego.","Servir bien caliente en plato hondo o cazuela individual."}', 'Carne de ternera guisada con champiñones en una salsa cremosa de vino blanco.', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Se doran la carne y las verduras en una olla apta para horno, se añaden el resto de ingredientes y se cocina tapado en el horno precalentado a 160°C durante unos 75-80 minutos, hasta que la carne esté muy tierna. Permite una cocción uniforme y un guiso con sabores bien integrados"},{"appliance":"thermomix","time":70,"difficulty":"facil","prepSummary":"Se sofríen las verduras y se dora ligeramente la carne en el vaso. Luego se añaden los líquidos y el resto de ingredientes y se cocina a 100°C, giro inverso, velocidad cuchara, durante unos 55-60 minutos, logrando una carne tierna y una salsa perfectamente ligada."},{"appliance":"olla_express","time":50,"difficulty":"facil","prepSummary":"Se doran la carne y las verduras en la olla. Se incorporan el resto de ingredientes, se cierra la olla y se cocina a presión durante unos 30-35 minutos desde que sube la válvula. La carne quedará extremadamente tierna en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_089', 'Solomillo con salsa de queso de cabra y miel', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 515, 36, 16, 34, 2, false, true, '{"lactosa"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Queso de cabra en rulo","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Sacar solomillo de ternera de la nevera para que atempere.","Salpimentar el solomillo por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee.","Marcar el solomillo 2 min por cada cara hasta que esté dorado por fuera y rosado por dentro.","Retirar el solomillo de la sartén y reservar en un plato.","Bajar el fuego a medio y añadir nata para cocinar a la misma sartén, removiendo para recoger los jugos.","Cortar queso de cabra en rulo en trozos pequeños.","Añadir el queso de cabra troceado a la sartén y remover hasta que se funda por completo.","Incorporar miel y remover hasta integrar.","Cocer la salsa a fuego medio hasta que esté cremosa y homogénea.","Devolver el solomillo a la sartén y napar con la salsa.","Calentar 1 min a fuego suave hasta que el solomillo esté bien caliente.","Servir el solomillo con la salsa de queso de cabra y miel por encima."}', 'Solomillo de ternera con una salsa cremosa de queso de cabra y miel.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 200°C y cocina el solomillo unos 15-18 minutos, volteándolo a mitad para un dorado perfecto. La salsa se prepara aparte en un cazo, calentando suavemente el queso de cabra, nata y miel hasta obtener una crema homogénea."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén apta para horno a fuego fuerte y termina de cocinarlo en el horno precalentado a 190°C durante 10-15 minutos. Mientras, prepara la salsa en un cazo a fuego suave con el queso de cabra, nata y miel hasta que espese ligeramente."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_090', 'Escalopines al cava', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 430, 32, 12, 28, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Escalopines de ternera","amount":350,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Cava","amount":150,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Laminar champiñones en láminas de unos 3 mm.","Salpimentar escalopines de ternera por ambas caras con sal y pimienta negra.","Enharinar los escalopines con harina de trigo, sacudiendo el exceso.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego fuerte.","Dorar los escalopines 1 min por cada cara hasta que estén dorados. Reservar en un plato.","Añadir el resto de la mantequilla a la misma sartén a fuego medio.","Saltear los champiñones laminados hasta que estén dorados y hayan soltado su agua.","Verter cava y llevar a ebullición a fuego fuerte hasta que reduzca a la mitad.","Añadir nata para cocinar y cocer a fuego medio hasta que la salsa espese ligeramente.","Incorporar los escalopines reservados a la sartén y calentar a fuego suave, napando con la salsa.","Servir enseguida, bien caliente."}', 'Escalopines de ternera con champiñones en una salsa ligera de cava.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Dora los escalopines en la Thermomix (modo alta temperatura), retira y reserva. Luego, sofríe los champiñones, añade el cava y la nata, e incorpora la carne para que la salsa espese y se integren los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_091', 'Costillas confitadas con miel y mostaza', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 150, 'normal', 'all', 625, 40, 12, 46, 2, true, true, '{"mostaza"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Tomillo","amount":2,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar costillar de cerdo con sal y pimienta negra por ambos lados.","Colocar el costillar en una cazuela ancha o fuente honda de forma que quede en una sola capa.","Machacar ajo con el lateral del cuchillo hasta aplastarlo.","Verter aceite de oliva suave sobre el costillar hasta cubrirlo casi por completo.","Añadir el ajo machacado, laurel y tomillo al aceite.","Cocinar a fuego muy suave durante 120 min, hasta que la carne esté muy tierna pero entera.","Mezclar miel y mostaza de dijon en un bol pequeño hasta obtener un glaseado homogéneo.","Precalentar el horno a 220 °C con función grill.","Retirar el costillar del aceite y escurrir el exceso sobre un papel absorbente.","Pincelar el costillar por ambos lados con el glaseado de miel y mostaza.","Hornear en la bandeja superior del horno durante 10 min bajo el grill, hasta que esté dorado y brillante.","Retirar del horno y dejar reposar 3 min antes de cortar.","Cortar el costillar entre hueso y hueso y servir caliente."}', 'Costillar de cerdo confitado a fuego lento y glaseado con miel y mostaza.', '[{"appliance":"horno","time":200,"difficulty":"normal","prepSummary":"Para confitar, sumerge las costillas con el aceite y aromáticos en una fuente apta para horno y cocina a 120°C durante 3 horas. Escurre, glasea con la miel y mostaza, y hornea a 200°C unos 15-20 minutos hasta caramelizar."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_092', 'Brochetas de solomillo con pimientos', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 410, 34, 10, 26, 2, true, true, '{}', '[{"name":"Solomillo de ternera en dados","amount":350,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo, pimiento verde y cebolla en trozos cuadrados del mismo tamaño que los dados de carne.","Picar ajo fino.","Mezclar solomillo de ternera en dados con aceite de oliva, el ajo picado, orégano, sal y pimienta negra hasta cubrir bien.","Dejar marinar la carne con el adobo durante 15 min.","Ensartar en las brochetas alternando dado de carne, pimiento rojo, pimiento verde y cebolla hasta completarlas.","Calentar plancha a fuego fuerte hasta que humee.","Cocinar las brochetas 3 min por cada lado hasta que la carne esté dorada y las verduras tiernas.","Servir las brochetas recién hechas."}', 'Brochetas de solomillo de ternera con pimientos, marinadas y asadas a la plancha.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Marinar la carne y los pimientos con aceite y especias. Precalentar la airfryer a 190-200°C. Cocinar las brochetas durante 18-22 minutos, girándolas a mitad del tiempo, hasta que la carne esté dorada y las verduras tiernas."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Marinar la carne y los pimientos con aceite y especias. Precalentar el horno a 200°C con calor arriba y abajo. Colocar las brochetas en una bandeja y hornear durante 25-30 minutos, dándoles la vuelta una vez, hasta que estén doradas y cocidas."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_093', 'Pollo a la naranja crujiente', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 560, 36, 48, 24, 2, true, false, '{"gluten","huevo","soja","sesamo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Zumo de naranja","amount":150,"unit":"ml"},{"name":"Ralladura de naranja","amount":5,"unit":"g"},{"name":"Azúcar moreno","amount":30,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en dados de 3 cm.","Picar ajo y jengibre fresco muy finos.","Picar cebolleta fina y reservar para el emplatado.","Batir huevo en un bol hasta que esté homogéneo.","Añadir los dados de pollo al bol con el huevo batido y mezclar hasta que queden bien impregnados.","Mezclar maicena y harina en un plato llano.","Rebozar los dados de pollo en la mezcla de maicena y harina, sacudiendo el exceso.","Calentar aceite de girasol en sartén honda a fuego fuerte hasta que alcance temperatura de fritura.","Freír los dados de pollo rebozados en tandas hasta que estén dorados y crujientes.","Escurrir el pollo frito sobre papel absorbente y reservar.","Mezclar en un cazo zumo de naranja, ralladura de naranja, azúcar moreno, salsa de soja y vinagre de arroz.","Añadir el ajo y el jengibre picados al cazo con la salsa.","Llevar la salsa a ebullición a fuego fuerte, removiendo hasta que rompa a hervir.","Reducir a fuego medio y cocer hasta que la salsa espese ligeramente.","Añadir el pollo frito a la salsa y saltear a fuego fuerte durante 1 min para que quede bien bañado.","Servir de inmediato espolvoreado con sésamo tostado y la cebolleta picada."}', 'Pollo rebozado y frito hasta quedar crujiente, bañado en una salsa brillante de naranja agridulce.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Para el pollo crujiente, reboza las pechugas y rocíalas con un poco de aceite. Cocínalas en la airfryer a 190°C durante 18-20 minutos, volteando a mitad, hasta que estén doradas. La salsa se prepara aparte en una sartén."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Reboza el pollo y colócalo en una bandeja con rejilla para que circule el aire. Hornea a 200°C (con función ventilador si es posible) durante 25-30 minutos, dándole la vuelta una vez, hasta que esté bien dorado y crujiente. La salsa se elabora en paralelo en una cacerola."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_094', 'Ternera Stroganoff', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 430, 34, 12, 26, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":100,"unit":"ml"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar solomillo de ternera en tiras finas y salpimentar.","Laminar champiñones.","Picar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego fuerte.","Sellar las tiras de solomillo en tandas hasta que estén doradas por fuera. Reservar.","Añadir mantequilla a la misma sartén y sofreír la cebolla a fuego medio hasta que esté transparente.","Incorporar los champiñones laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","Espolvorear harina y pimentón dulce sobre los champiñones y remover durante 1 min hasta que se cocine el crudo de la harina.","Añadir caldo de carne y mostaza de dijon y remover a fuego medio hasta que la salsa espese ligeramente.","Incorporar nata para cocinar, bajar el fuego a suave y cocer 3 min sin que hierva fuerte.","Devolver las tiras de solomillo reservadas a la sartén junto con sus jugos y calentar 2 min a fuego suave.","Picar perejil fresco finamente.","Espolvorear el perejil picado sobre el stroganoff y servir bien caliente."}', 'Tiras de ternera selladas en una salsa cremosa de champiñones y mostaza, el clásico ruso reconvertido en plato de cuchara rápido.', '[{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"La Thermomix permite picar y sofreír la cebolla y los champiñones, dorar la ternera en porciones y luego cocinar la salsa a temperatura controlada, espesándola a la perfección. El resultado es un Stroganoff completo y homogéneo."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Utiliza la función de saltear o dora la ternera y sofríe las verduras en la propia olla. Luego, añade el resto de ingredientes para la salsa y cocina a fuego lento hasta que espese, o si prefieres, cocina a presión por un breve tiempo y luego reduce la salsa sin tapa."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_095', 'Carrillada con puré de patata y reducción', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 160, 'normal', 'all', 520, 32, 38, 24, 2, true, true, '{"lactosa","sulfitos","gluten"}', '[{"name":"Carrillada de cerdo","amount":500,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Vino tinto","amount":200,"unit":"ml"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla, zanahoria, puerro y ajo en trozos pequeños.","Salpimentar carrillada de cerdo por ambos lados.","Enharinar las carrilladas con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar las carrilladas por todos los lados hasta que estén selladas. Reservar en un plato.","Sofreír la cebolla, la zanahoria, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén tiernos.","Añadir laurel y las carrilladas reservadas a la cazuela.","Verter vino tinto y dejar reducir a fuego medio hasta que el alcohol evapore.","Añadir caldo de carne, tapar la cazuela y cocer a fuego suave hasta que la carne esté muy tierna.","Pelar y cortar patata en trozos medianos.","Cocer las patatas en una olla con agua y sal a fuego fuerte hasta que estén tiernas.","Calentar leche en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","Escurrir las patatas cocidas y triturar con la leche caliente y mantequilla hasta obtener un puré fino.","Salpimentar el puré y reservar tapado para mantener el calor.","Retirar las carrilladas de la cazuela y reservar en un plato.","Retirar el laurel y triturar la salsa de cocción con un batidor hasta obtener una crema homogénea.","Colar la salsa triturada a través de un colador fino y verter en la cazuela limpia.","Reducir la salsa colada a fuego medio hasta que nape el dorso de una cuchara.","Disponer el puré de patata en la base del plato y colocar las carrilladas encima.","Napar con la reducción de salsa y servir de inmediato."}', 'Carrillada de cerdo cocinada a fuego lento hasta deshacerse, servida sobre puré de patata y napada con su propia reducción.', '[{"appliance":"horno","time":210,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes líquidos y aromáticos, cubre y guisa en el horno a 150-160°C durante 2.5-3 horas hasta que esté muy tierna. Termina la salsa reduciendo en el fuego y prepara el puré aparte."},{"appliance":"thermomix","time":180,"difficulty":"normal","prepSummary":"Sofríe las verduras y sella la carrillada en el vaso. Añade el resto de ingredientes y programa 120-150 minutos a 90-100°C, velocidad cuchara, giro inverso. Retira la carne, tritura la salsa y prepara el puré en el mismo vaso para un resultado cremoso."},{"appliance":"olla_express","time":120,"difficulty":"normal","prepSummary":"Sella la carrillada y sofríe las verduras en la olla. Añade el vino, caldo y el resto de ingredientes. Cierra y cocina a presión alta durante 45-60 minutos. Tras despresurizar, retira la carne, tritura y reduce la salsa al fuego, y prepara el puré de patata aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_096', 'Pastel de carne con puré gratinado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 75, 'normal', 'all', 500, 28, 35, 26, 4, true, true, '{"lactosa"}', '[{"name":"Carne picada de ternera","amount":600,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Caldo de carne","amount":100,"unit":"ml"},{"name":"Salsa Worcestershire","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Patata","amount":800,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer la patata en una olla con agua abundante y sal hasta que esté tierna.","Picar cebolla, zanahoria y ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, la zanahoria y el ajo hasta que estén blandos.","Añadir carne picada de ternera y dorar a fuego fuerte, deshaciendo los grumos.","Incorporar tomate triturado, caldo de carne, salsa worcestershire y tomillo.","Cocer a fuego medio hasta que la salsa espese. Salpimentar y reservar.","Precalentar el horno a 200 °C.","Calentar leche en un cazo a fuego suave hasta que esté caliente.","Escurrir la patata cocida y triturar en el mismo cazo.","Añadir la leche caliente y la mitad de mantequilla al puré y mezclar hasta que esté cremoso.","Extender la carne guisada en una fuente de horno formando una capa uniforme.","Cubrir la carne con el puré y alisar la superficie con un tenedor.","Repartir queso rallado y el resto de la mantequilla en trocitos por encima.","Hornear a 200 °C hasta que la superficie esté dorada.","Servir la fuente bien caliente en la mesa."}', 'Carne picada guisada con verduras, cubierta de puré de patata y gratinada al horno hasta dorarse.', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Prepara el sofrito y la carne en una sartén. Hierve las patatas para el puré. Monta el pastel en un recipiente apto para horno y gratina a 180-200°C durante 25-30 minutos hasta dorar."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras y la carne en el vaso. Cocina las patatas al vapor en el Varoma y tritúralas para el puré. Monta el pastel en un molde y gratina en el horno a 190°C unos 20-25 minutos."},{"appliance":"olla_express","time":70,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en la olla, luego cocina a presión con el resto de ingredientes unos 15-20 minutos. Cuece las patatas a presión y haz el puré. Monta el pastel y gratina en el horno a 190°C durante 20-25 minutos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_097', 'Lomo a la miel y mostaza', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 380, 30, 20, 18, 2, true, true, '{"mostaza"}', '[{"name":"Lomo de cerdo (filetes)","amount":350,"unit":"g"},{"name":"Miel","amount":40,"unit":"g"},{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Mostaza a la antigua","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Mezclar en un bol miel, mostaza de dijon, mostaza a la antigua, el ajo picado y vinagre de manzana hasta integrar.","Salpimentar lomo de cerdo (filetes) por ambos lados.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar los filetes de lomo 2 min por cada lado hasta que estén sellados y dorados.","Bajar el fuego a medio y verter la mezcla de miel y mostaza sobre los filetes.","Cocinar 5 min, girando los filetes a mitad para que se impregnen bien, hasta que el glaseado espese y brille.","Retirar del fuego cuando la carne esté jugosa y el glaseado cubra los filetes.","Servir los filetes napados con el glaseado de la sartén."}', 'Filetes de lomo de cerdo glaseados en una salsa brillante de miel y dos mostazas, listos en menos de media hora.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Marinar los filetes de lomo en la mezcla de miel, mostazas, ajo, aceite y vinagre. Cocinar en la airfryer precalentada a 190°C durante 15-18 minutos, dándoles la vuelta a mitad, para un exterior dorado y un interior jugoso."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Tras marinar los filetes, colocarlos en una fuente de horno. Hornear a 200°C durante 20-25 minutos, volteándolos una vez y rociando con la salsa para asegurar que queden tiernos y con un buen glaseado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_098', 'Jarrete de ternera al horno con verduras', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 200, 'normal', 'all', 480, 38, 30, 20, 2, true, true, '{"sulfitos","gluten"}', '[{"name":"Jarrete de ternera","amount":700,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Patata baby","amount":300,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Romero","amount":3,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Pelar y cortar zanahoria en trozos grandes.","Pelar y cortar cebolla en trozos grandes.","Limpiar y cortar puerro en rodajas gruesas.","Picar ajo fino.","Lavar patata baby y reservar enteras.","Salpimentar jarrete de ternera por todos los lados.","Enharinar el jarrete con harina, sacudiendo el exceso.","Calentar aceite de oliva en una cazuela apta para horno a fuego fuerte.","Dorar el jarrete por todos los lados hasta que esté bien sellado y con color.","Retirar el jarrete y reservar en un plato.","Sofreír la cebolla, el puerro y el ajo en la misma cazuela a fuego medio hasta que estén pochados.","Añadir la zanahoria y la patata baby y saltear 2 min a fuego medio.","Incorporar vino blanco y dejar reducir hasta que el alcohol se evapore.","Añadir tomate triturado, caldo de carne, laurel y romero y remover para integrar.","Devolver el jarrete a la cazuela, colocándolo sobre las verduras.","Tapar la cazuela y hornear a 180 °C hasta que la carne se separe del hueso con facilidad.","Retirar el laurel y el romero de la cazuela.","Servir el jarrete con las verduras y el jugo de cocción."}', 'Jarrete de ternera cocinado lentamente al horno junto a verduras de raíz, hasta que la carne se deshace sola del hueso.', '[{"appliance":"horno","time":200,"difficulty":"normal","prepSummary":"Sella el jarrete, sofríe las verduras y desglasa con vino. Añade el caldo, tomate y hierbas, y hornea cubierto a 160-170°C durante 3 horas y 20 minutos hasta que la carne esté muy tierna."},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Tras sellar la carne y sofreír las verduras, incorpora los líquidos y hierbas. Cocina en olla express a presión alta durante 60-75 minutos. Deja despresurizar y si es necesario, reduce la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_099', 'Solomillo Café de París', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 540, 33, 3, 44, 2, true, true, '{"lactosa","mostaza"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Mantequilla","amount":80,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Chalota","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"},{"name":"Brandy","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Curry en polvo","amount":1,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Retirar solomillo de ternera de la nevera y dejar atemperar a temperatura ambiente.","Picar finamente perejil fresco, cebollino, ajo y chalota.","Ablandar mantequilla a temperatura ambiente hasta que esté cremosa.","Mezclar la mantequilla con el perejil, el cebollino, el ajo y la chalota picados.","Añadir mostaza de dijon, brandy, pimentón dulce, curry en polvo y zumo de limón a la mezcla de mantequilla.","Mezclar bien hasta obtener una mantequilla compuesta homogénea.","Formar un cilindro con la mantequilla compuesta enrollándola en film transparente.","Enfriar el cilindro de mantequilla en el congelador hasta que esté firme.","Salpimentar el solomillo de ternera por ambos lados.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Marcar el solomillo de ternera 2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","Retirar el solomillo de la sartén y dejar reposar fuera del fuego.","Cortar la mantequilla compuesta en rodajas de 1 cm.","Colocar 2 o 3 rodajas de mantequilla compuesta sobre cada medallón caliente y servir enseguida."}', 'Medallones de solomillo de ternera marcados a la plancha y coronados con mantequilla compuesta de hierbas, mostaza y un toque de brandy.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Para el solomillo, precalienta la airfryer a 190-200°C y cocina el solomillo unos 15-20 minutos, dándole la vuelta a mitad, hasta el punto deseado. La mantequilla Café de París se prepara aparte mezclando todos los ingredientes picados y se sirve sobre el solomillo caliente."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén muy caliente con aceite por 2-3 minutos por cada lado. Luego, trasládalo a una bandeja y hornea a 190°C durante 10-15 minutos para terminar la cocción. La mantequilla Café de París se elabora mezclando los ingredientes picados y se añade al solomi"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_100', 'Filete tártaro con patatas fritas al lado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 620, 29, 38, 36, 2, false, false, '{"huevo","mostaza","pescado"}', '[{"name":"Solomillo de ternera (para tartar)","amount":300,"unit":"g"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Alcaparras","amount":20,"unit":"g"},{"name":"Pepinillos encurtidos","amount":30,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Salsa Worcestershire","amount":10,"unit":"ml"},{"name":"Tabasco","amount":3,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones uniformes de unos 1 cm de grosor.","Calentar aceite de girasol en una sartén profunda a fuego medio hasta alcanzar 150 °C.","Freír las patatas en 2 tandas durante 6 min cada una hasta que estén tiernas pero sin dorar.","Subir el fuego a fuerte hasta que el aceite alcance 190 °C.","Freír las patatas de nuevo en 2 tandas durante 2 min hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y reservar en lugar templado.","Picar solomillo de ternera (para tartar) a cuchillo en dados muy pequeños; nunca usar picadora.","Picar alcaparras muy finamente.","Picar pepinillos encurtidos muy finamente.","Picar cebolla morada muy finamente.","Picar perejil fresco muy finamente.","Mezclar en un bol frío el solomillo picado con las alcaparras, los pepinillos, la cebolla morada y el perejil.","Añadir mostaza de dijon, salsa worcestershire, tabasco y aceite de oliva.","Mezclar con delicadeza hasta integrar sin machacar la carne; salpimentar al gusto.","Reservar la mezcla en la nevera hasta el momento de emplatar.","Salar las patatas fritas recién escurridas.","Moldear el tartar en 2 platos fríos con un aro de cocina formando un cilindro compacto.","Coronar cada tartar con yema de huevo cruda centrada sobre la carne.","Servir las patatas fritas al lado del tartar y llevar a la mesa de inmediato."}', 'Carne de ternera picada a cuchillo, aliñada al estilo clásico de brasserie con alcaparras y mostaza, coronada con yema y servida con patatas fritas.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"La airfryer es ideal para las patatas fritas, ofreciendo una versión crujiente y más saludable. Corta las patatas en bastones, rocía con un poco de aceite y cocina a 190-200°C durante 20-25 minutos, agitándolas a mitad de cocción. El tartar se prepara aparte, mezclando a mano tod"},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"El horno permite preparar unas patatas fritas más ligeras y doradas. Corta las patatas en bastones, mézclalas con un hilo de aceite y sal, y hornea a 200-220°C durante 30-40 minutos, volteándolas ocasionalmente hasta que estén crujientes. El filete tártaro se elabora mezclando ma"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_101', 'Solomillo a la parrilla con patatas panadera y salsa de boletus', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'all', 610, 34, 34, 36, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Solomillo de ternera","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Boletus","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de carne","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 3 mm.","Cortar cebolla en juliana fina.","Calentar la mitad de aceite de oliva en una sartén grande a fuego medio.","Añadir las rodajas de patata y la cebolla en juliana. Tapar y cocinar a fuego suave hasta que estén tiernas.","Limpiar boletus y cortar en trozos medianos.","Picar ajo fino.","Picar perejil fresco fino y reservar.","Destapar las patatas, subir a fuego medio y remover hasta que estén doradas. Salpimentar.","Calentar un chorrito del aceite de oliva restante en un cazo a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los boletus y saltear a fuego fuerte hasta que estén dorados y hayan soltado el agua.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne y nata para cocinar. Cocinar a fuego suave hasta que la salsa espese. Salpimentar.","Salpimentar solomillo de ternera por ambas caras.","Calentar plancha a fuego fuerte hasta que humee.","Asar el solomillo 2-3 min por cada lado hasta alcanzar el punto deseado.","Retirar el solomillo de la plancha y dejar reposar sobre una tabla.","Disponer las patatas panadera en el plato, colocar el solomillo encima y napar con la salsa de boletus.","Espolvorear con el perejil picado y servir de inmediato."}', 'Medallones de solomillo marcados a la plancha, acompañados de patatas panadera y una salsa cremosa de boletus.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_102', 'Entrecot a la brasa con patatas fritas y salsa Café de París', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 700, 40, 35, 45, 2, true, false, '{"lactosa","mostaza"}', '[{"name":"Entrecot de ternera","amount":400,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Perejil fresco","amount":8,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Chalota","amount":15,"unit":"g"},{"name":"Mostaza de Dijon","amount":8,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Sacar entrecot de ternera de la nevera y dejar atemperar.","Ablandar mantequilla a temperatura ambiente hasta que esté pomada.","Picar perejil fresco, cebollino, ajo y chalota muy finos.","Mezclar la mantequilla pomada con el perejil, el cebollino, el ajo y la chalota picados.","Añadir mostaza de dijon, zumo de limón y pimentón dulce a la mezcla de mantequilla.","Mezclar bien hasta integrar todos los ingredientes y formar una pasta homogénea.","Formar un cilindro con la mantequilla compuesta, envolver en film y refrigerar hasta que esté firme.","Pelar patata y cortar en bastones de grosor uniforme.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las patatas en 2 tandas hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","Salpimentar el entrecot atemperado por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte hasta que humee.","Marcar el entrecot 3 min por cada cara hasta alcanzar el punto deseado. No mover entre giros.","Retirar el entrecot de la plancha y dejar reposar sobre una rejilla o tabla.","Cortar rodajas de la mantequilla compuesta fría y colocarlas sobre el entrecot caliente.","Servir el entrecot con la mantequilla fundiéndose y las patatas fritas al lado."}', 'Entrecot a la brasa con mantequilla Café de París derritiéndose por encima, acompañado de patatas fritas crujientes.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Cocina el entrecot unos 12-15 minutos (dando la vuelta) y las patatas (con un poco de aceite) a 180°C durante 20-25 minutos, agitando. La salsa Café de París se prepara aparte mezclando los ingredientes."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C. Hornea las patatas (con aceite y sal) durante 30-40 minutos, volteando a mitad. El entrecot se puede sellar en sartén y terminar en el horno a 200°C unos 8-10 minutos. La salsa Café de París se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_103', 'Costillas glaseadas con puré de boniato y salsa barbacoa', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 120, 'normal', 'all', 630, 32, 45, 34, 2, true, true, '{"mostaza","sulfitos","lactosa"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Boniato","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Ketchup","amount":80,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Vinagre de manzana","amount":20,"unit":"ml"},{"name":"Mostaza","amount":10,"unit":"g"},{"name":"Pimentón ahumado","amount":5,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 150 °C.","Salpimentar costillar de cerdo por ambos lados.","Colocar el costillar sobre una bandeja de horno cubierta con papel de aluminio y taparlo bien con más papel.","Hornear el costillar tapado a 150 °C hasta que la carne esté muy tierna.","Mezclar ketchup, miel, vinagre de manzana, mostaza, pimentón ahumado y ajo en polvo en un bol hasta obtener la salsa barbacoa.","Pelar boniato y cortar en trozos medianos.","Llevar a ebullición un cazo con agua con sal y cocer el boniato hasta que esté tierno.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente.","Escurrir el boniato cocido.","Triturar el boniato escurrido con la leche caliente y mantequilla hasta obtener un puré fino.","Subir el horno a 220 °C.","Retirar el papel de aluminio y pincelar el costillar con la salsa barbacoa por ambos lados.","Hornear el costillar destapado a 220 °C durante 8 min.","Retirar la bandeja y pincelar el costillar de nuevo con la salsa barbacoa por ambos lados.","Hornear otros 8 min hasta que el glaseado quede brillante y pegajoso.","Retirar el costillar del horno y cortar entre hueso y hueso.","Servir el costillar sobre el puré de boniato."}', 'Costillar de cerdo horneado hasta quedar tierno y glaseado con salsa barbacoa casera, sobre un puré cremoso de boniato.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Las costillas se cocinan a baja temperatura (150°C) durante 90-100 minutos para ablandarlas, luego se glasean con la salsa barbacoa y se hornean a 180-200°C por 20-30 minutos hasta caramelizar. El boniato se asa en el mismo horno hasta estar tierno y se tritura para el puré."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_104', 'Secreto ibérico con patatas Hasselback y romesco', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 70, 'normal', 'all', 660, 30, 32, 44, 2, true, true, '{"frutos_secos","gluten","sulfitos"}', '[{"name":"Secreto ibérico","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Pimiento choricero","amount":15,"unit":"g"},{"name":"Almendra tostada","amount":30,"unit":"g"},{"name":"Avellana tostada","amount":20,"unit":"g"},{"name":"Pan","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Lavar patata y hacer cortes finos y paralelos cada 3 mm sin llegar a atravesarlas.","Colocar las patatas en una bandeja y regar con aceite de oliva.","Salpimentar las patatas y hornear en el centro del horno a 200 °C hasta que estén doradas y crujientes.","Colocar tomate maduro y ajo en una bandeja pequeña con aceite de oliva e introducir en el horno.","Asar el tomate y el ajo en el horno a 200 °C hasta que estén blandos y ligeramente tostados.","Calentar aceite de oliva en una sartén pequeña a fuego fuerte y freír pimiento choricero 30 segundos hasta que se hidrate.","Tostar pan en la misma sartén a fuego medio hasta que esté ligeramente dorado.","Triturar el tomate y el ajo asados con el pimiento choricero, almendra tostada, avellana tostada y el pan.","Añadir vinagre de jerez y el resto del aceite de oliva al vaso del triturador y triturar hasta obtener una salsa espesa.","Salpimentar el romesco y reservar a temperatura ambiente.","Salpimentar secreto ibérico por ambas caras.","Calentar plancha a fuego fuerte hasta que humee.","Colocar el secreto ibérico en la plancha y marcar 3 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","Retirar el secreto de la plancha y dejar reposar sobre una tabla.","Cortar el secreto ibérico en lonchas de aproximadamente 1 cm.","Servir las lonchas de secreto junto a las patatas Hasselback y el romesco en un cuenco aparte."}', 'Secreto ibérico a la plancha con patatas Hasselback crujientes y una salsa romesco de almendras y pimiento choricero.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Hornea las patatas Hasselback durante 50-60 min y el secreto ibérico los últimos 15-20 min. Asa los ingredientes del romesco junto a las patatas y tritura para la salsa."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Cocina las patatas Hasselback en la airfryer a 190°C durante 35-40 min, luego el secreto ibérico a 200°C por 15 min. Asa los ingredientes del romesco en la misma airfryer antes de triturar para la salsa."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_105', 'Magret de pato con puré de boniato y reducción de frutos rojos', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 580, 30, 40, 32, 2, false, true, '{"lactosa","sulfitos"}', '[{"name":"Magret de pato","amount":350,"unit":"g"},{"name":"Boniato","amount":350,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Frutos rojos","amount":150,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Azúcar moreno","amount":30,"unit":"g"},{"name":"Vinagre de Módena","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en trozos medianos.","Cocer el boniato en una olla con agua salada hasta que esté tierno.","Marcar la piel de magret de pato con un cuchillo en rombos sin llegar a la carne.","Salpimentar el magret por ambas caras.","Colocar el magret en sartén fría con la piel hacia abajo y encender el fuego medio.","Cocinar hasta que la piel esté dorada y crujiente, retirando la grasa que suelte con una cuchara.","Calentar frutos rojos, vino tinto, azúcar moreno y vinagre de módena en un cazo a fuego medio.","Reducir la mezcla a fuego medio hasta que la salsa esté espesa y nape la cuchara.","Dar la vuelta al magret y cocinar por el lado de la carne hasta alcanzar el punto deseado.","Retirar el magret de la sartén y dejar reposar sobre una tabla.","Escurrir el boniato cocido y triturar con leche y mantequilla hasta obtener un puré fino.","Cortar el magret en lonchas de 1 cm en sentido transversal a la fibra.","Disponer el puré en el plato, colocar las lonchas de magret encima y napar con la reducción de frutos rojos."}', 'Magret de pato con la piel crujiente, servido sobre un puré de boniato y napado con una reducción de frutos rojos.', '[{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Para el magret, márcalo por el lado de la piel en una sartén y luego cocínalo en la airfryer a 180°C por 15-20 min. El boniato se puede asar en la misma airfryer hasta que esté tierno, facilitando el puré."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Sella el magret por el lado de la piel en una sartén y termina su cocción en el horno a 180°C durante 10-15 min. Aprovecha el horno para asar el boniato hasta que esté muy tierno para el puré."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_106', 'Chuletón a la parrilla con patatas fritas y alioli de ajo asado', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 800, 45, 35, 55, 2, true, false, '{"huevo"}', '[{"name":"Chuletón de ternera","amount":700,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Cabeza de ajos","amount":1,"unit":"ud"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Envolver cabeza de ajos en papel de aluminio con aceite de oliva suave.","Hornear el paquete de ajos a 200 °C durante 40 min, hasta que los dientes estén blandos.","Pelar patata y cortar en bastones de 1 cm de grosor.","Sacar chuletón de ternera de la nevera para que atempere al menos 20 min antes de cocinarlo.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta que alcance 180 °C.","Freír las patatas en el aceite caliente durante 8 min, hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Retirar los ajos del horno y dejar templar 5 min hasta poder manejarlos.","Extraer la pulpa de los dientes de ajo asados presionando cada diente desde la base.","Poner huevo y zumo de limón en el vaso de la batidora junto con la pulpa de ajo asado.","Triturar a velocidad baja y añadir el aceite de oliva suave en hilo fino hasta que emulsione y espese.","Salpimentar el chuletón atemperado por ambas caras antes de cocinarlo.","Calentar plancha a fuego fuerte hasta que humee.","Marcar el chuletón 4 min por el primer lado sin moverlo, hasta que se forme costra.","Dar la vuelta al chuletón y marcar 4 min por el otro lado hasta alcanzar el punto deseado.","Retirar el chuletón de la plancha y dejar reposar 5 min para que los jugos se asienten.","Cortar el chuletón en lonchas gruesas siguiendo el hueso.","Servir las lonchas de chuletón junto con las patatas fritas y el alioli de ajo asado aparte."}', 'Chuletón de ternera a la parrilla, cortado en lonchas gruesas, con patatas fritas y un alioli suave de ajo asado.', '[{"appliance":"airfryer","time":50,"difficulty":"facil","prepSummary":"El airfryer es ideal para las patatas fritas y el ajo asado. Para el chuletón, precalienta a 200°C y cocina unos 15-20 minutos, volteando a mitad, para un exterior crujiente y un interior jugoso. Las patatas quedan doradas y el ajo tierno para el alioli."},{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"El horno es excelente para asar el ajo y las patatas (horneadas). Para el chuletón, precalienta a 220°C y cocina unos 20-25 minutos, volteando, para un buen sellado y cocción uniforme. Las patatas se dorarán y el ajo quedará tierno y dulce."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_107', 'Costillar de cerdo con puré de patata cremoso y salsa BBQ ahumada', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 650, 33, 42, 38, 2, true, true, '{"lactosa","mostaza","sulfitos"}', '[{"name":"Costillar de cerdo","amount":600,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Ketchup","amount":80,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Pimentón ahumado","amount":6,"unit":"g"},{"name":"Mostaza","amount":10,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 150 °C.","Salpimentar costillar de cerdo por ambas caras.","Envolver el costillar en papel de aluminio y colocarlo sobre una bandeja de horno.","Hornear el costillar tapado a 150 °C hasta que la carne esté muy tierna y se separe fácilmente del hueso.","Mezclar ketchup, miel, vinagre de manzana, pimentón ahumado, mostaza y ajo en polvo en un bol hasta obtener la salsa BBQ.","Pelar patata y cortar en trozos medianos.","Llevar a ebullición un cazo con agua y sal, añadir la patata y cocer hasta que esté tierna.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin llegar a hervir.","Escurrir la patata cocida y triturar en el cazo con la leche caliente y mantequilla hasta obtener un puré liso.","Salpimentar el puré y reservar tapado para que se mantenga caliente.","Subir el horno a 220 °C.","Retirar el papel de aluminio y pincelar el costillar generosamente con la salsa BBQ.","Hornear el costillar destapado a 220 °C durante 7 min, pincelar de nuevo con la salsa BBQ y hornear 8 min más.","Retirar el costillar del horno y cortar entre hueso y hueso.","Servir el costillar sobre una base de puré de patata y añadir salsa BBQ restante por encima."}', 'Costillar de cerdo horneado hasta la ternura, glaseado con una salsa barbacoa ahumada y servido sobre puré de patata cremoso.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Cocina el costillar lentamente a baja temperatura (aprox. 150-160°C) durante 90-100 minutos para que quede tierno, glaseando con la salsa BBQ en los últimos 20-30 minutos para caramelizar. Prepara el puré y la salsa en paralelo."},{"appliance":"olla_express","time":90,"difficulty":"normal","prepSummary":"Cocina el costillar en la olla express con un poco de líquido durante 35-45 minutos para una ternura excepcional. Luego, termina en el horno a 200°C durante 15-20 minutos, glaseando con la salsa BBQ para dorar y caramelizar. El puré se puede hacer también en la olla express."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_108', 'Pollo asado con patatas panadera y salsa de sus jugos', 'carnes', 'pollo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 70, 'facil', 'all', 560, 38, 32, 30, 2, true, true, '{"gluten"}', '[{"name":"Muslos y contramuslos de pollo","amount":500,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de pollo","amount":150,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Tomillo","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar patata y cortarla en rodajas finas de unos 3 mm.","Cortar cebolla en juliana fina.","Colocar la patata y la cebolla en una fuente de horno.","Regar con la mitad de aceite de oliva, salpimentar y mezclar bien hasta cubrir todas las rodajas.","Salpimentar muslos y contramuslos de pollo por todas las caras.","Colocar el pollo sobre la cama de patatas y cebolla en la fuente.","Repartir ajo entero sin pelar alrededor del pollo.","Espolvorear tomillo y regar con el resto del aceite de oliva.","Hornear 45 min hasta que el pollo esté dorado y las patatas tiernas.","Voltear las patatas a mitad de cocción, hacia el minuto 22-23, para que se doren de manera uniforme.","Retirar el pollo y las patatas de la fuente y reservar calientes tapados con papel de aluminio.","Pasar los jugos de la fuente a un cazo y calentar a fuego medio.","Añadir harina y remover sin parar durante 1 min hasta que no queden grumos.","Verter vino blanco y raspar el fondo del cazo para soltar los jugos pegados.","Añadir caldo de pollo y dejar reducir a fuego medio hasta obtener una salsa ligera.","Servir el pollo junto a las patatas y napar con la salsa de sus jugos."}', 'Pollo asado al horno sobre patatas panadera, con una salsa ligera hecha con sus propios jugos de cocción.', '[{"appliance":"horno","time":70,"difficulty":"facil","prepSummary":"Asa el pollo y las patatas panadera en una bandeja de horno, permitiendo que los jugos del pollo impregnen las patatas. Al final, usa los jugos concentrados para ligar la salsa."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Cocina el pollo en la airfryer a 190°C hasta que esté dorado y crujiente, volteándolo a mitad. Las patatas y cebolla se asan por separado en la misma airfryer, y la salsa se prepara en un cazo con los mínimos jugos que se puedan recoger o con caldo adicional."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_109', 'Presa ibérica con patatas fritas y salsa de pimienta verde', 'carnes', 'cerdo', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 770, 34, 33, 52, 2, false, false, '{"lactosa"}', '[{"name":"Presa ibérica","amount":350,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Pimienta verde en grano","amount":20,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Caldo de carne","amount":80,"unit":"ml"},{"name":"Brandy","amount":20,"unit":"ml"},{"name":"Chalota","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Calentar aceite de girasol en una olla o sartén honda a fuego fuerte hasta que alcance unos 180 °C.","Freír los bastones de patata hasta que estén dorados y crujientes.","Escurrir las patatas sobre papel absorbente y reservar.","Picar chalota muy fina.","Salpimentar presa ibérica por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte.","Dorar la presa ibérica 3 min por cada cara hasta alcanzar el punto deseado.","Retirar la presa ibérica y dejar reposar en un plato.","Sofreír la chalota picada en la misma plancha a fuego medio hasta que esté transparente.","Añadir pimienta verde en grano y remover 1 min para que libere su aroma.","Verter brandy y dejar evaporar el alcohol a fuego fuerte hasta que deje de humear.","Añadir caldo de carne y nata para cocinar; remover para integrar.","Cocer a fuego medio hasta que la salsa espese y nape la cuchara.","Cortar la presa ibérica en lonchas de unos 2 cm.","Servir las lonchas napadas con la salsa de pimienta verde y las patatas fritas al lado."}', 'Presa ibérica a la plancha en una cremosa salsa de pimienta verde, servida con patatas fritas.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"La presa se cocina a 190°C por 15-20 min, volteando a mitad para un sellado uniforme. Las patatas se hacen a 180°C por 20-25 min con poco aceite, agitándolas ocasionalmente. La salsa se prepara aparte en una sartén mientras se cocinan los otros elementos."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Las patatas se hornean a 200°C por 30-40 min con un chorrito de aceite, volteándolas para que doren parejo. La presa se sella primero en sartén y se termina en el horno a 200°C por 10-15 min. La salsa se elabora en una sartén aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_110', 'Hamburguesa de solomillo con patatas fritas y salsa de queso azul', 'carnes', 'ternera', 'pan', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 850, 40, 52, 50, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Solomillo de ternera picado","amount":350,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Formar 2 hamburguesas con solomillo de ternera picado, salpimentar y reservar en la nevera.","Reposar las hamburguesas en la nevera para que asienten.","Pelar patata y cortar en bastones de grosor uniforme.","Calentar aceite de girasol en una olla a fuego fuerte hasta que alcance 180 °C.","Freír los bastones de patata en el aceite de girasol caliente hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y salar al gusto.","Desmenuzar queso azul en un cazo pequeño y añadir nata para cocinar.","Calentar la mezcla a fuego suave, remover hasta que el queso azul se funda y la salsa esté homogénea.","Calentar aceite de oliva en plancha a fuego fuerte hasta que humee ligeramente.","Cocinar las hamburguesas en la plancha 3 min por cada lado hasta que estén doradas al punto deseado.","Tostar pan de hamburguesa por su cara interior en la plancha hasta que esté ligeramente dorado.","Laminar tomate y cebolla morada en rodajas finas; separar hojas de lechuga.","Colocar lechuga, tomate y cebolla morada sobre la base del pan de hamburguesa tostado.","Disponer la hamburguesa sobre las verduras y verter la salsa de queso azul por encima.","Cerrar con la tapa del pan de hamburguesa y servir con las patatas fritas al lado."}', 'Hamburguesa de solomillo de ternera con una cremosa salsa de queso azul, servida con patatas fritas.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara las patatas con un poco de aceite y cocínalas en la airfryer a 190°C durante 20-25 minutos. Luego, cocina las hamburguesas a 180°C por 12-15 minutos, dándoles la vuelta a mitad, para un exterior crujiente y un interior jugoso."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Dispón las patatas y las hamburguesas en bandejas separadas con un poco de aceite. Hornea a 200°C durante 30-40 minutos para las patatas y 15-20 minutos para las hamburguesas, asegurando un cocinado uniforme."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_111', 'Costillas de cordero con puré de boniato y salsa de menta', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 630, 32, 34, 38, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Costillas de cordero (chuletillas)","amount":400,"unit":"g"},{"name":"Boniato","amount":350,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Menta fresca","amount":15,"unit":"g"},{"name":"Azúcar","amount":15,"unit":"g"},{"name":"Vinagre de vino blanco","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en trozos medianos.","Cocer el boniato en agua con sal hasta que esté tierno.","Laminar ajo.","Picar menta fresca muy fina.","Mezclar la menta picada con vinagre de vino blanco y azúcar en un cazo.","Calentar el cazo a fuego suave hasta que el azúcar se disuelva.","Retirar el cazo del fuego y reservar la salsa de menta para que temple.","Salpimentar costillas de cordero (chuletillas) y dejar atemperar.","Escurrir el boniato cocido.","Calentar leche en el cazo a fuego suave hasta que esté caliente.","Triturar el boniato escurrido con la leche caliente y mantequilla hasta obtener un puré fino.","Salpimentar el puré y reservar tapado.","Calentar aceite de oliva en sartén a fuego fuerte.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse.","Añadir las costillas y dorar 2 min por cada lado hasta que estén doradas por fuera y rosadas por dentro.","Retirar las costillas de la sartén y dejar reposar.","Servir las costillas sobre el puré de boniato y rociar con la salsa de menta."}', 'Costillas de cordero doradas a la plancha, servidas sobre puré de boniato y con una salsa fresca de menta.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Cocina las chuletillas a 190-200°C por 12-15 min, volteando a mitad, para un exterior crujiente. Asa el boniato en cubos a 180°C por 15-20 min hasta que esté tierno para el puré."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Asa el boniato en trozos y las chuletillas de cordero en el horno precalentado a 200-220°C. El boniato tardará unos 30-40 min y las chuletillas 15-20 min, volteándolas para un dorado uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_112', 'Pollo Marry Me con tomate seco y parmesano', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 500, 38, 8, 32, 2, true, true, '{"lactosa"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Tomate seco en aceite","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Caldo de pollo","amount":100,"unit":"ml"},{"name":"Parmesano rallado","amount":40,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en filetes de grosor uniforme.","Salpimentar los filetes por ambas caras.","Picar ajo fino.","Cortar tomate seco en aceite en tiras pequeñas.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar los filetes de pollo 3 min por cada cara hasta que estén dorados. Reservar.","Sofreír el ajo picado y el tomate seco en la misma sartén a fuego medio hasta que estén fragantes.","Añadir pimentón dulce y remover para integrarlo con el sofrito.","Añadir caldo de pollo y nata para cocinar y remover para mezclar bien.","Añadir parmesano rallado y remover hasta que se integre en la salsa.","Cocer la salsa a fuego medio hasta que espese, unos 4 min.","Incorporar los filetes de pollo reservados y napar con la salsa.","Cocer a fuego suave 3 min hasta que el pollo esté bien caliente y la salsa lo cubra.","Picar albahaca fresca fina y espolvorear sobre el plato. Servir de inmediato."}', 'Pechuga de pollo en una salsa cremosa de tomate seco y parmesano, el viral que promete pedida de mano.', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sella las pechugas en una sartén y luego pásalas a una fuente apta para horno. Vierte la salsa con el resto de ingredientes (excepto albahaca) sobre el pollo y hornea a 190°C durante 20-25 minutos, hasta que el pollo esté cocido y la salsa burbujeante. Un truco es cubrir la fuent"},{"appliance":"thermomix","time":28,"difficulty":"facil","prepSummary":"Trocea el ajo y sofríelo. Añade las pechugas troceadas y sofríe hasta que doren. Incorpora el resto de ingredientes (excepto albahaca y parte del parmesano), programa 18-20 min a 90°C, giro inverso, velocidad cuchara. El truco es añadir el parmesano y la albahaca al final para ma"},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sella las pechugas de pollo en la olla. Añade el tomate seco, ajo, nata, caldo y pimentón. Cierra la olla y cocina a presión alta durante 5-7 minutos. Despresuriza, retira el pollo, y si la salsa está líquida, reduce a fuego alto unos minutos. El truco es no sobrecocer el pollo p"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_113', 'Alitas de pollo al gochujang', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 50, 'normal', 'all', 560, 34, 22, 34, 2, false, true, '{"soja","sesamo","gluten"}', '[{"name":"Alitas de pollo","amount":600,"unit":"g"},{"name":"Gochujang","amount":40,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo y jengibre fresco muy finos.","Mezclar gochujang, salsa de soja, miel, aceite de sésamo, el ajo picado y el jengibre picado en un bol hasta obtener una salsa homogénea.","Picar cebolleta fina y reservar.","Secar alitas de pollo con papel de cocina y colocarlas en una bandeja con papel de horno.","Rociar las alitas con aceite de girasol y salpimentar.","Hornear las alitas a 200 °C durante 30 min, dándoles la vuelta a los 15 min, hasta que estén doradas.","Retirar las alitas del horno y pincelarlas generosamente con la mezcla de gochujang por ambos lados.","Devolver las alitas al horno a 200 °C durante 8 min, hasta que el glaseado esté pegajoso y caramelizado.","Servir las alitas espolvoreadas con sésamo tostado y la cebolleta picada."}', 'Alitas de pollo horneadas hasta quedar crujientes y glaseadas con gochujang, dulce y picante a la vez.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Marinar las alitas con la mezcla de gochujang. Cocinar en la airfryer a 190°C durante 20-25 minutos, volteándolas a mitad de cocción para asegurar un dorado uniforme y una piel crujiente."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Tras marinar las alitas, hornear a 200°C (con ventilador si es posible) durante 45-50 minutos. Voltear las alitas una o dos veces y pincelar con la salsa durante los últimos minutos para un glaseado perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_114', 'Costillas coreanas glaseadas (estilo galbi)', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 150, 'normal', 'all', 560, 32, 24, 34, 2, true, true, '{"soja","sesamo"}', '[{"name":"Costillas de ternera (corte fino estilo galbi)","amount":600,"unit":"g"},{"name":"Salsa de soja","amount":80,"unit":"ml"},{"name":"Pera","amount":100,"unit":"g"},{"name":"Azúcar moreno","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Aceite de sésamo","amount":15,"unit":"ml"},{"name":"Sésamo tostado","amount":8,"unit":"g"},{"name":"Cebolleta","amount":15,"unit":"g"}]'::jsonb, '{"Pelar pera y cortar en trozos.","Pelar ajo y jengibre fresco.","Triturar la pera, el ajo y el jengibre hasta obtener un puré fino.","Añadir salsa de soja, azúcar moreno y aceite de sésamo al puré y mezclar hasta integrar.","Sumergir costillas de ternera (corte fino estilo galbi) en la marinada, cubrir y refrigerar mínimo 120 min.","Precalentar el horno a 200 °C.","Retirar las costillas de la marinada y escurrir, reservando la marinada sobrante.","Picar cebolleta fina y reservar.","Colocar las costillas escurridas en una bandeja con papel de horno.","Hornear las costillas a 200 °C durante 20 min.","Retirar la bandeja del horno y pincelar las costillas con la marinada reservada.","Hornear de nuevo a 200 °C durante 15 min, hasta que estén doradas y el glaseado pegajoso.","Retirar las costillas del horno y dejar reposar 3 min.","Servir las costillas espolvoreadas con sésamo tostado y la cebolleta picada."}', 'Costillas de ternera cortadas finas y marinadas al estilo coreano, horneadas hasta quedar pegajosas y glaseadas.', '[{"appliance":"horno","time":150,"difficulty":"normal","prepSummary":"Marinar las costillas al menos 4 horas. Hornear a 160°C durante 120 minutos, luego subir a 180-200°C los últimos 30 minutos, pintando con la marinada reducida para un glaseado perfecto y tierno."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Marinar bien las costillas. Cocinar en la airfryer a 180°C durante 35-45 minutos, volteando cada 10-15 minutos y pincelando con la marinada para lograr un glaseado crujiente y tierno."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Marinar las costillas. Cocer en la olla express con parte de la marinada durante 30-35 minutos a presión para ablandar. Luego, terminar en el horno o airfryer a alta temperatura (200°C) durante 15-20 minutos para caramelizar el glaseado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_115', 'Smash burger con queso cheddar doble', 'carnes', 'ternera', 'pan', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 800, 38, 40, 52, 2, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Queso cheddar (lonchas)","amount":4,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Pepinillos en rodajas","amount":20,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Mostaza americana","amount":15,"unit":"g"},{"name":"Mayonesa","amount":20,"unit":"g"}]'::jsonb, '{"Dividir carne picada de ternera en 4 porciones iguales y formar bolas.","Salpimentar las 4 bolas de carne por todos los lados.","Laminar cebolla en juliana muy fina.","Mezclar ketchup, mostaza americana y mayonesa en un bol pequeño hasta integrar. Reservar.","Calentar plancha a fuego fuerte hasta que humee.","Fundir mantequilla en plancha a fuego medio.","Tostar pan de hamburguesa por la cara interior hasta que esté dorado. Reservar.","Subir el fuego a fuego fuerte y colocar las 4 bolas de carne en plancha dejando espacio entre ellas.","Aplastar cada bola con una espátula firme hasta dejarla muy fina, formando un borde crujiente.","Cocer las hamburguesas sin moverlas durante 2 min hasta que los bordes estén bien dorados.","Dar la vuelta a cada hamburguesa con la espátula.","Colocar 1 loncha de queso cheddar (lonchas) sobre cada hamburguesa.","Cocer 1 min más hasta que el queso cheddar se funda completamente.","Extender la mezcla de salsas sobre la base de pan tostado.","Añadir la cebolla en juliana y pepinillos en rodajas sobre la salsa.","Apilar 2 hamburguesas con queso por ración sobre los pepinillos.","Cerrar con la tapa de pan tostado y servir de inmediato."}', 'Dos capas de carne aplastada en la plancha con bordes crujientes, dobles de queso cheddar fundido, entre pan de hamburguesa.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Para las smash burgers, precalienta la airfryer a 200°C. Aplasta bien la carne y cocina cada patty 4-5 minutos, dándole la vuelta y añadiendo el queso al final para que se funda. Tuesta los panes brevemente."},{"appliance":"horno","time":22,"difficulty":"normal","prepSummary":"Precalienta el horno a 230°C con una bandeja de hierro fundido o una bandeja de hornear boca abajo dentro. Coloca las patties aplastadas en la bandeja muy caliente y cocina 3-4 minutos por lado, añadiendo el queso al final. Tuesta los panes aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_116', 'Callos a la madrileña', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 210, 'facil', 'invierno', 480, 30, 18, 30, 4, false, true, '{"sulfitos"}', '[{"name":"Callos de ternera limpios","amount":1000,"unit":"g"},{"name":"Pata de ternera","amount":300,"unit":"g"},{"name":"Chorizo","amount":150,"unit":"g"},{"name":"Morcilla","amount":150,"unit":"g"},{"name":"Jamón","amount":80,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Pimentón dulce","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":3,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar chorizo y morcilla en rodajas gruesas y jamón en trozos pequeños. Reservar.","Picar cebolla fina y ajo fino. Reservar por separado.","Llevar a ebullición una olla grande con abundante agua. Añadir callos de ternera limpios y pata de ternera.","Escaldar los callos y la pata 5 min. Escurrir y enjuagar bajo agua fría hasta que estén limpios.","Colocar los callos y la pata en la olla limpios, cubiertos de agua fría. Añadir la mitad de la cebolla picada, laurel y vino blanco.","Cocer a fuego suave tapado, espumando de vez en cuando, hasta que los callos y la pata estén tiernos.","Calentar aceite de oliva en una cazuela a fuego medio. Sofreír la cebolla picada restante hasta que esté blanda.","Añadir el ajo picado y sofreír junto a la cebolla hasta que esté dorado, sin que se queme.","Retirar la cazuela del fuego. Añadir pimentón dulce y pimentón picante y remover rápido para que no se quemen.","Volver la cazuela al fuego suave. Añadir tomate triturado y remover para integrar con el sofrito.","Cocer el sofrito a fuego suave hasta que el tomate pierda el agua y quede concentrado.","Incorporar el chorizo, la morcilla y el jamón troceados al sofrito. Remover para integrar.","Sofreír el conjunto a fuego medio hasta que el chorizo y la morcilla suelten su grasa.","Escurrir los callos y la pata cocidos, reservando el caldo de cocción colado. Añadirlos a la cazuela.","Añadir guindilla a la cazuela junto con el laurel ya cocido recuperado del caldo.","Cubrir con el caldo de cocción colado hasta que los callos queden justos cubiertos. Remover con suavidad.","Cocer a fuego suave tapado hasta que la salsa espese y quede untuosa.","Retirar del fuego y dejar reposar tapado para que los sabores se asienten.","Servir los callos bien calientes en cazuela o plato hondo."}', 'Guiso tradicional madrileño de callos, chorizo y morcilla en una salsa untuosa de pimentón, que mejora de un día para otro.', '[{"appliance":"horno","time":270,"difficulty":"normal","prepSummary":"Tras un sofrito inicial en la cazuela, se añaden todos los ingredientes y se cocinan cubiertos en el horno precalentado a 150-160°C durante 3.5-4 horas, logrando una cocción lenta y uniforme que ablanda los callos y la pata."},{"appliance":"olla_express","time":100,"difficulty":"normal","prepSummary":"Se realiza un sofrito en la propia olla, se incorporan el resto de ingredientes con el vino y se cocinan a presión alta durante 45-60 minutos. Luego se despresuriza y se deja reducir a fuego lento unos minutos para espesar la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_117', 'Hígado encebollado', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 420, 28, 20, 24, 2, false, false, '{"gluten","sulfitos"}', '[{"name":"Hígado de ternera","amount":350,"unit":"g"},{"name":"Cebolla","amount":300,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla a fuego suave hasta que esté muy blanda y dorada.","Cortar hígado de ternera en filetes finos.","Salpimentar los filetes de hígado de ternera.","Enharinar los filetes con harina, sacudiendo el exceso.","Picar ajo fino.","Picar perejil fresco fino.","Retirar la cebolla de la sartén y reservar en un plato.","Añadir aceite de oliva a la misma sartén y subir a fuego fuerte.","Dorar el hígado de ternera enharinado 1-2 min por cada lado hasta que esté sellado.","Añadir el ajo picado y remover 30 segundos hasta que empiece a dorarse.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Incorporar la cebolla reservada y mezclar hasta que todo esté caliente.","Espolvorear con el perejil picado y servir enseguida."}', 'Lonchas de hígado de ternera doradas entre cebolla muy pochada, un clásico que se prepara en un momento.', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Pica el ajo y perejil. Sofríe la cebolla picada con aceite a 120°C/Varoma, velocidad cuchara, durante 15-20 minutos hasta que esté muy tierna. Añade el hígado enharinado, el vino y el ajo, y cocina a 100°C, giro inverso, velocidad cuchara, 5-7 minutos. Sirve con perejil fresco."},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta hasta que estén tiernos. Dora el hígado enharinado rápidamente, añade el vino y cierra la olla. Cocina 1-2 minutos desde que sube la presión. Libera la presión, rectifica la salsa y termina con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_118', 'Manitas de cerdo guisadas', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 200, 'normal', 'invierno', 420, 26, 15, 26, 4, false, true, '{"gluten","sulfitos"}', '[{"name":"Manitas de cerdo partidas por la mitad","amount":1200,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":8,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Chamuscar manitas de cerdo partidas por la mitad con un soplete o llama para eliminar los pelos restantes.","Enjuagar las manitas bajo agua fría hasta que el agua salga limpia.","Llevar a ebullición agua abundante en una olla grande e introducir las manitas.","Escaldar las manitas 5 min desde que rompa a hervir, escurrir y reservar.","Pelar y picar cebolla, zanahoria, puerro y ajo en trozos finos.","Calentar aceite de oliva en una olla grande a fuego medio.","Sofreír la cebolla, la zanahoria, el puerro y el ajo picados hasta que estén tiernos y ligeramente dorados.","Retirar la olla del fuego y añadir pimentón dulce, removiendo rápido para que no se queme.","Añadir tomate triturado y harina, mezclar bien y volver al fuego medio.","Cocer el conjunto removiendo sin parar durante 2 min hasta que la harina pierda el sabor a crudo.","Incorporar las manitas escaldadas, vino blanco y laurel; subir a fuego fuerte.","Dejar reducir el alcohol 2 min sin tapar, removiendo de vez en cuando.","Verter caldo de carne, tapar la olla y bajar a fuego suave.","Cocer a fuego suave tapado durante 150 min hasta que las manitas estén muy tiernas y la salsa untuosa.","Retirar el laurel y rectificar de sal si fuera necesario.","Reposar el guiso tapado fuera del fuego 10 min antes de servir.","Servir las manitas con abundante salsa por encima."}', 'Manitas de cerdo guisadas lentamente hasta quedar gelatinosas y untuosas, el clásico guiso de invierno de toda la vida.', '[{"appliance":"horno","time":210,"difficulty":"normal","prepSummary":"Sella las manitas y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes y cocina tapado a 160-170°C durante 3-3.5 horas, removiendo ocasionalmente para una cocción uniforme y tierna."},{"appliance":"thermomix","time":180,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras en el vaso. Incorpora las manitas selladas, el resto de ingredientes y cocina a 95°C, giro inverso, velocidad cuchara durante 180 minutos para una cocción controlada y homogénea."},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Sella las manitas y sofríe las verduras en la olla. Añade el resto de ingredientes y cocina a presión durante 45-60 minutos desde que sube la válvula, logrando una ternura perfecta en una fracción del tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_119', 'Wrap de pollo crujiente, aguacate y salsa césar', 'carnes', 'pollo', 'pan', ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 700, 34, 48, 38, 2, true, false, '{"gluten","huevo","lactosa","pescado","mostaza"}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Tortillas de trigo grandes","amount":2,"unit":"ud"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Lechuga","amount":60,"unit":"g"},{"name":"Tomate","amount":60,"unit":"g"},{"name":"Yogur natural","amount":40,"unit":"g"},{"name":"Parmesano rallado","amount":15,"unit":"g"},{"name":"Anchoas en aceite","amount":8,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de unos 2 cm de grosor y salpimentar.","Batir huevo en un bol.","Pasar cada tira de pollo por harina, luego por el huevo batido y finalmente por pan rallado, presionando para que el rebozado se adhiera bien.","Calentar aceite de girasol en sartén a fuego fuerte hasta que alcance unos 175 °C.","Freír las tiras de pollo rebozadas hasta que estén doradas y crujientes por fuera y cocidas por dentro.","Escurrir el pollo frito sobre papel absorbente y reservar.","Triturar yogur natural, parmesano rallado, anchoas en aceite, ajo, zumo de limón y mostaza de dijon hasta obtener una salsa homogénea.","Laminar aguacate, cortar lechuga en juliana y cortar tomate en dados.","Calentar tortillas de trigo grandes en sartén a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir la lechuga, el tomate y el aguacate sobre cada tortilla.","Colocar las tiras de pollo crujiente sobre las verduras y salsear con la salsa césar.","Enrollar cada tortilla bien apretada formando un wrap y cortar por la mitad en diagonal para servir."}', 'Tortilla rellena de pollo crujiente, aguacate fresco y una cremosa salsa césar casera, lista en dos minutos de montaje.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Para el pollo crujiente, precalienta la airfryer a 190-200°C. Rocía el pollo empanado con un poco de aceite y cocina durante 15-20 minutos, dándole la vuelta a mitad, hasta que esté dorado y crujiente. Prepara la salsa mezclando el resto de ingredientes."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Para el pollo crujiente, precalienta el horno a 200-220°C con calor arriba y abajo. Coloca el pollo empanado en una bandeja con papel de horno, rocía con un poco de aceite y hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente. La salsa se prepara me"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_120', 'Quesadillas de queso y jamón con guacamole', 'carnes', 'cerdo', 'pan', ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 600, 26, 42, 36, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortillas de trigo grandes","amount":4,"unit":"ud"},{"name":"Queso rallado","amount":160,"unit":"g"},{"name":"Jamón cocido","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":20,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar cebolla morada en dados muy finos.","Cortar tomate en dados pequeños.","Picar cilantro fresco fino.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa a un bol.","Machacar la pulpa del aguacate con un tenedor hasta obtener una pasta con textura.","Añadir la cebolla morada picada, el tomate en dados, el cilantro picado y zumo de lima al aguacate machacado.","Mezclar bien hasta integrar y reservar el guacamole.","Extender queso rallado y jamón cocido sobre la mitad de cada tortillas de trigo grandes.","Doblar cada tortilla por la mitad para cerrar la quesadilla.","Calentar aceite de oliva en plancha a fuego medio.","Colocar las quesadillas en la plancha y cocinar 2-3 min por cada lado hasta que estén doradas y el queso fundido.","Cortar cada quesadilla en triángulos.","Servir las quesadillas calientes acompañadas del guacamole."}', 'Quesadillas de queso fundido y jamón, doradas en la plancha, servidas con guacamole fresco.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rellena las tortillas, dóblalas y cocina de 6 a 8 minutos por tanda, dándoles la vuelta a mitad, hasta que estén doradas y el queso fundido. Quedarán crujientes y deliciosas."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca las quesadillas rellenas en una bandeja con papel de horno y hornea durante 8-10 minutos, hasta que el queso se derrita y las tortillas estén doradas y crujientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_121', 'Bowl de quinoa, pollo y verduras crudas', 'carnes', 'pollo', 'quinoa', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 560, 40, 50, 23, 2, true, true, '{}', '[{"name":"Quinoa","amount":120,"unit":"g"},{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Enjuagar quinoa bajo agua fría hasta que el agua salga clara.","Llevar a ebullición una olla con agua y sal, añadir la quinoa y cocer a fuego medio.","Cocer la quinoa tapada a fuego suave hasta que esté tierna y haya absorbido el agua.","Escurrir la quinoa si ha quedado agua y extenderla en un bol para que temple.","Pelar zanahoria y cortarla en bastones finos.","Cortar pepino en medias lunas y tomate cherry por la mitad.","Cortar aguacate en láminas.","Exprimir limón y rociar las láminas de aguacate con unas gotas de zumo para que no se oxiden.","Calentar plancha a fuego fuerte con aceite de oliva.","Colocar pechuga de pollo entera en la plancha y cocinar 5 min por el primer lado hasta que se dore.","Dar la vuelta a la pechuga de pollo y cocinar 4 min más hasta que esté cocida por dentro.","Retirar la pechuga de pollo de la plancha y dejar reposar 3 min antes de cortarla.","Cortar la pechuga de pollo en tiras.","Repartir la quinoa en la base de 2 boles.","Disponer encima las tiras de pollo, la zanahoria, el pepino, el tomate cherry y el aguacate en montones separados.","Aliñar con el resto del zumo de limón y aceite de oliva al gusto justo antes de servir."}', 'Bowl fresco de quinoa con pollo a la plancha y verduras crudas variadas, listo en poco más de veinte minutos.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Cocina la pechuga de pollo a 190°C durante 15-18 minutos, volteándola a mitad para un dorado uniforme. La quinoa se puede cocer en un recipiente apto con agua en la misma airfryer o de forma tradicional."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo a 190°C durante 20-25 minutos hasta que esté bien cocida. La quinoa se puede preparar en una olla apta para horno con agua o en una olla convencional."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina la quinoa en el cestillo (15-20 min/Varoma/vel 1) y el pollo troceado al vapor en el Varoma simultáneamente para una cocción eficiente y jugosa."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cuece la quinoa y la pechuga de pollo (entera o troceada) al vapor simultáneamente durante 15-20 minutos. El pollo quedará muy jugoso y saludable."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa y el pollo troceado en la olla express con un poco de agua durante 5-7 minutos a partir de que suba la válvula para una cocción ultrarrápida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_122', 'Sándwich club de pollo, bacon y huevo', 'carnes', 'pollo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 650, 46, 38, 32, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan de molde","amount":6,"unit":"ud"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Bacon en lonchas","amount":70,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Salpimentar pechuga de pollo por ambas caras.","Calentar plancha a fuego fuerte con aceite de oliva.","Cocinar la pechuga de pollo 4 min por cada lado hasta que esté dorada y cocinada por dentro.","Lavar y secar lechuga y reservar.","Cortar tomate en rodajas finas y reservar.","Retirar la pechuga de pollo de la plancha y dejar templar 2 min.","Cortar la pechuga de pollo en filetes finos y reservar.","Dorar bacon en lonchas en la misma plancha a fuego fuerte 2 min por cada lado hasta que estén crujientes.","Retirar el bacon de la plancha y reservar sobre papel absorbente.","Cocinar huevo en la misma plancha a fuego medio hasta que la clara esté cuajada y la yema al punto.","Retirar los huevos de la plancha y reservar.","Tostar pan de molde en la misma plancha a fuego medio hasta que estén doradas y crujientes.","Untar una cara de cada tostada con mayonesa.","Montar el primer piso: colocar una tostada, disponer la lechuga, las rodajas de tomate y los filetes de pollo.","Cubrir con una segunda tostada con la cara de mayonesa hacia abajo.","Añadir encima el bacon crujiente y los huevos fritos.","Cerrar con la tercera tostada, sujetar con palillos y cortar en triángulos para servir."}', 'Sándwich de tres pisos con pollo a la plancha, bacon crujiente, huevo y mayonesa, sujeto con palillos.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina las lonchas de pollo y el bacon en la airfryer a 190°C hasta que estén dorados y crujientes. Tuesta el pan y cocina los huevos en un ramekin apto para airfryer a 180°C para un resultado tipo frito."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C y hornea el pollo y el bacon en una bandeja hasta que estén cocidos y crujientes. Tuesta el pan y hornea los huevos en la misma bandeja o en ramequines para un efecto de huevo frito."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_123', 'Ensalada César exprés con pollo de bolsa', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 480, 34, 18, 30, 2, false, false, '{"gluten","lactosa","huevo","pescado","mostaza"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pollo asado de bolsa","amount":200,"unit":"g"},{"name":"Pan de molde","amount":60,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Salsa César","amount":60,"unit":"g"},{"name":"Anchoas en aceite","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de molde en dados de 1 cm aproximadamente.","Calentar sartén a fuego medio con aceite de oliva.","Tostar los dados de pan de molde en la sartén hasta que estén dorados y crujientes.","Retirar los picatostes de la sartén y reservar.","Lavar y secar lechuga romana, luego trocearla en tiras de tamaño de bocado.","Desmenuzar pollo asado de bolsa en tiras con las manos.","Picar anchoas en aceite en trozos pequeños.","Rallar queso parmesano en lascas finas con un pelador o rallador.","Disponer la lechuga en un bol grande y aliñar con salsa césar, mezclando bien hasta que quede repartida.","Añadir el pollo desmenuzado y las anchoas picadas al bol y mezclar de nuevo.","Repartir los picatostes y el queso parmesano rallado por encima de la ensalada.","Servir inmediatamente para que los picatostes conserven el punto crujiente."}', 'Ensalada César exprés con pollo de bolsa, picatostes caseros y aliño clásico, lista en diez minutos.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Para los picatostes, corta el pan en dados, rocía con aceite y cocínalos en la airfryer a 180°C durante 5-7 minutos. Añade el pollo de bolsa troceado los últimos 3-5 minutos para calentarlo y dorarlo ligeramente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Corta el pan en dados, rocía con aceite y hornea 8-10 minutos hasta dorar. El pollo troceado se puede calentar o dorar ligeramente junto a los picatostes durante los últimos 5-7 minutos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_124', 'Tacos de pollo rápidos con pico de gallo', 'carnes', 'pollo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 34, 40, 20, 2, true, false, '{"gluten"}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Tortillas de trigo","amount":6,"unit":"ud"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas de unos 1 cm.","Salpimentar el pollo con comino molido, pimentón dulce y sal; mezclar bien.","Picar tomate en dados pequeños.","Picar cebolla morada en dados pequeños.","Picar cilantro fresco fino.","Exprimir lima y reservar el zumo.","Mezclar el tomate, la cebolla morada y el cilantro con la mitad del zumo de lima y sal.","Reservar el pico de gallo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear las tiras de pollo 5 min, removiendo, hasta que estén doradas y cocidas por dentro.","Calentar tortillas de trigo en sartén limpia, 20 segundos por cada lado, hasta que estén flexibles.","Rellenar cada tortilla con el pollo salteado y una cucharada generosa de pico de gallo.","Añadir el zumo de lima restante por encima y servir de inmediato."}', 'Tacos rápidos de pollo especiado con pico de gallo fresco de tomate, cebolla morada y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas con las especias en la airfryer a 190°C durante 15-18 minutos, dándoles la vuelta a mitad para un dorado uniforme y un interior jugoso. Calienta las tortillas brevemente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Asa las pechugas de pollo sazonadas en el horno precalentado a 200°C durante 20-22 minutos, hasta que estén bien cocidas y ligeramente doradas. Las tortillas se pueden calentar en el mismo horno al final."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Prepara el pico de gallo picando los ingredientes en el vaso. Luego, cocina las pechugas de pollo sazonadas al vapor en el Varoma durante 15-18 minutos, para obtener un pollo tierno y fácil de desmenuzar."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas en la vaporera durante unos 20 minutos hasta que estén tiernas y cocidas, ideales para desmenuzar. Mientras, prepara el pico de gallo."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las pechugas de pollo sazonadas en la olla express con un poco de agua o caldo durante 5-7 minutos desde que sube la presión, para un pollo muy tierno y rápido de desmenuzar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_125', 'Tosta de sobrasada y miel con queso', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 520, 20, 40, 30, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan rústico","amount":4,"unit":"ud"},{"name":"Sobrasada","amount":150,"unit":"g"},{"name":"Queso semicurado en lonchas","amount":80,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"}]'::jsonb, '{"Tostar pan rústico bajo el grill del horno hasta que estén doradas y crujientes.","Retirar el pan del horno y extender sobrasada sobre cada tosta mientras aún están calientes.","Colocar queso semicurado en lonchas sobre la sobrasada, cubriendo bien la superficie.","Gratinar las tostas bajo el grill hasta que el queso empiece a fundirse.","Retirar las tostas del horno y rociar miel sobre cada una.","Servir inmediatamente mientras el queso está fundente."}', 'Tostas crujientes de sobrasada con queso fundido y un toque dulce de miel.', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Coloca el pan con la sobrasada y el queso en la airfryer precalentada a 190°C. Cocina durante 6-8 minutos, o hasta que el pan esté crujiente y el queso fundido y burbujeante. Añade la miel al servir."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Dispón las tostas con la sobrasada y el queso en una bandeja y hornea durante 8-10 minutos, hasta que el pan dore y el queso se funda. Termina con un chorrito de miel."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_126', 'Sándwich de pastrami y mostaza', 'carnes', 'ternera', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 560, 36, 42, 26, 2, true, false, '{"gluten","mostaza","lactosa"}', '[{"name":"Pan de centeno","amount":4,"unit":"ud"},{"name":"Pastrami de ternera en lonchas","amount":200,"unit":"g"},{"name":"Mostaza a la antigua","amount":30,"unit":"g"},{"name":"Pepinillos encurtidos","amount":40,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"}]'::jsonb, '{"Laminar pepinillos encurtidos en rodajas finas.","Untar mantequilla por una cara de 2 rebanadas de pan de centeno.","Untar mostaza a la antigua por una cara de las otras 2 rebanadas de pan de centeno.","Calentar sartén a fuego medio sin aceite hasta que esté bien caliente.","Tostar las rebanadas con mantequilla por la cara untada hasta que se doren.","Calentar pastrami de ternera en lonchas en la misma sartén hasta que estén templadas.","Montar cada sándwich con el pastrami templado y los pepinillos laminados entre las rebanadas.","Cortar cada sándwich por la mitad en diagonal y servir templado."}', 'Sándwich de pastrami templado con mostaza a la antigua y pepinillos encurtidos.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Unta el pan con mantequilla, monta el sándwich y cocínalo en la airfryer precalentada a 180-190°C durante 6-8 minutos, dándole la vuelta a mitad, hasta que esté dorado y el pastrami caliente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C (o usa la función grill). Unta el pan con mantequilla, monta el sándwich y hornea durante 8-12 minutos, vigilando que el pan quede crujiente y el pastrami bien caliente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_127', 'Ensalada de pollo asado de bolsa con nueces y queso', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 460, 32, 14, 30, 2, true, false, '{"frutos_secos","lactosa","sulfitos"}', '[{"name":"Mezcla de hojas verdes","amount":150,"unit":"g"},{"name":"Pollo asado de bolsa","amount":200,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Queso parmesano en virutas","amount":50,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar mezcla de hojas verdes bajo agua fría y escurrir bien en un colador.","Cortar tomate cherry por la mitad.","Desmenuzar pollo asado de bolsa en tiras con las manos.","Picar nueces groseramente con un cuchillo.","Repartir la mezcla de hojas verdes en 2 platos o boles.","Añadir el pollo desmenuzado, las nueces picadas y los tomates cherry sobre las hojas.","Distribuir queso parmesano en virutas por encima.","Aliñar con aceite de oliva, vinagre balsámico y sal justo antes de servir."}', 'Ensalada rápida con pollo asado de bolsa, nueces crujientes y queso, lista en diez minutos.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Para darle un toque crujiente y templado al pollo asado, caliéntalo en la airfryer a 180°C durante 5-7 minutos. Desmenúzalo y mézclalo con los demás ingredientes."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Si buscas un pollo más crujiente y templado, hornéalo a 180°C durante 10-12 minutos. Luego, desmenúzalo y úsalo en la ensalada para un contraste de texturas."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_128', 'Tosta de paté, higos y rúcula', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 420, 14, 38, 24, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Pan rústico","amount":4,"unit":"ud"},{"name":"Paté de cerdo","amount":120,"unit":"g"},{"name":"Higos frescos","amount":3,"unit":"ud"},{"name":"Rúcula","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar higos frescos bajo el grifo y secarlos con papel de cocina.","Laminar los higos frescos en rodajas finas de unos 3-4 mm.","Tostar pan rústico en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","Untar paté de cerdo en capa generosa sobre cada rebanada tostada.","Repartir las láminas de higo sobre el paté de cada tosta.","Colocar rúcula sobre cada tosta.","Terminar con aceite de oliva por encima y servir de inmediato."}', 'Tostas de paté con higos frescos laminados y rúcula, un contraste dulce y amargo muy rápido de montar.', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Para tostar el pan, precalienta la airfryer a 190°C y cocina las rebanadas durante 4-6 minutos, volteándolas a mitad, hasta que estén crujientes. Luego, unta el paté y decora con higos y rúcula."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Tuesta las rebanadas de pan rústico directamente sobre la rejilla durante 5-7 minutos hasta que estén doradas. Monta la tosta con el paté, los higos y la rúcula."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('carnes_129', 'Croque monsieur rápido', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 20, 'facil', 'all', 540, 28, 34, 32, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Jamón cocido en lonchas","amount":120,"unit":"g"},{"name":"Queso emmental en lonchas","amount":80,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego medio hasta que esté líquida.","Añadir harina de golpe y remover sin parar durante 1 min hasta que la mezcla forme una pasta homogénea.","Verter leche poco a poco sin dejar de remover hasta que no queden grumos.","Cocer a fuego medio sin dejar de remover hasta que la bechamel espese, unos 3 min.","Añadir nuez moscada y remover para integrar. Retirar el cazo del fuego y reservar.","Precalentar el horno con grill a 220 °C.","Extender una capa fina de bechamel sobre 2 rebanadas de pan de molde.","Repartir jamón cocido en lonchas sobre las 2 rebanadas untadas con bechamel.","Colocar queso emmental en lonchas sobre el jamón, reservando 2 lonchas para la cobertura.","Cerrar cada sándwich con las 2 rebanadas de pan de molde restantes.","Cubrir la parte superior de cada sándwich con el resto de la bechamel.","Repartir las lonchas de queso emmental reservadas por encima de la bechamel.","Hornear los sándwiches bajo el grill a 220 °C hasta que el queso esté dorado y burbujeante, unos 7 min.","Retirar del horno y dejar templar 2 min antes de servir.","Servir los sándwiches en el plato, con el queso gratinado hacia arriba."}', 'Sándwich de jamón y queso gratinado con bechamel casera, listo en el tiempo que tarda el horno.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Prepara la bechamel en un cazo. Monta los sándwiches con jamón, queso y bechamel, y hornea a 180-200°C durante 15-20 minutos hasta que estén dorados y el queso fundido."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Prepara la bechamel por separado. Monta los sándwiches y cocínalos en la airfryer a 180°C durante 10-12 minutos, dándoles la vuelta a mitad, hasta que estén crujientes y el queso derretido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_130', 'Tortilla francesa de pavo y queso con ensalada de aguacate, tomate cherry y queso de cabra', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 430, 28, 12, 30, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Pechuga de pavo en lonchas","amount":80,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Queso de cabra","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados y tomate cherry por la mitad.","Desmenuzar queso de cabra sobre los dados de aguacate y los tomates cherry.","Aliñar la ensalada con aceite de oliva, vinagre de jerez y sal.","Batir huevo en un bol con sal al gusto hasta que estén homogéneos.","Calentar sartén con aceite de oliva a fuego medio.","Verter el huevo batido y repartirlo por toda la sartén formando una capa fina.","Colocar pechuga de pavo en lonchas y queso rallado sobre una mitad cuando la base empiece a cuajar.","Doblar la tortilla por la mitad y cocer 2 min hasta que el queso se funda.","Servir la tortilla acompañada de la ensalada de aguacate, tomate cherry y queso de cabra."}', 'Tortilla francesa rellena de pavo y queso fundido, con una ensalada fresca de aguacate, tomate cherry y queso de cabra.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para la tortilla, bate los huevos con el pavo y el queso rallado. Vierte la mezcla en un molde apto para airfryer y cocina a 180°C durante 10-12 minutos hasta que esté cuajada y ligeramente dorada. La ensalada se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Bate los huevos con el pavo y el queso rallado, vierte la mezcla en un molde apto para horno y hornea durante 12-15 minutos hasta que esté cuajada y ligeramente dorada. La ensalada se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_131', 'Pechuga de pollo a la plancha con ensalada de aguacate, maíz y lima', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 480, 40, 24, 24, 2, true, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Maíz dulce cocido","amount":100,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en filetes de grosor uniforme.","Salpimentar los filetes por ambos lados con sal y pimienta negra.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Cocinar los filetes 5 min por el primer lado sin moverlos, hasta que se doren.","Dar la vuelta a los filetes y cocinar 5 min más hasta que estén bien hechos por dentro.","Cortar aguacate en dados.","Exprimir lima y reservar el zumo.","Picar cilantro fresco fino.","Mezclar el aguacate en dados con maíz dulce cocido, el cilantro picado y la mitad del zumo de lima.","Aliñar la ensalada con el resto del zumo de lima, un chorrito de aceite de oliva y sal al gusto.","Retirar los filetes de la plancha y dejar reposar 3 min.","Servir los filetes de pollo junto a la ensalada de aguacate y maíz."}', 'Pechuga de pollo a la plancha con una ensalada fresca de aguacate, maíz dulce y un toque ácido de lima.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Sazona la pechuga, rocíala con un poco de aceite y cocina unos 15-18 minutos, dándole la vuelta a mitad, para un exterior dorado y jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Sazona la pechuga, rocíala con un poco de aceite y hornea durante 20-25 minutos hasta que esté bien cocida y ligeramente dorada, asegurando que no se seque."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_132', 'Lomo a la plancha con ensalada de aguacate, tomate cherry y queso feta', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 36, 12, 34, 2, true, false, '{"lactosa"}', '[{"name":"Lomo de cerdo en filetes","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados medianos y tomate cherry por la mitad.","Desmenuzar queso feta sobre el aguacate y el tomate cherry.","Aliñar la ensalada con aceite de oliva, orégano seco y sal.","Salpimentar lomo de cerdo en filetes por ambas caras.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Colocar los filetes en la plancha y cocinar 3 min por cada lado hasta que estén dorados.","Retirar los filetes de la plancha y dejar reposar 2 min.","Servir el lomo junto con la ensalada de aguacate, tomate cherry y queso feta."}', 'Lomo de cerdo a la plancha con una ensalada fresca de aguacate, tomate cherry y queso feta.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina los filetes de lomo sazonados y ligeramente aceitados durante 10-12 minutos, volteándolos a mitad para un dorado uniforme y un interior jugoso."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (preferiblemente con función grill o ventilador). Coloca los filetes de lomo sazonados y aceitados en una bandeja y hornea durante 15-20 minutos, volteándolos una vez, hasta que estén dorados y cocidos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_133', 'Pollo a la plancha con especias cajún y ensalada de aguacate, maíz y cilantro', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 40, 22, 22, 2, false, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Especias cajún","amount":8,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Maíz dulce cocido","amount":100,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en filetes uniformes de unos 2 cm de grosor.","Salpimentar los filetes con especias cajún y sal por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Cocinar los filetes en plancha 5 min por el primer lado sin moverlos, hasta que se doren.","Cortar aguacate en dados de unos 2 cm.","Picar cilantro fresco fino.","Dar la vuelta a los filetes y cocinar 5 min más hasta que estén hechos por dentro.","Exprimir lima y reservar el zumo.","Mezclar el aguacate en dados con maíz dulce cocido y el cilantro picado en un bol.","Aliñar la ensalada con el zumo de lima, aceite de oliva y sal al gusto.","Retirar los filetes de la plancha y reposar 3 min antes de cortar.","Cortar los filetes en tiras.","Servir las tiras de pollo junto a la ensalada de aguacate, maíz y cilantro."}', 'Pollo a la plancha con especias cajún y una ensalada refrescante de aguacate, maíz y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Marinar el pollo con las especias y aceite. Cocinar en la airfryer precalentada a 190°C durante 15-18 minutos, volteando a mitad, para un exterior dorado y un interior jugoso. La ensalada se prepara aparte."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Marinar el pollo con las especias y aceite. Hornear en el horno precalentado a 200°C durante 20-25 minutos, hasta que esté bien cocido y ligeramente dorado. La ensalada se prepara en frío."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_134', 'Filete de pavo a la plancha con ensalada de aguacate, tomate y mostaza a la antigua', 'carnes', 'pavo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 420, 38, 14, 22, 2, true, false, '{"mostaza","sulfitos"}', '[{"name":"Filete de pavo","amount":350,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Mostaza a la antigua","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar aguacate en láminas y tomate en gajos.","Mezclar mostaza a la antigua, aceite de oliva, vinagre de vino y sal en un bol hasta integrar.","Salpimentar filete de pavo por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte.","Cocinar el filete de pavo 3 min por cada lado hasta que esté dorado y bien hecho por dentro.","Disponer las láminas de aguacate y los gajos de tomate en el plato.","Aliñar la ensalada con la vinagreta de mostaza.","Servir el filete de pavo junto a la ensalada aliñada."}', 'Filete de pavo a la plancha con una ensalada de aguacate y tomate aliñada con mostaza a la antigua.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Cocina el filete de pavo durante 12-15 minutos, dándole la vuelta a mitad, hasta que esté dorado y jugoso."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C, preferiblemente con función grill. Coloca el filete en una bandeja y cocina 15-20 minutos, volteándolo una vez, hasta que esté hecho y ligeramente dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_135', 'Bowl mexicano de pollo, arroz y frijoles', 'carnes', 'pollo', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 620, 40, 68, 20, 2, true, true, '{}', '[{"name":"Pechuga de pollo","amount":300,"unit":"g"},{"name":"Arroz blanco","amount":150,"unit":"g"},{"name":"Frijoles negros cocidos","amount":200,"unit":"g"},{"name":"Maíz dulce cocido","amount":80,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo y cocer arroz blanco según el tiempo del envase.","Cortar pechuga de pollo en dados de tamaño uniforme.","Sazonar los dados de pechuga de pollo con comino molido, pimentón dulce y sal.","Picar tomate y cebolla morada en dados pequeños y reservar.","Escurrir el arroz blanco cocido y reservar caliente.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear los dados de pechuga de pollo hasta que estén dorados por fuera y cocidos por dentro.","Calentar frijoles negros cocidos en un cazo a fuego medio hasta que estén calientes.","Repartir el arroz blanco en la base de 2 boles.","Disponer encima el pollo salteado, los frijoles negros y maíz dulce cocido en montones separados.","Añadir el tomate y la cebolla morada picados sobre el resto de ingredientes del bol.","Exprimir lima sobre cada bol y servir de inmediato."}', 'Bowl mexicano completo con pollo especiado, arroz, frijoles negros y maíz, listo en boles individuales.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta el pollo en dados, sazona y cocina en la airfryer a 190°C durante 15-18 minutos, volteando a mitad, hasta que esté dorado y cocido."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo sazonada a 200°C durante 20-25 minutos hasta que esté bien cocida y ligeramente dorada."},{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Cocina el arroz en el vaso y el pollo en el Varoma (o sofríe en el vaso) para integrar todos los ingredientes de forma eficiente."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz y la pechuga de pollo troceada al vapor durante 20-25 minutos hasta que estén tiernos y jugosos."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina el arroz y la pechuga de pollo en la olla express por separado durante unos 5-7 minutos desde que sube la presión para una cocción rápida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_136', 'Vol-au-vent de setas y foie', 'carnes', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'elaborada', 'invierno', 480, 12, 28, 36, 2, false, false, '{"gluten","lactosa","sulfitos"}', '[{"name":"Vol-au-vent de hojaldre","amount":4,"unit":"ud"},{"name":"Foie fresco o mi-cuit","amount":100,"unit":"g"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino oloroso","amount":30,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Picar cebolla fino.","Limpiar setas variadas y cortar en trozos medianos.","Fundir mantequilla en sartén a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté transparente.","Añadir las setas troceadas y saltear a fuego medio hasta que suelten el agua y se doren ligeramente.","Verter vino oloroso y remover hasta que reduzca.","Añadir nata para cocinar y remover a fuego suave hasta que la salsa espese ligeramente.","Salpimentar con sal y pimienta negra.","Retirar la sartén del fuego.","Cortar foie fresco o mi-cuit en dados de unos 2 cm.","Añadir los dados de foie a la sartén fuera del fuego y remover con suavidad hasta que se funda parcialmente.","Calentar vol-au-vent de hojaldre en el horno a 180 °C durante 5 min.","Rellenar los vol-au-vent calientes con la mezcla de setas y foie.","Servir de inmediato para conservar el hojaldre crujiente."}', 'Vol-au-vent de hojaldre relleno de una cremosa mezcla de setas salteadas y foie, listo para una ocasión especial.', '[{"appliance":"horno","time":40,"difficulty":"elaborada","prepSummary":"Prepara el sofrito de cebolla y setas en una sartén. Sella el foie y desglasa con vino, luego añade la nata. Rellena los vol-au-vents y hornea a 180°C durante 15-20 minutos hasta que estén dorados y el relleno caliente."},{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Prepara el relleno de setas, foie y nata en una sartén. Calienta los vol-au-vents vacíos en la airfryer a 180°C durante 5-7 minutos hasta que estén crujientes. Rellénalos y calienta todo junto 3-5 minutos más para servir."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y las setas en el vaso. Añade el vino, la nata y el foie mi-cuit (o fresco sellado aparte), cocina a 90°C, velocidad cuchara hasta obtener una crema. Rellena los vol-au-vents previamente horneados para mantener su textura crujiente."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('carnes_137', 'Croquetas de pollo asado', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 75, 'normal', 'all', 420, 22, 32, 22, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Pollo asado desmenuzado","amount":300,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Desmenuzar pollo asado desmenuzado en trozos pequeños.","Fundir mantequilla en una cazuela a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté transparente.","Añadir harina y remover sin parar a fuego medio hasta que se tueste, unos 2 min.","Verter leche poco a poco sin dejar de remover hasta que no quede ningún grumo.","Añadir el pollo desmenuzado, sal y nuez moscada; remover para integrar.","Cocer la masa a fuego suave, removiendo con frecuencia, hasta que se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","Refrigerar la masa en la nevera hasta que esté completamente fría y firme.","Batir huevo en un bol hondo.","Extender pan rallado en un plato llano.","Formar las croquetas con las manos, dándoles forma alargada y uniforme.","Pasar cada croqueta por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","Calentar aceite de oliva en una sartén honda hasta alcanzar 180 °C.","Freír las croquetas en tandas hasta que estén doradas por fuera, unos 2-3 min por tanda.","Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas calientes."}', 'Croquetas cremosas hechas con restos de pollo asado, bechamel casera y un rebozado crujiente.', '[{"appliance":"airfryer","time":75,"difficulty":"normal","prepSummary":"Prepara la bechamel de forma tradicional. Una vez formadas y empanadas las croquetas, rocíalas ligeramente con aceite y cocínalas en la airfryer a 190-200°C durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén doradas y crujientes."},{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Tras preparar la bechamel y empanar las croquetas, colócalas en una bandeja de horno con papel y rocía con un poco de aceite. Hornea a 200°C (con ventilador si es posible) durante 20-25 minutos, volteándolas a mitad, hasta que estén doradas."},{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para preparar la bechamel: pica la cebolla, sofríela con la mantequilla y luego añade la harina, leche, pollo y especias, cocinando a temperatura y velocidad controladas hasta obtener una masa perfecta. Luego, forma y fríe las croquetas de manera tradicional."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_138', 'Croquetas de cocido de la abuela', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 75, 'normal', 'all', 410, 20, 32, 22, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Carne de cocido desmenuzada","amount":300,"unit":"g"},{"name":"Caldo de cocido","amount":500,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Desmenuzar carne de cocido desmenuzada con las manos hasta obtener hebras muy finas.","Fundir mantequilla en una cazuela a fuego suave hasta que se derrita por completo.","Añadir harina de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla forme una pasta dorada.","Verter caldo de cocido poco a poco sin dejar de remover con la varilla para evitar grumos.","Añadir leche poco a poco, alternando con el caldo, sin parar de remover hasta integrar todo.","Incorporar la carne desmenuzada, sal y nuez moscada; remover bien para integrar.","Cocer la masa a fuego suave sin dejar de remover hasta que se despegue de las paredes de la cazuela.","Extender la masa en una fuente y cubrir con film a piel para que no forme costra.","Enfriar la fuente en la nevera hasta que la masa esté completamente fría y firme.","Batir huevo en un bol hondo hasta que la yema y la clara estén bien integradas.","Poner pan rallado en un plato llano y disponer el bol con el huevo batido al lado.","Tomar porciones de masa fría y dar forma alargada con las manos hasta formar cada croqueta.","Pasar cada croqueta primero por el huevo batido y después por el pan rallado, cubriendo bien toda la superficie.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas en tandas pequeñas durante 2-3 min hasta que estén doradas por todos los lados.","Escurrir las croquetas fritas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas recién fritas y bien calientes."}', 'Croquetas hechas con los restos del cocido de la abuela, cremosas por dentro y crujientes por fuera.', '[{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"La Thermomix es ideal para la masa de las croquetas. Sofríe la mantequilla y harina, añade líquidos y carne, y cocina a 90°C, velocidad 4, durante 8-10 minutos, obteniendo una bechamel perfecta y sin grumos. El resto del proceso (enfriar, formar y freír) se mantiene igual."},{"appliance":"airfryer","time":80,"difficulty":"normal","prepSummary":"Para un acabado crujiente y más saludable, precalienta la airfryer a 190°C. Rocía ligeramente las croquetas ya empanadas con aceite y cocina durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén doradas y crujientes. La masa se prepara de forma tradicional."},{"appliance":"horno","time":85,"difficulty":"normal","prepSummary":"Para una versión horneada, precalienta el horno a 200°C. Coloca las croquetas empanadas en una bandeja con papel de horno y un chorrito de aceite. Hornea durante 20-25 minutos, volteando a mitad, hasta que estén doradas y cocidas por dentro. La masa se prepara de forma tradiciona"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_139', 'Empanadillas de morcilla y piñones', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 430, 14, 34, 28, 4, false, false, '{"gluten","frutos_secos"}', '[{"name":"Obleas de empanadilla","amount":16,"unit":"ud"},{"name":"Morcilla","amount":250,"unit":"g"},{"name":"Piñones","amount":40,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"}]'::jsonb, '{"Picar cebolla en brunoise fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Retirar la piel de morcilla y desmenuzar la carne directamente en la sartén.","Añadir piñones y mezclar con la morcilla a fuego medio.","Cocinar el relleno hasta que la morcilla esté integrada y ligeramente crujiente.","Retirar la sartén del fuego y dejar templar el relleno.","Extender obleas de empanadilla sobre una superficie limpia.","Colocar una cucharada del relleno en el centro de cada oblea.","Humedecer los bordes de cada oblea con un poco de agua.","Doblar cada oblea por la mitad y sellar los bordes presionando con un tenedor.","Calentar aceite de oliva en sartén hasta alcanzar 180 °C.","Freír las empanadillas en tandas hasta que estén doradas por un lado.","Dar la vuelta a las empanadillas y freír hasta que estén doradas por el otro lado.","Escurrir las empanadillas sobre papel absorbente y servir calientes."}', 'Empanadillas fritas y crujientes rellenas de morcilla y piñones, con la sorpresa oscura del relleno al morderlas.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Prepara el relleno sofriendo la cebolla y la morcilla, luego rellena las obleas. Cocina las empanadillas en la airfryer a 190°C durante 12-15 minutos, volteándolas a mitad, hasta que estén doradas y crujientes con muy poco aceite."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Elabora el relleno sofriendo la cebolla y la morcilla. Rellena las obleas, séllalas y hornea a 200°C durante 15-20 minutos, pincelándolas con huevo batido o un poco de aceite para un acabado dorado y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_140', 'Tarta de puerros y bacon', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 480, 18, 30, 32, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Masa quebrada","amount":1,"unit":"ud"},{"name":"Puerro","amount":400,"unit":"g"},{"name":"Bacon en dados","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Lavar puerro y cortar en rodajas finas.","Forrar un molde de tarta con masa quebrada y pinchar la base con un tenedor.","Hornear la base en blanco a 190 °C durante 10 min.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír bacon en dados en la sartén 4 min hasta que empiece a dorarse.","Añadir el puerro cortado y sofreír a fuego medio 10 min hasta que esté blando.","Retirar la sartén del fuego y reservar el sofrito para que temple.","Batir huevo con nata para cocinar en un bol hasta integrar.","Añadir sal, pimienta negra y nuez moscada al bol y mezclar.","Repartir el sofrito de puerro y bacon sobre la base precocida de forma uniforme.","Verter la mezcla de huevo y nata sobre el relleno con cuidado.","Espolvorear queso rallado de forma uniforme sobre la superficie.","Hornear a 180 °C durante 30 min hasta que la tarta esté cuajada y dorada.","Retirar del horno y dejar templar 5 min antes de desmoldar.","Cortar en porciones y servir."}', 'Tarta salada de puerros pochados y bacon crujiente sobre una base de masa quebrada, cuajada al horno.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Prepara el relleno salteando puerros y bacon, luego mézclalo con los huevos, nata y queso. Vierte sobre la masa quebrada en un molde y hornea a 180-200°C durante 40-50 minutos hasta que esté dorada y cuajada."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Saltea los puerros y el bacon por separado. Monta la tarta en un molde apto para airfryer. Cocina a 160-170°C durante 35-45 minutos, vigilando que no se dore demasiado rápido, hasta que el relleno esté cuajado y la masa dorada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_141', 'Pastel de patata y carne (shepherd''s pie casero)', 'carnes', 'ternera', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 520, 28, 40, 26, 4, true, true, '{"lactosa"}', '[{"name":"Patata","amount":800,"unit":"g"},{"name":"Carne picada de ternera","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Caldo de carne","amount":150,"unit":"ml"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomate concentrado","amount":20,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos grandes.","Cocer las patatas en una olla con agua y sal hasta que estén tiernas.","Picar cebolla en dados pequeños.","Cortar zanahoria en dados pequeños.","Precalentar el horno a 200 °C.","Escurrir las patatas cocidas y volcarlas en un bol grande.","Añadir mantequilla y leche a las patatas escurridas.","Triturar las patatas con la mantequilla y la leche hasta obtener un puré suave.","Salpimentar el puré con pimienta negra y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y la zanahoria picadas hasta que estén blandas.","Añadir carne picada de ternera y deshacer los grumos con una cuchara.","Dorar la carne a fuego medio-fuerte hasta que esté bien dorada.","Añadir guisantes, caldo de carne y tomate concentrado; remover para integrar.","Cocer a fuego medio hasta que la salsa reduzca y espese.","Verter el relleno de carne en una fuente de horno formando una capa uniforme.","Cubrir el relleno con el puré de patata y alisar la superficie con un tenedor creando surcos.","Hornear a 200 °C hasta que la superficie esté dorada.","Reposar la fuente fuera del horno antes de servir.","Servir en plato hondo racionando con una espátula."}', 'Pastel de carne picada con verduras cubierto de puré de patata dorado al horno.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Prepara el puré de patata y el sofrito de carne en la encimera. Monta el pastel en una fuente apta para horno y hornea a 180-200°C durante 25-30 minutos, hasta que el puré esté dorado y burbujeante."},{"appliance":"thermomix","time":65,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para cocinar las patatas al vapor y hacer el puré, así como para preparar el sofrito de carne. Luego, monta el pastel en una fuente y gratina en el horno a 200°C durante 15-20 minutos para un acabado perfecto."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Acelera la cocción de las patatas y el sofrito de carne usando la olla express. Una vez listos, monta el pastel en una fuente y gratina en el horno a 200°C durante 15-20 minutos para obtener el gratinado característico."},{"appliance":"airfryer","time":65,"difficulty":"normal","prepSummary":"Prepara el puré de patata y el sofrito de carne por separado en la encimera. Monta el pastel en un recipiente apto para airfryer y cocina a 180°C durante 20-25 minutos, hasta que el puré esté dorado y burbujeante."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('carnes_142', 'Calzone de jamón y queso', 'carnes', 'cerdo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 620, 28, 62, 28, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Masa de pizza","amount":300,"unit":"g"},{"name":"Jamón cocido en lonchas","amount":100,"unit":"g"},{"name":"Queso mozzarella","amount":150,"unit":"g"},{"name":"Tomate frito","amount":60,"unit":"g"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Harina","amount":20,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo, introduciendo la bandeja vacía para que se caliente.","Espolvorear la superficie de trabajo con harina y dividir masa de pizza en 2 porciones iguales.","Estirar cada porción con un rodillo hasta obtener 2 círculos de unos 25 cm de diámetro.","Laminar queso mozzarella en lonchas finas si no viene ya loncheada.","Untar la mitad de cada círculo con tomate frito, dejando 1 cm de borde libre.","Repartir jamón cocido en lonchas sobre el tomate frito de cada círculo.","Distribuir la mozzarella sobre el jamón cocido.","Espolvorear orégano seco sobre el relleno de cada calzone.","Doblar cada círculo por la mitad sobre el relleno y sellar el borde presionando con los dedos.","Rematar el sellado repasando el borde con un tenedor para que no se abra al hornear.","Pincelar la superficie de cada calzone con aceite de oliva.","Colocar los calzones sobre la bandeja caliente y hornear hasta que estén dorados y crujientes.","Retirar del horno y dejar templar hasta que el relleno no queme al cortar.","Servir los calzones en plato, enteros o cortados por la mitad."}', 'Calzone casero de jamón y queso con tomate frito, dorado y crujiente por fuera, fundente por dentro.', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Rellena la masa, sella bien los bordes y hornea durante 25-30 minutos, o hasta que esté dorado y el queso burbujee. Para un acabado más crujiente, pincela con aceite de oliva antes de hornear."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Divide la masa en porciones más pequeñas para formar mini calzones individuales. Precalienta la airfryer a 180°C. Cocina cada calzone durante 15-20 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_143', 'Buñuelos de queso y jamón', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 380, 14, 26, 24, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":120,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Leche","amount":200,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Jamón cocido en dados","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Calentar leche con mantequilla y sal en un cazo a fuego medio hasta que rompa a hervir.","Retirar el cazo del fuego y añadir harina de golpe.","Remover enérgicamente con una espátula hasta que la masa se despegue de las paredes del cazo.","Dejar templar la masa en el cazo.","Incorporar huevo a la masa uno a uno, batiendo bien después de cada uno hasta integrar por completo.","Añadir queso rallado a la masa y mezclar hasta integrar.","Añadir jamón cocido en dados y mezclar hasta que quede repartido de forma uniforme.","Calentar aceite de oliva en una sartén honda a fuego medio-fuerte hasta alcanzar 175 °C.","Formar bolitas de masa con 2 cucharas y freírlas en tandas hasta que estén doradas y hayan crecido, unos 4 min por tanda.","Escurrir los buñuelos sobre papel absorbente.","Servir los buñuelos templados."}', 'Buñuelos salados de queso y jamón, dorados y crujientes por fuera, fundentes por dentro.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara la masa de los buñuelos. Forma las porciones, rocíalas ligeramente con aceite y cocínalas en la airfryer precalentada a 190°C durante 15-20 minutos, dándoles la vuelta a mitad de cocción hasta que estén dorados y crujientes."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Una vez hecha la masa, forma los buñuelos y pincélalos con un poco de aceite de oliva. Hornéalos en el horno precalentado a 200°C durante 20-25 minutos, o hasta que estén bien dorados y cocidos por dentro."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_144', 'Croquetas de jamón cocido y queso', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'all', 420, 18, 32, 24, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Jamón cocido en dados","amount":200,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":70,"unit":"g"},{"name":"Leche","amount":700,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":500,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en una cazuela a fuego medio hasta que esté completamente derretida.","Añadir harina de golpe y remover sin parar con una varilla hasta obtener una pasta homogénea.","Verter leche poco a poco, sin dejar de remover, hasta integrar todo el líquido sin grumos.","Añadir jamón cocido en dados y queso rallado; remover para integrarlos en la bechamel.","Añadir sal y nuez moscada; remover para repartir los condimentos.","Cocer la masa a fuego suave, removiendo con frecuencia, hasta que esté muy espesa y se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a piel para evitar costra.","Refrigerar la masa en la nevera hasta que esté completamente firme.","Batir huevo en un bol hondo hasta homogeneizar.","Poner pan rallado en un plato llano para el empanado.","Formar porciones de masa con las manos dándoles forma alargada y uniforme.","Pasar cada croqueta por el huevo batido, escurrir el exceso y rebozar bien en el pan rallado.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas en tandas, sin amontonarlas, hasta que estén doradas por todos los lados.","Escurrir las croquetas fritas sobre papel absorbente para eliminar el exceso de aceite.","Servir las croquetas recién fritas y bien calientes."}', 'Croquetas cremosas de jamón cocido y queso fundido, con el interior que se estira al partirlas.', '[{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Prepara la bechamel en la Thermomix: funde la mantequilla, añade la harina y cocina unos minutos, luego incorpora la leche gradualmente a velocidad 4-5 a 90-100°C hasta espesar. Esto asegura una bechamel perfecta y sin grumos, el paso más crítico de la receta."},{"appliance":"airfryer","time":70,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas, cocina las croquetas en la airfryer precalentada a 190-200°C durante 12-15 minutos, rociándolas ligeramente con aceite. Gíralas a mitad de cocción para un dorado uniforme y una textura crujiente sin apenas aceite."},{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Para una versión más ligera, hornea las croquetas ya empanadas en una bandeja con papel de horno, rociadas con un poco de aceite, a 200°C (con ventilador si es posible) durante 15-20 minutos. Voltéalas a mitad de cocción para que se doren por todos lados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('carnes_145', 'Gyozas caseras con salsa de soja y sésamo', 'carnes', 'cerdo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 440, 20, 38, 22, 2, true, false, '{"gluten","soja","sesamo"}', '[{"name":"Obleas para gyoza","amount":18,"unit":"ud"},{"name":"Carne picada de cerdo","amount":250,"unit":"g"},{"name":"Col china","amount":150,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Semillas de sésamo","amount":5,"unit":"g"}]'::jsonb, '{"Cortar col china en tiras muy finas y picar fino.","Salar la col picada y dejar reposar hasta que suelte agua.","Escurrir la col apretándola con las manos para eliminar el exceso de agua.","Picar fino cebolleta, jengibre fresco y ajo.","Mezclar en un bol carne picada de cerdo, la col escurrida, la cebolleta, el jengibre y el ajo picados.","Añadir 10 ml de salsa de soja y aceite de sésamo al bol y mezclar hasta integrar.","Colocar una cucharadita de relleno en el centro de cada obleas para gyoza.","Humedecer los bordes de cada oblea con agua y cerrar en forma de media luna haciendo pliegues para sellar.","Calentar aceite de oliva en sartén a fuego medio-alto.","Colocar las gyozas con la base plana hacia abajo en la sartén caliente.","Dorar la base de las gyozas hasta que esté crujiente y dorada.","Añadir 60 ml de agua a la sartén y tapar de inmediato.","Cocer al vapor, tapado, hasta que la masa esté translúcida.","Mezclar el resto de la salsa de soja con vinagre de arroz y semillas de sésamo en un bol pequeño.","Destapar la sartén y dejar evaporar el agua restante hasta que la base recupere el crujiente.","Servir las gyozas calientes acompañadas de la salsa de soja y sésamo."}', 'Gyozas caseras de cerdo y col, doradas por la base y jugosas por dentro, para mojar en salsa de soja y sésamo.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Para un acabado crujiente y con menos aceite, rocía ligeramente las gyozas con aceite y cocínalas en la airfryer a 190°C durante 15-18 minutos, volteándolas a mitad de cocción hasta que estén doradas."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Hornea las gyozas para una versión más saludable y crujiente. Pincélalas con un poco de aceite y cuécelas a 200°C durante 20-25 minutos, hasta que estén bien doradas."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Usa la Thermomix para picar y mezclar el relleno de forma rápida y homogénea. Luego, cocina las gyozas al vapor en el recipiente Varoma durante 18-20 minutos para una textura tierna y jugosa."},{"appliance":"vaporera","time":40,"difficulty":"normal","prepSummary":"La vaporera es ideal para cocinar las gyozas de manera tradicional, obteniendo una masa suave y un relleno jugoso. Cocínalas al vapor durante 12-15 minutos hasta que estén bien cocidas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('cenas_rapidas_001', 'Sándwich mixto', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 348, 16, 32, 18, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Untar mantequilla por una cara de cada rebanada de pan de molde.","Colocar jamón cocido sobre la cara sin mantequilla de 2 rebanadas.","Añadir queso en lonchas encima del jamón cocido y tapar con las otras 2 rebanadas, con la mantequilla hacia afuera.","Calentar sartén a fuego medio y colocar los sándwiches con la cara con mantequilla hacia abajo.","Tostar hasta que la base esté dorada, girar y tostar el otro lado hasta que el queso en lonchas esté fundido.","Cortar cada sándwich en diagonal y servir de inmediato."}', 'Sándwich tostado de jamón cocido y queso fundido', '[{"appliance":"airfryer","time":9,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Unta el pan con mantequilla, monta el sándwich y cocina durante 8-10 minutos, dándole la vuelta a mitad para un dorado uniforme y queso bien fundido."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Unta el pan con mantequilla, monta el sándwich y hornea sobre papel de horno durante 10-12 minutos, o hasta que esté dorado y el queso fundido."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_002', 'Tosta de tomate con jamón', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 312, 14, 30, 16, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro por la mitad en sentido transversal.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la plancha hasta que estén doradas por ambas caras.","Frotar el tomate partido sobre cada rebanada tostada hasta impregnar bien la superficie.","Añadir aceite de oliva sobre cada rebanada.","Colocar jamón serrano sobre las tostas y servir de inmediato."}', 'Pan tostado con tomate rallado, aceite y jamón serrano', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tuesta las rebanadas de pan en la airfryer a 180°C durante 4-6 minutos, hasta que estén doradas y crujientes. Después, unta el tomate maduro sobre el pan tostado, añade el jamón serrano y finaliza con un chorrito de aceite de oliva virgen extra."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta las rebanadas de pan durante 5-8 minutos hasta que estén bien doradas. Una vez tostadas, unta el tomate maduro, coloca el jamón serrano y rocía con aceite de oliva."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_003', 'Ensalada de quinoa, feta y granada', 'cenas_rapidas', 'none', 'quinoa', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 366, 15, 36, 18, 2, true, true, '{"lactosa"}', '[{"name":"Quinoa","amount":140,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Granada","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Llevar a ebullición 280 ml de agua en un cazo a fuego fuerte y añadir quinoa.","Cocer la quinoa a fuego suave, tapada, hasta que absorba toda el agua y esté tierna.","Cortar tomate cherry por la mitad.","Cortar pepino en dados pequeños.","Laminar cebolla morada en medias lunas finas.","Extraer los granos de granada y reservar.","Cortar queso feta en dados de 1 cm.","Escurrir la quinoa cocida y extenderla en un bol amplio para que se enfríe.","Exprimir limón y mezclar el zumo con aceite de oliva en un bol pequeño hasta integrar.","Añadir al bol con la quinoa los tomates cherry, el pepino, la cebolla morada, los granos de granada y el queso feta.","Verter el aliño sobre la ensalada y mezclar con suavidad hasta que todo quede bien impregnado.","Servir la ensalada en platos hondos, repartiendo bien todos los ingredientes."}', 'Ensalada fría de quinoa con feta, granada, cherry y pepino', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina la quinoa con agua en el vaso del Thermomix (15-20 min, 100°C, velocidad cuchara). Mientras, pica los vegetales y mezcla todo con el aderezo."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Coloca la quinoa con el doble de agua en un recipiente apto para vaporera y cocina al vapor durante 20-25 minutos hasta que esté tierna. Luego, mezcla con los vegetales frescos y el aderezo."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa con el doble de agua en la olla express durante 5-7 minutos desde que sube la válvula. Deja despresurizar y luego mezcla con los ingredientes frescos y el aliño."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Combina la quinoa con el doble de agua en un recipiente apto para microondas, tapa y cocina a máxima potencia durante 10-12 minutos, o hasta que el agua se absorba. Mezcla con el resto de ingredientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_004', 'Pan tumaca con embutido', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 368, 16, 32, 20, 2, true, false, '{"gluten"}', '[{"name":"Pan de payés","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Fuet","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar pan de payés en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro por la mitad para frotar directamente sobre el pan.","Laminar fuet en rodajas finas.","Tostar las rebanadas de pan en plancha a fuego fuerte hasta que estén doradas por ambas caras.","Frotar cada rebanada tostada con las mitades de tomate maduro hasta que la miga quede bien impregnada.","Añadir aceite de oliva por encima de cada rebanada.","Disponer las rodajas de fuet sobre las rebanadas y servir de inmediato."}', 'Pan catalán con tomate rallado, aceite y fuet', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Tuesta el pan de payés en la airfryer a 180-200°C durante 3-5 minutos hasta que esté dorado y crujiente. Mientras, ralla el tomate y corta el fuet. Monta el pan con tomate, aceite y fuet."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan durante 4-6 minutos hasta que estén doradas. Ralla el tomate, aliña con aceite y monta sobre el pan tostado con el fuet."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_005', 'Tostada de aguacate y tomate', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 298, 6, 28, 18, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 2 rebanadas de grosor medio.","Cortar tomate cherry por la mitad y reservar.","Exprimir limón y reservar el zumo.","Tostar las rebanadas de pan en plancha a fuego fuerte hasta que estén doradas por ambas caras.","Abrir aguacate, retirar el hueso y volcar la pulpa en un bol.","Añadir el zumo de limón reservado sobre la pulpa de aguacate y aplastar con un tenedor hasta obtener una pasta rústica.","Untar la pasta de aguacate sobre las rebanadas tostadas de manera generosa.","Disponer los tomates cherry cortados sobre el aguacate y regar con aceite de oliva."}', 'Tostada de pan con aguacate machacado y tomate cherry', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta el pan durante 5-7 minutos, volteándolo a mitad, hasta que esté crujiente y dorado. Un truco es rociar un poco de aceite de oliva antes de tostar para un extra de sabor."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta el pan directamente sobre la rejilla durante 5-7 minutos, vigilando que no se queme, para un tostado uniforme. Monta la tostada con el resto de ingredientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_006', 'Salchichas con puré', 'cenas_rapidas', 'cerdo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 452, 18, 32, 28, 2, true, true, '{"lactosa"}', '[{"name":"Salchichas frescas","amount":250,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cubrir la patata con agua fría en un cazo, llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que esté tierna, unos 18 min.","Calentar plancha a fuego medio con aceite de oliva.","Colocar salchichas frescas en la plancha caliente y dorar por todos los lados hasta que estén doradas y cocidas por dentro, unos 8 min.","Escurrir la patata cocida y devolver al cazo a fuego suave para evaporar el exceso de humedad, 1 min.","Añadir mantequilla y leche a la patata escurrida y aplastar con un tenedor o pasapurés hasta obtener un puré liso.","Servir el puré en el plato y colocar las salchichas encima."}', 'Salchichas frescas a la plancha con puré de patata casero', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para las salchichas, precalienta la airfryer a 190°C y cocínalas durante 15-20 minutos, volteándolas a mitad de cocción para que queden doradas y crujientes por fuera."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Cocina las salchichas en una bandeja de horno precalentado a 200°C durante 20-25 minutos, dándoles la vuelta una vez para un dorado uniforme y un interior jugoso."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Prepara un puré de patatas perfecto cociendo las patatas troceadas al vapor en el Varoma (20-25 min) y luego triturándolas en el vaso con la leche y mantequilla hasta lograr una textura cremosa."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_007', 'Nachos con guacamole', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 382, 8, 36, 24, 2, true, false, '{}', '[{"name":"Nachos de maíz","amount":150,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Cebolla","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Cilantro","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate en dados pequeños y reservar.","Picar cebolla muy fina y reservar.","Picar cilantro fino y reservar.","Partir limón por la mitad y exprimir el zumo en un bol.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara al bol con el zumo de limón.","Aplastar la pulpa de aguacate con un tenedor hasta obtener una textura grumosa al gusto.","Añadir el tomate, la cebolla y el cilantro al bol y mezclar hasta integrar.","Disponer nachos de maíz en un plato amplio y servir el guacamole en un bol aparte para mojar."}', 'Nachos de maíz con guacamole casero de aguacate', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_008', 'Bruschetta de tomate', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 268, 6, 30, 14, 2, true, false, '{"gluten"}', '[{"name":"Pan chapata","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Albahaca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar pan chapata en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro en dados pequeños y reservar en un bol.","Pelar ajo y reservar el diente entero para frotar.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la plancha hasta que estén doradas por ambas caras.","Frotar el ajo por la superficie de cada rebanada tostada mientras aún está caliente.","Repartir el tomate en dados sobre las rebanadas.","Aliñar con aceite de oliva por encima de cada bruschetta.","Distribuir albahaca fresca sobre el tomate y servir de inmediato."}', 'Tostadas de pan con tomate fresco, ajo y albahaca', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta las rebanadas de pan durante 5-7 minutos hasta que estén doradas y crujientes, dándoles la vuelta a mitad de cocción. Esto asegura un tostado uniforme y rápido."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca las rebanadas de pan en una bandeja y tuéstalas durante 7-10 minutos, o hasta que estén doradas y crujientes. Vigila para que no se quemen."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_009', 'Rollitos de jamón y queso', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 262, 18, 2, 20, 2, true, true, '{"lactosa"}', '[{"name":"Jamón cocido","amount":120,"unit":"g"},{"name":"Queso en porciones","amount":80,"unit":"g"},{"name":"Pepinillos","amount":30,"unit":"g"}]'::jsonb, '{"Laminar pepinillos en rodajas finas a lo largo y reservar.","Extender jamón cocido en lonchas sobre una superficie plana.","Colocar queso en porciones en el extremo de cada loncha de jamón cocido.","Distribuir las rodajas de pepinillos sobre el queso en porciones.","Enrollar cada loncha de jamón cocido apretando para que el relleno quede compacto.","Servir los rollitos fríos dispuestos en un plato."}', 'Lonchas de jamón cocido enrolladas con queso y pepinillo', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_010', 'Tabla de quesos y embutidos', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 412, 22, 4, 34, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Queso curado","amount":80,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Pan de barra","amount":80,"unit":"g"}]'::jsonb, '{"Cortar queso curado en cuñas o tacos de tamaño bocado.","Laminar chorizo en rodajas finas y doblarlas ligeramente.","Cortar pan de barra en rebanadas de unos 2 cm de grosor.","Disponer el queso, el chorizo y jamón serrano en lonchas sobre una tabla amplia, agrupando cada producto.","Colocar aceitunas en un bol pequeño y situarlo en un extremo de la tabla junto con las rebanadas de pan."}', 'Tabla para compartir con queso curado, chorizo y jamón', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_012', 'Gazpacho con picatostes', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 198, 4, 18, 12, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":4,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y colocar en el vaso de la batidora.","Cortar pepino en trozos y añadir al vaso.","Cortar pimiento verde en trozos y añadir al vaso.","Añadir ajo al vaso.","Trocear pan y sumergirlo en agua fría durante 1 min; escurrir y añadir al vaso.","Triturar todos los ingredientes del vaso a máxima potencia hasta que la mezcla esté completamente lisa.","Añadir aceite de oliva y vinagre al vaso; triturar 30 segundos más hasta integrar.","Colar la mezcla por un colador fino sobre un bol, presionando con una cuchara para extraer todo el líquido.","Cortar el pan sobrante en dados pequeños y tostar en sartén a fuego medio hasta que estén dorados; reservar.","Servir el gazpacho frío en boles y repartir los dados de pan tostado por encima."}', 'Gazpacho frío servido con picatostes crujientes', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pepino, pimiento, ajo, aceite y vinagre en el vaso de la Thermomix. Tritura a velocidad progresiva 5-10 durante 1-2 minutos hasta lograr una textura fina y homogénea. Sirve muy frío con los picatostes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_013', 'Tostas de aguacate y huevo poché', 'cenas_rapidas', 'huevo', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 384, 15, 30, 23, 2, true, false, '{"huevo","gluten"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro","amount":5,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en 2 rebanadas de grosor medio.","Picar cilantro fino y reservar.","Exprimir lima y reservar el zumo.","Abrir aguacate, retirar el hueso y extraer la pulpa en un bol.","Machacar la pulpa de aguacate con un tenedor hasta obtener una textura cremosa con algunos grumos.","Añadir el zumo de lima y el cilantro picado al aguacate machacado y mezclar hasta integrar.","Llevar agua a ebullición en un cazo a fuego fuerte; añadir vinagre y bajar a fuego suave hasta mantener un hervor leve.","Tostar las rebanadas de pan de hogaza en la tostadora hasta que estén doradas y crujientes.","Cascar huevo de uno en uno en un cuenco pequeño e introducirlos suavemente en el agua con vinagre.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos poché con una espumadera y escurrir sobre papel de cocina.","Untar el guacamole de forma generosa sobre las tostas.","Colocar 1 huevo poché sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con guacamole casero (aguacate, lima y cilantro) y huevo poché de yema jugosa', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Tuesta el pan en la airfryer a 190°C durante 4-5 minutos hasta que quede dorado y crujiente. Mientras, escalfa los huevos en un cazo con agua y un chorro de vinagre 3 minutos. Monta las tostas con el aguacate machacado y el huevo poché por encima."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_016', 'Tostas de salmón ahumado y aguacate', 'cenas_rapidas', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 398, 19, 29, 22, 2, true, false, '{"gluten","pescado","lactosa"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Queso crema","amount":60,"unit":"g"},{"name":"Eneldo","amount":3,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 4 rebanadas de grosor medio.","Pelar y deshuesar aguacate, y laminarlo en tiras finas.","Exprimir limón y reservar el zumo en un cuenco pequeño.","Tostar las rebanadas de pan en sartén a fuego medio hasta que estén doradas por ambos lados.","Untar queso crema sobre cada rebanada tostada, cubriendo toda la superficie.","Disponer las láminas de aguacate sobre el queso crema, repartidas entre las 4 rebanadas.","Repartir salmón ahumado sobre el aguacate, cubriendo cada tosta de forma uniforme.","Rociar unas gotas del zumo de limón reservado sobre cada tosta.","Espolvorear eneldo sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con queso crema, aguacate, salmón ahumado y eneldo', '[]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('cenas_rapidas_017', 'Tostas de burrata, tomate y albahaca', 'cenas_rapidas', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 406, 15, 32, 23, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Burrata","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar pan de hogaza en rebanadas de unos 2 cm de grosor.","Cortar tomate maduro en rodajas finas y reservar.","Calentar una sartén o plancha a fuego fuerte hasta que esté bien caliente.","Tostar las rebanadas de pan en la sartén caliente hasta que estén doradas por ambas caras.","Frotar cada rebanada tostada con un trozo de tomate maduro por la superficie hasta impregnarla.","Repartir las rodajas de tomate maduro restantes sobre las rebanadas de pan.","Romper burrata con las manos y distribuirla sobre el tomate de cada tosta.","Repartir albahaca fresca entera o rasgada por encima de la burrata.","Acabar con aceite de oliva virgen extra sobre cada tosta y servir de inmediato."}', 'Tostas de pan crujiente con burrata cremosa, tomate maduro y albahaca fresca', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_014', 'Tortilla wrap de atún', 'cenas_rapidas', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 368, 22, 32, 16, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":40,"unit":"g"},{"name":"Mayonesa","amount":20,"unit":"g"}]'::jsonb, '{"Escurrir atún en conserva presionando bien la lata para eliminar el líquido.","Cortar tomate en dados pequeños y trocear lechuga en tiras finas.","Mezclar el atún escurrido con mayonesa en un bol hasta integrar bien.","Extender la mezcla de atún en el centro de tortilla de trigo, dejando 3 cm libres en los bordes.","Repartir la lechuga y el tomate cortado sobre la mezcla de atún.","Añadir maíz dulce distribuido de forma uniforme sobre cada tortilla.","Enrollar cada tortilla con firmeza plegando primero los laterales y luego enroscando hacia adelante hasta cerrar el wrap.","Cortar cada wrap por la mitad en diagonal y servir de inmediato."}', 'Wrap de tortilla de trigo con atún, lechuga y maíz', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Para darle un toque crujiente y caliente, rellena las tortillas con los ingredientes y dóblalas. Precalienta la airfryer a 180°C y cocina los wraps durante 5-7 minutos, volteándolos a mitad, hasta que estén dorados y crujientes."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('cenas_rapidas_015', 'Sopa fría de melón', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 178, 6, 22, 8, 2, true, true, '{"lactosa"}', '[{"name":"Melón","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Menta","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar melón y cortar en trozos grandes, retirando las pepitas.","Cortar jamón serrano en virutas finas con un cuchillo y reservar.","Añadir los trozos de melón, yogur natural, menta y aceite de oliva a un vaso batidor.","Triturar todos los ingredientes hasta obtener una crema lisa y homogénea.","Refrigerar la sopa en la nevera hasta que esté bien fría, al menos 30 min.","Servir la sopa en cuencos fríos y repartir las virutas de jamón serrano por encima."}', 'Sopa fría de melón con yogur, menta y jamón serrano', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce el melón troceado, el yogur, la menta y el aceite de oliva en el vaso. Tritura a velocidad progresiva 5-10 hasta obtener una crema fina y homogénea. Sirve muy frío, decorado con el jamón serrano."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('desayunos_001', 'Bol de yogur con fruta y avena', 'desayunos', 'none', 'avena', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 320, 13, 52, 7, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":100,"unit":"g"},{"name":"Copos de avena","amount":40,"unit":"g"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar plátano en rodajas de unos 5 mm.","Cortar fresas en cuartos, retirando el pedúnculo.","Repartir yogur natural a partes iguales en 2 boles.","Disponer las rodajas de plátano y las fresas cortadas sobre el yogur.","Repartir copos de avena por encima de la fruta.","Verter miel en hilo fino sobre cada bol y servir."}', 'Bol de yogur natural con plátano, fresas, avena y un toque de miel', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('desayunos_002', 'Tostada de tomate y aceite', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 230, 6, 34, 8, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Rallar tomate maduro sobre un bol hasta obtener la pulpa; desechar la piel.","Tostar pan en la tostadora hasta que esté dorado y crujiente.","Repartir la pulpa de tomate rallado sobre las tostadas de forma uniforme.","Añadir aceite de oliva sobre cada tostada y terminar con sal."}', 'Clásica tostada de pan con tomate rallado, aceite de oliva y sal', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('desayunos_003', 'Tostada con mantequilla y mermelada', 'desayunos', 'none', 'pan', ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 290, 6, 44, 10, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Mermelada","amount":40,"unit":"g"}]'::jsonb, '{"Tostar pan en la tostadora o bajo el grill hasta que esté dorado y crujiente.","Untar mantequilla sobre el pan recién tostado mientras aún está caliente, para que se funda.","Extender mermelada por encima de la mantequilla y servir de inmediato."}', 'Tostada clásica con mantequilla y mermelada', NULL, '{}', NULL, true, NULL, '{}', NULL),
