insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('ensaladas_verduras_038', 'Ensalada de burrata, melocotón y albahaca', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 302, 12, 14, 22, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Burrata","amount":250,"unit":"g"},{"name":"Melocotón","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar melocotón bajo agua fría.","Cortar el melocotón en gajos finos, sin pelar.","Repartir los gajos de melocotón en la base de 2 platos.","Colocar burrata entera o partida en el centro de cada plato.","Salpimentar con sal y pimienta negra.","Regar con aceite de oliva virgen extra y vinagre balsámico.","Deshojar albahaca fresca por encima justo antes de servir."}', 'Burrata cremosa con melocotón jugoso y albahaca fresca, un contraste dulce y suave.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('ensaladas_verduras_039', 'Ensalada de remolacha, queso de cabra y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 346, 12, 16, 26, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Remolacha cocida","amount":200,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar remolacha cocida en dados de unos 2 cm.","Cortar queso de cabra en rodajas de aproximadamente 1 cm.","Trocear nueces groseramente con el cuchillo.","Mezclar aceite de oliva virgen extra, vinagre balsámico y miel en un bol pequeño hasta integrar.","Repartir rúcula en la base de 2 platos formando una cama uniforme.","Distribuir la remolacha en dados sobre la rúcula.","Colocar las rodajas de queso de cabra repartidas por encima.","Esparcir las nueces troceadas sobre la ensalada.","Regar con la vinagreta justo antes de servir."}', 'Remolacha dulce, queso de cabra cremoso y nueces crujientes con vinagreta de miel.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_040', 'Ensalada templada de pato y naranja', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 433, 34, 18, 25, 2, false, false, '{"sulfitos"}', '[{"name":"Magret de pato","amount":300,"unit":"g"},{"name":"Naranja","amount":200,"unit":"g"},{"name":"Canónigos","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Laminar cebolla morada en aros muy finos y reservar.","Pelar naranja a vivo, separar los gajos y recoger el jugo que suelte en un bol.","Marcar la piel de magret de pato en forma de rejilla con un cuchillo, sin llegar a la carne.","Salpimentar magret de pato por ambos lados con sal.","Colocar el magret con la piel hacia abajo en sartén fría, sin aceite, y encender el fuego medio.","Cocinar sin mover hasta que la piel esté dorada y haya soltado su grasa, unos 7 min.","Retirar el exceso de grasa de la sartén con una cuchara.","Subir el fuego a fuerte y dorar el magret por el lado de la carne durante 2 min.","Retirar el magret a una tabla y dejar reposar 5 min antes de cortar.","Añadir el jugo de naranja reservado, vinagre de jerez y miel a la misma sartén.","Reducir a fuego medio hasta que la salsa espese ligeramente, unos 3 min. Retirar del fuego.","Cortar el magret reposado en láminas finas.","Disponer canónigos y la cebolla morada laminada en una fuente amplia.","Repartir los gajos de naranja y las láminas de magret sobre los canónigos.","Regar con aceite de oliva virgen extra y la reducción templada. Servir enseguida."}', 'Magret de pato dorado y jugoso sobre canónigos frescos, con naranja y una reducción agridulce.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_041', 'Ensalada de langostinos y aguacate', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 290, 22, 10, 18, 2, true, false, '{"marisco"}', '[{"name":"Langostinos pelados","amount":200,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Lechuga","amount":60,"unit":"g"},{"name":"Lima","amount":20,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lechuga y tomate bajo el grifo con agua fría.","Picar cilantro fresco fino y reservar.","Cortar el tomate en dados pequeños y reservar.","Cortar aguacate por la mitad, retirar el hueso y cortar la pulpa en dados.","Trocear la lechuga en piezas medianas y reservar.","Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer langostinos pelados en el agua hirviendo hasta que cambien de color, unos 2 min.","Escurrir los langostinos y enfriar en un bol con agua y hielo durante 2 min.","Escurrir los langostinos del agua con hielo y reservar.","Mezclar aceite de oliva virgen extra con lima y el cilantro picado en un bol pequeño.","Repartir la lechuga troceada en la base de 2 platos.","Distribuir los dados de aguacate y de tomate sobre la lechuga.","Colocar los langostinos encima y regar con el aliño de lima y cilantro justo antes de servir."}', 'Langostinos tiernos, aguacate cremoso y un aliño cítrico fresco con lima y cilantro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_042', 'Ensalada de pera, nueces y roquefort', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 352, 10, 24, 24, 2, false, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Canónigos","amount":80,"unit":"g"},{"name":"Pera","amount":200,"unit":"g"},{"name":"Queso roquefort","amount":80,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Laminar pera en rodajas finas sin pelar.","Mezclar aceite de oliva virgen extra, vinagre balsámico y miel en un bol pequeño hasta integrar.","Repartir los canónigos escurridos en la base de 2 platos.","Distribuir las láminas de pera sobre los canónigos.","Desmigar queso roquefort por encima de la pera.","Trocear nueces en trozos gruesos y esparcir sobre la ensalada.","Regar la ensalada con la vinagreta justo antes de servir."}', 'Pera crujiente, roquefort intenso y nueces tostadas, el clásico contraste dulce y salado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_043', 'Ensalada de sandía, feta y menta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 231, 8, 16, 15, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Sandía","amount":300,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceitunas negras","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cortar sandía en dados grandes, retirando las pepitas.","Cortar queso feta en dados del mismo tamaño que la sandía.","Deshojar menta fresca y reservar las hojas enteras.","Repartir la sandía y el queso feta en una fuente.","Añadir aceitunas negras y las hojas de menta fresca por encima.","Regar con aceite de oliva virgen extra y vinagre balsámico.","Terminar con pimienta negra y servir bien fría."}', 'Sandía jugosa y feta salado con menta fresca, la ensalada más refrescante del verano.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('ensaladas_verduras_044', 'Ensalada de quinoa, granada y feta', 'ensaladas_verduras', 'none', 'quinoa', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 343, 12, 40, 15, 2, true, true, '{"lactosa"}', '[{"name":"Quinoa","amount":100,"unit":"g"},{"name":"Granada","amount":100,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar quinoa bajo agua fría hasta que el agua salga clara.","Llevar a ebullición un cazo con agua y sal.","Cocer la quinoa a fuego medio hasta que esté tierna y haya absorbido el agua.","Desgranar granada y reservar los granos.","Cortar pepino en dados pequeños.","Picar menta fresca fina.","Escurrir la quinoa cocida y extenderla en una fuente hasta que esté fría.","Desmigar queso feta con los dedos en trozos irregulares.","Mezclar la quinoa fría con el pepino, los granos de granada y el queso feta desmigado.","Aliñar con aceite de oliva virgen extra y limón.","Añadir la menta picada y remover con suavidad hasta integrar.","Servir la ensalada templada o fría."}', 'Quinoa suelta con granada, feta y menta, fresca y ligera, para servir templada o fría.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_045', 'Ensalada Waldorf de manzana, apio y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 326, 6, 26, 22, 2, true, false, '{"frutos_secos","apio","huevo","lactosa"}', '[{"name":"Manzana","amount":200,"unit":"g"},{"name":"Apio","amount":80,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Uvas pasas","amount":30,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Yogur natural","amount":30,"unit":"g"},{"name":"Limón","amount":10,"unit":"ml"},{"name":"Lechuga","amount":60,"unit":"g"}]'::jsonb, '{"Lavar lechuga y manzana bajo el grifo.","Cortar la manzana en dados medianos sin pelar.","Exprimir limón sobre los dados de manzana y remover para que no se oxiden.","Laminar apio en rodajas finas.","Trocear nueces en trozos gruesos.","Mezclar en un bol la manzana, el apio, las nueces y uvas pasas.","Añadir mayonesa y yogur natural al bol y remover hasta que todo quede bien integrado.","Repartir la lechuga como base en una fuente o en los platos.","Servir la mezcla Waldorf sobre la lechuga."}', 'Manzana crujiente, apio y nueces en una cremosa mezcla de mayonesa y yogur, el clásico americano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_046', 'Ensalada de pulpo y patata', 'ensaladas_verduras', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 333, 26, 28, 13, 2, false, true, '{"moluscos"}', '[{"name":"Pulpo cocido","amount":300,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Sal gorda","amount":3,"unit":"g"},{"name":"Laurel","amount":2,"unit":"g"}]'::jsonb, '{"Lavar patata y colocarlas enteras con piel en una olla.","Cubrir las patatas con agua fría, añadir laurel y sal gorda.","Llevar a ebullición a fuego fuerte y cocer a fuego medio hasta que estén tiernas, unos 25 min.","Cortar pulpo cocido en rodajas de 1 dedo de grosor.","Escurrir las patatas y dejarlas templar hasta que se puedan pelar sin quemarse, unos 10 min.","Pelar las patatas y cortarlas en rodajas gruesas de unos 2 cm.","Repartir las rodajas de patata en la base de una fuente.","Colocar las rodajas de pulpo cocido sobre las patatas.","Espolvorear pimentón dulce de manera uniforme sobre el pulpo y las patatas.","Regar con aceite de oliva virgen extra generoso y servir templado."}', 'Pulpo tierno en rodajas sobre patata cocida, con pimentón y un buen chorro de aceite de oliva.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_047', 'Ensalada de garbanzos especiados con comino', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 300, 12, 36, 12, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Comino molido","amount":4,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y enjuagarlos bajo el grifo hasta que el agua salga limpia.","Pelar cebolla morada y cortar en dados pequeños.","Cortar pimiento rojo en dados pequeños del mismo tamaño que la cebolla morada.","Picar perejil fresco fino y reservar aparte.","Mezclar en un bol los garbanzos escurridos, la cebolla morada y el pimiento rojo.","Añadir comino molido, pimentón dulce y sal sobre la mezcla y remover hasta integrar bien.","Aliñar con aceite de oliva virgen extra y limón, y remover para que el aliño cubra todos los garbanzos.","Esperar 5 min para que los garbanzos absorban el aliño y los aromas de las especias.","Repartir la ensalada en los platos y dispersar el perejil picado por encima antes de servir."}', 'Garbanzos especiados con comino y pimentón, coloridos y listos para servir templados o fríos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_048', 'Ensalada de espárragos trigueros y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 233, 12, 8, 17, 2, true, true, '{"sulfitos"}', '[{"name":"Espárragos trigueros","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar espárragos trigueros y retirar la parte leñosa del tallo rompiéndolo por donde ceda de forma natural.","Laminar ajo.","Calentar plancha a fuego fuerte con aceite de oliva virgen extra.","Asar los espárragos trigueros hasta que estén tiernos y con puntos dorados.","Retirar los espárragos y reservar en la fuente de servicio.","Añadir jamón serrano en tiras a la plancha caliente y dorar hasta que quede crujiente.","Añadir el ajo laminado junto al jamón y saltear hasta que esté dorado.","Repartir el jamón crujiente y el ajo sobre los espárragos reservados.","Aliñar con el resto del aceite de oliva virgen extra, vinagre de jerez, sal y pimienta negra.","Servir templado."}', 'Espárragos trigueros a la plancha con jamón crujiente, un aliño sencillo que no tapa el sabor.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_049', 'Ensalada de tomate raf con ventresca de atún', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 310, 20, 8, 22, 2, true, true, '{"pescado"}', '[{"name":"Tomate raf","amount":300,"unit":"g"},{"name":"Ventresca de atún en aceite","amount":120,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Aceitunas negras","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal en escamas","amount":3,"unit":"g"}]'::jsonb, '{"Lavar tomate raf bajo el grifo y secar con papel de cocina.","Cortar el tomate raf a mano en trozos irregulares, conservando todo el jugo que suelte.","Laminar cebolleta en aros muy finos.","Repartir el tomate raf en una fuente honda, vertiendo también el jugo acumulado.","Esparcir la cebolleta laminada sobre el tomate de forma uniforme.","Añadir aceitunas negras distribuidas por toda la fuente.","Escurrir ventresca de atún en aceite y colocarla entera encima del tomate, sin desmigar.","Regar con aceite de oliva virgen extra por encima de todos los ingredientes.","Terminar con sal en escamas y servir a temperatura ambiente."}', 'Tomate raf maduro partido a mano con ventresca de atún brillante y aceite de oliva.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('ensaladas_verduras_050', 'Ensalada de higos, jamón y queso de cabra', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 341, 14, 24, 21, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Higos","amount":200,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Rúcula","amount":50,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar higos bajo agua fría y secarlos con papel de cocina.","Cortar los higos en cuartos.","Cortar queso de cabra en rodajas de aproximadamente 1 cm.","Cortar jamón serrano en tiras finas.","Repartir rúcula en la base de 2 platos formando una cama uniforme.","Distribuir los higos en cuartos sobre la rúcula.","Repartir las tiras de jamón serrano por encima de los higos.","Colocar las rodajas de queso de cabra repartidas por toda la ensalada.","Aliñar con miel, aceite de oliva virgen extra y vinagre balsámico en hilo fino."}', 'Higos maduros, jamón serrano y queso de cabra sobre rúcula, con un toque de miel.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_051', 'Ensalada de rúcula, parmesano y piñones', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 280, 10, 6, 24, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Rúcula","amount":100,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Piñones","amount":25,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Tostar piñones en una sartén sin aceite a fuego medio, removiendo hasta que se doren ligeramente.","Retirar los piñones de la sartén y reservar en un plato.","Lavar rúcula bajo agua fría y escurrir bien.","Hacer virutas de queso parmesano con un pelador.","Repartir la rúcula escurrida en una fuente o en 2 platos.","Distribuir las virutas de queso parmesano sobre la rúcula.","Esparcir los piñones tostados por encima.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Añadir sal y pimienta negra, y servir de inmediato."}', 'Rúcula intensa con virutas de parmesano y piñones tostados, sencilla y llena de sabor.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_052', 'Ensalada thai de pollo con cacahuete', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 380, 30, 20, 20, 2, false, true, '{"cacahuetes","soja","pescado","sesamo"}', '[{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Col china","amount":150,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cacahuetes tostados","amount":30,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":20,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Salsa de pescado","amount":10,"unit":"ml"},{"name":"Azúcar moreno","amount":10,"unit":"g"},{"name":"Guindilla roja","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar plancha a fuego fuerte.","Cocinar pechuga de pollo hasta que esté hecha por dentro, unos 6 min por cada lado.","Cortar col china en juliana fina.","Cortar zanahoria en bastones finos.","Cortar pepino en bastones finos.","Picar guindilla roja en rodajas finas.","Picar cilantro fresco fino.","Picar cacahuetes tostados groseramente.","Mezclar en un bol lima, salsa de soja, salsa de pescado, azúcar moreno y aceite de sésamo hasta disolver el azúcar.","Retirar la pechuga de pollo de la plancha y dejar templar 5 min.","Cortar la pechuga de pollo en tiras finas.","Disponer en una fuente grande la col china, la zanahoria, el pepino y las tiras de pollo.","Añadir el aliño sobre la fuente y remover bien hasta que todo quede impregnado.","Servir con los cacahuetes picados, el cilantro fresco y la guindilla roja por encima."}', 'Pollo, col y verduras crujientes con un aliño agridulce de lima y salsa de pescado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_053', 'Ensalada de bogavante', 'ensaladas_verduras', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 376, 32, 8, 24, 2, true, false, '{"marisco","huevo"}', '[{"name":"Bogavante","amount":600,"unit":"g"},{"name":"Lechugas variadas","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Huevo","amount":50,"unit":"g"},{"name":"Aceite de oliva suave","amount":100,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Sumergir bogavante en el agua hirviendo y cocer 9 min.","Retirar el bogavante y sumergirlo en agua con hielo hasta que esté frío para cortar la cocción.","Extraer la carne de la cola y las pinzas con cuidado hasta que quede entera.","Cortar la carne del bogavante en medallones.","Verter huevo en un vaso de batidora junto con sal.","Añadir aceite de oliva suave en hilo fino mientras se bate hasta que emulsione.","Añadir limón a la mayonesa y remover hasta integrar.","Lavar lechugas variadas y escurrirlas bien.","Cortar aguacate en láminas.","Cortar tomate cherry por la mitad.","Repartir las lechugas variadas en la base de 2 platos.","Distribuir las láminas de aguacate y los tomates cherry sobre las lechugas.","Colocar los medallones de bogavante encima.","Servir con la mayonesa en un cordón fino sobre la ensalada o aparte."}', 'Bogavante recién cocido sobre hojas frescas, aguacate y tomate, para una ocasión especial.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_054', 'Ensalada niçoise', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 452, 30, 20, 28, 2, false, false, '{"huevo","pescado","sulfitos","mostaza"}', '[{"name":"Lechuga o mezclum","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Judías verdes","amount":150,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Atún en aceite","amount":120,"unit":"g"},{"name":"Anchoas","amount":20,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer patata con piel en el agua hirviendo a fuego medio hasta que estén tiernas.","Llevar a ebullición un cazo con agua a fuego fuerte para cocer los huevos.","Cocer huevo en el agua hirviendo a fuego medio durante 10 min.","Escurrir los huevos y sumergirlos en agua fría hasta que estén templados.","Llevar a ebullición otro cazo con agua y sal a fuego fuerte para las judías.","Escaldar judías verdes en el agua hirviendo a fuego medio.","Escurrir las judías verdes y pasar por agua fría hasta que estén frías para cortar la cocción.","Escurrir las patatas y dejar templar hasta que se puedan manipular.","Pelar las patatas y cortar en rodajas.","Pelar los huevos y cortar en cuartos.","Cortar tomate en gajos.","Mezclar aceite de oliva, vinagre de vino y mostaza de dijon en un bol pequeño hasta emulsionar.","Lavar lechuga o mezclum y repartir en la base de 2 platos o una fuente.","Distribuir encima las rodajas de patata, las judías verdes y los gajos de tomate.","Añadir atún en aceite desmigado, anchoas y aceitunas negras repartidos por la ensalada.","Colocar los cuartos de huevo por encima.","Aliñar la ensalada con la vinagreta justo antes de servir."}', 'Ensalada niçoise clásica con atún, huevo cocido, anchoas, patata y judías verdes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_055', 'Ensalada de aguacate y gambas con salsa rosa', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 426, 20, 10, 34, 2, true, false, '{"marisco","huevo"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Gambas cocidas peladas","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Mayonesa","amount":60,"unit":"g"},{"name":"Ketchup","amount":20,"unit":"g"},{"name":"Limón","amount":10,"unit":"ml"}]'::jsonb, '{"Mezclar mayonesa, ketchup y limón en un bol pequeño hasta obtener una salsa rosa homogénea.","Lavar canónigos bajo el grifo y escurrir bien.","Cortar tomate cherry por la mitad.","Cortar aguacate por la mitad, retirar el hueso y laminar la pulpa.","Repartir los canónigos escurridos en la base de 2 platos.","Distribuir las láminas de aguacate, gambas cocidas peladas y los tomates cherry sobre los canónigos.","Napar con la salsa rosa y servir enseguida."}', 'Ensalada fresca de aguacate y gambas cocidas con una cremosa salsa rosa casera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_056', 'Ensalada de manzana, nueces y queso azul', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 331, 8, 14, 27, 2, false, false, '{"frutos_secos","lactosa","sulfitos"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Módena","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Repartir los canónigos escurridos en una ensaladera o en 2 platos.","Descorazonar manzana y cortar en láminas finas.","Calentar sartén a fuego medio sin aceite y tostar nueces hasta que desprendan aroma tostado.","Retirar las nueces de la sartén y reservar.","Desmenuzar queso azul en trozos irregulares.","Mezclar aceite de oliva, vinagre de módena y miel en un bol hasta emulsionar.","Repartir las láminas de manzana, las nueces y el queso azul sobre la base de canónigos.","Aliñar la ensalada con el aliño justo antes de servir."}', 'Ensalada dulce y crujiente de manzana, nueces tostadas y queso azul.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_057', 'Tabulé de cuscús con menta y limón', 'ensaladas_verduras', 'none', 'cuscus', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 300, 7, 38, 13, 2, true, true, '{"gluten"}', '[{"name":"Cuscús","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Perejil fresco","amount":20,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Limón","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Hervir agua con sal en un cazo pequeño.","Colocar cuscús en un bol amplio y cubrir con el agua hirviendo recién lista.","Añadir aceite de oliva al bol, tapar con un plato y dejar reposar 5 min.","Cortar tomate en dados pequeños.","Cortar pepino en dados pequeños.","Picar cebolleta muy fina.","Picar perejil fresco muy fino.","Picar menta fresca muy fina.","Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","Añadir el tomate, el pepino, la cebolleta, el perejil y la menta al bol con el cuscús.","Aliñar con limón y el resto del aceite de oliva.","Salpimentar al gusto y remover bien hasta integrar todos los ingredientes.","Tapar el bol y refrigerar en la nevera al menos 15 min para que los sabores se asienten.","Servir el tabulé frío directamente del bol."}', 'Tabulé de cuscús con menta, perejil y limón, ligero y muy aromático.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_058', 'Ensalada de cuscús con verduras asadas', 'ensaladas_verduras', 'none', 'cuscus', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 355, 8, 42, 17, 2, true, true, '{"gluten"}', '[{"name":"Cuscús","amount":100,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Cebolla roja","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar calabacín, pimiento rojo, berenjena y cebolla roja en trozos regulares de unos 2 cm.","Disponer las verduras cortadas en una bandeja de horno en una sola capa.","Rociar las verduras con aceite de oliva y salpimentar.","Hornear las verduras a 200 °C durante 25 min, hasta que estén tiernas y doradas.","Llevar agua con sal a ebullición y verterla sobre cuscús en un bol hasta cubrirlo justo.","Tapar el bol y dejar reposar el cuscús 5 min hasta que absorba toda el agua.","Soltar los granos de cuscús con un tenedor hasta que queden sueltos y esponjosos.","Picar perejil fresco fino y reservar.","Mezclar el cuscús con las verduras asadas templadas en el bol grande.","Aliñar con el resto del aceite de oliva y limón, y remover para integrar.","Espolvorear el perejil picado por encima y servir templado o frío."}', 'Ensalada de cuscús con verduras de temporada asadas al horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_059', 'Ensalada campera con ventresca', 'ensaladas_verduras', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 404, 22, 25, 24, 2, true, true, '{"pescado","huevo","sulfitos"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ventresca de atún en aceite","amount":120,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo y cocer patata con piel hasta que estén tiernas.","Cocer huevo en agua hirviendo durante 10 min.","Enfriar el huevo bajo agua fría, pelar y cortar en cuartos.","Escurrir las patatas, dejar templar y pelar.","Cortar las patatas en rodajas y disponer en una fuente.","Cortar tomate en dados pequeños y repartir sobre las patatas.","Cortar pimiento verde en dados pequeños y añadir a la fuente.","Cortar cebolla en dados pequeños y añadir a la fuente.","Desmigar ventresca de atún en aceite sobre la fuente.","Añadir aceitunas y los cuartos de huevo sobre la ensalada.","Aliñar con aceite de oliva y vinagre de vino.","Reposar la ensalada 5 min antes de servir para que se integren los sabores.","Servir la ensalada campera directamente desde la fuente."}', 'Ensalada campera de patata con ventresca de atún, huevo y pimiento.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_060', 'Ensalada tibia de setas y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 215, 13, 5, 17, 2, true, false, '{"sulfitos"}', '[{"name":"Mezclum de hojas","amount":80,"unit":"g"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Jamón serrano en taquitos","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Laminar las setas limpias.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que aromatice sin que se dore.","Añadir las setas laminadas y subir a fuego fuerte.","Saltear las setas hasta que se doren y suelten el agua, removiendo a menudo.","Añadir jamón serrano en taquitos y saltear 1 min más hasta que esté caliente.","Picar perejil fresco fino y reservar.","Repartir mezclum de hojas en los platos como base.","Distribuir las setas y el jamón templados sobre las hojas.","Aliñar con aceite de oliva y vinagre de jerez.","Espolvorear el perejil picado y servir enseguida."}', 'Ensalada tibia de setas salteadas y jamón serrano sobre un fondo de hojas frescas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_061', 'Ensalada de espinacas, fresas y almendras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 220, 5, 11, 17, 2, true, false, '{"frutos_secos"}', '[{"name":"Espinacas baby","amount":100,"unit":"g"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Almendras laminadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre balsámico","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar espinacas baby bajo el grifo con agua fría y escurrir bien.","Lavar fresas, retirar el rabito y cortar cada una en láminas.","Calentar sartén a fuego medio sin aceite hasta que esté bien caliente.","Tostar almendras laminadas en la sartén hasta que estén doradas, removiendo con frecuencia.","Retirar las almendras laminadas de la sartén y reservar sobre un plato para que enfríen.","Mezclar aceite de oliva con vinagre balsámico y miel en un bol pequeño hasta emulsionar.","Repartir las espinacas baby en la base de los platos.","Distribuir las fresas laminadas y las almendras laminadas tostadas por encima de las espinacas.","Aliñar con el aceite de oliva, el vinagre balsámico y la miel justo antes de servir."}', 'Ensalada de espinacas baby con fresas y almendras tostadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_062', 'Ensalada de canónigos con granada y queso de cabra', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 316, 10, 15, 24, 2, true, false, '{"lactosa","frutos_secos"}', '[{"name":"Canónigos","amount":100,"unit":"g"},{"name":"Granada (arilos)","amount":100,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Nueces","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de Módena","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Lavar canónigos bajo agua fría y escurrir bien.","Desgranar granada (arilos) retirando toda la piel blanca.","Cortar queso de cabra en rodajas.","Mezclar aceite de oliva, vinagre de módena y miel en un bol hasta emulsionar.","Repartir los canónigos escurridos en una fuente.","Disponer sobre los canónigos los arilos de granada, las rodajas de queso de cabra y nueces.","Aliñar con el vinagre de Módena emulsionado justo antes de servir."}', 'Ensalada de canónigos con granada, queso de cabra y nueces.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_063', 'Ensalada de tomate, mozzarella y pesto', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 323, 14, 6, 27, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Tomate","amount":250,"unit":"g"},{"name":"Mozzarella fresca","amount":150,"unit":"g"},{"name":"Pesto","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Albahaca fresca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate en rodajas gruesas de unos 8 mm.","Cortar mozzarella fresca en rodajas del mismo grosor que el tomate.","Alternar en el plato las rodajas de tomate y mozzarella, superponiéndolas ligeramente.","Repartir pesto por encima con una cuchara, en hilo fino y uniforme.","Rociar con aceite de oliva sobre el conjunto.","Distribuir albahaca fresca en hojas enteras por encima y servir a temperatura ambiente."}', 'Ensalada caprese de tomate y mozzarella con pesto casero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_064', 'Ensalada de lentejas templadas con feta', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 400, 20, 35, 20, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Cebolla roja","amount":40,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Cortar tomate cherry por la mitad.","Picar cebolla roja muy fina.","Cortar pepino en dados pequeños.","Picar perejil fresco fino.","Calentar lentejas cocidas en un cazo a fuego suave hasta que estén templadas.","Mezclar las lentejas templadas con el tomate cherry, la cebolla roja y el pepino en un bol.","Aliñar con aceite de oliva y vinagre de vino.","Añadir el perejil picado y remover con cuidado.","Desmenuzar queso feta por encima y servir templado."}', 'Ensalada templada de lentejas con feta desmenuzado y verduras frescas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_065', 'Ensalada de pollo crujiente y aguacate', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 579, 36, 30, 35, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pechuga de pollo","amount":260,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva suave para freír","amount":200,"unit":"ml"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Mezclum de hojas","amount":100,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas y salpimentar.","Batir huevo en un bol hasta que esté homogéneo.","Pasar cada tira de pollo por harina, luego por el huevo batido y por último por pan rallado, presionando bien.","Calentar aceite de oliva suave para freír en sartén a fuego medio-fuerte hasta que esté caliente.","Freír las tiras de pollo empanadas hasta que estén doradas y crujientes, unos 3 min por cada lado.","Escurrir el pollo frito sobre papel absorbente y reservar.","Lavar y escurrir mezclum de hojas y repartir sobre los platos.","Cortar tomate cherry por la mitad.","Laminar aguacate y repartir sobre las hojas junto con los tomates cherry.","Mezclar aceite de oliva con vinagre de vino en un bol pequeño hasta integrar.","Colocar las tiras de pollo crujiente sobre la ensalada.","Aliñar con el vinagre y el aceite de oliva y servir enseguida para que el pollo conserve el crujiente."}', 'Ensalada de pollo crujiente empanado con aguacate y tomate cherry.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_066', 'Ensalada de calabaza asada y queso de cabra', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 365, 13, 22, 25, 2, true, false, '{"lactosa","frutos_secos"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Rúcula","amount":80,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortar en dados de 2 cm.","Disponer los dados de calabaza en una bandeja y rociar con aceite de oliva.","Salpimentar los dados de calabaza y hornear a 200 °C hasta que estén tiernos y dorados.","Mezclar miel y vinagre balsámico con el resto del aceite de oliva en un bol hasta emulsionar.","Trocear nueces en trozos gruesos.","Retirar la calabaza del horno y dejar templar.","Repartir rúcula en los platos.","Disponer los dados de calabaza templada sobre la rúcula.","Desmenuzar queso de cabra por encima de la calabaza.","Repartir las nueces troceadas sobre la ensalada.","Aliñar la ensalada con la vinagreta de miel y vinagre balsámico justo antes de servir."}', 'Ensalada de calabaza asada con queso de cabra y nueces sobre rúcula.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_067', 'Ensalada César con pollo crujiente', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 540, 38, 25, 32, 2, true, false, '{"gluten","huevo","lactosa","pescado","mostaza"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":260,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Pan de molde para picatostes","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Anchoas","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de tamaño uniforme y salpimentar.","Batir huevo en un bol hondo hasta que esté homogéneo.","Pasar cada tira de pollo por harina, luego por el huevo batido y después por pan rallado.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír las tiras de pollo empanadas 3 min por cada lado hasta que estén doradas.","Retirar el pollo y escurrir sobre papel absorbente. Reservar.","Cortar pan de molde para picatostes en dados pequeños y uniformes.","Calentar un chorrito de aceite de oliva en sartén a fuego medio.","Dorar los dados de pan de molde en la sartén, removiendo, hasta que estén crujientes y dorados.","Retirar los picatostes y reservar sobre papel absorbente.","Picar ajo fino y colocar en el vaso de la batidora junto con anchoas.","Rallar la mitad de queso parmesano e incorporar al vaso con mayonesa, limón y mostaza de dijon.","Triturar todos los ingredientes de la salsa hasta obtener una mezcla lisa y homogénea.","Lavar y trocear lechuga romana en trozos grandes y repartir en los platos.","Aliñar la lechuga con la salsa César y remover hasta que quede bien cubierta.","Repartir las tiras de pollo crujiente y los picatostes sobre la lechuga aliñada.","Rallar el resto del queso parmesano por encima y servir de inmediato."}', 'Ensalada César completa con pollo crujiente, picatostes y parmesano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_068', 'Ensalada de zanahoria rallada, pasas y comino', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 213, 2, 31, 9, 2, true, true, '{"sulfitos"}', '[{"name":"Zanahoria","amount":300,"unit":"g"},{"name":"Pasas","amount":40,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Pelar zanahoria y rallarla con un rallador grueso en tiras finas.","Sumergir pasas en un bol con agua templada hasta que se hidraten.","Picar perejil fresco fino.","Escurrir las pasas y reservar.","Mezclar la zanahoria rallada con las pasas escurridas en un bol grande.","Añadir comino molido y remover para distribuirlo.","Aliñar con aceite de oliva y limón.","Espolvorear el perejil picado y remover bien hasta integrar todos los ingredientes.","Tapar el bol y refrigerar hasta que los sabores se integren.","Servir la ensalada fría directamente del bol."}', 'Ensalada marroquí de zanahoria rallada con pasas, comino y limón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_069', 'Ensalada de brotes tiernos con miel y mostaza', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 172, 2, 11, 14, 2, true, false, '{"mostaza","sulfitos"}', '[{"name":"Brotes tiernos","amount":160,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar brotes tiernos bajo agua fría y escurrir bien.","Cortar tomate cherry por la mitad.","Mezclar aceite de oliva, miel, mostaza de dijon y vinagre de vino en un bol hasta emulsionar.","Repartir los brotes tiernos en los platos y distribuir los tomates cherry por encima.","Aliñar con la vinagreta justo antes de servir y remover con suavidad hasta que las hojas queden bien cubiertas."}', 'Ensalada de brotes tiernos con tomate cherry y aliño de miel y mostaza.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_070', 'Ensalada de arroz salvaje con verduras', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 346, 5, 50, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Arroz salvaje","amount":120,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":10,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con abundante agua y una pizca de sal a fuego fuerte.","Añadir arroz salvaje cuando el agua hierva y cocer a fuego medio durante 35-40 min, hasta que esté tierno.","Cortar pimiento rojo en dados pequeños.","Cortar calabacín en dados pequeños.","Cortar zanahoria en dados pequeños.","Picar cebolleta finamente.","Picar perejil fresco finamente.","Escurrir el arroz cuando esté tierno y extenderlo en un bol para que temple.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear el pimiento rojo, el calabacín y la zanahoria en la sartén 5-6 min, hasta que estén tiernos con un punto crujiente.","Retirar las verduras del fuego y dejar templar 5 min.","Mezclar el arroz templado con las verduras salteadas y la cebolleta picada en el bol.","Aliñar con el resto del aceite de oliva y vinagre de vino y remover bien para integrar.","Espolvorear el perejil picado por encima y servir templado o frío."}', 'Ensalada de arroz salvaje con verduras salteadas, fresca y con textura.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_071', 'Ensalada de judías verdes, tomate y huevo', 'ensaladas_verduras', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 227, 9, 14, 15, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Judías verdes","amount":300,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Limpiar judías verdes, retirar las puntas y cortar en mitades si son muy largas.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer las judías verdes 9 min hasta que estén tiernas pero firmes.","Cocer huevo en otro cazo con agua a ebullición durante 10 min.","Cortar tomate en gajos.","Laminar cebolla en juliana fina.","Escurrir las judías verdes y enfriar de inmediato en un bol con agua fría para conservar el color.","Escurrir los huevos, enfriar bajo el grifo, pelar y cortar en cuartos.","Colocar las judías verdes escurridas, el tomate y la cebolla en una fuente.","Repartir los cuartos de huevo por encima.","Aliñar con aceite de oliva, vinagre de vino y servir templado o frío."}', 'Ensalada de judías verdes, tomate y huevo cocido, sencilla y equilibrada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_072', 'Ensalada de patata, huevo y atún', 'ensaladas_verduras', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 440, 30, 35, 20, 2, true, true, '{"huevo","pescado","sulfitos"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar patata y colocarlas enteras con piel en un cazo. Cubrir con agua fría y llevar a ebullición a fuego fuerte.","Cocer las patatas a fuego medio hasta que estén tiernas al pincharlas con un cuchillo, aproximadamente 22 min.","Cocer huevo en un cazo aparte con agua hirviendo a fuego medio durante 10 min.","Escurrir los huevos y sumergirlos en agua fría hasta que estén fríos.","Escurrir las patatas y dejarlas templar hasta que se puedan manipular sin quemarse.","Pelar y cortar las patatas en rodajas gruesas de unos 1,5 cm.","Pelar los huevos y cortarlos en cuartos.","Picar cebolla muy fina.","Escurrir atún en conserva y desmigar con un tenedor.","Disponer las rodajas de patata en una fuente formando una capa uniforme.","Repartir la cebolla picada sobre las patatas.","Distribuir el atún desmigado sobre las patatas y la cebolla.","Colocar los cuartos de huevo y aceitunas sobre la ensalada.","Aliñar con aceite de oliva y vinagre de vino por encima.","Dejar reposar la ensalada 5 min antes de servir para que los sabores se integren."}', 'Ensalada de patata, huevo y atún, variante clásica de la ensalada campera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_073', 'Ensalada de pepino, yogur y menta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 210, 10, 11, 14, 2, true, true, '{"lactosa"}', '[{"name":"Pepino","amount":400,"unit":"g"},{"name":"Yogur griego natural","amount":200,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortarlo por la mitad a lo largo.","Retirar las semillas del pepino con una cuchara y rallarlo en trozos gruesos.","Colocar el pepino rallado en un colador, añadir sal y dejar reposar 10 min para que suelte el agua.","Picar ajo muy fino.","Picar menta fresca fina.","Escurrir el pepino con las manos para eliminar el máximo de agua posible.","Mezclar yogur griego natural con el pepino escurrido, el ajo picado y la menta picada en un bol.","Añadir aceite de oliva y remover hasta integrar.","Tapar el bol y refrigerar al menos 20 min hasta que esté bien fría.","Servir la ensalada fría directamente del bol."}', 'Ensalada fría de pepino con yogur y menta, ideal para el calor.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_074', 'Ensalada de naranja, hinojo y aceitunas negras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'invierno', 232, 2, 25, 14, 2, true, true, '{}', '[{"name":"Naranja","amount":300,"unit":"g"},{"name":"Hinojo","amount":200,"unit":"g"},{"name":"Aceitunas negras","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar naranja retirando también la piel blanca.","Cortar la naranja pelada en rodajas finas.","Limpiar hinojo y retirar la parte más dura de la base.","Laminar el hinojo en láminas muy finas, preferiblemente con mandolina.","Disponer las rodajas de naranja y las láminas de hinojo alternadas en una fuente.","Repartir aceitunas negras por encima de la naranja y el hinojo.","Aliñar con aceite de oliva y sal.","Dejar reposar en la nevera hasta que los sabores se mezclen.","Servir la ensalada fría directamente de la nevera."}', 'Ensalada de naranja, hinojo y aceitunas negras, fresca y de inspiración mediterránea.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_075', 'Ensalada de alcachofas confitadas y jamón', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'invierno', 271, 16, 9, 19, 2, true, false, '{"sulfitos"}', '[{"name":"Corazones de alcachofa","amount":300,"unit":"g"},{"name":"Jamón serrano en virutas","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":120,"unit":"ml"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Tomillo fresco","amount":5,"unit":"g"},{"name":"Limón","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar ajo.","Escurrir corazones de alcachofa y secarlos con papel de cocina.","Colocar los corazones de alcachofa en un cazo pequeño junto con aceite de oliva, el ajo laminado y tomillo fresco.","Confitar a fuego suave hasta que los corazones de alcachofa estén muy tiernos y el aceite no llegue a hervir.","Escurrir los corazones de alcachofa del aceite y reservar un chorrito del aceite de confitar.","Dejar templar los corazones de alcachofa escurridos.","Repartir los corazones de alcachofa en una fuente.","Distribuir jamón serrano en virutas por encima de las alcachofas.","Rociar con el aceite de confitar reservado y limón."}', 'Ensalada de alcachofas confitadas con virutas de jamón serrano.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_076', 'Ensalada de aguacate, tomate y maíz con lima', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 344, 5, 27, 24, 2, true, true, '{}', '[{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Maíz dulce cocido","amount":160,"unit":"g"},{"name":"Cebolla roja","amount":40,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar aguacate por la mitad, retirar el hueso y cortarlo en dados de tamaño uniforme.","Cortar tomate en dados del mismo tamaño que el aguacate.","Escurrir maíz dulce cocido y reservar.","Picar cebolla roja muy fina.","Picar cilantro fresco fino.","Mezclar en un bol el aguacate, el tomate, el maíz, la cebolla roja y el cilantro picado.","Aliñar con lima, aceite de oliva y sal.","Remover con cuidado hasta que el aliño cubra todos los ingredientes sin deshacer el aguacate.","Servir enseguida para que el aguacate no se oxide."}', 'Ensalada fresca de aguacate, tomate y maíz con un toque de lima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_077', 'Ensalada de col kale con manzana y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 330, 8, 19, 25, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Col kale","amount":150,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar col kale, retirar el tallo central duro y cortar en tiras finas.","Masajear el kale con sal y un chorrito de aceite de oliva virgen extra durante 1-2 min hasta que se ablande y oscurezca ligeramente.","Lavar manzana, descorazonar y laminar en láminas finas.","Rociar la manzana laminada con zumo de limón para evitar la oxidación.","Calentar sartén a fuego medio sin aceite y tostar nueces 2-3 min, removiendo, hasta que estén doradas y aromáticas.","Retirar las nueces de la sartén y dejar enfriar sobre una superficie plana.","Mezclar en un bol el aceite de oliva virgen extra restante, el zumo de limón restante y miel hasta obtener el aliño.","Rallar queso parmesano en virutas finas con un pelador o rallador.","Disponer el kale masajeado en un bol grande y añadir la manzana laminada.","Verter el aliño sobre la ensalada y remover con cuidado hasta cubrir bien.","Repartir las nueces tostadas y el queso parmesano en virutas por encima y servir."}', 'Ensalada de col kale masajeada con manzana crujiente, nueces tostadas y virutas de parmesano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_078', 'Ensalada de espárragos blancos y salmón ahumado', 'ensaladas_verduras', 'pescado_azul', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 210, 15, 7, 14, 2, true, false, '{"pescado","mostaza"}', '[{"name":"Espárragos blancos en conserva","amount":300,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Mostaza de Dijon","amount":5,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir espárragos blancos en conserva y secarlos con papel de cocina.","Lavar rúcula y secarla con papel de cocina.","Mezclar aceite de oliva virgen extra, zumo de limón, mostaza de dijon y sal en un bol pequeño hasta emulsionar.","Cortar salmón ahumado en lonchas del tamaño de un bocado.","Picar eneldo fresco finamente.","Repartir la rúcula como base en 2 platos.","Colocar los espárragos sobre la rúcula, distribuyéndolos de forma uniforme entre los 2 platos.","Disponer el salmón entre los espárragos en cada plato.","Rociar cada plato con el aliño justo antes de servir.","Espolvorear el eneldo picado sobre cada plato y servir de inmediato."}', 'Espárragos blancos tiernos con salmón ahumado, rúcula y un aliño ligero de mostaza y eneldo.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_079', 'Ensalada tibia de coliflor asada y tahini', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 290, 9, 17, 21, 2, true, true, '{"sesamo"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Tahini","amount":40,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar coliflor en ramilletes de tamaño similar para que se asen de manera uniforme.","Picar ajo muy fino.","Picar perejil fresco fino y reservar.","Disponer los ramilletes en una bandeja de horno en una sola capa.","Mezclar los ramilletes con aceite de oliva, comino molido, pimentón dulce y sal hasta cubrirlos bien.","Hornear 25 min hasta que los bordes estén dorados y la coliflor tierna, removiendo a mitad de cocción.","Mezclar tahini, zumo de limón, el ajo picado y agua hasta obtener una salsa cremosa y homogénea.","Retirar la coliflor del horno y disponer en una fuente.","Rociar la salsa de tahini sobre la coliflor asada.","Terminar con el perejil fresco picado y servir templada."}', 'Arbolitos de coliflor asados hasta dorarse, bañados en una salsa cremosa de tahini y limón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_080', 'Ensalada de garbanzos, atún y pimientos', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 520, 35, 47, 22, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y reservar en un bol grande.","Escurrir atún en conserva y desmigar con un tenedor hasta obtener lascas sueltas.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Picar cebolla morada muy fina.","Cortar tomate en dados medianos.","Picar perejil fresco fino y reservar.","Añadir el atún desmigado, los pimientos, la cebolla morada, el tomate y aceitunas negras al bol con los garbanzos.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover con cuidado hasta que el aliño se distribuya sin romper los garbanzos.","Tapar el bol y reposar en la nevera hasta que los sabores se integren.","Espolvorear el perejil picado por encima y servir frío."}', 'Ensalada contundente de garbanzos con atún, pimientos y aceitunas, perfecta para llevar de tupper.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_081', 'Ensalada de pasta fría mediterránea', 'ensaladas_verduras', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'verano', 520, 18, 55, 26, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Fusilli","amount":140,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Mozzarella (bocconcini)","amount":80,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con abundante agua y sal.","Cocer fusilli en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del envase.","Cortar tomate cherry por la mitad.","Cortar pepino en dados.","Cortar pimiento rojo en tiras finas.","Cortar mozzarella (bocconcini) en dados.","Escurrir los fusilli y refrescar bajo agua fría hasta que estén completamente fríos.","Escurrir bien los fusilli y reservar en un bol grande.","Añadir el tomate cherry, el pepino, el pimiento rojo, aceitunas negras y la mozzarella al bol.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Deshojar albahaca fresca con las manos y añadir al bol.","Remover con suavidad hasta integrar todos los ingredientes.","Tapar el bol y refrigerar en la nevera hasta que la ensalada esté bien fría.","Servir la ensalada fría directamente del bol o repartir en platos."}', 'Pasta fría con tomate cherry, mozzarella, pimiento y albahaca, ideal para el calor del verano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_082', 'Ensalada de melón y jamón', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 265, 18, 20, 13, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Melón","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Reducción de vinagre balsámico","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar melón en dados de unos 2 cm, retirando antes la piel y las semillas.","Rallar queso parmesano en virutas finas con un pelador o rallador grueso.","Lavar rúcula bajo agua fría y secar bien con papel de cocina.","Repartir la rúcula seca en la base de 2 platos.","Colocar los dados de melón sobre la rúcula, distribuyéndolos de forma uniforme.","Enrollar jamón serrano en cilindros y disponerlos entre los dados de melón.","Añadir las virutas de queso parmesano por encima.","Rociar con aceite de oliva virgen extra y reducción de vinagre balsámico.","Servir de inmediato, bien frío."}', 'El clásico contraste dulce y salado de melón fresco con jamón serrano y virutas de parmesano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_083', 'Ensalada de endivias, roquefort y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 385, 12, 14, 32, 2, false, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Endivias","amount":300,"unit":"g"},{"name":"Queso roquefort","amount":60,"unit":"g"},{"name":"Nueces","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Separar las hojas de endivias, lavarlas bajo agua fría y secarlas bien con papel de cocina.","Calentar sartén a fuego medio sin aceite y tostar nueces hasta que estén doradas, sin dejar de remover.","Retirar las nueces de la sartén y trocearlas groseramente con un cuchillo.","Mezclar aceite de oliva, vinagre de jerez, miel y sal en un bol pequeño hasta emulsionar.","Disponer las hojas de endivias en forma de barco en una fuente o plato.","Desmenuzar queso roquefort en trozos irregulares sobre las hojas de endivias.","Repartir las nueces troceadas sobre la ensalada.","Rociar la ensalada con el aliño justo antes de servir y servir enseguida para conservar la textura crujiente."}', 'Hojas de endivia en barco con queso roquefort desmenuzado, nueces tostadas y un aliño de miel y mostaza.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_084', 'Ensalada de aguacate y langostinos al curry', 'ensaladas_verduras', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 455, 25, 11, 36, 2, true, false, '{"marisco","huevo"}', '[{"name":"Langostinos pelados","amount":200,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Curry en polvo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Canónigos","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar langostinos pelados con sal.","Calentar sartén con aceite de oliva a fuego fuerte.","Saltear los langostinos 2-3 min hasta que estén rosados y reservar para que enfríen.","Mezclar mayonesa con curry en polvo y zumo de limón hasta obtener una salsa homogénea.","Cortar aguacate por la mitad, deshuesar y cortar en dados.","Rociar los dados de aguacate con el zumo de limón restante para que no se oxiden.","Cortar tomate cherry por la mitad.","Repartir canónigos como base en los platos.","Colocar encima los dados de aguacate y los langostinos fríos.","Añadir los tomates cherry sobre la ensalada.","Napar con la salsa de curry o servirla aparte en un cuenco."}', 'Langostinos salteados con aguacate cremoso y una suave salsa de curry, fresca y elegante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_085', 'Ensalada de remolacha, naranja y aceitunas negras', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'invierno', 258, 4, 32, 13, 2, true, true, '{"sulfitos"}', '[{"name":"Remolacha cocida","amount":250,"unit":"g"},{"name":"Naranja","amount":300,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Laminar cebolla morada en aros muy finos.","Cortar remolacha cocida en dados o láminas uniformes.","Pelar naranja a lo vivo, retirando toda la piel blanca.","Cortar las naranjas en rodajas o gajos.","Repartir rúcula como base en una fuente amplia.","Disponer la remolacha y los gajos de naranja sobre la rúcula.","Repartir la cebolla morada laminada por encima.","Distribuir aceitunas negras por toda la ensalada.","Mezclar aceite de oliva virgen extra, vinagre de jerez y sal en un bol pequeño.","Aliñar la ensalada con la mezcla y servir de inmediato."}', 'Remolacha y naranja en una combinación muy vistosa, con aceitunas negras y un aliño sencillo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_086', 'Ensalada de tomate cherry, mozzarella y albahaca', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 355, 16, 9, 28, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Tomate cherry","amount":300,"unit":"g"},{"name":"Mozzarella fresca","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar tomate cherry bajo el grifo y escurrir bien.","Cortar cada tomate cherry por la mitad y reservar.","Escurrir mozzarella fresca y cortar en dados de unos 2 cm.","Lavar albahaca fresca, secar con papel de cocina y reservar las hojas enteras.","Disponer los tomates cherry y la mozzarella en una fuente, alternando los trozos.","Repartir las hojas de albahaca por encima.","Aliñar con aceite de oliva virgen extra y vinagre balsámico.","Añadir sal y servir de inmediato a temperatura ambiente."}', 'Bocados de tomate cherry y mozzarella fresca con albahaca, sencilla y llena de color.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_087', 'Ensalada de pollo, mango y aguacate', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 470, 42, 28, 24, 2, true, false, '{"soja"}', '[{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Mango","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mezclum de lechugas","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Zumo de lima","amount":20,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar pechuga de pollo por ambas caras con sal.","Calentar plancha a fuego fuerte con aceite de oliva.","Cocinar la pechuga de pollo 6 min por cada lado hasta que esté bien hecha.","Pelar mango y cortarlo en dados.","Laminar cebolla morada muy fina.","Mezclar zumo de lima, salsa de soja, miel y el aceite de oliva restante en un bol hasta integrar.","Retirar la pechuga de la plancha y dejar reposar 3 min.","Cortar la pechuga en tiras.","Cortar aguacate por la mitad, deshuesar y laminar.","Rociar las láminas de aguacate con un poco del zumo de lima del aliño para evitar que se oxide.","Repartir mezclum de lechugas como base en 2 platos.","Disponer sobre la base las tiras de pollo, el mango y el aguacate.","Añadir la cebolla morada laminada sobre la ensalada.","Rociar con el aliño justo antes de servir."}', 'Ensalada contundente de pollo a la plancha con mango dulce y aguacate cremoso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_088', 'Ensalada de burrata con miel, pistachos y guindilla', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 448, 19, 13, 36, 2, false, false, '{"lactosa","frutos_secos"}', '[{"name":"Burrata","amount":200,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Pistachos","amount":30,"unit":"g"},{"name":"Guindilla fresca","amount":2,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal en escamas","amount":2,"unit":"g"}]'::jsonb, '{"Retirar burrata de la nevera y dejar reposar a temperatura ambiente.","Picar guindilla fresca en rodajas muy finas y reservar.","Cortar pistachos groseramente con un cuchillo y reservar.","Repartir rúcula en una fuente o en 2 platos individuales.","Colocar la burrata entera o partida por la mitad sobre la rúcula.","Rociar miel sobre la burrata.","Repartir los pistachos y la guindilla picada por encima.","Terminar con aceite de oliva virgen extra y sal en escamas, y servir enseguida."}', 'Burrata cremosa con miel, pistachos crujientes y un toque picante de guindilla fresca.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('ensaladas_verduras_089', 'Ensalada de orzo con feta, pepino y aceitunas', 'ensaladas_verduras', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 515, 18, 51, 28, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Orzo","amount":130,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceitunas negras (kalamata)","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua abundante y sal.","Cocer orzo en el agua hirviendo hasta que esté al dente, siguiendo el tiempo del envase.","Cortar pepino en dados pequeños.","Cortar tomate cherry por la mitad.","Picar cebolla morada muy fina.","Desmenuzar queso feta en trozos irregulares.","Escurrir el orzo cocido y refrescar bajo agua fría hasta que esté completamente frío.","Escurrir bien el orzo y trasladar a un bol grande.","Añadir el pepino, el tomate cherry, la cebolla morada y aceitunas negras (kalamata) al bol.","Añadir aceite de oliva virgen extra, zumo de limón y orégano seco.","Remover con suavidad hasta que todo quede bien aliñado.","Añadir el queso feta desmenuzado y remover con cuidado para no romperlo demasiado.","Tapar el bol y refrigerar hasta que la ensalada esté bien fría y los sabores integrados.","Servir la ensalada fría directamente del bol."}', 'Orzo frío con queso feta, pepino y aceitunas, brillante de aceite de oliva.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_090', 'Berenjenas a la parmesana', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 555, 26, 45, 29, 4, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Berenjena","amount":600,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Pan rallado","amount":80,"unit":"g"},{"name":"Salsa de tomate","amount":400,"unit":"g"},{"name":"Mozzarella rallada","amount":200,"unit":"g"},{"name":"Queso parmesano rallado","amount":60,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar berenjena en rodajas de 0,5 cm de grosor.","Salar las rodajas de berenjena con sal y disponerlas en un colador.","Dejar reposar las rodajas saladas hasta que suelten el amargor.","Secar las rodajas de berenjena con papel de cocina presionando suavemente.","Batir huevo en un bol hondo hasta que esté homogéneo.","Preparar 3 platos: uno con harina, uno con el huevo batido y uno con pan rallado.","Pasar cada rodaja de berenjena primero por la harina, cubriéndola por ambos lados.","Pasar cada rodaja enharinada por el huevo batido y después por el pan rallado.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Freír las rodajas rebozadas por tandas hasta que estén doradas por ambos lados.","Escurrir las rodajas fritas sobre papel absorbente y reservar.","Precalentar el horno a 190 °C.","Cubrir el fondo de una fuente de horno con una capa fina de salsa de tomate.","Disponer una capa de rodajas de berenjena rebozadas sobre la salsa de tomate.","Cubrir la capa de berenjena con salsa de tomate, mozzarella rallada y queso parmesano rallado.","Repetir las capas hasta agotar los ingredientes, acabando con salsa de tomate, mozzarella y parmesano.","Hornear la fuente en el horno a 190 °C hasta que el queso esté fundido y dorado.","Retirar la fuente del horno y dejar reposar antes de servir.","Repartir en platos y decorar con albahaca fresca por encima."}', 'Capas de berenjena rebozada gratinadas con salsa de tomate, mozzarella y parmesano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_091', 'Pisto con huevo frito por encima', 'ensaladas_verduras', 'huevo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'verano', 295, 10, 17, 21, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Huevo","amount":100,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en dados pequeños.","Pelar y picar ajo fino.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Cortar calabacín en dados pequeños.","Hacer un corte en cruz en la base de tomate maduro y sumergir en agua hirviendo 30 s hasta que la piel se despegue.","Retirar el tomate, pelar y cortar en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén translúcidos.","Añadir el pimiento rojo y el pimiento verde en dados y sofreír hasta que estén tiernos.","Añadir el calabacín en dados y sofreír hasta que esté tierno.","Añadir el tomate en dados y sal; remover para integrar.","Cocer a fuego suave hasta que el pisto esté meloso y sin exceso de agua.","Calentar aceite de oliva en otra sartén a fuego fuerte.","Freír huevo hasta que la clara esté cuajada y la yema quede jugosa.","Repartir el pisto en 2 platos y colocar un huevo frito encima de cada uno."}', 'Pisto de verduras bien meloso coronado con un huevo frito de yema jugosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_092', 'Coliflor asada entera con tahini y granada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 270, 8, 21, 18, 4, true, true, '{"sesamo"}', '[{"name":"Coliflor entera","amount":1000,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Cúrcuma","amount":3,"unit":"g"},{"name":"Tahini","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":30,"unit":"ml"},{"name":"Agua","amount":40,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Granada (arilos)","amount":100,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Retirar las hojas exteriores de coliflor entera, dejando el tallo intacto para que se sostenga.","Mezclar aceite de oliva, comino molido, pimentón dulce, cúrcuma y sal en un bol pequeño.","Pincelar toda la coliflor con la mezcla de especias, cubriendo bien las hendiduras entre los ramilletes.","Colocar la coliflor en una bandeja de horno y tapar con papel de aluminio.","Hornear tapada a 200 °C durante 30 min.","Picar ajo muy fino.","Mezclar tahini, zumo de limón, agua y el ajo picado en un bol hasta obtener una salsa cremosa y homogénea.","Picar perejil fresco fino y reservar.","Retirar el papel de aluminio y hornear 25 min más, hasta que la coliflor esté tierna por dentro y dorada por fuera.","Sacar la coliflor del horno y trasladarla a una fuente de servir.","Rociar la coliflor generosamente con la salsa de tahini.","Repartir granada (arilos) y el perejil picado por encima y servir entera para trocear en la mesa."}', 'Coliflor entera asada hasta dorarse, bañada en salsa de tahini y coronada con granada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_093', 'Calabacines rellenos de quinoa y verduras', 'ensaladas_verduras', 'none', 'quinoa', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 390, 17, 44, 16, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Quinoa","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":40,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Añadir quinoa al cazo y cocer a fuego medio hasta que esté tierna y haya absorbido el agua.","Precalentar el horno a 190 °C.","Cortar calabacín por la mitad a lo largo.","Vaciar la pulpa de cada mitad de calabacín con una cuchara, dejando una base de 1 cm.","Picar la pulpa de calabacín reservada en dados pequeños.","Picar cebolla y ajo finos.","Cortar pimiento rojo y tomate en dados pequeños.","Escurrir la quinoa cocida y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo hasta que estén translúcidos.","Añadir el pimiento rojo y la pulpa de calabacín picada y sofreír a fuego medio.","Incorporar el tomate y maíz dulce a la sartén y remover bien.","Añadir la quinoa escurrida y orégano seco a la sartén y mezclar hasta integrar.","Retirar la sartén del fuego y salpimentar el relleno al gusto.","Disponer las mitades de calabacín en una bandeja de horno con la cavidad hacia arriba.","Rellenar cada mitad de calabacín con el sofrito de quinoa y verduras.","Cubrir cada calabacín relleno con queso rallado repartido a partes iguales.","Hornear a 190 °C durante 22 min hasta que el calabacín esté tierno y el queso gratinado.","Servir templado, 2 mitades de calabacín por ración."}', 'Barcas de calabacín rellenas de quinoa y verduras, gratinadas con queso por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_094', 'Setas al horno con ajo y perejil', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 195, 7, 10, 15, 2, true, true, '{}', '[{"name":"Setas (champiñones portobello)","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Limpiar setas (champiñones portobello) con un paño húmedo, sin mojarlas bajo el grifo.","Picar ajo muy fino.","Picar perejil fresco muy fino.","Mezclar en un bol el ajo picado, el perejil picado, aceite de oliva virgen extra y sal.","Colocar las setas en una bandeja de horno con la parte hueca hacia arriba.","Repartir la mezcla de ajo y perejil sobre cada seta hasta que queden bien impregnadas.","Hornear en la bandeja central hasta que las setas estén doradas y hayan soltado su jugo.","Retirar la bandeja del horno y regar las setas con el jugo que hayan soltado.","Servir las setas calientes, recién salidas del horno."}', 'Setas doradas al horno con ajo y perejil, jugosas y con aroma a ajo tostado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_095', 'Espárragos trigueros a la brasa con romesco', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'plancha', 35, 'facil', 'all', 505, 10, 21, 43, 2, true, true, '{"frutos_secos","gluten","sulfitos"}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Pimiento choricero (pulpa)","amount":20,"unit":"g"},{"name":"Almendras","amount":30,"unit":"g"},{"name":"Avellanas","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":55,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Calentar plancha a fuego fuerte hasta que esté bien caliente.","Tostar almendras y avellanas en una sartén sin aceite a fuego medio hasta que estén doradas.","Retirar las almendras y avellanas tostadas de la sartén y reservar.","Calentar aceite de oliva virgen extra en la misma sartén a fuego medio.","Freír pan frito en el aceite caliente hasta que esté dorado y crujiente.","Retirar el pan frito y reservar. Añadir tomate a la misma sartén.","Asar el tomate a fuego medio hasta que esté blando y la piel se despegue.","Pelar el tomate asado cuando esté templado y reservar.","Pelar ajo y reservar.","Triturar en una batidora el tomate pelado, pimiento choricero (pulpa), las almendras y avellanas tostadas, el ajo, el pan frito y vinagre de jerez.","Añadir el aceite de oliva virgen extra restante poco a poco mientras se tritura hasta obtener una salsa espesa y homogénea.","Añadir sal a la salsa romesco y triturar brevemente. Reservar.","Limpiar espárragos trigueros retirando la parte final más dura del tallo.","Pincelar los espárragos con un chorrito de aceite de oliva virgen extra.","Asar los espárragos en la plancha caliente hasta que estén tiernos con marcas de brasa, dándoles la vuelta a mitad.","Servir los espárragos calientes con la salsa romesco napada por encima o aparte."}', 'Espárragos trigueros marcados a la plancha sobre una salsa romesco espesa de frutos secos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_096', 'Repollo braseado con miso y sésamo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 220, 5, 17, 15, 2, true, true, '{"soja","sesamo"}', '[{"name":"Repollo","amount":400,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Miso","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Sésamo tostado","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Agua","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar repollo en gajos gruesos, dejando parte del tronco para que no se deshagan.","Picar ajo y jengibre fresco muy finos.","Calentar aceite de oliva y aceite de sésamo en sartén amplia a fuego medio-alto.","Colocar los gajos de repollo en sartén y dorar 3 min por cada lado hasta que tomen color.","Mezclar miso con salsa de soja y agua en un bol hasta que se disuelva bien.","Añadir el ajo picado y el jengibre picado a la mezcla de miso y remover para integrar.","Verter la mezcla de miso sobre los gajos de repollo, tapar la sartén y cocer a fuego suave.","Cocer tapado a fuego suave hasta que el repollo esté tierno y caramelizado.","Destapar y subir a fuego medio hasta que el líquido reduzca y quede una salsa espesa.","Servir los gajos de repollo espolvoreados con sésamo tostado."}', 'Gajos de repollo braseados hasta caramelizarse, con una glasa de miso y sésamo tostado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_097', 'Zanahorias asadas enteras con comino y yogur', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 235, 7, 26, 13, 2, true, true, '{"lactosa"}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar zanahoria bajo el grifo y secar con papel de cocina.","Cortar las zanahorias en mitades a lo largo si son gruesas; dejarlas enteras si son finas.","Mezclar en un bol aceite de oliva, comino molido, miel y sal hasta integrar.","Disponer las zanahorias en una bandeja de horno y verter la mezcla de aceite y especias por encima.","Remover las zanahorias en la bandeja hasta que queden bien impregnadas de la mezcla.","Hornear las zanahorias durante 25 min, dándoles la vuelta a los 12 min, hasta que estén tiernas y caramelizadas.","Rallar ajo muy fino sobre un bol pequeño.","Añadir yogur griego, zumo de limón y sal al bol con el ajo rallado.","Mezclar el yogur, el ajo, el zumo de limón y la sal hasta obtener una salsa homogénea.","Picar perejil fresco fino y reservar.","Extender la salsa de yogur en la base de una fuente de servir.","Colocar las zanahorias asadas encima de la salsa de yogur.","Terminar con el perejil picado por encima y servir templado."}', 'Zanahorias enteras asadas con comino sobre una base cremosa de yogur y ajo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_098', 'Puerros confitados con vinagreta de mostaza', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 355, 3, 29, 26, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Puerro","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Mostaza de Dijon","amount":15,"unit":"g"},{"name":"Vinagre de jerez","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Retirar las capas exteriores y la parte verde más dura de puerro.","Cortar los puerros en trozos de 6-8 cm.","Lavar los trozos de puerro bajo el grifo hasta eliminar toda la tierra entre las capas.","Colocar los trozos de puerro en una cazuela baja y cubrir con aceite de oliva hasta la mitad de su altura.","Confitar a fuego suave, con el aceite apenas burbujeando, hasta que los puerros estén muy tiernos al pincharlos.","Escurrir los puerros del aceite y reservar 2 cucharadas del aceite de confitar en un bol aparte.","Dejar templar los puerros escurridos.","Picar perejil fresco fino y reservar.","Añadir mostaza de dijon, vinagre de jerez y sal al bol con el aceite de confitar reservado.","Mezclar enérgicamente hasta obtener una vinagreta homogénea.","Disponer los puerros templados en una fuente y rociar con la vinagreta de mostaza.","Terminar con el perejil fresco picado y servir templado o a temperatura ambiente."}', 'Puerros confitados hasta quedar tiernos, con una vinagreta de mostaza con carácter.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_099', 'Calabaza asada con tahini y granada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 262, 5, 21, 18, 2, true, true, '{"sesamo"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Canela molida","amount":1,"unit":"g"},{"name":"Tahini","amount":30,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Agua","amount":15,"unit":"ml"},{"name":"Granada (arilos)","amount":50,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortarla en gajos grandes.","Mezclar los gajos de calabaza con aceite de oliva, comino molido, canela molida y sal.","Repartir los gajos de calabaza en una bandeja de horno en una sola capa.","Hornear durante 30 min hasta que la calabaza esté tierna y dorada por los bordes.","Dar la vuelta a los gajos de calabaza a mitad de cocción.","Mezclar tahini con zumo de limón, agua y sal hasta obtener una salsa cremosa.","Picar perejil fresco fino.","Disponer los gajos de calabaza en una fuente.","Rociar la calabaza con la salsa de tahini.","Añadir granada (arilos) y el perejil fresco picado. Servir templada."}', 'Calabaza asada dulce y tierna, bañada en salsa de tahini y coronada con granada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_100', 'Berenjenas a la miso (nasu dengaku)', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 235, 6, 22, 15, 2, false, true, '{"soja","sesamo"}', '[{"name":"Berenjena","amount":400,"unit":"g"},{"name":"Miso blanco","amount":40,"unit":"g"},{"name":"Mirin","amount":30,"unit":"ml"},{"name":"Azúcar moreno","amount":15,"unit":"g"},{"name":"Aceite de sésamo","amount":15,"unit":"ml"},{"name":"Semillas de sésamo","amount":8,"unit":"g"},{"name":"Cebolleta","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con función grill.","Cortar berenjena por la mitad a lo largo.","Hacer cortes en rombo en la carne de cada mitad sin llegar a la piel.","Pincelar la carne de las berenjenas con la mitad de aceite de sésamo.","Colocar las berenjenas boca abajo en una bandeja de horno.","Hornear 20 min hasta que la carne esté tierna.","Picar cebolleta en rodajas finas y reservar.","Calentar en un cazo miso blanco, mirin, azúcar moreno y el resto del aceite de sésamo a fuego suave.","Remover sin parar hasta que el glaseado sea brillante y homogéneo, unos 3 min.","Dar la vuelta a las berenjenas y pincelar generosamente la carne con el glaseado de miso.","Gratinar con el grill 3 min hasta que el glaseado burbujee y se oscurezca sin quemarse.","Espolvorear semillas de sésamo sobre las berenjenas.","Espolvorear la cebolleta picada y servir templadas."}', 'Berenjenas asadas con un glaseado de miso oscuro y brillante, dulce y salado a la vez, gratinado hasta caramelizar.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_101', 'Coles de Bruselas laqueadas con miel picante', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'invierno', 165, 5, 22, 7, 2, false, true, '{}', '[{"name":"Coles de Bruselas","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Guindilla en copos","amount":2,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Limpiar coles de bruselas y cortar cada una por la mitad.","Picar ajo muy fino.","Colocar las coles en una bandeja, añadir aceite de oliva y sal y mezclar hasta que queden bien impregnadas.","Hornear las coles a 200 °C durante 22 min hasta que estén doradas y crujientes por fuera.","Mezclar en un bol el ajo picado, miel, guindilla en copos y zumo de limón.","Remover la bandeja a mitad de la cocción para que las coles se doren de forma uniforme.","Calentar la mezcla de miel en una sartén a fuego medio durante 2 min hasta que espese ligeramente.","Verter el laqueado sobre las coles recién salidas del horno.","Remover bien para que las coles queden cubiertas con el laqueado.","Servir las coles calientes de inmediato."}', 'Coles de Bruselas asadas hasta quedar crujientes y laqueadas con un glaseado de miel picante, brillante y pegajoso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_102', 'Alcachofas fritas a la judía', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'invierno', 290, 6, 16, 22, 2, true, false, '{}', '[{"name":"Alcachofas","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores más duras de alcachofas y cortar la punta y el tallo de cada una.","Exprimir limón y verter el zumo en un bol con agua fría.","Sumergir las alcachofas limpias en el agua con zumo de limón hasta tenerlas todas listas.","Calentar aceite de oliva en una cazuela honda a fuego medio hasta alcanzar 160 °C.","Sacar las alcachofas del agua y secar bien cada una con papel absorbente.","Golpear suavemente cada alcachofa boca abajo contra la encimera para abrir las hojas.","Freír las alcachofas boca abajo en el aceite caliente durante 10 min, hasta que estén tiernas al pincharlas.","Subir el fuego a fuego fuerte y freír 3 min más hasta que las hojas exteriores estén crujientes y doradas.","Escurrir las alcachofas sobre papel absorbente y salar con sal al momento.","Picar perejil fino.","Servir las alcachofas calientes con el perejil picado por encima y gajos del limón restante al lado."}', 'Alcachofas fritas enteras hasta que las hojas quedan doradas y crujientes por fuera, tiernas por dentro; se comen con las manos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_103', 'Tomates rellenos de arroz y verduras al horno', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'verano', 265, 8, 38, 9, 2, true, true, '{"lactosa"}', '[{"name":"Tomates grandes","amount":4,"unit":"ud"},{"name":"Arroz","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Calabacín","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Caldo de verduras","amount":100,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar la tapa superior de tomates grandes y vaciar la pulpa con una cuchara.","Reservar la pulpa de tomate picada en un bol.","Picar cebolla, calabacín, pimiento rojo y ajo en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el calabacín, el pimiento rojo y el ajo hasta que ablanden.","Añadir arroz y remover para que se impregne del sofrito.","Añadir la pulpa de tomate reservada y sofreír el conjunto.","Rellenar los tomates vaciados con la mezcla de arroz y verduras.","Colocar los tomates rellenos en una fuente de horno.","Verter caldo de verduras en el fondo de la fuente.","Cubrir cada tomate con queso rallado.","Hornear la fuente a 190 °C hasta que el arroz esté cocido y los tomates arrugados.","Picar perejil fino.","Espolvorear el perejil picado sobre los tomates y servir templados."}', 'Tomates asados con la piel arrugada y dulce, rellenos de un arroz colorido con verduras que se descubre al cortarlos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_104', 'Champiñones portobello rellenos gratinados', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 320, 18, 12, 22, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Champiñones portobello","amount":4,"unit":"ud"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Limpiar champiñones portobello con un paño húmedo y retirar el pie de cada uno.","Picar fino el pie de los champiñones y reservar.","Picar fino ajo.","Picar fino perejil y reservar.","Cortar jamón serrano en taquitos pequeños y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado en la sartén hasta que esté dorado, sin que se queme.","Añadir el pie de champiñón picado y sofreír hasta que evapore el agua y esté tierno.","Retirar la sartén del fuego y dejar que el sofrito temple 2 min.","Desmenuzar queso de cabra en un bol.","Añadir al bol el sofrito templado, el jamón en taquitos, pan rallado y el perejil picado.","Mezclar bien todos los ingredientes del bol hasta obtener un relleno homogéneo.","Disponer los sombreros de los champiñones boca arriba en una bandeja de horno.","Rellenar cada sombrero con la mezcla, presionando ligeramente para que quede compacta.","Cubrir cada champiñón relleno con queso rallado repartiéndolo de forma uniforme.","Hornear la bandeja en el horno a 200 °C durante 20 min, hasta que estén tiernos y gratinados.","Retirar la bandeja del horno y servir los champiñones calientes de inmediato."}', 'Sombreros grandes de champiñón portobello rellenos y gratinados, con presentación de plato único.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_105', 'Brócoli asado con ajo negro', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 190, 7, 12, 14, 2, true, true, '{"frutos_secos"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Ajo negro","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Almendras laminadas","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C.","Cortar brócoli en ramilletes de tamaño similar.","Laminar ajo.","Disponer el brócoli en una bandeja y añadir aceite de oliva, el ajo laminado y sal.","Mezclar bien para que el brócoli quede impregnado de aceite y especias.","Hornear en la bandeja central hasta que los bordes estén tostados y crujientes.","Machacar ajo negro con un chorrito de aceite de oliva hasta obtener una pasta homogénea.","Añadir zumo de limón a la pasta de ajo negro y mezclar hasta que quede una crema lisa.","Tostar almendras laminadas en sartén a fuego medio sin aceite hasta que se doren.","Retirar el brócoli del horno y disponerlo en la fuente de servicio.","Repartir la crema de ajo negro por encima del brócoli.","Esparcir las almendras tostadas y servir de inmediato."}', 'Brócoli asado con los bordes tostados y crujientes, coronado por el dulzor oscuro de una crema de ajo negro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_106', 'Escalivada con anchoas y aceite de oliva', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 60, 'facil', 'verano', 200, 7, 13, 14, 2, false, true, '{"pescado"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":300,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Anchoas en aceite","amount":40,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar berenjena, pimiento rojo y cebolla bajo el grifo y secar bien.","Disponer las verduras enteras y con piel sobre la bandeja del horno.","Hornear las verduras a 200 °C hasta que la piel esté ennegrecida y la carne muy tierna.","Picar ajo muy fino y reservar.","Retirar la bandeja del horno y tapar las verduras con un paño limpio.","Esperar tapadas hasta que suden y se pelen con facilidad.","Pelar las verduras retirando la piel ennegrecida.","Retirar las semillas y los tallos de la berenjena, el pimiento rojo y la cebolla.","Cortar la carne de las verduras en tiras longitudinales.","Disponer las tiras de verdura en una fuente alargada alternando colores.","Repartir anchoas en aceite sobre las verduras.","Añadir el ajo picado y distribuirlo de manera uniforme sobre la fuente.","Aliñar con aceite de oliva virgen extra y sal.","Reposar la escalivada a temperatura ambiente antes de servir."}', 'Verduras asadas de colores ahumados, en tiras, rematadas con anchoas saladas y un buen aceite de oliva.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_107', 'Espinacas con garbanzos a la andaluza', 'ensaladas_verduras', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 315, 14, 34, 14, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Pimentón","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan en dados pequeños.","Laminar ajo.","Calentar aceite de oliva en sartén a fuego medio.","Freír los dados de pan en el aceite caliente hasta que estén dorados y crujientes.","Retirar el pan frito con una espumadera y reservar en un plato.","Freír el ajo laminado en el mismo aceite a fuego medio hasta que se dore ligeramente.","Retirar el ajo frito y reservar junto al pan.","Machacar en un mortero el pan frito y el ajo frito reservados hasta obtener una pasta.","Añadir comino y pimentón al mortero y seguir machacando hasta integrar.","Incorporar un chorrito de agua al majado y mezclar hasta lograr una pasta homogénea.","Sofreír espinacas frescas en la misma sartén a fuego medio hasta que reduzcan su volumen.","Añadir garbanzos cocidos a las espinacas y remover para integrar.","Incorporar el majado a la sartén y remover bien hasta que todo quede integrado.","Añadir vinagre de jerez y remover.","Cocer a fuego suave hasta que la salsa espese ligeramente, removiendo de vez en cuando.","Servir caliente en platos hondos."}', 'Espinacas guisadas con garbanzos, majado de pan frito y especias, con el toque crujiente del pan y aroma andaluz.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_108', 'Pimientos del piquillo rellenos de brandada', 'ensaladas_verduras', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 335, 21, 18, 20, 2, false, true, '{"pescado","lactosa"}', '[{"name":"Pimientos del piquillo","amount":8,"unit":"ud"},{"name":"Bacalao desalado","amount":200,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos.","Picar ajo fino y reservar.","Picar perejil fino y reservar.","Colocar la patata troceada y bacalao desalado en un cazo. Cubrir con leche y llevar a ebullición a fuego medio.","Cocer a fuego suave hasta que la patata y el bacalao estén tiernos.","Escurrir la patata y el bacalao, reservando el líquido de cocción en un bol.","Precalentar el horno a 180 °C.","Triturar la patata escurrida y el bacalao escurrido con el ajo picado en un bol hasta obtener una pasta homogénea.","Añadir aceite de oliva en hilo fino mientras se remueve la pasta hasta ligarla en crema.","Añadir nata para cocinar y remover hasta obtener una brandada suave.","Añadir un poco del líquido de cocción reservado si la brandada resulta demasiado espesa, hasta ajustar la textura.","Rellenar pimientos del piquillo con la brandada con ayuda de una cuchara.","Colocar los pimientos rellenos en una fuente de horno y hornear a 180 °C hasta que estén bien calientes.","Servir los pimientos espolvoreados con el perejil picado."}', 'Pimientos del piquillo de un rojo brillante rellenos de una brandada cremosa de bacalao.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_109', 'Calabacín a la plancha con menta y feta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 220, 9, 8, 17, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Queso feta","amount":100,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Laminar calabacín en tiras longitudinales de 0,5 cm de grosor.","Calentar plancha a fuego fuerte con aceite de oliva.","Colocar las láminas de calabacín en la plancha y dorar 2 min por cada cara hasta que estén marcadas.","Retirar las láminas de calabacín y disponer en una fuente plana.","Desmenuzar queso feta con las manos sobre las láminas de calabacín.","Picar menta fresca y repartir sobre el plato.","Aliñar con aceite de oliva, zumo de limón, sal y pimienta.","Servir templado o a temperatura ambiente."}', 'Calabacín marcado a la plancha con el dorado bien visible, coronado con menta fresca y feta desmenuzado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_110', 'Remolacha asada entera con queso de cabra y avellanas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'invierno', 285, 10, 19, 19, 2, true, false, '{"lactosa","frutos_secos","sulfitos"}', '[{"name":"Remolacha","amount":400,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Queso de cabra","amount":100,"unit":"g"},{"name":"Avellanas tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre balsámico","amount":15,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Lavar remolacha bajo el grifo frotando bien la piel.","Envolver cada remolacha entera, con piel, en papel de aluminio formando un paquete cerrado.","Hornear los paquetes en la bandeja central durante 50 min, hasta que estén tiernas al pincharlas.","Mezclar aceite de oliva, vinagre balsámico y miel en un bol pequeño hasta emulsionar.","Picar avellanas tostadas groseramente con el cuchillo.","Retirar los paquetes del horno y dejar templar sin abrir durante 10 min.","Abrir el papel de aluminio y pelar las remolachas frotando la piel con un paño de cocina.","Cortar las remolachas en gajos.","Disponer rúcula en una fuente formando una base uniforme.","Colocar los gajos de remolacha sobre la rúcula.","Desmenuzar queso de cabra sobre la remolacha y repartir las avellanas picadas.","Aliñar con la mezcla de aceite, vinagre balsámico y miel justo antes de servir."}', 'Remolacha asada entera de un magenta intenso, servida con queso de cabra cremoso y avellanas tostadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_111', 'Verduras de temporada al vapor con vinagreta de cítricos', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 165, 5, 17, 9, 2, true, true, '{"mostaza"}', '[{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Brócoli","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Zumo de naranja","amount":60,"unit":"ml"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mostaza","amount":5,"unit":"g"},{"name":"Miel","amount":5,"unit":"g"}]'::jsonb, '{"Lavar y pelar zanahoria, luego cortar en rodajas de 0,5 cm.","Lavar judías verdes y retirar los extremos; cortar en trozos de 4 cm.","Lavar calabacín y brócoli; cortar el calabacín en medias lunas y el brócoli en ramilletes.","Llevar agua a ebullición en una olla con cesto de vapor a fuego fuerte.","Colocar la zanahoria y las judías verdes en el cesto; tapar y cocer al vapor hasta que estén tiernas pero firmes.","Mezclar zumo de naranja, zumo de limón, mostaza y miel en un bol hasta integrar.","Añadir aceite de oliva poco a poco al bol sin dejar de batir hasta emulsionar la vinagreta.","Retirar la zanahoria y las judías verdes del cesto; reservar en la fuente.","Colocar el calabacín y el brócoli en el cesto; tapar y cocer al vapor hasta que estén tiernos pero firmes.","Retirar el calabacín y el brócoli del cesto y añadir a la fuente junto al resto de las verduras.","Regar las verduras con la vinagreta de cítricos y servir templadas."}', 'Verduras de temporada al vapor que conservan sus colores intactos, despertadas con una vinagreta de cítricos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_112', 'Endivias braseadas con naranja y nueces', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'invierno', 215, 4, 18, 14, 2, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Endivias","amount":4,"unit":"ud"},{"name":"Naranja","amount":150,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Cortar endivias por la mitad a lo largo.","Exprimir naranja y reservar el zumo; separar el resto en gajos pelados al vivo.","Trocear nueces en trozos gruesos y reservar.","Calentar sartén a fuego medio y fundir mantequilla con aceite de oliva.","Colocar las endivias con el corte hacia abajo y dorar hasta que tomen color dorado.","Dar la vuelta a las endivias.","Añadir el zumo de naranja reservado, azúcar y sal.","Tapar la sartén y cocer a fuego suave hasta que las endivias estén tiernas.","Destapar y reducir el jugo a fuego medio hasta que espese ligeramente.","Servir las endivias con los gajos de naranja y las nueces troceadas por encima."}', 'Endivias braseadas con las hojas doradas por los bordes y el dulzor cítrico de la naranja.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_113', 'Setas confitadas al ajillo con perejil', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 230, 6, 7, 20, 2, true, true, '{}', '[{"name":"Setas variadas","amount":400,"unit":"g"},{"name":"Ajo","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Cortar las setas más grandes en trozos y dejar las pequeñas enteras.","Laminar ajo.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela a fuego suave hasta que esté caliente pero sin humear.","Añadir el ajo laminado y guindilla y sofreír a fuego suave hasta que el ajo aromatice sin dorarse.","Añadir las setas a la cazuela y remover para que se impregnen del aceite aromatizado.","Confitar las setas a fuego suave, tapado, removiendo de vez en cuando, hasta que estén tiernas.","Añadir sal al final de la cocción y remover.","Servir las setas templadas espolvoreadas con el perejil picado y un poco del aceite de la cocción."}', 'Setas confitadas a fuego lento en aceite de oliva y ajo, con el brillo del aceite y perejil fresco por encima.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_114', 'Calabaza rellena de arroz y verduras al horno', 'ensaladas_verduras', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, 'horno', 70, 'normal', 'invierno', 340, 10, 48, 12, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":800,"unit":"g"},{"name":"Arroz","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Calabacín","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":150,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar calabaza por la mitad a lo largo y retirar las semillas con una cuchara.","Salpimentar el interior de las mitades de calabaza.","Colocar las mitades de calabaza boca abajo en una bandeja con un dedo de agua.","Hornear la calabaza 25 min hasta que empiece a ablandarse.","Picar cebolla, pimiento rojo, calabacín, champiñones y ajo en trozos pequeños.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír la cebolla, el ajo, el pimiento rojo, el calabacín y los champiñones 6 min hasta que estén tiernos.","Añadir arroz al sofrito y remover 2 min para que se impregne.","Verter caldo de verduras y cocer a fuego medio 10 min hasta que el arroz esté casi al dente.","Picar perejil fino y reservar.","Retirar la calabaza del horno y girarla boca arriba con cuidado.","Rellenar las mitades de calabaza con el sofrito de arroz repartiéndolo a partes iguales.","Cubrir cada mitad con queso rallado a partes iguales.","Hornear 20 min hasta que la calabaza esté tierna y el queso se haya dorado.","Espolvorear el perejil picado sobre la calabaza y servir de inmediato."}', 'Media calabaza como fuente, rellena de un arroz de verduras colorido que se descubre al abrirla.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_115', 'Timbal de verduras y queso de cabra gratinado', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'verano', 260, 14, 12, 17, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Queso de cabra","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Laminar berenjena en rodajas finas de unos 3 mm.","Laminar calabacín en rodajas finas de unos 3 mm.","Laminar pimiento rojo en tiras finas.","Laminar tomate en rodajas finas de unos 3 mm.","Laminar queso de cabra en rodajas de unos 5 mm y reservar.","Disponer una primera capa de berenjena en 2 moldes individuales o en una fuente.","Añadir una capa de calabacín sobre la berenjena.","Añadir una capa de tomate sobre el calabacín.","Añadir una capa de pimiento rojo y salpimentar con sal y pimienta.","Repetir las capas hasta agotar las verduras, salpimentando entre cada capa.","Regar la superficie con aceite de oliva.","Tapar la fuente con papel de aluminio y hornear a 200 °C durante 30 min.","Retirar el papel de aluminio y colocar las rodajas de queso de cabra sobre las verduras.","Espolvorear orégano sobre el queso de cabra.","Hornear sin tapar a 200 °C con el gratinador encendido hasta que el queso se dore, unos 8 min.","Retirar del horno y dejar reposar 5 min antes de servir.","Servir el timbal caliente directamente en los moldes o desmoldado en el plato."}', 'Capas de verduras asadas visibles al cortar, coronadas con queso de cabra dorado y gratinado.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_116', 'Milhojas de berenjena, tomate y mozzarella', 'ensaladas_verduras', 'none', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'verano', 310, 18, 10, 22, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Tomate","amount":250,"unit":"g"},{"name":"Mozzarella fresca","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Cortar berenjena en láminas de 0,5 cm de grosor.","Salar las láminas de berenjena con sal y disponerlas en un colador.","Dejar reposar las láminas de berenjena 15 min para que suelten el amargor.","Cortar tomate en rodajas de 0,5 cm de grosor.","Cortar mozzarella fresca en rodajas de 0,5 cm de grosor.","Secar las láminas de berenjena con papel de cocina para eliminar la humedad.","Calentar plancha a fuego fuerte con aceite de oliva.","Marcar las láminas de berenjena hasta que se doren por ambos lados.","Precalentar el horno a 190 °C.","Montar el milhojas en una fuente de horno alternando capas de berenjena, tomate y mozzarella fresca.","Salpimentar el milhojas con pimienta y regar con un chorrito de aceite de oliva.","Hornear la fuente a 190 °C durante 15 min hasta que la mozzarella fresca funda.","Distribuir albahaca fresca por encima y regar con un hilo de aceite de oliva.","Servir el milhojas templado."}', 'Capas apiladas de berenjena, tomate y mozzarella fundida, con hilos de queso al partirlas.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_117', 'Ensalada templada de perdiz escabechada', 'ensaladas_verduras', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 70, 'normal', 'invierno', 385, 30, 6, 26, 2, false, false, '{"sulfitos"}', '[{"name":"Perdiz","amount":2,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Vinagre de vino","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":150,"unit":"ml"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Laurel","amount":2,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Hojas verdes variadas","amount":100,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Cortar zanahoria en rodajas y cebolla en rodajas.","Salpimentar perdiz por todos los lados con sal.","Calentar aceite de oliva en una cazuela a fuego fuerte.","Dorar las perdices en la cazuela hasta que estén doradas por todos los lados.","Retirar las perdices de la cazuela y reservar.","Sofreír la cebolla, la zanahoria y el ajo laminado en el mismo aceite a fuego medio hasta que estén blandos.","Añadir laurel y remover.","Devolver las perdices a la cazuela sobre las verduras.","Añadir vino blanco, vinagre de vino y el resto del aceite de oliva.","Tapar la cazuela y cocer a fuego suave hasta que la carne esté tierna.","Retirar la cazuela del fuego y dejar enfriar las perdices dentro del escabeche.","Deshuesar las perdices y trocear la carne en piezas generosas.","Colar el escabeche y reservar el líquido resultante.","Disponer hojas verdes variadas en la base de los platos.","Colocar los trozos de perdiz templada sobre las hojas verdes.","Regar con el escabeche colado y servir."}', 'Piezas de perdiz escabechadas y doradas sobre hojas frescas, con el brillo característico del escabeche.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
