insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('ensaladas_verduras_118', 'Croquetas de boletus', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 60, 'normal', 'invierno', 420, 12, 32, 26, 2, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Boletus","amount":200,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar boletus con un paño húmedo para retirar la tierra.","Picar los boletus en trozos pequeños y reservar.","Picar cebolla muy fina.","Picar ajo muy fino.","Fundir mantequilla en sartén a fuego suave.","Sofreír la cebolla picada y el ajo picado en la mantequilla fundida hasta que estén transparentes.","Añadir los boletus picados y saltear a fuego medio hasta que suelten el agua y esta se evapore.","Añadir harina sobre el sofrito y remover sin parar durante 2 min hasta que se tueste ligeramente.","Calentar leche en un cazo a fuego suave hasta que esté caliente pero sin hervir.","Verter la leche caliente sobre la sartén poco a poco, removiendo sin parar para integrar.","Añadir sal y nuez moscada y remover para integrar.","Cocer la bechamel a fuego suave, removiendo sin parar, hasta que esté espesa y se despegue de las paredes.","Extender la masa en una fuente y cubrir con film a contacto directo con la superficie.","Dejar enfriar la masa en la nevera hasta que esté firme y fácil de manejar.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Volcar pan rallado en un plato llano y reservar.","Tomar porciones de masa fría y darles forma ovalada con las manos para formar las croquetas.","Pasar cada croqueta por el huevo batido y escurrir el exceso.","Rebozar cada croqueta en el pan rallado y presionar para que se adhiera bien.","Calentar aceite de oliva en sartén a fuego fuerte hasta alcanzar 180 °C.","Freír las croquetas por tandas hasta que estén doradas por todos los lados.","Escurrir las croquetas sobre papel absorbente para retirar el exceso de aceite.","Servir las croquetas calientes."}', 'Croquetas de interior oscuro y cremoso, con aroma a bosque y textura crujiente por fuera.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_119', 'Moussaka de berenjena', 'ensaladas_verduras', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 480, 26, 22, 32, 4, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Berenjena","amount":800,"unit":"g"},{"name":"Carne picada de ternera","amount":500,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Tomate triturado","amount":500,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Leche","amount":600,"unit":"ml"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Canela","amount":2,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta","amount":2,"unit":"g"}]'::jsonb, '{"Cortar berenjena en láminas de 0,5 cm de grosor.","Salar las láminas de berenjena y dejar reposar para que suelten el amargor.","Picar cebolla en daditos finos.","Picar ajo fino.","Secar las láminas de berenjena con papel de cocina para eliminar el exceso de humedad.","Calentar plancha a fuego fuerte y marcar las láminas de berenjena hasta que estén doradas por ambos lados.","Reservar las láminas de berenjena marcadas en un plato.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","Añadir carne picada de ternera y dorar deshaciendo los grumos hasta que esté bien cocinada.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Añadir tomate triturado, canela, sal y pimienta; remover para integrar.","Cocer la salsa de carne a fuego suave, tapada, hasta que espese y los sabores se concentren.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina a la mantequilla fundida y remover sin parar hasta obtener un roux dorado.","Incorporar leche poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","Añadir nuez moscada a la bechamel y salpimentar; retirar del fuego y reservar.","Precalentar el horno a 190 °C.","Disponer una capa de láminas de berenjena en el fondo de una fuente de horno.","Cubrir la capa de berenjena con la mitad de la salsa de carne, extendiéndola de forma uniforme.","Repetir con otra capa de berenjena y el resto de la salsa de carne.","Verter la bechamel sobre las capas cubriendo toda la superficie de forma uniforme.","Repartir queso rallado sobre la bechamel de manera uniforme.","Hornear la fuente en el horno a 190 °C hasta que la superficie esté dorada y gratinada.","Retirar la fuente del horno y dejar reposar antes de cortar y servir.","Servir la moussaka cortada en porciones."}', 'Capas de berenjena y carne especiada bajo una bechamel gratinada y dorada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_120', 'Pizza casera con burrata y rúcula', 'ensaladas_verduras', 'none', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 100, 'facil', 'all', 530, 22, 55, 25, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Harina de fuerza","amount":250,"unit":"g"},{"name":"Agua","amount":150,"unit":"ml"},{"name":"Levadura fresca","amount":5,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Burrata","amount":200,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Parmesano","amount":20,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Disolver levadura fresca en agua templada hasta que no queden grumos.","Mezclar harina de fuerza, sal y aceite de oliva con el agua con levadura hasta obtener una masa homogénea.","Amasar sobre la encimera durante 10 min hasta que la masa esté lisa y elástica.","Colocar la masa en un bol, tapar con un paño y dejar fermentar en un lugar templado hasta que doble su volumen.","Precalentar el horno a 250 °C con la bandeja dentro.","Extender la masa sobre papel de horno hasta obtener una base fina y uniforme.","Repartir tomate triturado sobre la base estirada, dejando un borde de 1-2 cm libre.","Espolvorear orégano sobre el tomate triturado.","Hornear a 250 °C durante 10 min hasta que la base esté dorada y crujiente.","Rallar parmesano en láminas finas con un pelador o rallador.","Retirar la pizza del horno y repartir burrata troceada por encima.","Añadir rúcula y el parmesano rallado sobre la pizza.","Terminar con un chorrito de aceite de oliva y servir de inmediato."}', 'Pizza casera de base crujiente coronada con el corte cremoso de la burrata sobre rúcula fresca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_121', 'Tarta salada de calabacín y feta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'verano', 340, 13, 22, 22, 4, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Masa quebrada","amount":230,"unit":"g"},{"name":"Calabacín","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Queso feta","amount":150,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Eneldo","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Laminar calabacín en rodajas finas.","Cortar cebolla en juliana fina.","Forrar un molde con masa quebrada y pinchar la base con un tenedor.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla hasta que esté transparente.","Añadir el calabacín y saltear hasta que ablande ligeramente.","Batir huevo con nata para cocinar en un bol.","Añadir sal, pimienta y eneldo a la mezcla y remover.","Repartir la cebolla y el calabacín sobre la base de masa quebrada.","Desmenuzar queso feta por encima del relleno.","Verter la mezcla de huevo y nata sobre el relleno.","Hornear hasta que cuaje y la superficie esté dorada.","Retirar del horno y dejar templar antes de desmoldar.","Servir la tarta cortada en porciones."}', 'Tarta salada de verde y blanco, ligera y muy vistosa, con calabacín y feta cuajados en una base crujiente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_122', 'Tartar de aguacate con soja y sésamo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 285, 4, 10, 26, 2, true, false, '{"soja","sesamo"}', '[{"name":"Aguacate","amount":400,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo tostado","amount":10,"unit":"g"},{"name":"Zumo de lima","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar aguacate en dados de aproximadamente 1 cm.","Rociar el aguacate con zumo de lima para evitar que se oxide.","Cortar pepino en dados del mismo tamaño que el aguacate.","Picar cebolleta muy fina.","Mezclar en un bol el aguacate, el pepino y la cebolleta con salsa de soja y aceite de sésamo.","Remover con suavidad hasta que todo quede integrado sin aplastar el aguacate.","Colocar un aro metálico en el centro de cada plato y rellenar con la mezcla, presionando ligeramente.","Retirar el aro con cuidado para mantener la forma.","Espolvorear semillas de sésamo tostado por encima y servir inmediatamente bien frío."}', 'Tartar de aguacate verde brillante montado en aro perfecto, con un toque asiático de soja y sésamo que lo levanta.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('ensaladas_verduras_123', 'Espinacas a la crema', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 200, 9, 13, 12, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Espinaca fresca","amount":400,"unit":"g"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar espinaca fresca bajo agua fría con cuidado.","Llevar a ebullición una olla con abundante agua.","Escaldar las espinacas en el agua hirviendo hasta que reduzcan de volumen, unos 2 min.","Escurrir las espinacas en un colador y apretar bien para retirar el exceso de agua.","Picar las espinacas escurridas en trozos y reservar.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta obtener un roux homogéneo.","Añadir leche poco a poco sin dejar de remover hasta integrarla por completo.","Salpimentar con sal y pimienta negra y añadir nuez moscada.","Cocer la bechamel a fuego suave, removiendo, hasta que esté espesa y sin grumos, unos 5 min.","Incorporar las espinacas picadas a la bechamel y mezclar hasta integrarlas por completo.","Precalentar el grill del horno a temperatura alta.","Verter la mezcla en una fuente apta para horno y extender en capa uniforme.","Cubrir la superficie con queso rallado de forma homogénea.","Gratinar en el horno con el grill hasta que la superficie esté dorada, unos 6 min.","Servir caliente directamente desde la fuente."}', 'Espinacas envueltas en una salsa bechamel sedosa con nuez moscada, gratinadas y doradas por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_024', 'Puré de patata con mantequilla y nuez moscada', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 310, 6, 38, 14, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos regulares de unos 3 cm.","Colocar los trozos de patata en una olla, cubrir con agua fría y añadir sal.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata esté muy tierna al pinchar, unos 18 min.","Calentar leche entera con mantequilla en un cazo a fuego suave hasta que la mantequilla se derrita.","Escurrir las patatas y devolverlas a la olla caliente fuera del fuego.","Machacar las patatas con un pasapurés añadiendo la leche caliente poco a poco.","Remover hasta conseguir una textura sedosa y sin grumos.","Añadir nuez moscada molida y ajustar de sal al gusto, mezclar bien.","Servir el puré caliente de inmediato."}', 'Puré de patata cremoso, con el brillo de la mantequilla derretida y un toque de nuez moscada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_025', 'Boniato asado con miel y tomillo', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 260, 3, 46, 7, 2, true, true, '{}', '[{"name":"Boniato","amount":400,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar boniato bajo el grifo y secar bien.","Cortar el boniato en gajos de unos 3 cm sin pelarlo.","Disponer los gajos en una bandeja forrada con papel de horno.","Añadir aceite de oliva y sal sobre los gajos y mezclar hasta cubrirlos bien.","Hornear a 200 °C durante 20 min.","Retirar la bandeja, remover los gajos y volver a hornear hasta que estén tiernos y dorados.","Calentar miel en un cazo a fuego suave durante 1 min hasta que fluya con facilidad.","Retirar la bandeja del horno y rociar la miel templada sobre los gajos.","Repartir tomillo fresco por encima y servir de inmediato."}', 'Boniato asado hasta caramelizarse en los bordes, con un toque dulce de miel y tomillo fresco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_026', 'Coles de Bruselas con panceta y balsámico', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 270, 9, 18, 17, 2, false, true, '{"sulfitos"}', '[{"name":"Coles de Bruselas","amount":350,"unit":"g"},{"name":"Panceta ahumada en taquitos","amount":60,"unit":"g"},{"name":"Vinagre balsámico","amount":20,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores de coles de bruselas y cortarlas por la mitad.","Llevar a ebullición una olla con agua y sal.","Escaldar las coles en el agua hirviendo durante 4 min, hasta que empiecen a ablandarse.","Escurrir las coles y reservar.","Calentar sartén a fuego medio-alto y añadir panceta ahumada en taquitos.","Dorar la panceta, removiendo, durante 4 min, hasta que quede crujiente y haya soltado su grasa.","Añadir aceite de oliva a la sartén y colocar las coles con el corte hacia abajo.","Saltear las coles a fuego medio-alto durante 5 min, hasta que el corte se dore bien.","Añadir vinagre balsámico y remover para glasear las coles.","Dejar reducir el vinagre balsámico 2 min, removiendo, hasta que las coles queden bien lacadas.","Rectificar de sal y servir las coles bien calientes."}', 'Coles de Bruselas doradas y crujientes con panceta, envueltas en un glaseado oscuro de vinagre balsámico.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_027', 'Espárragos trigueros con huevo poché', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'normal', 'all', 170, 9, 6, 13, 2, true, false, '{"huevo"}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar espárragos trigueros bajo agua fría y retirar la parte leñosa del tallo rompiéndola con los dedos.","Llevar a ebullición un cazo con agua y vinagre.","Calentar plancha con aceite de oliva a fuego fuerte.","Asar los espárragos trigueros 5 min, dándoles la vuelta a mitad, hasta que estén tiernos y algo tostados.","Cascar huevo uno a uno en un cuenco pequeño, sin romper la yema.","Bajar el fuego del cazo hasta que el agua esté sin hervir con fuerza y crear un remolino con una cuchara.","Verter un huevo desde el cuenco en el centro del remolino con cuidado.","Cocer 3 min hasta que la clara cuaje y la yema quede líquida.","Retirar el huevo poché con una espumadera y escurrir sobre papel absorbente.","Repetir el remolino y cocer el segundo huevo de la misma forma 3 min.","Retirar el segundo huevo con la espumadera y escurrir sobre papel absorbente.","Repartir los espárragos trigueros en los platos, colocar un huevo poché sobre cada ración y añadir sal."}', 'Espárragos trigueros a la plancha coronados con un huevo poché cuya yema los baña al romperse.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_028', 'Patatas panadera con romero', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'facil', 'all', 280, 5, 38, 10, 2, true, true, '{}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar patata y cortar en rodajas finas de 3-4 mm.","Cortar cebolla en juliana fina.","Engrasar una fuente de horno con aceite de oliva.","Disponer una capa de patatas en la fuente, cubrir con cebolla y añadir sal. Repetir hasta agotar los ingredientes.","Verter caldo de verduras y el resto del aceite de oliva sobre las capas.","Repartir romero fresco por encima de las patatas.","Tapar la fuente con papel de aluminio y hornear a 190 °C durante 25 min.","Retirar el papel de aluminio y hornear 15 min más hasta que las patatas estén doradas por arriba.","Reposar la fuente 5 min fuera del horno antes de servir.","Servir las patatas directamente desde la fuente, repartiendo capas con un poco del jugo del fondo."}', 'Patatas panadera en capas doradas y jugosas, perfumadas con romero fresco entre capa y capa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_029', 'Zanahorias glaseadas con miel y comino', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 160, 2, 25, 6, 2, true, true, '{"lactosa"}', '[{"name":"Zanahoria","amount":350,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar zanahoria y cortarlas por la mitad a lo largo si son grandes; dejarlas enteras si son pequeñas.","Llevar a ebullición agua con sal en un cazo.","Cocer las zanahorias en el agua hirviendo hasta que estén tiernas pero firmes.","Escurrir las zanahorias en un colador y reservar.","Calentar sartén a fuego medio y fundir mantequilla hasta que espume.","Añadir las zanahorias escurridas, miel y comino molido a la sartén.","Saltear removiendo con frecuencia hasta que las zanahorias queden glaseadas y brillantes.","Servir las zanahorias calientes con el jugo del glaseado de la sartén."}', 'Zanahorias glaseadas hasta quedar brillantes y pegajosas, con un toque cálido de comino.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_030', 'Champiñones al ajillo enteros', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 190, 6, 7, 15, 2, true, true, '{"sulfitos"}', '[{"name":"Champiñones enteros","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Guindilla seca","amount":2,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar champiñones enteros con un paño húmedo y retirar la base terrosa del pie, dejándolos enteros.","Laminar ajo.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén amplia a fuego medio hasta que esté caliente.","Sofreír el ajo laminado junto con guindilla seca hasta que el ajo empiece a dorarse.","Subir el fuego a fuego fuerte y añadir los champiñones enteros.","Saltear los champiñones hasta que empiecen a dorarse, removiendo de vez en cuando.","Añadir vino blanco y remover hasta que evapore el alcohol.","Añadir sal y saltear hasta que los champiñones estén tiernos pero enteros.","Espolvorear el perejil picado sobre los champiñones y servir bien calientes."}', 'Champiñones enteros salteados al ajillo, con el brillo del aceite y el ajo dorado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_031', 'Puré de coliflor con hierbas y aceite de oliva', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 170, 5, 12, 12, 2, true, true, '{}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Cebollino","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Separar coliflor en ramilletes y lavar bajo agua fría.","Pelar ajo y dejar los dientes enteros.","Llevar una olla con agua abundante y sal a ebullición a fuego fuerte.","Añadir los ramilletes de coliflor y el ajo a la olla cuando rompa a hervir.","Cocer a fuego medio hasta que la coliflor esté muy tierna, unos 13 min.","Picar perejil fresco y cebollino muy finos y reservar.","Escurrir la coliflor y el ajo, reservando un vaso del agua de cocción.","Triturar la coliflor y el ajo con la batidora hasta obtener una textura fina.","Añadir un poco del agua de cocción reservada si el puré queda demasiado espeso y triturar de nuevo.","Añadir la mitad de aceite de oliva mientras se tritura hasta que el puré quede sedoso.","Servir el puré en un plato hondo y terminar con el aceite de oliva restante en hilo y las hierbas picadas."}', 'Puré de coliflor de un blanco inmaculado, terminado con un hilo de aceite de oliva y hierbas frescas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_032', 'Alcachofas confitadas con jamón', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'normal', 'all', 290, 8, 10, 19, 2, true, true, '{}', '[{"name":"Alcachofa","amount":4,"unit":"ud"},{"name":"Jamón serrano en virutas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":200,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Limón","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Retirar las hojas exteriores duras de alcachofa hasta llegar a las hojas tiernas.","Cortar la punta de cada alcachofa y frotar con limón para evitar la oxidación.","Cortar cada alcachofa por la mitad y retirar la pelusa interior con una cuchara.","Aplastar ajo con el lateral del cuchillo para agrietarlo sin pelarlo del todo.","Verter aceite de oliva en una cazuela pequeña y añadir el ajo aplastado y laurel.","Calentar el aceite a fuego suave hasta que esté templado, sin que humee.","Sumergir las alcachofas en el aceite templado, con el corte hacia abajo.","Confitar a fuego muy suave durante 25 min, sin que el aceite llegue a burbujear.","Comprobar la terneza pinchando con una punta de cuchillo; deben ceder sin resistencia.","Retirar las alcachofas del aceite y escurrir sobre papel absorbente.","Salpimentar con sal y abrir ligeramente cada mitad en forma de abanico.","Disponer las alcachofas en el plato y repartir jamón serrano en virutas por encima."}', 'Corazones de alcachofa confitados hasta quedar tiernísimos, abiertos en abanico y coronados con virutas de jamón.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('guarniciones_033', 'Setas salteadas con jamón ibérico', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 190, 12, 5, 14, 2, true, true, '{}', '[{"name":"Setas variadas","amount":350,"unit":"g"},{"name":"Jamón ibérico en taquitos","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo y cortar las más grandes en trozos, dejando las pequeñas enteras.","Picar ajo fino.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén amplia a fuego fuerte hasta que esté bien caliente.","Saltear las setas a fuego fuerte sin remover en exceso hasta que se doren y suelten su agua.","Añadir el ajo picado y saltear hasta que esté dorado.","Añadir jamón ibérico en taquitos y saltear hasta que se dore ligeramente y suelte su grasa.","Añadir sal y espolvorear el perejil picado por encima.","Servir de inmediato en el plato."}', 'Setas de temporada salteadas con jamón ibérico, con la grasa dorada del jamón impregnándolo todo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_034', 'Puerros a la brasa con romesco', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'plancha', 30, 'normal', 'all', 340, 7, 20, 23, 2, false, true, '{"frutos_secos","gluten","sulfitos"}', '[{"name":"Puerro","amount":4,"unit":"ud"},{"name":"Tomate maduro","amount":50,"unit":"g"},{"name":"Pimiento choricero","amount":10,"unit":"g"},{"name":"Almendra tostada","amount":20,"unit":"g"},{"name":"Avellana tostada","amount":10,"unit":"g"},{"name":"Pan frito","amount":15,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Retirar la parte verde más dura y las raíces de puerro, lavar bien entre las capas y escurrir.","Llevar a ebullición agua con sal en una olla grande a fuego fuerte.","Cocer los puerros enteros durante 9 min, hasta que estén tiernos pero no blandos.","Escurrir los puerros cocidos y dejar templar sobre un trapo limpio.","Triturar tomate maduro, pimiento choricero, almendra tostada, avellana tostada y pan frito en el vaso de la batidora.","Añadir ajo, aceite de oliva y vinagre de jerez al vaso y triturar hasta obtener una salsa espesa y homogénea.","Salpimentar el romesco con sal al gusto, remover y reservar.","Calentar plancha a fuego fuerte hasta que humee.","Marcar los puerros por todos los lados hasta que queden bien tostados y con marcas oscuras.","Cortar los puerros por la mitad a lo largo y disponerlos en el plato.","Napar los puerros con el romesco o servirlo aparte en un cuenco junto al plato."}', 'Puerros marcados a la brasa hasta tostarse, servidos sobre un intenso romesco rojo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_035', 'Calabaza asada con queso de cabra y nueces', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 380, 13, 20, 28, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Nuez","amount":30,"unit":"g"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y cortarla en dados de unos 2 cm.","Disponer la calabaza en una bandeja de horno en una sola capa.","Aliñar con aceite de oliva, sal y tomillo fresco y mezclar bien.","Hornear la bandeja en la rejilla central hasta que la calabaza esté tierna y dorada en los bordes.","Picar nuez groseramente mientras la calabaza se hornea.","Retirar la bandeja del horno y desmenuzar queso de cabra por encima para que se ablande con el calor residual.","Repartir las nueces picadas sobre la calabaza con queso de cabra.","Terminar con un hilo de miel repartido por toda la bandeja.","Servir templado directamente de la bandeja."}', 'Calabaza asada de naranja intenso, con queso de cabra cremoso y nueces tostadas por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_036', 'Patatas bravas caseras', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'normal', 'all', 400, 7, 36, 23, 2, false, false, '{"huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":300,"unit":"ml"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Cayena molida","amount":1,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados irregulares de unos 3 cm.","Picar ajo fino y dividir en 2 partes: una para la salsa brava y otra para el alioli.","Calentar aceite de oliva en sartén honda a fuego medio hasta que esté caliente.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes por fuera y tiernas por dentro.","Calentar aceite de oliva en un cazo a fuego suave hasta que esté templado.","Sofreír la mitad del ajo picado en el cazo a fuego suave hasta que empiece a dorarse.","Retirar el cazo del fuego y añadir pimentón picante removiendo para que no se queme.","Añadir tomate triturado y cayena molida al cazo y volver al fuego suave.","Cocer la salsa a fuego suave hasta que espese ligeramente.","Poner huevo en un vaso alto junto con la otra mitad del ajo picado y limón.","Triturar con batidora de mano arrancando desde el fondo hasta que emulsione.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que el alioli espese.","Escurrir las patatas fritas sobre papel absorbente y salar con sal.","Repartir las patatas en el plato y cubrir con la salsa brava.","Añadir el alioli en líneas por encima y servir de inmediato."}', 'Dados de patata dorados y crujientes, cubiertos de brava roja picante y líneas de alioli casero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_037', 'Espinacas con piñones y pasas', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 250, 8, 18, 18, 2, true, true, '{"frutos_secos"}', '[{"name":"Espinacas frescas","amount":400,"unit":"g"},{"name":"Piñones","amount":25,"unit":"g"},{"name":"Pasas","amount":25,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir pasas en agua templada para hidratarlas.","Laminar ajo.","Lavar espinacas frescas con abundante agua fría y escurrirlas bien.","Escurrir las pasas y reservar.","Tostar piñones en sartén sin aceite a fuego medio, removiendo hasta que se doren.","Retirar los piñones de la sartén y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio.","Sofreír el ajo laminado hasta que esté dorado.","Añadir las espinacas por tandas y saltear a fuego fuerte hasta que reduzcan y suelten el agua.","Incorporar las pasas escurridas y los piñones tostados y mezclar bien.","Salpimentar con sal y servir caliente."}', 'Espinacas salteadas de un verde brillante, salpicadas de piñones dorados y pasas granate.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_038', 'Patatas Hasselback gratinadas', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 480, 12, 42, 26, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Queso rallado","amount":50,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar patata y apoyar cada una entre 2 palillos o cucharas para no cortarla del todo.","Hacer cortes finos y paralelos en cada patata, sin llegar al fondo, separados unos 3 mm.","Picar ajo muy fino.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida.","Retirar el cazo del fuego y mezclar la mantequilla fundida con aceite de oliva y el ajo picado.","Colocar las patatas en una fuente de horno y pincelar con la mezcla, introduciendo la brocha entre las láminas.","Añadir sal sobre las patatas.","Hornear la fuente en el centro del horno durante 35 min, hasta que las patatas empiecen a abrirse en abanico y doren.","Retirar la fuente del horno y repartir queso rallado sobre y entre las láminas de cada patata.","Volver a introducir la fuente en el horno y hornear 12 min más, hasta que el queso funda y esté dorado.","Retirar la fuente del horno y repartir tomillo fresco por encima. Servir de inmediato."}', 'Patatas Hasselback abiertas en abanico, doradas y crujientes, con el queso fundido entre las láminas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_039', 'Patatas fritas caseras crujientes', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 250, 4, 34, 12, 2, true, false, '{}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":350,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor, regulares.","Sumergir los bastones en agua fría hasta que el agua salga limpia, unos 10 min.","Escurrir los bastones y secar muy bien con un paño limpio, sin dejar humedad.","Calentar aceite de oliva en una sartén honda a fuego medio hasta alcanzar 160 °C.","Freír los bastones a 160 °C durante 6 min hasta que estén tiernos por dentro sin dorarse.","Retirar los bastones y escurrir sobre papel absorbente.","Subir el fuego hasta que el aceite alcance 190 °C.","Freír los bastones de nuevo a 190 °C durante 3 min hasta que estén dorados y muy crujientes.","Retirar y escurrir sobre papel absorbente.","Añadir sal al momento sobre las patatas recién escurridas y servir enseguida."}', 'Patatas fritas doradas y crujientes por fuera, tiernas por dentro, fritas en dos tandas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_040', 'Patatas fritas con parmesano y perejil', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'normal', 'all', 380, 9, 34, 21, 2, true, false, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":350,"unit":"ml"},{"name":"Parmesano rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor.","Secar bien los bastones de patata con un paño limpio para evitar salpicaduras al freír.","Picar ajo muy fino.","Picar perejil fresco muy fino.","Mezclar el ajo picado y el perejil picado con parmesano rallado en un bol pequeño y reservar.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que esté bien caliente.","Freír los bastones de patata a fuego medio-fuerte hasta que estén dorados y crujientes por fuera y tiernos por dentro.","Escurrir las patatas fritas sobre papel absorbente.","Salar las patatas escurridas con sal al momento.","Volcar las patatas en un bol grande y espolvorear con la mezcla de parmesano, ajo y perejil.","Remover con energía para que la mezcla se adhiera a las patatas con el calor residual.","Servir de inmediato."}', 'Patatas fritas envueltas en parmesano, ajo y perejil, con un aroma que sube nada más servirlas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_041', 'Gratín dauphinois (patatas gratinadas con nata)', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 70, 'normal', 'all', 540, 13, 47, 44, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":500,"unit":"g"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso gruyere rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 170 °C con calor arriba y abajo.","Pelar patata y laminar muy fino, a 2-3 mm, con mandolina o cuchillo afilado.","Frotar una fuente de horno con ajo cortado por la mitad frotando toda la superficie.","Untar la fuente con mantequilla en capa fina por el fondo y las paredes.","Disponer las láminas de patata en capas superpuestas en la fuente, añadir sal entre capa y capa.","Calentar nata para cocinar, leche entera y nuez moscada molida en un cazo a fuego medio hasta que humee sin hervir.","Verter la mezcla caliente de nata y leche sobre las patatas hasta casi cubrirlas.","Repartir queso gruyere rallado de forma uniforme por toda la superficie.","Hornear en el centro del horno durante 50 min, hasta que las patatas estén tiernas al pinchar y la superficie esté dorada.","Reposar el gratín 10 min fuera del horno antes de servir para que asiente.","Servir en la propia fuente cortando porciones con espátula."}', 'Gratín dauphinois en capas finísimas, con una corteza dorada y burbujeante recién salida del horno.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('guarniciones_042', 'Coliflor gratinada con bechamel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 310, 15, 26, 18, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Leche entera","amount":250,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Separar coliflor en ramilletes de tamaño similar para que se cuezan de forma uniforme.","Llevar a ebullición una olla con agua y sal.","Cocer los ramilletes de coliflor a fuego medio durante 8 min, hasta que estén tiernos pero firmes.","Escurrir la coliflor cocida y reservar en una fuente apta para horno.","Precalentar el horno a 200 °C con función gratinar.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente derretida.","Añadir harina de trigo de golpe y remover sin parar con unas varillas durante 2 min, hasta que la mezcla burbujee sin dorarse.","Verter leche entera poco a poco sin dejar de remover con las varillas para evitar grumos.","Cocer la bechamel a fuego suave, removiendo constantemente, durante 5 min hasta que espese.","Añadir nuez moscada molida y sal, remover y retirar del fuego.","Cubrir la coliflor reservada en la fuente con la bechamel, extendiéndola de forma uniforme.","Repartir queso rallado de manera homogénea por toda la superficie.","Gratinar en el horno a 200 °C durante 8 min, hasta que la superficie quede dorada y burbujeante.","Servir la coliflor gratinada recién salida del horno."}', 'Coliflor cubierta de bechamel y gratinada hasta quedar dorada y burbujeante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_043', 'Endivias gratinadas con jamón y bechamel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'normal', 'all', 360, 19, 17, 23, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Endivia","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Leche entera","amount":300,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada molida","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal.","Cocer endivia enteras en el agua hirviendo hasta que estén tiernas.","Escurrir las endivias y apretar con las manos para eliminar el máximo de agua posible.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de trigo de golpe y remover sin parar hasta obtener una pasta homogénea.","Incorporar leche entera poco a poco, removiendo sin parar para evitar grumos.","Cocer la bechamel a fuego suave, removiendo, hasta que espese y sea fina.","Añadir nuez moscada molida y sal; remover y retirar del fuego.","Precalentar el horno a 200 °C con función gratinar.","Envolver cada endivia con 1 loncha de jamón cocido.","Colocar las endivias envueltas en una fuente de horno en una sola capa.","Cubrir las endivias con la bechamel repartiéndola de manera uniforme.","Repartir queso rallado por encima de la bechamel.","Gratinar en el horno a 200 °C hasta que la superficie esté dorada.","Servir la fuente bien caliente directamente a la mesa."}', 'Endivias envueltas en jamón y bañadas en bechamel, con un gratinado dorado por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_044', 'Puré de boniato con canela', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 280, 4, 46, 9, 2, true, true, '{"lactosa"}', '[{"name":"Boniato","amount":450,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Canela molida","amount":2,"unit":"g"},{"name":"Leche entera","amount":50,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en dados de unos 3 cm.","Llevar a ebullición una olla con agua y sal.","Cocer los dados de boniato hasta que estén muy tiernos al pinchar, unos 15 min.","Calentar leche entera en un cazo a fuego suave hasta que esté templada.","Escurrir los dados de boniato y devolver a la olla fuera del fuego.","Añadir mantequilla y machacar con un pasapurés hasta obtener una masa homogénea.","Incorporar la leche caliente poco a poco sin dejar de triturar hasta lograr textura suave.","Añadir canela molida y mezclar bien hasta integrar.","Rectificar de sal y servir el puré templado."}', 'Puré de boniato de un naranja intenso, con el dulzor suave de la canela.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_045', 'Patatas asadas con romero y ajo', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 230, 4, 32, 9, 2, true, true, '{}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar patata y cortarlas en gajos gruesos sin pelar.","Machacar ajo con la piel hasta abrirlos.","Picar romero fresco fino.","Mezclar las patatas en un bol con aceite de oliva, el ajo machacado, el romero picado, sal y pimienta negra.","Extender las patatas en una bandeja en una sola capa, sin amontonar.","Hornear durante 15 min a 200 °C.","Dar la vuelta a las patatas y hornear 15 min más hasta que estén doradas y crujientes por fuera.","Retirar la bandeja del horno y servir las patatas calientes."}', 'Patatas asadas al horno en gajos, doradas y crujientes por fuera, con ajo y romero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_046', 'Ensalada de patata templada con mostaza', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 240, 4, 30, 12, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Mostaza de Dijon","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Lavar patata bajo el grifo hasta que estén limpias.","Cocer las patatas enteras con piel en una olla con agua y sal hasta que estén tiernas.","Picar cebolleta en fino mientras las patatas cuecen.","Picar perejil fresco en fino.","Mezclar en un bol mostaza de dijon, aceite de oliva, vinagre de vino y sal.","Batir la mezcla con un tenedor hasta emulsionar la vinagreta.","Escurrir las patatas y dejar templar hasta que se puedan manipular sin quemarse.","Pelar las patatas templadas con los dedos retirando la piel.","Cortar las patatas en rodajas gruesas de unos 1 cm.","Añadir la cebolleta picada y el perejil picado a la vinagreta y remover.","Incorporar las patatas cortadas al bol con la vinagreta y mezclar con cuidado de no romperlas.","Añadir pimienta negra y rectificar de sal al gusto.","Servir la ensalada templada en el momento."}', 'Patatas cocidas templadas, con firmeza justa, aliñadas con una vinagreta de mostaza con carácter.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_047', 'Verduras asadas al horno con miel', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'facil', 'all', 170, 3, 24, 7, 2, true, true, '{}', '[{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Tomillo fresco","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar zanahoria y cortar en bastones de unos 5 cm.","Cortar calabacín, pimiento rojo y cebolla en trozos del mismo tamaño que la zanahoria.","Mezclar aceite de oliva con miel y tomillo fresco en un bol hasta integrar.","Disponer todas las verduras en una bandeja de horno forrada con papel vegetal en una sola capa.","Rociar las verduras con la mezcla de aceite y miel y añadir sal.","Hornear a 200 °C durante 15 min.","Remover las verduras con una espátula y hornear 10 min más, hasta que estén tiernas y con los bordes caramelizados.","Servir las verduras calientes directamente de la bandeja."}', 'Verduras de temporada asadas con un toque de miel que caramelizan los bordes al horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_048', 'Pimientos de padrón fritos', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 160, 2, 6, 14, 2, true, false, '{}', '[{"name":"Pimiento de padrón","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Sal en escamas","amount":3,"unit":"g"}]'::jsonb, '{"Lavar pimiento de padrón bajo el grifo y secarlos bien con un paño limpio.","Calentar aceite de oliva en sartén grande a fuego fuerte hasta que humee ligeramente.","Añadir los pimientos en una sola capa, sin amontonar, para que frían de manera uniforme.","Freír removiendo con frecuencia hasta que los pimientos se arruguen y doren por todos los lados.","Retirar los pimientos con una espumadera y escurrir sobre papel absorbente.","Colocar los pimientos en una fuente y espolvorear sal en escamas justo antes de servir.","Servir de inmediato, muy calientes."}', 'Pimientos de padrón fritos, arrugados y brillantes, con su punto de sal en escamas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_049', 'Berenjenas fritas con miel de caña', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 290, 4, 32, 16, 2, true, false, '{"gluten"}', '[{"name":"Berenjena","amount":300,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Miel de caña","amount":30,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar berenjena en bastones de unos 1 cm de grosor, sin pelar.","Sumergir los bastones en agua fría con sal durante 10 min para eliminar el amargor.","Escurrir bien los bastones y secarlos con papel absorbente.","Rebozar los bastones en harina, sacudiendo el exceso para que quede una capa fina.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que esté bien caliente.","Freír los bastones en tandas a fuego fuerte hasta que estén dorados y crujientes.","Escurrir los bastones fritos sobre papel absorbente y salar ligeramente.","Disponer los bastones en una fuente y regar con miel de caña justo antes de servir."}', 'Berenjenas fritas doradas y crujientes, con un hilo de miel de caña oscura por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_050', 'Puré de guisantes con menta', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 160, 8, 15, 7, 2, true, true, '{"lactosa"}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Nata líquida","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla con agua y sal.","Añadir guisantes congelados y cocer 5 min hasta que estén tiernos.","Reservar un vaso del agua de cocción antes de escurrir.","Escurrir los guisantes cocidos.","Separar las hojas de menta fresca y desechar los tallos.","Triturar los guisantes escurridos con las hojas de menta, mantequilla y nata líquida hasta obtener un puré fino.","Añadir agua de cocción reservada a cucharadas si el puré ha quedado demasiado espeso y volver a triturar.","Salpimentar con sal y pimienta negra y triturar 10 segundos más hasta integrar.","Servir el puré templado como acompañamiento."}', 'Puré de guisantes de un verde vivo, fresco y ligero gracias a la menta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_051', 'Cebolla caramelizada', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 45, 'facil', 'all', 150, 1, 16, 9, 2, true, true, '{"lactosa"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y cortarla en juliana fina.","Calentar aceite de oliva y mantequilla en una sartén amplia a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla y sal; remover para que se impregne bien de la grasa.","Bajar el fuego a suave y cocer la cebolla 30 min, removiendo cada 5 min, hasta que esté muy blanda y empiece a dorarse.","Añadir azúcar y remover para integrarlo con la cebolla.","Continuar cocinando 5 min a fuego suave, removiendo a menudo, hasta que la cebolla esté uniformemente dorada y caramelizada.","Retirar la sartén del fuego y servir la cebolla caramelizada templada."}', 'Cebolla cocinada muy despacio hasta quedar dorada, brillante, dulce y untuosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_052', 'Boniatos fritos crujientes', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 260, 2, 34, 12, 2, true, false, '{}', '[{"name":"Boniato","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en bastones uniformes del tamaño de unas patatas fritas.","Secar bien los bastones con un paño limpio hasta que no quede humedad visible.","Calentar aceite de oliva en sartén honda a fuego fuerte hasta que empiece a humear ligeramente.","Freír los bastones en tandas sin amontonar hasta que estén dorados por fuera y tiernos por dentro.","Retirar los bastones con una espumadera y escurrir sobre papel absorbente.","Repetir el proceso con el resto de bastones hasta terminar toda la tanda.","Añadir sal sobre los bastones recién escurridos y servir de inmediato bien calientes."}', 'Bastones de boniato fritos, dorados y crujientes por fuera, más dulces que la patata clásica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_053', 'Espárragos blancos con vinagreta', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 15, 'facil', 'all', 150, 5, 5, 12, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Espárragos blancos en conserva","amount":300,"unit":"g"},{"name":"Huevo cocido","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Escurrir espárragos blancos en conserva y disponerlos en una fuente.","Picar huevo cocido en trozos pequeños.","Verter aceite de oliva en un bol junto con vinagre de vino, sal y pimienta negra.","Batir la mezcla hasta emulsionar.","Regar los espárragos escurridos con la vinagreta.","Repartir el huevo picado por encima de los espárragos.","Dejar reposar en la nevera hasta que los espárragos se impregnen bien con la vinagreta."}', 'Espárragos blancos delicados y pálidos, con un aliño ácido de contraste y huevo picado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_054', 'Judías verdes con jamón', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 25, 'facil', 'all', 140, 9, 8, 8, 2, true, true, '{}', '[{"name":"Judía verde","amount":350,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar judía verde retirando los extremos y los hilos laterales.","Cortar las judías verdes por la mitad.","Llevar a ebullición una olla con agua abundante y sal.","Cocer las judías verdes en el agua hirviendo hasta que estén tiernas pero firmes.","Picar ajo fino.","Cortar jamón serrano en tiras finas.","Escurrir las judías verdes cocidas y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado a fuego medio hasta que empiece a dorarse sin quemarse.","Añadir el jamón en tiras y saltear hasta que empiece a dorarse.","Incorporar las judías escurridas y saltear todo junto a fuego medio.","Servir las judías con jamón en caliente."}', 'Judías verdes de un verde vivo salteadas con virutas rosadas de jamón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_055', 'Puré de calabaza con jengibre', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 35, 'facil', 'all', 130, 2, 14, 7, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Nata líquida","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar calabaza, retirar las semillas y cortarla en dados de unos 3 cm.","Pelar jengibre fresco y rallarlo fino.","Llevar a ebullición una olla con agua y sal. Añadir la calabaza y cocer a fuego medio hasta que esté muy tierna.","Escurrir la calabaza con un colador y dejarla reposar 1 min para que pierda el exceso de agua.","Triturar la calabaza escurrida junto con el jengibre rallado, mantequilla y nata líquida hasta obtener un puré fino.","Añadir pimienta negra y ajustar de sal al gusto. Triturar de nuevo si hace falta hasta conseguir una textura homogénea.","Servir el puré caliente."}', 'Puré de calabaza de color naranja intenso, con un toque picante de jengibre que lo levanta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_056', 'Calabacines rellenos de verduras gratinados', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 190, 8, 15, 11, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Cortar calabacín por la mitad a lo largo.","Vaciar la pulpa de cada mitad con una cuchara, dejando una base firme. Reservar la pulpa.","Picar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Rallar zanahoria.","Picar tomate en dados pequeños.","Picar la pulpa reservada del calabacín en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el pimiento rojo, la zanahoria, el tomate y la pulpa de calabacín hasta que estén tiernos.","Añadir sal y orégano al sofrito. Remover para mezclar bien.","Rellenar las mitades de calabacín con el sofrito de verduras.","Cubrir cada mitad rellena con queso rallado y colocar en una bandeja de horno.","Hornear a 190 °C hasta que el calabacín esté tierno y el queso dorado.","Servir los calabacines rellenos calientes recién salidos del horno."}', 'Calabacines rellenos de un sofrito colorido de verduras, gratinados con queso dorado por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_057', 'Tomates asados con ajo y hierbas', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 130, 2, 9, 10, 2, true, true, '{}', '[{"name":"Tomate","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Tomillo fresco","amount":2,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Lavar tomate y cortar cada uno por la mitad.","Picar ajo fino.","Mezclar el ajo picado con aceite de oliva, tomillo fresco y orégano en un bol hasta integrar.","Colocar las mitades de tomate con el corte hacia arriba en una bandeja de horno.","Repartir el aceite aromatizado sobre cada mitad de tomate.","Salpimentar con sal y pimienta negra.","Hornear 25 min hasta que la piel esté arrugada y el tomate tierno.","Servir los tomates templados con el jugo de la bandeja por encima."}', 'Tomates asados de piel arrugada y dulce, perfumados con ajo, hierbas y aroma a horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_058', 'Patatas duquesa', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 55, 'normal', 'all', 230, 6, 27, 11, 2, true, true, '{"lactosa","huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Huevo","amount":60,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer los trozos de patata en agua con sal hasta que estén muy tiernos.","Precalentar el horno a 200 °C con calor arriba y abajo.","Escurrir las patatas cocidas y triturar en caliente hasta obtener un puré fino sin grumos.","Añadir mantequilla al puré caliente y mezclar hasta que se funda por completo.","Separar huevo: reservar la clara en un bol pequeño y añadir la yema al puré.","Añadir nuez moscada, sal y pimienta negra al puré y mezclar hasta integrar.","Dejar templar el puré hasta que esté manejable sin quemar la mano.","Forrar una bandeja de horno con papel vegetal.","Introducir el puré en una manga pastelera con boquilla rizada.","Formar rosetones sobre la bandeja con la manga, dejando espacio entre ellos.","Batir la clara reservada en el bol y pincelar los rosetones por encima con ella.","Hornear a 200 °C durante 17 min hasta que estén dorados y ligeramente crujientes.","Servir las patatas duquesa calientes recién salidas del horno."}', 'Rosetones de puré de patata, dorados y crujientes por fuera, cremosos por dentro.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('guarniciones_059', 'Champiñones rellenos gratinados', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 40, 'normal', 'all', 180, 8, 11, 11, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Champiñón grande","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Queso rallado","amount":50,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Limpiar champiñón grande y separar los pies de los sombreros.","Picar los pies de champiñón fino.","Picar ajo fino.","Picar perejil fresco fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado y los pies de champiñón picados hasta que estén dorados y hayan soltado el agua.","Retirar la sartén del fuego.","Añadir pan rallado, la mitad de queso rallado, el perejil picado y sal al sofrito.","Mezclar bien hasta obtener un relleno homogéneo.","Rellenar cada sombrero de champiñón con la mezcla, presionando ligeramente.","Colocar los champiñones rellenos en una bandeja de horno.","Cubrir cada champiñón con el resto del queso rallado.","Hornear a 190 °C hasta que el queso esté dorado y el champiñón tierno.","Servir los champiñones rellenos calientes."}', 'Champiñones rellenos y gratinados, con sombreros individuales dorados en el horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_060', 'Puré mixto de patata y zanahoria', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 30, 'facil', 'all', 170, 3, 26, 6, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y zanahoria.","Cortar la patata y la zanahoria en trozos similares de unos 3 cm.","Llevar a ebullición una olla con agua abundante y sal.","Cocer la patata y la zanahoria juntas hasta que estén muy tiernas.","Calentar leche en un cazo pequeño a fuego suave hasta que esté caliente, sin que hierva.","Escurrir la patata y la zanahoria, reservando un poco del agua de cocción.","Triturar la patata y la zanahoria escurridas hasta obtener una mezcla homogénea.","Añadir mantequilla y la leche caliente al puré, mezclando hasta que quede cremoso.","Añadir un poco del agua de cocción reservada si el puré ha quedado demasiado espeso.","Salpimentar con pimienta negra y sal, mezclando bien.","Servir el puré caliente."}', 'Puré de patata y zanahoria de color naranja suave, más ligero que el puré clásico.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_061', 'Verduras salteadas al wok con soja', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 20, 'facil', 'all', 150, 5, 15, 8, 2, true, true, '{"soja","sesamo","gluten"}', '[{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Brócoli","amount":100,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y calabacín en tiras finas.","Cortar zanahoria en tiras finas y brócoli en arbolitos pequeños.","Picar ajo y jengibre fresco muy finos.","Calentar aceite de sésamo en sartén a fuego fuerte hasta que humee ligeramente.","Saltear el ajo y el jengibre picados hasta que suelten aroma, sin dejar que se quemen.","Añadir la zanahoria y el brócoli y saltear a fuego fuerte, removiendo sin parar.","Incorporar el pimiento rojo y el calabacín y saltear, removiendo sin parar.","Añadir salsa de soja y saltear hasta que las verduras queden brillantes y al dente.","Servir las verduras espolvoreadas con sésamo tostado."}', 'Verduras salteadas al wok con el brillo del salteado rápido y los colores vivos intactos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_062', 'Chips de boniato al horno', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 35, 'facil', 'all', 190, 2, 32, 6, 2, true, false, '{}', '[{"name":"Boniato","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar boniato bajo el grifo y secar la piel con un paño limpio.","Laminar el boniato en rodajas muy finas (2-3 mm) con mandolina o cuchillo.","Secar las láminas de boniato con un paño limpio hasta que no quede humedad visible.","Colocar las láminas en un bol y añadir aceite de oliva, sal y pimentón dulce.","Mezclar bien hasta que todas las láminas queden cubiertas de forma uniforme.","Extender las láminas en una sola capa sobre una bandeja con papel vegetal, sin superponerlas.","Hornear en el centro del horno durante 12 min hasta que empiecen a dorarse.","Dar la vuelta a cada lámina y hornear 8-10 min más hasta que estén doradas y crujientes.","Retirar la bandeja del horno y dejar reposar las chips 2 min para que terminen de crujir.","Servir las chips de boniato recién hechas, en caliente."}', 'Chips de boniato finas y crujientes, horneadas y más dulces que la patata clásica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('guarniciones_063', 'Patatas aplastadas al horno (smashed potatoes)', 'guarniciones', 'none', 'patatas', ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, 'horno', 45, 'facil', 'all', 230, 4, 32, 9, 2, true, false, '{}', '[{"name":"Patata baby","amount":450,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Cocer patata baby enteras con piel en agua con sal a fuego fuerte hasta que estén tiernas.","Precalentar el horno a 220 °C con calor arriba y abajo.","Picar romero fresco fino.","Picar ajo muy fino.","Mezclar aceite de oliva con el ajo picado y el romero picado en un bol pequeño.","Escurrir las patatas baby cocidas y dejarlas reposar 2 min para que suelten el vapor.","Disponer las patatas escurridas sobre una bandeja con papel vegetal, bien separadas entre sí.","Aplastar cada patata suavemente con el fondo de un vaso hasta que queden aplastadas sin deshacerse.","Rociar las patatas aplastadas con el aceite aromatizado de forma uniforme.","Salpimentar con sal y pimienta negra por encima.","Hornear en el horno precalentado a 220 °C durante 22 min hasta que los bordes estén dorados y crujientes.","Servir las patatas recién salidas del horno."}', 'Patatas baby aplastadas y doradas al horno, con el crujiente que arrasa en redes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_001', 'Tortilla de patatas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 386, 16, 28, 24, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar y laminar las patatas en rodajas de 3 mm y cortar la cebolla en juliana","Calentar el aceite en sartén a fuego medio e incorporar patatas y cebolla","Confitar a fuego suave 20 min removiendo de vez en cuando hasta que estén tiernas","Escurrir en colador y reservar el aceite","Batir los huevos en un bol grande con sal y pimienta","Incorporar las patatas y la cebolla al huevo y remover","Dejar reposar la mezcla 2 min para que el huevo penetre bien","Cuajar en sartén con un poco del aceite reservado 3 min por el primer lado","Dar la vuelta con un plato y cuajar 2 min más; reposar 1 min y servir"}', 'Tortilla de patata con cebolla, jugosa por dentro', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_002', 'Tortilla francesa', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, NULL, 5, 'facil', 'all', 232, 14, 1, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cascar y batir los huevos con sal hasta integrar yema y clara","Calentar el aceite en sartén antiadherente a fuego medio-alto","Verter el huevo, mover el centro con espátula en cuanto los bordes cuajen","Doblar cuando el interior esté aún cremoso y deslizar al plato"}', 'Tortilla francesa sencilla, cuajada por fuera y jugosa', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_003', 'Huevos rotos con jamón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 482, 22, 32, 30, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones de unos 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los bastones de patata en el aceite caliente hasta que estén dorados y tiernos por dentro, removiendo de vez en cuando.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Freír huevo en el mismo aceite caliente a fuego medio hasta que la clara esté cuajada y la yema líquida.","Distribuir las patatas en 2 platos y colocar los huevos fritos encima.","Disponer jamón serrano en virutas sobre los huevos y romper las yemas con un tenedor al momento de servir."}', 'Huevos fritos con yema líquida sobre patatas fritas y jamón', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados finos, rocíalas con un poco de aceite y sal, y cocínalas en la airfryer a 190°C durante 18-20 minutos, agitando a mitad. Fríe los huevos en una sartén aparte hasta que la clara cuaje y la yema quede líquida. Sirve las patatas con los huevos rotos y el jamón por encima."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta las patatas en dados, mézclalas con aceite de oliva y sal, y extiéndelas en una bandeja de horno. Hornea a 200°C durante 25-30 minutos, hasta que estén tiernas y doradas. Retira, haz huecos y casca los huevos, horneando 5-8 minutos más hasta que la clara cuaje y la yema esté al gusto. Rompe los huevos sobre las patatas y reparte el jamón por encima."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_004', 'Revuelto de champiñones', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 268, 16, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo y laminar.","Picar ajo fino.","Picar perejil fino y reservar.","Batir huevo en un bol hasta que estén homogéneos y reservar.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Saltear el ajo picado hasta que empiece a dorarse, sin dejar que se queme.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Bajar el fuego a fuego suave y añadir los huevos batidos sobre los champiñones.","Remover suavemente con una espátula hasta que los huevos cuajen cremosos, sin pasarse de cocción.","Servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de huevos con champiñones y ajo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_005', 'Revuelto de ajetes', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 248, 14, 4, 20, 2, false, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajetes tiernos","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Gambas","amount":80,"unit":"g"}]'::jsonb, '{"Cortar ajetes tiernos en trozos de unos 2 cm.","Batir huevo en un bol hasta homogeneizar la clara y la yema.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír los ajetes troceados a fuego medio hasta que estén tiernos y ligeramente dorados, unos 3 min.","Añadir gambas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Bajar el fuego a suave y verter los huevos batidos sobre el conjunto.","Remover con movimientos lentos y continuos a fuego suave hasta que el huevo cuaje cremoso sin secarse.","Retirar la sartén del fuego y servir de inmediato en plato caliente."}', 'Revuelto cremoso de ajetes tiernos con gambas', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_006', 'Tortilla de calabacín', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 278, 14, 8, 22, 2, true, true, '{"huevo"}', '[{"name":"Calabacín","amount":250,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y cortar en medias lunas finas.","Lavar calabacín y cortar en medias lunas finas.","Calentar aceite de oliva en sartén a fuego medio.","Añadir el calabacín y la cebolla; sofreír a fuego suave hasta que estén tiernos y translúcidos.","Batir huevo en un bol hasta que estén homogéneos.","Escurrir el calabacín y la cebolla pochados y reservar el aceite sobrante.","Añadir el calabacín y la cebolla escurridos al huevo batido, salpimentar y mezclar bien.","Calentar en la sartén un poco del aceite reservado a fuego medio y verter la mezcla.","Cuajar a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente cremoso.","Dar la vuelta con un plato y cuajar por el otro lado hasta que esté dorada.","Retirar la tortilla de la sartén y servir."}', 'Tortilla de calabacín y cebolla pochada', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_007', 'Huevos fritos con puntillas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 312, 14, 1, 28, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Verter aceite de oliva en una sartén pequeña y calentar a fuego fuerte hasta que humee ligeramente.","Cascar huevo de uno en uno sobre un cuenco pequeño para comprobar que están en buen estado.","Deslizar 1 huevo con cuidado al centro de la sartén con el aceite muy caliente.","Inclinar la sartén y bañar la clara continuamente con el aceite caliente hasta que los bordes burbujeen y formen puntillas doradas.","Retirar el huevo cuando la clara esté cuajada y crujiente en los bordes pero la yema permanezca líquida. Reservar.","Repetir el proceso con los 3 huevos restantes, de uno en uno, bañando siempre con el aceite caliente.","Servir los huevos de inmediato en plato caliente."}', 'Huevos fritos en abundante aceite con bordes crujientes', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_008', 'Revuelto de espárragos', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 238, 14, 6, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espárragos trigueros","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Laminar ajo.","Cortar espárragos trigueros en trozos de unos 3 cm, desechando la parte leñosa del extremo.","Cascar huevo en un bol y batir hasta que la yema y la clara queden integradas.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado en la sartén a fuego medio hasta que esté dorado.","Añadir los espárragos a la sartén y saltear a fuego medio hasta que estén tiernos.","Añadir los huevos batidos sobre los espárragos y remover a fuego suave hasta que el huevo cuaje cremoso y jugoso.","Retirar la sartén del fuego y servir de inmediato."}', 'Revuelto cremoso de huevos con espárragos trigueros', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_009', 'Huevos al plato', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 20, 'facil', 'all', 328, 18, 10, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":120,"unit":"ml"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Chorizo","amount":30,"unit":"g"}]'::jsonb, '{"Cortar chorizo en rodajas finas y reservar.","Cortar jamón serrano en trozos pequeños y reservar.","Precalentar el horno a 200 °C con calor arriba y abajo.","Verter aceite de oliva en el fondo de 2 cazuelitas de barro y repartirlo bien.","Repartir tomate triturado a partes iguales entre las 2 cazuelitas.","Distribuir guisantes, el jamón serrano y el chorizo en rodajas sobre el tomate de cada cazuelita.","Cascar huevo con cuidado, 2 en cada cazuelita, sin romper la yema.","Hornear las cazuelitas a 200 °C durante 10 min, hasta que la clara cuaje y la yema quede ligeramente líquida.","Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa."}', 'Huevos horneados en cazuelita con tomate, jamón y guisantes', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. En cazuelitas individuales, vierte el tomate, guisantes, jamón y chorizo. Haz un hueco y casca el huevo. Hornea 15-20 minutos hasta que la clara esté cuajada y la yema líquida."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 170°C. En una cazuelita apta para airfryer, distribuye el tomate, guisantes, jamón y chorizo, y casca el huevo. Cocina durante 12-15 minutos hasta que la clara esté firme y la yema a tu gusto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_010', 'Huevos rellenos', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 298, 18, 6, 22, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Atún en conserva","amount":80,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Pimiento morrón","amount":30,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua en un cazo a fuego fuerte. Añadir huevo con cuidado y cocer durante 10 min a fuego medio.","Escurrir los huevos y sumergirlos en agua fría hasta que estén completamente fríos.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Extraer las yemas con una cucharilla y reservarlas en un bol. Reservar las claras en una fuente.","Cortar pimiento morrón en trozos muy pequeños.","Añadir al bol con las yemas atún en conserva, mayonesa y el pimiento morrón picado. Mezclar hasta obtener una pasta homogénea.","Rellenar cada clara con la mezcla usando una cucharilla, formando un montículo generoso.","Napar cada huevo relleno con tomate triturado y servir."}', 'Huevos cocidos rellenos de atún y mayonesa con tomate', '[{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Cuece los huevos al vapor durante 12-15 minutos para que queden perfectos y fáciles de pelar. Luego, solo tienes que preparar el relleno manualmente y montar los huevos."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina los huevos en la olla express con un poco de agua durante 5-7 minutos a presión alta. Enfría rápidamente para facilitar el pelado y luego procede con el relleno manual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_011', 'Revuelto de gambas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 288, 22, 2, 22, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Batir huevo en un bol hasta que estén homogéneos.","Picar perejil finamente y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Bajar a fuego suave y añadir el huevo batido sobre las gambas.","Remover suavemente con una espátula hasta que el huevo esté cremoso y cuajado a punto.","Retirar del fuego y servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de huevos con gambas al ajillo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_012', 'Tortilla de espinacas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 256, 16, 4, 20, 2, true, true, '{"huevo"}', '[{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar y picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que esté dorado.","Añadir espinacas frescas y saltear a fuego medio hasta que reduzcan por completo.","Retirar las espinacas de la sartén y escurrir bien el líquido sobrante.","Cortar las espinacas escurridas en trozos gruesos.","Batir huevo en un bol hasta homogeneizar.","Mezclar las espinacas picadas con los huevos batidos y salpimentar al gusto.","Calentar aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla de huevo y espinacas en la sartén y cocer hasta que los bordes estén cuajados, unos 3 min.","Dar la vuelta a la tortilla con un plato y cuajar el otro lado hasta que esté hecha, unos 3 min.","Retirar y servir en plato."}', 'Tortilla jugosa de espinacas salteadas con ajo', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_013', 'Huevos a la flamenca', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 372, 20, 18, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Chorizo","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"}]'::jsonb, '{"Cortar cebolla en brunoise fina y pimiento rojo en tiras de 1 cm.","Cortar chorizo en rodajas de 5 mm y jamón serrano en taquitos pequeños.","Calentar aceite de oliva en una cazuela de barro o sartén apta para horno a fuego medio.","Sofreír la cebolla picada y el pimiento rojo en tiras hasta que estén tiernos, unos 5 min a fuego medio.","Añadir el chorizo en rodajas y el jamón en taquitos; sofreír 2 min hasta que suelten su grasa.","Añadir tomate triturado y guisantes; remover y cocer a fuego medio-suave 8 min hasta que la salsa espese.","Precalentar el horno a 200 °C con calor arriba y abajo.","Repartir la base de sofrito en 2 cazuelitas individuales aptas para horno, dejando hueco en el centro.","Cascar huevo con cuidado, 2 por cazuelita, sobre la base de sofrito sin romper la yema.","Hornear las cazuelitas a 200 °C durante 8-10 min hasta que la clara esté cuajada y la yema aún jugosa.","Retirar del horno con cuidado y servir las cazuelitas directamente en la mesa."}', 'Huevos al horno sobre sofrito con pimiento, jamón y chorizo', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara un sofrito con la cebolla, pimiento y tomate. Distribúyelo en cazuelitas individuales con los guisantes, jamón y chorizo. Haz un hueco, casca los huevos y hornea a 180°C durante 15-20 minutos hasta que las claras estén cuajadas y las yemas a tu gusto."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén o microondas. Distribúyelo en ramequines aptos para airfryer con el resto de ingredientes, casca los huevos y cocina a 160-170°C durante 10-12 minutos. Vigila para que las yemas queden a tu gusto."},{"appliance":"microondas","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito en un bol apto para microondas. Distribúyelo en tazas o ramequines individuales con el resto de ingredientes. Casca los huevos, pincha ligeramente las yemas y cocina a media potencia (500W) en intervalos de 1 minuto hasta que las claras cuajen, vigilando para no sobrecocer las yemas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_014', 'Huevos cocidos con ensalada', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'verano', 286, 16, 8, 22, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Lechuga","amount":100,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar una olla con agua abundante a ebullición a fuego fuerte.","Introducir huevo con cuidado y cocer a fuego medio durante 10 min.","Cortar lechuga en trozos y distribuir en una fuente o bol grande.","Cortar tomate en gajos y añadir sobre la lechuga.","Cortar pepino en rodajas y añadir a la fuente.","Añadir aceitunas a la fuente con el resto de la ensalada.","Escurrir los huevos y sumergir en agua fría durante 2 min hasta que estén templados.","Pelar los huevos y cortar cada uno en 4 cuartos.","Aliñar la ensalada con aceite de oliva y vinagre, y remover con suavidad.","Disponer los cuartos de huevo sobre la ensalada y servir de inmediato."}', 'Huevos cocidos en cuartos sobre ensalada mixta aliñada', '[{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Calienta agua en la base de la vaporera hasta que hierva. Coloca los huevos en la cesta y cocina al vapor durante 12-15 minutos para huevos duros fáciles de pelar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_015', 'Revuelto de setas', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'invierno', 274, 15, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino.","Cortar setas variadas en trozos irregulares de bocado.","Cascar huevo en un bol y batirlos hasta integrar la clara y la yema.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Añadir el ajo picado y saltear hasta que empiece a dorarse, sin que se queme.","Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten el agua y se doren.","Salpimentar las setas al gusto y bajar el fuego a suave.","Verter los huevos batidos sobre las setas y remover suavemente con espátula hasta que cuajen de forma cremosa.","Retirar la sartén del fuego cuando los huevos aún estén ligeramente líquidos; el calor residual los termina.","Servir de inmediato con el perejil picado esparcido por encima."}', 'Revuelto cremoso de setas de temporada con ajo y perejil', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_016', 'Pisto con huevos', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'verano', 310, 16, 14, 22, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":180,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate maduro","amount":180,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados pequeños.","Cortar pimiento rojo, pimiento verde y calabacín en dados pequeños.","Pelar tomate maduro y cortar en dados pequeños.","Calentar 20 ml de aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida, unos 4 min.","Añadir los pimientos y sofreír 5 min hasta que estén tiernos.","Incorporar el calabacín, remover y cocer 4 min.","Añadir el tomate, tapar y cocer a fuego suave hasta que las verduras estén tiernas, unos 12 min.","Calentar el resto del aceite en una sartén a fuego medio.","Freír los huevos hasta que la clara esté cuajada y la yema líquida.","Servir el pisto en plato con el huevo frito encima."}', 'Pisto de verduras con huevos fritos encima, para acompañar con guarnición', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara el pisto en sartén. Fríe los huevos en sartén aparte o casca los huevos sobre el pisto caliente y termina 3-4 min en airfryer a 180 °C hasta cuajar la clara."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Prepara el pisto en cazuela. Reparte en dos cazuelitas, casca un huevo (o dos) encima de cada una y hornea a 180 °C durante 8-10 min hasta que la clara cuaje y la yema quede líquida."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_017', 'Pisto con huevo y patatas fritas', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'verano', 520, 20, 38, 32, 2, true, false, '{"huevo"}', '[{"name":"Calabacín","amount":180,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate maduro","amount":180,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en bastones de 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte.","Freír los bastones de patata hasta que estén dorados y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Picar cebolla y ajo en dados pequeños.","Cortar pimiento rojo, pimiento verde y calabacín en dados pequeños.","Pelar tomate maduro y cortar en dados pequeños.","Calentar un chorrito de aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo hasta que la cebolla esté translúcida.","Añadir el pimiento rojo y el pimiento verde y sofreír hasta que estén tiernos.","Añadir el calabacín y remover para integrar con las verduras.","Cocer el conjunto hasta que el calabacín empiece a ablandarse.","Añadir el tomate maduro, tapar y cocer a fuego suave hasta que todo esté tierno.","Freír huevo en sartén con el aceite restante a fuego medio hasta que la clara esté cuajada.","Servir el pisto en el plato con las patatas fritas al lado y el huevo frito encima."}', 'Pisto manchego con huevos fritos y patatas fritas', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Prepara el pisto en sartén como de costumbre. Corta las patatas en bastones, rocía con aceite y cocina en la airfryer a 190 °C durante 18-20 min, agitando a mitad. Fríe los huevos en sartén y emplata el pisto con las patatas y el huevo encima."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara el pisto en cazuela. Extiende las patatas en bastones con aceite en una bandeja y hornea a 200 °C durante 30-35 min. Fríe los huevos en sartén y sirve junto al pisto y las patatas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_018', 'Tortilla francesa rellena de queso y espinacas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 320, 20, 4, 25, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":80,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar aceite de oliva en sartén a fuego medio.","Añadir espinacas frescas y saltear hasta que reduzcan de volumen.","Retirar las espinacas salteadas de la sartén y reservar.","Batir huevo en un bol hasta integrar bien.","Calentar aceite de oliva en la sartén limpia a fuego medio.","Verter la mitad del huevo batido y dejar que los bordes cuajen.","Repartir la mitad de queso rallado y la mitad de las espinacas sobre una mitad de la tortilla.","Doblar la tortilla sobre el relleno y bajar a fuego suave hasta que el queso funda.","Deslizar la primera tortilla al plato y repetir desde el paso 5 con el resto de ingredientes.","Servir las 2 tortillas inmediatamente, con el queso aún fundido."}', 'Tortilla francesa doblada con queso fundido y espinacas salteadas por dentro', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_019', 'Revuelto exprés de gambas congeladas y ajo', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 300, 26, 3, 20, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas congeladas","amount":200,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Descongelar gambas peladas congeladas bajo el grifo con agua fría hasta que estén blandas.","Escurrir las gambas y secar bien con papel de cocina para eliminar el exceso de agua.","Picar ajo fino.","Picar perejil fino.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado unos segundos hasta que aromatice sin que se dore.","Saltear las gambas a fuego fuerte hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","Remover con espátula de forma continua hasta que el huevo cuaje cremoso sin secarse.","Retirar del fuego y espolvorear el perejil picado. Servir de inmediato."}', 'Revuelto rápido de gambas y ajo, listo en diez minutos', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_020', 'Huevos revueltos con salmón ahumado exprés', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 8, 'facil', 'all', 300, 21, 2, 23, 2, true, false, '{"huevo","pescado","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":30,"unit":"ml"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Cortar salmón ahumado en tiras finas.","Picar cebollino muy fino.","Batir huevo junto con nata para cocinar en un bol hasta obtener una mezcla homogénea.","Calentar sartén a fuego suave y fundir mantequilla hasta que espume sin dorarse.","Verter la mezcla de huevo en la sartén y remover despacio con espátula de forma continua.","Incorporar la mitad del salmón cuando el huevo empiece a cuajar en grumos cremosos.","Retirar la sartén del fuego y remover 30 segundos más; el calor residual termina de cuajar el huevo.","Repartir los huevos revueltos en 2 platos.","Coronar con el resto del salmón y el cebollino picado. Servir enseguida."}', 'Huevos revueltos cremosos con tiras de salmón ahumado, listos en cinco minutos', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_021', 'Revuelto de jamón y queso con ensalada de aguacate, tomate y cebollino', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 26, 10, 40, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso curado","amount":30,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar jamón cocido en dados pequeños.","Rallar queso curado finamente.","Batir huevo en un bol con sal hasta que estén bien integrados.","Cortar aguacate en dados medianos.","Cortar tomate en dados medianos.","Picar cebollino fino.","Mezclar el aguacate y el tomate en un bol.","Aliñar la ensalada con aceite de oliva, vinagre de vino y el cebollino picado.","Calentar aceite de oliva en sartén a fuego medio.","Saltear el jamón cocido en la sartén hasta que esté ligeramente dorado.","Verter el huevo batido sobre el jamón y remover con espátula a fuego medio.","Añadir el queso rallado y seguir removiendo hasta obtener un revuelto cremoso.","Retirar la sartén del fuego cuando el revuelto esté cuajado pero aún jugoso.","Servir el revuelto junto a la ensalada de aguacate y tomate."}', 'Revuelto cremoso de jamón y queso junto a una ensalada fresca de aguacate y tomate', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_022', 'Tortilla francesa de queso de cabra y espinacas con ensalada de tomate y albahaca', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 380, 19, 7, 30, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso de cabra","amount":60,"unit":"g"},{"name":"Espinacas frescas","amount":60,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar sartén a fuego medio con aceite de oliva y añadir espinacas frescas.","Saltear las espinacas hasta que reduzcan por completo, luego retirar y reservar.","Cortar tomate en gajos y disponer en un plato.","Añadir albahaca fresca troceada sobre el tomate.","Aliñar el tomate con aceite de oliva y vinagre de vino.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar la misma sartén a fuego medio con aceite de oliva y verter la mitad del huevo batido.","Repartir la mitad de queso de cabra en trozos y la mitad de las espinacas reservadas sobre una mitad de la tortilla cuando cuajen los bordes.","Doblar la tortilla y dejar fundir el queso hasta que el interior esté cremoso.","Deslizar la primera tortilla a un plato.","Repetir el proceso con el resto del huevo batido, el queso de cabra y las espinacas para hacer la segunda tortilla.","Servir cada tortilla junto a la ensalada de tomate y albahaca."}', 'Tortilla francesa verde por dentro con queso de cabra fundido, junto a tomate y albahaca frescos', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_023', 'Huevos fritos con jamón serrano y ensalada de aguacate, tomate y albahaca', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 480, 23, 10, 39, 2, true, false, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar aguacate en dados de 1 cm.","Cortar tomate en dados de 1 cm.","Picar albahaca fresca en trozos gruesos.","Mezclar el aguacate, el tomate y la albahaca en un bol.","Aliñar la ensalada con vinagre de vino y la mitad de aceite de oliva. Remover y reservar.","Calentar el resto del aceite de oliva en sartén a fuego fuerte.","Freír huevo de 2 en 2 hasta que la clara esté cuajada y la puntilla dorada, con la yema líquida.","Escurrir los huevos fritos sobre papel absorbente y reservar. Repetir con los 2 huevos restantes.","Repartir los huevos fritos en 2 platos y colocar jamón serrano en lonchas encima.","Servir la ensalada de aguacate, tomate y albahaca junto a los huevos y el jamón."}', 'Huevos fritos con jamón serrano y una ensalada fresca de aguacate, tomate y albahaca', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_024', 'Revuelto de gambas con ensalada de aguacate, mango y cilantro', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 500, 27, 21, 35, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mango","amount":150,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar aguacate y mango en dados de 1 cm.","Picar cilantro fresco fino.","Exprimir lima y reservar el zumo.","Mezclar el aguacate, el mango y el cilantro picado en un bol.","Aliñar la mezcla con el zumo de lima y reservar.","Batir huevo en un bol hasta que queden homogéneos.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear gambas peladas 2 min hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas.","Remover con espátula sin parar hasta que el huevo cuaje cremoso.","Retirar la sartén del fuego en cuanto el revuelto esté jugoso.","Repartir el revuelto en 2 platos y servir con la ensalada de aguacate, mango y cilantro al lado."}', 'Revuelto de gambas junto a una ensalada tropical de aguacate, mango y cilantro con vinagreta cítrica', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_025', 'Tortilla francesa de brie y nueces con ensalada de canónigos y pera', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 490, 20, 15, 39, 2, true, false, '{"huevo","lactosa","frutos_secos","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso brie","amount":60,"unit":"g"},{"name":"Nueces","amount":30,"unit":"g"},{"name":"Canónigos","amount":60,"unit":"g"},{"name":"Pera","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar queso brie en trozos pequeños.","Picar nueces groseramente.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Laminar pera en láminas finas.","Mezclar canónigos con la pera laminada en un bol.","Aliñar la ensalada con aceite de oliva y vinagre de vino.","Calentar sartén a fuego medio con la mitad del aceite de oliva restante.","Verter la mitad del huevo batido en sartén caliente.","Repartir la mitad del brie y la mitad de las nueces sobre una mitad de la tortilla cuando cuajen los bordes.","Doblar la tortilla sobre el relleno y dejar fundir el queso hasta que esté cremoso.","Deslizar la tortilla al plato y repetir el proceso con el aceite de oliva restante, el huevo, el brie y las nueces.","Servir cada tortilla junto a la ensalada de canónigos y pera."}', 'Tortilla francesa con brie fundido y nueces, junto a una ensalada de canónigos y pera', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_026', 'Bacon crujiente y huevo frito con ensalada de aguacate y rúcula', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 530, 25, 8, 45, 2, true, false, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Bacon en lonchas","amount":60,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Rúcula","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar sartén a fuego fuerte sin aceite hasta que esté bien caliente.","Añadir bacon en lonchas en una sola capa y dorar hasta que esté crujiente, unos 3 min.","Retirar el bacon y escurrir sobre papel absorbente. Reservar la grasa en la sartén.","Laminar aguacate y colocarlo en un bol junto con rúcula.","Aliñar la ensalada con aceite de oliva y vinagre de vino. Reservar.","Freír huevo en la grasa del bacon a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir los huevos fritos y el bacon crujiente entre 2 platos.","Servir la ensalada de aguacate y rúcula aliñada junto al resto del plato."}', 'Bacon crujiente y huevo frito de yema líquida junto a una ensalada de aguacate y rúcula', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_027', 'Tortilla de calabacín y feta con ensalada de tomate cherry y menta', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 375, 16, 8, 30, 2, true, true, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Tomate cherry","amount":150,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":8,"unit":"ml"}]'::jsonb, '{"Cortar calabacín en dados pequeños.","Calentar aceite de oliva en sartén a fuego fuerte y saltear el calabacín hasta que esté tierno y ligeramente dorado.","Cortar tomate cherry por la mitad.","Picar menta fresca en trozos gruesos.","Batir huevo en un bol con sal.","Desmenuzar queso feta y añadirlo al bol junto con el calabacín salteado.","Mezclar bien hasta integrar todos los ingredientes del bol.","Calentar un chorrito del aceite de oliva en sartén antiadherente a fuego medio y verter la mezcla de huevo.","Tapar la sartén y cuajar la tortilla 4 min hasta que los bordes estén firmes y el centro apenas líquido.","Mezclar los tomates cherry con la menta picada, el aceite de oliva restante y vinagre de vino.","Dar la vuelta a la tortilla con ayuda de un plato y cuajar 3 min más por el otro lado.","Retirar la tortilla de la sartén y cortar en porciones.","Servir las porciones de tortilla junto a la ensalada de tomate cherry y menta."}', 'Tortilla jugosa de calabacín y feta junto a una ensalada fresca de tomate cherry y menta', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_028', 'Huevos revueltos con champiñones y ensalada de rúcula, parmesano y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 405, 19, 5, 33, 2, true, false, '{"huevo","lactosa","frutos_secos","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Parmesano en virutas","amount":30,"unit":"g"},{"name":"Piñones","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":8,"unit":"ml"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo y laminar.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear los champiñones laminados hasta que doren y suelten el agua.","Batir huevo en un bol hasta integrar.","Tostar piñones en una sartén pequeña sin aceite a fuego medio hasta que doren ligeramente.","Bajar el fuego al mínimo y verter el huevo batido sobre los champiñones.","Remover con espátula sin parar hasta que el huevo cuaje cremoso y retirar del fuego.","Disponer rúcula en un bol junto con parmesano en virutas y los piñones tostados.","Aliñar la ensalada con el resto del aceite de oliva y vinagre de vino y mezclar.","Servir el revuelto de champiñones junto a la ensalada aliñada."}', 'Revuelto cremoso de champiñones junto a una ensalada de rúcula, parmesano y piñones tostados', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_029', 'Salmón ahumado con huevo revuelto y ensalada de aguacate y eneldo', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 460, 23, 8, 38, 2, true, false, '{"huevo","pescado","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Batir huevo en un bol hasta homogeneizar; salpimentar al gusto.","Cortar aguacate en láminas y reservar en un bol.","Picar eneldo fresco fino y reservar.","Mezclar aceite de oliva, zumo de limón y el eneldo picado en un bol pequeño.","Aliñar las láminas de aguacate con la mezcla de aceite, limón y eneldo; reservar.","Fundir mantequilla en sartén a fuego suave hasta que espume sin dorarse.","Verter el huevo batido en la sartén y remover despacio con espátula a fuego suave.","Retirar la sartén del fuego cuando el huevo cuaje en grumos cremosos y aún brille.","Cortar salmón ahumado en tiras y disponer sobre el revuelto repartido en 2 platos.","Servir la ensalada de aguacate aliñada junto al plato de revuelto y salmón."}', 'Salmón ahumado sobre huevo revuelto cremoso, junto a una ensalada de aguacate y eneldo', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_030', 'Huevos benedictinos con salsa holandesa', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 640, 30, 27, 45, 2, true, false, '{"huevo","lactosa","gluten","sulfitos"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Muffin inglés","amount":2,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que esté completamente líquida; reservar tibia.","Separar 2 yemas de huevo del resto; reservar las yemas en un bol resistente al calor y reservar los 4 huevos enteros aparte.","Añadir zumo de limón a las yemas y batir con varillas hasta mezclar.","Colocar el bol sobre un cazo con agua caliente sin que toque el agua; batir las yemas con el zumo de limón al baño maría.","Incorporar la mantequilla tibia en hilo fino sin dejar de batir hasta que la salsa esté homogénea y cremosa.","Retirar el bol del baño maría y reservar la salsa holandesa en un lugar tibio, tapada.","Llevar a ebullición una cazuela con agua abundante y vinagre de vino a fuego medio.","Bajar el fuego hasta ebullición suave; remover el agua para formar un remolino e introducir 1 huevo entero.","Escalfar el huevo 3 min hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","Repetir el proceso con los 3 huevos enteros restantes de uno en uno; escurrir cada uno sobre papel absorbente.","Cortar muffin inglés por la mitad y tostar en una sartén a fuego medio hasta que estén dorados.","Calentar jamón cocido en la misma sartén a fuego medio, 1 min por cada lado.","Disponer cada mitad de muffin tostada en el plato y colocar encima una porción de jamón cocido.","Colocar 1 huevo escalfado sobre cada porción de jamón.","Napar con la salsa holandesa reservada y servir de inmediato."}', 'Muffin inglés con jamón, huevo escalfado y salsa holandesa recién montada', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_031', 'Huevos rotos con jamón y patatas fritas', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 535, 26, 31, 34, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":70,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en bastones finos tipo paja.","Calentar aceite de oliva en una sartén honda a fuego fuerte hasta que esté bien caliente.","Freír las patatas en 2 tandas hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y salar al gusto.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir las patatas fritas en 2 platos formando una base.","Colocar los huevos fritos encima de las patatas.","Disponer jamón serrano en lonchas sobre los huevos.","Romper las yemas con un tenedor al momento de servir para que se mezclen con las patatas."}', 'Patatas paja crujientes con huevos fritos de yema rota y jamón serrano', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_032', 'Huevos rotos con jamón y foie', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 680, 26, 36, 46, 2, false, false, '{"huevo","sulfitos"}', '[{"name":"Patata","amount":350,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":50,"unit":"g"},{"name":"Foie mi-cuit","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino Pedro Ximénez","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortarlas en bastones finos tipo paja.","Calentar aceite de oliva en sartén honda a fuego fuerte.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Verter vino pedro ximénez en un cazo a fuego suave hasta que espese ligeramente.","Retirar la reducción del fuego y reservar en el cazo.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Cortar foie mi-cuit en lonchas gruesas de aproximadamente 1 cm.","Calentar sartén sin aceite a fuego fuerte hasta que humee.","Marcar las lonchas de foie 30 segundos por cada lado y retirar.","Repartir las patatas fritas en 2 platos y colocar los huevos fritos encima.","Añadir jamón serrano y las lonchas de foie sobre los huevos.","Terminar con un hilo de la reducción de Pedro Ximénez y romper las yemas al servir."}', 'Versión de lujo del clásico de bar: patatas fritas, huevo roto, jamón y foie marcado', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_033', 'Tortilla de patatas con queso curado', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 670, 28, 30, 48, 2, true, true, '{"huevo","lactosa"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Queso curado","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego suave.","Añadir la patata laminada y la cebolla en juliana a la sartén y confitar a fuego suave.","Cortar queso curado en dados pequeños.","Batir huevo en un bol grande con sal hasta obtener una mezcla homogénea.","Escurrir la patata y la cebolla en un colador, reservando el aceite sobrante.","Añadir la patata escurrida, la cebolla escurrida y el queso en dados al bol con el huevo batido.","Remover la mezcla con cuidado para integrar todos los ingredientes sin romper la patata.","Dejar reposar la mezcla en el bol 2 min para que el huevo penetre bien en la patata.","Calentar un poco del aceite reservado en sartén a fuego fuerte hasta que humee ligeramente.","Verter la mezcla en la sartén, extender y cuajar a fuego medio-fuerte durante 3 min hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo a la sartén.","Cuajar el segundo lado a fuego medio 2 min hasta que esté dorado pero el interior jugoso.","Reposar la tortilla en la sartén fuera del fuego 1 min antes de servir.","Servir la tortilla entera o en porciones, con el queso fundido en el interior."}', 'Tortilla de patatas con queso curado fundido por dentro, de aroma intenso', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_034', 'Tortilla abierta de boletus', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'normal', 'all', 335, 18, 6, 26, 2, true, true, '{"huevo"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Limpiar boletus con un paño húmedo y laminarlos.","Picar ajo fino.","Picar perejil fino y reservar.","Batir huevo en un bol con sal hasta que estén homogéneos.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los boletus laminados y saltear a fuego fuerte hasta que suelten el agua y se doren.","Verter el huevo batido sobre los boletus y bajar a fuego medio.","Cuajar sin remover, moviendo la sartén de vez en cuando, hasta que el fondo esté dorado y la superficie aún jugosa.","Espolvorear con el perejil picado y servir directamente desde la sartén."}', 'Tortilla abierta y jugosa con boletus dorados y aroma a bosque', NULL, '{}', true, NULL, NULL, '{}', NULL)
