insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('huevos_035', 'Tortilla de patatas con cebolla caramelizada', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 590, 18, 41, 39, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego suave y sofreír la cebolla 25 min, removiendo de vez en cuando, hasta que empiece a dorarse.","Añadir azúcar a la cebolla y remover a fuego suave hasta que esté caramelizada y muy tierna.","Retirar la cebolla caramelizada de la sartén y reservar en un bol grande.","Calentar aceite de oliva en sartén a fuego suave y confitar las patatas laminadas hasta que estén tiernas.","Escurrir las patatas confitadas para eliminar el exceso de aceite.","Batir huevo en el bol con la cebolla caramelizada hasta obtener una mezcla homogénea.","Añadir las patatas escurridas al bol con la mezcla de huevo y cebolla y remover con cuidado.","Dejar reposar la mezcla 2 min para que el huevo empape bien las patatas.","Calentar un chorrito de aceite de oliva en sartén a fuego medio y volcar la mezcla, distribuyéndola bien.","Cuajar la tortilla a fuego medio-suave hasta que los bordes estén firmes y el centro ligeramente jugoso.","Dar la vuelta a la tortilla con la ayuda de un plato llano y devolver a la sartén.","Cuajar el segundo lado a fuego suave hasta que esté dorado pero el interior quede jugoso.","Retirar la tortilla de la sartén y dejar reposar 3 min antes de servir.","Servir la tortilla cortada en porciones."}', 'Tortilla de patatas con el dulzor de una cebolla muy pochada y caramelizada', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_036', 'Revuelto de setas silvestres', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 18, 'normal', 'all', 305, 15, 5, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas silvestres variadas","amount":250,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":6,"unit":"g"}]'::jsonb, '{"Limpiar setas silvestres variadas con un paño húmedo, retirando bien la tierra.","Cortar las setas en trozos o laminarlas según su tamaño.","Picar ajo fino.","Picar perejil.","Batir huevo en un bol con sal hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir las setas cortadas y saltear a fuego fuerte hasta que suelten el agua y se evapore.","Bajar el fuego a suave y verter el huevo batido sobre las setas.","Remover con espátula con movimientos lentos hasta que el huevo cuaje cremoso y aún jugoso.","Servir de inmediato con el perejil picado por encima."}', 'Revuelto cremoso de setas silvestres de temporada con aroma a bosque', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_037', 'Revuelto de gambas y ajetes', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 330, 24, 6, 22, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":180,"unit":"g"},{"name":"Ajetes","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Retirar la primera capa de ajetes y cortarlos en trozos de 3 cm.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Saltear los ajetes en la sartén hasta que estén tiernos.","Añadir gambas peladas y saltear hasta que cambien de color.","Bajar el fuego a fuego suave y verter el huevo batido sobre las gambas y los ajetes.","Remover con espátula hasta que el huevo cuaje cremoso, sin que llegue a secarse.","Servir de inmediato en plato caliente."}', 'Revuelto de gambas y ajetes tiernos, rosado entre el huevo cuajado', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_038', 'Huevos poché sobre espárragos con holandesa', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 480, 21, 5, 40, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Espárragos verdes","amount":300,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar la parte final dura del tallo de espárragos verdes.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Cocer los espárragos en el agua hirviendo hasta que estén tiernos pero firmes.","Escurrir los espárragos y reservar en caliente.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida; reservar tibia.","Separar 2 yemas de huevo y reservar las claras junto al resto de huevos enteros.","Batir las 2 yemas con zumo de limón al baño maría a fuego suave.","Remover sin parar hasta que las yemas espesen y blanqueen.","Incorporar la mantequilla tibia en hilo fino sin dejar de remover hasta obtener una salsa cremosa.","Salpimentar la salsa holandesa y reservar al baño maría para mantenerla tibia.","Llevar a ebullición suave una cazuela con agua y vinagre de vino a fuego medio.","Remover el agua para formar un remolino y cascar un huevo entero en el centro.","Cocer el huevo hasta que la clara esté cuajada y la yema líquida; retirar con espumadera.","Escurrir el huevo pochado sobre papel absorbente; repetir con los 3 huevos restantes.","Repartir los espárragos en 2 platos y colocar 2 huevos pochados encima de cada uno.","Napar con la salsa holandesa y servir de inmediato."}', 'Espárragos verdes con huevo escalfado y salsa holandesa recién montada', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_039', 'Huevos fritos con jamón y virutas de parmesano', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 355, 26, 2, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Parmesano en virutas","amount":25,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Cascar huevo de uno en uno y freír hasta que la puntilla esté crujiente y la clara cuajada.","Retirar los huevos fritos y escurrir sobre papel absorbente.","Repartir los huevos escurridos en 2 platos.","Colocar jamón serrano sobre los huevos.","Añadir parmesano en virutas por encima y servir de inmediato."}', 'Huevos fritos de puntilla crujiente y yema líquida con jamón serrano y virutas de parmesano', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_040', 'Huevos al plato con chorizo y pimientos', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 398, 21, 16, 29, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar cebolla y ajo fino.","Cortar pimiento rojo y pimiento verde en trozos pequeños.","Laminar chorizo en rodajas finas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el ajo y los pimientos a fuego medio hasta que estén tiernos.","Añadir el chorizo y sofreír hasta que suelte su grasa.","Añadir tomate triturado y salpimentar al gusto.","Cocer a fuego medio hasta que la salsa espese ligeramente.","Repartir el sofrito entre 2 cazuelitas de barro.","Cascar huevo sobre el sofrito, 2 por cazuelita, sin romper la yema.","Hornear hasta que la clara cuaje y la yema quede jugosa.","Servir de inmediato en la misma cazuelita."}', 'Huevos horneados en cazuelita con chorizo, pimientos y tomate, burbujeantes y coloridos recién salidos del horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_041', 'Tortilla de gambas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 320, 28, 4, 22, 2, true, true, '{"huevo","marisco"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Picar perejil muy fino.","Cascar huevo en un bol grande y batir hasta homogeneizar.","Calentar la mitad de aceite de oliva en sartén a fuego medio-alto.","Saltear el ajo picado con gambas peladas hasta que las gambas estén rosadas.","Retirar las gambas y el ajo de la sartén y dejar templar.","Añadir las gambas templadas, el ajo y el perejil picado al huevo batido y mezclar.","Calentar el aceite de oliva restante en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar 2 min, moviendo el centro con espátula.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar 1 min más o hasta alcanzar el punto de cuajado deseado.","Servir la tortilla cortada en porciones."}', 'Tortilla jugosa de gambas frescas salteadas con ajo y perejil, rosadas y visibles entre el huevo cuajado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_042', 'Quiche lorraine', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 520, 20, 32, 36, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Panceta ahumada","amount":100,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":150,"unit":"ml"},{"name":"Queso gruyère rallado","amount":60,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Extender masa quebrada en un molde, presionando bien los bordes.","Pinchar el fondo de la masa con un tenedor para que no suba al hornear.","Hornear la base en blanco a 180 °C durante 10 min hasta que empiece a dorarse ligeramente.","Cortar panceta ahumada en tiras finas.","Dorar la panceta en sartén sin aceite a fuego medio durante 3 min hasta que esté dorada.","Escurrir la panceta sobre papel absorbente y reservar.","Batir huevo con nata en un bol hasta integrar bien.","Repartir la panceta reservada sobre la base horneada.","Espolvorear la mitad de queso gruyère rallado sobre la panceta.","Verter la mezcla de huevo y nata sobre el relleno de manera uniforme.","Espolvorear el resto del queso gruyère rallado por encima.","Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","Dejar reposar la quiche en el molde 5 min antes de cortar.","Cortar en porciones y servir."}', 'Quiche lorraine clásica, con corteza dorada y un relleno cremoso de bacon y queso gruyère.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_043', 'Quiche de puerros y queso de cabra', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 460, 18, 32, 28, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Puerro","amount":200,"unit":"g"},{"name":"Queso de cabra","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":120,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Lavar puerro y cortar en rodajas finas.","Extender masa quebrada en el molde, presionar los bordes y pinchar el fondo con un tenedor.","Hornear la base en blanco 10 min hasta que esté ligeramente dorada.","Calentar aceite de oliva en sartén a fuego suave.","Sofreír el puerro a fuego suave 10 min hasta que esté tierno y sin color.","Batir huevo con nata en un bol hasta obtener una mezcla homogénea.","Salpimentar la mezcla de huevo y nata al gusto.","Repartir el puerro pochado sobre la base horneada.","Desmenuzar queso de cabra por encima del puerro de forma uniforme.","Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","Hornear a 180 °C durante 30 min hasta que la superficie esté dorada y el relleno cuajado.","Reposar la quiche fuera del horno 5 min antes de cortar.","Servir en porciones directamente desde el molde."}', 'Quiche de puerros pochados y queso de cabra, con base crujiente y relleno verde y blanco por dentro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_044', 'Huevos escalfados con salmón ahumado', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'normal', 'all', 340, 20, 24, 18, 2, true, false, '{"huevo","pescado","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Pan de masa madre","amount":120,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de masa madre en rebanadas de unos 2 cm de grosor.","Tostar las rebanadas en una tostadora o sartén a fuego medio hasta que estén doradas y crujientes.","Llevar agua abundante a ebullición en una cazuela ancha; añadir vinagre y bajar a fuego suave.","Cascar huevo de uno en uno en una taza pequeña antes de deslizarlos al agua.","Remover el agua con una cuchara para formar un remolino suave y deslizar el primer huevo al centro.","Repetir con los 3 huevos restantes, deslizando cada uno con cuidado al agua.","Escalfar los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con una espumadera y reservar sobre papel absorbente.","Picar eneldo fresco fino y reservar.","Repartir aceite de oliva sobre las tostadas.","Repartir salmón ahumado sobre las tostadas.","Colocar un huevo escalfado sobre cada tostada.","Espolvorear el eneldo picado por encima y servir de inmediato."}', 'Huevos escalfados de yema líquida sobre tostadas con salmón ahumado y eneldo, rosa contra el blanco del huevo.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_045', 'Huevos rellenos de atún gratinados', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, 'horno', 30, 'facil', 'all', 360, 22, 10, 25, 2, true, false, '{"huevo","pescado","lactosa","gluten"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Leche","amount":150,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"}]'::jsonb, '{"Cocer huevo en agua abundante durante 10 min desde que rompa a hervir.","Retirar los huevos y sumergirlos en agua fría hasta que estén templados.","Pelar los huevos y cortarlos por la mitad a lo largo.","Retirar las yemas con cuidado y reservarlas en un bol; reservar las claras en una fuente de horno.","Escurrir atún en conserva y añadirlo al bol con las yemas.","Machacar las yemas con el atún escurrido hasta obtener una pasta homogénea.","Rellenar cada clara con la pasta de yema y atún y colocarlas en la fuente de horno.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta que se forme una pasta dorada.","Añadir leche poco a poco sin dejar de remover hasta obtener una bechamel fina y sin grumos.","Cubrir los huevos rellenos con la bechamel y espolvorear queso rallado por encima.","Gratinar en el horno a 220 °C durante 8 min hasta que la superficie esté dorada.","Servir templado directamente desde la fuente."}', 'Huevos rellenos de atún cubiertos de bechamel y gratinados hasta dorar, clásico de aperitivo en versión de cena.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_046', 'Tortilla de bacalao', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 310, 28, 4, 19, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Bacalao desalado desmigado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla a fuego medio hasta que esté tierna y transparente.","Batir huevo en un bol grande hasta que estén bien integrados.","Añadir bacalao desalado desmigado a la sartén y saltear a fuego medio hasta que esté cocido.","Retirar la sartén del fuego y dejar templar el bacalao con la cebolla.","Incorporar el bacalao templado y la cebolla al huevo batido y remover hasta mezclar.","Calentar un chorrito de aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla en la sartén y cuajar a fuego medio hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato y deslizarla de nuevo a la sartén.","Cuajar por el segundo lado a fuego medio hasta alcanzar el punto deseado.","Retirar la tortilla de la sartén y dejar reposar antes de servir.","Servir la tortilla entera o cortada en porciones."}', 'Tortilla jugosa de bacalao desmigado y cebolla pochada, con textura melosa entre el huevo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_047', 'Huevos cocotte con nata y champiñones', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 25, 'normal', 'all', 320, 15, 5, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Nata","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Limpiar y laminar champiñones.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar sartén a fuego medio y fundir mantequilla.","Sofreír el ajo picado en la mantequilla fundida hasta que empiece a dorarse.","Añadir los champiñones laminados y saltear a fuego medio hasta que se doren y suelten el agua.","Salpimentar los champiñones y retirar del fuego.","Repartir los champiñones entre 2 cazuelitas individuales.","Verter la mitad de nata sobre los champiñones de cada cazuelita.","Cascar huevo: 2 huevos en cada cazuelita, sobre la nata.","Repartir el resto de la nata alrededor de las yemas en cada cazuelita.","Colocar las cazuelitas en una bandeja con agua caliente hasta la mitad para el baño maría.","Hornear a 180 °C durante 12 min hasta que la clara cuaje y la yema quede cremosa.","Espolvorear el perejil picado sobre cada cazuelita y servir de inmediato."}', 'Huevos cocidos en su propia cazuelita individual con nata y champiñones salteados.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_048', 'Huevos mimosa', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 240, 15, 3, 19, 2, true, false, '{"huevo","mostaza"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Mostaza","amount":5,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en un cazo a fuego fuerte.","Introducir huevo con cuidado y cocer 10 min desde que rompa a hervir.","Escurrir los huevos y sumergir en agua fría hasta que estén templados.","Pelar los huevos con cuidado y cortar cada uno por la mitad a lo largo.","Separar las yemas de las claras y reservar las claras en una fuente.","Machacar las yemas con un tenedor en un bol hasta obtener un granulado fino.","Añadir mayonesa y mostaza a las yemas y mezclar hasta obtener una crema homogénea.","Picar cebollino muy fino.","Rellenar cada clara con la crema de yemas formando un montoncito generoso.","Espolvorear el cebollino picado y pimentón dulce sobre cada huevo.","Refrigerar los huevos rellenos hasta el momento de servir.","Servir los huevos mimosa bien fríos en la fuente."}', 'Huevos rellenos de una crema de yema, mayonesa y mostaza, con la yema rallada como nieve sobre la clara.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_049', 'Soufflé de queso', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 45, 'elaborada', 'all', 400, 19, 16, 28, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Queso gruyère rallado","amount":100,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Untar 2 moldes individuales con mantequilla.","Separar las claras de las yemas de huevo en 2 boles distintos.","Fundir la mantequilla restante en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta que la mezcla se despegue del cazo.","Incorporar leche poco a poco sin dejar de remover a fuego medio.","Cocer hasta que la bechamel espese y se despegue de las paredes; retirar del fuego.","Añadir las yemas una a una a la bechamel templada, batiendo bien tras cada adición.","Añadir queso gruyère rallado y mezclar hasta integrar por completo.","Montar las claras en un bol limpio a punto de nieve firme.","Incorporar un tercio de las claras a la mezcla de bechamel con movimientos envolventes para aligerarla.","Añadir el resto de las claras en 2 tandas con movimientos envolventes hasta integrar sin bajar la espuma.","Repartir la mezcla en los moldes hasta ¾ de su capacidad.","Hornear 20 min sin abrir el horno hasta que los soufflés suban y estén dorados.","Servir de inmediato, recién sacados del horno."}', 'Soufflé de queso que sube dorado y esponjoso en el horno, para servir al momento.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_050', 'Huevos con jamón y bechamel gratinados', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 430, 25, 17, 29, 2, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Jamón cocido","amount":100,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Queso rallado","amount":50,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua en un cazo a fuego fuerte.","Cocer huevo desde que rompa a hervir, a fuego medio, durante 10 min.","Precalentar el horno a 200 °C con función gratinador.","Retirar los huevos del cazo y sumergirlos en agua fría hasta que estén templados.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Cortar jamón cocido en tiras.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar durante 1 min hasta obtener una pasta homogénea.","Añadir leche poco a poco sin dejar de remover a fuego medio hasta que la bechamel esté fina.","Salpimentar la bechamel y retirar el cazo del fuego.","Colocar los huevos con el corte hacia arriba en una fuente de horno y distribuir el jamón cocido entre ellos.","Cubrir con la bechamel caliente hasta que los huevos queden completamente cubiertos.","Espolvorear queso rallado de manera uniforme por toda la superficie.","Gratinar en el horno a 200 °C durante 10 min hasta que la superficie esté dorada y burbujeante.","Servir caliente directamente de la fuente."}', 'Huevos cocidos con jamón cubiertos de bechamel y gratinados, con el huevo escondido debajo del dorado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_051', 'Tortilla paisana', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 410, 20, 28, 24, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Judías verdes","amount":60,"unit":"g"},{"name":"Guisantes","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Jamón cocido","amount":50,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en dados pequeños.","Cortar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Trocear judías verdes en piezas de unos 2 cm.","Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer las judías verdes troceadas y guisantes 5 min hasta que estén tiernos.","Escurrir las judías verdes y los guisantes y reservar.","Cortar jamón cocido en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Añadir la patata y la cebolla y confitar a fuego suave 12 min hasta que estén tiernos.","Añadir el pimiento rojo y sofreír a fuego medio 3 min hasta que esté tierno.","Añadir las judías verdes, los guisantes y el jamón cocido y sofreír 2 min.","Escurrir el conjunto con un colador y reservar el aceite sobrante.","Batir huevo en un bol grande hasta que estén homogéneos.","Incorporar la patata, la cebolla, el pimiento, las judías, los guisantes y el jamón cocido a los huevos batidos.","Dejar reposar la mezcla 2 min para que los huevos impregnen bien el conjunto.","Calentar un chorrito del aceite reservado en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar a fuego medio 3 min hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato y devolverla a la sartén.","Cuajar el segundo lado a fuego medio 2 min hasta alcanzar el punto deseado.","Servir la tortilla en un plato, entera o en porciones."}', 'Tortilla cuajada con patata, verduras y jamón, colorida y contundente.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_052', 'Huevos turcos (cilbir) con yogur y mantequilla de pimentón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 380, 17, 22, 25, 2, false, false, '{"huevo","lactosa","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Yogur griego","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Pan","amount":100,"unit":"g"}]'::jsonb, '{"Rallar ajo muy fino sobre un bol pequeño.","Añadir yogur griego al bol con el ajo rallado y mezclar hasta integrar.","Salpimentar el yogur con ajo al gusto y remover.","Repartir el yogur en 2 platos hondos y reservar.","Tostar pan en sartén a fuego medio hasta que esté crujiente por ambos lados.","Calentar agua en una cazuela con vinagre hasta que rompa a hervir suave.","Escalfar huevo de 2 en 2: cascar cada uno en un cuenco y deslizar al agua con cuidado.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con espumadera y escurrir sobre papel de cocina.","Fundir mantequilla en un cazo pequeño a fuego suave hasta que empiece a dorarse.","Retirar el cazo del fuego e incorporar pimentón dulce, removiendo rápido para que no se queme.","Colocar los huevos escalfados sobre el yogur de cada plato.","Rociar con la mantequilla de pimentón y servir de inmediato con el pan tostado."}', 'Huevos escalfados turcos sobre yogur de ajo, con yogur blanco y mantequilla de pimentón roja y brillante encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_053', 'Huevos poché sobre aguacate y tostada', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 380, 16, 30, 22, 2, true, false, '{"huevo","gluten","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Pan de masa madre","amount":120,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de masa madre en rebanadas de grosor medio.","Tostar las rebanadas en el tostador hasta que estén doradas.","Cortar aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Machacar la pulpa de aguacate en un bol con zumo de limón hasta obtener una crema con textura.","Llevar a ebullición agua en una cazuela ancha con vinagre.","Reducir el fuego hasta mantener un hervor muy suave.","Cascar huevo de uno en uno en una taza y deslizarlo con cuidado al agua girando para formar un remolino.","Escalfar los huevos hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos con una espumadera y escurrir sobre papel absorbente.","Untar las tostadas con la crema de aguacate.","Colocar 2 huevos escalfados sobre cada tostada.","Rociar con aceite de oliva y servir de inmediato."}', 'Tostada de aguacate cremoso coronada con huevo escalfado de yema rota, verde y jugosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_054', 'Tortilla francesa rellena de jamón y queso', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 350, 24, 3, 27, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar jamón cocido en tiras o dados pequeños.","Batir huevo en un bol hasta integrar yemas y claras.","Salpimentar el huevo batido al gusto y remover.","Calentar aceite de oliva en sartén a fuego medio.","Verter la mitad del huevo batido en la sartén y dejar cuajar los bordes.","Distribuir la mitad del jamón cocido y queso en lonchas sobre una mitad de la tortilla.","Doblar la mitad libre de la tortilla sobre el relleno con la espátula.","Cocer a fuego suave hasta que el queso empiece a fundirse.","Retirar la tortilla y reservar en un plato caliente.","Repetir los pasos 4 a 9 con el resto del huevo batido, el jamón cocido y el queso en lonchas.","Servir las 2 tortillas de inmediato mientras el queso está fundido."}', 'Tortilla francesa rellena de jamón y queso, que se derrama al doblarla.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_055', 'Huevos fritos con patatas paja y pimentón', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 16, 32, 32, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en tiras muy finas tipo paja.","Secar bien las patatas paja con un paño limpio para eliminar el exceso de almidón y humedad.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír la mitad de las patatas paja hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel absorbente y reservar.","Freír la segunda tanda de patatas paja hasta que estén doradas y crujientes.","Escurrir la segunda tanda sobre papel absorbente y reservar junto a las anteriores.","Freír huevo en el mismo aceite a fuego medio hasta que la clara esté cuajada y la yema líquida.","Repartir las patatas paja reservadas en 2 platos formando un nido.","Colocar los huevos fritos sobre las patatas paja.","Espolvorear pimentón dulce sobre los huevos y las patatas antes de servir."}', 'Huevos fritos de puntilla crujiente sobre una nube de patata paja con pimentón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_056', 'Revuelto de morcilla y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 430, 17, 7, 37, 2, false, false, '{"huevo","frutos_secos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Morcilla de Burgos","amount":150,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Retirar la piel de morcilla de burgos y desmenuzarla con los dedos o un tenedor hasta obtener trozos irregulares.","Batir huevo en un bol hasta que estén homogéneos.","Tostar piñones en sartén seca a fuego suave hasta que estén dorados.","Retirar los piñones tostados y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio.","Añadir la morcilla desmenuzada y saltear a fuego medio hasta que esté crujiente por fuera.","Bajar el fuego a suave y verter los huevos batidos sobre la morcilla.","Remover suavemente con una espátula hasta que el huevo cuaje cremoso.","Retirar la sartén del fuego, espolvorear los piñones tostados por encima y servir de inmediato."}', 'Revuelto cremoso de morcilla de Burgos, oscuro y cremoso, con piñones tostados por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_057', 'Revuelto de espárragos trigueros con jamón', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 300, 20, 5, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espárragos trigueros","amount":150,"unit":"g"},{"name":"Jamón serrano","amount":50,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar espárragos trigueros, retirar la parte dura del tallo y cortar en trozos de 3 cm.","Cortar jamón serrano en tiras finas.","Picar ajo fino.","Batir huevo en un bol hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los espárragos y saltear a fuego medio hasta que estén tiernos.","Incorporar el jamón serrano en tiras y saltear hasta que se integre con los espárragos.","Bajar el fuego a suave y verter los huevos batidos sobre la sartén.","Remover con movimientos lentos y continuos hasta que los huevos cuajen cremosos sin secarse.","Servir de inmediato en plato caliente."}', 'Revuelto jugoso de espárragos trigueros con jamón serrano, verde y rosado entre el huevo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_058', 'Huevos escalfados sobre puré de patata', 'huevos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 360, 14, 34, 18, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Cebollino","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Cocer las patatas en una olla con agua con sal hasta que estén tiernas.","Calentar leche y mantequilla en un cazo a fuego suave hasta que la mantequilla se funda.","Escurrir bien las patatas cocidas y pasarlas por el pasapurés sobre un bol grande.","Añadir la leche caliente al puré poco a poco, removiendo hasta obtener una textura cremosa.","Salpimentar el puré y reservar tapado para que se mantenga caliente.","Picar cebollino fino y reservar.","Llevar a ebullición agua en una cazuela ancha con vinagre a fuego medio.","Reducir el fuego hasta que el agua hierva suave, sin borbotones fuertes.","Cascar huevo uno a uno en un cuenco pequeño y deslizar con cuidado al agua.","Cocer los huevos hasta que la clara esté cuajada y la yema líquida.","Retirar los huevos escalfados con una espumadera y escurrir sobre papel de cocina.","Repartir el puré caliente en 2 platos hondos formando una base generosa.","Colocar 2 huevos escalfados sobre el puré de cada plato.","Espolvorear el cebollino picado por encima y servir de inmediato."}', 'Huevos escalfados sobre un puré de patata cremoso, con la yema hundiéndose despacio en lo cremoso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_059', 'Tortilla de calabacín y queso', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 340, 20, 8, 24, 2, true, true, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Calabacín","amount":250,"unit":"g"},{"name":"Queso rallado","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Lavar calabacín y cortar en dados pequeños.","Picar cebolla en trozos finos.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el calabacín en dados y saltear a fuego medio hasta que esté tierno y algo dorado.","Salpimentar el calabacín y la cebolla al gusto.","Retirar la sartén del fuego y dejar templar el sofrito.","Batir huevo en un bol grande hasta que estén bien mezclados.","Añadir el sofrito templado de calabacín y cebolla al bol con los huevos batidos.","Incorporar queso rallado y remover hasta que todo quede bien integrado.","Calentar un chorrito de aceite de oliva en la sartén limpia a fuego medio.","Verter la mezcla de huevos en la sartén y cuajar hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar por el otro lado hasta que el queso esté fundido por dentro.","Servir cortada en porciones."}', 'Tortilla jugosa de calabacín con hilos de queso fundido.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_060', 'Frittata de verduras al horno', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 260, 15, 7, 19, 4, true, true, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":8,"unit":"ud"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Espinacas","amount":100,"unit":"g"},{"name":"Queso rallado","amount":80,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Cortar calabacín en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Cortar cebolla en dados pequeños.","Batir huevo con leche en un bol grande hasta obtener una mezcla homogénea.","Calentar aceite de oliva en sartén apta para horno a fuego medio.","Sofreír la cebolla y el pimiento rojo a fuego medio hasta que estén pochados.","Añadir el calabacín y saltear a fuego medio hasta que esté tierno.","Incorporar espinacas y saltear a fuego medio hasta que se reduzcan.","Añadir la mitad de queso rallado a la mezcla de huevo y leche y remover.","Verter la mezcla de huevo sobre las verduras en la sartén de forma uniforme.","Espolvorear el resto del queso rallado por encima.","Hornear en el horno a 180 °C hasta que la frittata esté dorada y firme al tacto.","Reposar la frittata fuera del horno antes de cortar.","Cortar en porciones y servir."}', 'Frittata de verduras horneada, colorida, que se corta en porciones como una tarta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_061', 'Huevos al horno con tomate y queso', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 320, 18, 12, 22, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Queso mozzarella rallado","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir tomate triturado y salpimentar.","Cocer a fuego medio hasta que la salsa espese.","Repartir la salsa de tomate entre 2 cazuelitas aptas para horno.","Cascar huevo sobre el tomate, 2 por cazuelita, sin romper la yema.","Repartir queso mozzarella rallado por encima de los huevos.","Espolvorear orégano sobre el queso.","Hornear hasta que la clara cuaje, la yema quede jugosa y el queso se funda.","Servir de inmediato en las mismas cazuelitas."}', 'Huevos al horno con salsa de tomate y queso fundido, burbujeante con el queso dorado en la superficie.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_062', 'Tortilla de espinacas y piñones', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 400, 19, 9, 32, 2, true, true, '{"huevo","frutos_secos"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo finos.","Lavar espinacas frescas bajo el grifo y escurrir.","Tostar piñones en sartén seca a fuego medio hasta que estén ligeramente dorados.","Retirar los piñones a un plato y reservar.","Calentar la mitad de aceite de oliva en la misma sartén a fuego medio.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","Añadir las espinacas escurridas por tandas y saltear hasta que reduzcan y suelten el agua.","Escurrir las espinacas con cebolla apretando con una cuchara para retirar el exceso de líquido.","Batir huevo en un bol grande hasta que estén homogéneos.","Añadir las espinacas escurridas, la cebolla y los piñones reservados al huevo batido y mezclar.","Calentar el aceite de oliva restante en la sartén a fuego medio-fuerte.","Verter la mezcla de huevo en la sartén y extender para igualar la superficie.","Cuajar a fuego medio hasta que los bordes estén firmes y el centro ligeramente jugoso.","Dar la vuelta a la tortilla con un plato y deslizarla de nuevo a la sartén.","Cuajar por el segundo lado hasta que esté hecha al punto deseado.","Retirar la tortilla de la sartén y dejar reposar antes de cortar.","Servir la tortilla cortada en porciones."}', 'Tortilla jugosa de espinacas salteadas con piñones tostados, verde por dentro y dorada por fuera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_063', 'Huevos con jamón ibérico y trufa', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 450, 26, 27, 26, 2, false, false, '{"huevo","gluten"}', '[{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón ibérico en lonchas","amount":60,"unit":"g"},{"name":"Trufa negra fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Aceite de trufa","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar ajo y reservar.","Laminar finamente trufa negra fresca y reservar.","Cortar pan rústico en rebanadas gruesas.","Tostar las rebanadas de pan en una tostadora o sartén seca a fuego medio hasta que estén crujientes.","Frotar cada rebanada tostada por una cara con el ajo pelado.","Calentar aceite de oliva virgen extra en sartén a fuego medio.","Freír jamón ibérico en lonchas 1 min hasta que esté crujiente.","Retirar el jamón y reservar sobre papel absorbente.","Freír huevo en la misma sartén a fuego medio, 2 min, hasta que la clara esté cuajada y la yema líquida.","Disponer las rebanadas de pan tostado en los platos.","Repartir el jamón crujiente sobre el pan.","Colocar los huevos fritos encima del jamón.","Repartir las láminas de trufa negra fresca sobre los huevos.","Terminar con unas gotas de aceite de trufa y servir enseguida."}', 'Huevos fritos de yema líquida sobre pan tostado con jamón ibérico crujiente y virutas de trufa negra.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_064', 'Shakshuka de huevos poché en salsa de tomate', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 415, 19, 36, 22, 2, true, false, '{"huevo","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Picar cebolla en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento en la sartén hasta que estén blandos, unos 8 min a fuego medio.","Añadir el ajo picado, comino molido y pimentón dulce.","Remover hasta que las especias desprendan aroma, unos 1 min a fuego medio.","Incorporar tomate triturado y salpimentar al gusto.","Cocer la salsa a fuego medio hasta que espese, unos 10 min.","Hacer 4 huecos en la salsa con una cuchara.","Cascar huevo con cuidado y depositar uno en cada hueco de la salsa.","Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida, unos 6 min.","Tostar pan rústico al gusto.","Servir la shakshuka directamente en la sartén acompañada del pan tostado para mojar."}', 'Huevos escalfados hundidos en una salsa de tomate y pimiento especiada, para mojar pan.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_065', 'Huevos rancheros', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 515, 26, 46, 26, 2, false, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tortilla de maíz","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Chile jalapeño","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Judías negras cocidas","amount":100,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cilantro fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Picar chile jalapeño muy fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla, el ajo y el chile jalapeño hasta que la cebolla esté transparente.","Añadir tomate triturado y salpimentar.","Cocer la salsa a fuego medio hasta que espese, removiendo de vez en cuando.","Calentar judías negras cocidas en un cazo a fuego suave, aplastando ligeramente con un tenedor.","Calentar tortilla de maíz en sartén seca a fuego medio, 30 segundos por cada lado.","Picar cilantro fresco fino.","Freír huevo en sartén con el resto del aceite de oliva a fuego medio, hasta que la clara esté cuajada y la yema líquida.","Repartir las tortillas de maíz en los platos y distribuir las judías negras encima.","Verter la salsa ranchera sobre las judías negras.","Colocar 2 huevos fritos sobre cada tortilla y espolvorear queso rallado por encima.","Terminar con el cilantro fresco picado y servir de inmediato."}', 'Huevos fritos sobre tortilla de maíz con salsa ranchera picante, frijoles y queso fundido.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_066', 'Tortilla de patatas con chorizo', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 460, 20, 29, 30, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Cortar chorizo en dados pequeños.","Calentar aceite de oliva en sartén amplia a fuego suave.","Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave hasta que estén tiernas.","Añadir el chorizo en dados y sofreír junto a las patatas hasta que suelte su grasa y aroma.","Escurrir las patatas, la cebolla y el chorizo en un colador. Reservar el aceite sobrante.","Batir huevo en un bol grande hasta que estén bien mezclados.","Incorporar las patatas, la cebolla y el chorizo escurridos al huevo batido. Mezclar bien.","Reposar la mezcla en el bol durante 2 min para que el huevo empape bien.","Calentar un poco del aceite reservado en sartén a fuego medio.","Volcar la mezcla en la sartén y cuajar a fuego medio-suave hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con ayuda de un plato llano.","Cuajar el segundo lado a fuego suave hasta que esté dorado y el centro ligeramente jugoso.","Retirar del fuego y reposar 1 min antes de servir.","Servir la tortilla entera o en porciones, recién hecha."}', 'Tortilla de patatas jugosa con trocitos de chorizo que tiñen el huevo de rojo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_067', 'Huevo frito sobre risotto de setas', 'huevos', 'huevo', 'arroz', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 610, 21, 70, 26, 2, true, false, '{"huevo","lactosa","sulfitos"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de verduras","amount":600,"unit":"ml"},{"name":"Queso parmesano rallado","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Limpiar y cortar setas variadas en trozos medianos.","Calentar caldo de verduras en un cazo a fuego suave hasta que empiece a humear; mantener caliente.","Calentar aceite de oliva en sartén a fuego fuerte.","Saltear las setas cortadas a fuego fuerte durante 5 min hasta que se doren.","Retirar las setas de la sartén y reservar.","Sofreír la cebolla y el ajo picados en la misma sartén a fuego medio hasta que estén tiernos.","Añadir arroz arborio y remover 1 min hasta que los granos estén nacarados.","Añadir vino blanco y remover sin parar hasta que se evapore por completo.","Incorporar un cucharón de caldo caliente y remover hasta que el arroz lo absorba.","Continuar añadiendo caldo cucharón a cucharón, removiendo sin parar, durante 12 min.","Incorporar las setas reservadas al risotto y seguir removiendo 5 min hasta que el arroz esté al dente.","Retirar el risotto del fuego y añadir mantequilla y queso parmesano rallado.","Remover con energía hasta que la mantequilla y el parmesano se integren y el risotto quede cremoso.","Calentar un chorrito de aceite de oliva en otra sartén a fuego fuerte.","Cascar huevo uno a uno y freír a fuego fuerte hasta que el borde esté crujiente y la yema líquida.","Repartir el risotto en 2 platos y colocar un huevo frito encima de cada uno."}', 'Risotto cremoso de setas coronado con un huevo frito de yema líquida.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_068', 'Ensaladilla con huevo y gambas', 'huevos', 'huevo', 'patatas', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 505, 22, 26, 35, 4, true, false, '{"huevo","marisco"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Zanahoria","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Mayonesa","amount":150,"unit":"g"},{"name":"Guisantes cocidos","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en una olla grande a fuego fuerte.","Cocer patata y zanahoria enteras y sin pelar hasta que estén tiernas.","Cocer huevo en otro cazo con agua hirviendo durante 10 min.","Calentar sartén a fuego fuerte con aceitunas de aceite.","Saltear gambas peladas hasta que estén rosadas y reservar en un plato para que enfríen.","Transferir los huevos cocidos a un bol con agua fría hasta que estén templados.","Pelar los huevos fríos y reservar 1 entero para decorar.","Picar 3 huevos pelados en dados pequeños y reservar.","Pelar la patata y la zanahoria templadas en cuanto se puedan manipular.","Cortar la patata pelada en dados pequeños y reservar en un bol grande.","Cortar la zanahoria pelada en dados pequeños e incorporar al bol.","Añadir al bol los huevos picados, guisantes cocidos y la mitad de las gambas peladas.","Incorporar mayonesa y remover con cuidado hasta que todo quede bien ligado.","Refrigerar la ensaladilla tapada hasta que esté bien fría.","Cortar el huevo reservado en cuartos y reservar junto al resto de las gambas y aceitunas.","Decorar la ensaladilla con el resto de las gambas, los cuartos de huevo y las aceitunas."}', 'Ensaladilla clásica de patata y mayonesa con huevo duro y gambas por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_069', 'Huevos rellenos de txangurro', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 510, 37, 15, 33, 2, true, true, '{"huevo","lactosa","gluten","marisco"}', '[{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Carne de txangurro","amount":150,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Tomate frito","amount":50,"unit":"g"},{"name":"Brandy","amount":10,"unit":"ml"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Queso rallado","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua en un cazo e introducir huevo. Cocer 10 min a fuego medio.","Transferir los huevos a un bol con agua fría hasta que estén templados.","Pelar los huevos y cortar cada uno por la mitad a lo largo.","Separar las yemas de las claras con cuidado y reservar ambas por separado.","Picar cebolla en fino.","Calentar aceite de oliva en sartén a fuego medio y sofreír la cebolla picada hasta que esté tierna.","Añadir carne de txangurro y tomate frito. Saltear 3 min removiendo.","Verter brandy y dejar reducir hasta que el alcohol se evapore.","Retirar la sartén del fuego y reservar el relleno de txangurro.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Incorporar leche poco a poco sin dejar de remover hasta que la bechamel espese y esté lisa.","Retirar el cazo del fuego y reservar la bechamel.","Desmenuzar las yemas reservadas sobre el relleno de txangurro.","Mezclar la mitad de la bechamel con el relleno de txangurro y las yemas hasta integrar.","Rellenar cada clara con la mezcla de txangurro y colocarlas en una fuente apta para horno.","Napar los huevos rellenos con el resto de la bechamel.","Espolvorear queso rallado por encima de todos los huevos.","Gratinar en el horno a 220 °C con el grill hasta que la superficie esté dorada.","Retirar la fuente del horno y servir los huevos rellenos templados."}', 'Huevos duros rellenos de txangurro cremoso, gratinados hasta dorarse.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_070', 'Huevos con salsa de queso azul', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 555, 25, 29, 38, 2, false, false, '{"huevo","lactosa","frutos_secos","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Nueces","amount":20,"unit":"g"},{"name":"Pan rústico","amount":100,"unit":"g"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan rústico en rebanadas gruesas.","Tostar las rebanadas en el tostador o en una sartén seca a fuego medio hasta que estén crujientes.","Trocear nueces en trozos gruesos y reservar.","Calentar nata para cocinar en un cazo a fuego suave.","Desmenuzar queso azul dentro del cazo cuando la nata esté caliente.","Remover hasta que el queso se funda y la salsa quede homogénea, sin que llegue a hervir.","Retirar el cazo del fuego y reservar la salsa caliente.","Llevar a ebullición agua en un cazo amplio con vinagre.","Bajar el fuego hasta mantener un hervor suave; remover el agua para crear un remolino.","Cascar huevo uno a uno sobre el remolino y escalfar 3 min cada uno.","Sacar los huevos con una espumadera y escurrir sobre papel absorbente.","Repartir las rebanadas de pan tostado en los platos y colocar 2 huevos escalfados sobre cada una.","Napar con la salsa de queso azul caliente y esparcir las nueces por encima.","Servir inmediatamente."}', 'Huevos escalfados bañados en una salsa cremosa de queso azul y nueces.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_071', 'Tortilla de patatas con pimientos verdes', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 410, 18, 27, 26, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Pimiento verde italiano","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":55,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Cortar pimiento verde italiano en tiras finas.","Calentar aceite de oliva en sartén amplia a fuego medio hasta que esté caliente.","Añadir las patatas laminadas, la cebolla y el pimiento verde a la sartén.","Confitar a fuego suave 20 min, removiendo de vez en cuando, hasta que todo esté tierno.","Escurrir las patatas, la cebolla y el pimiento en un colador, reservando el aceite sobrante.","Batir huevo en un bol grande con sal hasta obtener una mezcla homogénea.","Añadir las patatas, la cebolla y el pimiento escurridos a los huevos batidos y mezclar.","Reposar la mezcla 2 min para que el huevo empape bien las patatas.","Calentar un chorrito del aceite reservado en la sartén limpia a fuego medio hasta que esté caliente.","Volcar la mezcla en la sartén y cuajar 3 min a fuego medio hasta que los bordes estén firmes.","Dar la vuelta a la tortilla con un plato llano y deslizarla de nuevo en la sartén.","Cuajar el segundo lado 2 min a fuego medio hasta que esté cuajado al gusto.","Reposar la tortilla fuera del fuego 1 min antes de servir.","Servir la tortilla entera o cortada en porciones."}', 'Tortilla de patatas con pimientos verdes fritos, trocitos verdes entre el huevo cuajado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_072', 'Huevos poché con crema de guisantes y menta', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 450, 20, 24, 30, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Guisantes","amount":300,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Picar cebolleta muy fina.","Calentar mantequilla y aceite de oliva en un cazo a fuego medio.","Sofreír la cebolleta picada hasta que esté translúcida, unos 4 min.","Añadir guisantes y caldo de verduras. Llevar a ebullición.","Cocer a fuego medio hasta que los guisantes estén tiernos, unos 8 min.","Retirar del fuego. Añadir nata para cocinar y menta fresca.","Triturar el conjunto hasta obtener una crema fina.","Llevar a ebullición abundante agua en un cazo. Añadir vinagre.","Reducir el fuego hasta que el agua apenas se mueva. Remover para crear un remolino suave.","Cascar huevo de uno en uno en un bol pequeño y deslizarlo con cuidado al centro del remolino.","Cocer cada huevo poché 3 min hasta que la clara esté cuajada y la yema líquida.","Retirar cada huevo con una espumadera y escurrir sobre papel absorbente.","Repetir con los huevos restantes de uno en uno.","Repartir la crema de guisantes caliente en los platos.","Colocar 2 huevos poché sobre la crema en cada plato.","Terminar con unas hojas de menta fresca y un hilo de aceite de oliva."}', 'Huevos poché sobre una crema fina de guisantes y menta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_073', 'Huevos con setas y jamón al horno', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 505, 28, 26, 33, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Jamón serrano en taquitos","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Laminar setas variadas.","Picar ajo fino.","Picar perejil fresco fino y reservar.","Calentar aceite de oliva en sartén a fuego fuerte.","Sofreír las setas laminadas y el ajo picado hasta que se doren y suelten el agua.","Añadir jamón serrano en taquitos y saltear 1 min hasta que tome color.","Repartir la mezcla de setas y jamón en 2 cazuelitas individuales aptas para horno.","Verter nata para cocinar a partes iguales sobre cada cazuelita.","Cascar huevo encima de cada cazuelita, 2 huevos por ración.","Hornear 10 min hasta que la clara cuaje y la yema quede semilíquida.","Cortar pan rústico en rebanadas y tostar en el horno los últimos 3 min.","Espolvorear el perejil picado sobre cada cazuelita y servir muy caliente con el pan tostado."}', 'Huevos al horno con setas salteadas y jamón, burbujeantes recién sacados del horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_074', 'Tortilla de patatas con pulpo', 'huevos', 'huevo', 'patatas', ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 475, 26, 28, 27, 2, true, true, '{"huevo","moluscos"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Pulpo cocido","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas finas de unos 2-3 mm.","Cortar cebolla en juliana fina.","Calentar aceite de oliva en sartén grande a fuego suave.","Añadir la patata laminada y la cebolla en juliana hasta que queden confitadas, sin dorarse.","Cortar pulpo cocido en rodajas de 1 cm.","Batir huevo en un bol grande hasta integrar.","Añadir pimentón dulce al huevo batido y mezclar.","Escurrir la patata y la cebolla en un colador, reservando el aceite de oliva sobrante.","Incorporar la patata escurrida, la cebolla escurrida y el pulpo al huevo batido.","Remover bien y dejar reposar la mezcla para que el huevo empape la patata.","Calentar un poco del aceite reservado en la sartén a fuego medio.","Verter la mezcla en la sartén y cuajar hasta que los bordes estén firmes y el centro algo jugoso.","Dar la vuelta con un plato y devolver la tortilla a la sartén por el otro lado.","Cuajar hasta que el segundo lado esté firme, dejando el interior ligeramente meloso.","Retirar la tortilla del fuego y dejar reposar antes de servir.","Servir la tortilla cortada en porciones."}', 'Tortilla de patatas con rodajas de pulpo y un toque de pimentón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_075', 'Huevos a la Florentina con espinacas y bechamel', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'normal', 'all', 525, 28, 23, 36, 2, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar ajo muy fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado 1 min hasta que esté dorado sin quemarse.","Añadir espinacas frescas por tandas y saltear a fuego medio hasta que reduzcan por completo.","Escurrir las espinacas salteadas presionando con una cuchara para eliminar el exceso de agua.","Fundir mantequilla en un cazo a fuego suave.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Verter leche poco a poco sin dejar de remover a fuego suave.","Remover sin parar hasta que la bechamel espese y se despegue de las paredes del cazo.","Sazonar la bechamel con nuez moscada y sal al gusto.","Repartir las espinacas escurridas en 2 cazuelitas individuales aptas para horno.","Cascar huevo de 2 en 2 sobre las espinacas de cada cazuelita, colocando las yemas enteras.","Cubrir cada cazuelita con la bechamel sin tapar del todo las yemas.","Espolvorear queso rallado por encima de la bechamel en cada cazuelita.","Hornear en el horno a 200 °C durante 10 min hasta que la clara cuaje y la superficie esté dorada.","Servir las cazuelitas recién salidas del horno con cuidado de no romper las yemas."}', 'Huevos a la florentina con espinacas y bechamel, gratinados hasta dorarse por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_076', 'Revuelto ajoarriero de bacalao con pimientos', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 410, 34, 6, 28, 2, false, false, '{"huevo","pescado"}', '[{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Bacalao desalado desmigado","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Laminar ajo.","Cortar pimiento rojo en tiras finas.","Picar perejil fresco fino y reservar.","Batir huevo ligeramente en un bol hasta homogeneizar.","Calentar aceite de oliva en sartén a fuego suave.","Sofreír el ajo laminado y guindilla en el aceite caliente hasta que el ajo empiece a dorarse.","Añadir el pimiento rojo en tiras y pochar hasta que esté tierno.","Incorporar bacalao desalado desmigado y remover hasta que esté bien caliente.","Bajar el fuego al mínimo y verter el huevo batido sobre el bacalao y las verduras.","Remover sin parar con una espátula hasta que el huevo esté cuajado pero cremoso.","Retirar la sartén del fuego en cuanto el huevo esté jugoso, antes de que cuaje del todo.","Espolvorear el perejil picado y servir de inmediato."}', 'Revuelto de bacalao desmigado con pimientos y ajo, al estilo ajoarriero.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_077', 'Shakshuka verde con espinacas y feta', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 470, 24, 31, 28, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espinacas frescas","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Queso feta","amount":60,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Picar cebolla en dados finos.","Cortar pimiento verde en dados finos.","Picar ajo fino.","Calentar aceite de oliva en sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento verde en la sartén hasta que estén blandos.","Añadir el ajo picado y comino molido y remover sin parar hasta que el ajo suelte aroma.","Incorporar espinacas frescas por tandas y saltear hasta que reduzcan por completo.","Retirar la mitad de las espinacas a un vaso de batidora y triturar hasta obtener una crema verde.","Incorporar la crema triturada a la sartén y remover hasta mezclar todo de forma uniforme.","Hacer 4 huecos en la mezcla verde con una cuchara.","Cascar huevo uno a uno y depositar cada huevo en un hueco.","Tapar la sartén y cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","Desmenuzar queso feta por encima de la sartén.","Tostar pan rústico y servir junto a la sartén para acompañar."}', 'Shakshuka verde de espinacas con huevos escalfados y queso feta desmenuzado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_078', 'Huevos al horno con burrata y tomate', 'huevos', 'huevo', 'pan', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 610, 28, 30, 42, 2, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Burrata","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan rústico","amount":80,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Picar ajo fino.","Calentar aceite de oliva en una cazuela apta para horno a fuego medio.","Sofreír el ajo picado hasta que empiece a blanquear, sin que llegue a dorarse.","Añadir tomate triturado y salpimentar al gusto.","Cocer a fuego medio hasta que la salsa espese, removiendo de vez en cuando.","Hacer 4 huecos en la salsa con una cuchara.","Cascar huevo de uno en uno y depositar cada uno en un hueco.","Hornear en el horno a 200 °C hasta que la clara empiece a cuajar pero la yema siga líquida.","Repartir trozos de burrata entre los huevos.","Hornear 2 min más hasta que la burrata se funda ligeramente.","Espolvorear con hojas de albahaca fresca recién arrancadas.","Servir la cazuela muy caliente acompañada de pan rústico."}', 'Huevos al horno con tomate y burrata fundiéndose entre las yemas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_079', 'Huevos rotos con jamón, patatas paja y salsa de boletus', 'huevos', 'huevo', 'patatas', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 620, 28, 38, 40, 2, true, false, '{"huevo","lactosa"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano en lonchas","amount":80,"unit":"g"},{"name":"Boletus","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":20,"unit":"ml"},{"name":"Aceite de oliva para freír","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar patata y rallar en juliana muy fina con mandolina o rallador.","Secar la patata rallada con papel absorbente hasta eliminar toda la humedad.","Calentar aceite de oliva para freír en una sartén honda a fuego fuerte hasta que humee.","Freír la patata por tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y reservar.","Picar ajo fino.","Limpiar boletus y cortar en trozos.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse.","Añadir los boletus troceados y saltear a fuego fuerte hasta que estén dorados.","Añadir vino blanco y cocer hasta que se evapore el alcohol.","Añadir nata para cocinar y cocer a fuego suave hasta que la salsa espese ligeramente.","Freír huevo en sartén a fuego medio hasta que la clara cuaje y la yema quede líquida.","Repartir la patata paja en los platos como base.","Colocar jamón serrano en lonchas sobre la patata.","Disponer los huevos fritos encima del jamón y romper las yemas con un tenedor.","Napar con la salsa de boletus caliente y servir de inmediato."}', 'Huevos rotos sobre patatas paja crujiente con jamón y una salsa cremosa de boletus.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('huevos_080', 'Huevos estrellados con jamón y patata paja', 'huevos', 'huevo', 'patatas', ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 26, 33, 36, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano en lonchas","amount":80,"unit":"g"},{"name":"Aceite de oliva para freír","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en juliana muy fina con mandolina o rallador.","Secar la patata con papel absorbente para eliminar el exceso de humedad.","Calentar aceite de oliva para freír en una sartén honda a fuego fuerte hasta que esté muy caliente.","Freír la patata en tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y reservar en lugar cálido.","Calentar aceite de oliva en otra sartén a fuego medio hasta que esté caliente.","Freír huevo de uno en uno hasta que la clara cuaje pero la yema quede líquida.","Repartir la patata caliente en los platos formando una base uniforme.","Colocar jamón serrano en lonchas sobre la patata.","Disponer los huevos fritos encima del jamón.","Romper las yemas con un tenedor justo al servir para que se mezclen con la patata y el jamón."}', 'Huevos estrellados clásicos sobre patata paja crujiente con jamón serrano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_081', 'Quiche de setas y queso de cabra', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 635, 19, 32, 47, 4, true, true, '{"huevo","lactosa","gluten"}', '[{"name":"Masa quebrada","amount":230,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Setas variadas","amount":250,"unit":"g"},{"name":"Queso de cabra","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde de quiche con masa quebrada y pincharla con un tenedor por toda la superficie.","Refrigerar la base en el molde en la nevera durante 10 min.","Picar cebolla en trozos finos.","Laminar setas variadas.","Cubrir la base fría con papel de horno y peso encima (legumbres secas o bolas de cerámica).","Hornear la base en blanco a 180 °C durante 10 min.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté translúcida, unos 6 min.","Añadir las setas laminadas y saltear a fuego fuerte hasta que se doren y suelten el agua, unos 5 min.","Retirar la sartén del fuego y reservar el sofrito.","Batir huevo con nata para cocinar en un bol hasta obtener una mezcla homogénea.","Añadir nuez moscada a la mezcla de huevo y nata y remover.","Retirar el peso y el papel de la base horneada.","Repartir el sofrito de setas y cebolla de manera uniforme sobre la base.","Desmenuzar queso de cabra por encima del sofrito de manera uniforme.","Verter la mezcla de huevo y nata sobre el relleno hasta cubrir.","Hornear a 180 °C durante 30 min hasta que cuaje y la superficie esté dorada.","Dejar templar la quiche fuera del horno durante 5 min antes de cortar.","Cortar la quiche en porciones y servir."}', 'Quiche de setas salteadas y queso de cabra, cremosa por dentro y dorada por fuera.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('huevos_082', 'Soufflé de espinacas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'elaborada', 'all', 325, 19, 13, 23, 4, true, false, '{"huevo","lactosa","gluten"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Huevo","amount":6,"unit":"ud"},{"name":"Leche","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Queso parmesano rallado","amount":50,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C.","Untar cuatro moldes individuales con mantequilla.","Separar huevo: reservar las yemas y las claras en boles distintos.","Picar ajo fino.","Calentar sartén a fuego medio y fundir una pequeña parte de la mantequilla.","Sofreír el ajo picado 1 min hasta que esté ligeramente dorado.","Añadir espinacas frescas y saltear a fuego medio 4 min hasta que reduzcan.","Retirar las espinacas de la sartén y escurrir muy bien el exceso de agua.","Picar las espinacas escurridas fino y reservar.","Fundir el resto de la mantequilla en un cazo a fuego medio.","Añadir harina de golpe y remover sin parar 1 min hasta obtener una pasta homogénea.","Incorporar leche poco a poco, removiendo sin parar a fuego medio hasta que la bechamel espese.","Retirar el cazo del fuego y añadir nuez moscada.","Añadir queso parmesano rallado y las espinacas picadas; mezclar bien.","Dejar templar la bechamel de espinacas hasta que no queme al tacto.","Añadir las yemas reservadas una a una a la bechamel templada, mezclando bien tras cada una.","Montar las claras reservadas a punto de nieve firme en un bol limpio hasta que formen picos duros.","Incorporar un tercio de las claras a la mezcla de espinacas y mezclar para aligerar.","Añadir el resto de las claras con movimientos envolventes suaves hasta que no queden vetas blancas.","Repartir la mezcla en los moldes untados hasta tres cuartas partes de su capacidad.","Alisar la superficie de cada molde con una espátula.","Hornear 22 min sin abrir el horno hasta que los soufflés suban y estén dorados.","Servir los soufflés inmediatamente en los propios moldes."}', 'Soufflé de espinacas, esponjoso y dorado, que sube alto en el horno.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_001', 'Lentejas con verduras', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 348, 18, 46, 7, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Lavar lentejas bajo el grifo en un colador hasta que el agua salga limpia y escurrir bien.","Pelar zanahoria y cortar en rodajas de medio centímetro.","Pelar patata y cortar en dados de unos 2 cm.","Retirar las semillas de pimiento rojo y cortar en dados pequeños.","Pelar cebolla y picar en dados finos.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 3 min.","Añadir el pimiento rojo y la zanahoria a la olla y sofreír a fuego medio hasta que empiecen a ablandarse, unos 3 min.","Añadir tomate triturado y pimentón y remover hasta integrar bien con las verduras.","Incorporar las lentejas escurridas y la patata en dados a la olla y remover para mezclar todo.","Cubrir con agua fría hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Reducir a fuego suave, tapar la olla y cocer hasta que las lentejas estén tiernas y la patata cocida, unos 20 min.","Retirar del fuego y servir las lentejas con las verduras bien repartidas en cada plato."}', 'Lentejas guisadas con zanahoria, patata y pimiento', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite. Añade las lentejas, tomate, pimentón y agua (o caldo), y cocina a 100°C o Varoma, giro inverso y velocidad cuchara durante 35-45 minutos, hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en la olla. Incorpora las lentejas, tomate, pimentón y agua (o caldo). Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula, luego deja despresurizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_002', 'Lentejas con chorizo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'invierno', 432, 22, 44, 18, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picar en trozos pequeños.","Pelar zanahoria y cortar en rodajas de medio centímetro.","Pelar patata y cortar en trozos medianos de unos 3 cm.","Cortar chorizo en rodajas de medio centímetro.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en la olla a fuego medio hasta que esté transparente, unos 5 min.","Añadir la zanahoria y sofreír junto a la cebolla a fuego medio durante 3 min, removiendo con frecuencia.","Añadir el chorizo en rodajas y sofreír 2 min hasta que suelte la grasa.","Añadir pimentón y remover rápidamente durante 20 segundos para que no se queme.","Añadir tomate triturado y sofreír a fuego medio 3 min hasta que reduzca ligeramente.","Incorporar lentejas y la patata troceada; cubrir con agua fría hasta superar 4 cm los ingredientes.","Llevar a ebullición a fuego fuerte y retirar la espuma que suba a la superficie.","Tapar la olla, bajar a fuego suave y cocer hasta que las lentejas estén tiernas, unos 35 min.","Comprobar el punto de sal y servir las lentejas bien calientes en cuenco hondo."}', 'Lentejas tradicionales guisadas con chorizo y patata', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Sofríe la cebolla, zanahoria y chorizo. Añade el tomate, pimentón, lentejas, patata y agua. Programa 30-35 min a 100°C, velocidad cuchara, giro inverso. Quedarán unas lentejas cremosas y con todo el sabor."},{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Prepara un sofrito con cebolla, zanahoria y chorizo en la olla. Incorpora el tomate, pimentón, lentejas, patata y agua. Cierra y cocina a presión durante 20-25 minutos. El resultado son unas lentejas tiernas y sabrosas en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_003', 'Garbanzos con espinacas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 384, 16, 42, 16, 2, true, true, '{"gluten"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Espinacas","amount":200,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar ajo fino.","Cortar pan del día anterior en trozos pequeños.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Freír los trozos de pan del día anterior en el aceite caliente hasta que estén dorados; retirar y reservar.","Freír el ajo picado en el mismo aceite a fuego suave hasta que se dore ligeramente; retirar y reservar junto al pan.","Triturar el pan frito y el ajo frito con pimentón y comino hasta obtener una majada homogénea; reservar.","Sofreír espinacas en la misma sartén a fuego medio hasta que se reduzcan y estén tiernas.","Añadir tomate triturado sobre las espinacas y remover; cocer a fuego medio hasta que el tomate pierda el agua.","Añadir garbanzos cocidos y la majada reservada; remover para integrar bien.","Cocer a fuego suave, removiendo de vez en cuando, hasta que la salsa espese y los sabores se integren.","Servir los garbanzos con espinacas en platos hondos, bien calientes."}', 'Garbanzos con espinacas y majada de pan frito al estilo andaluz', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe el ajo y las espinacas en una sartén. Traslada a una cazuela de horno con los garbanzos, tomate, especias y el pan tostado. Hornea a 180°C durante unos 30-35 minutos para que los sabores se integren bien, cubierto para mantener la humedad."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea el ajo y sofríelo con aceite. Añade el tomate y cocina unos minutos. Incorpora las espinacas, garbanzos, especias y el pan desmenuzado, cocinando a 100°C, velocidad cuchara, giro inverso, durante 15-20 minutos para que los sabores se fundan."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en la olla abierta con aceite. Añade el tomate, las espinacas, los garbanzos, especias y el pan. Cierra la olla y cocina a presión durante 5-7 minutos. Despresuriza y remueve para integrar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_004', 'Cocido madrileño', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 120, 'elaborada', 'invierno', 618, 38, 40, 32, 2, true, true, '{}', '[{"name":"Garbanzos","amount":250,"unit":"g"},{"name":"Morcillo de ternera","amount":150,"unit":"g"},{"name":"Pollo","amount":120,"unit":"g"},{"name":"Tocino","amount":50,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Repollo","amount":150,"unit":"g"}]'::jsonb, '{"Poner garbanzos en un bol grande con agua fría abundante y dejar en remojo un mínimo de 12 horas.","Escurrir los garbanzos remojados y reservar.","Pelar patata y zanahoria.","Cortar la patata en trozos grandes y la zanahoria en rodajas gruesas.","Retirar las hojas exteriores duras de repollo y cortar en cuartos.","Colocar morcillo de ternera, pollo y tocino en una olla grande; cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir los garbanzos escurridos y la zanahoria; bajar el fuego a suave y tapar.","Cocer tapado a fuego suave durante 45 min.","Incorporar la patata y el repollo a la olla.","Añadir chorizo entero; tapar y cocer a fuego suave durante 20 min hasta que la patata esté tierna.","Retirar el morcillo de ternera, el pollo, el tocino y el chorizo de la olla.","Cortar las carnes y el tocino en porciones individuales; reservar en un plato caliente.","Servir primero el caldo en tazón hondo, luego los garbanzos con las verduras y, por último, las carnes."}', 'Cocido tradicional de garbanzos con carnes y verduras en tres vuelcos', '[{"appliance":"horno","time":210,"difficulty":"elaborada","prepSummary":"Cocinar en una olla de hierro fundido o cazuela apta para horno a 150°C durante 3.5 a 4 horas. Este método asegura una cocción lenta y uniforme, logrando carnes y garbanzos extremadamente tiernos y un caldo profundo."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Permite cocer los garbanzos y las carnes en el vaso, y las verduras en el Varoma, optimizando tiempos. Cocinar a 100°C, velocidad cuchara, durante 90-120 minutos, añadiendo los ingredientes en fases para una cocción perfecta y controlada."},{"appliance":"olla_express","time":75,"difficulty":"normal","prepSummary":"Ideal para acortar drásticamente los tiempos de cocción. Cocinar los garbanzos y carnes a presión durante 45-60 minutos, añadiendo las verduras (repollo, patata, zanahoria) al final para que no se deshagan, logrando una ternura excepcional en menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_005', 'Potaje de garbanzos con bacalao', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'normal', 'invierno', 412, 30, 40, 12, 2, true, true, '{"pescado"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Bacalao desalado","amount":150,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños y laminar ajo.","Desmigar bacalao desalado con los dedos en lascas medianas y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse, unos 2 min.","Incorporar pimentón y remover durante 30 segundos para que no se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y pierda el agua, unos 4 min.","Incorporar espinacas y remover hasta que se ablanden y reduzcan su volumen, unos 2 min.","Añadir garbanzos cocidos y mezclar bien con el sofrito.","Cubrir con agua hasta superar ligeramente los garbanzos, llevar a ebullición y tapar la olla.","Cocer a fuego suave durante 15 min hasta que el caldo espese y los sabores se integren.","Incorporar el bacalao desmigado, remover con suavidad y cocer 3 min más hasta que esté hecho.","Servir el potaje bien caliente, repartido en 2 platos hondos."}', 'Potaje de vigilia con garbanzos, bacalao y espinacas', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Comienza el sofrito de cebolla y ajo en una cazuela apta para horno. Incorpora el resto de ingredientes y cocina a 180°C durante 60 minutos, permitiendo que los sabores se integren lentamente."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Pica y sofríe la cebolla y el ajo. Añade el tomate, garbanzos, bacalao y espinacas, y cocina a 100°C, velocidad cuchara, giro inverso durante 45 minutos para una cocción homogénea."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula para un potaje rápido y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_006', 'Fabada asturiana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 150, 'elaborada', 'invierno', 682, 32, 42, 42, 2, true, true, '{}', '[{"name":"Fabes","amount":250,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Morcilla","amount":80,"unit":"g"},{"name":"Panceta","amount":80,"unit":"g"},{"name":"Lacón","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Remojar fabes en agua fría abundante durante un mínimo de 12 horas antes de cocinar.","Escurrir las fabes y colocarlas en una olla grande; cubrir con agua fría hasta 4 cm por encima.","Cortar chorizo, morcilla, panceta y lacón en piezas de unos 4 cm.","Cortar cebolla en 2 mitades sin pelar del todo.","Añadir el chorizo, la morcilla, la panceta, el lacón y la cebolla a la olla con las fabes.","Añadir aceite de oliva y llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una espumadera hasta que el caldo quede limpio.","Reducir el fuego a suave y ''asustar'' la cocción añadiendo un vaso de agua fría; repetir 2 veces más durante la cocción.","Tostar azafrán en seco en una sartén pequeña a fuego suave durante 30 segundos hasta que desprenda aroma.","Disolver el azafrán tostado en un poco del caldo de la olla y verter el líquido de vuelta a la olla.","Cocer a fuego muy suave, con la olla semitapada, hasta que las fabes estén tiernas y el caldo haya espesado ligeramente.","Retirar la cebolla, rectificar de sal si fuera necesario y dejar reposar la fabada tapada fuera del fuego.","Servir en cazuela de barro o plato hondo, repartiendo las fabes y el compango a partes iguales entre las raciones."}', 'Alubias blancas guisadas con chorizo, morcilla, panceta y lacón', '[{"appliance":"horno","time":180,"difficulty":"elaborada","prepSummary":"Tras un remojo previo de las fabes, sofríe la cebolla y los embutidos en una cazuela apta para horno. Añade las fabes, el azafrán y agua, y cocina a fuego lento en el horno a 160°C durante 3 horas, hasta que las fabes estén muy tiernas y los sabores bien integrados."},{"appliance":"thermomix","time":135,"difficulty":"elaborada","prepSummary":"Remoja las fabes la noche anterior. Sofríe la cebolla y los embutidos en el vaso. Incorpora las fabes remojadas, azafrán y agua, y cocina a 100°C, velocidad cuchara, giro inverso, durante 120-150 minutos, ajustando el tiempo hasta que las fabes estén en su punto."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Imprescindible remojar las fabes. Sofríe la cebolla y los embutidos en la olla. Añade las fabes, azafrán y agua, cierra la olla y cocina a presión alta durante 25-35 minutos. Deja despresurizar de forma natural para un resultado óptimo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_007', 'Alubias rojas estofadas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'facil', 'invierno', 366, 19, 48, 9, 2, true, true, '{}', '[{"name":"Alubias rojas","amount":250,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Escurrir alubias rojas del agua de remojo y reservar en un bol.","Pelar zanahoria y cortar en rodajas de 1 cm.","Limpiar puerro, retirar la parte verde oscura y cortar en rodajas de 1 cm.","Limpiar pimiento verde, retirar las semillas y cortar en trozos medianos.","Pelar ajo y picar fino.","Colocar las alubias escurridas en una olla y cubrir con agua fría abundante.","Llevar la olla a ebullición a fuego fuerte.","Añadir la zanahoria, el puerro y el pimiento verde a la olla cuando rompa a hervir.","Bajar a fuego suave, tapar y cocer hasta que las alubias estén tiernas, unos 35 min.","Añadir un chorrito de agua fría 2 veces durante la cocción para ''asustar'' las alubias.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado en la sartén a fuego medio hasta que se dore ligeramente, unos 2 min.","Añadir tomate triturado al sofrito y remover para integrar.","Añadir pimentón al sofrito y remover bien.","Cocer el sofrito a fuego medio, removiendo, hasta que reduzca y pierda el agua, unos 5 min.","Incorporar el sofrito a la olla con las alubias y las verduras; remover con cuidado para integrar.","Cocer el conjunto a fuego suave, destapado, hasta que el caldo ligue y tome cuerpo, unos 10 min.","Servir las alubias estofadas bien calientes, repartidas en 2 platos hondos."}', 'Alubias rojas guisadas con puerro, zanahoria y pimiento', '[{"appliance":"horno","time":80,"difficulty":"facil","prepSummary":"Prepara el sofrito en una olla apta para horno en la encimera. Luego, añade las alubias, tomate, pimentón y agua, cubre y hornea a 160°C durante unos 80 minutos para un guiso tierno y homogéneo."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite. Añade las alubias, tomate, pimentón y agua, y cocina a 100°C, velocidad cuchara, giro inverso, durante 55 minutos hasta que estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla. Incorpora las alubias, tomate, pimentón y agua, cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula para un guiso rápido y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_008', 'Garbanzos con chorizo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 458, 21, 44, 21, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Pimiento rojo","amount":70,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pelar cebolla y ajo, y cortar la cebolla en dados pequeños y picar el ajo fino.","Cortar pimiento rojo en dados pequeños, retirando las semillas y el tallo.","Cortar chorizo en rodajas de unos 5 mm.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada, el ajo picado y el pimiento rojo en dados en la olla hasta que estén tiernos, unos 5 min a fuego medio.","Añadir las rodajas de chorizo y dorar a fuego medio hasta que suelten la grasa y cojan color, unos 3 min.","Añadir pimentón y remover durante 30 segundos a fuego suave para que no se queme.","Añadir tomate triturado, remover bien y dejar sofreír a fuego medio hasta que el tomate pierda el agua y se concentre, unos 4 min.","Incorporar garbanzos cocidos, remover para integrar todos los ingredientes y tapar la olla.","Cocer a fuego suave durante 15 min hasta que los garbanzos absorban los sabores y el guiso espese.","Servir los garbanzos con chorizo bien calientes, repartidos en 2 platos o cazuelas."}', 'Garbanzos guisados con chorizo y pimiento en sofrito de tomate', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sofríe las verduras y el chorizo en una cazuela apta para horno. Añade los garbanzos, tomate y pimentón. Cubre y hornea a 180°C durante 20-25 minutos para que los sabores se integren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con el chorizo y aceite. Incorpora los garbanzos, tomate y pimentón, y cocina a 100°C, velocidad cuchara, giro inverso, durante 15-20 minutos hasta que espese y los sabores se mezclen."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras y el chorizo en la olla. Agrega los garbanzos, tomate y pimentón con un poco de líquido. Cierra y cocina a presión durante 5-7 minutos, permitiendo que despresurice naturalmente para una mejor integración de sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_009', 'Lentejas con arroz', 'legumbres', 'legumbre', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 394, 17, 58, 8, 2, true, true, '{}', '[{"name":"Lentejas","amount":160,"unit":"g"},{"name":"Arroz","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar y picar cebolla en dados finos.","Pelar y cortar zanahoria en rodajas de unos 5 mm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir la zanahoria y sofreír 3 min hasta que empiece a ablandarse.","Añadir tomate triturado y pimentón, remover y rehogar 2 min a fuego medio.","Incorporar lentejas y laurel, cubrir con 600 ml de agua y llevar a ebullición a fuego fuerte.","Reducir el fuego a suave, tapar y cocer 20 min hasta que las lentejas estén casi tiernas.","Añadir arroz, remover y cocer a fuego suave destapado 15 min hasta que el arroz esté en su punto.","Retirar el laurel y servir en boles."}', 'Lentejas guisadas con arroz, plato completo y económico', '[{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Pica las verduras, sofríelas con aceite y pimentón. Añade las lentejas, arroz, tomate y agua, y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 35-40 minutos hasta que estén tiernas."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y zanahoria en la olla. Incorpora el tomate, pimentón, lentejas, arroz y agua. Cierra y cocina a presión durante 12-15 minutos desde que sube la válvula, para unas lentejas perfectas y rápidas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_010', 'Hummus casero', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'batidora', 10, 'facil', 'all', 268, 9, 24, 16, 2, true, true, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Tahini","amount":30,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Pimentón","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos sobre un colador, reservando 3-4 cucharadas del líquido de cocción en un bol pequeño.","Pelar ajo y picarlo fino.","Añadir los garbanzos escurridos, el ajo picado, tahini, zumo de limón y comino al vaso de la batidora.","Triturar a máxima potencia hasta obtener una pasta homogénea.","Añadir aceite de oliva y 2-3 cucharadas del líquido reservado.","Triturar de nuevo a máxima potencia hasta que la textura sea cremosa y lisa.","Probar y ajustar el punto de limón o comino si es necesario; triturar 30 segundos más si procede.","Extender el hummus en un plato hondo formando un surco con el dorso de una cuchara.","Espolvorear pimentón y terminar con un chorrito de aceite de oliva."}', 'Crema de garbanzos con tahini, limón y comino', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en el vaso de la Thermomix y tritura a velocidad progresiva 5-10 durante 2-3 minutos, o hasta obtener una crema homogénea. Para un hummus extra suave, puedes añadir un chorrito de agua fría o hielo durante el triturado si la textura es muy densa."}]'::jsonb, '{"Hummus"}', NULL, true, NULL, '{}', NULL),
  ('legumbres_011', 'Judiones de la Granja', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 524, 28, 44, 26, 2, true, true, '{}', '[{"name":"Judiones","amount":250,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Morcilla","amount":60,"unit":"g"},{"name":"Oreja de cerdo","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Poner judiones en un bol grande con agua fría y dejar en remojo un mínimo de 12 h.","Escurrir los judiones y reservar.","Pelar cebolla y cortar en trozos grandes.","Pelar ajo y dejar los dientes enteros.","Cortar oreja de cerdo en trozos de bocado.","Cortar chorizo en rodajas de 1 cm.","Cortar morcilla en rodajas de 1 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo hasta que estén blandos, unos 5 min.","Añadir pimentón y remover 30 segundos hasta que se integre.","Incorporar los judiones escurridos y la oreja de cerdo; cubrir con agua fría (unos 2 cm por encima).","Llevar a ebullición a fuego fuerte; retirar la espuma que suba a la superficie con una cuchara.","Bajar a fuego suave, tapar la olla y cocer hasta que los judiones estén tiernos, unos 60 min.","Añadir el chorizo y la morcilla y cocer a fuego suave, destapado, 20 min más.","Retirar del fuego y dejar reposar 10 min antes de servir.","Servir los judiones bien calientes en plato hondo, repartiendo los trozos de oreja, chorizo y morcilla."}', 'Judiones blancos grandes guisados con chorizo, morcilla y oreja', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Tras un sofrito inicial en cazuela, incorpora los judiones remojados y las carnes con caldo. Cocina en el horno precalentado a 160°C durante 90-120 minutos, cubierto, para una cocción lenta y uniforme."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Realiza el sofrito de cebolla y ajo, añade las carnes y los judiones remojados con el caldo. Cocina a 95°C, velocidad cuchara inversa, durante 75-90 minutos hasta que los judiones estén tiernos y el guiso ligado."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Prepara un sofrito rápido con cebolla y ajo, añade las carnes y los judiones (previamente remojados) con el caldo. Cierra la olla y cocina a presión durante 25-35 minutos para una cocción rápida y judiones perfectamente tiernos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_012', 'Ensalada de lentejas', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 312, 16, 34, 12, 2, true, true, '{"sulfitos"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Escurrir lentejas cocidas con un colador y aclarar bajo agua fría hasta que estén a temperatura ambiente.","Cortar tomate en dados pequeños de aproximadamente 1 cm.","Cortar cebolla morada en dados pequeños.","Cortar pimiento verde en dados pequeños.","Cortar pepino en dados pequeños.","Mezclar en un bol las lentejas escurridas con el tomate, la cebolla morada, el pimiento verde y el pepino.","Añadir aceite de oliva y vinagre sobre la mezcla y remover hasta que todo quede bien integrado.","Tapar el bol y dejar reposar en la nevera hasta que esté bien fría, mínimo 10 min.","Servir la ensalada fría directamente del bol."}', 'Ensalada fría de lentejas con verduras de temporada', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_013', 'Garbanzos con calabaza', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'invierno', 356, 14, 48, 11, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picar en trozos pequeños. Pelar ajo y picar fino.","Pelar calabaza y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min hasta que empiece a dorarse.","Incorporar los dados de calabaza y saltear a fuego medio durante 5 min hasta que empiecen a ablandarse.","Añadir tomate triturado, comino y pimentón. Remover bien para integrar las especias.","Sofreír el conjunto a fuego medio durante 3 min hasta que el tomate pierda el agua y se concentre.","Añadir garbanzos cocidos y 150 ml de agua. Remover para mezclar todo.","Llevar a ebullición, tapar y cocer a fuego suave durante 15 min hasta que la calabaza esté tierna y el caldo se reduzca.","Retirar del fuego y servir en plato hondo con el caldo de cocción."}', 'Garbanzos guisados con calabaza y comino', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo. Mezcla con el resto de ingredientes en una fuente apta para horno y hornea a 180°C durante 30-35 minutos hasta que la calabaza esté tierna y los sabores se integren."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el ajo. Añade la calabaza, garbanzos, tomate y especias, y cocina a temperatura Varoma/100°C, velocidad cuchara, durante 20-25 minutos hasta que la calabaza esté cocida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Prepara un sofrito con cebolla y ajo en la olla abierta. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_014', 'Judías pintas con arroz', 'legumbres', 'legumbre', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'facil', 'all', 402, 18, 56, 10, 2, true, true, '{}', '[{"name":"Judías pintas","amount":200,"unit":"g"},{"name":"Arroz","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas de 1 cm. Reservar.","Pelar cebolla y picar en trozos pequeños. Reservar.","Limpiar pimiento verde, retirar las semillas y cortar en trozos pequeños. Reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada en el aceite caliente hasta que esté transparente, unos 4 min.","Añadir el pimiento verde y la zanahoria a la olla y sofreír 3 min hasta que empiecen a ablandarse.","Añadir pimentón y remover 30 segundos a fuego suave para que no se queme.","Incorporar judías pintas y laurel a la olla. Cubrir con agua fría hasta unos 4 cm por encima.","Llevar a ebullición a fuego fuerte y luego bajar a fuego suave. Tapar y cocer 35 min hasta que las judías estén tiernas.","Añadir arroz a la olla con las judías y remover para integrar. Cocer a fuego medio 15 min hasta que el arroz esté en su punto.","Retirar el laurel. Tapar la olla y dejar reposar 5 min fuera del fuego.","Servir el guiso bien caliente en cuencos hondos."}', 'Judías pintas guisadas con arroz y verduras', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Sofríe las verduras en una cazuela apta para horno, añade las judías (previamente cocidas), el arroz, el pimentón, laurel y caldo o agua. Cubre y hornea a 180°C durante 45-50 minutos hasta que el arroz esté tierno."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en el vaso con aceite. Incorpora las judías (previamente cocidas), el arroz, pimentón, laurel y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara durante 30-35 minutos."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express. Añade las judías (previamente cocidas), el arroz, pimentón, laurel y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que suba la válvula."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_015', 'Ensalada templada de garbanzos', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 332, 14, 34, 15, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pimiento rojo asado","amount":120,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar tomate en dados pequeños y reservar.","Laminar cebolla morada en tiras finas y reservar.","Cortar pimiento rojo asado en tiras y reservar.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Añadir garbanzos cocidos y comino a la sartén y saltear 3 min hasta que estén ligeramente dorados.","Retirar la sartén del fuego y añadir el tomate en dados, la cebolla morada laminada y el pimiento asado en tiras.","Añadir vinagre de jerez y el aceite de oliva restante, y remover para mezclar bien.","Añadir el perejil picado, remover y servir de inmediato mientras la ensalada está templada."}', 'Ensalada templada de garbanzos con pimiento asado, comino y vinagre de Jerez', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_016', 'Potaje de habichuelas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'facil', 'invierno', 378, 20, 46, 10, 2, true, true, '{}', '[{"name":"Alubias blancas","amount":250,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Escurrir alubias blancas del remojo y reservar.","Pelar patata y cortarla en trozos medianos.","Pelar zanahoria y cortarla en rodajas.","Picar cebolla en dados finos.","Picar ajo fino.","Introducir las alubias escurridas en una olla grande, cubrir con agua fría y añadir laurel y la zanahoria en rodajas.","Llevar a ebullición a fuego fuerte y cocer a fuego medio durante 45 min, hasta que las alubias estén tiernas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén a fuego suave hasta que esté transparente, unos 5 min.","Añadir el ajo picado y sofreír 1 min a fuego suave hasta que desprenda aroma.","Incorporar tomate triturado al sofrito y cocer a fuego medio durante 5 min hasta que reduzca y se concentre.","Añadir la patata en trozos a la olla con las alubias y cocer a fuego medio 15 min hasta que esté tierna.","Incorporar el sofrito a la olla y remover para ligar el caldo durante 5 min a fuego suave.","Retirar la hoja de laurel y servir el potaje bien caliente."}', 'Potaje sencillo de alubias blancas con patata y verduras', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Prepara un sofrito inicial con cebolla, ajo, zanahoria y tomate en una olla apta para horno. Añade las alubias, patata, laurel y caldo/agua. Cocina tapado en el horno a 180°C durante unos 50-60 minutos, o hasta que las alubias estén tiernas, removiendo ocasionalmente y ajustando el líquido si es necesario."},{"appliance":"thermomix","time":65,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso, sofríe con aceite. Añade las alubias (previamente remojadas o cocidas), patata, laurel y caldo/agua. Programa 45-50 minutos, 100°C, giro inverso, velocidad cuchara, hasta que el potaje esté en su punto."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Realiza un sofrito con la cebolla, ajo, zanahoria y tomate en la olla a presión. Incorpora las alubias (remojadas), patata, laurel y suficiente agua/caldo. Cierra la olla y cocina a fuego medio-alto durante 20-25 minutos desde que sube la válvula, dejando despresurizar de forma natural."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_017', 'Lentejas con pollo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'all', 422, 32, 38, 14, 2, true, true, '{}', '[{"name":"Lentejas","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de bocado de tamaño uniforme.","Pelar y picar cebolla en brunoise fina.","Pelar zanahoria y cortar en rodajas de unos 5 mm.","Pelar patata y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar los trozos de contramuslo de pollo en la olla hasta que estén dorados por todos los lados; retirar y reservar.","Sofreír la cebolla picada en la misma olla a fuego medio hasta que esté transparente.","Añadir la zanahoria y sofreír junto a la cebolla durante 2 min, removiendo.","Añadir tomate triturado y pimentón y remover hasta integrar; sofreír 2 min a fuego medio.","Incorporar lentejas, la patata en dados y los trozos de contramuslo de pollo reservados.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar y cocer hasta que las lentejas y la patata estén tiernas.","Comprobar el punto de sal y servir las lentejas con el pollo en platos hondos bien calientes."}', 'Lentejas guisadas con trozos de pollo y verduras', '[{"appliance":"horno","time":65,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras y el pollo en una olla apta para horno. Añade las lentejas, tomate, pimentón y caldo. Hornea tapado a 180°C durante unos 60-70 minutos, removiendo ocasionalmente, hasta que las lentejas estén tiernas."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Incorpora el pollo, lentejas, tomate, pimentón y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 50-55 minutos o hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras y el pollo en la olla. Incorpora las lentejas, tomate, pimentón y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_018', 'Garbanzos con tomate', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 342, 14, 40, 14, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla y ajo en trozos finos.","Cortar pimiento verde en trozos pequeños.","Calentar aceite de oliva en una sartén grande a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde en sartén hasta que estén tiernos y la cebolla esté transparente.","Añadir tomate triturado y comino al sofrito y remover para integrar.","Cocer la salsa a fuego medio hasta que reduzca y se concentre el sabor.","Incorporar garbanzos cocidos a la salsa y remover para que se impregnen bien.","Guisar a fuego suave hasta que los garbanzos absorban la salsa y el conjunto ligue.","Servir los garbanzos con tomate bien calientes directamente de la sartén."}', 'Garbanzos en salsa de tomate casera con comino', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén, luego transfiere todo a una cazuela apta para horno. Hornea a 180°C durante 25 minutos para que los sabores se integren y el guiso espese ligeramente."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite. Añade el tomate, garbanzos y comino, y cocina a 100°C, velocidad cuchara, giro inverso durante 14 minutos para un guiso perfecto."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y pimiento en la olla abierta. Incorpora el tomate, garbanzos y comino, cierra la olla y cocina 5 minutos desde que sube la válvula para potenciar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_019', 'Alubias blancas con almejas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 386, 24, 40, 13, 2, false, true, '{"moluscos","gluten"}', '[{"name":"Alubias blancas cocidas","amount":300,"unit":"g"},{"name":"Almejas","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 20 min para que suelten la arena.","Escurrir y aclarar las almejas bajo agua fría; reservar.","Picar cebolla en trozos muy finos.","Picar ajo en trozos muy finos.","Picar perejil fino; reservar.","Calentar sartén a fuego medio-fuerte; añadir las almejas escurridas y vino blanco; tapar hasta que abran, unos 3 min.","Retirar las almejas abiertas; colar y reservar el caldo de cocción; descartar las que no hayan abierto.","Calentar aceite de oliva en una cazuela a fuego medio; sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min más hasta que empiece a dorarse.","Añadir harina y remover sin parar durante 1 min hasta que se integre con el sofrito.","Incorporar el caldo de almejas reservado y remover hasta que la salsa espese y quede homogénea.","Añadir alubias blancas cocidas y mezclar con suavidad; cocer a fuego suave 5 min hasta que absorban el sabor.","Incorporar las almejas reservadas y el perejil picado; calentar a fuego suave 2 min hasta que todo esté bien caliente.","Servir el guiso en platos hondos con un poco de perejil picado por encima."}', 'Alubias blancas guisadas con almejas en salsa de vino blanco', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade la harina, el vino, las alubias y las almejas. Cocina a temperatura y velocidad suaves (giro inverso) hasta que las almejas se abran y la salsa espese, unos 20-25 minutos."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Incorpora la harina, el vino y las alubias. Añade las almejas, cierra la olla y cocina a presión baja solo 2-3 minutos desde que sube la válvula, para que las almejas se abran sin sobrecocer."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_020', 'Lentejas pardinas en ensalada templada', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 336, 16, 32, 15, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Lentejas pardinas cocidas","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Módena","amount":10,"unit":"ml"},{"name":"Mostaza","amount":5,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y calabacín en dados de 1 cm.","Cortar cebolla morada en juliana fina y reservar en frío.","Mezclar vinagre de módena, mostaza y aceite de oliva en un bol hasta emulsionar.","Calentar sartén a fuego fuerte sin aceite hasta que humee.","Saltear los dados de pimiento rojo y calabacín hasta que estén dorados pero ligeramente crujientes, unos 5 min.","Añadir lentejas pardinas cocidas a la sartén y saltear hasta que estén templadas, unos 2 min.","Retirar la sartén del fuego y volcar las lentejas con las verduras en un bol.","Añadir la vinagreta sobre las lentejas y remover para que se integre bien.","Servir la ensalada templada con la cebolla morada en juliana por encima."}', 'Lentejas pardinas templadas con verduras salteadas y vinagreta', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Corta el pimiento, calabacín y cebolla en trozos. Mézclalos con aceite de oliva, sal y pimienta. Cocínalos en la airfryer a 190°C durante 15-18 minutos, agitando la cesta a mitad del tiempo, hasta que estén tiernos y ligeramente dorados. Mezcla con las lentejas y el aliño."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Trocea el pimiento, calabacín y cebolla, mézclalos con aceite de oliva, sal y pimienta. Extiéndelos en una bandeja y ásalos durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Combina con las lentejas cocidas y el aliño."},{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Trocea la cebolla, pimiento y calabacín. Sofríelos en el vaso de la Thermomix con aceite a 120°C, velocidad cuchara, durante 10-12 minutos hasta que estén tiernos. Prepara el aliño en el vaso y luego mezcla todo con las lentejas cocidas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_021', 'Ensalada de garbanzos de bote con atún y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 460, 29, 33, 23, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Garbanzos cocidos de bote","amount":300,"unit":"g"},{"name":"Atún en aceite de oliva","amount":160,"unit":"g"},{"name":"Pimiento rojo asado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos de bote bajo el grifo hasta que el agua salga limpia.","Escurrir atún en aceite de oliva y reservar el aceite de la lata.","Picar pimiento verde y cebolleta en dados pequeños.","Cortar pimiento rojo asado en tiras finas.","Desmigar el atún con un tenedor.","Añadir en un bol los garbanzos, el atún desmigado, el pimiento verde, la cebolleta y el pimiento rojo.","Añadir aceitunas negras al bol.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover bien para integrar el aliño con todos los ingredientes.","Reposar la ensalada en la nevera hasta que esté fría y los sabores se asienten.","Servir la ensalada fría directamente del bol o en platos individuales."}', 'Ensalada rápida de garbanzos de bote con atún, pimientos y aceitunas, lista en cinco minutos.', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Pica los pimientos, la cebolleta y las aceitunas en el vaso. Añade los garbanzos escurridos, el atún y el aliño. Mezcla suavemente a velocidad baja para integrar todos los ingredientes sin triturarlos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_022', 'Tosta de hummus, pepino y sésamo', 'legumbres', 'legumbre', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 510, 18, 60, 21, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Pan de pueblo","amount":160,"unit":"g"},{"name":"Garbanzos cocidos","amount":240,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Sésamo tostado","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo con un colador.","Pelar ajo y partir en trozos.","Triturar los garbanzos escurridos con tahini, zumo de limón, el ajo, comino molido y sal hasta obtener una crema lisa.","Añadir aceite de oliva y triturar de nuevo hasta integrar. Añadir un chorrito de agua si la crema ha quedado muy espesa.","Laminar pepino en rodajas finas.","Tostar pan de pueblo en una tostadora o bajo el grill hasta que esté dorado y crujiente.","Untar cada tosta generosamente con el hummus.","Repartir las láminas de pepino sobre el hummus.","Terminar con sésamo tostado y un chorrito de aceite de oliva por encima."}', 'Tostas crujientes untadas con hummus casero, pepino fresco y sésamo tostado.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es ideal para preparar el hummus. Tritura los garbanzos cocidos con el resto de ingredientes (tahini, zumo de limón, ajo, comino, aceite, sal) hasta obtener una crema fina y homogénea. El pan se tuesta aparte en tostadora o sartén y se monta la tosta."},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"La airfryer es perfecta para tostar el pan de pueblo, dejándolo crujiente por fuera y tierno por dentro. Precalienta a 180°C y tuesta las rebanadas unos 5-7 minutos, dándoles la vuelta a mitad. El hummus se elabora aparte con una batidora o procesador de alimentos."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"El horno es excelente para tostar varias rebanadas de pan a la vez. Precalienta a 200°C con función grill y tuesta el pan durante 5-8 minutos, vigilando para que no se queme. Prepara el hummus aparte con una batidora o procesador de alimentos."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_023', 'Wrap vegetal de hummus y verduras crudas', 'legumbres', 'legumbre', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 420, 15, 55, 16, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Garbanzos cocidos","amount":200,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo hasta que el agua salga limpia.","Pelar y picar ajo muy fino.","Rallar zanahoria con un rallador fino.","Cortar pepino en tiras finas.","Cortar pimiento rojo en tiras finas.","Cortar lechuga en tiras finas.","Triturar los garbanzos escurridos con tahini, zumo de limón, el ajo picado y comino molido hasta que la mezcla sea homogénea.","Añadir aceite de oliva y sal; triturar de nuevo hasta obtener un hummus cremoso.","Calentar tortilla de trigo en una sartén seca a fuego medio hasta que estén flexibles, 20-30 segundos por cada cara.","Untar cada tortilla con una capa generosa de hummus, dejando 2 cm libres en el borde.","Repartir la zanahoria rallada, el pepino, el pimiento rojo y la lechuga sobre el hummus de cada tortilla.","Enrollar cada tortilla apretando bien y cortar por la mitad en diagonal para servir."}', 'Wrap crujiente y colorido de hummus casero con verduras crudas, listo sin encender el fuego.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el hummus: tritura los garbanzos cocidos con el tahini, zumo de limón, ajo, comino, aceite de oliva y sal durante 2-3 minutos a velocidad progresiva hasta obtener una crema suave. También puedes picar las verduras rápidamente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_024', 'Bowl de falafel congelado con hummus y ensalada', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'all', 530, 19, 48, 29, 2, true, false, '{"gluten","sesamo"}', '[{"name":"Falafel congelado","amount":200,"unit":"g"},{"name":"Garbanzos cocidos","amount":120,"unit":"g"},{"name":"Tahini","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Lechuga variada","amount":80,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Hornear falafel congelado en el horno a 200 °C hasta que estén dorados y crujientes.","Triturar garbanzos cocidos con tahini, zumo de limón, comino molido y la mitad de aceite de oliva hasta obtener un hummus homogéneo.","Cortar tomate cherry por la mitad.","Cortar pepino en rodajas.","Laminar cebolla morada en juliana fina.","Repartir lechuga variada como base en 2 boles.","Añadir el tomate cherry, el pepino y la cebolla morada sobre la lechuga.","Colocar el falafel horneado sobre la ensalada y una cucharada generosa de hummus.","Terminar con el resto del aceite de oliva y sal."}', 'Bowl completo con falafel del congelador, hummus rápido y ensalada fresca, listo en diez minutos.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Cocina los falafel congelados durante 20-25 minutos, dándoles la vuelta a mitad para que doren uniformemente. Mientras, prepara el hummus y la ensalada."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cocina los falafel congelados en la airfryer a 190°C durante 15-18 minutos, agitándolos a mitad de cocción para un acabado crujiente y dorado. Aprovecha para preparar el hummus y la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_025', 'Lentejas guisadas con chorizo y huevo poché', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 520, 27, 42, 26, 2, true, false, '{"huevo"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Pelar y picar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento verde en dados pequeños.","Pelar y cortar zanahoria en dados pequeños.","Cortar chorizo en rodajas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde hasta que ablanden.","Añadir la zanahoria y el chorizo y sofreír hasta que el chorizo suelte su color.","Añadir pimentón dulce y tomate triturado y remover durante 1 min.","Añadir las lentejas pardinas y laurel y cubrir con agua hasta 3 cm por encima.","Llevar a ebullición a fuego fuerte.","Bajar el fuego, tapar y cocer hasta que las lentejas estén tiernas.","Llevar agua a ebullición en un cazo a fuego suave y añadir vinagre.","Remover el agua para crear un remolino y cascar huevo de uno en uno en el centro.","Cocer cada huevo hasta que la clara esté cuajada y la yema aún líquida.","Retirar los huevos con espumadera y reservar.","Servir las lentejas en platos hondos y coronar cada uno con un huevo poché."}', 'Lentejas guisadas con chorizo y coronadas con un huevo poché que rompe su yema sobre el guiso.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Prepara el sofrito con las verduras y el chorizo en una cazuela apta para horno en la encimera. Luego, añade las lentejas, el pimentón, el laurel y el caldo, y cocina a fuego lento en el horno a 160-170°C durante 1.5-2 horas hasta que estén tiernas. Los huevos poché se hacen apar"},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríe en el vaso. Añade las lentejas, chorizo, pimentón, laurel y agua/caldo, programa 35-40 min, Varoma/100°C, giro inverso, velocidad cuchara. Los huevos poché se pueden hacer en el Varoma al mismo tiempo o al final para un resultado óptimo."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe las verduras y el chorizo en la olla. Incorpora las lentejas, pimentón, laurel y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos. Libera la presión y sirve las lentejas con los huevos poché hechos al momento en una cacerola aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_026', 'Hummus de remolacha con piñones tostados', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 470, 15, 41, 27, 2, true, true, '{"sesamo","frutos_secos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Remolacha cocida","amount":150,"unit":"g"},{"name":"Tahini","amount":30,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y enjuagarlos bajo el grifo.","Cortar remolacha cocida en dados.","Pelar ajo.","Tostar piñones en sartén sin aceite a fuego medio hasta que estén dorados, removiendo para que no se quemen.","Retirar los piñones de la sartén y reservar.","Triturar los garbanzos, la remolacha, tahini, zumo de limón, el ajo y comino molido hasta obtener una crema fina.","Añadir aceite de oliva poco a poco sin dejar de triturar hasta ligar la crema.","Añadir sal y triturar un instante más hasta integrar.","Extender el hummus en un plato haciendo un hueco en el centro con el dorso de una cuchara.","Repartir los piñones tostados por encima y servir."}', 'Hummus de un magenta intenso gracias a la remolacha, coronado con piñones tostados.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes (excepto los piñones) en el vaso de la Thermomix y tritura a velocidad progresiva hasta obtener una crema fina y homogénea. Sirve con los piñones tostados, que puedes hacer rápidamente en una sartén o en el mismo vaso de la Thermomix."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_027', 'Hummus de aguacate y lima', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 400, 12, 32, 25, 2, true, false, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Zumo de lima","amount":25,"unit":"ml"},{"name":"Tahini","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Cortar aguacate por la mitad y retirar el hueso.","Sacar la pulpa del aguacate con una cuchara y reservar.","Pelar ajo y reservar.","Triturar los garbanzos con la pulpa de aguacate, zumo de lima, tahini, el ajo y comino molido hasta obtener una crema homogénea.","Añadir aceite de oliva poco a poco mientras se tritura, hasta que la crema quede suave y cremosa.","Añadir sal y triturar unos segundos hasta integrar.","Picar cilantro fresco finamente.","Servir el hummus en un bol, espolvorear el cilantro picado por encima y añadir un chorrito de aceite de oliva."}', 'Hummus cremoso y verde con aguacate y un toque ácido de lima que lo levanta.', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en el vaso de la Thermomix y tritura a velocidad progresiva 5-10 hasta obtener una crema suave y homogénea. Si es necesario, baja los restos de las paredes y vuelve a triturar brevemente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_028', 'Falafel crujiente con salsa de yogur y tahini', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 610, 27, 50, 33, 2, true, false, '{"gluten","lactosa","sesamo"}', '[{"name":"Garbanzos secos crudos (en remojo)","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil fresco","amount":15,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Cilantro molido","amount":3,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Levadura química","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Yogur griego","amount":150,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"}]'::jsonb, '{"Escurrir garbanzos secos crudos (en remojo) y reservar.","Cortar cebolla en trozos y pelar ajo.","Triturar los garbanzos escurridos, la cebolla, el ajo, perejil fresco y cilantro fresco hasta obtener una pasta gruesa.","Añadir comino molido, cilantro molido, harina, levadura química y sal a la pasta.","Mezclar bien hasta integrar todos los ingredientes.","Tapar la masa y dejar reposar en la nevera.","Mezclar yogur griego, tahini, zumo de limón y agua en un bol hasta obtener una crema fluida.","Formar bolitas de unos 3 cm con las manos húmedas usando la masa reposada.","Calentar aceite de girasol en sartén honda a fuego medio-alto hasta que esté bien caliente.","Freír las bolitas en tandas hasta que estén doradas y crujientes por fuera.","Escurrir los falafel fritos sobre papel absorbente.","Servir los falafel calientes junto a la salsa de yogur y tahini para mojar."}', 'Falafel casero con una corteza dorada y crujiente, servido con salsa fresca de yogur y tahini.', '[{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Prepara la mezcla de falafel y forma las bolitas. Rocíalas ligeramente con aceite y cocínalas en la airfryer precalentada a 190-200°C durante 15-20 minutos, dándoles la vuelta a mitad del tiempo para un dorado uniforme y crujiente."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Forma los falafel y colócalos en una bandeja de horno con papel de hornear, rociados con un poco de aceite. Hornea a 180-190°C durante 25-30 minutos, volteándolos a mitad de cocción hasta que estén dorados y firmes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_029', 'Fabes con almejas y azafrán', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'all', 480, 31, 46, 18, 2, false, true, '{"moluscos","sulfitos"}', '[{"name":"Fabes de la granja secas","amount":200,"unit":"g"},{"name":"Almejas","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner fabes de la granja secas en un bol grande cubiertas de agua fría y dejar en remojo.","Pelar cebolla y dejarla entera.","Pelar ajo y dejarlo entero.","Escurrir las fabes y colocarlas en una olla cubiertas de agua fría 3 dedos por encima.","Añadir la cebolla, el ajo, laurel y aceite de oliva a la olla.","Llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una espumadera.","Bajar el fuego al mínimo, tapar y cocer hasta que las fabes estén tiernas, añadiendo agua fría si rompe a hervir fuerte.","Poner almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Calentar vino blanco en un cazo pequeño a fuego suave hasta que esté caliente.","Disolver azafrán en hebras en el vino blanco caliente y reservar.","Escurrir las almejas y reservar.","Retirar la cebolla y el ajo cocidos de la olla y triturarlos con un poco del caldo de cocción.","Devolver el triturado a la olla y remover para ligar el guiso.","Añadir el vino con azafrán a la olla y remover.","Añadir las almejas escurridas, tapar y cocer a fuego medio hasta que todas las almejas se abran.","Picar perejil fresco fino.","Espolvorear el perejil picado sobre el guiso y servir bien caliente."}', 'Fabes tiernas en caldo dorado por el azafrán, con almejas recién abiertas encima.', '[{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla y ajo, añade las fabes previamente remojadas y el resto de ingredientes para cocerlas a temperatura Varoma o 100°C durante 60-90 minutos. Incorpora las almejas al final en el vaso o Varoma hasta que se abran."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla. Añade las fabes remojadas, el vino, el azafrán y el laurel, cubre con agua y cocina a presión durante 20-30 minutos. Despresuriza, añade las almejas y cocina unos minutos más hasta que se abran."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_030', 'Ensalada templada de lentejas, chorizo y manzana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 430, 24, 38, 20, 2, true, true, '{"sulfitos","mostaza"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Manzana","amount":150,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Vinagre de jerez","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Mostaza a la antigua","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo con agua fría hasta que salga clara.","Cocer las lentejas pardinas en una olla con agua fría y laurel a fuego fuerte hasta que rompa a hervir.","Bajar el fuego y cocer las lentejas pardinas a fuego suave hasta que estén tiernas pero enteras.","Cortar chorizo en dados pequeños.","Cortar manzana en dados pequeños, sin pelar.","Picar cebolleta en aros finos.","Mezclar aceite de oliva, vinagre de jerez, mostaza a la antigua y sal en un bol pequeño hasta emulsionar.","Escurrir las lentejas pardinas y dejarlas templar en un bol amplio.","Dorar el chorizo en sartén sin aceite a fuego medio hasta que quede crujiente y suelte su grasa.","Retirar el chorizo sobre papel absorbente.","Añadir la manzana, la cebolleta y el chorizo al bol con las lentejas templadas.","Aliñar con la vinagreta y remover con cuidado hasta integrar. Servir templado."}', 'Lentejas templadas con chorizo dorado y crujiente, manzana fresca y una vinagreta de mostaza.', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Cocina las lentejas en el vaso a 100°C con giro inverso (aprox. 25-30 min). Sofríe el chorizo y la cebolleta en el mismo vaso o en una sartén aparte, y luego mezcla con la manzana y el aliño."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Cuece las lentejas en la olla express (8-12 min desde que sube la válvula) para un cocinado rápido. Mientras, dora el chorizo y la cebolleta en una sartén, y saltea la manzana brevemente. Combina todo y aliña."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_031', 'Garbanzos especiados con espinacas y piñones', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 380, 16, 34, 20, 2, true, true, '{"frutos_secos","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Lavar espinacas frescas con abundante agua fría y escurrir bien.","Laminar ajo.","Calentar sartén a fuego medio sin aceite y tostar piñones hasta que estén dorados.","Retirar los piñones y reservar.","Calentar aceite de oliva en la misma sartén a fuego medio y sofreír el ajo laminado hasta que esté dorado.","Añadir comino molido y pimentón dulce y remover unos segundos hasta que suelten aroma.","Incorporar los garbanzos escurridos y saltear hasta que cojan el sabor de las especias.","Añadir las espinacas escurridas y saltear hasta que se reduzcan.","Rociar con vinagre de jerez y añadir sal y remover para integrar.","Servir los garbanzos con espinacas y repartir los piñones tostados por encima."}', 'Garbanzos salteados con especias, espinacas y piñones tostados, con aroma a comino.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Mezcla los garbanzos con aceite, ajo, comino y pimentón. Cocina en la airfryer a 190°C durante 15 minutos, agitando a mitad. Añade los piñones los últimos 3 minutos y las espinacas al final para que se marchiten con el calor residual."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Extiende los garbanzos con aceite, ajo, comino y pimentón en una bandeja. Hornea a 200°C durante 20 minutos, removiendo a mitad. Incorpora los piñones los últimos 5 minutos y las espinacas al sacar para que se ablanden con el calor."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo con aceite. Añade los garbanzos, especias y piñones, cocina unos minutos a temperatura Varoma, giro inverso, velocidad cuchara. Incorpora las espinacas y cocina 2-3 minutos más hasta que se marchiten."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_032', 'Lentejas rojas al curry con leche de coco', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 410, 17, 44, 19, 2, true, true, '{}', '[{"name":"Lentejas rojas peladas","amount":180,"unit":"g"},{"name":"Leche de coco","amount":200,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Curry en polvo","amount":10,"unit":"g"},{"name":"Cúrcuma","amount":3,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Enjuagar lentejas rojas peladas bajo el grifo hasta que el agua salga clara.","Pelar y picar fino cebolla.","Pelar y picar fino ajo.","Pelar y picar fino jengibre fresco.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el ajo picado y el jengibre picado y sofreír hasta que suelten el aroma.","Añadir curry en polvo y cúrcuma y remover para tostar las especias.","Añadir tomate triturado y cocinar hasta que se integre con las especias.","Añadir las lentejas enjuagadas y leche de coco.","Cubrir con agua hasta superar los ingredientes 2 cm y llevar a ebullición.","Cocer a fuego suave hasta que las lentejas se deshagan y el curry espese, removiendo de vez en cuando.","Picar cilantro fresco fino.","Rectificar con sal.","Servir el curry en cuencos y espolvorear el cilantro picado por encima."}', 'Curry cremoso de lentejas rojas con leche de coco, sin nata y con mucho sabor.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica y sofríe la cebolla, ajo y jengibre con aceite. Incorpora las lentejas, leche de coco, tomate y especias, y cocina a 90-100°C, velocidad cuchara, durante unos 20 minutos hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y jengibre en la olla. Añade las lentejas, leche de coco, tomate y especias, cierra la olla y cocina a presión durante 5-7 minutos. Deja despresurizar antes de abrir y servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
