insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('legumbres_033', 'Hummus de guisantes y menta', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 320, 13, 26, 19, 2, true, true, '{"sesamo"}', '[{"name":"Guisantes congelados","amount":250,"unit":"g"},{"name":"Garbanzos cocidos","amount":100,"unit":"g"},{"name":"Tahini","amount":15,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Cocer guisantes congelados en el agua hirviendo hasta que estén tiernos.","Escurrir los guisantes y refrescar bajo agua fría hasta que estén completamente fríos.","Escurrir y enjuagar garbanzos cocidos bajo agua fría.","Pelar ajo y reservar.","Separar la mitad de menta fresca y reservar para el emplatado.","Triturar los guisantes, los garbanzos, tahini, zumo de limón, el ajo y la mitad de la menta hasta obtener una crema fina.","Añadir aceite de oliva poco a poco mientras se tritura hasta ligar la crema.","Rectificar de sal al gusto y triturar un instante más para integrar.","Picar la menta reservada en fino.","Servir el hummus en un bol y espolvorear la menta picada por encima."}', 'Hummus verde y fresco de guisantes y menta, distinto al hummus clásico.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Cocina los guisantes al vapor en el Varoma (10-12 min). Luego, añade los demás ingredientes al vaso y tritura a velocidad progresiva hasta obtener una crema suave y homogénea."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cuece los guisantes al vapor hasta que estén tiernos (8-10 min). Después, tritura los guisantes cocidos con el resto de ingredientes en una batidora hasta lograr una textura cremosa."},{"appliance":"microondas","time":10,"difficulty":"facil","prepSummary":"Cocina los guisantes en el microondas con un poco de agua en un recipiente tapado (3-5 min). Luego, procesa los guisantes con los demás ingredientes en una batidora hasta conseguir un hummus cremoso."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_034', 'Buñuelos de garbanzo especiados', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 480, 20, 42, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Levadura química","amount":3,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"},{"name":"Yogur natural","amount":100,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Ajo","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y secarlos bien con papel de cocina.","Picar cebolleta muy fina.","Picar perejil fresco fino.","Triturar los garbanzos escurridos con la cebolleta picada, el perejil picado, comino molido y pimentón dulce hasta obtener una pasta gruesa.","Añadir huevo, harina, levadura química y sal a la pasta.","Mezclar todo hasta integrar una masa espesa y homogénea.","Tapar la masa y reposar en la nevera 10 min.","Rallar ajo fino.","Picar menta fresca fina.","Mezclar yogur natural con la menta picada y el ajo rallado hasta integrar. Reservar en frío.","Calentar aceite de girasol en una sartén honda a fuego medio hasta que esté caliente.","Formar los buñuelos con 2 cucharas cogiendo porciones de masa del tamaño de una nuez.","Freír los buñuelos en tandas hasta que estén dorados por todos los lados, unos 3-4 min por tanda.","Escurrir los buñuelos sobre papel absorbente.","Servir los buñuelos calientes acompañados de la salsa de yogur y menta."}', 'Buñuelos de garbanzo dorados y crujientes por fuera, tiernos por dentro, con salsa de yogur.', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Forma los buñuelos y rocíalos ligeramente con aceite. Cocínalos en la airfryer precalentada a 180-190°C durante 15-20 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Prepara la masa y forma los buñuelos. Colócalos en una bandeja de horno con papel de hornear, pincela con un poco de aceite y hornea a 200°C durante 20-25 minutos, hasta que estén dorados."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para picar finamente la cebolleta, el perejil, la menta y el ajo, y para mezclar todos los ingredientes de los buñuelos y la salsa de yogur en pocos minutos. Luego, cocina los buñuelos en sartén, horno o airfryer."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_035', 'Ensalada de garbanzos, chorizo crujiente y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 460, 24, 38, 24, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Chorizo","amount":90,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de jerez","amount":12,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y enjuagarlos bajo el grifo.","Cortar chorizo en dados pequeños.","Calentar sartén a fuego medio sin aceite y dorar el chorizo hasta que esté crujiente.","Retirar el chorizo sobre papel absorbente y reservar la grasa de la sartén.","Cortar pimiento rojo en dados pequeños.","Cortar pimiento verde en dados pequeños.","Picar cebolla morada en juliana fina.","Picar perejil fresco fino.","Mezclar en un bol los garbanzos escurridos, el pimiento rojo, el pimiento verde, la cebolla morada y el perejil picado.","Añadir el chorizo crujiente y la grasa reservada por encima de la mezcla.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover bien y servir de inmediato."}', 'Ensalada contundente de garbanzos con chorizo crujiente y pimientos de colores.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta el chorizo en rodajas y los pimientos en tiras. Cocina en la airfryer a 190°C durante 12-15 minutos, agitando a mitad, hasta que el chorizo esté crujiente y los pimientos tiernos. Luego, mezcla con los garbanzos y el resto de ingredientes."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Dispón el chorizo en rodajas y los pimientos en tiras en una bandeja de horno y ásalos durante 15-20 minutos, hasta que el chorizo esté crujiente y los pimientos asados. Luego, mezcla con los garbanzos y el resto de ingredientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_036', 'Judiones con almejas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'normal', 'all', 470, 30, 46, 18, 2, false, true, '{"moluscos","sulfitos"}', '[{"name":"Judiones secos","amount":250,"unit":"g"},{"name":"Almejas","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Perejil fresco","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Poner judiones secos en un bol cubiertos de agua fría y dejar en remojo toda la noche.","Escurrir los judiones y trasladarlos a una olla grande.","Pelar cebolla y añadirla entera a la olla junto con laurel y aceite de oliva.","Cubrir con agua fría y llevar a ebullición a fuego fuerte.","Retirar la espuma con una espumadera hasta que el caldo quede limpio.","Bajar el fuego al mínimo, tapar y cocer hasta que los judiones estén cremosos por fuera y enteros por dentro.","Cubrir almejas con agua fría y sal y dejar reposar 30 min para que suelten la arena.","Picar ajo muy fino.","Picar perejil fresco fino y reservar.","Escurrir las almejas y reservar.","Sacar la cebolla cocida de la olla y triturarla con un cucharón de caldo hasta obtener una crema lisa.","Devolver la crema de cebolla a la olla y remover para ligar el caldo con los judiones.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo picado a fuego suave hasta que empiece a dorarse sin quemarse.","Añadir pimentón dulce a la sartén, remover y retirar del fuego en 10 segundos para que no se queme.","Añadir vino blanco a la sartén y dejar reducir a fuego medio hasta que el alcohol se evapore.","Volcar el sofrito de ajo, pimentón y vino sobre la olla de judiones y remover para integrar.","Añadir las almejas escurridas a la olla, tapar y cocer a fuego medio hasta que todas las almejas se abran.","Retirar las almejas que no se hayan abierto y desechar.","Espolvorear el perejil picado sobre el guiso y servir bien caliente en plato hondo."}', 'Judiones enormes y cremosos en caldo dorado, con almejas recién abiertas.', '[{"appliance":"thermomix","time":90,"difficulty":"normal","prepSummary":"Prepara el sofrito en el vaso (10 min, 120°C, vel 1). Añade los judiones remojados y agua, cocinando 60-90 min (100°C, giro inverso, vel cuchara). Incorpora las almejas en los últimos 5-7 min, cocinando hasta que se abran."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla (10 min). Añade los judiones remojados, pimentón, laurel y agua, cociendo a presión durante 20-30 min. Despresuriza, incorpora las almejas y cocina sin tapa 5 min más hasta que se abran."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_037', 'Lentejas con boletus y tomillo', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'invierno', 380, 19, 42, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Boletus","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomillo fresco","amount":5,"unit":"g"},{"name":"Vino oloroso","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Limpiar boletus con un paño húmedo y laminar en láminas gruesas.","Pelar cebolla y picar en dados pequeños.","Pelar ajo y picar fino.","Pelar zanahoria y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria a fuego medio hasta que ablanden.","Añadir el ajo picado y sofreír hasta que empiece a dorarse.","Incorporar los boletus laminados y saltear a fuego fuerte hasta que se doren.","Añadir vino oloroso y remover hasta que se evapore el alcohol.","Incorporar las lentejas escurridas, laurel y tomillo fresco.","Cubrir con agua fría hasta superar 3 cm por encima y llevar a ebullición a fuego fuerte.","Bajar el fuego suave, tapar y cocer hasta que las lentejas estén tiernas.","Añadir sal y remover para integrar.","Servir en cuencos bien caliente con un chorrito de aceite de oliva."}', 'Guiso reconfortante de lentejas con boletus salteados y aroma a tomillo fresco.', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Sofríe los aromáticos en una olla apta para horno. Añade las lentejas, boletus, vino, caldo o agua y especias. Cocina tapado en el horno precalentado a 160°C durante 75 minutos, removiendo ocasionalmente, para una cocción lenta y uniforme."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Sofríe la cebolla, ajo y zanahoria en el vaso. Incorpora las lentejas, boletus, vino, agua/caldo y especias, y cocina a 100°C, giro inverso, velocidad cuchara durante 45 minutos, hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe los vegetales en la olla express. Añade las lentejas, boletus, vino y caldo, cierra la olla y cocina a presión durante 12-15 minutos. Deja despresurizar naturalmente para un resultado tierno y sabroso en menos tiempo."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('legumbres_038', 'Garbanzos con espinacas y huevo escalfado', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 400, 20, 34, 20, 2, true, false, '{"huevo","gluten"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Pan del día anterior","amount":40,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Comino molido","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo agua fría y reservar.","Lavar espinacas frescas con abundante agua fría y escurrir bien.","Cortar pan del día anterior en dados pequeños.","Pelar y laminar ajo.","Calentar aceite de oliva en sartén a fuego medio.","Freír el pan en dados hasta que esté dorado. Retirar y reservar en un mortero o vaso triturador.","Freír el ajo laminado en la misma sartén hasta que se dore. Retirar y añadir al pan.","Añadir comino molido y un chorrito de agua al mortero y triturar hasta obtener un majado homogéneo.","Calentar el resto del aceite en una cazuela a fuego suave.","Añadir pimentón dulce y remover durante 10 segundos hasta que empiece a soltar aroma, sin dejar que se queme.","Incorporar los garbanzos escurridos y las espinacas. Saltear a fuego medio hasta que las espinacas se reduzcan.","Añadir el majado y un chorrito de agua. Remover y cocer a fuego suave hasta que la mezcla ligue.","Llevar a ebullición agua en un cazo. Añadir vinagre y reducir a fuego suave.","Cascar huevo uno a uno en un cuenco y deslizar cada uno con cuidado en el agua con vinagre.","Cocer los huevos 3 min hasta que la clara esté cuajada y la yema aún líquida. Retirar con espumadera.","Salpimentar los garbanzos con sal y remover.","Servir los garbanzos en platos hondos y coronar cada uno con un huevo escalfado."}', 'Garbanzos con espinacas al estilo andaluz, con la yema del huevo escalfado rota por encima.', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo en el vaso con aceite. Incorpora los garbanzos, espinacas y especias, cocinando a temperatura Varoma. Escalfa los huevos en el recipiente Varoma al mismo tiempo para optimizar el tiempo."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en la olla abierta. Añade los garbanzos, espinacas y especias con un poco de agua y cocina a presión 3-5 minutos. Escalfa los huevos por separado en un cazo con agua y vinagre."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_039', 'Potaje de garbanzos con langostinos', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 428, 30, 36, 18, 2, true, true, '{"marisco","pescado"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Langostinos","amount":250,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":300,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo agua fría y reservar.","Pelar langostinos, reservando las cabezas y cáscaras aparte.","Picar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír las cabezas y cáscaras de langostino hasta que estén doradas y suelten su jugo.","Retirar las cabezas y cáscaras de la cazuela y desechar.","Sofreír la cebolla picada, el ajo picado y el pimiento rojo a fuego medio hasta que ablanden.","Añadir pimentón dulce y remover para que no se queme.","Añadir tomate triturado y cocinar hasta que pierda el agua y la mezcla espese.","Incorporar los garbanzos escurridos, azafrán en hebras y caldo de pescado.","Cocer a fuego medio hasta que los sabores se integren y el caldo reduzca ligeramente.","Añadir los langostinos pelados y cocer hasta que cambien de color y estén hechos.","Salpimentar con sal y remover para integrar.","Servir el potaje bien caliente en cuencos hondos."}', 'Potaje de garbanzos dorado con langostinos, un guiso contundente y marinero.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Se puede preparar en una cazuela apta para horno. Primero, hacer el sofrito en la misma cazuela sobre la encimera, luego añadir el resto de ingredientes (excepto langostinos), cubrir y hornear a 180°C durante 40-50 minutos. Incorporar los langostinos los últimos 10 minutos."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Ideal para este potaje, ya que pica las verduras, sofríe y cocina en el mismo vaso. Sofreír cebolla, ajo y pimiento, añadir el resto de ingredientes (excepto langostinos) y programar 25-30 minutos a 100°C, velocidad cuchara. Incorporar los langostinos los últimos 5 minutos."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Perfecta para acelerar el proceso. Sofríe las verduras en la olla, añade los garbanzos, tomate, caldo y especias. Cierra la olla y cocina a presión durante 10-12 minutos. Libera la presión, añade los langostinos y cocina unos minutos más hasta que estén hechos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_040', 'Fabada asturiana ligera con compango crujiente', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 130, 'elaborada', 'invierno', 610, 34, 42, 34, 4, true, true, '{}', '[{"name":"Fabes de la granja secas","amount":400,"unit":"g"},{"name":"Chorizo asturiano","amount":150,"unit":"g"},{"name":"Morcilla asturiana","amount":150,"unit":"g"},{"name":"Panceta","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Laurel","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cubrir fabes de la granja secas con agua fría abundante y dejar en remojo 12 h.","Pelar cebolla y dejarla entera. Pelar ajo y dejar los dientes enteros.","Escurrir las fabes y colocarlas en una olla grande. Cubrir con agua fría.","Añadir la cebolla entera, el ajo, laurel, chorizo asturiano y panceta a la olla.","Llevar a ebullición a fuego fuerte. Retirar la espuma que suba a la superficie con una espumadera.","Bajar el fuego al mínimo y tapar la olla. Cocer 75 min, añadiendo un chorro de agua fría cada vez que rompa a hervir fuerte.","Calentar un poco de caldo de cocción en un cazo pequeño a fuego suave.","Disolver azafrán en hebras y pimentón dulce en el caldo caliente del cazo. Remover hasta integrar.","Verter el caldo con el azafrán y el pimentón en la olla. Remover con suavidad.","Añadir morcilla asturiana entera a la olla. Cocer a fuego mínimo tapado 20 min.","Cortar el chorizo asturiano en rodajas de 1 cm de grosor.","Calentar aceite de oliva en sartén a fuego fuerte.","Dorar las rodajas de chorizo en la sartén a fuego fuerte hasta que estén crujientes. Reservar.","Retirar la cebolla, el ajo y el laurel de la olla.","Sacar el chorizo, la morcilla y la panceta de la olla. Cortar en trozos.","Añadir sal a las fabes y remover con suavidad.","Servir las fabes con el compango troceado encima y las rodajas de chorizo crujiente por encima."}', 'Fabada asturiana clásica aligerada, con el compango extra dorado y crujiente por encima.', '[{"appliance":"horno","time":200,"difficulty":"elaborada","prepSummary":"Las fabes, previamente remojadas, se cocinan lentamente en una cazuela de hierro fundido tapada a 160°C durante unas 3 horas. El compango se asa en una bandeja aparte a 200°C los últimos 20 minutos para que quede crujiente y se incorpora al guiso."},{"appliance":"olla_express","time":80,"difficulty":"normal","prepSummary":"Las fabes, tras un remojo de 12 horas, se cocinan con los aromáticos y el compango en la olla express a presión durante 35-40 minutos. Para el toque crujiente, el compango se puede dorar en una sartén o airfryer antes de añadirlo al final."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_041', 'Alubias blancas estofadas con costilla', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 95, 'normal', 'all', 560, 34, 38, 30, 2, true, true, '{}', '[{"name":"Alubias blancas secas","amount":200,"unit":"g"},{"name":"Costilla de cerdo","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Poner alubias blancas secas en un bol grande cubierto con agua fría abundante y dejar en remojo toda la noche.","Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Pelar y cortar zanahoria en rodajas finas.","Cortar pimiento verde en trozos pequeños.","Escurrir las alubias del agua de remojo y reservar.","Salpimentar costilla de cerdo por todos los lados con sal.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar la costilla de cerdo por todos los lados hasta que esté dorada.","Retirar la costilla de cerdo dorada y reservar en un plato.","Bajar el fuego a medio y sofreír la cebolla, el ajo, la zanahoria y el pimiento verde en la misma olla.","Añadir pimentón dulce y remover hasta que el sofrito huela a especias tostadas.","Añadir tomate triturado y cocinar hasta que pierda el exceso de agua y se integre con el sofrito.","Incorporar las alubias escurridas, la costilla de cerdo dorada y laurel.","Cubrir con agua fría hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Retirar la espuma que suba a la superficie con una cuchara.","Bajar el fuego al mínimo, tapar y cocer hasta que las alubias estén tiernas y la carne se separe del hueso.","Rectificar de sal al gusto y retirar el laurel.","Tapar y reposar fuera del fuego antes de servir.","Servir las alubias blancas estofadas bien calientes con la costilla de cerdo."}', 'Alubias blancas estofadas con costilla de cerdo, caldo espeso y carne que se deshace.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora las costillas en una olla apta para horno. Añade las alubias remojadas, tomate, pimentón, laurel y agua. Hornea a 160°C durante 120 minutos hasta que las alubias y la costilla estén tiernas, removiendo ocasionalmente."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Prepara el sofrito en el vaso. Incorpora las costillas troceadas y sofríe. Añade las alubias remojadas, tomate, pimentón, laurel y caldo. Cocina a 100°C, giro inverso, velocidad cuchara durante 90-100 minutos, ajustando el tiempo hasta que las alubias y la costilla estén tiernas."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora las costillas en la olla. Añade las alubias remojadas, tomate, pimentón, laurel y agua. Cierra la olla y cocina a presión durante 35-40 minutos. Deja despresurizar naturalmente para una costilla y alubias muy tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_042', 'Lentejas con verduras de otoño y castañas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'invierno', 400, 18, 55, 12, 2, true, true, '{}', '[{"name":"Lentejas pardinas","amount":200,"unit":"g"},{"name":"Castañas cocidas","amount":150,"unit":"g"},{"name":"Calabaza","amount":150,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar lentejas pardinas bajo el grifo y escurrir.","Laminar ajo.","Cortar puerro en rodajas finas.","Pelar zanahoria y cortarla en dados pequeños.","Pelar calabaza y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y el ajo hasta que ablanden.","Añadir la zanahoria y la calabaza y sofreír a fuego medio.","Incorporar las lentejas escurridas y tomillo fresco y remover.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Bajar el fuego, tapar y cocer hasta que las lentejas empiecen a estar tiernas.","Añadir castañas cocidas y cocer tapado hasta que las lentejas estén completamente tiernas.","Salpimentar con sal y remover.","Servir las lentejas bien calientes."}', 'Lentejas con verduras de otoño y castañas dulces, un guiso de colores cálidos.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno con el aceite, añade las lentejas, el caldo, las castañas y el tomillo. Tapa y cocina en el horno precalentado a 170°C durante 50-60 minutos hasta que las lentejas estén tiernas y los sabores bien integrados."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade las lentejas, el caldo, las castañas y el tomillo, y programa 40-45 minutos, 100°C, velocidad cuchara, giro inverso, hasta obtener unas lentejas cremosas y en su punto."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en la olla, incorpora las lentejas, el caldo, las castañas y el tomillo. Cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula, dejando despresurizar de forma natural para un resultado óptimo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_043', 'Ensalada de alubias, atún y pimientos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 420, 28, 32, 20, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Alubias blancas cocidas de bote","amount":350,"unit":"g"},{"name":"Atún en aceite de oliva","amount":160,"unit":"g"},{"name":"Pimiento rojo asado","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir alubias blancas cocidas de bote con un colador y enjuagar bajo el grifo hasta que el agua salga limpia.","Escurrir atún en aceite de oliva y desmigar con un tenedor en trozos medianos.","Cortar pimiento rojo asado en tiras finas.","Cortar cebolleta en aros finos.","Picar perejil fresco fino.","Mezclar en un bol las alubias escurridas, el atún desmigado, las tiras de pimiento rojo asado y los aros de cebolleta.","Añadir aceitunas negras y el perejil picado al bol.","Aliñar con aceite de oliva, vinagre de jerez y sal.","Remover con cuidado hasta que el aliño cubra todos los ingredientes sin romper las alubias."}', 'Ensalada fresca de alubias con atún y pimientos, perfecta para tupper o para plato.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Pica la cebolleta y el perejil en el vaso durante unos segundos. Luego añade las alubias escurridas, el atún, el pimiento asado, las aceitunas, el aceite, el vinagre y la sal, y mezcla a velocidad cuchara o giro inverso para integrar suavemente sin triturar."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_044', 'Garbanzos con calamares', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 418, 32, 36, 16, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Calamar limpio","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos bajo el grifo y reservar.","Cortar calamar limpio en anillas de unos 2 cm.","Picar cebolla y pimiento verde en trozos pequeños.","Picar ajo fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde hasta que estén blandos.","Añadir pimentón dulce y remover 30 segundos para que no se queme.","Añadir tomate triturado y sofreír hasta que pierda el agua, removiendo.","Verter vino blanco y dejar reducir hasta que se evapore el alcohol.","Incorporar las anillas de calamar y saltear a fuego fuerte hasta que estén opacas.","Añadir los garbanzos escurridos y cubrir justo con agua hasta nivelar.","Cocer a fuego medio, tapado, hasta que los sabores se integren y el calamar esté tierno.","Picar perejil fresco fino.","Salpimentar con sal, espolvorear el perejil picado y servir en plato hondo."}', 'Garbanzos guisados con anillas tiernas de calamar en un sofrito oscuro y sabroso.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Sofríe las verduras y el calamar en una cazuela apta para horno. Añade el resto de ingredientes, cubre y hornea a 180°C durante unos 35-40 minutos, permitiendo que los sabores se integren lentamente."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con el aceite. Incorpora el calamar, el vino y el resto de ingredientes, y cocina a 100°C, giro inverso, velocidad cuchara, durante 25-30 minutos hasta que el calamar esté tierno."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras y el calamar en la olla. Añade los garbanzos, tomate, pimentón y vino. Cierra la olla y cocina a presión durante 10-12 minutos, logrando una textura tierna y sabores concentrados en menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_045', 'Hummus de remolacha y comino', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'all', 300, 10, 28, 17, 2, true, true, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Remolacha cocida","amount":150,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos y reservar.","Cortar remolacha cocida en dados.","Pelar ajo y retirar el germen central para que no amargue.","Añadir los garbanzos escurridos, la remolacha, el ajo, tahini, zumo de limón y comino molido al vaso de la batidora.","Triturar a máxima potencia hasta obtener una pasta homogénea, parando para bajar los restos de las paredes si hace falta.","Añadir aceite de oliva en hilo mientras se tritura de nuevo hasta que el hummus quede cremoso y de un magenta uniforme.","Triturar 20 segundos más si la textura sigue densa.","Extender el hummus en un plato hondo formando un surco con el dorso de una cuchara.","Terminar con un chorrito de aceite de oliva y una pizca de comino molido por encima antes de servir."}', 'Crema de garbanzos y remolacha de color magenta intenso, con el aroma cálido del comino.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en el vaso de la Thermomix y tritura a velocidad progresiva hasta obtener una crema suave y homogénea. Raspa las paredes si es necesario para asegurar una textura perfecta."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('legumbres_046', 'Potaje de vigilia con bacalao y espinacas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'invierno', 390, 29, 34, 12, 2, true, true, '{"pescado"}', '[{"name":"Alubias blancas cocidas","amount":350,"unit":"g"},{"name":"Bacalao desalado","amount":150,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado con los dedos en lascas medianas y reservar.","Picar cebolla en dados finos.","Laminar ajo.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir el ajo laminado y sofreír hasta que empiece a dorarse, sin que se queme.","Retirar la olla del fuego e incorporar pimentón dulce; remover rápidamente.","Añadir tomate triturado y volver a fuego medio.","Sofreír el tomate hasta que reduzca y espese.","Incorporar alubias blancas cocidas y cubrir con agua hasta superarlas ligeramente.","Llevar a ebullición a fuego fuerte.","Añadir espinacas, tapar y cocer a fuego suave hasta que el caldo espese ligeramente.","Incorporar el bacalao desmigado y remover con suavidad.","Cocer a fuego suave hasta que el bacalao esté hecho.","Servir en platos hondos, repartiendo las lascas de bacalao por encima."}', 'Potaje de vigilia con alubias blancas, bacalao desmigado y espinacas.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Comienza haciendo el sofrito de cebolla, ajo, tomate y pimentón en una cazuela apta para horno sobre la encimera. Luego, incorpora las alubias, el bacalao y las espinacas, añade un poco de agua si es necesario, cubre y hornea a 180°C durante 45-50 minutos para una cocción lenta y"},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con el aceite. Añade el tomate y el pimentón, cocinando unos minutos más. Incorpora el bacalao en trozos, las alubias y las espinacas, y programa 30-35 minutos a 95°C, giro inverso, velocidad cuchara, para un potaje perfectamente cocinado y emu"},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Realiza el sofrito de cebolla, ajo, tomate y pimentón en la olla abierta. Agrega las alubias, el bacalao y las espinacas con un chorrito de agua o caldo. Cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula, logrando un potaje con sabores concentrados e"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_047', 'Lentejas estofadas con calabaza', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 365, 17, 55, 8, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Calabaza","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir lentejas en un colador y lavar bajo el grifo hasta que el agua salga limpia.","Pelar calabaza y cortar en dados de unos 2 cm.","Pelar y picar cebolla y ajo fino.","Pelar zanahoria y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo a fuego medio hasta que estén transparentes.","Añadir la zanahoria y sofreír a fuego medio hasta que empiece a ablandarse.","Añadir tomate triturado y comino molido y sofreír hasta que el tomate pierda el agua.","Añadir las lentejas escurridas y los dados de calabaza y remover para que se impregnen del sofrito.","Cubrir con agua hasta superar los ingredientes unos 3 cm y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar y cocer hasta que las lentejas y la calabaza estén tiernas.","Servir bien caliente, con la calabaza ligeramente deshecha en el caldo."}', 'Lentejas guisadas con calabaza que se deshace en el caldo, dulces y reconfortantes.', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Prepara un sofrito en una cazuela apta para horno. Añade las lentejas, calabaza, tomate triturado, comino y suficiente agua o caldo. Tapa y hornea a 160°C durante 90-100 minutos, o hasta que las lentejas estén tiernas y el guiso haya espesado."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Incorpora las lentejas, calabaza, tomate, comino y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara, durante 45-50 minutos, o hasta que las lentejas estén en su punto."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Realiza el sofrito de cebolla, zanahoria y ajo en la olla. Agrega las lentejas, calabaza, tomate, comino y agua/caldo. Cierra la olla y cocina a presión durante 10-15 minutos desde que sube la válvula. Deja despresurizar antes de servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_048', 'Alubias pintas con costillas de cerdo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 640, 34, 45, 32, 2, true, true, '{}', '[{"name":"Alubias pintas","amount":200,"unit":"g"},{"name":"Costillas de cerdo","amount":300,"unit":"g"},{"name":"Cebolla","amount":90,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Poner alubias pintas en un bol grande con agua fría abundante y dejar en remojo un mínimo de 8 horas.","Escurrir las alubias pintas y reservar.","Cortar costillas de cerdo en piezas de unos 4 cm si no vienen ya troceadas.","Picar cebolla y pimiento verde en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar las costillas de cerdo por todos los lados hasta que estén bien selladas, unos 6 min.","Retirar las costillas doradas de la olla y reservar.","Sofreír la cebolla picada, el pimiento verde picado y el ajo picado en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego y añadir pimentón dulce; remover para que no se queme.","Volver la olla al fuego y añadir tomate triturado; sofreír a fuego medio hasta que reduzca ligeramente.","Incorporar las alubias pintas escurridas, las costillas reservadas y hoja de laurel; remover para integrar.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar el fuego al mínimo y cocer hasta que las alubias y las costillas estén tiernas, unos 65 min.","Añadir agua caliente si el caldo reduce demasiado durante la cocción para que los ingredientes queden cubiertos.","Retirar la hoja de laurel del guiso.","Servir el guiso bien caliente y espeso en platos hondos."}', 'Guiso espeso de alubias pintas y costilla de cerdo, con la carne deshaciéndose de tierna.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Prepara un sofrito con las verduras y dora las costillas en una cazuela apta para horno. Añade las alubias (previamente remojadas) y el caldo, y cocina a 160°C durante 2 horas, removiendo ocasionalmente, hasta que las alubias estén tiernas y el guiso ligado."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Realiza el sofrito en el vaso, luego incorpora las costillas y rehoga. Añade las alubias (remojadas) y el caldo, y cocina a 100°C, giro inverso, velocidad cuchara, durante 90-100 minutos, hasta que las alubias estén en su punto."},{"appliance":"olla_express","time":50,"difficulty":"facil","prepSummary":"Sofríe las verduras y dora las costillas en la olla. Incorpora las alubias (remojadas) y el caldo. Cierra la olla y cocina a presión durante 25-30 minutos desde que sube la válvula, logrando un guiso tierno y rápido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_049', 'Ensalada tibia de lentejas y salmón ahumado', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 380, 27, 32, 16, 2, false, false, '{"pescado"}', '[{"name":"Lentejas cocidas","amount":300,"unit":"g"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Cebolleta","amount":40,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar lentejas cocidas en un cazo a fuego suave hasta que estén templadas.","Picar cebolleta muy fina.","Picar eneldo fresco fino.","Cortar salmón ahumado en lascas de bocado.","Mezclar aceite de oliva y vinagre de manzana en un bol pequeño hasta integrar el aliño.","Repartir rúcula en la base de los platos.","Añadir las lentejas templadas sobre la rúcula y verter el aliño por encima.","Repartir el salmón, la cebolleta picada y el eneldo sobre las lentejas.","Servir enseguida mientras las lentejas están templadas."}', 'Lentejas templadas con salmón ahumado, cebolleta y eneldo sobre un fondo de rúcula.', '[{"appliance":"thermomix","time":12,"difficulty":"facil","prepSummary":"Pica la cebolleta y emulsiona el aderezo en el vaso. Luego, calienta las lentejas cocidas suavemente a 90°C durante unos minutos para que queden tibias y listas para mezclar."},{"appliance":"microondas","time":5,"difficulty":"facil","prepSummary":"Calienta las lentejas cocidas en un recipiente apto para microondas durante 2-3 minutos a potencia media-alta, removiendo a mitad, hasta que estén tibias. Luego, mezcla con el resto de ingredientes."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('legumbres_050', 'Garbanzos fritos crujientes especiados', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 320, 12, 30, 17, 2, true, false, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Pimentón picante","amount":4,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Ajo en polvo","amount":3,"unit":"g"}]'::jsonb, '{"Escurrir garbanzos cocidos con un colador y secarlos bien con papel de cocina hasta que no quede humedad superficial.","Calentar aceite de oliva en sartén amplia a fuego fuerte hasta que esté bien caliente.","Añadir los garbanzos en una sola capa sin moverlos hasta que se doren por debajo.","Saltear los garbanzos removiendo con frecuencia hasta que estén dorados y crujientes por todos los lados.","Retirar los garbanzos de la sartén y escurrirlos sobre papel de cocina.","Espolvorear pimentón picante, comino molido y ajo en polvo sobre los garbanzos aún calientes.","Remover los garbanzos para que las especias se adhieran bien por todos los lados.","Servir los garbanzos templados en un bol."}', 'Garbanzos dorados y crujientes por fuera, especiados para picotear recién hechos.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Mezcla los garbanzos con el aceite y las especias. Cocina en la airfryer a 190°C durante 15-20 minutos, agitando la cesta a mitad para asegurar un dorado y crujido uniforme."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Extiende los garbanzos sazonados con aceite y especias en una bandeja de horno. Hornea a 200°C durante 20-25 minutos, removiendo una o dos veces para que queden bien crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_051', 'Judías verdes con garbanzos y jamón', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 340, 20, 32, 14, 2, true, true, '{}', '[{"name":"Judías verdes","amount":300,"unit":"g"},{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Despuntar judías verdes, retirar los hilos si los tienen y cortar en trozos de unos 4 cm.","Picar cebolla y ajo finos.","Cortar jamón serrano en taquitos pequeños.","Llevar a ebullición agua con sal en un cazo y cocer las judías verdes hasta que estén tiernas pero firmes.","Escurrir las judías verdes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo picados a fuego medio hasta que estén blandos.","Añadir el jamón serrano en taquitos y saltear hasta que suelte su aroma.","Añadir tomate triturado y sofreír a fuego medio.","Añadir las judías verdes escurridas y garbanzos cocidos y saltear todo junto a fuego medio-fuerte.","Servir bien caliente, con cuidado al rectificar la sal ya que el jamón aporta salinidad."}', 'Judías verdes salteadas con garbanzos y virutas de jamón serrano.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa las judías verdes, cebolla y ajo con aceite en una bandeja a 190°C durante 20-25 minutos. Luego, incorpora los garbanzos, jamón y tomate triturado, y cocina 10 minutos más para que los sabores se integren y el tomate reduzca ligeramente."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade las judías verdes y un poco de agua, cocinando a 100°C o Varoma. Finalmente, incorpora los garbanzos, jamón y tomate triturado, y cocina unos minutos más a velocidad cuchara para integrar los sabores."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, el ajo y el jamón en la olla. Añade las judías verdes, garbanzos y tomate triturado con un chorrito de agua. Cierra la olla y cocina 5-7 minutos desde que sube la presión. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_052', 'Alubiada con butifarra y costilla', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'normal', 'invierno', 680, 36, 48, 36, 2, true, true, '{}', '[{"name":"Alubias blancas","amount":220,"unit":"g"},{"name":"Butifarra","amount":150,"unit":"g"},{"name":"Costilla de cerdo","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Dejar alubias blancas en remojo con agua fría abundante durante al menos 8 horas o toda la noche.","Escurrir las alubias blancas y reservar.","Picar cebolla en dados pequeños.","Picar zanahoria en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte.","Dorar costilla de cerdo por todos sus lados hasta que esté bien sellada, unos 5 min. Reservar.","Sofreír la cebolla picada, la zanahoria picada y el ajo picado en el mismo aceite a fuego medio.","Continuar sofriendo hasta que la verdura esté blanda, unos 6 min.","Añadir tomate triturado y sofreír a fuego medio hasta que se evapore el líquido, unos 3 min.","Incorporar las alubias escurridas, la costilla reservada y hoja de laurel a la olla.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Retirar la espuma que pueda formarse en la superficie con una cuchara.","Tapar la olla, bajar a fuego suave y cocer hasta que las alubias empiecen a estar tiernas, unos 50 min.","Añadir butifarra entera y continuar la cocción a fuego suave hasta que las alubias y la carne estén tiernas.","Cocer tapado a fuego suave hasta que todo esté tierno y el caldo haya espesado, unos 20 min.","Retirar la hoja de laurel y desechar.","Cortar la butifarra en rodajas y volver a incorporar a la olla.","Servir el guiso bien caliente y espeso en platos hondos."}', 'Guiso catalán de alubias con butifarra y costilla de cerdo, generoso y de cuchara.', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en una cazuela apta para horno. Añade las alubias, el tomate y el laurel, cubre con caldo y hornea a 160°C durante 90-120 minutos hasta que las alubias estén tiernas y los sabores se hayan integrado."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Trocea las verduras y sofríelas. Incorpora la butifarra y la costilla troceadas para dorar ligeramente. Añade las alubias, tomate, laurel y caldo, y cocina a 100°C, velocidad cuchara, giro inverso, durante 80-90 minutos, hasta que las alubias estén tiernas."},{"appliance":"olla_express","time":60,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne en la olla. Añade las alubias (previamente remojadas), tomate, laurel y caldo. Cierra la olla y cocina a presión alta durante 25-30 minutos, dejando despresurizar de forma natural para un resultado tierno y sabroso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_053', 'Garbanzos con pulpo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 380, 28, 34, 12, 2, true, true, '{"moluscos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Pulpo cocido","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados pequeños.","Cortar pulpo cocido en rodajas de un dedo de grosor.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla y el ajo picados a fuego medio hasta que estén transparentes.","Retirar la cazuela del fuego y añadir pimentón dulce.","Remover rápido el pimentón para que no se queme.","Incorporar garbanzos cocidos con un chorrito de agua y remover para integrar con el sofrito.","Cocer a fuego suave hasta que los garbanzos absorban el sabor del pimentón.","Añadir las rodajas de pulpo y calentar a fuego suave hasta que estén calientes, sin que hierva fuerte.","Picar perejil fresco fino.","Repartir los garbanzos y el pulpo en platos hondos.","Rociar con el resto del aceite de oliva en crudo y espolvorear con el perejil picado."}', 'Garbanzos guisados en un suave sofrito de pimentón con rodajas de pulpo tierno.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Sofreír la cebolla y el ajo aparte. Mezclar con los garbanzos, pulpo, pimentón y aceite, y cocinar en la airfryer a 180-190°C durante 15-20 minutos, removiendo a mitad, para calentar y dorar ligeramente."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sofreír la cebolla y el ajo en una fuente apta para horno. Añadir los garbanzos, pulpo, pimentón y aceite, mezclando bien, y hornear a 180°C durante 30-35 minutos para que los sabores se integren."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Picar cebolla y ajo, y sofreír con aceite. Incorporar los garbanzos, pulpo y pimentón, y cocinar a temperatura y velocidad bajas (ej. 100°C, velocidad cuchara, 15-20 min) para integrar los sabores."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_054', 'Lentejas con morcilla y manzana', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 560, 24, 50, 28, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Morcilla de Burgos","amount":150,"unit":"g"},{"name":"Manzana","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Lavar lentejas bajo el grifo en un colador hasta que el agua salga limpia.","Escurrir las lentejas y reservar.","Picar cebolla en dados pequeños.","Cortar zanahoria en dados pequeños.","Pelar manzana y cortarla en dados algo más grandes que la cebolla y la zanahoria.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria a fuego medio hasta que estén blandas.","Retirar la olla del fuego y añadir pimentón dulce.","Remover el pimentón con la verdura hasta integrarlo y volver a poner la olla al fuego.","Añadir las lentejas escurridas y cubrir con agua hasta superarlas unos 3 cm.","Llevar a ebullición a fuego fuerte.","Bajar el fuego a suave, tapar la olla y cocer hasta que las lentejas estén casi tiernas.","Retirar la piel de morcilla de burgos y desmenuzarla en trozos.","Añadir la morcilla desmenuzada y la manzana en dados a la olla.","Cocer sin tapar a fuego suave hasta que la manzana esté tierna y el guiso haya espesado.","Retirar la olla del fuego y dejar reposar el guiso.","Servir las lentejas bien calientes."}', 'Lentejas guisadas con morcilla desmenuzada y dados de manzana, un contraste dulce y sabroso.', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Prepara un sofrito con la cebolla y zanahoria en una cazuela apta para horno. Añade las lentejas, el pimentón, agua o caldo y hornea tapado a 180°C durante 60-75 minutos. Incorpora la morcilla y la manzana los últimos 15 minutos para que se integren bien."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Sofríe la cebolla y zanahoria picadas en el vaso con aceite. Añade las lentejas, agua o caldo, el pimentón y programa 35-40 minutos, 100°C, giro inverso, velocidad cuchara. Incorpora la morcilla y la manzana troceadas al final para que se cocinen brevemente."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Haz un sofrito con la cebolla y zanahoria en la olla. Añade las lentejas, el pimentón y el agua o caldo. Cierra y cocina a presión durante 12-15 minutos. Una vez despresurizada, incorpora la morcilla y la manzana y cocina a fuego suave unos minutos más para que se integren los sa"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_055', 'Potaje de habichuelas con conejo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'normal', 'invierno', 480, 30, 42, 18, 2, true, true, '{}', '[{"name":"Judías blancas","amount":200,"unit":"g"},{"name":"Conejo troceado","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Poner judías blancas en un bol grande cubiertas con agua fría abundante y dejar en remojo un mínimo de 8 horas.","Escurrir las judías blancas remojadas y reservar.","Picar cebolla en dados pequeños.","Picar pimiento rojo en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego fuerte hasta que esté bien caliente.","Dorar conejo troceado por todos los lados hasta que esté bien sellado, unos 6 min.","Retirar el conejo dorado de la olla y reservar.","Sofreír la cebolla picada, el pimiento picado y el ajo picado en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego, añadir pimentón dulce y remover para que no se queme.","Volver la olla al fuego medio, añadir tomate triturado y sofreír hasta que el tomate pierda el agua y se integre.","Añadir las judías escurridas, el conejo reservado y hoja de laurel a la olla.","Cubrir con agua fría hasta superar los ingredientes unos 4 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que las judías y el conejo estén tiernos, unos 50 min.","Añadir agua caliente si el caldo reduce demasiado durante la cocción.","Retirar la hoja de laurel del potaje antes de servir.","Servir el potaje bien caliente en cuencos hondos, con el caldo espeso."}', 'Potaje suave de judías blancas con conejo, de caldo espeso y sabroso.', '[{"appliance":"horno","time":90,"difficulty":"normal","prepSummary":"Se sofríen las verduras y se dora el conejo en una cazuela apta para horno. Se añaden las judías (previamente en remojo o cocidas), el tomate, pimentón, laurel y el líquido. Se cocina a fuego lento en el horno a unos 160-170°C durante 90 minutos, permitiendo que los sabores se in"},{"appliance":"thermomix","time":75,"difficulty":"normal","prepSummary":"Se prepara el sofrito en el vaso de la Thermomix. Se incorpora el conejo troceado y se dora. Luego se añaden las judías (previamente en remojo o cocidas), el tomate, pimentón, laurel y el líquido, cocinando a 100°C, velocidad cuchara, durante 75 minutos para un guiso homogéneo y "},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Se sofríen las verduras y se dora el conejo en la olla abierta. Se añaden las judías (previamente en remojo), tomate, pimentón, laurel y el líquido. Se cierra la olla y se cocina a presión durante 25-30 minutos, logrando un guiso tierno y con sabores concentrados en mucho menos t"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_056', 'Ensalada de garbanzos asados crujientes con feta', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 380, 16, 32, 20, 2, true, true, '{"lactosa"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Queso feta","amount":80,"unit":"g"},{"name":"Tomates cherry","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla roja","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Orégano seco","amount":2,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Escurrir garbanzos cocidos y secarlos bien con papel de cocina.","Extender los garbanzos en una bandeja de horno.","Añadir aceite de oliva, comino molido y sal sobre los garbanzos y mezclar hasta que queden bien cubiertos.","Hornear los garbanzos 20 min hasta que estén dorados y crujientes, removiendo a mitad de cocción.","Cortar tomates cherry por la mitad.","Cortar pepino en dados pequeños.","Laminar cebolla roja en juliana fina.","Desmenuzar queso feta en trozos irregulares con los dedos o un tenedor.","Mezclar en un bol los tomates cherry, el pepino y la cebolla roja.","Aliñar la mezcla con el resto del aceite de oliva, zumo de limón y orégano seco.","Retirar los garbanzos del horno cuando estén crujientes y dejarlos templar 2 min.","Incorporar los garbanzos templados al bol y mezclar con suavidad.","Repartir el queso feta desmenuzado por encima y servir de inmediato."}', 'Garbanzos asados hasta quedar crujientes sobre una ensalada fresca con feta desmenuzado.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Los garbanzos se mezclan con aceite y especias, se extienden en una bandeja y se asan en el horno precalentado a 200°C durante 25-30 minutos, removiendo a mitad, hasta que estén dorados y crujientes. Luego se mezclan con el resto de ingredientes frescos."},{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para unos garbanzos extra crujientes en menos tiempo, cocínalos en la airfryer a 190°C durante 15-20 minutos, agitándolos cada 5 minutos. Es clave no sobrecargar la cesta para asegurar una cocción uniforme y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_057', 'Alubias negras con arroz estilo cubano', 'legumbres', 'legumbre', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 480, 16, 82, 10, 2, true, true, '{}', '[{"name":"Alubias negras cocidas","amount":300,"unit":"g"},{"name":"Arroz blanco","amount":160,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Hoja de laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Llevar a ebullición agua con sal en un cazo a fuego fuerte.","Añadir arroz blanco y cocer a fuego medio hasta que esté tierno.","Picar cebolla en dados pequeños.","Picar pimiento verde en dados pequeños.","Picar ajo fino.","Escurrir el arroz cocido y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el pimiento picado a fuego medio hasta que estén blandos.","Añadir el ajo picado y comino molido y sofreír hasta que suelten aroma.","Incorporar alubias negras cocidas y hoja de laurel a la sartén.","Cocer a fuego suave hasta que el conjunto espese ligeramente.","Aplastar ligeramente algunas alubias con el dorso de una cuchara para espesar la salsa.","Retirar la hoja de laurel de las alubias.","Servir las alubias negras junto al arroz blanco, uno al lado del otro en el plato."}', 'Alubias negras guisadas al estilo cubano, servidas junto a arroz blanco suelto.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno, añade las alubias cocidas, especias y un poco de agua o caldo. Hornea a 180°C durante 35-40 minutos para que los sabores se integren. El arroz se cocina aparte en una olla."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite. Añade las alubias cocidas, especias y agua, cocinando a 100°C, velocidad cuchara, durante 20-25 minutos. Puedes cocinar el arroz en el cestillo al mismo tiempo para una cocción simultánea y eficiente."},{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express, añade las alubias cocidas, especias y un poco de agua o caldo. Cierra la olla y cocina a presión durante 7-10 minutos para que los sabores se concentren rápidamente. El arroz se prepara en una olla aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_058', 'Garbanzos con curry y espinacas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 420, 16, 40, 22, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Leche de coco","amount":150,"unit":"ml"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Curry en polvo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomate triturado","amount":60,"unit":"ml"}]'::jsonb, '{"Picar cebolla en dados finos.","Picar ajo fino.","Rallar jengibre fresco fino.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el ajo picado y el jengibre rallado y sofreír hasta que suelten aroma.","Añadir curry en polvo y remover hasta que tueste ligeramente sin quemarse.","Añadir tomate triturado y sofreír hasta que reduzca ligeramente.","Incorporar garbanzos cocidos y leche de coco y remover hasta mezclar bien.","Llevar a ebullición suave a fuego medio-bajo.","Cocer a fuego medio-bajo hasta que el guiso espese y los sabores se integren.","Añadir espinacas y cocer hasta que se ablanden.","Servir bien caliente."}', 'Garbanzos en un guiso de curry cremoso con espinacas, rápido y de sabor potente.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla, ajo y jengibre unos segundos. Sofríe con aceite 5 min a 120°C. Añade el resto de ingredientes (excepto espinacas), programa 15 min a 100°C, giro inverso, velocidad cuchara. Incorpora las espinacas los últimos 2-3 min."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y jengibre en la olla abierta con aceite. Añade el curry, tomate, leche de coco y garbanzos. Cierra la olla y cocina a presión mínima durante 3-5 minutos. Libera la presión, incorpora las espinacas y cocina un par de minutos más hasta que se integren."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_059', 'Lentejas con salchichas y pimentón', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 520, 24, 48, 24, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Salchichas frescas","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón dulce","amount":6,"unit":"g"}]'::jsonb, '{"Lavar lentejas en un colador bajo el grifo hasta que el agua salga limpia y escurrir.","Picar cebolla y ajo fino.","Cortar zanahoria en dados pequeños.","Cortar salchichas frescas en rodajas de un dedo de grosor.","Calentar aceite de oliva en una olla a fuego medio-fuerte.","Dorar las salchichas en la olla hasta que estén tostadas por fuera, unos 3 min, y reservar.","Sofreír la cebolla, la zanahoria y el ajo en el mismo aceite a fuego medio hasta que estén blandos.","Retirar la olla del fuego y añadir pimentón dulce removiendo rápido para que no se queme.","Incorporar tomate triturado y sofreír a fuego medio hasta que reduzca y se integre.","Añadir las lentejas escurridas y cubrir con agua hasta superarlas unos 3 cm.","Llevar la olla a ebullición a fuego fuerte.","Tapar, bajar el fuego al mínimo y cocer hasta que las lentejas estén casi tiernas.","Incorporar las salchichas reservadas y cocer a fuego suave hasta que las lentejas estén completamente tiernas.","Servir en platos hondos bien caliente."}', 'Lentejas guisadas con salchichas y el rojo del pimentón, un plato de toda la vida.', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Sofríe la cebolla, zanahoria y ajo en una cazuela apta para horno. Añade las salchichas para dorarlas ligeramente. Incorpora las lentejas, tomate, pimentón y agua o caldo, y cocina tapado en el horno precalentado a 180°C durante 60-70 minutos, o hasta que las lentejas estén tiern"},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Trocea la cebolla, zanahoria y ajo y sofríe con aceite. Añade las salchichas troceadas y sofríe unos minutos más. Incorpora las lentejas, tomate, pimentón y agua, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos, o hasta que las lentejas estén a tu gusto."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe la cebolla, zanahoria y ajo en la olla express. Añade las salchichas para dorarlas. Incorpora las lentejas, tomate, pimentón y agua o caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula, dejando despresurizar antes de abrir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_060', 'Hummus de calabaza asada', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 320, 9, 32, 17, 2, true, true, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Tahini","amount":20,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar calabaza y cortar en dados de 2 cm.","Pelar ajo y reservar.","Disponer los dados de calabaza en una bandeja de horno en una sola capa.","Regar la calabaza con aceite de oliva y hornear hasta que esté blanda y ligeramente dorada.","Retirar la bandeja del horno y dejar templar la calabaza asada.","Añadir garbanzos cocidos, la calabaza templada, tahini, zumo de limón, el ajo y comino molido a un vaso batidor.","Triturar a máxima potencia hasta obtener una crema homogénea.","Añadir el resto del aceite de oliva en hilo fino mientras se tritura hasta que la crema quede suave y cremosa.","Extender el hummus en un plato hondo y terminar con aceite de oliva por encima."}', 'Hummus suave con el dulzor de la calabaza asada, sorprendente y cremoso.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Asa la calabaza y el ajo troceados con un chorrito de aceite de oliva durante 25-30 minutos hasta que estén tiernos y ligeramente caramelizados. Luego, tritura todos los ingredientes hasta obtener un hummus suave."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Corta la calabaza en cubos pequeños y ásala junto al ajo en la airfryer a 190°C durante 15-20 minutos, removiendo a mitad, hasta que esté tierna y dorada. Después, procesa todos los ingredientes hasta conseguir una textura cremosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_061', 'Alubias blancas con setas y romero', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'invierno', 380, 16, 40, 16, 2, true, true, '{"sulfitos","lactosa"}', '[{"name":"Alubias blancas cocidas","amount":350,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Romero fresco","amount":3,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo y cortar en trozos las que sean grandes.","Picar cebolla en dados finos.","Picar ajo en dados finos.","Picar romero fresco fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir el ajo picado y las setas troceadas y saltear a fuego fuerte hasta que las setas se doren.","Añadir el romero picado y vino blanco, subir el fuego y cocer hasta que el alcohol se evapore.","Incorporar alubias blancas cocidas y remover para integrar con las setas.","Cocer a fuego suave, tapado, hasta que los sabores se integren.","Añadir nata para cocinar y remover con suavidad.","Cocer a fuego suave hasta que la salsa esté cremosa, sin que llegue a hervir fuerte.","Servir bien caliente."}', 'Alubias blancas en un guiso cremoso con setas salteadas y aroma a romero fresco.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Sofríe ligeramente la cebolla y el ajo en una sartén apta para horno o directamente en el horno con las setas y romero a 180°C durante 20-25 min. Luego, añade las alubias, el vino y la nata, y hornea otros 15-20 min para que los sabores se integren."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade las setas y el romero, cocina a temperatura Varoma. Incorpora las alubias, el vino blanco y la nata, y cocina a 90°C con giro inverso hasta que la salsa espese y los sabores se integren."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla, el ajo y las setas con aceite y romero en la olla abierta. Añade las alubias, el vino blanco y la nata. Cocina a fuego medio-bajo durante 10-15 minutos, removiendo ocasionalmente, para que los sabores se integren y la salsa espese ligeramente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_062', 'Garbanzos con chorizo y huevo frito', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 580, 28, 40, 34, 2, true, false, '{"huevo"}', '[{"name":"Garbanzos cocidos","amount":350,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en dados finos.","Cortar chorizo en rodajas de unos 5 mm.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y el ajo picados hasta que estén blandos.","Añadir el chorizo en rodajas y saltear hasta que suelte su grasa y aroma.","Retirar la sartén del fuego y añadir pimentón dulce; remover rápido.","Volver al fuego y añadir tomate triturado; sofreír a fuego medio.","Añadir garbanzos cocidos con un chorrito de agua; cocer a fuego medio removiendo de vez en cuando.","Calentar el resto del aceite de oliva en otra sartén a fuego fuerte.","Freír huevo uno a uno hasta que la clara esté cuajada y el borde crujiente, con la yema jugosa.","Repartir los garbanzos con chorizo en 2 platos y coronar cada uno con un huevo frito."}', 'Garbanzos guisados con chorizo, con la puntilla crujiente de un huevo frito encima.', '[{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y chorizo en la olla abierta. Añade el tomate, garbanzos y pimentón. Cierra la olla y cocina a presión 5-7 minutos para integrar sabores. Sirve con un huevo frito recién hecho en una sartén aparte."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el ajo en el vaso. Añade el chorizo troceado y sofríe. Incorpora el tomate, garbanzos y pimentón, cocinando a 100°C/Vel. Cuchara/Giro inverso durante 15-20 minutos. Sirve con un huevo frito hecho aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_063', 'Cocido madrileño en tres vuelcos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 150, 'facil', 'invierno', 610, 37, 38, 31, 4, true, true, '{"gluten"}', '[{"name":"Garbanzos","amount":500,"unit":"g"},{"name":"Morcillo de ternera","amount":300,"unit":"g"},{"name":"Pollo","amount":240,"unit":"g"},{"name":"Tocino","amount":100,"unit":"g"},{"name":"Hueso de jamón","amount":100,"unit":"g"},{"name":"Chorizo","amount":120,"unit":"g"},{"name":"Morcilla","amount":100,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Repollo","amount":300,"unit":"g"},{"name":"Fideos finos","amount":80,"unit":"g"}]'::jsonb, '{"Cubrir garbanzos con agua fría abundante y dejar en remojo un mínimo de 12 horas.","Pelar patata y zanahoria y cortar en trozos grandes.","Cortar repollo en cuartos.","Escurrir los garbanzos remojados.","Colocar morcillo de ternera, pollo, tocino y hueso de jamón en una olla grande y cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir los garbanzos escurridos y la zanahoria troceada, bajar a fuego suave y tapar.","Cocer tapado a fuego suave durante 60 min.","Incorporar la patata troceada, el repollo y chorizo entero; tapar y subir ligeramente el fuego.","Cocer tapado a fuego suave hasta que la patata esté tierna, unos 20 min.","Añadir morcilla entera y cocer tapado 10 min más para que no se deshaga.","Retirar la morcilla, el chorizo, el morcillo, el pollo y el tocino de la olla y reservar en una fuente tapada.","Retirar los garbanzos, la patata, la zanahoria y el repollo con una espumadera y reservar en una fuente aparte.","Colar el caldo sobrante y llevar a ebullición en un cazo a fuego fuerte.","Cocer fideos finos en el caldo hirviendo hasta que estén tiernos, unos 3 min.","Servir la sopa con los fideos como primer vuelco en soperas o platos hondos.","Servir como segundo vuelco los garbanzos con la zanahoria, la patata y el repollo bien escurridos en una fuente.","Trinchar el morcillo, el pollo y el tocino en porciones y cortar el chorizo y la morcilla en rodajas.","Servir las carnes y embutidos como tercer vuelco en una fuente aparte."}', 'El cocido de siempre servido en sus tres vuelcos: sopa, garbanzos con verdura y carnes, la comida que resuelve varios días.', '[{"appliance":"olla_express","time":120,"difficulty":"facil","prepSummary":"Ideal para acortar el tiempo de cocción de garbanzos y carnes, logrando un caldo sabroso y concentrado. Cocina los ingredientes principales a presión y luego añade las verduras y fideos para el punto final."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_064', 'Sopa de cocido con fideos finos', 'legumbres', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 180, 6, 28, 5, 2, true, true, '{"gluten"}', '[{"name":"Caldo de cocido","amount":600,"unit":"ml"},{"name":"Fideos finos","amount":80,"unit":"g"},{"name":"Perejil fresco","amount":3,"unit":"g"}]'::jsonb, '{"Colar caldo de cocido sobre la olla para retirar restos de verdura o grasa suelta.","Llevar el caldo a ebullición a fuego fuerte.","Picar perejil fresco fino y reservar.","Añadir fideos finos cuando el caldo rompa a hervir y remover para que no se peguen.","Cocer a fuego medio hasta que los fideos estén sueltos y tiernos.","Retirar del fuego y dejar reposar.","Servir en tazones hondos y espolvorear el perejil picado por encima."}', 'El primer vuelco del cocido servido solo: caldo dorado con fideos finos recién cocidos.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Vierte el caldo en el vaso y calienta 10 min/100°C/vel 1. Añade los fideos y cocina 8-10 min/100°C/vel 1, o el tiempo indicado en el paquete, hasta que estén al dente. Sirve con perejil fresco."},{"appliance":"microondas","time":10,"difficulty":"facil","prepSummary":"Calienta el caldo en un recipiente apto para microondas a máxima potencia durante 5-7 minutos hasta que hierva. Incorpora los fideos y cocina 3-5 minutos más, o hasta que estén tiernos, removiendo a mitad de cocción. Finaliza con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_065', 'Ropa vieja de cocido con garbanzos', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 480, 32, 30, 24, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":250,"unit":"g"},{"name":"Carne de cocido variada","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Desmenuzar carne de cocido variada con las manos o dos tenedores en tiras finas.","Picar cebolla y pimiento verde en dados pequeños.","Picar ajo fino.","Calentar aceite de oliva en una sartén amplia a fuego medio.","Sofreír la cebolla y el pimiento verde hasta que estén blandos.","Añadir el ajo y sofreír hasta que desprenda aroma.","Retirar la sartén del fuego y añadir pimentón dulce.","Remover el pimentón con la verdura hasta que se integre.","Volver la sartén al fuego y añadir tomate triturado.","Sofreír el tomate a fuego medio hasta que pierda el agua y se oscurezca.","Añadir la carne desmenuzada y saltear a fuego fuerte hasta que se dore por los bordes.","Incorporar garbanzos cocidos y saltear hasta que estén bien calientes y ligados con la salsa.","Servir bien caliente directamente desde la sartén."}', 'La carne y el garbanzo sobrantes del cocido, salteados y dorados en la sartén del día siguiente.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en una sartén. Incorpora la carne, garbanzos, tomate y pimentón, mezcla bien y pasa a una fuente de horno. Hornea a 180°C durante 15-20 minutos para que los sabores se integren y se caliente uniformemente."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade la carne desmenuzada, garbanzos, tomate y pimentón. Cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 10-12 minutos para integrar los sabores."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, pimiento y ajo en la olla express abierta con aceite. Añade el tomate, pimentón, carne y garbanzos. Tapa y cocina a fuego medio durante 5-7 minutos sin presión para que los sabores se mezclen bien."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_066', 'Puchero andaluz con hierbabuena', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 100, 'facil', 'invierno', 520, 28, 42, 24, 4, true, true, '{}', '[{"name":"Garbanzos","amount":400,"unit":"g"},{"name":"Pollo troceado","amount":400,"unit":"g"},{"name":"Tocino","amount":80,"unit":"g"},{"name":"Chorizo","amount":100,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Judías verdes","amount":150,"unit":"g"},{"name":"Calabaza","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Hierbabuena fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Poner garbanzos en remojo en un bol grande cubiertos con agua fría abundante un mínimo de 12 h.","Escurrir los garbanzos y reservar.","Pelar patata y calabaza y cortar ambas en trozos grandes.","Despuntar judías verdes y cortar en trozos de unos 4 cm.","Picar cebolla fina.","Picar tomate en trozos pequeños.","Colocar pollo troceado y tocino en una olla grande y cubrir con agua fría abundante.","Llevar a ebullición a fuego fuerte.","Espumar la superficie con una espumadera hasta que el caldo salga limpio.","Añadir la cebolla picada, el tomate picado, aceite de oliva y los garbanzos escurridos.","Bajar el fuego a suave, tapar la olla y cocer 45 min.","Incorporar la patata, las judías verdes, la calabaza y chorizo entero.","Tapar de nuevo y cocer a fuego suave 25 min hasta que la patata y los garbanzos estén tiernos.","Picar hierbabuena fresca fina.","Añadir la hierbabuena picada al puchero y cocer 5 min más a fuego suave.","Retirar el chorizo y el tocino de la olla y cortar ambos en rodajas.","Devolver el chorizo y el tocino en rodajas a la olla y mezclar con el resto.","Servir bien caliente repartiendo caldo, garbanzos, verduras y carne en cada plato."}', 'Puchero de garbanzos y pollo perfumado con hierbabuena fresca, distinto del cocido del norte.', '[{"appliance":"horno","time":120,"difficulty":"facil","prepSummary":"Sofríe las carnes y verduras en una olla apta para horno, añade los garbanzos y el resto de ingredientes con agua o caldo. Cocina tapado a 160°C durante 2 horas para un puchero tierno y sabroso."},{"appliance":"thermomix","time":90,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras y carnes en el vaso. Incorpora los garbanzos, patata, judías, calabaza y líquido. Programa 90 min, 100°C, giro inverso, velocidad cuchara, para un guiso homogéneo."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Dora las carnes y sofríe las verduras en la olla. Añade los garbanzos (previamente remojados), patata, judías, calabaza y agua. Cierra y cocina 30-35 minutos desde que sube la válvula para un puchero rápido y tierno."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('legumbres_067', 'Buddha bowl de garbanzos asados y tahini', 'legumbres', 'legumbre', 'quinoa', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 480, 18, 46, 24, 2, true, false, '{"sesamo"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Quinoa","amount":100,"unit":"g"},{"name":"Boniato","amount":200,"unit":"g"},{"name":"Rúcula","amount":60,"unit":"g"},{"name":"Aguacate","amount":100,"unit":"g"},{"name":"Tahini","amount":25,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Pimentón ahumado","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar boniato y cortar en dados de 2 cm.","Escurrir garbanzos cocidos y secar con papel de cocina hasta que estén bien secos.","Mezclar el boniato y los garbanzos con aceite de oliva, comino molido y pimentón ahumado en una bandeja.","Hornear 25 min hasta que el boniato esté tierno y los garbanzos crujientes.","Llevar a ebullición agua con sal en un cazo y cocer quinoa según el tiempo del envase.","Escurrir la quinoa y dejar templar.","Mezclar tahini, zumo de limón y el resto del aceite de oliva con 2 cucharadas de agua hasta que el aliño esté fluido.","Laminar aguacate.","Retirar la bandeja del horno cuando el boniato esté tierno y los garbanzos crujientes.","Repartir la quinoa en 2 boles y añadir rúcula encima.","Añadir el boniato asado, los garbanzos crujientes y el aguacate laminado sobre cada bol.","Terminar cada bol con un chorrito del aliño de tahini por encima."}', 'Cuencos de colores con garbanzos asados crujientes, quinoa, boniato y un aliño cremoso de tahini.', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa los garbanzos y el boniato cortado en cubos en el horno precalentado a 200°C durante 20-25 minutos, hasta que estén dorados y tiernos. Cocina la quinoa en una olla aparte y prepara la salsa de tahini mientras se asan los vegetales."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C y cocina los garbanzos y el boniato en tandas durante 15-20 minutos, agitándolos a mitad, hasta que estén crujientes. Cocina la quinoa por separado y mezcla el aderezo de tahini."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_001', 'Smoothie de kéfir y fruta', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 210, 9, 34, 4, 2, true, false, '{"lactosa"}', '[{"name":"Kéfir","amount":300,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":120,"unit":"g"},{"name":"Miel","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar plátano y cortar en trozos.","Retirar el pedúnculo a fresas y cortar en mitades.","Añadir kéfir, el plátano troceado y las fresas al vaso de la batidora.","Añadir miel y triturar hasta que la mezcla quede cremosa y sin grumos.","Servir de inmediato en vasos bien fríos."}', 'Batido cremoso de kéfir con plátano y fresas endulzado con miel', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_002', 'Tostada de plátano y miel', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 260, 6, 46, 5, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Plátano","amount":2,"unit":"ud"},{"name":"Miel","amount":20,"unit":"ml"}]'::jsonb, '{"Tostar pan en una tostadora o bajo el grill del horno hasta que esté dorado y crujiente.","Laminar plátano en rodajas de unos 5 mm.","Disponer las rodajas de plátano sobre las tostadas, cubriéndolas bien.","Repartir miel en hilo fino sobre el plátano y servir de inmediato."}', 'Merienda rápida de tostada con plátano en rodajas y miel', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('meriendas_003', 'Bocadillo de jamón serrano', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 380, 20, 44, 13, 2, true, true, '{"gluten"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pan de barra por la mitad a lo largo para abrir cada pieza.","Cortar tomate maduro por la mitad y rallar la pulpa sobre cada mitad de pan hasta que quede bien impregnada.","Repartir aceite de oliva por encima de la pulpa de tomate en cada mitad de pan.","Distribuir jamón serrano sobre la base de cada bocadillo y cerrar con la tapa de pan.","Servir de inmediato para que el pan no se ablande."}', 'Bocadillo de jamón serrano con tomate y aceite', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_004', 'Bocadillo de pavo y queso', 'meriendas', 'none', 'pan', ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 360, 22, 42, 12, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Pechuga de pavo","amount":90,"unit":"g"},{"name":"Queso en lonchas","amount":50,"unit":"g"}]'::jsonb, '{"Cortar pan de barra por la mitad a lo largo sin llegar al fondo, dejando las dos mitades unidas.","Disponer queso en lonchas sobre la mitad inferior del pan, cubriéndola de manera uniforme.","Colocar pechuga de pavo sobre el queso, distribuyendo las lonchas en una sola capa.","Cerrar el bocadillo presionando ligeramente y servir."}', 'Bocadillo de fiambre de pavo con queso', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_005', 'Fruta con frutos secos', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 250, 6, 34, 11, 2, false, true, '{"frutos_secos"}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Nueces","amount":40,"unit":"g"}]'::jsonb, '{"Pelar plátano y cortarlo en rodajas.","Lavar manzana, retirar el corazón y cortarla en trozos.","Repartir la manzana y el plátano en 2 cuencos.","Añadir nueces por encima de la fruta y servir."}', 'Merienda de fruta troceada con nueces', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('meriendas_006', 'Batido de leche y cacao', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 220, 9, 32, 6, 2, true, false, '{"lactosa"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cacao en polvo","amount":30,"unit":"g"}]'::jsonb, '{"Verter leche en un cazo y calentar a fuego medio hasta que esté templada, o dejarla fría según preferencia.","Añadir cacao en polvo a la leche y remover con energía hasta que el cacao quede completamente disuelto sin grumos.","Servir el batido repartido en 2 vasos."}', 'Vaso de leche con cacao, la merienda clásica de la infancia', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_001', 'Macarrones con tomate', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 412, 14, 62, 12, 2, true, true, '{"gluten"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Llevar a ebullición una olla grande con agua abundante y sal.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min hasta que se dore ligeramente.","Añadir tomate triturado y orégano a la sartén y remover.","Cocer la salsa a fuego suave, sin tapar, hasta que espese ligeramente.","Cocer macarrones en el agua hirviendo con sal según el tiempo indicado en el envase.","Escurrir los macarrones cuando estén al dente y reservar.","Añadir los macarrones escurridos a la sartén con la salsa y mezclar a fuego suave 1 min.","Servir los macarrones en platos hondos."}', 'Macarrones con salsa de tomate casera y orégano', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, luego añade el tomate triturado y el orégano para la salsa. Incorpora los macarrones y el agua, cocinando a 100°C, velocidad cuchara, giro inverso, hasta que la pasta esté al dente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_002', 'Espaguetis a la boloñesa', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 518, 26, 58, 20, 2, true, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino tinto","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y picarla en dados finos. Pelar ajo y picarlo muy fino.","Pelar zanahoria y rallarla con un rallador fino.","Calentar aceite de oliva en sartén grande a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado en la sartén a fuego medio hasta que estén transparentes.","Añadir la zanahoria rallada y sofreír junto con la cebolla hasta que esté tierna.","Incorporar carne picada de ternera y saltear a fuego fuerte, desmenuzando con una cuchara, hasta que se dore por completo.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Incorporar tomate triturado y remover bien.","Tapar la sartén y cocer a fuego suave hasta que la salsa espese.","Llevar a ebullición una olla con abundante agua y sal.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo indicado en el paquete.","Escurrir los espaguetis y volcarlos en la sartén con la boloñesa.","Mezclar a fuego suave hasta que los espaguetis queden bien integrados con la salsa.","Servir los espaguetis con la salsa boloñesa bien repartida."}', 'Espaguetis con ragú de carne picada, tomate y zanahoria', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Prepara el sofrito y dora la carne en una olla apta para horno en la encimera. Añade el resto de ingredientes de la salsa y hornea a 150°C durante 1.5-2 horas para una boloñesa de sabor profundo. Los espaguetis se cuecen aparte."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite, añade la carne y el vino para dorar. Incorpora el tomate y cocina la salsa a temperatura y velocidad controladas. Los espaguetis se pueden cocer en el vaso o cestillo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_003', 'Arroz con tomate frito', 'pasta_arroces', 'none', 'arroz', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 342, 6, 58, 8, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar y picar ajo muy fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo picado en el aceite caliente hasta que esté dorado y fragante, sin que llegue a quemarse.","Añadir arroz y sofreír sin parar de remover hasta que los granos estén ligeramente translúcidos.","Incorporar tomate triturado y remover para integrar bien con el arroz.","Añadir 360 ml de agua, remover y llevar a ebullición a fuego fuerte.","Tapar la cazuela, bajar a fuego suave y cocer hasta que el arroz haya absorbido todo el líquido y esté tierno.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz con tomate en platos hondos recién hecho."}', 'Arroz blanco cocido con salsa de tomate frito', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en una cazuela apta para horno. Añade el arroz y el doble de agua, lleva a ebullición, tapa y hornea a 180°C durante 18-20 minutos hasta que el líquido se absorba."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en el vaso. Añade el arroz y el doble de agua, programa 18-20 minutos, 100°C, giro inverso, velocidad cuchara para un arroz suelto y bien integrado."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en la olla. Añade el arroz y 1.5 veces su volumen de agua, cierra la olla y cocina a presión durante 6-7 minutos. Deja despresurizar de forma natural para un arroz perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_004', 'Arroz al horno', 'pasta_arroces', 'cerdo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'invierno', 528, 24, 56, 22, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Costilla de cerdo","amount":150,"unit":"g"},{"name":"Morcilla","amount":60,"unit":"g"},{"name":"Garbanzos cocidos","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en rodajas de unos 5 mm de grosor.","Calentar aceite de oliva en una cazuela de barro a fuego medio.","Dorar costilla de cerdo en el aceite caliente hasta que esté dorada por todos los lados; retirar y reservar.","Dorar morcilla en la misma cazuela a fuego medio hasta que esté marcada; retirar y reservar.","Añadir tomate triturado a la cazuela y sofreír a fuego medio durante 3 min hasta que reduzca ligeramente.","Incorporar pimentón al sofrito y remover 30 segundos a fuego suave para que no se queme.","Precalentar el horno a 200 °C con calor arriba y abajo.","Repartir arroz de forma uniforme sobre el sofrito en la cazuela de barro.","Distribuir garbanzos cocidos, las rodajas de patata, la costilla reservada y la morcilla reservada sobre el arroz.","Verter agua o caldo caliente hasta cubrir el arroz unos 2 cm por encima (aprox. 360 ml); salpimentar al gusto.","Hornear la cazuela destapada a 200 °C durante 25 min hasta que el arroz esté seco y la superficie ligeramente dorada.","Retirar la cazuela del horno y dejar reposar 3 min antes de servir.","Servir el arroz al horno directamente en la cazuela de barro."}', 'Arroz al horno valenciano con costilla, morcilla y garbanzos', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara un sofrito con la costilla y el tomate, añade el arroz y el caldo (o agua con pimentón) en una cazuela de barro. Hornea a 190°C durante 45-50 minutos, incorporando la morcilla y las patatas cortadas a mitad de cocción para que se doren y el arroz quede suelto y con socarrat en el fondo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_005', 'Espaguetis carbonara', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 548, 22, 56, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Panceta","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano finamente y reservar.","Cortar panceta en dados de unos 5 mm y reservar.","Batir huevo en un bol.","Añadir el queso parmesano rallado al huevo batido y mezclar hasta obtener una crema homogénea. Reservar.","Llevar a ebullición una olla con agua abundante y sal al gusto.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la panceta en dados hasta que esté dorada y crujiente.","Escurrir los espaguetis reservando un vaso del agua de cocción.","Retirar la sartén del fuego e incorporar los espaguetis escurridos a la panceta.","Añadir la crema de huevo y parmesano sobre la pasta y remover con rapidez.","Añadir el agua de cocción reservada poco a poco hasta que la salsa ligue y quede cremosa sin cuajar el huevo.","Servir de inmediato con más queso parmesano rallado al gusto."}', 'Espaguetis carbonara con panceta, huevo y parmesano', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_006', 'Macarrones con atún', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 448, 24, 58, 14, 2, true, true, '{"gluten","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos finos y picar ajo.","Llevar a ebullición una olla con agua abundante y sal.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén hasta que esté transparente.","Añadir el ajo picado y sofreír 1 min hasta que se dore ligeramente.","Incorporar tomate triturado a la sartén y remover. Cocer a fuego medio hasta que reduzca.","Cocer macarrones en el agua hirviendo según el tiempo indicado en el paquete, hasta que estén al dente.","Escurrir atún en conserva y desmenuzarlo con un tenedor.","Añadir el atún desmenuzado a la salsa de tomate y mezclar a fuego suave.","Añadir orégano a la salsa y remover para integrar.","Escurrir los macarrones y añadirlos a la sartén con la salsa. Mezclar bien a fuego suave hasta que estén integrados.","Servir los macarrones en platos hondos y añadir orégano al gusto."}', 'Macarrones con salsa de tomate y atún en conserva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade el tomate triturado, orégano y un poco de agua, cocina unos minutos. Incorpora los macarrones y cocina el tiempo indicado en el paquete. Finalmente, añade el atún escurrido y mezcla."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_007', 'Arroz con pollo', 'pasta_arroces', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 498, 30, 54, 16, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de unos 4 cm.","Salpimentar los trozos de contramuslo de pollo y reservar.","Picar cebolla en brunoise fina.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela amplia a fuego medio hasta que esté caliente.","Dorar los trozos de contramuslo de pollo en la cazuela a fuego medio-fuerte hasta que estén dorados por todos los lados.","Retirar el contramuslo de pollo dorado y reservar en un plato.","Sofreír la cebolla picada y el pimiento rojo en la misma cazuela a fuego medio hasta que estén tiernos.","Añadir tomate triturado y pimentón al sofrito; remover hasta integrar.","Cocinar el sofrito a fuego medio hasta que el tomate pierda el agua.","Añadir arroz y remover hasta que los granos queden bien impregnados del sofrito.","Incorporar el contramuslo de pollo reservado y guisantes; remover para integrar.","Cubrir con 360 ml de agua caliente, llevar a ebullición a fuego fuerte y ajustar de sal.","Cocer a fuego suave, tapado, sin remover hasta que el arroz haya absorbido todo el líquido.","Retirar del fuego y dejar reposar tapado antes de servir.","Servir el arroz con pollo directamente de la cazuela, repartiendo el pollo de forma uniforme."}', 'Arroz caldoso con trozos de pollo, pimiento y guisantes', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara un sofrito con el pollo y las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de caldo caliente que de arroz, y hornea a 190°C durante 25-30 minutos hasta que el arroz absorba el líquido y esté tierno."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras, luego dora el pollo. Incorpora el arroz, tomate, pimentón y el caldo (doble de agua que de arroz), y cocina a 100°C, giro inverso, velocidad cuchara, durante 20-22 minutos, hasta que el arroz esté en su punto."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el pollo y las verduras en la olla abierta. Añade el arroz, tomate, pimentón y el caldo (1.5 veces el volumen de arroz), cierra la olla y cocina a presión media-alta durante 8-10 minutos desde que sube la válvula. Deja reposar unos minutos antes de abrir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_008', 'Fideos con carne', 'pasta_arroces', 'cerdo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 472, 24, 54, 18, 2, true, true, '{"gluten"}', '[{"name":"Fideos gruesos","amount":180,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Picar cebolla y pimiento verde en trozos pequeños. Picar ajo fino. Reservar por separado.","Calentar aceite de oliva en una sartén amplia a fuego fuerte hasta que esté caliente.","Añadir carne picada de cerdo y dorar a fuego fuerte, removiendo, hasta que pierda el color rosado y esté dorada.","Retirar la carne de la sartén y reservar en un plato.","Bajar a fuego medio. Sofreír la cebolla y el pimiento verde picados en la misma sartén hasta que estén tiernos.","Añadir el ajo picado y pimentón y sofreír hasta que el ajo esté dorado, sin que se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y la salsa esté concentrada.","Añadir fideos gruesos y tostar en la salsa a fuego medio, removiendo, hasta que se doren ligeramente.","Cubrir los fideos con agua caliente o caldo hasta superarlos en 1 cm. Llevar a ebullición a fuego fuerte.","Incorporar la carne reservada, remover y cocer a fuego medio hasta que los fideos estén tiernos y absorban el caldo.","Retirar del fuego y dejar reposar 1 min antes de servir.","Servir los fideos con la carne directamente en platos hondos."}', 'Fideos gruesos guisados con carne picada y sofrito', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla, pimiento y ajo. Sofríe con aceite, añade la carne y sofríe. Incorpora el tomate, pimentón, fideos y agua/caldo. Cocina a temperatura y tiempo indicados para los fideos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_009', 'Arroz a la cubana', 'pasta_arroces', 'huevo', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 468, 14, 62, 18, 2, true, false, '{"huevo"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Plátano macho","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar ajo y picar fino. Reservar.","Pelar plátano macho y cortar en rodajas de 1 cm. Reservar.","Llevar a ebullición una olla con agua y sal a fuego fuerte.","Añadir arroz al agua hirviendo y cocer a fuego medio durante 18 min hasta que esté tierno.","Calentar aceite de oliva en sartén a fuego medio y sofreír el ajo picado 1 min hasta que empiece a dorarse.","Añadir tomate triturado a la sartén con el ajo y cocer a fuego suave 8 min hasta que la salsa espese.","Retirar la salsa de tomate de la sartén y reservar.","Calentar aceite de oliva en sartén a fuego fuerte y freír las rodajas de plátano macho 2 min hasta que estén doradas.","Dar la vuelta a las rodajas de plátano macho y freír 2 min más hasta que estén doradas por el otro lado. Retirar y reservar.","Freír huevo en la misma sartén a fuego medio hasta que la clara esté cuajada y el borde dorado.","Escurrir el arroz cocido.","Servir el arroz en plato junto a la salsa de tomate, el huevo frito y las rodajas de plátano macho."}', 'Arroz blanco con tomate frito, huevo frito y plátano', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_010', 'Pasta al pesto', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 478, 14, 54, 24, 2, true, true, '{"gluten","frutos_secos","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Albahaca fresca","amount":30,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano con un rallador fino y reservar.","Llevar una olla con agua abundante y sal a ebullición a fuego fuerte.","Cocer espaguetis en el agua hirviendo siguiendo el tiempo indicado en el envase, hasta que estén al dente.","Poner albahaca fresca, piñones, ajo, el queso parmesano rallado y aceite de oliva en el vaso de la batidora.","Triturar todos los ingredientes del vaso hasta obtener una pasta homogénea y reservar el pesto.","Reservar un cazo pequeño con agua de cocción de la olla antes de escurrir los espaguetis.","Escurrir los espaguetis y devolverlos a la olla a fuego suave.","Añadir el pesto reservado a la olla y mezclar bien con los espaguetis hasta que queden uniformemente cubiertos.","Añadir un chorrito del agua de cocción reservada y remover hasta que la salsa ligue y tenga textura cremosa.","Servir los espaguetis al pesto en platos hondos."}', 'Espaguetis con pesto casero de albahaca y piñones', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es ideal para esta receta. Primero, tritura los ingredientes del pesto en el vaso a velocidad progresiva durante unos segundos. Luego, sin limpiar el vaso, añade agua y sal, calienta y cocina los espaguetis según el tiempo indicado en el paquete."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_011', 'Arroz con verduras', 'pasta_arroces', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 368, 8, 58, 12, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Cortar judías verdes en trozos de 2-3 cm y zanahoria en dados pequeños.","Cortar pimiento rojo en dados pequeños.","Calentar aceite de oliva en una cazuela amplia a fuego medio.","Sofreír las judías verdes, la zanahoria y el pimiento rojo hasta que estén ligeramente tiernos, unos 5 min.","Añadir guisantes y remover para integrar con el resto de verduras.","Añadir tomate triturado y pimentón y sofreír hasta que el tomate pierda el agua, unos 2 min.","Añadir arroz y remover para que se impregne bien del sofrito durante 1 min.","Añadir 360 ml de agua caliente, llevar a ebullición a fuego fuerte y remover una sola vez.","Reducir a fuego suave, tapar la cazuela y cocer hasta que el arroz absorba todo el líquido, unos 16 min.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz con verduras directamente de la cazuela."}', 'Arroz seco con verduras de temporada al estilo paella', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de agua caliente. Cubre bien y hornea a 190°C durante 30-35 minutos, hasta que el arroz absorba el líquido y quede suelto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso y sofríelas con aceite. Incorpora el arroz, tomate, pimentón y el agua (aprox. el doble que de arroz). Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 20-25 minutos, hasta que el arroz esté cocido."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla abierta con aceite. Añade el arroz, tomate, pimentón y 1.5 veces su volumen de agua caliente. Cierra la olla y cocina a presión (posición 2) durante 5-7 minutos. Apaga el fuego y deja despresurizar sola."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_012', 'Espaguetis con gambas', 'pasta_arroces', 'marisco', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 438, 24, 56, 14, 2, true, true, '{"gluten","marisco"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Laminar ajo finamente y reservar.","Cortar guindilla en rodajas finas y reservar.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, unos 8 min.","Calentar sartén a fuego medio con aceite de oliva.","Sofreír el ajo laminado y la guindilla en rodajas hasta que el ajo esté dorado, unos 2 min.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, unos 2 min.","Verter vino blanco y remover a fuego fuerte hasta que se evapore el alcohol, unos 2 min.","Escurrir los espaguetis y añadirlos a la sartén.","Mezclar a fuego suave hasta que la pasta quede bien ligada con la salsa, 1 min.","Picar perejil fino y esparcir sobre la pasta antes de servir."}', 'Espaguetis salteados con gambas al ajillo y vino blanco', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina la pasta en el vaso con agua y sal. Luego, en el mismo vaso, sofríe el ajo y la guindilla, añade las gambas y el vino blanco para hacer la salsa, y finalmente mezcla todo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_013', 'Arroz negro', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 432, 20, 56, 14, 2, false, false, '{"moluscos","pescado"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Sepia","amount":200,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos finos.","Pelar y picar ajo en trozos finos.","Cortar sepia en trozos de bocado de unos 2 cm.","Disolver tinta de calamar en caldo de pescado removiendo hasta que se integre por completo. Reservar.","Calentar aceite de oliva en una paella o cazuela ancha a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado a fuego medio, removiendo, hasta que estén blandos y translúcidos.","Añadir la sepia troceada y saltear a fuego fuerte hasta que se dore ligeramente por fuera.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y el conjunto se concentre.","Incorporar arroz y remover durante 1 min hasta que los granos queden impregnados del sofrito.","Verter el caldo con la tinta reservado, repartir bien el arroz en una capa uniforme y llevar a ebullición.","Cocer a fuego medio-suave, sin remover, hasta que el arroz absorba el caldo y esté en su punto.","Retirar del fuego y dejar reposar tapado 2 min antes de servir.","Servir el arroz negro directamente desde la cazuela, repartiendo la sepia de forma uniforme entre los platos."}', 'Arroz teñido con tinta de calamar y sepia troceada', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Se prepara el sofrito con la sepia en una cazuela apta para horno. Se añade el arroz, la tinta y el caldo caliente, se lleva a ebullición y se hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido y quede en su punto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica cebolla y ajo, sofríe con aceite. Añade la sepia y tomate, luego el arroz, la tinta y el caldo, programando 20-22 minutos a 100°C, giro inverso y velocidad cuchara hasta que el arroz esté cocido y jugoso."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Se sofríen las verduras y la sepia en la olla. Se añade el arroz, la tinta y el caldo, se cierra la olla y se cocina a presión durante 7-8 minutos. Se despresuriza y se deja reposar unos minutos antes de servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_014', 'Pasta con salmón y champiñones', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 472, 24, 52, 18, 2, true, true, '{"gluten","lactosa","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Salmón","amount":200,"unit":"g"},{"name":"Champiñones","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Nata","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Laminar champiñones y reservar.","Picar cebolla en trozos finos y reservar.","Picar ajo fino y reservar.","Cortar salmón en dados de unos 2 cm y reservar.","Llevar a ebullición agua con sal en una olla a fuego fuerte.","Cocer macarrones en el agua hirviendo hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada y el ajo picado en la sartén hasta que estén tiernos y ligeramente dorados.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Añadir los dados de salmón y saltear a fuego medio hasta que estén sellados por fuera, unos 2 min.","Añadir nata y remover a fuego suave hasta que la salsa ligue y espese ligeramente.","Escurrir los macarrones y añadirlos a la sartén; remover hasta que se integren bien con la salsa.","Picar perejil y repartir sobre la pasta antes de servir."}', 'Pasta con salmón, champiñones y cebolla en una salsa suave y sedosa', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, el ajo y los champiñones en el vaso. Añade la pasta, el agua y la sal, cocinando el tiempo indicado en el paquete. Incorpora el salmón en dados y la nata, y mezcla a baja velocidad hasta integrar una salsa suave y sedosa. Termina con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_015', 'Arroz tres delicias', 'pasta_arroces', 'huevo', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 428, 16, 56, 14, 2, true, true, '{"huevo","soja"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Salsa de soja","amount":15,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición agua con sal en una olla a fuego fuerte.","Añadir arroz y cocer según el paquete hasta que esté tierno.","Pelar zanahoria y cortar en dados de 5 mm.","Cortar jamón cocido en dados de 5 mm.","Batir huevo en un bol con salsa de soja hasta que estén homogéneos.","Escurrir el arroz cocido y extender en una bandeja para que enfríe.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Añadir el huevo batido y cuajar sin remover hasta que esté hecho por dentro.","Retirar la tortilla de la sartén y cortar en dados de 5 mm. Reservar.","Subir el fuego a fuerte en la misma sartén. Saltear la zanahoria 2 min hasta que empiece a estar tierna.","Añadir guisantes y saltear junto a la zanahoria 1 min hasta que estén calientes.","Añadir el jamón cocido y saltear 1 min removiendo hasta que se integre con las verduras.","Añadir el arroz frío y saltear a fuego fuerte 2 min removiendo sin parar hasta que esté suelto.","Verter salsa de soja sobre el arroz y saltear 1 min removiendo hasta que tome color uniforme.","Añadir los dados de tortilla reservados y mezclar con suavidad hasta incorporarlos sin que se deshagan.","Servir de inmediato."}', 'Arroz salteado con tortilla, guisantes, zanahoria y jamón', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_016', 'Tallarines con pollo', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 472, 30, 54, 14, 2, true, true, '{"gluten","soja"}', '[{"name":"Tallarines","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Calabacín","amount":80,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras finas de 1 cm de grosor.","Cortar pimiento rojo en juliana fina.","Cortar calabacín en juliana fina.","Picar ajo muy fino.","Llevar a ebullición una olla grande con agua abundante y salsa de soja.","Añadir tallarines cuando el agua rompa a hervir y cocer hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Saltear las tiras de pechuga de pollo en sartén a fuego fuerte hasta que estén doradas por fuera y cocidas por dentro.","Añadir el pimiento rojo, el calabacín y el ajo picado a sartén.","Saltear las verduras a fuego fuerte hasta que estén tiernas pero con mordida.","Escurrir los tallarines al dente y reservar un poco del agua de cocción.","Incorporar los tallarines escurridos a sartén y añadir salsa de soja.","Saltear a fuego fuerte removiendo constantemente hasta que todo esté bien integrado.","Servir los tallarines con pollo directamente desde sartén al plato, bien calientes."}', 'Tallarines salteados con tiras de pollo y verduras', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo, pollo y verduras en el vaso. Añade los tallarines, agua (o caldo) y salsa de soja, y cocina a la temperatura y tiempo indicados para la pasta, usando la mariposa para remover."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_017', 'Lasaña de carne', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 562, 28, 42, 30, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Placas de lasaña","amount":120,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Bechamel","amount":200,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en dados finos.","Calentar aceite de oliva en una sartén grande a fuego medio.","Sofreír la cebolla picada en sartén hasta que esté transparente, unos 5 min a fuego medio.","Añadir carne picada de ternera y saltear a fuego fuerte hasta que pierda el color rosado por completo.","Añadir tomate triturado, remover y cocer a fuego suave hasta que la salsa reduzca y espese, unos 10 min.","Cocer placas de lasaña en una olla con agua hirviendo con sal el tiempo indicado en el envase; escurrir y reservar sobre un paño limpio.","Precalentar el horno a 190 °C con calor arriba y abajo.","Cubrir la base de una bandeja para horno con una capa fina de bechamel.","Disponer una capa de placas de lasaña sobre la bechamel, cubriendo toda la superficie sin solapar.","Extender la mitad de la boloñesa sobre las placas de lasaña de forma uniforme.","Verter una capa de bechamel sobre la boloñesa y alisar con una espátula.","Repetir el orden: placas de lasaña, el resto de la boloñesa y otra capa de bechamel.","Cubrir la superficie con el resto de la bechamel y esparcir queso rallado por encima de manera uniforme.","Hornear en el horno precalentado a 190 °C durante 25 min hasta que la superficie esté dorada y burbujeante.","Retirar la bandeja del horno y dejar reposar 5 min antes de cortar.","Cortar en porciones y servir directamente desde la bandeja."}', 'Lasaña de placas con ragú de ternera, bechamel y queso gratinado', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la carne y la bechamel por separado, monta la lasaña por capas en una fuente y hornea a 180-200°C durante 30-40 minutos hasta que el queso esté gratinado y burbujeante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Monta la lasaña en un molde pequeño apto para airfryer. Cocina a 170-180°C durante 25-30 minutos, vigilando que no se dore demasiado rápido y cubriendo si es necesario para un gratinado perfecto."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_018', 'Cannelones de carne', 'pasta_arroces', 'ternera', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'invierno', 538, 28, 38, 30, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Placas de cannelones","amount":100,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Bechamel","amount":250,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla muy fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, a fuego suave.","Añadir carne picada de ternera y sofreír a fuego medio hasta que pierda el color rosado, removiendo con frecuencia.","Incorporar tomate triturado y remover para integrar.","Cocer a fuego suave hasta que el relleno reduzca y espese.","Retirar el relleno del fuego y reservar.","Llevar a ebullición una olla con abundante agua con sal.","Precalentar el horno a 190 °C con calor arriba y abajo.","Cocer placas de cannelones según el tiempo indicado en el envase, removiendo ocasionalmente.","Escurrir las placas y extenderlas sobre un paño limpio hasta que se enfríen.","Disponer una porción del relleno en el borde de cada placa.","Enrollar cada placa con cuidado hasta formar los cannelones.","Verter una fina capa de bechamel en el fondo de una fuente apta para horno.","Colocar los cannelones sobre la bechamel, bien juntos y en una sola capa.","Cubrir los cannelones con el resto de la bechamel, repartiéndola de forma uniforme.","Espolvorear queso rallado sobre la bechamel.","Añadir nuez moscada por encima del queso.","Hornear a 190 °C durante 20 min, hasta que la superficie esté dorada y burbujeante.","Retirar la fuente del horno y dejar reposar 3 min antes de servir.","Servir los cannelones directamente de la fuente, bien calientes."}', 'Cannelones rellenos de carne con bechamel y queso gratinado', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara el relleno y la bechamel por separado. Monta los canelones en una fuente, cubre con bechamel y queso. Hornea a 180-200°C durante 20-25 minutos hasta que estén dorados y burbujeantes."},{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para picar y sofreír la cebolla con la carne, y para preparar una bechamel perfecta. Luego, rellena los canelones y gratínalos en el horno a 190°C durante 20-25 minutos."},{"appliance":"airfryer","time":60,"difficulty":"normal","prepSummary":"Una vez montados los canelones con su bechamel y queso (preparados aparte), gratínalos en la airfryer en pequeñas porciones. Precalienta a 180°C y cocina durante 15-20 minutos hasta que el queso esté fundido y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_019', 'Arroz caldoso con marisco', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 442, 24, 52, 14, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Almejas","amount":100,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"}]'::jsonb, '{"Picar ajo fino y cortar sepia en trozos pequeños.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo picado hasta que empiece a dorarse, sin que se queme.","Añadir la sepia troceada y saltear a fuego fuerte hasta que pierda el agua y tome color.","Añadir tomate triturado y sofreír a fuego medio hasta que reduzca y oscurezca.","Añadir arroz y remover sin parar durante 1 min para que se impregne del sofrito.","Calentar caldo de pescado en un cazo aparte hasta que rompa a hervir.","Verter el caldo caliente sobre el arroz, subir a fuego fuerte y llevar a ebullición.","Bajar a fuego medio y cocer el arroz sin tapar durante 10 min, removiendo de vez en cuando.","Añadir gambas y almejas y cocer a fuego medio hasta que las almejas se abran.","Retirar del fuego y reposar 2 min antes de servir para que el arroz asiente.","Servir el arroz caldoso directamente en la cazuela o en platos hondos."}', 'Arroz caldoso con gambas, almejas y sepia', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_020', 'Pasta con verduras salteadas', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 386, 12, 56, 12, 2, true, true, '{"gluten"}', '[{"name":"Penne","amount":200,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Berenjena","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Albahaca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar calabacín, pimiento rojo y berenjena en dados de 1 cm.","Laminar ajo finamente.","Llevar a ebullición una olla con abundante agua salada a fuego fuerte.","Cocer penne en el agua hirviendo hasta que estén al dente, según el tiempo del paquete.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear los dados de calabacín, pimiento rojo y berenjena a fuego fuerte hasta que se doren, removiendo con frecuencia.","Añadir el ajo laminado a la sartén y sofreír a fuego medio hasta que esté dorado, sin que se queme.","Escurrir la pasta cocida y añadirla a la sartén con las verduras.","Mezclar a fuego medio durante 1 min hasta que la pasta quede bien integrada con las verduras.","Añadir albahaca picada, remover y retirar del fuego.","Servir la pasta con verduras en platos hondos calientes."}', 'Penne con calabacín, berenjena y pimiento salteados', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo y las verduras con aceite en el vaso. Luego, añade el agua y la pasta, cocinando a la temperatura y tiempo indicados para la pasta, logrando un plato completo y sabroso sin esfuerzo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_021', 'Arroz a banda', 'pasta_arroces', 'pescado_blanco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 418, 18, 56, 12, 2, true, false, '{"pescado","marisco"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Rape","amount":100,"unit":"g"},{"name":"Gambas","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Pelar gambas, reservar las colas y apartar las cabezas para el caldo.","Limpiar rape y cortar en dados de unos 3 cm; reservar.","Picar ajo muy fino; reservar.","Verter caldo de pescado en un cazo, añadir las cabezas de las gambas reservadas y llevar a ebullición a fuego fuerte.","Cocer el caldo a fuego medio durante 5 min, colar y mantener caliente a fuego suave.","Calentar aceite de oliva en una paella o cazuela amplia a fuego medio.","Sofreír el ajo picado hasta que esté dorado, sin que se queme.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua y se concentre, unos 3 min.","Añadir pimentón y remover 20 segundos fuera del fuego para que no se queme.","Incorporar arroz y sofreír removiendo a fuego medio durante 1 min hasta que los granos estén nacarados.","Verter el caldo caliente colado en proporción 2,2:1 sobre el arroz y remover una sola vez para igualar.","Cocer a fuego fuerte los primeros 5 min sin tapar y sin remover.","Bajar a fuego suave y cocer 13 min más hasta que el arroz absorba todo el caldo.","Calentar una plancha a fuego fuerte y marcar los dados de rape 1 min por cada lado hasta que estén dorados.","Marcar las colas de gambas en la misma plancha a fuego fuerte durante 1 min hasta que estén rosadas.","Retirar el arroz del fuego y dejar reposar tapado 2 min.","Servir el arroz en un plato y el rape y las gambas marcadas aparte, al estilo tradicional."}', 'Arroz seco cocinado en caldo de pescado, servido aparte', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno. Añade el arroz y el caldo de pescado caliente. Cocina en el horno precalentado a 190°C durante 18-20 minutos, incorporando el rape y las gambas en los últimos 5-7 minutos para que no se sequen. El horno asegura una cocción uniforme."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe el ajo y el tomate en la Thermomix. Añade el arroz, pimentón y caldo, programando 18-20 minutos, 100°C, giro inverso, velocidad cuchara. Incorpora el rape y las gambas los últimos 5 minutos para una cocción perfecta y sin pegarse."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_022', 'Espaguetis al ajo y guindilla', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 396, 10, 56, 14, 2, false, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Llevar una olla grande con agua abundante y sal a ebullición a fuego fuerte.","Laminar ajo en rodajas finas y cortar guindilla en aros, retirando las semillas si se desea menos picante.","Añadir espaguetis al agua hirviendo y cocer según el tiempo del fabricante hasta que estén al dente.","Calentar aceite de oliva en sartén a fuego suave hasta que esté templado.","Añadir el ajo laminado y los aros de guindilla al aceite templado y sofreír a fuego suave hasta que el ajo esté dorado y fragante.","Reservar 1 cazo del agua de cocción antes de escurrir los espaguetis.","Escurrir los espaguetis y añadirlos a la sartén con el aceite, el ajo y la guindilla.","Añadir el agua de cocción reservada y saltear a fuego medio removiendo hasta que la salsa ligue y cubra la pasta.","Picar perejil fino y espolvorear sobre la pasta justo antes de servir."}', 'Espaguetis aglio e olio con ajo dorado y guindilla', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica el ajo y la guindilla, sofríelos con aceite en el vaso. Después, añade el agua y la sal, calienta y cocina los espaguetis al dente, integrando todo al finalizar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_023', 'Fideuá de pollo', 'pasta_arroces', 'pollo', 'pasta', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 462, 28, 52, 16, 2, true, false, '{"gluten"}', '[{"name":"Fideos n°2","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pollo","amount":400,"unit":"ml"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de bocado y salpimentar.","Cortar pimiento rojo en brunoise fina y picar ajo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Dorar el contramuslo troceado en la sartén caliente hasta que esté dorado por todos los lados; retirar y reservar.","Bajar a fuego medio y sofreír el pimiento rojo y el ajo en la misma sartén hasta que estén tiernos.","Añadir tomate triturado y pimentón al sofrito; remover y cocer hasta que el tomate pierda el agua y se concentre.","Incorporar fideos n°2 y tostar removiendo sin parar hasta que estén dorados de forma uniforme.","Verter caldo de pollo caliente y llevar a ebullición a fuego fuerte.","Incorporar el contramuslo reservado, repartir de forma uniforme y bajar a fuego medio.","Cocer sin tapar hasta que los fideos absorban el caldo y estén al dente y el pollo esté cocinado por completo.","Retirar del fuego y dejar reposar 2 min antes de servir.","Servir la fideuá directamente en la sartén o repartir en platos hondos."}', 'Fideos tostados con pollo y pimiento en caldo', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en una sartén apta para horno. Añadir los fideos y el caldo, llevar a ebullición y hornear a 200°C durante unos 15-20 minutos, hasta que los fideos absorban el líquido y se doren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en el vaso. Incorporar los fideos y el caldo, programar temperatura Varoma, giro inverso y velocidad cuchara durante el tiempo necesario para que la pasta absorba el líquido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_024', 'Ensalada de pasta mediterránea', 'pasta_arroces', 'none', 'pasta', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 408, 14, 46, 18, 2, true, true, '{"gluten","lactosa","frutos_secos","sulfitos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":120,"unit":"g"},{"name":"Mozzarella fresca","amount":100,"unit":"g"},{"name":"Rúcula","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Pesto","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Llevar a ebullición una olla con agua abundante y sal.","Cocer fusilli en el agua hirviendo hasta que estén al dente, siguiendo el tiempo del paquete.","Cortar tomate cherry por la mitad.","Cortar mozzarella fresca en dados de 1 cm.","Escurrir los fusilli y enfriar bajo agua fría hasta que estén a temperatura ambiente.","Añadir los tomates cherry, la mozzarella, rúcula, aceitunas negras y pesto a la pasta escurrida.","Mezclar todo con suavidad hasta que el pesto cubra bien la pasta y el resto de ingredientes.","Servir con aceite de oliva por encima."}', 'Ensalada fría de pasta con cherry, mozzarella, rúcula, aceitunas y pesto', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_025', 'Risotto de champiñones', 'pasta_arroces', 'none', 'arroz', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 428, 10, 56, 18, 2, true, false, '{"lactosa"}', '[{"name":"Arroz arborio","amount":180,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Cortar cebolla en dados pequeños.","Limpiar champiñones y laminar.","Rallar queso parmesano y reservar.","Calentar caldo de verduras en un cazo a fuego suave hasta que esté caliente; mantener a fuego mínimo.","Fundir mantequilla en una olla a fuego medio.","Sofreír la cebolla en la mantequilla fundida hasta que esté transparente.","Añadir los champiñones laminados y saltear a fuego fuerte hasta que pierdan el agua y se doren.","Añadir arroz arborio y sofreír, removiendo sin parar, hasta que los granos estén nacarados.","Verter vino blanco y remover hasta que el arroz lo absorba por completo.","Añadir el caldo caliente cucharón a cucharón, removiendo sin parar y esperando a que cada adición se absorba.","Retirar la olla del fuego cuando el arroz esté al dente y cremoso.","Añadir el queso parmesano rallado y remover con energía hasta integrar por completo.","Tapar la olla y dejar reposar 2 min para que el risotto asiente.","Servir el risotto en platos hondos inmediatamente."}', 'Risotto cremoso de champiñones con parmesano', '[{"appliance":"thermomix","time":28,"difficulty":"facil","prepSummary":"Sofríe la cebolla y los champiñones, luego tuesta el arroz con el vino. Incorpora el caldo y cocina 15-18 min a 100°C, velocidad cuchara, giro inverso, hasta obtener la cremosidad deseada, finalizando con mantequilla y parmesano."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pasta_arroces_026', 'Pasta rápida con tomate cherry, ajo y albahaca', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 440, 13, 68, 14, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Tomates cherry","amount":300,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Laminar ajo.","Cortar tomates cherry por la mitad.","Rallar queso parmesano.","Cocer espaguetis en el agua hirviendo hasta que estén al dente, según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo laminado a fuego medio hasta que se dore ligeramente, sin que se queme.","Añadir los tomates cherry a la sartén y saltear a fuego fuerte hasta que empiecen a reventar.","Retirar un cucharón del agua de cocción y añadirlo a la sartén con los tomates.","Escurrir los espaguetis al dente y añadirlos a la sartén.","Saltear todo junto a fuego fuerte durante 1 min hasta que la pasta absorba la salsa.","Añadir albahaca fresca troceada a mano y el queso parmesano rallado.","Servir enseguida con un chorrito de aceite de oliva por encima."}', 'Espaguetis con cherrys reventados en la sartén, ajo dorado y hoja fresca de albahaca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_027', 'Espaguetis al huevo y queso (carbonara exprés)', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 22, 66, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":180,"unit":"g"},{"name":"Huevo","amount":120,"unit":"g"},{"name":"Yema de huevo","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":50,"unit":"g"},{"name":"Bacon en taquitos","amount":80,"unit":"g"},{"name":"Pimienta negra","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Rallar queso parmesano finamente.","Batir huevo y yema de huevo en un bol hasta homogeneizar.","Añadir el queso parmesano rallado y pimienta negra a la mezcla de huevo y batir hasta obtener una crema lisa.","Cocer espaguetis en el agua hirviendo el tiempo indicado en el envase.","Dorar bacon en taquitos en sartén a fuego medio sin aceite hasta que quede crujiente.","Reservar un cucharón del agua de cocción antes de escurrir la pasta.","Escurrir los espaguetis y añadirlos a la sartén con el bacon, fuera del fuego.","Verter la crema de huevo y queso sobre los espaguetis calientes y remover sin parar fuera del fuego hasta que ligue y quede cremosa.","Añadir un poco del agua de cocción reservada si la salsa ha espesado demasiado, removiendo hasta conseguir una textura sedosa.","Servir enseguida con más pimienta negra y queso parmesano rallado por encima."}', 'Espaguetis cremosos con huevo y queso, sin nata, listos en el tiempo de cocción de la pasta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_028', 'Pasta con pesto de bote y tomates cherry', 'pasta_arroces', 'none', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 480, 14, 64, 18, 2, true, true, '{"gluten","frutos_secos","lactosa"}', '[{"name":"Fusilli","amount":180,"unit":"g"},{"name":"Pesto de albahaca","amount":80,"unit":"g"},{"name":"Tomates cherry","amount":150,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Piñones","amount":15,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Lavar tomates cherry y cortar cada uno por la mitad.","Calentar sartén a fuego medio sin aceite y tostar piñones removiendo hasta que estén dorados.","Cocer fusilli en el agua hirviendo el tiempo indicado en el envase.","Reservar un cucharón del agua de cocción antes de escurrir la pasta.","Escurrir los fusilli y volcarlos de nuevo en la olla fuera del fuego.","Añadir pesto de albahaca y un poco del agua de cocción reservada, removiendo hasta cubrir uniformemente la pasta.","Incorporar los tomates cherry cortados y remover con suavidad para no aplastarlos.","Rallar queso parmesano sobre cada ración y repartir los piñones tostados por encima."}', 'Pasta verde vivo con pesto de bote y toques rojos de tomate cherry, del tarro a la mesa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_029', 'Pasta con atún, tomate y aceitunas exprés', 'pasta_arroces', 'pescado_azul', 'pasta', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 470, 26, 62, 14, 2, true, true, '{"gluten","pescado"}', '[{"name":"Macarrones","amount":180,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Aceitunas negras","amount":50,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Llevar a ebullición una olla grande con agua abundante y sal.","Pelar y picar ajo fino.","Añadir macarrones al agua hirviendo y cocer según el tiempo del envase.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el ajo picado hasta que empiece a dorar sin que se queme.","Añadir tomate triturado y cocer a fuego medio hasta que espese ligeramente.","Escurrir atún en conserva y añadirlo a la sartén.","Añadir aceitunas negras y remover para integrar todos los ingredientes.","Cocer 2 min a fuego suave hasta que los sabores se integren.","Escurrir los macarrones cocidos y añadirlos a la sartén.","Mezclar bien hasta que la salsa cubra todos los macarrones.","Servir caliente en platos hondos."}', 'Pasta con atún, tomate y aceitunas, de la despensa a la mesa en un cuarto de hora.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pasta_arroces_030', 'Risotto de setas y trufa negra', 'pasta_arroces', 'none', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 560, 14, 74, 20, 2, true, true, '{"lactosa"}', '[{"name":"Arroz arborio","amount":160,"unit":"g"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Caldo de verduras","amount":700,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Trufa negra","amount":8,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Limpiar setas variadas y laminar.","Rallar queso parmesano y reservar.","Laminar trufa negra muy fina y reservar.","Llevar caldo de verduras a ebullición en una olla, luego bajar a fuego suave para mantenerlo caliente.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir las setas laminadas y saltear hasta que suelten el agua y se doren ligeramente.","Añadir arroz arborio y remover hasta que los granos queden translúcidos por fuera.","Añadir vino blanco y remover hasta que el alcohol se evapore por completo.","Añadir un cucharón de caldo caliente y remover sin parar hasta que se absorba por completo.","Repetir el proceso, añadiendo el caldo cucharón a cucharón y removiendo sin parar, hasta que el arroz esté cremoso y al dente.","Salpimentar con sal al final de la cocción.","Retirar la cazuela del fuego y añadir mantequilla fría cortada en dados.","Añadir el queso parmesano rallado y mezclar con movimientos envolventes hasta obtener una textura cremosa.","Tapar la cazuela y dejar reposar.","Servir el risotto en platos hondos y disponer las láminas de trufa negra por encima."}', 'Risotto cremoso de setas con láminas de trufa negra recién cortadas por encima.', NULL, '{}', true, NULL, NULL, '{"seta"}', NULL),
