insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_026', 'Tosta de aguacate, huevo poché y salmón ahumado', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 430, 22, 32, 24, 2, true, false, '{"gluten","huevo","pescado"}', '[{"name":"Pan de masa madre","amount":4,"unit":"ud"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Salmón ahumado","amount":100,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en un cazo ancho con vinagre a fuego medio.","Tostar pan de masa madre en una tostadora o sartén hasta que estén doradas y crujientes.","Cortar aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Machacar la pulpa de aguacate con un tenedor hasta obtener una crema rústica.","Añadir zumo de limón, sal y pimienta negra al aguacate machacado y mezclar.","Cascar huevo uno a uno en una taza pequeña para verterlos con control.","Bajar el fuego a suave cuando el agua rompa a hervir, hasta que quede a punto de ebullición suave.","Remover el agua con una cuchara para crear un remolino y verter un huevo en el centro con cuidado.","Cocer el huevo poché hasta que la clara esté cuajada y la yema blanda, unos 3 min.","Retirar el huevo poché con una espumadera y escurrir sobre papel absorbente.","Repetir el proceso con el segundo huevo en el mismo cazo.","Untar cada rebanada de pan tostado con el aguacate machacado de forma generosa.","Repartir salmón ahumado en láminas sobre el aguacate de cada tosta.","Colocar un huevo poché encima de cada tosta con cuidado para no romper la yema.","Terminar con eneldo fresco picado, un hilo de aceite de oliva virgen extra y pimienta negra al gusto."}', 'Tosta crujiente con aguacate machacado, huevo poché y salmón ahumado, un desayuno o cena rápida y resultona.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Tuesta el pan a 180-200°C por 5-7 minutos. Para el huevo poché, coloca cada huevo en un ramequín con un poco de agua y cocina en la airfryer a 160°C durante 8-10 minutos hasta que la clara esté cuajada y la yema líquida."},{"appliance":"thermomix","time":17,"difficulty":"facil","prepSummary":"Prepara los huevos poché en el recipiente Varoma durante 10-12 minutos a temperatura Varoma, velocidad cuchara. Utiliza el vaso para triturar el aguacate con el limón, sal y pimienta. El pan se tostaría aparte en una tostadora o sartén."},{"appliance":"vaporera","time":17,"difficulty":"facil","prepSummary":"Para los huevos poché, coloca cada huevo en un ramequín ligeramente engrasado y cocina en la vaporera durante 8-12 minutos, hasta que la clara esté firme y la yema a tu gusto. El pan se tostaría aparte en una tostadora o sartén."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_027', 'Poke bowl de salmón, aguacate y edamame', 'pescados', 'pescado_azul', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 640, 32, 65, 26, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Arroz sushi","amount":160,"unit":"g"},{"name":"Salmón fresco para sushi","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Edamame desvainado","amount":100,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Vinagre de arroz","amount":15,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":6,"unit":"g"},{"name":"Alga nori","amount":2,"unit":"g"}]'::jsonb, '{"Lavar arroz sushi bajo el grifo hasta que el agua salga clara.","Cocer el arroz en un cazo con el doble de agua fría; llevar a ebullición a fuego fuerte.","Tapar el cazo, bajar a fuego suave y cocer hasta que el arroz absorba toda el agua.","Laminar aguacate en láminas finas.","Rallar zanahoria o cortar en bastones finos.","Cortar pepino en bastones finos.","Cortar salmón fresco para sushi en dados de bocado de unos 2 cm.","Hervir edamame desvainado en agua con sal durante 3 min y escurrir.","Retirar el cazo del fuego y dejar reposar el arroz tapado 5 min.","Extender el arroz en una fuente y aliñar con vinagre de arroz; mezclar con suavidad.","Dejar templar el arroz extendido hasta que pierda el exceso de calor.","Mezclar salsa de soja con aceite de sésamo en un cuenco pequeño.","Repartir el arroz templado en 2 boles.","Disponer el salmón, el aguacate, el edamame, la zanahoria y el pepino en montones sobre el arroz.","Aliñar cada bol con la mezcla de salsa de soja y aceite de sésamo.","Espolvorear semillas de sésamo y cortar alga nori en tiras finas para terminar."}', 'Bowl fresco de arroz templado con salmón, aguacate y edamame en bloques de color, listo en minutos.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz de sushi en el cestillo o Varoma (aprox. 20-25 min) y cuece el edamame al vapor en el Varoma (aprox. 15 min), pudiendo solaparse. La Thermomix también puede mezclar la salsa para el aliño, facilitando la preparación."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Prepara el arroz de sushi en el recipiente adecuado de la vaporera (aprox. 25-30 min) y cocina el edamame al vapor (aprox. 15 min), pudiendo solaparse. Es un método ideal para una cocción saludable y perfecta de ambos ingredientes."},{"appliance":"olla_express","time":22,"difficulty":"normal","prepSummary":"Cocina el arroz de sushi en la olla a presión (aprox. 5-7 min de cocción + 15 min de reposo natural), lo que acelera el proceso. El edamame también se puede cocer al vapor rápidamente en un cestillo (aprox. 2-3 min)."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_028', 'Tosta de salmón ahumado, queso crema y eneldo', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'all', 410, 18, 26, 25, 2, true, false, '{"gluten","lactosa","pescado"}', '[{"name":"Pan de centeno","amount":4,"unit":"ud"},{"name":"Queso crema","amount":100,"unit":"g"},{"name":"Salmón ahumado","amount":120,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Tostar pan de centeno en una tostadora o sartén seca a fuego medio hasta que estén crujientes.","Mezclar queso crema con zumo de limón y pimienta negra hasta obtener una crema homogénea.","Picar eneldo fresco fino.","Untar cada tosta con la crema de queso de forma generosa.","Disponer salmón ahumado en láminas onduladas sobre el queso crema.","Repartir alcaparras por encima del salmón.","Espolvorear el eneldo picado y servir enseguida."}', 'Tosta de pan de centeno con queso crema, salmón ahumado y eneldo fresco, lista en menos de diez minutos.', '[{"appliance":"airfryer","time":7,"difficulty":"facil","prepSummary":"Para tostar el pan, coloca las rebanadas en la airfryer a 180°C durante 4-5 minutos hasta que estén doradas. Luego, unta el queso crema y añade el salmón, eneldo, limón y alcaparras."},{"appliance":"horno","time":9,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C y tuesta el pan de centeno durante 5-7 minutos hasta que esté crujiente. Retira, unta el queso crema y decora con el salmón, eneldo, zumo de limón y alcaparras."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_029', 'Bowl de arroz, atún y aguacate al estilo hawaiano', 'pescados', 'pescado_azul', 'arroz', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 560, 30, 68, 18, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Arroz blanco","amount":160,"unit":"g"},{"name":"Atún fresco para sushi","amount":220,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Mango","amount":100,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Salsa de soja","amount":25,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":6,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"}]'::jsonb, '{"Cocer arroz blanco en abundante agua con sal según el paquete.","Exprimir lima y reservar el zumo.","Cortar atún fresco para sushi en dados regulares de unos 2 cm.","Cortar aguacate en dados del mismo tamaño que el atún.","Cortar mango en dados del mismo tamaño que el aguacate.","Laminar cebolleta en aros finos.","Escurrir el arroz cocido y dejar templar 3 min fuera del fuego.","Mezclar salsa de soja, aceite de sésamo y el zumo de lima en un bol pequeño.","Repartir el arroz templado en 2 boles como base.","Disponer el atún, el aguacate y el mango en montones separados sobre el arroz.","Repartir la cebolleta laminada y semillas de sésamo por encima.","Rociar con la mezcla de salsa de soja, aceite de sésamo y zumo de lima al gusto."}', 'Bowl al estilo hawaiano con arroz templado, atún fresco, aguacate y mango en dados de colores.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz en el cestillo con agua y sal (20 min/Varoma/vel 4). Mientras, pica la cebolleta y mezcla los ingredientes de la salsa y el atún marinado para montar el bowl."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Prepara el arroz blanco en la vaporera siguiendo las instrucciones para un arroz suelto y aromático (aprox. 25 min). Mientras, corta el resto de ingredientes y prepara la marinada del atún."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Cocina el arroz en la olla express con la proporción adecuada de agua (5-7 min a presión, luego despresuriza). Esto asegura un arroz rápido y perfecto para el bowl mientras preparas los demás ingredientes."},{"appliance":"microondas","time":18,"difficulty":"facil","prepSummary":"Cocina el arroz en un recipiente apto para microondas con la proporción de agua y sal (aprox. 18 min a máxima potencia). El resto de la preparación es montar el bowl con los ingredientes frescos y la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_030', 'Tortilla wrap de atún y maíz', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 470, 23, 40, 22, 2, true, false, '{"gluten","pescado","huevo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Atún en conserva escurrido","amount":160,"unit":"g"},{"name":"Maíz dulce","amount":80,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Lechuga","amount":40,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"}]'::jsonb, '{"Escurrir atún en conserva escurrido y desmigarlo en un bol.","Cortar tomate en dados pequeños.","Laminar cebolla morada en tiras finas.","Añadir maíz dulce y mayonesa al bol con el atún y mezclar hasta integrar.","Calentar tortilla de trigo en sartén a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir lechuga sobre cada tortilla caliente.","Distribuir la mezcla de atún y maíz sobre la lechuga de cada tortilla.","Añadir el tomate en dados y la cebolla morada laminada sobre cada tortilla.","Enrollar cada tortilla apretando bien y cortar por la mitad en diagonal para servir."}', 'Wrap relleno de atún, maíz dulce y mayonesa, enrollado y cortado en rodajas para llevar.', '[{"appliance":"airfryer","time":7,"difficulty":"facil","prepSummary":"Para un toque crujiente, precalienta la airfryer a 180°C y calienta las tortillas 1-2 minutos antes de rellenar, o el wrap ya montado durante 3-5 minutos para dorarlo ligeramente."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Para calentar las tortillas y hacerlas más flexibles, precalienta el horno a 180°C y caliéntalas envueltas en papel de aluminio durante 5-7 minutos. También puedes tostar el wrap montado unos minutos para un exterior crujiente."},{"appliance":"microondas","time":2,"difficulty":"facil","prepSummary":"Para ablandar las tortillas y que sean más fáciles de enrollar, envuélvelas en papel de cocina húmedo y caliéntalas en el microondas durante 30-60 segundos a máxima potencia."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('pescados_031', 'Tosta de tomate rallado, anchoas y aceite', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 8, 'facil', 'verano', 420, 13, 46, 15, 2, false, false, '{"gluten","pescado"}', '[{"name":"Pan de payés","amount":4,"unit":"ud"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Anchoas en aceite","amount":60,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Tostar pan de payés en una tostadora o sartén a fuego medio hasta que estén crujientes.","Rallar tomate maduro por el lado del corte hasta desechar la piel.","Frotar ajo pelado sobre cada tostada caliente.","Repartir la pulpa de tomate rallado sobre las tostadas.","Escurrir anchoas en aceite y colocar 2-3 filetes sobre cada tosta.","Rociar aceite de oliva virgen extra sobre cada tosta y añadir sal."}', 'El clásico pan con tomate rallado coronado con filetes de anchoa y un buen aceite de oliva.', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tuesta el pan en la airfryer a 180-200°C durante 3-5 minutos, hasta que esté dorado y crujiente. Mientras tanto, ralla el tomate y pica el ajo para el montaje final."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (preferiblemente con función grill). Tuesta el pan durante 5-8 minutos, vigilando que quede bien dorado y crujiente. Prepara el resto de ingredientes mientras el pan se hornea."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('pescados_032', 'Salmón a la plancha con ensalada de aguacate, pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'normal', 'all', 510, 34, 8, 38, 2, true, false, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Eneldo fresco","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Retirar lomos de salmón de la nevera y dejar atemperar 10 min antes de cocinar.","Cortar aguacate en dados pequeños.","Cortar pepino en dados pequeños.","Picar eneldo fresco fino.","Mezclar el aguacate y el pepino con la mitad del eneldo picado, zumo de limón, sal y aceite de oliva virgen extra.","Salpimentar pimienta negra los lomos de salmón por ambas caras.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva virgen extra sobre la plancha y colocar los lomos de salmón con la piel hacia abajo.","Cocinar los lomos por el lado de la piel 4 min hasta que la piel esté crujiente y dorada.","Dar la vuelta a los lomos y cocinar 2 min más hasta que estén al punto deseado.","Repartir la ensalada de aguacate y pepino en los platos.","Colocar los lomos de salmón sobre la ensalada, añadir el resto del eneldo picado y un hilo de aceite de oliva virgen extra."}', 'Salmón a la plancha con la piel crujiente, acompañado de una ensalada fresca de aguacate, pepino y eneldo.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina el salmón sazonado durante 12-15 minutos, dándole la vuelta a mitad, para un exterior crujiente y un interior jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Hornea el salmón sazonado sobre papel de horno durante 15-18 minutos hasta que esté tierno y cocido, manteniendo su jugosidad."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina el salmón sazonado en el recipiente Varoma durante 15-18 minutos a temperatura Varoma, para un resultado muy jugoso y saludable."},{"appliance":"vaporera","time":18,"difficulty":"facil","prepSummary":"Coloca el salmón sazonado en la cesta de la vaporera y cocina al vapor durante 12-15 minutos para obtener una textura tierna y jugosa, ideal para una comida ligera."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_033', 'Atún a la plancha con ensalada de tomate, aguacate y cebolla morada', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 18, 'normal', 'verano', 440, 34, 10, 26, 2, false, false, '{"pescado","sulfitos"}', '[{"name":"Lomo de atún fresco","amount":300,"unit":"g"},{"name":"Tomate","amount":200,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Retirar lomo de atún fresco de la nevera para que atempere.","Cortar tomate en dados medianos.","Cortar aguacate en dados medianos.","Laminar cebolla morada en tiras muy finas.","Mezclar el tomate, el aguacate y la cebolla morada en un bol.","Añadir vinagre de jerez, sal y la mitad de aceite de oliva virgen extra. Remover con suavidad.","Salpimentar el lomo de atún por todas sus caras con sal y pimienta negra.","Calentar plancha a fuego fuerte con un chorrito del aceite de oliva virgen extra hasta que humee.","Sellar el lomo de atún 1 min por cada lado hasta que el exterior esté dorado y el centro quede rosado.","Retirar el atún de la plancha y dejar reposar.","Cortar el lomo de atún en rodajas gruesas.","Repartir la ensalada de tomate, aguacate y cebolla morada en los platos.","Colocar las rodajas de atún sobre la ensalada y terminar con el resto del aceite de oliva virgen extra."}', 'Atún sellado por fuera y rosado por dentro junto a una ensalada vistosa de tomate, aguacate y cebolla morada.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para el atún, precalienta la airfryer a 200°C. Cocina el lomo de atún previamente salpimentado y aceitado durante 8-10 minutos, dándole la vuelta a mitad, para un exterior sellado y un interior jugoso."},{"appliance":"horno","time":20,"difficulty":"normal","prepSummary":"Precalienta el horno a 220°C. Coloca el lomo de atún en una bandeja con un poco de aceite y hornea durante 10-12 minutos, asegurando que quede cocido pero sin resecarse, para una textura tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_034', 'Gambas salteadas al ajo con ensalada de aguacate y tomate cherry', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 390, 25, 9, 24, 2, true, false, '{"marisco"}', '[{"name":"Gambas peladas","amount":300,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Tomates cherry","amount":150,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar aguacate en dados de unos 2 cm.","Cortar tomates cherry por la mitad.","Mezclar el aguacate y los tomates cherry con zumo de limón, sal y aceite de oliva virgen extra.","Reservar la ensalada a temperatura ambiente.","Picar ajo muy fino.","Picar perejil fino.","Secar gambas peladas con papel absorbente para que no suelten agua al saltear.","Calentar el aceite de oliva virgen extra restante en sartén a fuego fuerte hasta que humee ligeramente.","Sofreír el ajo picado 30 segundos, removiendo sin parar, hasta que esté dorado pero sin quemarse.","Añadir las gambas peladas en una sola capa.","Saltear las gambas a fuego fuerte, sin remover, hasta que estén rosadas por un lado (1 min).","Dar la vuelta a las gambas y saltear 1 min más hasta que estén firmes y rosadas por completo.","Espolvorear el perejil picado sobre las gambas y añadir sal al gusto.","Servir las gambas recién salteadas junto a la ensalada de aguacate y tomates cherry."}', 'Gambas doradas salteadas al ajo servidas junto a una ensalada fresca de aguacate y tomate cherry.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para las gambas, marínalas con ajo, aceite y sal. Cocínalas en la airfryer a 200°C durante 8-10 minutos, agitándolas a mitad de cocción para un dorado uniforme. La clave es no sobrecocerlas para mantenerlas jugosas."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Extiende las gambas marinadas con ajo, aceite y sal en una bandeja de horno. Hornea a 220°C (con función grill si es posible) durante 8-10 minutos hasta que estén rosadas. Un truco es precalentar bien la bandeja para un mejor sellado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_035', 'Salteado de langostinos con ensalada de aguacate, pomelo y menta', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 380, 23, 15, 21, 2, true, false, '{"marisco"}', '[{"name":"Langostinos pelados","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pomelo","amount":200,"unit":"g"},{"name":"Menta fresca","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de lima","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar pomelo a vivo sobre un bol para recoger el jugo que suelte.","Separar los gajos de pomelo y reservar junto con el jugo.","Picar menta fresca finamente.","Cortar aguacate en dados.","Mezclar en un bol los gajos de pomelo, el aguacate y la menta picada.","Añadir zumo de lima, sal y la mitad de aceite de oliva virgen extra. Remover con cuidado.","Secar langostinos pelados con papel absorbente hasta que estén bien secos.","Calentar el resto del aceite de oliva virgen extra en sartén a fuego fuerte.","Saltear los langostinos 2 min por cada lado hasta que estén dorados y firmes.","Salpimentar los langostinos con sal y pimienta negra al retirar del fuego.","Repartir la ensalada de pomelo y aguacate en los platos.","Colocar los langostinos encima de la ensalada y servir de inmediato."}', 'Langostinos salteados y dorados junto a una ensalada cítrica de aguacate, pomelo y menta.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cocina los langostinos con un chorrito de aceite a 190°C durante 8-10 minutos, agitándolos a mitad para un dorado uniforme. Mientras, prepara la ensalada fresca de aguacate, pomelo y menta."},{"appliance":"horno","time":20,"difficulty":"normal","prepSummary":"Asa los langostinos en una bandeja con un poco de aceite a 200°C (con función ventilador si es posible) durante 10-12 minutos, hasta que estén rosados y ligeramente dorados. Aprovecha el tiempo para montar la ensalada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_036', 'Lubina entera a la sal con hierbas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 55, 'normal', 'all', 300, 42, 1, 12, 2, true, false, '{"pescado","huevo"}', '[{"name":"Lubina entera limpia","amount":800,"unit":"g"},{"name":"Sal gruesa","amount":1500,"unit":"g"},{"name":"Clara de huevo","amount":2,"unit":"ud"},{"name":"Romero fresco","amount":10,"unit":"g"},{"name":"Tomillo fresco","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo.","Cortar limón en rodajas finas.","Rellenar la cavidad de lubina entera limpia con romero fresco, tomillo fresco y las rodajas de limón.","Mezclar sal gruesa con clara de huevo en un bol hasta obtener una textura de arena húmeda.","Extender una capa de la mezcla de sal en la base de una bandeja de horno del tamaño de la lubina.","Colocar la lubina rellena encima de la capa de sal.","Cubrir la lubina por completo con el resto de la mezcla de sal, presionando bien para sellarla sin dejar huecos.","Hornear la bandeja en el centro del horno hasta que la costra esté firme y ligeramente dorada.","Retirar la bandeja del horno y dejar reposar 3 min antes de romper la costra.","Romper la costra de sal golpeando suavemente con el dorso de una cuchara por todo el contorno.","Retirar los trozos de costra con cuidado, evitando que caiga sal sobre la carne.","Retirar la piel de la lubina y separar los lomos limpios de espinas con una espátula.","Servir los lomos en los platos y aliñar con aceite de oliva virgen extra."}', 'Lubina entera horneada bajo una costra de sal y hierbas, que se rompe en la mesa liberando todo el aroma.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C. Cubre la lubina con la mezcla de sal gruesa y claras, y hornea durante 55 minutos hasta que la costra esté dura y dorada, cocinándose en su propio jugo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_037', 'Rodaballo a la plancha con salsa de marisco', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 430, 38, 6, 26, 2, true, false, '{"pescado","marisco","lactosa","sulfitos"}', '[{"name":"Lomos de rodaballo","amount":350,"unit":"g"},{"name":"Gambas peladas","amount":100,"unit":"g"},{"name":"Chalota","amount":40,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Fumet de pescado","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Picar chalota muy fina.","Salpimentar lomos de rodaballo con sal y pimienta negra por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte hasta que humee ligeramente.","Colocar los lomos de rodaballo en plancha y cocinar 3 min por cada lado hasta que estén dorados.","Retirar los lomos de rodaballo de plancha y reservar en un plato caliente.","Fundir mantequilla en la misma sartén a fuego medio.","Sofreír la chalota picada a fuego suave hasta que esté transparente, unos 3 min.","Añadir gambas peladas y saltear a fuego fuerte hasta que estén rosadas, 1 min.","Verter vino blanco y dejar reducir a fuego fuerte hasta que se evapore a la mitad, unos 2 min.","Añadir fumet de pescado y nata para cocinar y remover para mezclar.","Cocer a fuego suave hasta que la salsa espese ligeramente, unos 5 min, removiendo de vez en cuando.","Retirar la mitad de la salsa con parte de las gambas y triturar hasta obtener una crema homogénea.","Verter la crema triturada de nuevo en la sartén y mezclar con el resto de la salsa a fuego suave 1 min.","Disponer los lomos de rodaballo reservados en el plato y salsear generosamente con la salsa de marisco."}', 'Rodaballo a la plancha napado con una cremosa salsa de marisco con trocitos de gamba.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_038', 'Tartar de atún rojo con aguacate y sésamo', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 20, 'normal', 'all', 370, 28, 6, 20, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Atún rojo fresco de calidad sashimi","amount":250,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":8,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar atún rojo fresco de calidad sashimi en dados pequeños y uniformes con un cuchillo bien afilado.","Cortar aguacate en dados del mismo tamaño que el atún.","Picar cebolleta muy fina.","Rallar jengibre fresco hasta obtener una pasta fina.","Exprimir lima y reservar el zumo; rallar la piel y reservar la ralladura por separado.","Mezclar en un bol el atún dados, la cebolleta picada, el jengibre rallado, salsa de soja y aceite de sésamo.","Añadir sal y remover con suavidad hasta integrar.","Tapar el bol y dejar marinar en la nevera hasta que el atún absorba los aromas.","Añadir el aguacate en dados sobre el atún marinado y mezclar con suavidad para no aplastarlo.","Colocar un aro de emplatar sobre el plato y rellenar con la mezcla, presionando ligeramente para compactar.","Retirar el aro con cuidado y terminar con semillas de sésamo, el zumo y la ralladura de lima reservados."}', 'Tartar de atún rojo fresco con aguacate en dados y un toque de sésamo tostado.', '[{"appliance":"thermomix","time":15,"difficulty":"normal","prepSummary":"Utiliza la función de picado a pulsos para el atún y el resto de ingredientes, asegurando una textura homogénea sin triturar. Mezcla suavemente en el vaso para integrar los sabores y emulsionar la vinagreta."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_039', 'Ceviche de corvina con leche de tigre', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'verano', 220, 30, 18, 3, 2, false, false, '{"pescado","apio"}', '[{"name":"Corvina fresca","amount":300,"unit":"g"},{"name":"Lima","amount":4,"unit":"ud"},{"name":"Cebolla morada","amount":60,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Ají amarillo o guindilla fresca","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Apio","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Maíz tostado","amount":40,"unit":"g"}]'::jsonb, '{"Cortar corvina fresca en dados de unos 2 cm y reservar en la nevera.","Cortar cebolla morada en juliana fina y sumergir en agua fría.","Dejar reposar la cebolla morada en agua fría 5 min para suavizar su sabor.","Exprimir lima y verter el zumo en el vaso de la batidora.","Cortar apio en trozos y añadir al vaso junto al zumo de lima.","Rallar jengibre fresco e incorporar al vaso.","Picar ají amarillo o guindilla fresca e incorporar al vaso.","Añadir sal al vaso y triturar todo hasta obtener una mezcla homogénea.","Colar la leche de tigre por un colador fino y reservar el líquido resultante.","Escurrir la cebolla morada y secarla ligeramente con papel de cocina.","Picar cilantro fresco fino y reservar.","Mezclar la corvina con la cebolla morada escurrida en un bol frío.","Verter la leche de tigre sobre la corvina y remover con cuidado para cubrir todos los dados.","Dejar marinar 4 min sin remover para que el pescado quede firme pero jugoso.","Añadir el cilantro picado y remover con suavidad.","Servir de inmediato en platos fríos con maíz tostado por encima."}', 'Ceviche de corvina marinada en una intensa leche de tigre con lima, cilantro y ají.', '[{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Utiliza la Thermomix para picar finamente la cebolla, el cilantro, el ají, el jengibre y el apio. Luego, mezcla estos ingredientes con el zumo de lima y la sal para crear la leche de tigre en pocos segundos. Finalmente, incorpora la corvina cortada y deja marinar."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_040', 'Vieiras con puré de guisantes y panceta', 'pescados', 'marisco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 380, 26, 15, 22, 2, true, false, '{"moluscos","lactosa"}', '[{"name":"Vieiras limpias","amount":6,"unit":"ud"},{"name":"Guisantes","amount":250,"unit":"g"},{"name":"Panceta ahumada en lonchas finas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":80,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Hervir agua con sal en un cazo a fuego fuerte.","Cocer guisantes en el agua hirviendo hasta que estén tiernos.","Escurrir los guisantes y triturarlos con caldo de verduras, mantequilla y menta fresca hasta obtener un puré fino.","Colar el puré por un colador fino hasta que esté sedoso.","Salpimentar el puré con pimienta negra y reservar caliente tapado.","Cortar panceta ahumada en lonchas finas en tiras.","Dorar las tiras de panceta en sartén sin aceite a fuego medio hasta que estén crujientes.","Retirar la panceta y reservar sobre papel absorbente.","Secar vieiras limpias con papel absorbente.","Salpimentar las vieiras por ambas caras con sal y pimienta negra.","Calentar aceite de oliva en la misma sartén a fuego fuerte hasta que humee.","Marcar las vieiras 90 segundos por el primer lado sin moverlas hasta que estén doradas.","Dar la vuelta a las vieiras y marcar 90 segundos por el otro lado hasta que estén jugosas por dentro.","Repartir el puré de guisantes en la base de los platos.","Colocar las vieiras encima del puré y terminar con la panceta crujiente."}', 'Vieiras doradas a la plancha sobre un puré sedoso de guisantes con panceta crujiente.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"La airfryer es ideal para la panceta crujiente y las vieiras doradas. Los guisantes se cocinan aparte (microondas o vaporera) y se trituran para el puré, logrando un plato completo y delicioso."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_041', 'Merluza a la vasca con kokotxas y almejas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 45, 'elaborada', 'all', 430, 40, 8, 22, 2, false, false, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Merluza en trozos","amount":300,"unit":"g"},{"name":"Kokotxas de merluza","amount":150,"unit":"g"},{"name":"Almejas","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de pescado","amount":150,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Sumergir almejas en agua fría con sal durante 30 min para que suelten la arena.","Picar ajo fino.","Picar perejil fino y reservar.","Salpimentar merluza en trozos y kokotxas de merluza con sal y reservar.","Escurrir las almejas y reservar.","Calentar aceite de oliva virgen extra en una cazuela a fuego suave hasta que esté caliente.","Sofreír el ajo picado a fuego suave hasta que se dore ligeramente, sin que se queme.","Añadir harina y remover sin parar durante 1 min hasta que quede integrada sin coger color.","Verter vino blanco y remover hasta que el alcohol evapore, unos 2 min a fuego medio.","Añadir caldo de pescado y mover la cazuela en círculos hasta que la salsa ligue, 2 min a fuego suave.","Incorporar la merluza en trozos y cocer a fuego suave durante 4 min, moviendo la cazuela con suavidad.","Añadir las kokotxas de merluza y las almejas escurridas.","Cocer a fuego suave 5 min, moviendo la cazuela, hasta que las almejas se abran y la salsa ligue.","Espolvorear con el perejil picado y servir en la misma cazuela."}', 'Merluza guisada en salsa verde con kokotxas y almejas, un clásico vasco con conchas abiertas en la mesa.', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Sofríe el ajo y perejil, añade el vino y el caldo. Incorpora la merluza y las kokotxas para una cocción suave y controlada. Al final, añade las almejas para que se abran y emulsiona la salsa para lograr la textura perfecta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_042', 'Kokotxas de bacalao al pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'elaborada', 'all', 400, 24, 1, 32, 2, false, false, '{"pescado"}', '[{"name":"Kokotxas de bacalao","amount":400,"unit":"g"},{"name":"Ajo","amount":30,"unit":"g"},{"name":"Guindilla","amount":3,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":120,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Secar kokotxas de bacalao con papel absorbente hasta que no quede humedad superficial.","Laminar ajo.","Cortar guindilla en aros finos.","Calentar aceite de oliva virgen extra en una cazuela de barro a fuego suave hasta que esté templado.","Sofreír el ajo laminado y los aros de guindilla a fuego suave hasta que el ajo esté dorado.","Retirar el ajo y la guindilla con una espumadera y reservar.","Colocar las kokotxas con la piel hacia arriba en el aceite templado a fuego muy suave.","Cocinar a fuego muy suave 4 min sin que el aceite hierva, moviendo la cazuela en círculos para que las kokotxas suelten gelatina.","Retirar la cazuela del fuego y seguir moviéndola en círculos sin parar.","Añadir el aceite de la cazuela poco a poco sobre las kokotxas mientras se mueve en círculos hasta que la salsa emulsione y forme un pil-pil espeso.","Volver la cazuela al fuego muy suave un instante si la salsa se corta, sin dejar de mover en círculos hasta que vuelva a ligar.","Salpimentar con sal y remover suavemente.","Servir las kokotxas con el pil-pil en cazuelitas individuales y coronar con el ajo y la guindilla reservados."}', 'Kokotxas de bacalao ligadas al pil-pil, con el clásico movimiento de cazuela para emulsionar la salsa.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"La Thermomix es excelente para el pil-pil. Primero, sofríe el ajo y la guindilla en el aceite. Luego, añade las kokotxas y cocina a baja temperatura (80-90°C) con giro inverso y velocidad cuchara, batiendo suavemente para emulsionar la gelatina con el aceite hasta lograr la textu"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_043', 'Cigalas a la plancha con alioli de azafrán', 'pescados', 'marisco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 340, 22, 3, 25, 2, true, false, '{"marisco","huevo"}', '[{"name":"Cigalas frescas","amount":8,"unit":"ud"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Machacar ajo con sal en un mortero hasta obtener una pasta fina.","Poner huevo, la pasta de ajo y azafrán en hebras en el vaso de la batidora.","Añadir aceite de oliva suave y triturar sin mover el brazo de la batidora.","Verter el resto del aceite de oliva suave en hilo fino hasta que emulsione en un alioli espeso.","Añadir zumo de limón y sal al alioli, mezclar y reservar en la nevera.","Secar cigalas frescas con papel absorbente hasta que estén bien secas por fuera.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Cocinar las cigalas frescas 1-2 min por cada lado hasta que estén rosadas y firmes.","Retirar las cigalas de la plancha y salar de inmediato.","Servir las cigalas calientes junto al alioli de azafrán reservado."}', 'Cigalas a la plancha servidas con un alioli suave de azafrán con hebras doradas.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para las cigalas, precalienta la airfryer a 190-200°C. Píntalas con un poco de aceite y sal, y cocínalas durante 8-10 minutos, dándoles la vuelta a mitad, hasta que estén doradas y rosadas. El alioli se prepara aparte de forma tradicional."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Para las cigalas, precalienta el horno con función grill o a 220°C. Colócalas en una bandeja con un chorrito de aceite y sal, y ásalas durante 8-12 minutos, hasta que estén bien rosadas y ligeramente doradas. El alioli se prepara aparte."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_044', 'Arroz de bogavante', 'pescados', 'marisco', 'arroz', ARRAY['plato_unico','primero']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 520, 34, 58, 15, 4, true, true, '{"marisco","pescado"}', '[{"name":"Bogavante","amount":800,"unit":"g"},{"name":"Arroz bomba","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Caldo de pescado y marisco","amount":900,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Cortar bogavante por la mitad longitudinalmente, reservar los jugos y separar las pinzas.","Picar cebolla, pimiento rojo y ajo muy finos.","Calentar aceite de oliva virgen extra en una paellera a fuego fuerte hasta que esté bien caliente.","Dorar los trozos de bogavante 2 min por cada lado hasta que la cáscara tome color rojo intenso.","Retirar el bogavante y reservar junto con los jugos que haya soltado.","Sofreír la cebolla picada, el pimiento rojo picado y el ajo picado en el mismo aceite a fuego medio.","Añadir tomate triturado y pimentón dulce, y remover bien para integrar con el sofrito.","Cocinar el tomate con el pimentón a fuego medio, removiendo de vez en cuando, hasta que pierda el agua.","Añadir arroz bomba y sofreír, removiendo, hasta que los granos estén translúcidos y bien impregnados.","Infusionar azafrán en hebras en un poco de caldo de pescado y marisco caliente durante 2 min.","Verter el resto del caldo y el azafrán infusionado en la paellera y llevar a ebullición a fuego fuerte.","Salpimentar con sal y colocar los trozos de bogavante y sus jugos sobre el arroz.","Cocinar a fuego medio-alto sin remover durante 10 min.","Bajar a fuego suave y cocinar sin remover hasta que el arroz haya absorbido casi todo el caldo.","Retirar del fuego, tapar la paellera con un paño de cocina limpio y dejar reposar.","Servir directamente de la paellera, repartiendo el bogavante entre los comensales."}', 'Arroz meloso cocinado con un bogavante entero partido por la mitad y un caldo intenso de marisco.', '[{"appliance":"horno","time":70,"difficulty":"elaborada","prepSummary":"Prepara el sofrito en una cazuela apta para horno en el fuego. Añade el arroz, el caldo y el bogavante, y termina la cocción en el horno precalentado a 190°C durante 20-25 minutos para un arroz meloso y uniforme."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Elabora el sofrito en el vaso de la Thermomix. Incorpora el arroz, el caldo y el bogavante troceado, cocinando a temperatura Varoma o 100°C con giro inverso y velocidad cuchara durante 20-22 minutos."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla a presión. Añade el arroz, el caldo caliente y el bogavante troceado, cierra y cocina a fuego medio durante 5-7 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_045', 'Gravlax de salmón casero con eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 1450, 'normal', 'all', 390, 32, 6, 27, 4, true, true, '{"pescado","mostaza","sulfitos"}', '[{"name":"Lomo de salmón fresco con piel","amount":600,"unit":"g"},{"name":"Sal gruesa","amount":100,"unit":"g"},{"name":"Azúcar","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":50,"unit":"g"},{"name":"Pimienta negra en grano machacada","amount":5,"unit":"g"},{"name":"Mostaza de Dijon","amount":40,"unit":"g"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Vinagre de vino blanco","amount":10,"unit":"ml"},{"name":"Aceite de girasol","amount":30,"unit":"ml"}]'::jsonb, '{"Retirar las espinas del lomo de salmón fresco con piel pasando los dedos a contrapelo y extrayéndolas con unas pinzas.","Picar eneldo fresco fino y dividirlo en dos partes iguales; reservar cada mitad por separado.","Machacar ligeramente pimienta negra en grano machacada con el reverso de un cuchillo hasta obtener trozos gruesos.","Mezclar en un bol sal gruesa, azúcar, la pimienta machacada y la primera mitad del eneldo picado hasta integrar.","Extender la mezcla de curado sobre toda la superficie del lomo de salmón, cubriéndolo por completo por ambos lados.","Envolver el salmón cubierto con film transparente, apretando bien para que la mezcla quede en contacto con la carne.","Colocar el salmón envuelto en una bandeja y disponer encima un peso (p. ej. una tabla con botes) para prensarlo.","Curar el salmón en la nevera durante 720 min (12 h); pasado ese tiempo, dar la vuelta al paquete y desechar el líquido.","Curar el salmón 720 min más en la nevera (otras 12 h), completando así las 24 h mínimas de curado.","Retirar el film y aclarar el salmón bajo un chorro de agua fría para eliminar el exceso de mezcla de curado.","Secar el salmón con papel absorbente, presionando con suavidad por todas las caras hasta que quede bien seco.","Cubrir la superficie del salmón con la segunda mitad del eneldo picado, presionando para que se adhiera a la carne.","Mezclar en un bol mostaza de dijon, miel y vinagre de vino blanco hasta integrar.","Añadir aceite de girasol en hilo fino sobre la mezcla mientras se remueve sin parar hasta que la salsa emulsione.","Cortar el salmón en lonchas muy finas en diagonal, con el cuchillo inclinado, separándolas con cuidado.","Servir las lonchas de salmón en el plato y acompañar con la salsa de mostaza y eneldo aparte o en hilo por encima."}', 'Salmón curado en casa con sal, azúcar y eneldo, cortado en lonchas finas y servido con salsa de mostaza.', '[{"appliance":"thermomix","time":1450,"difficulty":"normal","prepSummary":"La Thermomix es ideal para picar finamente el eneldo y machacar la pimienta en grano para la mezcla de curado. También permite emulsionar la salsa de mostaza y miel de forma rápida y homogénea, facilitando la preparación de los componentes de la receta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_046', 'Bacalao ajoarriero', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 380, 27, 15, 22, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado y desmigado","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Guindilla","amount":2,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños.","Cortar pimiento rojo y pimiento verde en trozos pequeños.","Picar ajo fino.","Calentar aceite de oliva virgen extra en una cazuela a fuego medio.","Sofreír la cebolla, el pimiento rojo y el pimiento verde hasta que estén blandos.","Añadir el ajo picado y guindilla y sofreír hasta que el ajo suelte aroma.","Añadir tomate triturado y remover para integrar.","Cocer a fuego suave hasta que la salsa reduzca y pierda el exceso de agua.","Añadir bacalao desalado y desmigado y remover con cuidado para integrarlo sin deshacerlo.","Cocer a fuego suave hasta que el bacalao esté cocinado y se integre en la salsa.","Picar perejil fino.","Espolvorear el perejil picado sobre el guiso y servir bien caliente."}', 'Bacalao desmigado en un sofrito de pimientos, tomate y ajo, un guiso reconfortante y sencillo.', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara un sofrito con las verduras en una cazuela apta para horno. Añade el bacalao desmigado y hornea a 180°C durante 20 minutos, permitiendo que los sabores se concentren y el bacalao se cocine suavemente."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite y guindilla. Incorpora el tomate y cocina. Añade el bacalao desmigado y cocina a 90°C en giro inverso, velocidad cuchara, durante 8-10 minutos para integrar sin deshacer el pescado."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla abierta hasta que estén tiernas. Añade el tomate y cocina unos minutos. Incorpora el bacalao desmigado y cocina a fuego suave sin tapar durante 5-7 minutos, permitiendo que los sabores se mezclen sin sobrecocer el pescado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_047', 'Bacalao a la vizcaína', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 60, 'elaborada', 'invierno', 420, 33, 20, 22, 2, true, true, '{"pescado","gluten"}', '[{"name":"Bacalao desalado en lomos","amount":350,"unit":"g"},{"name":"Pimientos choriceros","amount":4,"unit":"ud"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir pimientos choriceros en agua caliente hasta cubrirlos.","Esperar hasta que los pimientos choriceros estén hidratados.","Picar cebolla muy fina.","Picar ajo muy fino.","Retirar la pulpa de los pimientos choriceros hidratados raspando con una cuchara y reservar.","Calentar aceite de oliva virgen extra en una cazuela a fuego medio.","Sofreír la cebolla picada y el ajo picado a fuego suave hasta que estén muy tiernos.","Añadir la pulpa de los pimientos choriceros a la cazuela.","Añadir tomate triturado y remover para integrar.","Cocinar la salsa a fuego suave hasta que se concentre.","Añadir pan frito desmenuzado a la salsa y remover para integrar.","Triturar la salsa hasta obtener una textura fina.","Colar la salsa triturada sobre la misma cazuela.","Añadir sal y remover.","Colocar bacalao desalado en lomos con la piel hacia arriba sobre la salsa caliente.","Cocinar a fuego muy suave moviendo la cazuela en círculos hasta que el bacalao esté hecho.","Servir el bacalao napado con la salsa vizcaína."}', 'Bacalao en salsa vizcaína, con el intenso sabor del pimiento choricero y una salsa oscura y sedosa.', '[{"appliance":"horno","time":75,"difficulty":"elaborada","prepSummary":"Prepara el sofrito y la base de la salsa en una cazuela apta para horno en la encimera. Incorpora el bacalao y hornea a 170°C durante 30-40 minutos, permitiendo que los sabores se integren y el pescado se cocine suavemente en su jugo, logrando una textura melosa."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Pica y sofríe la cebolla y el ajo en la Thermomix. Añade el tomate, los pimientos choriceros rehidratados y el pan frito, tritura y cocina la salsa. Finalmente, incorpora el bacalao y cocínalo a 90°C en giro inverso durante 15-20 minutos para que quede jugoso y la salsa ligada."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_048', 'Gambas al ajillo con jerez y guindilla', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 380, 22, 3, 30, 2, false, false, '{"marisco","sulfitos"}', '[{"name":"Gambas frescas o congeladas","amount":350,"unit":"g"},{"name":"Ajo","amount":25,"unit":"g"},{"name":"Guindilla","amount":6,"unit":"g"},{"name":"Vino de Jerez","amount":40,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Pelar gambas frescas o congeladas dejando la cola si se desea, y secarlas bien con papel de cocina.","Laminar ajo finamente.","Cortar guindilla en aros, retirando las semillas si se quiere menos picante.","Picar perejil fino y reservar.","Calentar aceite de oliva virgen extra en una cazuela de barro a fuego medio.","Añadir el ajo laminado y los aros de guindilla y sofreír hasta que el ajo empiece a dorarse.","Subir el fuego a fuego fuerte y añadir las gambas secas.","Saltear las gambas hasta que empiecen a coger color, aproximadamente 1 min por cada lado.","Verter vino de jerez y remover la cazuela hasta que el alcohol se evapore.","Añadir sal y espolvorear el perejil picado por encima.","Servir burbujeante en la misma cazuela de barro."}', 'Gambas al ajillo con un toque de jerez y guindilla, burbujeantes recién salidas de la cazuela.', '[{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Combina las gambas, ajo laminado, guindilla, jerez, aceite y sal en una cazuela de barro. Hornea 12-15 minutos hasta que las gambas estén rosadas y el aceite burbujee."},{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Trocea el ajo y la guindilla. Sofríelos con el aceite en la Thermomix a 120°C, velocidad cuchara, durante 5 min. Añade las gambas, el jerez y la sal, y cocina 6-8 min a 100°C, giro inverso, velocidad cuchara."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_049', 'Navajas a la plancha con limón', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 240, 24, 3, 12, 2, true, false, '{"moluscos"}', '[{"name":"Navajas frescas","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Sumergir navajas frescas en agua fría con sal durante 20 min para que suelten la arena.","Picar ajo muy fino.","Picar perejil muy fino.","Cortar limón en gajos.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Escurrir las navajas y colocarlas en la plancha con la concha hacia abajo.","Cocinar 1-2 min hasta que se abran, retirando cada navaja en cuanto abra para que no se pasen.","Rociar las navajas con aceite de oliva virgen extra y repartir el ajo y el perejil picados por encima.","Servir de inmediato con los gajos de limón al lado."}', 'Navajas a la plancha abiertas al momento, con ajo, perejil y un chorro de limón.', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Coloca las navajas limpias en la cesta, rocía con un poco de aceite de oliva y cocina durante 6-8 minutos, o hasta que se abran y estén ligeramente doradas. Sirve con el ajo, perejil y limón."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con función grill si es posible. Coloca las navajas en una bandeja de horno, rocía con aceite de oliva y hornea durante 8-10 minutos, o hasta que se abran y los bordes estén ligeramente crujientes. Añade el ajo, perejil y limón al servir."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_050', 'Zamburiñas gratinadas', 'pescados', 'marisco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, 'horno', 30, 'normal', 'all', 372, 27, 19, 21, 2, true, false, '{"moluscos","gluten","lactosa","sulfitos"}', '[{"name":"Carne de zamburiña","amount":240,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Queso rallado","amount":20,"unit":"g"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar cebolla y ajo muy finos.","Cortar carne de zamburiña en 2-3 trozos si son grandes.","Calentar aceite de oliva y la mitad de mantequilla en sartén a fuego suave.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén tiernos.","Picar perejil fino.","Subir el fuego a fuerte y añadir la carne de zamburiña troceada a la sartén.","Saltear hasta que la carne de zamburiña cambie de color por fuera.","Verter vino blanco y remover hasta que se evapore casi por completo.","Retirar la sartén del fuego y salpimentar el relleno al gusto.","Mezclar pan rallado, queso rallado y el perejil picado en un bol.","Fundir el resto de la mantequilla y añadirla a la mezcla de pan rallado; remover hasta integrar.","Precalentar el horno con el grill a temperatura máxima.","Repartir el relleno de zamburiña entre 8 conchas cóncavas limpias dispuestas en una bandeja.","Espolvorear la mezcla de pan rallado y queso sobre cada concha de forma uniforme.","Gratinar en el horno con el grill fuerte hasta que la superficie esté dorada.","Servir las conchas muy calientes recién salidas del horno."}', 'Zamburiñas gratinadas en su concha con cebolla pochada, vino blanco y una costra dorada de pan rallado y queso.', '[{"appliance":"horno","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, añade las zamburiñas y el vino. Mezcla con el resto de ingredientes y gratina en el horno precalentado a 180-200°C durante 10-15 minutos hasta dorar."},{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito en una sartén. Rellena las conchas o moldes y gratina en la airfryer a 180-190°C durante 8-12 minutos, vigilando que el queso se dore sin quemarse."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_051', 'Tartar de salmón con mango y lima', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 340, 26, 14, 19, 2, false, false, '{"pescado","soja","sesamo"}', '[{"name":"Salmón fresco calidad sashimi","amount":240,"unit":"g"},{"name":"Mango maduro","amount":150,"unit":"g"},{"name":"Lima","amount":2,"unit":"ud"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Salsa de soja","amount":15,"unit":"ml"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Cilantro fresco","amount":8,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Congelar salmón fresco calidad sashimi un mínimo de 48 h antes de preparar el tartar para eliminar el riesgo de anisakis.","Descongelar el salmón en la nevera la noche anterior hasta que esté completamente descongelado.","Cortar el salmón en dados de 0,5 cm uniformes y reservar en la nevera.","Pelar mango maduro y cortar en dados del mismo tamaño que el salmón.","Picar cebolleta muy fina.","Picar cilantro fresco muy fino.","Exprimir lima en un bol.","Añadir salsa de soja y aceite de sésamo al zumo de lima y mezclar hasta integrar.","Añadir el salmón, el mango, la cebolleta y el cilantro al bol del aliño y mezclar con cuidado sin machacar los dados.","Tapar el bol y reposar en la nevera hasta que los sabores se integren.","Emplatar el tartar con un aro de cocina y espolvorear sésamo tostado por encima.","Rallar la piel de la lima sobre el tartar emplatado y servir muy frío."}', 'Tartar fresco de salmón con dados de mango, aliñado con lima, soja y aceite de sésamo.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Utiliza la función de picado para el salmón, mango, cebolleta y cilantro, ajustando la velocidad para obtener la textura deseada. Luego, mezcla suavemente todos los ingredientes con la salsa de soja, aceite de sésamo y zumo de lima para un tartar homogéneo y rápido."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_052', 'Suquet de pescado y marisco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 397, 35, 28, 12, 4, true, true, '{"pescado","marisco","moluscos","sulfitos"}', '[{"name":"Rape","amount":250,"unit":"g"},{"name":"Merluza en rodajas","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos. Reservar en agua fría.","Picar cebolla y pimiento rojo muy finos.","Picar ajo muy fino.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla, el ajo y el pimiento rojo a fuego medio hasta que estén tiernos.","Añadir tomate triturado y cocinar a fuego medio hasta que pierda el agua.","Escurrir las patatas y añadirlas a la cazuela. Remover para que se impregnen del sofrito.","Verter vino blanco y dejar reducir a fuego medio.","Añadir caldo de pescado y azafrán en hebras. Remover y llevar a ebullición.","Cocer a fuego medio hasta que las patatas estén casi tiernas.","Cortar rape y merluza en rodajas en trozos regulares mientras cuecen las patatas.","Colocar el rape y la merluza sobre las patatas. Repartir gambas peladas y mejillones alrededor.","Cocer a fuego medio hasta que el pescado esté hecho y los mejillones se hayan abierto.","Retirar los mejillones que no se hayan abierto.","Picar perejil fino y espolvorear sobre la cazuela. Servir directamente en la misma cazuela."}', 'Guiso marinero de pescado y marisco con patatas en un caldo dorado de azafrán.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno. Añade las patatas, pescado, vino, caldo y azafrán, y hornea a 180°C durante 45 minutos. Incorpora las gambas y mejillones y cocina 5-10 minutos más hasta que estén listos."},{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Añade las patatas, pescado, vino, caldo y azafrán, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos. Incorpora las gambas y mejillones y cocina 3-5 minutos más."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Prepara el sofrito en la olla sin presión. Añade las patatas, vino, caldo y azafrán, cierra la olla y cocina 10-12 minutos desde que sube la válvula. Libera la presión, incorpora el pescado, gambas y mejillones, y cocina 3-5 minutos más sin presión hasta que estén hechos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_053', 'Calamares rellenos en su tinta', 'pescados', 'marisco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 90, 'elaborada', 'all', 452, 38, 19, 17, 4, false, true, '{"moluscos","gluten","sulfitos","huevo"}', '[{"name":"Calamares medianos limpios con tinta","amount":800,"unit":"g"},{"name":"Bolsas de tinta de calamar","amount":4,"unit":"ud"},{"name":"Jamón serrano en tacos","amount":50,"unit":"g"},{"name":"Cebolla","amount":250,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Huevo cocido","amount":2,"unit":"ud"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"}]'::jsonb, '{"Picar finamente los tentáculos y las aletas de calamares medianos limpios con tinta, reservando los cuerpos enteros.","Picar finamente la mitad de cebolla y ajo.","Picar jamón serrano en tacos en trozos pequeños.","Picar huevo cocido finamente.","Mezclar en un bol los tentáculos y aletas picados, la cebolla picada, el ajo picado, el jamón picado, el huevo cocido picado y pan rallado hasta obtener el relleno.","Rellenar cada cuerpo de calamar con la mezcla sin llenarlo del todo para que no se abra al cocer.","Cerrar la boca de cada calamar con un palillo.","Picar el resto de la cebolla y pimiento verde muy finos.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla restante y el pimiento verde picados hasta que estén muy pochados.","Añadir tomate triturado y sofreír hasta que pierda el agua.","Añadir harina y remover sin parar hasta que se integre con el sofrito.","Verter vino blanco y remover hasta que el alcohol se evapore y la salsa espese ligeramente.","Disolver el contenido de bolsas de tinta de calamar en 50 ml de agua fría y añadir a la cazuela.","Triturar la salsa con la batidora hasta que quede fina y homogénea.","Colocar los calamares rellenos en la cazuela y cubrir con la salsa negra.","Cocer a fuego suave con la cazuela tapada hasta que los calamares estén tiernos, dando la vuelta a mitad de cocción.","Retirar los palillos de los calamares con cuidado.","Picar perejil finamente.","Servir los calamares napados con la salsa negra y espolvorear el perejil picado por encima."}', 'Calamares rellenos de jamón, huevo y sus propios tentáculos, cocinados lentamente en una salsa negra de su tinta.', '[{"appliance":"horno","time":95,"difficulty":"elaborada","prepSummary":"Tras sellar los calamares rellenos en una sartén, estófalos en una cazuela con la salsa de tinta en el horno precalentado a 160°C durante 60-75 minutos, cubierto, para una cocción uniforme y tierna."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Prepara los sofritos para el relleno y la salsa en el vaso. Una vez rellenos, cocina los calamares en la salsa de tinta en el vaso a 100°C, velocidad cuchara inversa, durante 45-60 minutos, asegurando una cocción suave y homogénea."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Realiza los sofritos y la salsa directamente en la olla. Tras rellenar y sellar los calamares, cocínalos en la salsa a presión durante 15-20 minutos desde que sube la válvula, logrando una ternura excepcional en mucho menos tiempo."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_054', 'Merluza a la plancha con salsa rápida de limón y perejil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 257, 27, 2, 16, 2, true, true, '{"pescado"}', '[{"name":"Lomos de merluza","amount":320,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Picar ajo muy fino.","Picar perejil muy fino.","Exprimir limón y reservar el zumo.","Salpimentar lomos de merluza por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Colocar los lomos de merluza con la piel hacia abajo y cocinar 3 min hasta que la piel esté dorada.","Mezclar en un bol el resto del aceite de oliva, el zumo de limón, el ajo picado y el perejil picado.","Dar la vuelta a los lomos de merluza y cocinar 2 min más hasta que estén hechos por dentro.","Retirar los lomos de merluza de la plancha y colocar en los platos.","Regar con la salsa de limón y perejil y servir."}', 'Lomos de merluza a la plancha con una salsa rápida de limón, ajo y perejil.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para la merluza, precalienta la airfryer a 190°C. Pincela los lomos con aceite, sazona y cocina durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme y una textura jugosa. La salsa se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los lomos de merluza en una bandeja con papel de horno, rocíalos con un poco de aceite y hornea durante 15-20 minutos hasta que estén cocidos y ligeramente dorados. La salsa se puede hacer mientras."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_055', 'Salmón a la plancha con ensalada de pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'facil', 'all', 445, 34, 7, 30, 2, true, true, '{"pescado","lactosa"}', '[{"name":"Lomos de salmón","amount":320,"unit":"g"},{"name":"Pepino","amount":250,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar pepino, cortar por la mitad a lo largo y retirar las semillas con una cuchara.","Cortar el pepino pelado en medias lunas finas.","Laminar cebolla morada en juliana muy fina.","Picar eneldo fresco fino.","Exprimir limón y reservar el zumo.","Mezclar yogur natural con el eneldo picado, el zumo de limón y lomos de salmón en un bol hasta obtener un aliño homogéneo.","Añadir el pepino y la cebolla morada al aliño y mezclar bien.","Reservar la ensalada en la nevera hasta el momento de servir.","Salpimentar lomos de salmón por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Colocar los lomos de salmón con la piel hacia abajo y cocinar 4 min hasta que la piel esté crujiente.","Dar la vuelta a los lomos de salmón y cocinar 2 min más hasta que el interior esté jugoso.","Servir los lomos de salmón con la ensalada de pepino y eneldo al lado."}', 'Salmón a la plancha con piel crujiente y una ensalada fresca de pepino y eneldo.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para el salmón, precalienta la airfryer a 190-200°C. Cocina los lomos durante 12-15 minutos, girándolos a mitad, hasta que estén dorados y jugosos. La ensalada se prepara aparte mientras el salmón se cocina."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función de aire si es posible. Hornea los lomos de salmón en una bandeja con papel de horno durante 15-18 minutos hasta que estén cocidos y ligeramente dorados. La ensalada se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_056', 'Filetes de lenguado a la plancha con salsa de mantequilla y limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 364, 28, 9, 24, 2, true, false, '{"pescado","lactosa","gluten"}', '[{"name":"Filetes de lenguado","amount":320,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar perejil fino y reservar.","Exprimir limón y reservar el zumo.","Salpimentar filetes de lenguado por ambas caras.","Pasar los filetes de lenguado por harina, sacudiendo bien el exceso.","Calentar aceite de oliva en plancha a fuego fuerte.","Añadir la mitad de mantequilla y fundir hasta que deje de burbujear.","Colocar los filetes de lenguado en la plancha y dorar 1 min por cada lado, hasta que estén dorados.","Retirar los filetes de lenguado y reservar en los platos.","Bajar a fuego suave y añadir el resto de la mantequilla a la misma plancha hasta que tome un tono avellana.","Añadir el zumo de limón y remover para ligar la salsa con los jugos de la plancha.","Verter la salsa sobre los filetes de lenguado y espolvorear el perejil picado."}', 'Filetes finos de lenguado a la plancha con una salsa de mantequilla dorada y limón.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía los filetes enharinados con un poco de aceite y cocina durante 10-12 minutos, volteando a mitad, hasta que estén dorados y crujientes. La salsa se prepara aparte."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Hornea los filetes enharinados y ligeramente aceitados a 180-200°C durante 12-15 minutos, hasta que estén cocidos y ligeramente dorados. La salsa de mantequilla y limón se prepara aparte y se vierte al servir."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_057', 'Emperador a la plancha con salsa rápida de tomate y albahaca', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 330, 33, 5, 19, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de emperador","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar ajo muy fino.","Cortar albahaca fresca en trozos pequeños con los dedos o con cuchillo.","Calentar aceite de oliva en un cazo a fuego medio.","Sofreír el ajo picado hasta que empiece a desprender aroma, sin que se dore.","Añadir tomate triturado y cocer a fuego medio hasta que reduzca y espese ligeramente.","Salpimentar la salsa y retirar del fuego.","Añadir la mitad de la albahaca troceada a la salsa y reservar.","Salpimentar rodajas de emperador por ambas caras.","Calentar el resto del aceite de oliva en plancha a fuego fuerte.","Marcar las rodajas de emperador 3 min por el primer lado sin moverlas.","Dar la vuelta a las rodajas de emperador y marcar 3 min más hasta que estén hechas pero jugosas.","Exprimir limón sobre el emperador recién hecho.","Servir el emperador napado con la salsa de tomate y con el resto de la albahaca troceada por encima."}', 'Emperador a la plancha con una salsa rápida de tomate y albahaca fresca.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Sazona el emperador y cocínalo en la airfryer precalentada a 200°C durante 10-12 minutos, dándole la vuelta a mitad para un dorado uniforme. Mientras, prepara la salsa mezclando el tomate, ajo picado, albahaca y aceite de oliva, calentándola ligeramente si lo deseas."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill. Sazona el emperador, rocía con aceite y hornea 12-15 minutos, usando el grill al final para dorar. Prepara la salsa rápida de tomate y albahaca mientras el pescado se hornea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_058', 'Tiradito de corvina al limón y ají amarillo', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 236, 29, 5, 11, 2, false, false, '{"pescado"}', '[{"name":"Corvina fresca en lomo limpio","amount":300,"unit":"g"},{"name":"Lima","amount":4,"unit":"ud"},{"name":"Ají amarillo","amount":15,"unit":"g"},{"name":"Cebolla morada","amount":20,"unit":"g"},{"name":"Cilantro fresco","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Laminar corvina fresca en lomo limpio en lonchas muy finas con un cuchillo afilado y reservar en un plato frío.","Exprimir lima hasta obtener el zumo completo y reservar.","Picar ají amarillo muy fino y añadir al zumo de lima para formar la leche de tigre.","Laminar cebolla morada en juliana finísima y sumergir en agua fría durante 5 min para suavizar su sabor.","Esperar 5 min hasta que la cebolla morada pierda su amargor en el agua fría.","Picar cilantro fresco fino y reservar.","Escurrir la cebolla morada y reservar.","Bañar las láminas de corvina con la leche de tigre justo antes de servir y dejar actuar 1 min.","Repartir la cebolla morada escurrida y el cilantro picado sobre la corvina.","Añadir aceite de oliva por encima y servir inmediatamente bien frío."}', 'Láminas finas de corvina marinadas en lima con un toque picante de ají amarillo, al estilo peruano.', '[{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"La Thermomix es ideal para preparar la ''leche de tigre'': tritura el ají amarillo, cebolla morada, cilantro y zumo de lima con el aceite de oliva. Luego, lamina la corvina muy fina y vierte la salsa para marinar, manteniendo el carácter crudo del tiradito."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_059', 'Carpaccio de salmón con cítricos', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 389, 24, 12, 26, 2, false, false, '{"pescado"}', '[{"name":"Salmón fresco calidad sashimi","amount":240,"unit":"g"},{"name":"Naranja","amount":1,"unit":"ud"},{"name":"Pomelo","amount":1,"unit":"ud"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Congelar salmón fresco calidad sashimi un mínimo de 48 h antes si no viene certificado apto para consumo en crudo.","Descongelar el salmón en la nevera hasta que esté firme pero manejable, sin llegar a temperatura ambiente.","Laminar el salmón en láminas muy finas con un cuchillo afilado, trabajando en frío.","Pelar naranja a lo vivo con un cuchillo, eliminando piel y membrana blanca por completo.","Separar los gajos de naranja retirando las membranas que los envuelven y reservar.","Pelar pomelo a lo vivo del mismo modo, separar los gajos y reservar.","Exprimir limón y verter el zumo en un bol pequeño.","Añadir aceite de oliva virgen extra al zumo de limón y mezclar hasta emulsionar la vinagreta.","Picar eneldo fresco fino y reservar.","Disponer las láminas de salmón extendidas y sin solaparse sobre un plato frío.","Repartir los gajos de naranja y pomelo sobre las láminas de salmón.","Regar con la vinagreta de limón y aceite de oliva virgen extra.","Terminar con el eneldo picado y servir de inmediato muy frío."}', 'Carpaccio de salmón fresco con gajos de naranja y pomelo y una vinagreta cítrica.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es excelente para preparar la vinagreta de cítricos. Emulsiona el aceite de oliva con los zumos de naranja, pomelo y limón, y el eneldo fresco picado durante 1 minuto a velocidad 5. Luego, solo tienes que laminar el salmón calidad sashimi y aderezar generosamente."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_060', 'Boquerones en vinagre', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 150, 'facil', 'all', 331, 32, 1, 20, 2, false, true, '{"pescado","sulfitos"}', '[{"name":"Boquerones frescos limpios en lomos","amount":320,"unit":"g"},{"name":"Vinagre de vino blanco","amount":200,"unit":"ml"},{"name":"Agua","amount":100,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Sal","amount":10,"unit":"g"}]'::jsonb, '{"Congelar boquerones frescos limpios en lomos un mínimo de 48 h para eliminar el riesgo de anisakis.","Descongelar los boquerones en la nevera durante 12 h antes de usarlos.","Colocar los boquerones en una fuente en una sola capa y espolvorear sal por encima.","Dejar reposar los boquerones con la sal durante 20 min.","Enjuagar los boquerones bajo el grifo para retirar el exceso de sal.","Secar los boquerones con papel de cocina y volver a colocarlos en la fuente en una sola capa.","Mezclar vinagre de vino blanco con agua en un bol hasta integrar.","Cubrir los boquerones por completo con la mezcla de vinagre y agua.","Tapar la fuente y marinar en la nevera hasta que la carne esté blanca y opaca.","Picar ajo y perejil muy finos y reservar.","Escurrir los boquerones del vinagre y colocarlos en una fuente limpia en una sola capa.","Espolvorear el ajo picado y el perejil picado por encima de los boquerones.","Cubrir los boquerones con aceite de oliva virgen extra y tapar la fuente.","Reposar en la nevera 30 min más antes de servir.","Servir los boquerones directamente desde la fuente bien fríos."}', 'Boquerones frescos marinados en vinagre con ajo y perejil, el clásico de bar en versión casera.', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_061', 'Salmón a la plancha con mostaza y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 461, 33, 5, 32, 2, true, true, '{"pescado","mostaza","lactosa"}', '[{"name":"Lomos de salmón","amount":320,"unit":"g"},{"name":"Mostaza de Dijon","amount":25,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Miel","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar eneldo fresco fino.","Mezclar en un bol mostaza de dijon, miel, nata para cocinar y el eneldo picado hasta obtener una salsa homogénea.","Salpimentar lomos de salmón por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte.","Colocar los lomos de salmón con la piel hacia abajo y dorar 4 min a fuego medio-alto hasta que la piel esté crujiente.","Dar la vuelta a los lomos de salmón y cocinar 2 min más a fuego medio.","Verter la salsa de mostaza alrededor del salmón y calentar 2 min a fuego suave hasta que esté caliente sin que hierva.","Napar los lomos de salmón con la salsa de la plancha y servir."}', 'Salmón a la plancha con una salsa cremosa de mostaza y eneldo.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina el salmón durante 12-15 minutos, dándole la vuelta a mitad, hasta que esté dorado y jugoso. Mientras, mezcla los ingredientes de la salsa y sírvela sobre el salmón."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca el salmón en una bandeja y hornea durante 15-18 minutos. Para la salsa, mezcla la mostaza, eneldo, nata y miel, y viértela sobre el salmón los últimos 5 minutos de cocción o sírvela aparte."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Prepara la salsa en el vaso mezclando los ingredientes. Coloca el salmón en el recipiente Varoma y cocina al vapor durante 15-20 minutos a temperatura Varoma, velocidad 1, con 500ml de agua en el vaso. Sirve el salmón con la salsa."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cocina el salmón al vapor en la vaporera durante 10-15 minutos hasta que esté tierno. Mientras, mezcla la mostaza, eneldo, nata y miel en un bol o sartén a fuego bajo para la salsa. Sirve el salmón con la salsa por encima."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_062', 'Merluza rebozada con patatas fritas y alioli', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 646, 36, 47, 34, 2, true, false, '{"pescado","gluten","huevo"}', '[{"name":"Lomos de merluza","amount":320,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Mayonesa","amount":35,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar patata y cortar en bastones regulares de grosor uniforme.","Secar los bastones de patata con un paño limpio hasta eliminar el exceso de humedad.","Calentar aceite de oliva en una sartén grande a fuego fuerte hasta que esté bien caliente.","Freír las patatas en 2 tandas hasta que estén doradas y crujientes.","Escurrir las patatas fritas sobre papel de cocina y reservar.","Secar lomos de merluza con papel de cocina por ambos lados.","Salpimentar los lomos de merluza por ambos lados.","Poner harina en un plato llano.","Batir huevo en un bol hasta que esté homogéneo.","Pasar cada lomo de merluza por la harina y sacudir el exceso.","Sumergir cada lomo enharinado en el huevo batido hasta cubrirlo bien.","Calentar aceite abundante en sartén a fuego fuerte hasta que esté bien caliente.","Freír los lomos de merluza rebozados 3 min por cada lado hasta que estén dorados.","Escurrir la merluza frita sobre papel de cocina y reservar.","Picar ajo muy fino hasta obtener una pasta.","Exprimir limón y reservar el zumo.","Mezclar el ajo picado con mayonesa y unas gotas de zumo de limón en un bol pequeño.","Servir los lomos de merluza rebozada junto a las patatas fritas y el alioli aparte."}', 'Merluza rebozada crujiente con patatas fritas y un alioli rápido, el clásico de chiringuito.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara la merluza rebozada y las patatas cortadas en bastones con un poco de aceite en spray. Cocina en la airfryer a 190°C: las patatas unos 20 minutos, agitándolas, y la merluza unos 12 minutos, dándole la vuelta. El alioli se prepara aparte."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Hornea las patatas cortadas en bastones con un chorrito de aceite a 200°C durante unos 35-40 minutos, dándoles la vuelta. Añade la merluza rebozada, rociada con un poco de aceite, y hornea 15-20 minutos más hasta que esté dorada. El alioli se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_063', 'Bacalao con patatas fritas y mayonesa de ajo', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 612, 34, 40, 34, 2, true, false, '{"pescado","gluten","huevo"}', '[{"name":"Lomos de bacalao desalado","amount":320,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarlas en bastones regulares de unos 8 mm de grosor.","Calentar aceite de oliva en una olla o sartén profunda a fuego fuerte hasta que esté bien caliente.","Freír las patatas en el aceite caliente hasta que estén doradas y crujientes.","Escurrir las patatas sobre papel absorbente y reservar.","Secar lomos de bacalao desalado con papel de cocina presionando suavemente.","Pasar los lomos de bacalao desalado por harina, sacudiendo bien el exceso.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Dorar los lomos de bacalao desalado 4 min por el primer lado hasta que estén dorados.","Dar la vuelta a los lomos de bacalao desalado y dorar 3 min por el otro lado hasta que estén jugosos por dentro.","Retirar los lomos de bacalao desalado de la sartén y reservar.","Picar ajo muy fino y machacar con el canto del cuchillo hasta obtener una pasta.","Mezclar la pasta de ajo con mayonesa en un bol pequeño hasta integrar completamente.","Picar perejil fino.","Servir los lomos de bacalao desalado junto con las patatas fritas, la mayonesa de ajo aparte y el perejil picado por encima."}', 'Lomos de bacalao dorados con patatas fritas y una mayonesa casera con mucho ajo.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Para las patatas, córtalas en bastones, rocía con aceite y cocina a 190°C durante 20-25 min, agitando. Luego, enharina el bacalao, rocíalo con aceite y cocínalo a 190°C durante 12-15 min, dándole la vuelta, para un acabado crujiente."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Corta las patatas en gajos, rocíalas con aceite y ásalas durante 30-35 min. Enharina el bacalao, úntalo con un poco de aceite y hornéalo junto a las patatas los últimos 15-20 min, hasta que esté dorado y jugoso."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_064', 'Lubina a la plancha con limón y alcaparras', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 331, 29, 1, 24, 2, false, true, '{"pescado","lactosa"}', '[{"name":"Filetes de lubina","amount":320,"unit":"g"},{"name":"Alcaparras","amount":20,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Picar perejil finamente y reservar.","Exprimir limón y reservar el zumo.","Salpimentar filetes de lubina por ambas caras.","Calentar aceite de oliva en plancha a fuego fuerte.","Colocar los filetes de lubina con la piel hacia abajo y cocinar hasta que la piel esté dorada y crujiente.","Dar la vuelta a los filetes de lubina y cocinar 2 min más hasta que estén hechos.","Retirar los filetes de lubina y reservar en los platos.","Bajar el fuego a medio y fundir mantequilla en la misma plancha hasta que se dore ligeramente.","Añadir alcaparras y el zumo de limón reservado.","Remover para ligar la salsa con los jugos de la plancha hasta que esté homogénea.","Verter la salsa de mantequilla y alcaparras sobre los filetes de lubina en los platos.","Espolvorear el perejil picado sobre los filetes y servir."}', 'Filetes de lubina a la plancha con mantequilla dorada, limón y alcaparras.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Sazona los filetes con sal y pimienta, úntalos ligeramente con aceite de oliva y cocínalos durante 10-12 minutos, dándoles la vuelta a mitad. Mientras, derrite la mantequilla con el zumo de limón, alcaparras y perejil para salsear el pescado u"},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca los filetes de lubina en una bandeja de horno con papel de hornear, rocíalos con aceite de oliva y hornea durante 12-15 minutos hasta que estén cocidos y ligeramente dorados. Sirve con la salsa de mantequilla, limón y "}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_065', 'Rape a la plancha con salsa verde', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 294, 27, 4, 15, 2, true, true, '{"pescado","gluten","sulfitos"}', '[{"name":"Medallones de rape","amount":350,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Caldo de pescado","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Laminar ajo.","Picar perejil fino.","Salpimentar medallones de rape por ambas caras.","Calentar aceite de oliva en una cazuela baja a fuego medio.","Sofreír el ajo laminado hasta que esté dorado sin quemarse.","Añadir harina y remover hasta que se integre con el aceite.","Verter vino blanco y remover hasta que no queden grumos.","Añadir caldo de pescado y remover hasta que la salsa ligue y esté homogénea.","Colocar los medallones de rape en la cazuela en una sola capa a fuego suave.","Cocer a fuego suave 8 min, moviendo la cazuela en círculos para ligar la salsa.","Añadir el perejil picado y remover suavemente.","Servir en la misma cazuela."}', 'Medallones de rape a la plancha bañados en una salsa verde de ajo y perejil.', '[{"appliance":"airfryer","time":25,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190°C. Sella los medallones de rape ligeramente enharinados y con un poco de aceite durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme. Prepara la salsa verde en paralelo en una sartén, sofriendo el ajo y añadiendo el resto de ingr"},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Precalienta el horno con la función grill a 200°C. Coloca los medallones de rape en una bandeja con un hilo de aceite y cocina durante 15-20 minutos, girándolos a mitad para asegurar un dorado parejo. La salsa verde se elabora simultáneamente en una cazuela."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_066', 'Salmón teriyaki con sésamo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 432, 34, 13, 26, 2, true, true, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Lomos de salmón","amount":320,"unit":"g"},{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Miel","amount":25,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Sésamo tostado","amount":10,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Cebolleta","amount":15,"unit":"g"}]'::jsonb, '{"Rallar jengibre fresco.","Picar ajo muy fino.","Mezclar en un bol salsa de soja, miel, el jengibre rallado y el ajo picado hasta integrar.","Sumergir lomos de salmón en la mitad de la salsa teriyaki y marinar 10 min.","Picar cebolleta fina y reservar.","Calentar aceite de sésamo en sartén a fuego fuerte.","Colocar los lomos de salmón con la piel hacia abajo y cocinar 4 min hasta que la piel esté dorada.","Dar la vuelta a los lomos con cuidado.","Verter el resto de la salsa teriyaki en la sartén y cocinar 3 min hasta que la salsa reduzca y glasee el salmón.","Espolvorear sésamo tostado y la cebolleta picada sobre los lomos.","Servir los lomos bien calientes con la salsa reducida por encima."}', 'Salmón glaseado en salsa teriyaki con sésamo tostado.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Prepara la salsa teriyaki y marina el salmón. Cocina en la airfryer a 190°C durante 12-15 minutos, pincelando con la salsa a mitad de cocción para un glaseado perfecto y una textura jugosa."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Marina el salmón en la salsa teriyaki. Hornea a 200°C durante 15-20 minutos, pincelando varias veces con la salsa para lograr un glaseado brillante y una carne tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_067', 'Atún encebollado con pimientos', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 402, 37, 17, 18, 2, true, true, '{"pescado","sulfitos"}', '[{"name":"Atún fresco","amount":300,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar cebolla y cortar en juliana fina.","Cortar pimiento rojo y pimiento verde en tiras finas.","Cortar atún fresco en 2 tacos o filetes uniformes y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y los pimientos a fuego suave hasta que estén muy tiernos y ligeramente dorados.","Añadir tomate triturado, vino blanco y laurel.","Cocinar a fuego medio hasta que el alcohol se evapore y la salsa reduzca ligeramente.","Colocar el atún sobre la cama de verduras y cubrir parcialmente con la cebolla y los pimientos.","Cocinar 3 min por el primer lado sin mover, hasta que el atún cambie de color por los bordes.","Dar la vuelta al atún y cocinar 3 min más por el otro lado hasta que esté hecho al gusto.","Servir el atún napado con la cebolla, los pimientos y el jugo de la sartén."}', 'Lomos de atún encebollados con pimientos rojo y verde en una salsa de tomate y vino blanco.', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sofríe ligeramente las verduras en una sartén o directamente en una fuente de horno. Añade el tomate, vino y laurel, hornea a 180°C durante 25-30 minutos y luego incorpora el atún en los últimos 10-12 minutos."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras con aceite. Añade el tomate, vino y laurel, programa para cocer a temperatura Varoma/100°C durante 15-20 minutos y luego el atún en los últimos 5-7 minutos."},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla abierta. Incorpora el tomate, vino y laurel, cierra y cocina 5-7 minutos desde que sube la válvula. Despresuriza, añade el atún y cocina 2-3 minutos más sin presión hasta que esté hecho."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_068', 'Dorada a la sal con salsa romesco', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 45, 'normal', 'all', 445, 44, 11, 26, 2, true, false, '{"pescado","frutos_secos","gluten","sulfitos"}', '[{"name":"Dorada entera limpia sin escamar","amount":900,"unit":"g"},{"name":"Sal gruesa","amount":1500,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Ñora hidratada","amount":15,"unit":"g"},{"name":"Almendras tostadas","amount":25,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 220 °C.","Extender la mitad de sal gruesa en una bandeja formando una capa uniforme.","Colocar dorada entera limpia sin escamar encima de la cama de sal gruesa.","Cubrir la dorada con el resto de la sal gruesa, apretando bien para formar una costra compacta.","Hornear la bandeja en el centro del horno hasta que la costra esté dura y ligeramente dorada.","Picar ajo.","Cortar tomate maduro en trozos.","Añadir el tomate, el ajo, ñora hidratada, almendras tostadas y pan frito al vaso de la batidora.","Añadir vinagre de vino y aceite de oliva al vaso de la batidora.","Triturar todo hasta obtener una salsa romesco fina y homogénea.","Retirar la bandeja del horno y dejar reposar la costra de sal intacta.","Romper la costra de sal golpeándola con el dorso de una cuchara.","Retirar la costra junto con la piel de la dorada con cuidado, sin romper la carne.","Separar los lomos de la dorada limpiándolos de espinas.","Servir los lomos de dorada en el plato con la salsa romesco aparte."}', 'Dorada entera horneada en costra de sal, con la carne jugosa y una salsa romesco de contraste.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Para la dorada, cubre el pescado con la sal gruesa y hornea a 190-200°C durante 45 minutos. Mientras, asa los tomates y ajos para la salsa romesco en el mismo horno, luego tritúralos con las ñoras, almendras, pan frito, vinagre y aceite hasta obtener una salsa homogénea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_069', 'Emperador a la plancha con salsa tártara', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 414, 32, 2, 31, 2, false, false, '{"pescado","huevo","mostaza"}', '[{"name":"Rodajas de emperador","amount":320,"unit":"g"},{"name":"Mayonesa","amount":45,"unit":"g"},{"name":"Pepinillos en vinagre","amount":20,"unit":"g"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Mostaza de Dijon","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar muy fino pepinillos en vinagre.","Picar muy finas alcaparras.","Picar muy fino perejil.","Mezclar mayonesa con los pepinillos, las alcaparras y el perejil picados.","Añadir mostaza de dijon a la mezcla y remover hasta que esté homogénea.","Reservar la salsa tártara en la nevera hasta el momento de servir.","Salpimentar rodajas de emperador por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee ligeramente.","Colocar las rodajas de emperador en la plancha y cocinar 3 min por el primer lado sin moverlas.","Dar la vuelta a las rodajas de emperador y cocinar 3 min más hasta que estén doradas y jugosas.","Retirar las rodajas de emperador de la plancha y dejar reposar 1 min.","Cortar limón en gajos.","Servir las rodajas de emperador con la salsa tártara aparte y los gajos de limón."}', 'Emperador a la plancha con una salsa tártara casera de pepinillos y alcaparras.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía las rodajas de emperador con un poco de aceite de oliva y cocínalas durante 10-12 minutos, volteándolas a mitad, hasta que estén doradas por fuera y jugosas por dentro. Prepara la salsa tártara mientras el pescado se cocina."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_070', 'Chipirones encebollados', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 359, 31, 16, 15, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Chipirones limpios","amount":400,"unit":"g"},{"name":"Cebolla","amount":220,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Añadir la cebolla, el ajo y laurel a la sartén.","Sofreír a fuego suave hasta que la cebolla esté muy tierna y dulce.","Subir el fuego a fuego fuerte y añadir chipirones limpios a la sartén.","Saltear hasta que los chipirones suelten su agua.","Verter vino blanco y remover.","Reducir a fuego medio-fuerte hasta que el vino se evapore casi por completo.","Bajar el fuego a fuego suave y cocer hasta que los chipirones estén tiernos y la salsa melosa.","Retirar el laurel y añadir el perejil picado.","Servir los chipirones bien calientes."}', 'Chipirones tiernos cocinados a fuego lento con cebolla muy pochada.', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en una cazuela apta para horno. Añade los chipirones, el vino blanco y el laurel, tapa y hornea a 180°C durante 25-30 minutos hasta que los chipirones estén tiernos."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Incorpora los chipirones, el vino y el laurel, y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 20-25 minutos hasta que estén tiernos y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Agrega los chipirones, el vino y el laurel, cierra la olla y cocina a presión alta durante 4-5 minutos. Deja despresurizar naturalmente para una textura perfecta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_071', 'Sepia a la plancha con ajo y perejil', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 306, 30, 8, 15, 2, true, true, '{"moluscos"}', '[{"name":"Sepia limpia","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar sepia limpia en trozos regulares y secar bien con papel de cocina para evitar que suelte agua en la plancha.","Picar ajo muy fino.","Picar perejil muy fino.","Calentar plancha a fuego fuerte con aceite de oliva hasta que humee ligeramente.","Marcar la sepia 2 min sin moverla, hasta que se dore por debajo.","Dar la vuelta a la sepia y marcar 2 min más por el otro lado hasta que esté dorada y tierna.","Añadir el ajo picado sobre la sepia durante el último minuto de cocción, sin dejar de vigilar para que no se queme.","Retirar la sepia del fuego y espolvorear con el perejil picado.","Exprimir limón por encima y servir inmediatamente."}', 'Sepia a la plancha con ajo y perejil, marcada por fuera y tierna por dentro.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina la sepia marinada con ajo, perejil y aceite durante 12-15 minutos, volteándola a mitad, para lograr un exterior dorado y un interior tierno."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con la función grill. Coloca la sepia marinada en una bandeja y cocina 15-20 minutos, dándole la vuelta, hasta que esté bien dorada y jugosa, imitando el efecto plancha."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_072', 'Mejillones a la marinera', 'pescados', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 313, 20, 14, 16, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Mejillones frescos","amount":800,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Limpiar mejillones frescos: retirar las barbas tirando hacia la punta y raspar las conchas con un cuchillo.","Descartar los mejillones que estén abiertos y no se cierren al golpearlos suavemente.","Picar cebolla muy fina.","Picar ajo muy fino.","Calentar aceite de oliva en una cazuela amplia a fuego medio.","Sofreír la cebolla picada y el ajo picado a fuego suave hasta que estén tiernos.","Añadir pimentón dulce y remover durante unos segundos hasta que se integre.","Añadir tomate triturado y cocer a fuego medio hasta que la salsa reduzca y espese.","Añadir vino blanco y laurel; llevar a ebullición.","Picar perejil fino y reservar.","Incorporar los mejillones limpios, tapar la cazuela y cocinar a fuego fuerte hasta que se abran todos.","Descartar los mejillones que no se hayan abierto.","Espolvorear el perejil picado sobre los mejillones y servir en la misma cazuela con el caldo."}', 'Mejillones abiertos en una salsa marinera de tomate, vino blanco y pimentón.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade el tomate, vino y especias. Coloca los mejillones en el Varoma y cocina al vapor mientras la salsa se integra en el vaso, o cocínalos directamente en el vaso."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Añade el resto de ingredientes y los mejillones. Cierra la olla y cocina a presión alta 2-3 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_073', 'Almejas a la marinera', 'pescados', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 241, 14, 6, 14, 2, true, true, '{"moluscos","gluten","sulfitos","pescado"}', '[{"name":"Almejas frescas","amount":600,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":8,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":50,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Sumergir almejas frescas en agua fría con sal durante 60 min para que suelten la arena.","Escurrir las almejas y aclarar bajo el grifo.","Picar ajo fino.","Picar perejil fino.","Calentar aceite de oliva en una cazuela baja a fuego medio.","Sofreír el ajo picado hasta que esté dorado sin llegar a quemarse.","Añadir harina y remover sin parar hasta que se integre con el ajo.","Verter vino blanco removiendo para disolver los grumos.","Añadir caldo de pescado y remover hasta que la salsa sea homogénea.","Llevar a ebullición y cocer a fuego medio hasta que la salsa espese ligeramente, unos 2 min.","Incorporar las almejas escurridas, subir a fuego fuerte y tapar la cazuela.","Cocer tapado, agitando la cazuela a mitad, hasta que todas las almejas estén abiertas.","Retirar las almejas que no se hayan abierto.","Espolvorear el perejil picado y servir en la misma cazuela bien caliente."}', 'Almejas abiertas en una salsa dorada de ajo, perejil y vino blanco.', '[{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Sofríe el ajo picado, añade la harina, el vino blanco y el caldo de pescado. Incorpora las almejas y cocina a 100°C con giro inverso y velocidad cuchara durante 6-8 minutos, o hasta que se abran, finalizando con perejil picado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_074', 'Berberechos al natural', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 145, 22, 3, 3, 2, true, false, '{"moluscos","sulfitos"}', '[{"name":"Berberechos frescos","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal gorda","amount":20,"unit":"g"},{"name":"Agua","amount":1000,"unit":"ml"}]'::jsonb, '{"Disolver sal gorda en agua fría en un bol amplio hasta que se integre.","Sumergir berberechos frescos en el agua con sal y dejar reposar para que suelten la arena.","Escurrir los berberechos y enjuagarlos bien bajo el grifo con agua fría.","Machacar ajo con la piel con el lateral de un cuchillo.","Colocar el ajo machacado y laurel en una cazuela amplia.","Verter vino blanco en la cazuela y llevar a ebullición a fuego fuerte.","Incorporar los berberechos escurridos de golpe y tapar la cazuela.","Cocer a fuego fuerte, agitando la cazuela una vez a mitad, hasta que todas las conchas se abran.","Retirar del fuego en cuanto estén abiertas para que no queden gomosos.","Descartar los berberechos que no se hayan abierto.","Servir inmediatamente en la misma cazuela con su propio jugo."}', 'Berberechos abiertos al vapor con ajo, laurel y un chorrito de vino blanco, con todo su jugo de mar.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo, añade el vino, agua, laurel y sal. Coloca los berberechos en el recipiente Varoma y cocina al vapor hasta que se abran, aprovechando el caldo aromático en el vaso."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Hierve el agua con el vino, ajo, laurel y sal en la base de la vaporera. Cocina los berberechos en la cesta de vapor hasta que se abran, permitiendo que absorban los aromas del caldo."},{"appliance":"olla_express","time":10,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en la olla a presión. Cocina a fuego medio-bajo por 1-2 minutos desde que sube la válvula, liberando la presión inmediatamente para evitar sobrecocer los berberechos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_075', 'Fritura de pescado variado', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'verano', 420, 30, 22, 24, 2, true, false, '{"pescado","moluscos","gluten"}', '[{"name":"Boquerones limpios","amount":200,"unit":"g"},{"name":"Calamar en anillas","amount":150,"unit":"g"},{"name":"Salmonetes pequeños","amount":150,"unit":"g"},{"name":"Harina fina de trigo","amount":100,"unit":"g"},{"name":"Aceite de oliva suave","amount":400,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Secar boquerones limpios con papel de cocina hasta eliminar toda la humedad.","Secar calamar en anillas con papel de cocina hasta eliminar toda la humedad.","Secar salmonetes pequeños con papel de cocina hasta eliminar toda la humedad.","Salar sal todo el pescado y el calamar por ambas caras.","Extender harina fina de trigo en una bandeja amplia.","Pasar cada pieza de pescado y calamar por la harina, sacudiendo bien el exceso.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el calamar en anillas en tandas pequeñas, sin amontonar, hasta que estén doradas.","Retirar el calamar con una espumadera a un plato con papel absorbente.","Freír los boquerones en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","Retirar los boquerones a papel absorbente y salar al instante de sacarlos del aceite.","Freír los salmonetes en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","Retirar los salmonetes a papel absorbente y salar al instante de sacarlos del aceite.","Cortar limón en gajos.","Servir todo el pescado junto, muy caliente, acompañado de los gajos de limón."}', 'Fritura variada de boquerones, calamar y salmonetes, crujiente por fuera y jugosa por dentro, con limón.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Enharina ligeramente el pescado, rocía con un poco de aceite y cocina en tandas durante 12-15 minutos cada una, volteando a mitad, hasta que esté dorado y crujiente."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (con ventilador si es posible). Enharina el pescado, rocía con aceite y distribúyelo en una bandeja con papel de horno. Hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_076', 'Croquetas de bacalao con alioli', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'all', 460, 22, 34, 26, 4, true, false, '{"pescado","gluten","lactosa","huevo"}', '[{"name":"Bacalao desalado desmigado","amount":250,"unit":"g"},{"name":"Leche entera","amount":500,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva suave","amount":400,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Fundir mantequilla en una sartén a fuego suave.","Sofreír la cebolla picada en la mantequilla fundida hasta que esté transparente.","Añadir bacalao desalado desmigado y sofreír removiendo durante 2 min.","Incorporar harina de trigo y remover sin parar durante 2 min hasta que no coja color.","Calentar leche entera en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","Verter la leche caliente sobre la mezcla poco a poco sin dejar de remover hasta obtener una bechamel espesa y sin grumos.","Añadir nuez moscada y remover para integrar.","Cocer la bechamel a fuego muy suave removiendo con frecuencia hasta que esté muy espesa y se despegue de los bordes.","Extender la masa en una bandeja y cubrir con film a piel para que no forme costra.","Enfriar la masa en la nevera hasta que esté completamente fría y firme.","Batir huevo en un bol hondo.","Poner pan rallado en otro bol o bandeja plana.","Formar las croquetas con las manos tomando porciones de masa fría y dándoles forma alargada.","Pasar cada croqueta por el huevo batido y escurrir el exceso.","Rebozar cada croqueta en el pan rallado presionando bien para que quede bien cubierta.","Pelar ajo y retirar el germen interior.","Majar el ajo en un mortero con una pizca de sal hasta obtener una pasta fina.","Añadir aceite de girasol en hilo muy fino sobre el ajo majado sin dejar de remover en círculos hasta emulsionar el alioli.","Reservar el alioli en un bol tapado en la nevera.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar unos 180 °C.","Freír las croquetas en tandas sin amontonarlas hasta que estén doradas por todos los lados.","Escurrir las croquetas sobre papel absorbente.","Servir las croquetas calientes con el alioli aparte."}', 'Croquetas cremosas de bacalao desmigado con corteza dorada y crujiente, acompañadas de alioli casero.', '[{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"La Thermomix es excelente para preparar la masa de las croquetas y el alioli. Sofríe la cebolla, elabora una bechamel perfecta con el bacalao y luego el alioli de forma rápida y sin esfuerzo, controlando temperatura y velocidad para evitar grumos."},{"appliance":"airfryer","time":70,"difficulty":"normal","prepSummary":"Para una versión más ligera, cocina las croquetas en la airfryer a 190-200°C durante 15-20 minutos, dándoles la vuelta a mitad. Rocíalas ligeramente con aceite para un exterior más crujiente, aunque la textura será menos jugosa que la fritura tradicional."},{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Para una alternativa horneada, precalienta el horno a 200°C. Hornea las croquetas durante 20-25 minutos, o hasta que estén doradas, dándoles la vuelta a mitad. Pulverízalas con un poco de aceite para mejorar la capa exterior."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_077', 'Merluza a la sidra', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 320, 30, 12, 14, 2, true, true, '{"pescado","moluscos","sulfitos","gluten"}', '[{"name":"Merluza en lomos","amount":350,"unit":"g"},{"name":"Almejas","amount":150,"unit":"g"},{"name":"Sidra natural","amount":150,"unit":"ml"},{"name":"Manzana ácida","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Harina de trigo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Sumergir almejas en agua fría con sal durante 30 min para que suelten la arena.","Picar cebolla muy fina.","Picar ajo muy fino.","Pelar manzana ácida y laminar en láminas finas.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela a fuego suave.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","Añadir harina de trigo y remover sin parar hasta que se integre con el sofrito.","Verter sidra natural poco a poco removiendo sin parar hasta que la salsa ligue sin grumos.","Incorporar la manzana laminada y cocer a fuego medio hasta que esté tierna.","Escurrir las almejas del agua de remojo.","Salpimentar merluza en lomos y colocar sobre la salsa en la cazuela.","Añadir las almejas escurridas alrededor de los lomos de merluza.","Tapar la cazuela y cocer a fuego suave, moviendo en círculos, hasta que las almejas se abran.","Espolvorear el perejil picado sobre el pescado y servir en la misma cazuela."}', 'Merluza cocinada en una salsa dorada de sidra y manzana, con almejas abiertas en su punto.', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla, ajo y manzana en una sartén apta para horno. Añade la sidra, coloca la merluza y las almejas, y hornea a 190°C durante 15-20 minutos hasta que el pescado esté hecho y las almejas abiertas."},{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla, ajo y manzana en el vaso. Añade la sidra, coloca la merluza y las almejas en el Varoma y cocina todo simultáneamente a temperatura Varoma, velocidad cuchara, durante 15-20 minutos."},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sofríe la cebolla, ajo y manzana en la olla. Añade la sidra, la merluza y las almejas. Cierra la olla y cocina a presión durante 3-4 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_078', 'Bacalao con pisto y huevo', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'verano', 390, 32, 16, 20, 2, true, true, '{"pescado","huevo"}', '[{"name":"Bacalao desalado en lomos","amount":300,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"}]'::jsonb, '{"Cortar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Cortar calabacín y berenjena en dados pequeños.","Calentar aceite de oliva en una sartén amplia a fuego medio.","Sofreír la cebolla y el ajo picado hasta que estén transparentes.","Añadir el pimiento rojo y el pimiento verde y sofreír hasta que se ablanden.","Añadir el calabacín y la berenjena y sofreír removiendo de vez en cuando.","Añadir tomate triturado, remover y tapar la sartén.","Cocer a fuego suave hasta que las verduras estén tiernas y el pisto espese.","Calentar plancha a fuego fuerte con aceite de oliva.","Dorar bacalao desalado en lomos por el lado de la piel hasta que esté dorado.","Dar la vuelta a los lomos y dorar por el otro lado hasta que la carne esté opaca.","Retirar los lomos y reservar.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Freír huevo uno a uno hasta que la clara esté cuajada y la yema líquida.","Repartir el pisto en 2 platos hondos o cazuelitas individuales.","Colocar un lomo de bacalao sobre el pisto en cada plato.","Colocar un huevo frito encima del bacalao y servir enseguida."}', 'Lomo de bacalao sobre un pisto de verduras coloridas, coronado con un huevo frito de yema rota.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Prepara el pisto cocinando las verduras troceadas con un poco de aceite a 180°C durante 20-25 minutos, removiendo a mitad. Luego, cocina el bacalao a 190°C durante 10-12 minutos y, si lo deseas, hornea un huevo en un ramekin junto a ellos."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa el pisto mezclando todas las verduras troceadas con aceite y tomate a 180-190°C durante 30-40 minutos. Añade el bacalao en los últimos 15-20 minutos y, si lo deseas, hornea un huevo en un ramekin junto a ellos."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Prepara el pisto en el vaso, troceando y sofriendo las verduras. Cocina el bacalao y los huevos al vapor en el recipiente Varoma mientras el pisto se termina de hacer en el vaso, a temperatura Varoma."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe las verduras del pisto en la olla express, añade el tomate y cocina a presión durante 8-10 minutos. Abre, introduce el bacalao y cocina 2-3 minutos más. El huevo se puede freír aparte o escalfar rápidamente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL),
  ('pescados_079', 'Tartar de salmón con soja y aguacate', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 380, 24, 8, 28, 2, false, false, '{"pescado","soja","sesamo"}', '[{"name":"Lomo de salmón fresco de calidad sashimi","amount":280,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Salsa de soja","amount":25,"unit":"ml"},{"name":"Aceite de sésamo","amount":8,"unit":"ml"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Semillas de sésamo","amount":5,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar lomo de salmón fresco de calidad sashimi en dados de medio centímetro, regulares y limpios.","Pelar aguacate y cortar en dados del mismo tamaño que el salmón.","Exprimir lima y reservar el zumo.","Rociar los dados de aguacate con la mitad del zumo de lima para evitar que se oxide.","Picar cebolleta muy fina.","Mezclar en un bol salsa de soja, aceite de sésamo y el zumo de lima restante hasta integrar.","Añadir el salmón, el aguacate y la cebolleta picada al bol con el aliño.","Mezclar con cuidado para no aplastar los dados, asegurando que el aliño los cubra por igual.","Tapar el bol y dejar reposar en la nevera hasta que los sabores se integren.","Emplatar con la ayuda de un aro de cocina, disponiendo el tartar en capas compactas.","Picar cilantro fresco y espolvorear sobre el tartar junto con semillas de sésamo justo antes de servir."}', 'Tartar fresco de salmón y aguacate en capas, aliñado con soja y sésamo, con un toque de lima.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es ideal para picar finamente la cebolleta y el cilantro, así como para emulsionar la vinagreta de soja y sésamo. El salmón se puede picar con golpes de turbo muy cortos para mantener su textura, mientras que el aguacate se corta a cuchillo para preservar su forma."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_080', 'Ceviche de lubina con leche de tigre', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'verano', 220, 26, 10, 6, 2, false, false, '{"pescado"}', '[{"name":"Lomo de lubina fresca","amount":300,"unit":"g"},{"name":"Lima","amount":4,"unit":"ud"},{"name":"Cebolla morada","amount":60,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Chile fresco","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Apio","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Cortar lomo de lubina fresca en dados de 1,5 cm, retirando cualquier espina.","Separar un tercio de los dados de lubina y reservar el resto en un bol frío.","Cortar cebolla morada en juliana muy fina y sumergirla en agua con hielo.","Dejar la cebolla morada en el agua con hielo hasta que pierda el amargor.","Exprimir lima y colar el zumo para eliminar pepitas.","Pelar y cortar jengibre fresco en trozos pequeños.","Cortar apio en trozos pequeños.","Picar chile fresco en trozos finos, retirando las semillas si se quiere menos picante.","Picar cilantro fresco fino y reservar.","Triturar el tercio de lubina reservado con el zumo de lima, el jengibre, el apio y sal hasta obtener una mezcla fina.","Colar la mezcla con un colador fino, presionando con una cuchara, hasta obtener la leche de tigre limpia.","Salpimentar los dados de lubina del bol frío con sal al gusto y remover con suavidad.","Verter la leche de tigre sobre los dados de lubina y remover con cuidado para que el zumo los cubra bien.","Dejar marinar hasta que el pescado quede opaco por fuera pero jugoso por dentro.","Escurrir la cebolla morada y añadirla al bol junto con el chile picado y el cilantro.","Servir de inmediato en cuencos fríos, repartiendo el jugo de la leche de tigre entre los dos."}', 'Ceviche de lubina fresca marinada en leche de tigre, con cebolla morada, cilantro y un toque picante.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"La Thermomix es excelente para picar finamente la cebolla morada, el cilantro, el chile, el jengibre y el apio. Además, permite emulsionar rápidamente la leche de tigre, mezclando los jugos de lima con los aromáticos para una base homogénea y llena de sabor."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_081', 'Trucha con jamón y almendras', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 380, 34, 6, 24, 2, true, true, '{"pescado","frutos_secos","gluten"}', '[{"name":"Trucha limpia sin espinas","amount":2,"unit":"ud"},{"name":"Jamón serrano en lonchas finas","amount":60,"unit":"g"},{"name":"Almendras laminadas","amount":30,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Secar trucha limpia sin espinas con papel de cocina por dentro y por fuera hasta que estén bien secas.","Rellenar el interior de cada trucha con jamón serrano en lonchas finas, repartiendo las lonchas entre las 2 piezas.","Enharinar las truchas por fuera con harina de trigo, sacudiendo el exceso para dejar una capa fina y uniforme.","Calentar aceite de oliva en sartén amplia a fuego medio-alto hasta que el aceite brille.","Colocar las truchas en la sartén y freír 5 min por el primer lado sin moverlas.","Dar la vuelta a las truchas con cuidado y freír 5 min por el segundo lado hasta que estén doradas y hechas por dentro.","Retirar las truchas de la sartén y reservar en un plato caliente.","Tostar almendras laminadas en la misma sartén a fuego medio 2 min, removiendo, hasta que se doren sin quemarse.","Exprimir limón y reservar el zumo.","Picar perejil fino y reservar.","Colocar las truchas en los platos y repartir las almendras tostadas por encima.","Rociar con el zumo de limón y espolvorear el perejil picado antes de servir."}', 'Trucha rellena de jamón serrano y frita, con almendras tostadas por encima, el clásico de río.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Enharina ligeramente la trucha, rocíala con un poco de aceite y cocina 12-15 minutos, añadiendo el jamón y las almendras laminadas los últimos 3-5 minutos para que se doren y queden crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Coloca la trucha en una bandeja con papel de horno y un chorrito de aceite. Hornea durante 15-20 minutos y añade el jamón y las almendras laminadas los últimos 5-7 minutos para que se tuesten y el jamón quede crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_082', 'Sardinas al horno con limón y ajo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'verano', 260, 26, 2, 16, 2, true, true, '{"pescado"}', '[{"name":"Sardinas frescas limpias","amount":400,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar ajo fino.","Picar perejil fino.","Cortar limón en rodajas finas.","Mezclar el ajo picado y el perejil picado con aceite de oliva en un bol pequeño.","Colocar sardinas frescas limpias en una fuente de horno formando una sola capa.","Repartir la mezcla de ajo y perejil por encima de las sardinas.","Salpimentar con sal y colocar las rodajas de limón sobre las sardinas.","Hornear 13 min hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","Servir directamente en la fuente."}', 'Sardinas frescas horneadas con ajo, perejil y limón, con la piel plateada y brillante recién salidas del horno.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca las sardinas en una bandeja, rocía con la mezcla de limón, ajo, perejil y aceite, y hornea durante 18-22 minutos hasta que estén doradas y cocidas."},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 185°C. Dispón las sardinas en una sola capa, rocía con la mezcla de aderezo y cocina por 12-15 minutos, volteándolas a mitad de cocción para un dorado uniforme y piel crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_083', 'Rodaballo al horno con patatas panadera', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 470, 34, 32, 22, 2, true, true, '{"pescado"}', '[{"name":"Rodaballo entero limpio","amount":800,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":45,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas de 3 mm.","Laminar cebolla en juliana fina.","Cortar pimiento verde en tiras finas.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio-bajo.","Sofreír la patata laminada y la cebolla en juliana hasta que estén tiernas, sin que se doren.","Escurrir el exceso de aceite de la patata y la cebolla.","Extender la patata y la cebolla escurridas en una fuente de horno grande formando una cama uniforme.","Salpimentar rodaballo entero limpio por ambos lados.","Colocar el rodaballo encima de la cama de patata y cebolla.","Repartir el ajo picado y las tiras de pimiento verde alrededor del rodaballo.","Rociar el rodaballo y las patatas con el aceite de oliva restante y vino blanco.","Hornear en el centro del horno hasta que el pescado esté opaco y se separe fácilmente de la espina.","Picar perejil fino.","Retirar la fuente del horno y dejar reposar el rodaballo.","Espolvorear el perejil picado sobre el rodaballo y servir directamente en la fuente."}', 'Rodaballo entero al horno sobre una cama de patatas panadera, cocinados juntos con ajo y vino blanco.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Precalienta el horno a 180-200°C. Dispón las patatas y verduras laminadas en una bandeja, coloca el rodaballo encima, riega con aceite y vino, y hornea hasta que el pescado esté en su punto y las patatas tiernas y doradas."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_084', 'Pez espada a la plancha con salsa de mango', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'verano', 310, 30, 14, 14, 2, true, false, '{"pescado"}', '[{"name":"Filetes de pez espada","amount":350,"unit":"g"},{"name":"Mango maduro","amount":150,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Pelar mango maduro y cortar en dados pequeños.","Picar cebolla morada en trozos muy finos.","Picar cilantro fresco en trozos muy finos.","Exprimir lima y reservar el zumo.","Mezclar en un bol el mango, la cebolla morada y el cilantro con el zumo de lima y sal.","Separar la mitad de la mezcla en un bol aparte y triturar esa mitad hasta obtener una salsa homogénea.","Mezclar la parte triturada con la parte en dados hasta integrar. Reservar.","Salar filetes de pez espada por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que empiece a humear.","Colocar los filetes de pez espada en la plancha y cocinar 3 min por el primer lado hasta que se doren.","Dar la vuelta a los filetes de pez espada y cocinar 2 min por el segundo lado hasta que estén dorados.","Retirar los filetes de pez espada de la plancha y reposar 1 min.","Servir los filetes de pez espada con la salsa de mango al lado o por encima."}', 'Pez espada marcado a la plancha con una salsa fresca y tropical de mango, lima y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Cocina el pez espada salpimentado con un poco de aceite durante 10-14 minutos, dándole la vuelta a mitad para un dorado uniforme. Prepara la salsa de mango mientras se cocina el pescado."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca el pez espada en una bandeja con un chorrito de aceite y hornea durante 15-20 minutos, o hasta que esté cocido y ligeramente dorado. Prepara la salsa fresca de mango mientras el pescado está en el horno."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_085', 'Bacalao con tomate y pimientos', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 300, 30, 12, 14, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado en lomos","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y pimiento verde en tiras finas.","Cortar cebolla en tiras finas.","Picar ajo fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el ajo y los pimientos a fuego suave hasta que estén tiernos.","Añadir tomate triturado y azúcar y remover para integrar.","Cocer la salsa a fuego suave hasta que espese, removiendo de vez en cuando.","Colocar bacalao desalado en lomos sobre la salsa con la piel hacia abajo.","Tapar la cazuela y cocer a fuego suave hasta que el bacalao esté hecho y jugoso.","Servir el bacalao napado con la salsa de tomate y pimientos."}', 'Lomos de bacalao cocinados sobre una salsa brillante de tomate y pimientos asomando entre el rojo.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara el sofrito de cebolla y pimientos en una sartén. Añade el tomate triturado y cocina 10 minutos. Vierte la salsa en una fuente de horno, coloca los lomos de bacalao y hornea a 180°C durante 20-25 minutos hasta que el pescado esté tierno y la salsa reducida."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla, pimientos y ajo, y sofríe en el vaso. Añade el tomate triturado y cocina la salsa. Incorpora el bacalao en el Varoma y cocina al vapor sobre la salsa durante 15-20 minutos, hasta que esté en su punto."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla, pimientos y ajo en la olla abierta. Añade el tomate triturado y cocina a presión durante 5-7 minutos. Despresuriza, incorpora los lomos de bacalao y cocina sin presión unos 3-5 minutos más hasta que el pescado esté hecho, evitando que se deshaga."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL),
  ('pescados_086', 'Lenguado meunière con mantequilla y limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'normal', 'all', 340, 28, 8, 22, 2, true, false, '{"pescado","gluten","lactosa"}', '[{"name":"Lenguado limpio","amount":2,"unit":"ud"},{"name":"Harina de trigo","amount":30,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Secar lenguado limpio por ambas caras con papel de cocina hasta eliminar toda la humedad.","Salpimentar los lenguados por ambos lados con sal.","Enharinar los lenguados pasándolos por harina de trigo y sacudir el exceso.","Picar perejil finamente y reservar.","Exprimir limón y reservar el zumo.","Calentar sartén a fuego medio-alto y fundir un tercio de mantequilla hasta que empiece a espumar.","Colocar los lenguados en la sartén y cocinar 3 min por el primer lado hasta que estén dorados.","Dar la vuelta a los lenguados y cocinar 3 min por el segundo lado hasta que estén dorados y hechos por dentro.","Retirar los lenguados de la sartén y reservar en los platos de servicio.","Limpiar la sartén con papel de cocina para eliminar los restos de harina quemada.","Fundir el resto de la mantequilla en la sartén a fuego medio, removiendo, hasta que tome color avellana y huela a tostado.","Retirar la sartén del fuego y añadir el zumo de limón reservado, removiendo para emulsionar.","Verter la mantequilla avellana sobre los lenguados reservados en los platos.","Espolvorear el perejil picado sobre los lenguados y servir de inmediato."}', 'Lenguado dorado a la mantequilla con un toque de limón, bañado en mantequilla avellana recién hecha.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Enharina el lenguado, rocíalo con mantequilla derretida o aceite en spray y cocina en la airfryer precalentada a 190°C durante 12-15 minutos, dándole la vuelta a mitad para un dorado uniforme. Sirve con la salsa de mantequilla, limón y perejil."},{"appliance":"horno","time":25,"difficulty":"normal","prepSummary":"Enharina el lenguado y colócalo en una bandeja de horno con papel de hornear, rociando con mantequilla derretida. Hornea a 200°C durante 15-20 minutos, hasta que esté dorado y cocido, luego añade el limón y perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_087', 'Calamares en su tinta con arroz', 'pescados', 'marisco', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'elaborada', 'all', 480, 28, 55, 16, 4, false, true, '{"moluscos","sulfitos","pescado"}', '[{"name":"Calamares limpios con sus tintas","amount":800,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Bolsitas de tinta de calamar","amount":4,"unit":"ud"},{"name":"Caldo de pescado","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Arroz blanco","amount":320,"unit":"g"}]'::jsonb, '{"Cortar calamares limpios con sus tintas en anillas los cuerpos y en trozos los tentáculos.","Picar cebolla, pimiento verde y ajo muy finos.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el pimiento y el ajo a fuego suave hasta que estén tiernos.","Añadir los calamares y saltear a fuego medio hasta que suelten su agua.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir tomate triturado y sofreír a fuego medio hasta que la salsa espese.","Disolver bolsitas de tinta de calamar en caldo de pescado removiendo hasta integrar.","Verter el caldo con la tinta en la cazuela y remover para mezclar con la salsa.","Tapar la cazuela y cocer a fuego suave hasta que los calamares estén tiernos.","Hervir agua con sal en un cazo a fuego fuerte hasta que rompa a hervir.","Añadir arroz blanco y cocer a fuego medio hasta que esté en su punto.","Escurrir el arroz y reservar caliente.","Servir los calamares en su tinta acompañados del arroz blanco."}', 'Calamares guisados lentamente en su propia tinta, de negro intenso, con arroz blanco como contraste.', '[{"appliance":"horno","time":110,"difficulty":"elaborada","prepSummary":"Prepara el sofrito en una cazuela apta para horno, incorpora los calamares, tintas, vino y caldo. Cocina tapado en el horno precalentado a 160°C durante 90-100 minutos hasta que los calamares estén muy tiernos. El arroz se cocina aparte."},{"appliance":"thermomix","time":90,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras en la Thermomix. Añade los calamares, tintas, vino y caldo, y cocina a 90°C, velocidad cuchara, giro inverso, durante 45-60 minutos. El arroz se puede cocinar en el cestillo o aparte."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla express. Incorpora los calamares, tintas, vino y caldo. Cierra la olla y cocina a presión durante 15-20 minutos. Despresuriza y sirve con arroz blanco cocido aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_088', 'Langostinos a la plancha con alioli', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 260, 26, 2, 16, 2, true, false, '{"marisco","huevo"}', '[{"name":"Langostinos frescos con cáscara","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Sal gorda","amount":5,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar y picar ajo muy fino.","Secar langostinos frescos con cáscara con papel de cocina para que no suelten agua en la plancha.","Introducir el ajo picado y huevo en un vaso de batidora alto.","Añadir aceite de girasol en hilo muy fino sobre el huevo y el ajo, batiendo sin mover el brazo de la batidora hasta que emulsione.","Añadir sal gorda al alioli y reservar en frío.","Calentar plancha a fuego fuerte sin aceite hasta que humee ligeramente.","Colocar los langostinos en la plancha muy caliente en una sola capa.","Salar los langostinos con sal gorda.","Cocinar 2 min por el primer lado hasta que la cáscara empiece a ponerse roja.","Dar la vuelta a los langostinos y cocinar 2 min más hasta que estén completamente rojos y la carne opaca.","Cortar limón en gajos.","Retirar los langostinos de la plancha y colocarlos en una fuente.","Servir de inmediato con los gajos de limón y el alioli aparte."}', 'Langostinos a la plancha, rojos y jugosos, servidos con un alioli blanco recién hecho y limón.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Rocía los langostinos con un poco de aceite y sal gorda y cocínalos durante 8-10 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con la función grill. Coloca los langostinos en una bandeja, rocíalos con un hilo de aceite y sal gorda, y gratina durante 5-7 minutos, vigilando que no se sequen, hasta que estén rosados y ligeramente tostados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_089', 'Buñuelos de bacalao', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 60, 'normal', 'all', 400, 20, 30, 22, 4, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Bacalao desalado desmigado","amount":250,"unit":"g"},{"name":"Harina de trigo","amount":150,"unit":"g"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva suave","amount":500,"unit":"ml"}]'::jsonb, '{"Escurrir bacalao desalado desmigado con las manos, retirar cualquier espina y reservar.","Picar fino ajo y perejil. Reservar juntos.","Batir huevo en un bol grande hasta integrar.","Añadir leche entera al bol y mezclar con el huevo batido.","Tamizar harina de trigo con levadura química e incorporar poco a poco al bol, removiendo hasta obtener una masa sin grumos.","Añadir el bacalao escurrido, el ajo y el perejil picados al bol y mezclar hasta integrar.","Tapar el bol y dejar reposar la masa 15 min a temperatura ambiente.","Calentar aceite de oliva suave en sartén honda a fuego medio hasta que alcance unos 175 °C.","Formar los buñuelos con 2 cucharas y dejarlos caer con cuidado en el aceite caliente, en tandas pequeñas.","Freír cada tanda hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","Escurrir los buñuelos sobre papel absorbente. Repetir con el resto de la masa.","Servir los buñuelos calientes en una fuente."}', 'Buñuelos esponjosos de bacalao, dorados y crujientes por fuera y cremosos por dentro.', '[{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190°C. Rocía ligeramente los buñuelos formados con aceite de oliva y cocínalos en tandas durante 15-20 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Forma los buñuelos y colócalos sobre papel de horno en una bandeja, pincelándolos con un poco de aceite. Hornea a 200°C durante 20-25 minutos, o hasta que estén bien dorados y cocidos por dentro."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"La Thermomix es ideal para preparar la masa de los buñuelos. Pica el ajo y perejil, añade el resto de ingredientes y mezcla a velocidad media hasta obtener una masa homogénea en pocos minutos. Luego, fríe los buñuelos en sartén como de costumbre."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_090', 'Marmitako de bonito', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 380, 30, 32, 14, 4, true, true, '{"pescado"}', '[{"name":"Bonito fresco en tacos","amount":500,"unit":"g"},{"name":"Patata","amount":600,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón dulce","amount":6,"unit":"g"},{"name":"Caldo de pescado","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"}]'::jsonb, '{"Picar cebolla, pimiento verde, pimiento rojo y ajo muy fino.","Pelar patata y cascarlas: cortar un poco y romper con la punta del cuchillo para que suelten almidón.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, los pimientos y el ajo picados a fuego suave hasta que estén pochados.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua.","Añadir pimentón dulce y remover sin parar durante 20 segundos para que no se queme.","Añadir las patatas cascadas y mezclar con el sofrito para que se impregnen.","Verter caldo de pescado, tapar la cazuela y llevar a ebullición a fuego medio.","Cocer tapado a fuego suave hasta que las patatas estén tiernas.","Añadir bonito fresco en tacos a la cazuela repartiendo los trozos por toda la superficie.","Cocer a fuego suave hasta que el bonito esté justo hecho, sin remover para que no se deshaga.","Reposar la cazuela apartada del fuego antes de servir.","Servir bien caliente en cazuela o platos hondos."}', 'Guiso marinero de patata y bonito en salsa roja, el clásico plato de barco vasco.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno. Añade el tomate, pimentón, patatas y caldo. Lleva a ebullición y hornea a 180°C durante 30-40 minutos hasta que las patatas estén tiernas. Incorpora el bonito los últimos 5 minutos."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Trocea y sofríe las verduras. Añade las patatas, tomate, pimentón y caldo, y cocina 25-30 minutos a 100°C, giro inverso, velocidad cuchara. Incorpora el bonito al final y deja reposar unos minutos."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla. Añade las patatas, tomate, pimentón y caldo. Cierra y cocina 10-12 minutos desde que sube la presión. Despresuriza, añade el bonito y deja reposar 5 minutos con el calor residual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_091', 'Pulpo a feira', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'all', 260, 28, 14, 10, 4, true, true, '{"moluscos"}', '[{"name":"Pulpo congelado limpio","amount":1200,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Pimentón dulce","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":3,"unit":"g"},{"name":"Sal gorda","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"}]'::jsonb, '{"Descongelar pulpo congelado limpio en la nevera hasta que esté completamente blando.","Llevar una olla grande con agua abundante a ebullición fuerte.","Asustar el pulpo sumergiéndolo y sacándolo del agua hirviendo 3 veces sujetándolo por la cabeza.","Cocer el pulpo a fuego medio 45 min, hasta que al pinchar en la parte más gruesa con un palillo entre con facilidad.","Pelar patata y cortar en rodajas gruesas de unos 2 cm.","Retirar el pulpo del agua y reservar en un plato; dejar el agua de cocción en la olla a fuego medio.","Reposar el pulpo 5 min fuera del agua antes de cortarlo.","Cocer las patatas en el agua de cocción del pulpo a fuego medio, hasta que estén tiernas.","Cortar el pulpo en rodajas con unas tijeras empezando por los tentáculos.","Escurrir las patatas y colocarlas como base en una tabla de madera o plato de servir.","Repartir las rodajas de pulpo por encima de las patatas.","Espolvorear sal gorda de manera uniforme sobre el pulpo y las patatas.","Espolvorear pimentón dulce y pimentón picante por encima.","Regar con aceite de oliva virgen extra en crudo y servir de inmediato."}', 'Pulpo cocido y tierno sobre patatas, servido sobre madera con pimentón y aceite en crudo, al estilo gallego.', '[{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Cuece el pulpo en la olla express con un vaso de agua durante 20-25 minutos desde que sube la válvula. Las patatas se pueden cocer en el mismo líquido o aparte para un resultado tierno y rápido."},{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Cocina el pulpo troceado en el vaso con agua (o al vapor en el Varoma) a 95-100°C durante 40-60 minutos, y las patatas en el Varoma simultáneamente para un cocinado preciso y uniforme."},{"appliance":"vaporera","time":90,"difficulty":"normal","prepSummary":"Cuece el pulpo y las patatas en la vaporera durante 60-90 minutos hasta que estén muy tiernos. Este método mantiene mejor los sabores y la textura."},{"appliance":"horno","time":180,"difficulty":"normal","prepSummary":"Cocina el pulpo a baja temperatura (120-140°C) en un recipiente tapado con un poco de agua o sus propios jugos durante 2-3 horas hasta que esté muy tierno. Las patatas se cuecen aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_092', 'Cazuela de fideos con rape y gambas', 'pescados', 'marisco', 'pasta', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 420, 28, 42, 14, 4, true, true, '{"pescado","marisco","gluten"}', '[{"name":"Fideos gruesos","amount":320,"unit":"g"},{"name":"Colas de rape en trozos","amount":250,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Cabezas y cáscaras de gamba","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Caldo de pescado","amount":700,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Calentar aceite de oliva en una cazuela a fuego fuerte.","Saltear cabezas y cáscaras de gamba 5 min, aplastándolas con una cuchara hasta que suelten todo el jugo.","Añadir caldo de pescado y llevar a ebullición.","Hervir 10 min a fuego medio para extraer todo el sabor de las cáscaras.","Picar cebolla, ajo y pimiento rojo finos.","Colar el caldo con un colador fino, presionando las cáscaras para extraer todo el jugo, y reservar.","Calentar el resto del aceite de oliva en la cazuela limpia a fuego medio.","Sofreír la cebolla picada, el ajo picado y el pimiento rojo picado 10 min hasta que estén tiernos.","Añadir tomate triturado y sofreír 5 min hasta que espese y pierda el agua.","Incorporar fideos gruesos y saltear 2 min hasta que se doren ligeramente en el sofrito.","Verter el caldo reservado sobre los fideos y mezclar.","Añadir azafrán y remover para distribuirlo bien.","Cocer a fuego medio 8 min sin remover hasta que los fideos absorban casi todo el caldo.","Añadir colas de rape en trozos y cocer 4 min hasta que estén opacos y firmes.","Incorporar gambas peladas y cocer 2 min hasta que estén rosadas.","Retirar del fuego y reposar 2 min tapado antes de servir.","Servir en la misma cazuela en la mesa."}', 'Fideos dorados en cazuela con rape y gambas, en un caldo de pescado con azafrán, marisco asomando entre ellos.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno en la encimera. Añade el caldo y los fideos, lleva a ebullición y hornea a 180°C durante 20-25 minutos. Incorpora el rape y las gambas en los últimos 5-7 minutos para que se cocinen a la perfección."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Realiza el sofrito programando velocidad y temperatura. Luego, añade el caldo y los fideos, cocinando a temperatura Varoma o 100°C con giro inverso. Incorpora el rape y las gambas en los últimos minutos para una cocción precisa."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla abierta. Añade el caldo y los fideos, cierra la olla y cocina a presión durante 3-5 minutos. Despresuriza, añade el rape y las gambas, y cocina unos minutos más sin presión hasta que estén hechos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_093', 'Salpicón de marisco', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'verano', 220, 24, 8, 10, 2, true, false, '{"marisco","moluscos","sulfitos"}', '[{"name":"Langostinos cocidos pelados","amount":150,"unit":"g"},{"name":"Mejillones cocidos","amount":100,"unit":"g"},{"name":"Palitos de cangrejo o surimi","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar langostinos cocidos pelados en trozos de bocado si son grandes.","Cortar palitos de cangrejo o surimi en rodajas finas.","Picar pimiento rojo en dados muy pequeños y regulares.","Picar pimiento verde en dados muy pequeños y regulares.","Picar cebolla morada en dados muy pequeños y regulares.","Picar tomate en dados pequeños, retirando el exceso de agua y semillas.","Mezclar en un bol grande los langostinos, mejillones cocidos y los palitos con todas las verduras picadas.","Añadir aceite de oliva virgen extra y vinagre de vino sobre la mezcla.","Remover bien hasta que todos los ingredientes queden impregnados del aliño.","Tapar el bol y reservar en la nevera al menos 60 min para que se integren los sabores.","Servir bien frío en cuencos o copas individuales."}', 'Salpicón fresco y colorido de langostinos, mejillones y verdura picada, perfecto para el aperitivo de verano.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Pica las verduras (pimientos, cebolla, tomate) en el vaso en varios golpes de turbo o velocidad 4-5. Añade el marisco cocido y el aliño, y mezcla suavemente a velocidad cuchara para integrar todos los ingredientes sin triturar."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_094', 'Vieiras gratinadas con jamón', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 30, 'normal', 'all', 260, 20, 10, 15, 2, true, false, '{"moluscos","lactosa","gluten"}', '[{"name":"Vieiras limpias en su concha","amount":8,"unit":"ud"},{"name":"Jamón serrano picado","amount":40,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno en modo grill a 220 °C.","Picar cebolla muy fina.","Picar perejil fino y reservar.","Separar el coral de la nuez de cada vieiras limpias en su concha y limpiar bien las conchas.","Cortar las nueces de vieira en 2 o 3 trozos y reservar.","Fundir la mitad de mantequilla en sartén a fuego suave.","Sofreír la cebolla picada en la mantequilla fundida a fuego suave hasta que esté blanda.","Añadir jamón serrano picado y sofreír a fuego medio 2 min.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir los trozos de vieira y los corales a la sartén y saltear 1 min a fuego fuerte.","Retirar la sartén del fuego y repartir la mezcla entre las conchas limpias.","Fundir el resto de la mantequilla en la sartén limpia a fuego suave.","Mezclar pan rallado con la mantequilla fundida en un bol hasta obtener una mezcla arenosa.","Espolvorear la mezcla de pan rallado sobre cada concha rellena de forma uniforme.","Gratinar las conchas en el horno a 220 °C en modo grill hasta que la superficie esté dorada.","Espolvorear el perejil picado sobre las conchas y servir de inmediato."}', 'Vieiras gratinadas con jamón y pan rallado dorado, servidas en su propia concha individual.', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón, mezcla con el vino y un poco de pan rallado. Coloca las vieiras en sus conchas, cubre con la mezcla, más pan rallado y un trocito de mantequilla. Gratina en el horno precalentado a 200°C durante 15-20 minutos hasta que estén doradas y burbujeantes."},{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito de cebolla y jamón en una sartén. Monta las vieiras en sus conchas o en recipientes aptos para airfryer con la mezcla, pan rallado y mantequilla. Cocina en la airfryer precalentada a 190°C durante 8-12 minutos, vigilando que el gratinado quede dorado y las viei"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_095', 'Congrio en salsa verde con almejas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'elaborada', 'all', 300, 30, 8, 14, 2, true, true, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Congrio en rodajas","amount":400,"unit":"g"},{"name":"Almejas","amount":150,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Harina de trigo","amount":12,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"}]'::jsonb, '{"Sumergir almejas en agua fría con sal para que suelten la arena.","Laminar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela ancha a fuego suave.","Sofreír el ajo laminado a fuego suave hasta que empiece a dorar.","Añadir harina de trigo y remover sin parar hasta que esté integrada sin coger color.","Verter vino blanco poco a poco sin dejar de remover hasta que la salsa ligue.","Añadir caldo de pescado poco a poco sin dejar de remover hasta obtener una salsa sin grumos.","Añadir la mitad del perejil picado y remover para integrarlo en la salsa.","Colocar congrio en rodajas en la cazuela en una sola capa.","Escurrir las almejas y repartirlas entre las rodajas de congrio.","Tapar la cazuela y cocer a fuego suave hasta que las almejas se abran y el congrio esté hecho.","Espolvorear con el resto del perejil picado y servir en la misma cazuela."}', 'Congrio en una salsa verde ligada y brillante, con almejas abiertas alrededor recién cocinadas.', '[{"appliance":"horno","time":45,"difficulty":"elaborada","prepSummary":"Prepara la salsa verde en una cazuela apta para horno, sofriendo el ajo y añadiendo la harina, vino y caldo hasta espesar. Incorpora el congrio y las almejas, y hornea a 180°C durante unos 20-25 minutos hasta que el pescado esté tierno y las almejas abiertas, vigilando que no se "},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Pica el ajo y perejil. Prepara la salsa verde en el vaso, sofriendo el ajo y luego añadiendo la harina, vino y caldo para cocinarla. Incorpora el congrio y las almejas y cocina a 90-100°C, velocidad cuchara inversa, durante 15-20 minutos, hasta que el pescado esté hecho y las alm"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_096', 'Salmonetes a la plancha con romesco', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 340, 28, 10, 20, 2, true, false, '{"pescado","frutos_secos","gluten"}', '[{"name":"Salmonetes limpios","amount":400,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Pimiento choricero o ñora hidratado","amount":20,"unit":"g"},{"name":"Almendras tostadas","amount":25,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar el horno a 200 °C.","Lavar tomate maduro y ajo y disponerlos en una bandeja con piel, sin pelar.","Hornear el tomate y el ajo a 200 °C durante 20 min hasta que estén blandos y la piel esté chamuscada.","Secar salmonetes limpios con papel de cocina mientras hornea el tomate.","Raspar la pulpa de pimiento choricero o ñora hidratado con una cuchara, desechando la piel.","Retirar el tomate y el ajo del horno cuando estén blandos y dejar templar 5 min.","Pelar el tomate y el ajo una vez templados.","Triturar el tomate y el ajo pelados junto con la pulpa del pimiento, almendras tostadas, pan frito, vinagre de vino y aceite de oliva hasta obtener una salsa fina.","Reservar el romesco a temperatura ambiente.","Calentar plancha a fuego fuerte hasta que humee.","Añadir aceite de oliva sobre la plancha caliente.","Cocinar los salmonetes 3 min por el primer lado sin moverlos hasta que la piel esté crujiente.","Dar la vuelta a los salmonetes y cocinar 2 min más hasta que la carne esté opaca.","Servir los salmonetes recién hechos con el romesco al lado."}', 'Salmonetes de piel rosada y crujiente a la plancha, con una salsa romesco de contraste.', '[{"appliance":"airfryer","time":45,"difficulty":"facil","prepSummary":"Para los salmonetes, cocínalos directamente en la airfryer a 190°C durante 10-12 minutos, dándoles la vuelta a mitad para un dorado uniforme. Para el romesco, asa los tomates, pimiento y ajo en la airfryer a 180°C por 15-20 minutos, luego tritura con el resto de ingredientes."},{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Para el romesco, asa los tomates, pimiento y ajo en el horno a 200°C durante 20-25 minutos. Luego, hornea los salmonetes a 210°C por 15-18 minutos hasta que estén dorados, pudiendo usar el grill al final. Tritura los ingredientes asados con el resto para la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_097', 'Tacos de pescado estilo Baja California', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 420, 26, 40, 18, 2, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Filetes de merluza o abadejo","amount":300,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Cerveza fría","amount":100,"unit":"ml"},{"name":"Tortillas de trigo pequeñas","amount":6,"unit":"ud"},{"name":"Repollo morado","amount":100,"unit":"g"},{"name":"Yogur natural","amount":60,"unit":"g"},{"name":"Mayonesa","amount":30,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"}]'::jsonb, '{"Cortar filetes de merluza o abadejo en tiras de unos 2 cm de ancho.","Laminar repollo morado en juliana muy fina.","Exprimir lima y reservar el zumo.","Picar cilantro fresco fino.","Mezclar yogur natural, mayonesa, la mitad del zumo de lima y el cilantro picado hasta obtener una salsa homogénea.","Mezclar harina de trigo con cerveza fría hasta obtener una masa de rebozado ligera y sin grumos.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta que alcance unos 180 °C.","Pasar las tiras de merluza por la masa de rebozado, cubriendo bien cada pieza.","Freír las tiras rebozadas en tandas, sin amontonarlas, hasta que estén doradas y crujientes.","Escurrir las tiras fritas sobre papel absorbente.","Calentar tortillas de trigo pequeñas en sartén seca a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir el repollo en juliana sobre cada tortilla caliente.","Colocar 2 o 3 tiras de merluza rebozada sobre el repollo en cada tortilla.","Añadir un poco de salsa cremosa encima y unas gotas del zumo de lima restante.","Servir de inmediato."}', 'Tacos de pescado rebozado y crujiente, con repollo morado y una salsa cremosa de lima, estilo Baja California.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Para los filetes de pescado, sumérgelos en la mezcla de harina y cerveza, rocía con un poco de aceite y cocina en la airfryer a 190°C durante 15-20 minutos, volteando a mitad, hasta que estén dorados y crujientes. Las tortillas se pueden calentar brevemente en la airfryer también"},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Reboza los filetes de merluza y colócalos en una bandeja de horno con papel de hornear, rociando con un poco de aceite. Hornea a 200°C (con calor arriba y abajo) durante 20-25 minutos, o hasta que estén dorados y cocidos, volteando una vez. Las tortillas se pueden calentar en el "}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_098', 'Bowl de salmón, arroz y sriracha', 'pescados', 'pescado_azul', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 780, 36, 60, 40, 2, false, true, '{"pescado","huevo","soja","sesamo"}', '[{"name":"Salmón (lomos)","amount":280,"unit":"g"},{"name":"Arroz blanco","amount":140,"unit":"g"},{"name":"Aguacate","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Edamame","amount":60,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Sriracha","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"}]'::jsonb, '{"Cocer arroz blanco en agua con sal según el tiempo del paquete.","Mezclar mayonesa con sriracha y salsa de soja hasta obtener una crema homogénea.","Cortar pepino en bastones finos.","Laminar aguacate.","Picar cebollino fino.","Escurrir el arroz cocido y reservar templado.","Salpimentar salmón (lomos) por ambas caras.","Calentar sartén a fuego fuerte y dorar los lomos de salmón 2 min por cada lado, hasta que estén dorados por fuera y jugosos por dentro.","Retirar el salmón del fuego y desmenuzarlo en lascas grandes con un tenedor.","Repartir el arroz templado en 2 boles.","Colocar encima las lascas de salmón, el aguacate laminado, el pepino en bastones y edamame por zonas.","Rociar la crema de mayonesa y sriracha sobre el bowl.","Espolvorear sésamo tostado y el cebollino picado, y servir."}', 'Bowl templado de salmón desmenuzado y arroz con aguacate, edamame y una cremosa mayonesa picante de sriracha.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el salmón en la airfryer a 190°C durante 12-15 minutos para un exterior ligeramente crujiente y un interior jugoso. Mientras, prepara el arroz por separado y el resto de ingredientes para montar el bowl."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Hornea el salmón a 200°C durante 15-20 minutos hasta que esté cocido y ligeramente dorado. Prepara el arroz y el resto de ingredientes frescos mientras el salmón se cocina."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz en el cestillo y el salmón (junto con el edamame) en el Varoma simultáneamente durante unos 20 minutos. Esto optimiza el tiempo y asegura una cocción perfecta y jugosa de todos los componentes principales."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cocina el arroz en un recipiente apto para vaporera y el salmón (y edamame) en las bandejas superiores durante unos 20-25 minutos. El salmón quedará muy jugoso y saludable, manteniendo todos sus nutrientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_099', 'Rodaballo a la plancha con patatas panadera y velouté de marisco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 590, 30, 34, 37, 2, true, true, '{"pescado","marisco","lactosa","gluten","sulfitos"}', '[{"name":"Rodaballo (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Fumet de marisco","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas de 3 mm de grosor.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio-bajo.","Añadir las patatas y la cebolla y confitar a fuego suave hasta que estén tiernas y ligeramente doradas.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina y remover sin parar hasta formar un roux liso.","Verter vino blanco y remover hasta que reduzca a la mitad.","Incorporar fumet de marisco poco a poco sin dejar de remover hasta obtener una salsa lisa y sin grumos.","Añadir nata para cocinar y cocer a fuego suave hasta que la velouté espese ligeramente.","Salpimentar la velouté y reservar caliente fuera del fuego.","Salpimentar rodaballo (filetes) por ambas caras.","Calentar plancha a fuego fuerte hasta que humee.","Marcar los filetes de rodaballo por el lado de la piel durante 2-3 min hasta que estén dorados.","Dar la vuelta a los filetes y marcar 1-2 min por el otro lado hasta que estén jugosos.","Repartir las patatas confitadas en la base de cada plato.","Colocar encima el rodaballo a la plancha y napar con la velouté caliente."}', 'Rodaballo a la plancha sobre patatas panadera doradas, napado con una velouté cremosa de marisco.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_100', 'Bacalao confitado sobre puré de coliflor con pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'elaborada', 'all', 590, 32, 11, 46, 2, true, false, '{"pescado","lactosa"}', '[{"name":"Bacalao desalado (lomos)","amount":320,"unit":"g"},{"name":"Coliflor","amount":400,"unit":"g"},{"name":"Aceite de oliva suave","amount":70,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Cortar coliflor en arbolitos pequeños.","Llevar a ebullición una olla con agua y sal. Añadir los arbolitos de coliflor y cocer 15 min hasta que estén muy tiernos.","Laminar ajo en láminas finas.","Calentar aceite de oliva suave en sartén a fuego suave. Sofreír el ajo laminado hasta que empiece a dorarse.","Retirar el ajo dorado de la sartén y reservar. Mantener el aceite en la sartén fuera del fuego.","Escurrir la coliflor cocida y dejar reposar 1 min para que pierda el exceso de vapor.","Triturar la coliflor escurrida con nata para cocinar, mantequilla y sal hasta obtener un puré fino y sedoso.","Reservar el puré caliente tapado.","Calentar el aceite reservado en la sartén a fuego muy suave, sin que llegue a humear.","Introducir bacalao desalado (lomos) con la piel hacia arriba. Confitar 9 min sin que el aceite llegue a hervir, hasta que la carne se separe en lascas.","Retirar los lomos con cuidado y reservar calientes tapados.","Colar el aceite de confitar en un cazo, dejando en el colador la gelatina que ha soltado el bacalao.","Añadir la gelatina del colador al cazo. Mover el cazo en círculos a fuego muy suave, incorporando el aceite poco a poco.","Continuar moviendo el cazo hasta que la salsa emulsione y adquiera un color blanquecino y textura untuosa.","Picar perejil fino.","Repartir el puré de coliflor en la base de los platos. Colocar encima los lomos de bacalao confitado.","Napar con el pil-pil. Terminar con el ajo laminado reservado y el perejil picado."}', 'Bacalao confitado a baja temperatura sobre un puré sedoso de coliflor, napado con un pil-pil brillante.', '[{"appliance":"horno","time":65,"difficulty":"elaborada","prepSummary":"El bacalao se confita en una fuente con aceite a baja temperatura (90-100°C) en el horno durante 30-40 minutos. La coliflor se puede asar en el horno para el puré, o cocer al vapor aparte, y el pil-pil se emulsiona en un cazo en la encimera."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"La Thermomix permite confitar el bacalao a baja temperatura (90°C, velocidad cuchara) en el vaso. La coliflor se cuece al vapor en el Varoma y se tritura en el vaso para el puré, y el pil-pil se emulsiona fácilmente con el aceite del confitado y los ajos, controlando temperatura "}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_101', 'Filete de lubina con patatas panadera y beurre blanc de alcaparras', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 630, 35, 28, 44, 2, false, false, '{"pescado","lactosa","sulfitos"}', '[{"name":"Lubina (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Chalota","amount":30,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Vinagre de vino blanco","amount":10,"unit":"ml"},{"name":"Alcaparras","amount":20,"unit":"g"}]'::jsonb, '{"Pelar patata y laminarlas en rodajas finas de unos 3 mm.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en una sartén amplia a fuego medio-bajo.","Añadir las patatas laminadas y la cebolla en juliana a la sartén.","Confitar las patatas y la cebolla a fuego suave durante 16 min, hasta que estén tiernas y ligeramente doradas.","Picar chalota muy fina mientras las patatas confitan.","Picar alcaparras finamente y reservar.","Retirar las patatas del fuego, salpimentar y reservar en un lugar templado.","Verter vino blanco y vinagre de vino blanco junto con la chalota picada en un cazo pequeño.","Reducir a fuego medio hasta que quede apenas 2 cucharadas de líquido, unos 5 min.","Cortar mantequilla en dados fríos mientras la reducción se concentra.","Bajar el fuego al mínimo e incorporar los dados de mantequilla fría de uno en uno, batiendo sin parar.","Remover hasta que la salsa emulsione y quede cremosa y brillante.","Añadir las alcaparras picadas, mezclar y retirar del fuego. Reservar caliente sin que vuelva a hervir.","Salpimentar lubina (filetes) por ambos lados.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva sobre la plancha y colocar los filetes con la piel hacia abajo.","Cocinar los filetes por el lado de la piel 3 min, hasta que la piel esté crujiente y dorada.","Dar la vuelta a los filetes y cocinar 1 min más por el lado de la carne, hasta que estén justos de punto.","Repartir las patatas panadera en la base de los platos y colocar los filetes encima con la piel hacia arriba.","Salsear generosamente con el beurre blanc de alcaparras y servir de inmediato."}', 'Filete de lubina a la plancha con patatas panadera y una mantecosa salsa beurre blanc de alcaparras.', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Para las patatas panadera, corta las patatas y cebolla en rodajas finas, mézclalas con aceite de oliva y sal, y hornea en una fuente a 180°C durante 30-35 minutos. Añade los filetes de lubina sobre las patatas o en una bandeja aparte y hornea 10-12 minutos más hasta que estén coc"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_102', 'Pescadilla frita con patatas paja y alioli de limón', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 780, 33, 50, 46, 2, true, false, '{"pescado","gluten","huevo"}', '[{"name":"Pescadilla (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Mayonesa","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar patata y laminar en juliana muy fina con mandolina.","Sumergir la patata en agua fría durante 10 min para eliminar el exceso de almidón.","Escurrir la patata y secarla bien con un paño limpio.","Rallar la piel de limón y exprimir la mitad.","Picar ajo muy fino.","Mezclar mayonesa con el ajo picado, la ralladura y el zumo de limón hasta integrar.","Reservar el alioli de limón en frío.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír la patata en tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y salar al gusto.","Salpimentar pescadilla (filetes).","Pasar los filetes por harina, sacudiendo el exceso.","Freír los filetes en el mismo aceite caliente 2 min por el primer lado, hasta que estén dorados.","Dar la vuelta a los filetes y freír 2 min más por el otro lado, hasta que estén dorados y crujientes.","Escurrir los filetes sobre papel absorbente.","Servir la pescadilla con la patata paja y el alioli de limón al lado."}', 'Pescadilla rebozada y frita bien crujiente, con una nube de patatas paja y un alioli suave de limón.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Para la pescadilla y las patatas, precalienta la airfryer a 190°C. Cocina el pescado enharinado y ligeramente rociado con aceite durante 12-15 minutos. Las patatas cortadas finas, también con un poco de aceite, cocínalas en tandas si es necesario, unos 15-20 minutos, agitando a m"},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea la pescadilla enharinada y rociada con un hilo de aceite durante 15-20 minutos. Las patatas cortadas finas, con un poco de aceite y sal, hornéalas en una sola capa por 25-35 minutos, volteándolas a mitad, hasta que estén doradas y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_103', 'Salmón a la plancha con puré de boniato y salsa teriyaki', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 660, 36, 50, 33, 2, true, true, '{"pescado","lactosa","soja","sesamo"}', '[{"name":"Salmón (lomos)","amount":320,"unit":"g"},{"name":"Boniato","amount":400,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":40,"unit":"ml"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Maicena","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en trozos de tamaño similar.","Cocer el boniato en una olla con agua abundante y sal hasta que esté muy tierno.","Rallar jengibre fresco y picar ajo muy fino.","Mezclar salsa de soja, miel, el jengibre rallado y el ajo picado en un cazo pequeño.","Disolver maicena en una cucharadita de agua fría.","Llevar el cazo a fuego medio y añadir la maicena disuelta, removiendo hasta que la salsa espese y quede brillante.","Retirar el cazo del fuego y añadir aceite de sésamo. Reservar la salsa teriyaki.","Escurrir el boniato cocido.","Calentar leche en el mismo cazo a fuego suave.","Triturar el boniato escurrido con mantequilla y la leche caliente hasta obtener un puré fino.","Salpimentar el puré y reservar caliente tapado.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Salpimentar salmón (lomos) por ambos lados.","Colocar los lomos de salmón con la piel hacia abajo y cocinar hasta que la piel esté dorada y crujiente.","Dar la vuelta a los lomos y cocinar por el otro lado hasta que el salmón esté jugoso por dentro.","Pincelar los lomos con parte de la salsa teriyaki y retirar del fuego en cuanto se glaseen.","Repartir el puré de boniato en la base de los platos y colocar encima cada lomo de salmón.","Salsear con el resto de la salsa teriyaki y espolvorear sésamo tostado por encima."}', 'Salmón a la plancha glaseado en teriyaki casero, servido sobre un cremoso puré de boniato.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina el salmón a 180°C durante 12-15 minutos para un exterior crujiente y jugoso. El boniato, cortado en cubos, se cocina a 180°C por 15-20 minutos hasta ablandar y luego se tritura para el puré. La salsa teriyaki se prepara aparte en un cazo."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa el salmón a 190°C durante 15-20 minutos hasta que esté tierno y jugoso. El boniato se asa entero o en trozos a la misma temperatura por 30-40 minutos, luego se tritura para el puré. La salsa se elabora en un cazo aparte."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Prepara el puré de boniato cociéndolo al vapor en el Varoma y luego triturándolo con el resto de ingredientes. El salmón se cocina al vapor en el Varoma simultáneamente. La salsa teriyaki se elabora y espesa en el vaso de la Thermomix, picando previamente el jengibre y ajo."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cocina el boniato al vapor hasta que esté muy tierno para el puré. El salmón se cuece al vapor en la misma vaporera, resultando jugoso y saludable. La salsa teriyaki se prepara en un cazo aparte."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Cuece el boniato en la olla express con un poco de agua hasta que esté muy tierno (aprox. 5-7 min desde que sube la válvula) para el puré. El salmón se cocina al vapor en la misma olla en una cesta, muy rápidamente (3-5 min). La salsa se prepara en un cazo aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_104', 'Rape a la plancha con patatas panadera y salsa verde de almejas', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 550, 40, 36, 24, 2, true, true, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Rape (cola, en medallones)","amount":350,"unit":"g"},{"name":"Almejas","amount":200,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Escurrir las almejas y reservar.","Pelar patata y laminar en rodajas finas de unos 3 mm.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave 18 min, hasta que estén tiernas y ligeramente doradas.","Laminar ajo en láminas finas.","Picar perejil fino.","Salpimentar las patatas confitadas y reservar en la sartén fuera del fuego.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","Añadir harina y remover sin parar durante 1 min para tostar la harina sin que coja color.","Verter vino blanco y remover hasta que evapore el alcohol, unos 2 min.","Añadir 60 ml de agua y remover hasta obtener una salsa ligera y homogénea.","Incorporar las almejas escurridas, tapar la cazuela y cocer a fuego medio hasta que se abran, unos 4 min.","Retirar las almejas que no se hayan abierto. Añadir el perejil picado y remover para ligar la salsa.","Salpimentar rape (cola, en medallones) por ambas caras.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Marcar los medallones de rape 3 min por el primer lado, sin moverlos, hasta que estén opacos por la mitad.","Dar la vuelta a los medallones y marcar 3 min más por el otro lado, hasta que estén opacos y firmes al tacto.","Repartir las patatas panadera en la base de los platos.","Colocar los medallones de rape encima de las patatas y napar con la salsa verde de almejas.","Servir de inmediato."}', 'Medallones de rape a la plancha con patatas panadera y una salsa verde ligada con almejas abiertas.', '[]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_105', 'Dorada al horno con patatas panadera y romesco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 720, 48, 36, 40, 2, true, true, '{"pescado","frutos_secos","gluten","sulfitos"}', '[{"name":"Dorada (limpia, entera)","amount":700,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Pimiento choricero (pulpa de ñora)","amount":15,"unit":"g"},{"name":"Almendra tostada","amount":30,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas finas de unos 3 mm.","Pelar cebolla y cortar en aros finos.","Disponer las patatas y la cebolla en una bandeja de horno en capas uniformes.","Regar las patatas y la cebolla con aceite de oliva y salpimentar.","Hornear la bandeja a 200 °C durante 20 min, hasta que las patatas empiecen a estar tiernas.","Tostar pan en sartén sin aceite a fuego medio hasta que esté dorado.","Tostar almendra tostada en la misma sartén a fuego medio hasta que tome color.","Asar tomate y ajo con piel en la sartén a fuego medio hasta que estén blandos.","Pelar el tomate y el ajo asados cuando estén templados.","Triturar el pan, las almendras, el tomate, el ajo, pimiento choricero (pulpa de ñora) y vinagre de vino.","Añadir el resto del aceite de oliva al vaso mientras se tritura, hasta obtener una salsa espesa y homogénea.","Salpimentar el romesco al gusto y reservar.","Retirar la bandeja del horno y salpimentar dorada (limpia, entera) por dentro y por fuera.","Colocar la dorada sobre la cama de patatas y cebolla en la bandeja.","Hornear a 200 °C durante 20 min, hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","Servir la dorada sobre las patatas y la cebolla, acompañada del romesco aparte."}', 'Dorada entera al horno sobre patatas panadera, con un romesco tostado de almendra y ñora.', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Precalienta el horno a 190°C. En una bandeja, dispón la dorada limpia junto con las patatas y cebolla en rodajas finas, riega con aceite de oliva y hornea durante unos 45-50 minutos. La salsa romesco se prepara aparte y se sirve como acompañamiento."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  main_protein = excluded.main_protein,
  main_base = excluded.main_base,
  meal_roles = excluded.meal_roles,
  type = excluded.type,
  base_dish_id = excluded.base_dish_id,
  required_appliance = excluded.required_appliance,
  time_minutes = excluded.time_minutes,
  difficulty = excluded.difficulty,
  season = excluded.season,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g = excluded.carbs_g,
  fat_g = excluded.fat_g,
  base_servings = excluded.base_servings,
  kid_friendly = excluded.kid_friendly,
  tupper_friendly = excluded.tupper_friendly,
  allergens = excluded.allergens,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  description = excluded.description,
  methods = excluded.methods,
  product_aliases = excluded.product_aliases,
  apetecible = excluded.apetecible,
  montaje = excluded.montaje,
  can_be_garnish = excluded.can_be_garnish,
  main_ingredients = excluded.main_ingredients,
  sauce_id = excluded.sauce_id;

insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('pescados_106', 'Atún a la plancha con puré de patata y salsa teriyaki', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 500, 42, 40, 17, 2, true, true, '{"pescado","lactosa","soja","sesamo"}', '[{"name":"Atún (lomo fresco)","amount":320,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":40,"unit":"ml"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Maicena","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarla en trozos de tamaño similar.","Cocer la patata en un cazo con agua y salsa de soja hasta que esté tierna.","Rallar jengibre fresco.","Picar ajo muy fino.","Mezclar salsa de soja, miel, el jengibre rallado y el ajo picado en un cazo pequeño.","Disolver maicena en una cucharada de agua fría y añadir la mezcla al cazo.","Llevar el cazo a fuego medio, removiendo, hasta que la salsa espese y brille.","Retirar del fuego y añadir aceite de sésamo. Reservar.","Escurrir la patata cocida cuando esté tierna.","Calentar leche en el mismo cazo a fuego suave hasta que esté caliente.","Triturar la patata escurrida con mantequilla y la leche caliente hasta obtener un puré fino.","Salpimentar el puré y reservar caliente.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Salpimentar atún (lomo fresco).","Marcar el atún en la plancha 1-2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","Cortar el atún en filetes gruesos y pincelar con parte de la salsa teriyaki.","Repartir el puré en la base de los platos y colocar el atún encima.","Salsear con el resto de la teriyaki y espolvorear sésamo tostado. Servir de inmediato."}', 'Atún marcado a la plancha, rosado por dentro, sobre puré de patata con un glaseado teriyaki.', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Cocina las patatas al vapor en el cestillo y Varoma, luego tritura para el puré con mantequilla y leche. Prepara la salsa teriyaki en el vaso y cocina el atún al vapor en el Varoma, aprovechando el vapor de las patatas."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Cocina las patatas al vapor en la olla a presión hasta que estén tiernas, luego tritura para el puré. Prepara la salsa teriyaki en la misma olla sin presión y cocina el atún al vapor en una cesta dentro de la olla."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_107', 'Coca de recapte con sardinas ahumadas', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 570, 20, 70, 22, 4, false, true, '{"pescado","gluten"}', '[{"name":"Harina de fuerza","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Levadura de panadería seca","amount":5,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":150,"unit":"g"},{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Sardinas ahumadas","amount":200,"unit":"g"}]'::jsonb, '{"Disolver levadura de panadería seca en 150 ml de agua templada y dejar reposar hasta que haga espuma.","Mezclar harina de fuerza con sal en un bol grande.","Añadir el agua con levadura y aceite de oliva a la harina.","Amasar la mezcla durante 10 min hasta obtener una masa lisa y elástica.","Formar una bola con la masa, tapar con un paño y dejar fermentar en un lugar cálido hasta que doble su volumen.","Precalentar el horno a 200 °C.","Cortar pimiento rojo, pimiento verde, berenjena y cebolla en tiras.","Cortar tomate en tiras.","Repartir las verduras cortadas en una bandeja y regar con aceite de oliva.","Salpimentar las verduras y asar a 200 °C durante 35 min, removiendo a media cocción, hasta que estén tiernas y doradas.","Estirar la masa fermentada con un rodillo hasta formar un rectángulo fino sobre una bandeja forrada con papel vegetal.","Repartir las verduras asadas sobre la masa dejando un borde libre de 1 cm.","Hornear a 200 °C durante 15 min hasta que la base empiece a dorarse.","Distribuir sardinas ahumadas por encima de la coca.","Hornear 5 min más a 200 °C hasta que las sardinas estén calientes.","Retirar del horno y dejar templar antes de cortar.","Cortar la coca en porciones y servir."}', 'Coca catalana de base fina con verduras asadas de temporada y sardinas ahumadas por encima.', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Prepara la masa y déjala levar. Asa los pimientos, berenjena, cebolla y tomate en el horno a 180-200°C hasta que estén tiernos y ligeramente caramelizados. Extiende la masa, cubre con las verduras peladas y troceadas, y las sardinas ahumadas. Hornea hasta que la masa esté dorada "}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_108', 'Tarta fina de cebolla caramelizada y anchoas', 'pescados', 'pescado_azul', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 520, 9, 40, 33, 4, false, true, '{"gluten","lactosa","pescado"}', '[{"name":"Masa de hojaldre","amount":230,"unit":"g"},{"name":"Cebolla","amount":500,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Anchoas en aceite","amount":60,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar cebolla y cortar en juliana fina.","Calentar mantequilla y aceite de oliva en una sartén amplia a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla en juliana y sofreír a fuego suave, removiendo de vez en cuando.","Añadir azúcar y remover para integrar.","Sofreír a fuego suave hasta que la cebolla caramelice ligeramente.","Retirar la sartén del fuego y dejar templar la cebolla caramelizada.","Extender masa de hojaldre sobre una bandeja de horno forrada con papel vegetal.","Pinchar toda la base del hojaldre con un tenedor para evitar que suba en exceso.","Repartir la cebolla caramelizada sobre el hojaldre dejando un borde libre de 1 cm.","Disponer anchoas en aceite en tiras formando un enrejado sobre la cebolla.","Repartir aceitunas negras entre los huecos del enrejado de anchoas.","Espolvorear tomillo de manera uniforme sobre la tarta.","Hornear en el centro del horno a 200 °C hasta que el hojaldre esté dorado y crujiente.","Retirar del horno y dejar templar antes de cortar.","Cortar en porciones y servir."}', 'Tarta fina de hojaldre crujiente con cebolla caramelizada, anchoas y aceitunas negras.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Carameliza la cebolla lentamente en una sartén. Extiende la cebolla sobre la masa de hojaldre, añade las anchoas y hornea a 190°C durante 25-30 minutos hasta que el hojaldre esté dorado y crujiente."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Prepara la cebolla caramelizada en una sartén. Monta la tarta en un molde pequeño o sobre papel de horno apto para airfryer y cocina a 180°C durante 15-20 minutos, vigilando para un hojaldre perfectamente crujiente."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_109', 'Empanada de vieiras y gambas', 'pescados', 'marisco', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 560, 30, 72, 15, 4, true, true, '{"gluten","marisco","moluscos","huevo"}', '[{"name":"Harina de fuerza","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Levadura de panadería seca","amount":6,"unit":"g"},{"name":"Vieiras (sin concha)","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 170 ml de agua templada y remover hasta integrar.","Esperar 5 min hasta que la levadura espume y esté activa.","Mezclar harina de fuerza con sal en un bol amplio y hacer un hueco en el centro.","Añadir el agua con levadura y aceite de oliva al hueco de la harina.","Amasar durante 10 min hasta obtener una masa lisa y elástica que no se pegue.","Tapar el bol con un paño y dejar fermentar la masa 60 min hasta que doble su volumen.","Picar cebolla fina.","Picar pimiento verde fino.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla y el pimiento verde picados a fuego medio 14 min hasta que estén tiernos.","Añadir tomate triturado al sofrito y cocer a fuego medio 9 min hasta que espese.","Salpimentar el sofrito y retirar la sartén del fuego.","Dejar templar el sofrito 10 min antes de añadir el marisco.","Cortar vieiras (sin concha) en trozos de bocado.","Añadir las vieiras troceadas y gambas peladas al sofrito templado y remover para integrar.","Reservar el relleno mientras la masa termina de fermentar.","Precalentar el horno a 190 °C.","Dividir la masa fermentada en 2 porciones iguales.","Estirar la primera porción con un rodillo hasta obtener una lámina del tamaño de la bandeja.","Estirar la segunda porción del mismo modo y reservar ambas láminas.","Colocar la primera lámina sobre la bandeja de horno y repartir el relleno dejando 1 cm de borde.","Cubrir con la segunda lámina y sellar los bordes pellizcando la masa con los dedos.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hornear a 190 °C durante 32 min hasta que la empanada esté dorada y crujiente.","Dejar templar la empanada 10 min antes de cortar en porciones y servir.","Cortar en porciones y servir."}', 'Empanada casera de masa fermentada rellena de vieiras y gambas con sofrito de pimiento.', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Prepara la masa y el sofrito por separado. Monta la empanada y hornea a 180-200°C durante 30-45 minutos hasta que esté dorada y crujiente. El truco es un buen sellado para que el relleno no se escape."},{"appliance":"airfryer","time":90,"difficulty":"normal","prepSummary":"Divide la masa y el relleno en porciones individuales para hacer empanadillas. Cocina en la airfryer a 180°C durante 15-20 minutos, volteando a mitad, hasta que estén doradas y crujientes. No sobrecargues la cesta para una cocción uniforme."},{"appliance":"thermomix","time":90,"difficulty":"facil","prepSummary":"Utiliza Thermomix para amasar la masa en unos minutos y para preparar el sofrito de forma rápida y homogénea. Luego, monta la empanada y hornea en un horno convencional a 190°C durante 35-40 minutos hasta que dore."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_110', 'Tosta de tartar de atún y aguacate', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 600, 34, 38, 33, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Atún rojo (calidad sashimi)","amount":240,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Pan de payés","amount":120,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar atún rojo (calidad sashimi) en dados muy pequeños y regulares con un cuchillo bien afilado.","Picar cebolleta muy fina.","Exprimir lima y reservar el zumo separado en dos partes iguales.","Mezclar el atún con salsa de soja, aceite de sésamo y la mitad del zumo de lima.","Añadir la cebolleta picada al atún aliñado y remover con cuidado.","Tapar el bol y dejar marinar el tartar en frío.","Cortar aguacate por la mitad y retirar el hueso.","Machacar la pulpa de aguacate con un tenedor junto con el resto del zumo de lima y aceite de oliva.","Calentar plancha a fuego medio y tostar pan de payés con aceite de oliva hasta que esté dorado y crujiente.","Untar cada tosta con la crema de aguacate en capa generosa.","Repartir el tartar de atún marinado encima de la crema de aguacate.","Espolvorear sésamo tostado sobre cada tosta y servir de inmediato."}', 'Tostas crujientes con crema de aguacate y un tartar de atún fresco marinado en soja y lima.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Tuesta el pan de payés en la airfryer a 180°C durante 5-7 minutos, hasta que esté crujiente y dorado. Mientras, pica finamente el atún, aguacate y cebolleta, mezcla con el resto de ingredientes y monta sobre el pan."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill. Tuesta las rebanadas de pan de payés durante 5-8 minutos, vigilando hasta que estén doradas y crujientes. Prepara el tartar mientras se tuesta el pan y luego monta."}]'::jsonb, '{}', true, true, NULL, '{}', NULL),
  ('pescados_111', 'Buñuelos de bacalao con alioli', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 760, 30, 46, 45, 2, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Bacalao desalado (desmigado)","amount":200,"unit":"g"},{"name":"Harina","amount":120,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Levadura química","amount":5,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Ajo","amount":16,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Mayonesa","amount":60,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado (desmigado) en trozos pequeños, comprobando que no queden espinas.","Picar perejil muy fino.","Picar la mitad de ajo muy fino.","Batir huevo en un bol grande hasta que estén homogéneos.","Añadir harina, levadura química y leche al bol y mezclar hasta obtener una masa sin grumos.","Incorporar el bacalao desmigado, el perejil picado y el ajo picado a la masa y mezclar bien.","Tapar el bol y dejar reposar la masa 15 min en la nevera.","Machacar la otra mitad del ajo y mezclar con mayonesa hasta obtener un alioli suave.","Reservar el alioli en la nevera hasta el momento de servir.","Calentar aceite de oliva suave en sartén honda a fuego medio-fuerte hasta alcanzar 180 °C.","Formar los buñuelos con 2 cucharas cogiendo porciones de masa y depositarlas con cuidado en el aceite caliente.","Freír los buñuelos en tandas 3 min, hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","Escurrir los buñuelos sobre papel absorbente para retirar el exceso de aceite.","Servir los buñuelos calientes acompañados del alioli."}', 'Buñuelos esponjosos de bacalao desmigado, fritos hasta quedar dorados, con un alioli suave al lado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_112', 'Pastel de cabracho', 'pescados', 'pescado_blanco', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 490, 32, 6, 35, 4, true, true, '{"pescado","marisco","huevo","lactosa"}', '[{"name":"Cabracho (o rape/merluza)","amount":400,"unit":"g"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Mayonesa","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar agua con sal en una olla a fuego fuerte hasta que rompa a hervir.","Cocer cabracho (o rape/merluza) a fuego medio hasta que esté hecho.","Retirar el cabracho del agua y dejar templar.","Picar cebolla muy fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté tierna y transparente.","Retirar piel y espinas del cabracho templado y desmenuzar la carne.","Llevar agua a ebullición en un cazo a fuego fuerte.","Cocer gambas peladas en el agua hirviendo durante 2 min.","Escurrir las gambas y picarlas en trozos pequeños.","Precalentar el horno a 180 °C.","Forrar un molde rectangular con papel vegetal mientras el horno calienta.","Triturar el cabracho desmenuzado, la cebolla pochada, tomate frito, huevo y nata para cocinar hasta obtener una mezcla fina.","Añadir las gambas picadas a la mezcla y remover con una espátula sin triturar.","Verter la mezcla en el molde preparado.","Hornear al baño maría a 180 °C hasta que al pinchar con un palillo salga limpio.","Retirar del horno y dejar enfriar completamente a temperatura ambiente.","Refrigerar el pastel en el molde hasta que esté bien frío y firme.","Desmoldar el pastel sobre una fuente.","Servir en lonchas cubierto con mayonesa."}', 'Pastel de pescado tipo terrina, con cabracho y gambas, cuajado al horno y cubierto de mayonesa.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_113', 'Empanada gallega de bonito', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 665, 32, 87, 21, 4, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina de fuerza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Levadura de panadería seca","amount":7,"unit":"g"},{"name":"Bonito en conserva","amount":300,"unit":"g"},{"name":"Cebolla","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 190 ml de agua templada.","Reposar la mezcla de levadura 5 min hasta que espume.","Mezclar harina de fuerza con sal en un bol grande.","Añadir el agua con levadura y aceite de oliva a la harina.","Amasar la mezcla 10 min hasta obtener una masa lisa y elástica.","Tapar la masa con un paño y dejar fermentar 60 min hasta que doble su volumen.","Picar cebolla en dados pequeños.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y los pimientos 15 min hasta que estén tiernos.","Añadir pimentón dulce y tomate triturado al sofrito.","Cocer el sofrito a fuego medio 10 min hasta que espese.","Salpimentar el sofrito y retirar del fuego.","Dejar templar el sofrito 10 min.","Escurrir bonito en conserva y desmenuzarlo en trozos sobre el sofrito templado.","Mezclar el bonito con el sofrito con cuidado hasta integrar.","Precalentar el horno a 190 °C.","Dividir la masa en 2 porciones iguales.","Estirar cada porción de masa hasta obtener 2 láminas del tamaño de la bandeja.","Colocar la primera lámina de masa sobre la bandeja de horno.","Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","Cubrir con la segunda lámina y sellar bien los bordes presionando con los dedos.","Batir huevo en un bol pequeño.","Pintar la superficie de la empanada con el huevo batido.","Hacer un pequeño agujero en el centro de la empanada para que salga el vapor.","Hornear la empanada 35 min hasta que la superficie esté dorada.","Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada gallega tradicional de masa fermentada, rellena de bonito y un sofrito de pimientos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_114', 'Empanada de atún y pimientos', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 648, 31, 87, 19, 4, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina de fuerza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":55,"unit":"ml"},{"name":"Levadura de panadería seca","amount":7,"unit":"g"},{"name":"Atún en conserva","amount":280,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":150,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 190 ml de agua templada y remover hasta que no queden grumos.","Esperar 5 min hasta que la levadura empiece a burbujear.","Mezclar harina de fuerza con sal en un bol amplio y hacer un hueco en el centro.","Añadir el agua con levadura y aceite de oliva al hueco de la harina.","Amasar la mezcla durante 10 min hasta obtener una masa lisa, elástica y que no se pegue.","Tapar el bol con un paño húmedo y dejar fermentar la masa 60 min hasta que doble su volumen.","Cortar pimiento rojo en dados pequeños.","Cortar pimiento verde en dados pequeños.","Cortar cebolla en dados pequeños.","Calentar sartén a fuego medio con aceite de oliva.","Sofreír el pimiento rojo, el pimiento verde y la cebolla picados a fuego medio 18 min hasta que estén muy tiernos.","Añadir tomate triturado al sofrito y cocer a fuego medio 10 min hasta que espese.","Salpimentar el sofrito y retirar la sartén del fuego.","Dejar templar el sofrito 10 min antes de incorporar el atún.","Escurrir atún en conserva y desmenuzarlo sobre el sofrito templado.","Mezclar el atún con el sofrito con cuidado hasta integrar bien todo el relleno.","Precalentar el horno a 190 °C.","Dividir la masa fermentada en 2 porciones iguales.","Estirar cada porción de masa con un rodillo hasta obtener 2 láminas del tamaño de la bandeja.","Colocar la primera lámina de masa sobre la bandeja de horno.","Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","Cubrir el relleno con la segunda lámina de masa y sellar los bordes presionando con los dedos.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hornear la empanada a 190 °C durante 33 min hasta que esté dorada y crujiente.","Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada casera bien rellena de atún y un colorido sofrito de pimiento rojo y verde.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_115', 'Vol-au-vent de marisco', 'pescados', 'marisco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'elaborada', 'all', 670, 27, 40, 39, 2, true, false, '{"gluten","marisco","moluscos","lactosa"}', '[{"name":"Vol-au-vent de hojaldre (cestas precocidas)","amount":6,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Mejillones (sin concha)","amount":100,"unit":"g"},{"name":"Champiñones","amount":100,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Laminar champiñones en láminas finas.","Fundir la mitad de mantequilla en sartén a fuego medio.","Sofreír los champiñones laminados a fuego medio hasta que suelten el agua y se doren ligeramente.","Retirar los champiñones de la sartén y reservar.","Saltear gambas peladas y mejillones (sin concha) en la misma sartén a fuego fuerte.","Añadir vino blanco y cocinar hasta que las gambas cambien de color y el vino se evapore.","Retirar las gambas y los mejillones de la sartén y reservar junto con los champiñones.","Fundir el resto de la mantequilla en un cazo a fuego medio.","Añadir harina al cazo y remover sin parar durante 1 min hasta formar un roux homogéneo.","Verter leche poco a poco sin dejar de remover para evitar grumos.","Cocer a fuego medio removiendo hasta obtener una bechamel espesa y lisa.","Añadir nuez moscada y remover para integrar.","Incorporar las gambas, los mejillones y los champiñones reservados a la bechamel y remover.","Colocar vol-au-vent de hojaldre (cestas precocidas) en una bandeja y calentar en el horno 5 min hasta que estén crujientes.","Retirar las cestas del horno y rellenar cada una con el relleno de marisco y bechamel.","Servir de inmediato."}', 'Cestas de hojaldre rellenas de una bechamel cremosa con gambas, mejillones y champiñones.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_116', 'Timbal de patata y bacalao', 'pescados', 'pescado_blanco', 'patatas', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 550, 33, 37, 26, 2, true, true, '{"pescado","lactosa","huevo"}', '[{"name":"Bacalao desalado (desmigado)","amount":250,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y colocarlas enteras en una olla cubiertas de agua fría con sal.","Llevar a ebullición y cocer a fuego medio hasta que estén tiernas.","Picar cebolla en fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio y sofreír la cebolla picada hasta que esté tierna.","Añadir bacalao desalado (desmigado) a la sartén y sofreír hasta que pierda el aspecto crudo.","Retirar la sartén del fuego y reservar el sofrito de bacalao y cebolla.","Escurrir las patatas cocidas y dejar templar.","Cortar las patatas templadas en rodajas de grosor uniforme.","Batir huevo con nata para cocinar en un bol hasta integrar.","Mezclar la mezcla de huevo y nata con el sofrito de bacalao y cebolla hasta obtener un relleno homogéneo.","Precalentar el horno a 190 °C y engrasar dos moldes individuales con aceite de oliva.","Disponer una primera capa de rodajas de patata en la base de cada molde.","Cubrir con una capa del relleno de bacalao y repetir hasta agotar ingredientes, terminando con rodajas de patata.","Espolvorear queso rallado sobre la capa superior de cada molde.","Hornear los moldes en el horno a 190 °C hasta que estén gratinados y dorados por encima.","Retirar los moldes del horno y dejar reposar antes de desmoldar.","Desmoldar con cuidado cada timbal sobre el plato y espolvorear con el perejil picado."}', 'Timbal de capas de patata y bacalao desmigado, gratinado al horno con queso.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('pescados_117', 'Pastel de puerros y salmón', 'pescados', 'pescado_azul', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 90, 'normal', 'all', 500, 26, 8, 38, 4, true, true, '{"pescado","huevo","lactosa"}', '[{"name":"Salmón (lomos)","amount":350,"unit":"g"},{"name":"Puerro","amount":400,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde rectangular con papel vegetal.","Limpiar puerro y cortarlos en rodajas finas.","Calentar mantequilla en sartén a fuego suave.","Sofreír el puerro en rodajas a fuego suave, removiendo de vez en cuando, hasta que esté muy tierno sin dorarse.","Salpimentar el puerro pochado y reservar para que temple.","Cocer salmón (lomos) en agua con sal a fuego medio hasta que estén hechos.","Retirar el salmón del agua y dejar templar.","Desmenuzar el salmón en trozos grandes, retirando piel y espinas.","Batir huevo con nata para cocinar en un bol grande.","Añadir nuez moscada al batido de huevo y nata y salpimentar al gusto.","Incorporar el puerro pochado y el salmón desmenuzado al batido, mezclando con cuidado.","Verter la mezcla en el molde preparado y repartir queso rallado por encima.","Colocar el molde dentro de una bandeja con agua caliente hasta la mitad del molde para el baño maría.","Hornear a 180 °C al baño maría hasta que el pastel esté cuajado y ligeramente dorado en la superficie.","Retirar el molde del horno y dejar templar a temperatura ambiente.","Refrigerar el pastel en el molde hasta que esté bien frío y firme para desmoldar.","Desmoldar el pastel sobre una fuente y cortar en lonchas.","Servir frío o templado."}', 'Pastel cuajado al horno con capas de puerro pochado y salmón desmenuzado, en lonchas rosadas y verdes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_118', 'Empanadillas de bonito y pimientos', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 760, 39, 76, 30, 2, true, false, '{"gluten","pescado","huevo"}', '[{"name":"Obleas para empanadillas","amount":16,"unit":"ud"},{"name":"Bonito en conserva","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"}]'::jsonb, '{"Picar cebolla en dados pequeños.","Picar pimiento rojo en dados pequeños.","Picar pimiento verde en dados pequeños.","Calentar aceite de oliva suave en sartén a fuego medio.","Sofreír la cebolla picada, el pimiento rojo y el pimiento verde hasta que estén tiernos.","Añadir tomate frito y cocer hasta que el conjunto espese ligeramente.","Retirar la sartén del fuego y dejar templar el sofrito.","Escurrir bonito en conserva y desmenuzarlo sobre el sofrito templado.","Mezclar el bonito con el sofrito hasta integrar bien. Reservar el relleno.","Extender obleas para empanadillas sobre una superficie limpia.","Colocar una cucharada de relleno en el centro de cada oblea.","Humedecer el borde de cada oblea con agua, doblarla por la mitad y sellar presionando con un tenedor.","Batir huevo en un bol pequeño.","Pincelar el borde de cada empanadilla con el huevo batido para reforzar el sellado.","Calentar el aceite de oliva suave restante en sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las empanadillas en tandas 2 min por cada lado, hasta que estén doradas.","Escurrir las empanadillas sobre papel absorbente.","Servir las empanadillas calientes."}', 'Empanadillas fritas y crujientes, rellenas de bonito con un sofrito colorido de pimientos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('pescados_119', 'Salmón al horno con soja y patatas panaderas', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 490, 34, 32, 24, 2, true, true, '{"pescado","soja","gluten"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Cebollino","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas finas de 3 mm.","Pelar cebolla y cortar en aros finos.","Disponer la patata y la cebolla en una bandeja de horno.","Regar con aceite de oliva, salpimentar y mezclar bien hasta cubrir.","Hornear la bandeja 20 min hasta que las patatas empiecen a dorarse por los bordes.","Picar ajo muy fino.","Rallar jengibre fresco finamente.","Mezclar en un bol salsa de soja, miel, el ajo picado y el jengibre rallado.","Remover el glaseado hasta obtener una mezcla homogénea y reservar.","Retirar la bandeja del horno y colocar lomos de salmón sobre la cama de patatas.","Pincelar los lomos de salmón generosamente con el glaseado de soja y miel.","Hornear 13 min más hasta que el salmón esté opaco y el glaseado brille.","Picar cebollino fino y espolvorear sobre el salmón.","Servir los lomos de salmón sobre las patatas panaderas directamente en la bandeja."}', 'Salmón glaseado con soja, miel y jengibre al horno sobre una cama de patatas panaderas doradas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_001', 'Paella valenciana', 'platos_unicos', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 528, 28, 58, 18, 2, true, false, '{}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Garrofón","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de unos 4 cm.","Cortar judías verdes en trozos de unos 3 cm.","Calentar la paella a fuego fuerte y añadir aceite de oliva.","Dorar el pollo en la paella a fuego fuerte hasta que esté bien dorado por todos los lados.","Añadir las judías verdes y garrofón y saltear a fuego medio hasta que estén ligeramente dorados, unos 3 min.","Incorporar tomate triturado y sofreír a fuego medio hasta que pierda el agua y quede concentrado.","Añadir pimentón y remover durante 20 segundos hasta que se integre; retirar la paella del fuego para que no se queme.","Llevar a ebullición 600 ml de agua en un cazo aparte.","Disolver azafrán en un poco del agua caliente dentro del cazo y remover.","Verter el agua con azafrán en la paella y volver a poner a fuego fuerte hasta que rompa a hervir.","Cocer el caldo a fuego medio durante 10 min para que el pollo y las verduras se terminen de cocinar y el caldo coja sabor.","Añadir arroz distribuyéndolo de forma uniforme por toda la paella sin remover.","Cocer a fuego fuerte los primeros 5 min sin remover en ningún momento.","Bajar a fuego medio-suave y cocer hasta que el arroz absorba todo el caldo y esté en su punto, unos 13 min más.","Retirar del fuego y dejar reposar la paella tapada con papel de periódico o un paño limpio durante 2 min.","Servir la paella directamente en la mesa desde la misma paella."}', 'Paella valenciana de pollo con judías verdes y garrofón', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Comienza dorando el pollo y las verduras en una paellera sobre la encimera. Añade el tomate, pimentón y arroz, luego el caldo con azafrán. Tras un hervor, hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido, logrando una cocción uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_002', 'Pizza casera', 'platos_unicos', 'none', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 518, 18, 62, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Mozzarella","amount":125,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Desmenuzar levadura fresca en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","Añadir harina al bol y verter aceite de oliva; mezclar hasta obtener una masa homogénea.","Amasar la masa sobre la encimera enharinada durante 8 min hasta que esté elástica y no se pegue.","Tapar la masa con un paño húmedo y dejar reposar hasta que doble su volumen.","Precalentar el horno a 230 °C con calor arriba y abajo.","Estirar la masa sobre papel de hornear formando un disco fino de unos 30 cm de diámetro.","Extender tomate triturado sobre la masa dejando 1 cm de borde libre.","Laminar mozzarella y repartir las láminas de forma uniforme sobre el tomate.","Espolvorear orégano sobre la mozzarella.","Hornear la pizza en la rejilla central a 230 °C hasta que los bordes estén dorados y el queso burbujee.","Retirar la pizza del horno, cortar en porciones y servir de inmediato."}', 'Pizza casera con masa fina, tomate y mozzarella', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Prepara la masa siguiendo la receta y estírala sobre una bandeja. Hornea la pizza en un horno precalentado a 200-220°C durante 15-20 minutos, hasta que la base esté dorada y el queso burbujeante y fundido."},{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Amasa y forma una o varias pizzas pequeñas que quepan en la cesta de la airfryer. Cocínalas en la airfryer precalentada a 180-190°C durante 10-15 minutos, vigilando que la masa quede crujiente y el queso bien fundido."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_003', 'Croquetas de jamón', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 428, 14, 32, 28, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Picar el jamón serrano en dados muy finos","Fundir la mantequilla en un cazo a fuego medio-suave","Calentar la leche en otro cazo hasta que esté caliente sin hervir","Añadir la harina al roux y remover con varillas 2 min hasta obtener una pasta lisa","Incorporar la leche caliente poco a poco sin dejar de remover hasta obtener bechamel","Añadir el jamón picado y la nuez moscada; remover 1 min para integrar","Extender la bechamel en bandeja, cubrir con film a piel y refrigerar mínimo 3 horas","Batir el huevo en un bol y disponer el pan rallado en un plato aparte","Dar forma ovalada a las croquetas con las manos enharinadas","Pasar cada croqueta por huevo batido y luego por pan rallado cubriendo bien","Calentar el aceite en sartén profunda a fuego fuerte hasta alcanzar 180 °C","Freír por tandas 2-3 min hasta que estén doradas; escurrir y servir calientes"}', 'Croquetas cremosas de bechamel con jamón serrano', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para la bechamel: funde la mantequilla, sofríe la harina y añade la leche progresivamente a 90°C, velocidad 4, durante unos 7-8 minutos hasta obtener una crema perfecta y sin grumos. Luego, se enfría la masa, se forman las croquetas y se fríen de forma tradicional en abundante aceite caliente."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas las croquetas, rocíalas ligeramente con aceite de oliva y cocínalas en la airfryer precalentada a 190-200°C durante 12-15 minutos, dándoles la vuelta a mitad de cocción, hasta que estén doradas y crujientes."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Para una versión más ligera, hornea las croquetas ya empanadas. Precalienta el horno a 200°C con calor arriba y abajo, rocía las croquetas con un poco de aceite y hornea durante 20-25 minutos, girándolas una vez, hasta que estén doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_004', 'Empanada gallega de atún', 'platos_unicos', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 468, 20, 46, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Picar cebolla en daditos finos.","Cortar pimiento rojo en tiras pequeñas.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el pimiento rojo a fuego medio hasta que estén tiernos.","Añadir tomate triturado al sofrito y remover hasta integrar.","Cocer a fuego medio hasta que el sofrito reduzca y espese.","Escurrir atún en conserva y desmenuzarlo sobre un plato.","Añadir el atún desmenuzado al sofrito, mezclar bien y retirar del fuego. Reservar.","Precalentar el horno a 190 °C con calor arriba y abajo.","Poner harina en un bol grande. Añadir sal y el aceite de oliva restante.","Añadir 65 ml de agua tibia a la mezcla de harina y amasar hasta obtener una masa homogénea.","Dividir la masa en 2 porciones iguales.","Estirar cada porción con un rodillo hasta obtener 2 láminas finas del tamaño de la bandeja.","Disponer la primera lámina sobre una bandeja de horno ligeramente engrasada.","Repartir el relleno de atún sobre la lámina dejando 1 cm de borde libre en todo el contorno.","Cubrir con la segunda lámina de masa.","Sellar los bordes presionando con los dedos y doblar el borde hacia arriba pellizcándolo para cerrar bien.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hacer 2 o 3 cortes pequeños en el centro de la empanada para permitir la salida de vapor.","Hornear a 190 °C hasta que la superficie esté dorada.","Retirar del horno y dejar reposar la empanada antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada gallega de masa casera rellena de atún y pimiento', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la masa y el relleno. Hornea la empanada a 180-190°C durante 35-40 minutos, o hasta que esté dorada y crujiente. Un truco es pintar con huevo batido para un acabado brillante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Elabora la masa y el relleno. Forma una empanada de tamaño adecuado para tu airfryer y cocina a 170-180°C durante 20-25 minutos, volteándola a mitad, hasta que esté dorada. Asegúrate de no sobrecargar la cesta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_005', 'Empanadillas de atún', 'platos_unicos', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 412, 18, 38, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Obleas de empanadilla","amount":8,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y cortar en brunoise fina. Lavar pimiento verde y cortar también en brunoise fina.","Escurrir atún en conserva y desmenuzar con un tenedor. Reservar.","Pelar huevo cocido y picar en trozos pequeños. Reservar.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla y el pimiento verde picados a fuego medio hasta que estén tiernos, unos 6 min.","Añadir tomate triturado y remover. Cocer a fuego medio hasta que el líquido reduzca, unos 4 min.","Añadir el atún desmenuzado y el huevo cocido picado. Mezclar y retirar del fuego.","Dejar enfriar el relleno hasta que esté a temperatura ambiente antes de rellenar las obleas.","Disponer obleas de empanadilla sobre una superficie plana. Colocar una cucharada de relleno en el centro de cada oblea.","Doblar cada oblea por la mitad y sellar el borde presionando con un tenedor para que no se abran.","Calentar el aceite de oliva restante en sartén a fuego fuerte hasta que esté bien caliente.","Freír las empanadillas en el aceite caliente hasta que estén doradas por ambos lados, unos 2 min por lado.","Escurrir las empanadillas sobre papel absorbente y servir calientes."}', 'Empanadillas rellenas de atún con pimiento y huevo', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara el sofrito en sartén. Rellena las obleas y cocina en la airfryer precalentada a 180-190°C durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Elabora el sofrito en una sartén. Rellena las obleas, séllalas y píntalas con huevo o aceite antes de hornear a 190-200°C durante 15-20 minutos, hasta que estén doradas y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_006', 'Crepes de jamón y queso', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 398, 18, 32, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":200,"unit":"ml"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"}]'::jsonb, '{"Tamizar harina en un bol amplio y añadir huevo; batir con varillas hasta incorporar.","Incorporar leche poco a poco sin dejar de remover hasta obtener una masa fina y sin grumos.","Calentar sartén a fuego medio y fundir mantequilla hasta que cubra toda la base.","Verter un cucharón de masa y mover la sartén en círculos hasta que cubra la base con una capa fina.","Cocer la crepe hasta que los bordes se despeguen y la base esté dorada; girar y cocer 30 segundos más.","Repetir el proceso con el resto de la masa hasta obtener 4 crepes; reservar apiladas.","Cortar jamón cocido en tiras y disponer sobre cada crepe extendida.","Colocar queso en lonchas sobre el jamón cubriendo la mitad de la crepe.","Doblar cada crepe por la mitad y luego en cuartos para formar un triángulo.","Calentar la sartén a fuego suave y dorar las crepes rellenas 2 min por cada lado hasta que el queso se funda.","Servir las crepes calientes, 2 por ración, recién sacadas de la sartén."}', 'Crepes finas rellenas de jamón cocido y queso fundido', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para preparar la masa de los crepes de forma rápida y sin grumos. Mezcla todos los ingredientes (harina, huevos, leche, mantequilla derretida) durante 30 segundos a velocidad 5. Luego, cocina los crepes en una sartén tradicional."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Tras cocinar los crepes en sartén y rellenarlos con jamón y queso, colócalos en una fuente apta para horno. Gratina a 180°C durante 8-10 minutos hasta que el queso se funda y los crepes estén calientes y ligeramente dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_007', 'Quiche de verduras', 'platos_unicos', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 412, 14, 28, 28, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C con calor arriba y abajo.","Lavar calabacín y cortar en dados pequeños.","Lavar puerro y cortar en rodajas finas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el puerro en la sartén a fuego medio hasta que esté tierno, unos 3 min.","Añadir el calabacín a la sartén y saltear a fuego medio hasta que esté dorado, unos 4 min.","Retirar la sartén del fuego y reservar las verduras.","Cascar huevo en un bol y batir con varillas hasta que estén bien integrados.","Añadir nata a los huevos batidos y mezclar hasta obtener una mezcla homogénea.","Añadir queso rallado a la mezcla de huevos y nata y remover hasta integrar.","Incorporar las verduras reservadas a la mezcla y remover para distribuirlas de manera uniforme.","Extender masa quebrada sobre el molde, presionar bien los bordes y pinchar el fondo con un tenedor.","Verter la mezcla de verduras y huevos sobre la masa quebrada en el molde de manera uniforme.","Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","Retirar del horno, dejar reposar 5 min y servir cortada en porciones."}', 'Quiche de masa quebrada con calabacín, puerro y queso', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Hornea la masa quebrada unos minutos en blanco, luego añade el relleno de verduras sofritas con huevo, nata y queso. Hornea durante 45-50 minutos hasta que esté dorado y cuajado."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Utiliza un molde apto para airfryer que quepa bien. Precalienta a 170°C. Cocina la masa quebrada unos 5-7 minutos, luego vierte el relleno y hornea por 30-35 minutos, vigilando que no se dore demasiado rápido por encima."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_008', 'Patatas rellenas de carne', 'platos_unicos', 'ternera', 'patatas', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 462, 24, 38, 24, 2, true, true, '{"lactosa"}', '[{"name":"Patata grande","amount":4,"unit":"ud"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar patata grande y pincharlas por varias partes con un tenedor.","Colocar las patatas en la bandeja del horno y hornear hasta que estén tiernas.","Pelar y picar cebolla en trozos muy finos.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","Añadir carne picada de ternera a la sartén y saltear hasta que pierda el color rosado.","Incorporar tomate triturado a la sartén y cocer a fuego suave hasta que se reduzca, unos 5 min.","Retirar las patatas del horno y dejar templar 2 min hasta que se puedan manipular.","Cortar cada patata por la mitad a lo largo y vaciar la pulpa con una cuchara, dejando 1 cm de borde.","Añadir la pulpa de las patatas a la sartén con la carne y mezclar bien hasta obtener un relleno homogéneo.","Rellenar cada mitad de patata con la mezcla de carne, presionando ligeramente para que quede compacta.","Repartir queso rallado por encima de cada patata rellena.","Hornear las patatas rellenas a 200 °C con gratinador hasta que el queso esté dorado y burbujeante.","Retirar del horno y servir las patatas rellenas inmediatamente."}', 'Patatas asadas rellenas de carne picada gratinadas con queso', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Hornea las patatas enteras a 200°C hasta que estén tiernas (aprox. 40-50 min). Vacía la pulpa, mezcla con el sofrito de carne y cebolla, rellena las patatas, cubre con queso y gratina a 180°C durante 15-20 min hasta dorar."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Cocina las patatas en la airfryer a 190°C durante 30-40 min hasta que estén tiernas. Vacía la pulpa, mezcla con el relleno de carne previamente cocinado, rellena las patatas, espolvorea queso y cocina en la airfryer a 180°C por 10-15 min hasta que el queso esté fundido y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_009', 'Wrap de pollo', 'platos_unicos', 'pollo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 382, 28, 32, 16, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Yogur natural","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de grosor uniforme y salpimentar al gusto.","Calentar plancha a fuego fuerte con aceite de oliva.","Dorar las tiras de pechuga en la plancha caliente durante 3 min por cada lado, hasta que estén doradas y cocidas por dentro.","Picar lechuga en tiras finas y cortar tomate en dados pequeños.","Retirar las tiras de pechuga de la plancha y reservar.","Mezclar yogur natural con sal en un bol pequeño hasta obtener una salsa homogénea.","Calentar tortilla de trigo en la plancha a fuego medio 30 segundos por cada lado, hasta que estén flexibles.","Extender la salsa de yogur sobre cada tortilla caliente, dejando un borde libre de 2 cm.","Distribuir la lechuga picada, el tomate en dados y las tiras de pechuga sobre cada tortilla.","Enrollar cada tortilla con firmeza, doblar los laterales hacia dentro y servir al momento."}', 'Tortilla de trigo enrollada con pollo a la plancha y verduras', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta la pechuga en tiras, rocía con aceite y cocina en la airfryer a 190°C durante 12-15 minutos, volteando a mitad, hasta que esté dorada y jugosa. Calienta las tortillas brevemente al final para que queden flexibles."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo cortada en tiras a 200°C durante 15-20 minutos, dándole la vuelta para que se dore uniformemente y quede cocida. Puedes calentar las tortillas en el horno durante los últimos minutos para ablandarlas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_010', 'Croquetas de bacalao', 'platos_unicos', 'pescado_blanco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 418, 18, 30, 26, 2, true, true, '{"gluten","lactosa","huevo","pescado"}', '[{"name":"Bacalao desalado","amount":120,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado con los dedos, retirando espinas y piel, hasta obtener hebras finas. Reservar.","Picar perejil muy fino. Reservar.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente líquida.","Añadir harina de golpe y remover sin parar con unas varillas a fuego medio hasta que la mezcla se despegue de las paredes.","Incorporar leche poco a poco, sin dejar de remover con las varillas a fuego medio, hasta que la bechamel esté espesa y sin grumos.","Añadir el bacalao desmigado y el perejil picado a la bechamel. Remover a fuego suave durante 2 min hasta que estén integrados.","Salpimentar la masa al gusto y remover para integrar.","Extender la masa en un recipiente plano y tapar con film a piel. Refrigerar hasta que esté completamente firme.","Batir huevo en un bol hondo. Disponer pan rallado en un recipiente plano aparte.","Tomar porciones de masa fría y dar forma alargada con las manos hasta obtener croquetas uniformes.","Pasar cada croqueta por el huevo batido y después por el pan rallado, presionando para que quede bien cubierta. Reservar en un plato.","Calentar aceite de oliva en sartén a fuego fuerte hasta que alcance unos 180 °C.","Freír las croquetas en tandas sin amontonar, girándolas, hasta que estén doradas por todos los lados.","Retirar las croquetas y escurrir sobre papel absorbente.","Servir las croquetas calientes."}', 'Croquetas cremosas de bechamel con bacalao desmigado', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas, las croquetas se cocinan en la airfryer a 195°C durante 12-15 minutos, rociadas ligeramente con aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Tras formar y empanar las croquetas, se hornean a 200°C durante 18-22 minutos en una bandeja con papel de horno y un poco de aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para cocer el bacalao y elaborar la bechamel de forma rápida y sin grumos. Una vez lista la masa de croquetas, se enfría, se forman y se fríen de la manera tradicional o se cocinan en airfryer/horno para el acabado final."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_011', 'Migas manchegas', 'platos_unicos', 'cerdo', 'pan', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 498, 16, 42, 28, 2, true, false, '{"gluten"}', '[{"name":"Pan del día anterior","amount":200,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Panceta","amount":60,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Desmigar pan del día anterior en trozos pequeños con las manos.","Humedecer el pan desmigado con un poco de agua fría hasta que esté ligeramente húmedo pero no empapado.","Cortar chorizo en rodajas finas.","Cortar panceta en trozos pequeños.","Laminar ajo.","Lavar uvas y reservar en un bol.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado a fuego suave hasta que se dore ligeramente.","Añadir la panceta y el chorizo a la sartén y sofreír a fuego medio hasta que estén dorados.","Retirar la sartén del fuego y añadir pimentón, removiendo rápido para que no se queme.","Incorporar el pan desmigado y húmedo a la sartén y mezclar bien con el sofrito.","Remover las migas a fuego medio sin parar hasta que queden sueltas y ligeramente doradas.","Servir las migas en plato hondo acompañadas de las uvas reservadas."}', 'Migas de pan con chorizo, panceta y uvas', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_012', 'Pimientos rellenos de arroz', 'platos_unicos', 'none', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 368, 10, 48, 14, 2, true, true, '{}', '[{"name":"Pimientos rojos","amount":4,"unit":"ud"},{"name":"Arroz","amount":150,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Picar cebolla en trozos finos.","Picar ajo fino.","Laminar champiñones.","Cortar la parte superior de pimientos rojos a modo de tapa y retirar las semillas y venas del interior.","Llevar a ebullición agua con sal en un cazo a fuego fuerte, añadir arroz y cocer 12 min hasta que esté tierno. Escurrir y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y los champiñones laminados a la sartén y saltear a fuego medio hasta que los champiñones suelten su agua y se doren.","Añadir tomate triturado al sofrito y remover a fuego medio durante 2 min hasta que se integre. Retirar del fuego.","Mezclar el arroz escurrido con el sofrito en la sartén hasta obtener un relleno homogéneo.","Disponer los pimientos en una bandeja de horno y rellenar cada uno con la mezcla de arroz, apretando ligeramente.","Hornear los pimientos rellenos en el horno a 190 °C durante 25 min hasta que la piel esté tierna y ligeramente tostada.","Retirar los pimientos del horno y servir inmediatamente."}', 'Pimientos rojos rellenos de arroz con champiñones', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara el sofrito con cebolla, ajo, champiñones, arroz y tomate triturado. Rellena los pimientos partidos por la mitad y hornea a 180-190°C durante unos 45-50 minutos, hasta que los pimientos estén tiernos y el relleno ligeramente gratinado."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Prepara el relleno en una sartén. Rellena los pimientos y colócalos en la cesta de la airfryer. Cocina a 170-180°C durante 30-35 minutos, girando a mitad de cocción y añadiendo un poco de agua en la base si es necesario para mantener la humedad y evitar que se sequen."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_013', 'Calzone casero', 'platos_unicos', 'none', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 492, 20, 56, 22, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Mozzarella","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Desmenuzar levadura fresca en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","Añadir harina al bol y mezclar hasta obtener una masa homogénea.","Incorporar aceite de oliva a la masa y amasar sobre una superficie enharinada hasta que esté lisa y elástica.","Tapar la masa con un paño y dejar reposar hasta que doble su volumen.","Precalentar el horno a 220 °C con calor arriba y abajo.","Cortar jamón cocido en trozos pequeños y reservar.","Cortar mozzarella en láminas finas y reservar.","Estirar la masa sobre una superficie enharinada formando un círculo de unos 30 cm de diámetro.","Extender tomate triturado sobre la mitad del círculo de masa, dejando 2 cm libres en el borde.","Disponer la mozzarella laminada sobre el tomate triturado y repartir el jamón cocido encima.","Doblar la mitad de masa sin relleno sobre la mitad rellena y sellar el borde presionando con un tenedor.","Colocar el calzone en una bandeja de horno ligeramente enharinada y hornear a 220 °C hasta que esté dorado.","Retirar del horno, dejar reposar 2 min y servir el calzone cortado al gusto."}', 'Pizza cerrada rellena de tomate, mozzarella y jamón', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Precalienta el horno a 190-200°C. Hornea el calzone durante 35-40 minutos o hasta que esté bien dorado y el queso burbujee."},{"appliance":"airfryer","time":80,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 175-185°C. Cocina el calzone (o calzones pequeños) durante 25-30 minutos, volteándolo a mitad del tiempo para un dorado uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_014', 'Tostas de aguacate y huevo', 'platos_unicos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 342, 14, 28, 20, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate cherry","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 4 rebanadas de grosor medio y reservar.","Cortar tomate cherry por la mitad y reservar.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Exprimir limón sobre la pulpa del aguacate y aplastar con un tenedor hasta obtener una crema rústica.","Calentar plancha a fuego fuerte y tostar las rebanadas de pan de hogaza 2 min por cada lado hasta que estén doradas.","Verter aceite de oliva en sartén y calentar a fuego medio.","Cascar huevo en la sartén con el aceite caliente y freír 2 min hasta que la clara esté cuajada y la yema tierna.","Extender la crema de aguacate sobre las rebanadas de pan de hogaza tostadas.","Colocar 1 huevo frito sobre cada tosta y distribuir los tomate cherry por encima."}', 'Tostadas de pan con aguacate machacado y huevo', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Tuesta el pan a 190°C durante 4-5 minutos hasta que esté dorado. Para el huevo, fríelo en un molde apto para airfryer a 160°C durante 8-10 minutos, logrando una yema jugosa."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan directamente en la rejilla durante 5-7 minutos. Para los huevos, hornéalos en cuencos individuales ligeramente engrasados durante 10-12 minutos hasta que la clara esté cuajada y la yema líquida."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('platos_unicos_015', 'Patatas bravas con huevo', 'platos_unicos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 448, 14, 42, 26, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Pimentón picante","amount":4,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados de unos 2 cm.","Laminar ajo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los dados de patata en el aceite caliente hasta que estén dorados y crujientes por fuera.","Retirar las patatas con una espumadera y escurrir sobre papel absorbente. Reservar.","Sofreír el ajo laminado en el aceite restante de la sartén a fuego suave hasta que se dore ligeramente.","Añadir pimentón picante al sofrito de ajo y remover durante 20 segundos para que no se queme.","Añadir tomate triturado, remover bien y cocer a fuego medio hasta que la salsa espese y reduzca.","Calentar un chorrito de aceite en otra sartén a fuego medio hasta que esté caliente.","Freír huevo de uno en uno en el aceite caliente hasta que la clara cuaje pero la yema quede líquida.","Disponer las patatas en el plato, cubrir con la salsa brava y colocar un huevo frito encima de cada ración. Servir de inmediato."}', 'Patatas fritas en dados con salsa brava y huevo frito', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Para las patatas, córtalas en dados, rocía con aceite y pimentón, y cocínalas en la airfryer a 190°C durante 20-25 minutos, agitándolas a mitad para un dorado uniforme. La salsa y el huevo se preparan aparte en sartén mientras las patatas se cocinan."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Asa las patatas cortadas en dados con aceite y pimentón en el horno precalentado a 200°C durante 35-40 minutos, volteándolas para que doren por todos lados. Prepara la salsa brava y el huevo frito en la sartén mientras las patatas se hornean."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_016', 'Bocadillo de tortilla', 'platos_unicos', 'huevo', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 512, 16, 52, 26, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas de unos 3 mm de grosor.","Pelar cebolla y cortar en juliana fina.","Calentar aceite de oliva en sartén a fuego suave hasta que esté templado.","Añadir las láminas de patata y la cebolla en juliana; confitar a fuego suave hasta que estén tiernas y sin color.","Cascar huevo en un bol amplio y batir hasta que estén bien integrados.","Escurrir la patata y la cebolla del aceite y reservar el aceite sobrante.","Añadir la patata y la cebolla escurridas al bol con el huevo batido y mezclar bien.","Dejar reposar la mezcla en el bol durante 2 min para que el huevo empape la patata.","Calentar 1 cucharada del aceite reservado en la sartén a fuego medio hasta que esté caliente.","Verter la mezcla de huevo, patata y cebolla en la sartén y extender de forma uniforme.","Cocer a fuego suave hasta que los bordes cuajen pero el centro quede ligeramente jugoso.","Dar la vuelta a la tortilla con la ayuda de un plato y deslizarla de nuevo a la sartén.","Cocer 1 min hasta que el exterior esté cuajado y el interior jugoso.","Retirar la tortilla de la sartén y dejar reposar 2 min antes de cortar.","Cortar pan de barra en 2 porciones iguales y abrir cada una por la mitad a lo largo.","Cortar la tortilla en porciones que encajen en el pan y disponer sobre la base de cada porción.","Tapar con la parte superior del pan, presionar ligeramente y servir de inmediato."}', 'Bocadillo de pan crujiente con tortilla de patata jugosa', '[]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_017', 'Burritos caseros de pollo', 'platos_unicos', 'pollo', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 468, 30, 42, 20, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Arroz cocido","amount":100,"unit":"g"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de 1 cm de grosor.","Cortar pimiento rojo en tiras del mismo tamaño que el pollo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear las tiras de pollo en la sartén a fuego fuerte hasta que estén doradas por fuera y cocidas por dentro.","Añadir las tiras de pimiento rojo a la sartén y saltear a fuego fuerte hasta que estén tiernas pero con algo de mordida.","Incorporar arroz cocido a la sartén y mezclar con el pollo y el pimiento.","Saltear todo junto a fuego fuerte hasta que el arroz esté bien integrado y caliente.","Retirar la sartén del fuego y reservar el relleno.","Calentar tortilla de trigo en una sartén limpia y seca a fuego medio 30 segundos por cada cara hasta que estén flexibles.","Disponer cada tortilla en plano y repartir el relleno de pollo, pimiento y arroz en el centro, dejando 3 cm libres en los laterales.","Espolvorear queso rallado sobre el relleno de cada tortilla.","Plegar los extremos laterales de cada tortilla hacia dentro.","Enrollar cada tortilla desde el borde más cercano hasta cerrar el burrito con firmeza.","Colocar los burritos con el cierre hacia abajo en la sartén a fuego medio hasta que el exterior quede sellado y crujiente.","Servir de inmediato."}', 'Burritos de tortilla de trigo con pollo, arroz y queso', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el pollo troceado y el pimiento a 180°C durante 15-18 min. Luego, rellena las tortillas y calienta los burritos montados en la airfryer a 180°C por 5-7 min para que se doren y el queso se funda."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa el pollo troceado y el pimiento en una bandeja a 200°C por 20-25 min. Rellena las tortillas y hornea los burritos a 180°C durante 10-12 min hasta que el queso se derrita y las tortillas estén ligeramente doradas."},{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Prepara el sofrito de pimiento y cocina el pollo troceado en el vaso. Añade el arroz cocido para integrarlo y calentarlo, obteniendo un relleno jugoso. Las tortillas se calientan aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('platos_unicos_018', 'Paella de marisco', 'platos_unicos', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 482, 26, 56, 16, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Picar ajo fino y reservar.","Cortar sepia en trozos pequeños y reservar.","Calentar aceite de oliva en una paella a fuego medio hasta que esté caliente.","Sofreír el ajo picado en el aceite caliente durante 1 min, hasta que esté dorado pero sin quemarse.","Añadir la sepia troceada y saltear a fuego medio hasta que pierda el agua y empiece a dorarse.","Incorporar tomate triturado y sofreír a fuego medio hasta que se evapore el líquido y el sofrito se oscurezca.","Disolver azafrán en 500 ml de agua caliente en un cazo y llevar a ebullición.","Verter el caldo con azafrán sobre el sofrito y cocer a fuego fuerte hasta que rompa a hervir.","Añadir arroz, repartir de forma uniforme por la paella y no remover más.","Cocer el arroz a fuego fuerte los primeros 5 min, luego reducir a fuego medio hasta que absorba casi todo el caldo.","Colocar gambas y mejillones sobre el arroz, distribuyéndolos de forma uniforme.","Cocer a fuego medio hasta que los mejillones se abran y las gambas estén rosadas.","Subir el fuego a fuerte durante los últimos 30 segundos hasta que el fondo suene seco y se forme el socarrat.","Retirar la paella del fuego y dejar reposar 2 min antes de servir.","Servir directamente desde la paella."}', 'Paella de arroz con gambas, mejillones y sepia', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito y saltea el marisco en una paellera apta para horno en la encimera. Añade el arroz y el caldo caliente, luego hornea a 200°C durante 20-25 minutos para una cocción uniforme y un socarrat perfecto."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL),
  ('platos_unicos_019', 'Quesadillas caseras', 'platos_unicos', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 388, 16, 34, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pimiento rojo en tiras finas y reservar.","Cortar jamón cocido en trozos pequeños y reservar.","Calentar sartén a fuego medio con aceite de oliva.","Colocar tortilla de trigo en la sartén caliente.","Repartir queso rallado sobre toda la superficie de la tortilla.","Distribuir el jamón cocido y el pimiento rojo sobre la mitad de la tortilla.","Doblar la tortilla por la mitad, cubriendo el relleno con la mitad vacía.","Cocinar a fuego medio hasta que se dore por la parte inferior, unos 2 min.","Dar la vuelta con cuidado y cocinar hasta que se dore el otro lado, unos 2 min.","Retirar de la sartén y dejar reposar 1 min sobre una tabla.","Cortar en 3 triángulos y servir inmediatamente."}', 'Tortilla de trigo doblada con queso fundido, jamón y pimiento', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina la quesadilla montada durante 10-12 minutos, dándole la vuelta a mitad de cocción, hasta que el queso se derrita y la tortilla esté dorada y crujiente."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea la quesadilla montada sobre papel de horno durante 10-12 minutos, hasta que el queso esté fundido y la tortilla ligeramente dorada y crujiente."}]'::jsonb, '{}', NULL, true, NULL, '{}', NULL),
  ('platos_unicos_020', 'Huevos a la riojana', 'platos_unicos', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 378, 16, 18, 26, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Pimiento choricero","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Chorizo","amount":50,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar y cortar patata en dados de 1 cm aproximadamente.","Pelar y picar cebolla en brunoise fina.","Picar ajo fino.","Cortar chorizo en rodajas de 0,5 cm.","Abrir pimiento choricero, raspar la pulpa con una cuchara y reservarla.","Calentar aceite de oliva en una sartén honda a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego suave hasta que esté transparente, unos 4 min.","Añadir el ajo picado y el chorizo en rodajas; sofreír a fuego medio hasta que el chorizo suelte su grasa, unos 2 min.","Añadir la patata en dados a la sartén y saltear a fuego medio hasta que empiece a dorarse por fuera, unos 5 min.","Incorporar la pulpa del pimiento choricero y tomate triturado; remover para mezclar bien.","Tapar la sartén y cocer a fuego suave hasta que la patata esté tierna y la salsa haya reducido, unos 10 min.","Hacer 4 huecos en la salsa con una cuchara y cascar huevo en cada uno con cuidado.","Tapar la sartén y cocer a fuego suave hasta que la clara esté cuajada y la yema quede cremosa, unos 5 min.","Servir directamente de la sartén, bien caliente."}', 'Huevos escalfados en salsa de tomate con chorizo, pimiento y patata en dados', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y chorizo en una cazuela apta para horno. Incorpora el pimiento choricero y el tomate, cocina unos minutos. Haz huecos, casca los huevos y hornea a 180°C durante 10-15 minutos hasta que las claras estén cuajadas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_001', 'Macedonia de fruta fresca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 140, 2, 33, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Naranja","amount":2,"unit":"ud"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar manzana y cortar en dados de 1 cm.","Pelar plátano y cortar en rodajas de 1 cm.","Pelar 1 naranja, separar en gajos y cortar cada gajo en 2 o 3 trozos.","Limpiar fresas, retirar el rabillo y cortar en cuartos.","Exprimir la naranja restante y mezclar su zumo con zumo de limón en un bol pequeño.","Reunir la manzana, el plátano, la naranja troceada y las fresas en un bol grande.","Verter la mezcla de zumos sobre la fruta y remover con suavidad hasta que toda la fruta quede impregnada.","Tapar el bol y refrigerar hasta que esté bien fría, al menos 15 min.","Servir la macedonia repartida en 4 cuencos fríos."}', 'Macedonia fresca de manzana, plátano, naranja y fresas con un toque de cítrico', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_002', 'Yogur con miel y nueces', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 4, 'facil', 'all', 280, 11, 28, 14, 2, false, false, '{"lactosa","frutos_secos"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"},{"name":"Nueces","amount":40,"unit":"g"}]'::jsonb, '{"Cortar nueces en trozos gruesos con un cuchillo.","Repartir yogur natural en 2 cuencos individuales a partes iguales.","Distribuir las nueces troceadas sobre el yogur de cada cuenco.","Verter miel en hilo fino sobre cada cuenco y servir de inmediato."}', 'Yogur natural con nueces troceadas y miel, un postre sencillo y saciante', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_003', 'Fruta de temporada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 90, 1, 22, 0, 2, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Naranja","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar manzana bajo el grifo con agua fría hasta que esté limpia.","Lavar naranja bajo el grifo con agua fría hasta que esté limpia.","Pelar la naranja y separar los gajos; cortar la manzana en láminas o trozos al gusto.","Servir la fruta en un plato o bol."}', 'Pieza de fruta de temporada como postre ligero. El planner elige naranja, fresa, melocotón o uva según el mes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_004', 'Natillas caseras', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 260, 9, 34, 9, 4, true, true, '{"lactosa","huevo"}', '[{"name":"Leche","amount":500,"unit":"ml"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Azúcar","amount":90,"unit":"g"},{"name":"Maicena","amount":20,"unit":"g"}]'::jsonb, '{"Separar huevo: extraer las yemas en un bol amplio y reservar las claras para otro uso.","Añadir azúcar y maicena a las yemas.","Mezclar con unas varillas hasta obtener una pasta homogénea y sin grumos.","Calentar leche en un cazo a fuego medio hasta que esté a punto de hervir; retirar antes de que rompa a ebullición.","Verter la leche caliente sobre la mezcla de yemas en hilo fino, removiendo sin parar con las varillas para templar las yemas.","Volcar la mezcla de nuevo al cazo a fuego suave.","Remover sin parar con las varillas hasta que la crema espese y nape la cuchara; no dejar que hierva.","Retirar el cazo del fuego y remover durante 1 min fuera del calor para detener la cocción y alisar la crema.","Repartir las natillas en 4 cuencos individuales y dejar enfriar a temperatura ambiente.","Tapar los cuencos y refrigerar hasta que las natillas estén completamente frías y cuajadas.","Servir los cuencos fríos directamente de la nevera."}', 'Natillas caseras de huevo y leche', NULL, '{"Natillas","Natillas de vainilla"}', NULL, NULL, NULL, '{}', NULL),
  ('postres_005', 'Flan de huevo', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 240, 8, 32, 8, 4, true, true, '{"lactosa","huevo"}', '[{"name":"Leche","amount":500,"unit":"ml"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Azúcar","amount":120,"unit":"g"}]'::jsonb, '{"Separar 60 g de azúcar y reservar el resto para la crema.","Verter los 60 g de azúcar en un cazo a fuego medio sin remover hasta que se funda y tome color ámbar dorado.","Repartir el caramelo caliente entre 4 flaneras individuales, girándolas para cubrir el fondo. Reservar.","Calentar leche en un cazo a fuego medio hasta que esté caliente pero sin llegar a hervir. Retirar del fuego.","Cascar huevo en un bol grande y añadir los 60 g de azúcar reservados. Mezclar con varillas hasta que el azúcar se integre.","Verter la leche caliente sobre la mezcla de huevos en hilo fino, removiendo sin parar para no cuajar los huevos.","Colar la mezcla con un colador fino y repartirla entre las 4 flaneras con el caramelo.","Precalentar el horno a 170 °C con calor arriba y abajo.","Colocar las flaneras en una bandeja honda. Verter agua caliente en la bandeja hasta alcanzar la mitad de la altura de los moldes.","Hornear al baño maría a 170 °C durante 35 min, hasta que el flan esté cuajado pero con un ligero temblor en el centro.","Retirar las flaneras del baño maría y dejar enfriar a temperatura ambiente hasta que estén templadas.","Refrigerar las flaneras en la nevera durante un mínimo de 2 h hasta que estén bien frías y firmes.","Pasar un cuchillo fino por el borde de cada flanera, colocar un plato encima y desmoldar con un giro rápido. Servir."}', 'Flan de huevo casero al baño maría', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Haz un caramelo, forra los moldes, bate huevos con leche y azúcar, y cuece al baño maría unos 40 minutos."}]'::jsonb, '{"Flan"}', NULL, NULL, NULL, '{}', NULL),
  ('postres_006', 'Arroz con leche', 'postres', 'none', 'arroz', ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 300, 7, 54, 6, 4, true, true, '{"lactosa"}', '[{"name":"Arroz","amount":150,"unit":"g"},{"name":"Leche","amount":800,"unit":"ml"},{"name":"Azúcar","amount":100,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar limón con un pelador o cuchillo, extrayendo solo la parte amarilla sin la parte blanca.","Verter leche en un cazo amplio y añadir la piel de limón. Llevar a ebullición a fuego medio.","Añadir arroz a la leche cuando rompa a hervir. Bajar el fuego a suave y remover.","Cocer el arroz a fuego suave durante 30 min, removiendo cada 2-3 min hasta que esté cremoso y tierno.","Retirar la piel de limón del cazo y desecharla.","Añadir azúcar al arroz y remover hasta que se disuelva por completo, unos 2 min a fuego suave.","Repartir el arroz con leche en 4 cuencos individuales.","Dejar enfriar los cuencos a temperatura ambiente y refrigerar hasta que estén fríos antes de servir."}', 'Arroz con leche tradicional aromatizado con limón', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_007', 'Manzana asada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'invierno', 160, 1, 38, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":4,"unit":"ud"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar manzana bajo el grifo y secar bien con un paño.","Descorazonar cada manzana con un descorazonador o cuchillo, sin llegar al fondo, para crear un hueco central.","Exprimir limón y reservar el zumo en un bol pequeño.","Precalentar el horno a 180 °C con calor arriba y abajo.","Colocar las manzanas en pie sobre una fuente de horno, dejando espacio entre ellas.","Repartir azúcar en partes iguales dentro del hueco de cada manzana.","Verter unas gotas del zumo de limón sobre cada manzana para aromatizar y evitar la oxidación.","Hornear la fuente en el centro del horno a 180 °C durante 35 min, hasta que las manzanas estén tiernas al pincharlas con una brocheta.","Retirar la fuente del horno y dejar reposar las manzanas 5 min antes de servir.","Servir cada manzana en un plato individual, regando con el jugo caramelizado que haya quedado en la fuente."}', 'Manzanas asadas al horno con azúcar y limón', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Descorazona las manzanas, colócalas en una fuente con un poco de azúcar y unas gotas de limón, y hornea unos 35-40 minutos hasta que estén tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_008', 'Yogur natural', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 2, 'facil', 'all', 65, 5, 6, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur natural","amount":250,"unit":"g"}]'::jsonb, '{"Reparte el yogur en dos cuencos","Sirve frío"}', 'Yogur natural sin nada más, el postre de siempre', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_009', 'Yogur con fruta', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 150, 6, 24, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":100,"unit":"g"}]'::jsonb, '{"Pelar plátano y cortar en rodajas de 1 cm.","Lavar fresas, retirar el pedúnculo y cortar en cuartos.","Repartir yogur natural en 2 cuencos individuales a partes iguales.","Distribuir las rodajas de plátano y las fresas en cuartos sobre el yogur de cada cuenco."}', 'Yogur natural con plátano y fresas troceadas', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_013', 'Yogur de sabores', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 1, 'facil', 'all', 110, 4, 16, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur de sabores","amount":250,"unit":"g"}]'::jsonb, '{"Abre los yogures","Sirve fríos"}', 'Yogur procesado de frutas de nevera (frambuesa/fresa), el postre más rápido', NULL, '{"Yogur de fresa","Yogur de frutas"}', NULL, NULL, NULL, '{}', NULL),
  ('postres_014', 'Compota de manzana', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 130, 1, 32, 0, 4, true, true, '{}', '[{"name":"Manzana","amount":4,"unit":"ud"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Canela","amount":2,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar manzana y cortar en trozos de tamaño similar.","Exprimir limón y reservar el zumo.","Poner los trozos de manzana en un cazo con azúcar, canela y el zumo de limón.","Añadir 2 cucharadas de agua y remover para mezclar todos los ingredientes.","Tapar el cazo y cocer a fuego suave hasta que la manzana esté tierna, unos 20 min.","Retirar del fuego y triturar o dejar en trozos según la textura deseada.","Servir la compota tibia o dejar enfriar antes de llevar a la mesa."}', 'Compota de manzana casera con canela, de cazo', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_015', 'Crema de chocolate', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 280, 6, 28, 16, 4, true, true, '{"lactosa"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Chocolate negro","amount":120,"unit":"g"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Maicena","amount":20,"unit":"g"}]'::jsonb, '{"Reservar 50 ml de leche fría en un vaso pequeño para disolver la maicena más adelante.","Trocear chocolate negro en piezas pequeñas para que se funda con facilidad.","Disolver maicena en los 50 ml de leche fría reservados, removiendo hasta que no queden grumos.","Verter el resto de leche y azúcar en un cazo y calentar a fuego medio hasta que empiece a humear, sin llegar a hervir.","Añadir el chocolate troceado al cazo y remover sin parar a fuego suave hasta que se funda por completo.","Incorporar la mezcla de maicena disuelta al cazo en hilo fino, sin dejar de remover.","Cocer a fuego suave sin parar de remover hasta que la crema espese y nape la cuchara, unos 4 min.","Repartir la crema en 4 cuencos individuales y dejar enfriar a temperatura ambiente durante 10 min.","Servir a temperatura ambiente o refrigerar hasta el momento de servir."}', 'Crema de chocolate de cazo, para enfriar en la nevera', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_016', 'Tarta de limón', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 70, 'elaborada', 'all', 340, 7, 42, 16, 8, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Galletas María","amount":200,"unit":"g"},{"name":"Mantequilla","amount":80,"unit":"g"},{"name":"Leche condensada","amount":400,"unit":"g"},{"name":"Limón","amount":3,"unit":"ud"},{"name":"Huevo","amount":3,"unit":"ud"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que esté completamente líquida.","Retirar el cazo del fuego y reservar la mantequilla fundida.","Triturar galletas maría en una bolsa con un rodillo hasta obtener un polvo fino y uniforme.","Mezclar las galletas trituradas con la mantequilla fundida en un bol hasta que la mezcla tenga textura de arena húmeda.","Verter la mezcla en un molde desmontable de 22 cm y presionar con el dorso de una cuchara para formar una base compacta.","Refrigerar el molde en la nevera hasta que la base esté firme.","Precalentar el horno a 160 °C con calor arriba y abajo.","Rallar la piel de limón con un rallador fino, evitando la parte blanca, hasta obtener la ralladura de los 3 limones.","Exprimir los limones rallados y colar el zumo para retirar pepitas y pulpa. Reservar.","Separar las yemas de huevo y colocarlas en un bol amplio. Reservar las claras para otro uso.","Añadir leche condensada al bol con las yemas y batir con varillas hasta obtener una mezcla homogénea.","Incorporar el zumo de limón colado a la mezcla de leche condensada y yemas. Remover hasta integrar.","Añadir la ralladura de limón a la mezcla anterior y remover hasta que quede distribuida de forma uniforme.","Verter el relleno sobre la base de galleta fría con cuidado para no desplazarla.","Hornear a 160 °C durante 25 min, hasta que el relleno esté cuajado en los bordes con un ligero temblor en el centro.","Retirar del horno y dejar enfriar a temperatura ambiente hasta que el molde no queme al tacto.","Refrigerar la tarta en la nevera hasta que esté completamente firme y fría.","Desmoldar con cuidado retirando el aro del molde. Cortar en porciones y servir."}', 'Tarta de limón casera con base de galleta', '[{"appliance":"horno","time":70,"difficulty":"elaborada","prepSummary":"Precalienta el horno a 160°C. Haz la base de galleta, mezcla el relleno de limón y hornea 25 minutos. Deja enfriar en la nevera."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_017', 'Tarta de queso', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 80, 'elaborada', 'all', 380, 9, 32, 24, 8, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Galletas María","amount":180,"unit":"g"},{"name":"Mantequilla","amount":80,"unit":"g"},{"name":"Queso crema","amount":400,"unit":"g"},{"name":"Nata para montar","amount":200,"unit":"ml"},{"name":"Azúcar","amount":120,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"}]'::jsonb, '{"Precalentar el horno a 170 °C con calor arriba y abajo.","Triturar galletas maría en un bol hasta obtener un polvo fino.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida.","Mezclar la mantequilla fundida con las galletas trituradas hasta que la mezcla quede húmeda y uniforme.","Extender la mezcla de galletas en la base de un molde desmontable de 22 cm y presionar bien para formar una capa compacta. Reservar.","Batir queso crema con azúcar en un bol a velocidad media hasta que la mezcla esté suave y sin grumos.","Añadir huevo uno a uno al bol, batiendo después de cada uno hasta que se integre por completo.","Incorporar nata para montar a la mezcla y remover a velocidad suave hasta obtener una crema homogénea.","Verter la crema de queso sobre la base de galletas en el molde, alisando la superficie con una espátula.","Colocar el molde dentro de una bandeja honda. Llenar la bandeja con agua caliente hasta alcanzar 2 cm de altura para el baño maría.","Hornear a 170 °C durante 50 min al baño maría hasta que los bordes estén cuajados y el centro tiemble ligeramente al mover el molde.","Retirar la tarta del horno y del baño maría. Dejar enfriar a temperatura ambiente durante 30 min.","Refrigerar la tarta en la nevera un mínimo de 4 horas hasta que esté completamente firme.","Desmoldar con cuidado y servir en porciones."}', 'Tarta de queso al horno, para hacer de antemano', '[{"appliance":"horno","time":80,"difficulty":"elaborada","prepSummary":"Precalienta el horno a 170°C. Prepara la base de galleta, bate el relleno y hornea al baño maría unos 50 minutos. Enfría en la nevera."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_018', 'Bizcocho de yogur', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 55, 'normal', 'all', 290, 6, 38, 12, 8, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Yogur natural","amount":125,"unit":"g"},{"name":"Harina","amount":250,"unit":"g"},{"name":"Azúcar","amount":180,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Aceite de girasol","amount":80,"unit":"ml"},{"name":"Levadura química","amount":16,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C con calor arriba y abajo.","Enharinar un molde redondo de unos 22 cm y reservar.","Cascar huevo en un bol grande y batir hasta que estén espumosos.","Añadir azúcar y mezclar hasta que la mezcla blanquee ligeramente.","Incorporar yogur natural y mezclar hasta obtener una masa homogénea.","Añadir aceite de girasol en hilo fino y mezclar hasta integrarlo por completo.","Tamizar harina junto con levadura química sobre el bol.","Mezclar con movimientos envolventes hasta que no queden grumos, sin trabajar la masa en exceso.","Verter la masa en el molde reservado y alisar la superficie.","Hornear a 180 °C durante 40 min, hasta que al pinchar el centro con un palillo salga limpio.","Retirar el molde del horno y dejar templar 10 min antes de desmoldar.","Desmoldar el bizcocho sobre una rejilla y servir en porciones."}', 'Bizcocho de yogur de toda la vida, el de las medidas del vasito', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Mezcla con las medidas del vaso de yogur, vierte en el molde y hornea unos 40 minutos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_019', 'Tarta de queso vasca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 580, 9, 29, 46, 8, true, true, '{"lactosa","huevo","gluten"}', '[{"name":"Queso crema","amount":600,"unit":"g"},{"name":"Nata para montar","amount":400,"unit":"ml"},{"name":"Azúcar","amount":220,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo.","Forrar un molde desmontable de 22 cm con papel de horno, dejando que sobresalga por los bordes.","Batir queso crema con azúcar y sal hasta obtener una crema lisa sin grumos.","Añadir huevo de uno en uno, batiendo bien después de cada uno.","Incorporar nata para montar poco a poco sin dejar de batir hasta integrarla por completo.","Tamizar harina sobre la mezcla y batir a velocidad baja solo hasta que desaparezca.","Verter la mezcla en el molde forrado.","Hornear 50 min, hasta que la superficie esté muy oscura y el centro tiemble ligeramente al mover el molde.","Dejar enfriar dentro del molde a temperatura ambiente hasta que se atempere por completo.","Refrigerar un mínimo de 3 h antes de desmoldar y cortar en porciones.","Desmoldar, cortar en porciones y servir fría."}', 'Tarta de queso cremosa y quemada por fuera al estilo vasco, sin base de galleta.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_020', 'Tarta Tatin de manzana caramelizada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 70, 'elaborada', 'all', 480, 3, 65, 23, 6, true, true, '{"gluten","lactosa"}', '[{"name":"Manzana reineta","amount":1000,"unit":"g"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Azúcar","amount":150,"unit":"g"},{"name":"Hojaldre","amount":230,"unit":"g"},{"name":"Canela en polvo","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar manzana reineta, descorazonarlas y cortarlas por la mitad.","Fundir mantequilla en una sartén apta para horno de 24 cm a fuego medio.","Añadir azúcar a la sartén sin remover hasta que se forme un caramelo dorado.","Retirar la sartén del fuego.","Colocar las mitades de manzana bien apretadas sobre el caramelo, con la parte redondeada hacia abajo.","Espolvorear canela en polvo de manera uniforme sobre las manzanas.","Volver a poner la sartén a fuego medio-suave hasta que las manzanas empiecen a ablandarse por la base.","Extender hojaldre sobre la sartén cubriendo las manzanas completamente.","Remeter los bordes del hojaldre hacia dentro con una cuchara para sellar.","Pinchar el hojaldre por toda la superficie con un tenedor.","Hornear a 190 °C hasta que el hojaldre esté dorado y crujiente.","Retirar la sartén del horno y dejar templar fuera del fuego.","Colocar un plato grande boca abajo sobre la sartén.","Volcar la sartén con cuidado usando guantes para desmoldar la tarta con las manzanas arriba.","Servir templada, cortada en porciones."}', 'Tarta de manzana caramelizada que se vuelca al servir, con el caramelo brillante quedando por encima.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_021', 'Brownie de chocolate con nueces', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 500, 6, 48, 31, 8, true, true, '{"gluten","lactosa","huevo","frutos_secos"}', '[{"name":"Chocolate negro","amount":200,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar","amount":200,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Harina","amount":100,"unit":"g"},{"name":"Nueces","amount":80,"unit":"g"},{"name":"Cacao en polvo","amount":20,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde rectangular de 20x20 cm con papel de horno.","Trocear chocolate negro en trozos pequeños.","Fundir el chocolate troceado con mantequilla al baño maría, removiendo hasta que la mezcla esté lisa.","Retirar del calor y dejar templar la mezcla de chocolate y mantequilla.","Trocear nueces en trozos gruesos y reservar.","Batir huevo con azúcar en un bol hasta que la mezcla blanquee ligeramente.","Añadir la mezcla de chocolate templada al bol con los huevos y remover hasta integrar.","Tamizar harina, cacao en polvo y sal sobre la mezcla.","Remover con espátula hasta que no queden restos de harina, sin trabajar la masa en exceso.","Añadir las nueces troceadas y mezclar suavemente para repartirlas por toda la masa.","Verter la masa en el molde forrado y extender de manera uniforme con la espátula.","Hornear a 180 °C durante 23 min, hasta que la superficie esté cuarteada y el centro siga húmedo.","Dejar enfriar el brownie por completo dentro del molde antes de desmoldar.","Cortar el brownie en 8 cuadrados iguales y servir."}', 'Brownie denso y húmedo con corteza crujiente y trozos de nuez.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_022', 'Tarta de limón con merengue', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 460, 6, 70, 17, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":200,"unit":"g"},{"name":"Mantequilla","amount":140,"unit":"g"},{"name":"Azúcar","amount":360,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Agua fría","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":150,"unit":"ml"},{"name":"Ralladura de limón","amount":10,"unit":"g"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Agua","amount":250,"unit":"ml"},{"name":"Yema de huevo","amount":4,"unit":"ud"},{"name":"Clara de huevo","amount":4,"unit":"ud"}]'::jsonb, '{"Cortar mantequilla fría en dados pequeños.","Mezclar harina con los dados de mantequilla fría con las yemas de los dedos hasta obtener una textura arenosa.","Añadir huevo y agua fría a la mezcla arenosa.","Amasar lo justo hasta formar una bola homogénea, sin trabajar en exceso la masa.","Envolver la bola en film transparente y refrigerar hasta que esté firme.","Precalentar el horno a 180 °C.","Estirar la masa sobre una superficie enharinada hasta formar un disco de unos 28 cm de diámetro.","Forrar un molde de 24 cm con la masa estirada, presionando bien los bordes.","Pinchar la base con un tenedor por toda la superficie para evitar que suba al hornear.","Cubrir la masa con papel de horno y peso (legumbres o bolas de cerámica) y hornear a 180 °C.","Retirar el peso y el papel, y hornear a 180 °C hasta que la base esté dorada.","Retirar la base del horno y dejar enfriar completamente sobre una rejilla.","Disolver maicena en agua dentro de un cazo, removiendo hasta que no queden grumos.","Añadir zumo de limón, ralladura de limón y 180 g de azúcar al cazo.","Calentar a fuego medio, removiendo sin parar, hasta que la mezcla espese y se despegue del fondo.","Retirar el cazo del fuego.","Añadir yema de huevo una a una, removiendo con rapidez tras cada incorporación.","Volver a calentar a fuego suave, removiendo, hasta que la crema esté bien ligada y brillante.","Retirar del fuego y añadir 40 g de mantequilla, removiendo hasta que se funda por completo.","Verter el relleno de limón caliente sobre la base horneada y alisar la superficie con una espátula.","Dejar enfriar el relleno a temperatura ambiente hasta que esté templado.","Montar clara de huevo con unas varillas a punto de nieve firme.","Añadir los 180 g de azúcar restantes poco a poco, sin dejar de batir, hasta lograr un merengue brillante y firme.","Cubrir el relleno de limón con el merengue, distribuyéndolo por toda la superficie.","Formar picos en el merengue con ayuda de una espátula o el dorso de una cuchara.","Tostar el merengue con un soplete de cocina o bajo el grill del horno hasta que se dore ligeramente, vigilando que no se queme.","Refrigerar la tarta hasta que esté bien fría y el relleno firme antes de cortar.","Servir en porciones, cortando con un cuchillo limpio y pasado por agua caliente entre corte y corte."}', 'Tarta de limón ácida bajo un merengue tostado con soplete, dulce y cítrica a la vez.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_023', 'Tiramisú clásico', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 610, 11, 47, 42, 6, false, true, '{"gluten","huevo","lactosa"}', '[{"name":"Bizcochos de soletilla","amount":200,"unit":"g"},{"name":"Café espresso","amount":300,"unit":"ml"},{"name":"Mascarpone","amount":500,"unit":"g"},{"name":"Yema de huevo","amount":4,"unit":"ud"},{"name":"Clara de huevo","amount":4,"unit":"ud"},{"name":"Azúcar","amount":100,"unit":"g"},{"name":"Cacao en polvo","amount":15,"unit":"g"},{"name":"Licor de café","amount":30,"unit":"ml"}]'::jsonb, '{"Preparar café espresso y dejar enfriar a temperatura ambiente.","Verter el café frío en un plato hondo y añadir licor de café. Mezclar y reservar.","Batir yema de huevo con la mitad de azúcar en un bol hasta que blanqueen y doblen su volumen.","Añadir mascarpone a las yemas y mezclar con suavidad hasta obtener una crema homogénea. Reservar.","Montar clara de huevo en un bol limpio a velocidad media hasta que empiecen a espumar.","Añadir el resto del azúcar poco a poco y seguir batiendo hasta lograr picos firmes.","Incorporar las claras montadas a la crema de mascarpone en 3 tandas, con movimientos envolventes.","Mojar bizcochos de soletilla en la mezcla de café, 1 segundo por cada lado, sin empaparlos.","Colocar una capa de bizcochos en el fondo de una fuente, cubriendo toda la base.","Extender la mitad de la crema de mascarpone sobre los bizcochos y alisar la superficie.","Mojar el resto de los bizcochos de soletilla en el café y formar una segunda capa sobre la crema.","Cubrir con el resto de la crema de mascarpone y alisar bien la superficie.","Tapar la fuente con film transparente y refrigerar un mínimo de 4 h, mejor toda la noche.","Espolvorear cacao en polvo por toda la superficie justo antes de servir."}', 'Tiramisú clásico en capas de café y mascarpone, con cacao espolvoreado por encima.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_024', 'Mousse de chocolate', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 340, 9, 20, 24, 4, true, true, '{"huevo"}', '[{"name":"Chocolate negro","amount":200,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Trocear chocolate negro en piezas pequeñas y colocarlas en un bol apto para microondas.","Fundir el chocolate en el microondas en tandas de 30 s, removiendo entre cada tanda, hasta que esté liso.","Dejar templar el chocolate fundido hasta que esté tibio al tacto.","Separar huevo: yemas en un bol grande y claras en otro bol grande y limpio.","Añadir las yemas al chocolate templado de una en una, removiendo bien tras cada adición.","Montar las claras con sal con unas varillas a velocidad alta hasta que estén a punto de nieve firme.","Añadir un tercio de las claras montadas al chocolate y remover con energía hasta integrar.","Incorporar el resto de las claras montadas con movimientos envolventes hasta que no queden restos blancos.","Repartir la mousse en 4 copas o vasitos individuales.","Refrigerar las copas al menos 120 min, hasta que la mousse esté cuajada y firme."}', 'Mousse de chocolate aireada y sedosa, hecha solo con chocolate y huevo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_025', 'Crumble de manzana y canela', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'all', 470, 4, 68, 21, 6, true, true, '{"gluten","lactosa"}', '[{"name":"Manzana","amount":800,"unit":"g"},{"name":"Azúcar","amount":60,"unit":"g"},{"name":"Canela en polvo","amount":5,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Harina","amount":150,"unit":"g"},{"name":"Azúcar moreno","amount":100,"unit":"g"},{"name":"Copos de avena","amount":50,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar manzana y descorazonarlas.","Cortar las manzanas peladas en dados de 2 cm.","Cortar mantequilla fría en dados pequeños y reservar en frío.","Mezclar los dados de manzana con azúcar y la mitad de canela en polvo en una fuente de horno.","Repartir la mezcla de manzana en la base de la fuente formando una capa uniforme.","Mezclar harina, azúcar moreno, copos de avena, el resto de la canela en polvo y sal en un bol.","Añadir los dados de mantequilla fría al bol y desmigar con las yemas de los dedos hasta obtener migas gruesas.","Repartir las migas sobre la manzana cubriendo toda la superficie sin apretar.","Hornear a 190 °C durante 38 min, hasta que la manzana burbujee por los bordes y las migas estén doradas.","Retirar del horno y dejar templar 10 min antes de servir.","Servir el crumble templado directamente de la fuente."}', 'Crumble de manzana blanda bajo una capa de migas doradas y crujientes con canela.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_026', 'Profiteroles con chocolate caliente', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 740, 10, 40, 58, 6, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Agua","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Harina","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Nata para montar","amount":500,"unit":"ml"},{"name":"Azúcar","amount":30,"unit":"g"},{"name":"Chocolate negro","amount":200,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Forrar dos bandejas de horno con papel de horno.","Calentar agua, mantequilla y sal en un cazo a fuego medio hasta que rompa a hervir.","Retirar el cazo del fuego y añadir harina de golpe.","Remover con fuerza hasta que la masa forme una bola y se despegue de las paredes del cazo.","Volver a poner el cazo a fuego suave y remover 2 min hasta que la masa quede ligeramente seca.","Pasar la masa a un bol y dejar templar.","Añadir huevo de uno en uno a la masa, batiendo bien tras cada uno hasta que quede lisa y brillante.","Introducir la masa en una manga pastelera con boquilla redonda.","Formar bolitas de unos 3 cm sobre las bandejas, separadas entre sí al menos 3 cm.","Hornear 28 min sin abrir el horno, hasta que los profiteroles estén dorados e inflados.","Retirar las bandejas del horno y dejar enfriar los profiteroles sobre una rejilla.","Verter nata para montar en un bol frío, reservando 100 ml aparte para la salsa de chocolate.","Añadir azúcar a los 400 ml de nata y montar con varillas a velocidad alta hasta que esté firme.","Introducir la nata montada en una manga pastelera con boquilla fina.","Rellenar cada profiterol inyectando nata montada por la base hasta notar que se hincha ligeramente.","Trocear chocolate negro y colocarlo en un bol resistente al calor sobre un cazo con agua caliente.","Calentar el cazo a fuego suave y añadir los 100 ml de nata reservados al chocolate.","Remover sin parar hasta que el chocolate y la nata formen una salsa lisa y brillante.","Apilar los profiteroles rellenos en platos o fuente y bañar con la salsa de chocolate caliente."}', 'Bolitas de pasta choux rellenas de nata, bañadas en chocolate caliente al momento.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_027', 'Cookies rellenas de chocolate fundente', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 590, 7, 70, 30, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar moreno","amount":120,"unit":"g"},{"name":"Azúcar","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Chocolate negro","amount":150,"unit":"g"},{"name":"Bicarbonato","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"}]'::jsonb, '{"Templar mantequilla hasta que esté en pomada (blanda pero sin fundir).","Batir la mantequilla en pomada con azúcar moreno y azúcar hasta obtener una crema pálida y esponjosa.","Añadir huevo y extracto de vainilla a la crema y batir hasta que estén completamente integrados.","Mezclar harina, bicarbonato y sal en un bol aparte hasta que estén bien combinados.","Añadir la mezcla de harina a la crema de mantequilla y remover lo justo hasta que se forme una masa homogénea.","Tapar la masa con film y refrigerar hasta que esté firme y manejable.","Precalentar el horno a 180 °C y forrar una bandeja con papel de horno.","Cortar chocolate negro en 12 trozos iguales para usar como relleno.","Dividir la masa fría en 12 porciones del mismo tamaño.","Aplanar cada porción en la palma de la mano hasta formar un disco.","Colocar un trozo de chocolate negro en el centro de cada disco.","Cerrar la masa alrededor del chocolate, sellando bien los bordes para que no se escape al hornear.","Disponer las bolas en la bandeja separadas al menos 5 cm entre sí.","Hornear a 180 °C hasta que los bordes estén dorados y el centro siga pálido.","Reposar las cookies en la bandeja fuera del horno para que se asienten sin romperse.","Servir templadas para que el chocolate del interior esté fundido."}', 'Cookies con el centro relleno de chocolate fundente que se derrama al partirlas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_028', 'Red velvet con glaseado de queso crema', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 80, 'elaborada', 'all', 720, 8, 96, 32, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":280,"unit":"g"},{"name":"Cacao en polvo","amount":15,"unit":"g"},{"name":"Bicarbonato","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Mantequilla","amount":200,"unit":"g"},{"name":"Azúcar","amount":300,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Suero de leche","amount":240,"unit":"ml"},{"name":"Colorante rojo alimentario","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Queso crema","amount":250,"unit":"g"},{"name":"Azúcar glas","amount":250,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Engrasar dos moldes redondos de 18 cm y forrar la base con papel de horno.","Tamizar harina, cacao en polvo, bicarbonato y sal juntos en un bol grande.","Mezclar en un bol pequeño suero de leche, colorante rojo alimentario, vinagre y extracto de vainilla.","Batir mantequilla con azúcar en un bol grande a velocidad alta hasta obtener una mezcla pálida y esponjosa.","Añadir huevo de uno en uno, batiendo bien tras cada incorporación hasta que quede integrado.","Añadir un tercio de la mezcla de harina a la masa y mezclar a velocidad baja hasta que se integre.","Añadir la mitad de la mezcla de suero de leche y mezclar a velocidad baja hasta que se integre.","Repetir alternando: un tercio de harina, el resto del suero de leche y, por último, el tercer tercio de harina.","Repartir la masa a partes iguales entre los dos moldes preparados y alisar la superficie con una espátula.","Hornear los dos moldes a 175 °C durante 30 min, hasta que al pinchar el centro con un palillo salga limpio.","Sacar los moldes del horno y dejar reposar los bizcochos dentro 10 min.","Batir queso crema con la mantequilla restante en un bol hasta obtener una mezcla lisa y sin grumos.","Añadir azúcar glas tamizado en 2 tandas, batiendo a velocidad baja hasta lograr un glaseado liso y cremoso.","Desmoldar los bizcochos sobre una rejilla y dejar enfriar por completo.","Colocar un bizcocho sobre el plato de servir y extender una capa generosa de glaseado sobre la superficie.","Colocar el segundo bizcocho encima y cubrir toda la tarta con el resto del glaseado.","Refrigerar la tarta 30 min hasta que el glaseado asiente antes de cortar y servir."}', 'Bizcocho rojo intenso de cacao con un cremoso glaseado blanco de queso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_029', 'Tarta de zanahoria con glaseado de queso', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 75, 'normal', 'all', 560, 7, 62, 30, 8, true, true, '{"gluten","lactosa","huevo","frutos_secos"}', '[{"name":"Zanahoria","amount":300,"unit":"g"},{"name":"Harina","amount":280,"unit":"g"},{"name":"Azúcar moreno","amount":200,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Canela en polvo","amount":5,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Bicarbonato","amount":6,"unit":"g"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Nueces","amount":60,"unit":"g"},{"name":"Queso crema","amount":180,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Azúcar glas","amount":180,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Rallar zanahoria con un rallador fino y reservar.","Picar nueces en trozos pequeños y reservar.","Engrasar un molde redondo de 22 cm y forrar la base con papel de horno.","Mezclar harina, bicarbonato, levadura química, canela en polvo, nuez moscada y sal en un bol hasta integrar.","Batir huevo con azúcar moreno en un bol grande hasta que la mezcla blanquee y doble su volumen.","Añadir aceite de girasol en hilo fino sin dejar de batir hasta que quede integrado.","Incorporar la mezcla de harina en 3 tandas con movimientos envolventes hasta que no queden restos de harina.","Añadir la zanahoria rallada y las nueces picadas y mezclar con espátula hasta distribuirlas de forma homogénea.","Verter la masa en el molde preparado y alisar la superficie con una espátula.","Hornear a 175 °C durante 50 min, hasta que al pinchar el centro con un palillo salga limpio.","Retirar el molde del horno y dejar enfriar sobre una rejilla hasta que esté a temperatura ambiente.","Sacar queso crema y mantequilla de la nevera 20 min antes para que estén a temperatura ambiente.","Batir el queso crema con la mantequilla a velocidad media hasta obtener una crema lisa y sin grumos.","Añadir azúcar glas tamizado poco a poco sin dejar de batir hasta lograr un glaseado liso y firme.","Desmoldar la tarta fría con cuidado sobre una rejilla o plato de servir.","Cubrir la superficie y los laterales de la tarta con el glaseado, extendiéndolo con una espátula."}', 'Bizcocho húmedo y especiado de zanahoria cubierto con un glaseado cremoso de queso.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_030', 'Panna cotta de vainilla con frutos rojos', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 460, 3, 32, 36, 4, true, true, '{"lactosa"}', '[{"name":"Nata para montar","amount":400,"unit":"ml"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Azúcar","amount":90,"unit":"g"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Hojas de gelatina","amount":6,"unit":"g"},{"name":"Frutos rojos","amount":200,"unit":"g"},{"name":"Agua","amount":30,"unit":"ml"}]'::jsonb, '{"Sumergir hojas de gelatina en un bol con agua fría hasta que estén blandas.","Calentar nata para montar, leche, azúcar y extracto de vainilla en un cazo a fuego medio hasta que esté caliente sin que llegue a hervir.","Escurrir las hojas de gelatina y añadirlas al cazo fuera del fuego.","Remover hasta que la gelatina se disuelva por completo en la mezcla de nata.","Repartir la mezcla en 4 moldes o vasos individuales.","Refrigerar los moldes hasta que la panna cotta cuaje por completo.","Calentar frutos rojos, el azúcar restante y agua en un cazo a fuego medio.","Cocer a fuego medio hasta que los frutos rojos suelten su jugo y la salsa espese ligeramente.","Retirar el cazo del fuego y triturar la mitad de la salsa, dejando el resto con los frutos enteros.","Dejar enfriar la salsa de frutos rojos a temperatura ambiente.","Desmoldar cada panna cotta pasando un cuchillo fino por el borde o servir directamente en el vaso.","Cubrir cada panna cotta con la salsa de frutos rojos y servir."}', 'Panna cotta cremosa de vainilla que tiembla al moverla, con una salsa brillante de frutos rojos.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_031', 'Helado casero de vainilla sin heladora', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 500, 7, 39, 35, 6, true, true, '{"lactosa"}', '[{"name":"Nata para montar","amount":500,"unit":"ml"},{"name":"Leche condensada","amount":400,"unit":"g"},{"name":"Extracto de vainilla","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Introducir el bol y las varillas en el congelador para enfriarlos.","Verter nata para montar en el bol frío y montar con las varillas hasta que forme picos firmes al levantar.","Mezclar leche condensada, extracto de vainilla y sal en un bol grande hasta integrar.","Añadir la nata montada sobre la mezcla de leche condensada en 3 tandas, con movimientos envolventes de abajo hacia arriba.","Verter la mezcla en un recipiente hermético apto para congelador.","Alisar la superficie con una espátula o el dorso de una cuchara.","Tapar el recipiente y congelar hasta que el helado esté completamente firme.","Sacar el helado del congelador y dejar atemperar hasta que sea posible bolear con facilidad.","Servir en boles o copas con una cuchara de helado."}', 'Helado cremoso de vainilla sin necesitar heladora, solo nata, leche condensada y paciencia.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_032', 'Sorbete de limón', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 190, 0, 48, 0, 4, true, true, '{}', '[{"name":"Zumo de limón","amount":200,"unit":"ml"},{"name":"Agua","amount":350,"unit":"ml"},{"name":"Azúcar","amount":180,"unit":"g"},{"name":"Ralladura de limón","amount":5,"unit":"g"}]'::jsonb, '{"Calentar agua con azúcar en un cazo a fuego medio hasta que el azúcar se disuelva por completo.","Retirar el cazo del fuego y añadir ralladura de limón. Remover para integrar.","Dejar enfriar el almíbar por completo a temperatura ambiente.","Añadir zumo de limón al almíbar frío. Mezclar hasta obtener una mezcla homogénea.","Verter la mezcla en un recipiente bajo y ancho apto para congelador.","Congelar la mezcla durante 60 min.","Raspar la mezcla con un tenedor, rompiendo los cristales de hielo de los bordes hacia el centro.","Congelar de nuevo durante 35 min.","Raspar de nuevo con el tenedor, removiendo toda la superficie para airear la textura.","Repetir el ciclo de congelado 35 min y raspado 3 veces más hasta lograr una textura granizada y suelta.","Servir el sorbete directamente del congelador en copas frías."}', 'Sorbete de limón refrescante y ácido, con esa textura granizada tan característica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_033', 'Coulant de chocolate', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 25, 'normal', 'all', 680, 10, 45, 49, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Chocolate negro","amount":150,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Harina","amount":60,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Engrasar 4 moldes individuales con mantequilla y enharinar con harina, sacudiendo el exceso.","Trocear chocolate negro en trozos pequeños y colocar en un bol resistente al calor.","Fundir el chocolate troceado con el resto de la mantequilla al baño maría hasta que esté liso y homogéneo.","Retirar el bol del calor y dejar templar hasta que esté tibio al tacto.","Batir huevo y yema de huevo con azúcar en un bol grande hasta que la mezcla blanquee ligeramente.","Añadir el chocolate fundido templado a la mezcla de huevos y remover hasta integrar completamente.","Incorporar el resto de la harina a la mezcla y remover con espátula hasta que no queden grumos.","Repartir la masa entre los 4 moldes preparados llenando hasta ¾ de su capacidad.","Hornear a 200 °C durante 10 min, hasta que la superficie esté cuajada pero el centro siga líquido.","Retirar los moldes del horno y dejar reposar 1 min sin desmoldar.","Desmoldar cada coulant volcando con cuidado sobre el plato de servicio y servir de inmediato."}', 'Bizcocho de chocolate que se abre al partirlo, dejando salir un centro líquido y caliente.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('postres_034', 'Tarta borracha de ron', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 400, 6, 60, 13, 8, false, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Azúcar","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Levadura química","amount":8,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Agua","amount":200,"unit":"ml"},{"name":"Ron","amount":80,"unit":"ml"},{"name":"Ralladura de limón","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Engrasar y enharinar un molde de 22 cm.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida. Reservar y dejar templar.","Batir huevo con 150 g de azúcar en un bol hasta que la mezcla blanquee y duplique su volumen.","Añadir leche y la mantequilla fundida al bol y mezclar hasta integrar.","Tamizar harina junto con levadura química directamente sobre el bol.","Incorporar la harina tamizada con movimientos envolventes hasta que no queden grumos.","Verter la masa en el molde y hornear 38 min, hasta que al pinchar con un palillo salga limpio.","Calentar agua con los 150 g de azúcar restantes y ralladura de limón en un cazo a fuego medio.","Remover hasta que la azúcar se disuelva y el almíbar rompa a hervir. Retirar del fuego.","Dejar templar el almíbar 5 min y añadir ron. Remover y reservar.","Retirar el bizcocho del horno cuando el palillo salga limpio. Dejar en el molde.","Pinchar toda la superficie del bizcocho con un palillo, haciendo agujeros uniformes.","Verter el almíbar despacio sobre el bizcocho, en varias veces, dejando que lo absorba entre cada adición.","Dejar reposar el bizcocho en el molde al menos 30 min hasta que quede bien empapado.","Desmoldar y servir."}', 'Bizcocho jugoso empapado en almíbar de ron, muy húmedo y aromático.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_035', 'Galletas de mantequilla decoradas', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 620, 7, 82, 28, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":300,"unit":"g"},{"name":"Mantequilla","amount":200,"unit":"g"},{"name":"Azúcar glas","amount":270,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Clara de huevo","amount":1,"unit":"ud"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Templar mantequilla hasta que esté en pomada, blanda pero sin derretir.","Batir la mantequilla en pomada con azúcar glas (120 g) hasta obtener una crema lisa y homogénea.","Añadir huevo y extracto de vainilla a la crema y mezclar hasta integrar.","Tamizar harina junto con sal sobre la crema.","Mezclar lo justo hasta que la masa se despegue de las manos y sea uniforme; no amasar en exceso.","Formar un disco con la masa, envolverlo en film transparente y refrigerar hasta que esté firme.","Precalentar el horno a 170 °C.","Estirar la masa sobre una superficie enharinada hasta un grosor de 4 mm.","Cortar formas con cortapastas y colocarlas en una bandeja con papel de horno, separadas entre sí.","Hornear las galletas a 170 °C hasta que los bordes empiecen a dorarse.","Retirar la bandeja del horno y dejar enfriar las galletas por completo sobre una rejilla.","Batir clara de huevo con los 150 g restantes de azúcar glas y zumo de limón hasta obtener una glasa espesa y brillante.","Decorar las galletas frías con la glasa y dejar secar hasta que esté completamente sólida.","Servir las galletas una vez la glasa esté seca y firme."}', 'Galletas de mantequilla doradas por los bordes, perfectas para decorar en familia.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('postres_036', 'Bizcocho de yogur y limón', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'all', 430, 6, 53, 21, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Yogur natural","amount":125,"unit":"g"},{"name":"Azúcar","amount":200,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Harina","amount":300,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Levadura química","amount":16,"unit":"g"},{"name":"Ralladura de limón","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Engrasar un molde de 22 cm con aceite de girasol y espolvorear harina hasta cubrir toda la superficie.","Rallar ralladura de limón hasta obtener la cantidad necesaria y reservar.","Verter yogur natural en un bol grande junto con azúcar y la ralladura de limón.","Batir la mezcla de yogur, azúcar y ralladura hasta obtener una crema homogénea.","Añadir huevo de uno en uno, batiendo bien tras cada incorporación antes de añadir el siguiente.","Incorporar el aceite de girasol en hilo fino sin dejar de batir hasta que la mezcla emulsione.","Tamizar la harina restante junto con levadura química y sal sobre un bol aparte.","Añadir los ingredientes secos tamizados sobre la mezcla húmeda en dos tandas.","Remover con espátula con movimientos envolventes hasta que no queden grumos, sin batir en exceso.","Verter la masa en el molde preparado y alisar la superficie con la espátula.","Hornear a 180 °C durante 42 min, hasta que al pinchar con un palillo en el centro salga limpio.","Retirar el molde del horno y dejar templar 10 min dentro del molde antes de desmoldar.","Desmoldar el bizcocho sobre una rejilla y dejar enfriar por completo antes de cortar.","Cortar en porciones y servir."}', 'Bizcocho esponjoso de yogur y limón, el clásico sencillo de toda la vida.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_001', 'Vinagreta clásica', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 130, 0, 1, 14, 4, true, true, '{"mostaza"}', '[{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Vinagre de Jerez","amount":20,"unit":"ml"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Añadir vinagre de jerez, mostaza de dijon y sal en un bol pequeño.","Mezclar con unas varillas hasta que la sal se disuelva y la mostaza quede integrada.","Verter aceite de oliva virgen extra en hilo muy fino mientras se bate sin parar hasta emulsionar.","Añadir pimienta negra y rectificar de sal al gusto.","Servir en salsera o verter directamente sobre la ensalada."}', 'Vinagreta clásica de mostaza y vinagre de Jerez, para aliñar ensaladas y verduras.', NULL, '{"Vinagreta"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_002', 'Alioli', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 180, 0, 1, 20, 4, false, true, '{}', '[{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar ajo y retirar el germen interior.","Machacar el ajo pelado en un mortero con sal hasta obtener una pasta fina y homogénea.","Añadir aceite de oliva suave en hilo muy fino, sin parar de remover con el mortero, hasta que emulsione.","Añadir zumo de limón y remover hasta integrar.","Reservar el alioli en frío hasta el momento de servir."}', 'Alioli tradicional de ajo y aceite, sin huevo, para carnes, pescados y marisco a la plancha.', NULL, '{"Alioli"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_003', 'Salsa de tomate casera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 25, 'facil', 'all', 70, 1, 8, 4, 4, true, true, '{}', '[{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos muy finos.","Pelar y picar ajo en trozos muy finos.","Calentar aceite de oliva en un cazo a fuego suave.","Sofreír la cebolla picada en el cazo hasta que esté transparente.","Añadir el ajo picado y sofreír hasta que se dore ligeramente.","Añadir tomate triturado y azúcar. Remover para mezclar bien.","Cocer a fuego suave durante 20 min, removiendo de vez en cuando.","Añadir sal y remover para integrar.","Triturar la salsa con un batidor hasta obtener una textura fina.","Servir la salsa de tomate caliente o reservar en un tarro hermético."}', 'El clásico tomate frito casero: para arroz blanco, huevos o cualquier plato sencillo.', NULL, '{"Tomate frito","Salsa de tomate"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_004', 'Salsa de carne (jugo de asado)', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 30, 'normal', 'all', 90, 2, 4, 6, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Vino tinto","amount":50,"unit":"ml"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Zanahoria","amount":30,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños.","Picar zanahoria en trozos pequeños.","Calentar mantequilla en un cazo a fuego medio hasta que se derrita.","Sofreír la cebolla picada y la zanahoria picada en la mantequilla fundida a fuego medio hasta que estén tiernas.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Añadir caldo de carne y llevar a ebullición a fuego fuerte.","Cocer a fuego suave hasta que el caldo reduzca a la mitad.","Mezclar harina con un poco de agua fría en un bol pequeño hasta obtener una pasta sin grumos.","Colar la salsa a través de un colador fino sobre un cazo limpio.","Añadir la pasta de harina a la salsa colada y remover a fuego medio hasta que esté ligada y sin grumos.","Servir la salsa caliente sobre el plato principal."}', 'Jugo de asado clásico, reducido aparte: para carnes al horno o a la plancha.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_005', 'Salsa verde clásica', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 110, 0, 1, 12, 4, true, true, '{}', '[{"name":"Perejil fresco","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Alcaparras","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Picar perejil fresco muy fino con un cuchillo hasta obtener una textura menuda y uniforme.","Picar ajo muy fino.","Picar alcaparras muy fino.","Mezclar el perejil picado, el ajo picado y las alcaparras picadas en un bol.","Añadir aceite de oliva y zumo de limón, y remover hasta integrar.","Añadir sal y remover.","Dejar reposar la salsa 10 min para que los sabores se asienten.","Servir la salsa verde."}', 'Salsa verde en crudo de perejil y alcaparras, para pescado blanco, azul o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_006', 'Mojo verde canario', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 115, 0, 1, 13, 4, true, true, '{}', '[{"name":"Cilantro fresco","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar ajo.","Lavar cilantro fresco y escurrir bien.","Introducir el cilantro fresco y el ajo en el vaso de la batidora o picadora.","Añadir comino y triturar hasta obtener una pasta fina.","Añadir vinagre y triturar de nuevo hasta integrar.","Incorporar aceite de oliva en hilo fino mientras se tritura hasta emulsionar la salsa.","Añadir sal y triturar 10 segundos más para integrar. Rectificar de sal si fuera necesario.","Servir el mojo verde en un bol o salsera."}', 'Mojo verde canario de cilantro y comino, para carnes blancas, pescado, marisco o verduras.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_007', 'Mojo rojo picón canario', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'normal', 'all', 120, 0, 2, 13, 4, false, true, '{}', '[{"name":"Pimiento choricero (ñora)","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cubrir pimiento choricero (ñora) con agua muy caliente en un bol pequeño.","Dejar en remojo hasta que la ñora esté blanda y rehidratada.","Retirar la ñora del agua y raspar la pulpa interior con una cuchara.","Añadir la pulpa de ñora al vaso de la batidora junto con ajo.","Añadir pimentón picante, comino y vinagre al vaso.","Triturar todo hasta obtener una pasta homogénea y fina.","Añadir aceite de oliva en hilo fino mientras se sigue triturando hasta emulsionar.","Rectificar con sal y triturar 10 segundos más para integrar."}', 'Mojo picón canario, picante, de pimentón y ñora: para carnes y verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_008', 'Chimichurri', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'facil', 'all', 125, 0, 1, 14, 4, true, true, '{}', '[{"name":"Perejil fresco","amount":30,"unit":"g"},{"name":"Orégano seco","amount":3,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":90,"unit":"ml"},{"name":"Vinagre de vino","amount":25,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino sobre la tabla.","Picar perejil fresco muy fino hasta obtener trozos menudos.","Mezclar en un bol el perejil picado, el ajo picado, orégano seco, guindilla y sal.","Añadir vinagre de vino y remover hasta integrar.","Añadir aceite de oliva en hilo fino mientras se remueve para emulsionar.","Reposar el chimichurri tapado a temperatura ambiente hasta que los sabores se integren.","Servir el chimichurri en un cuenco o directamente sobre el plato."}', 'Chimichurri argentino de perejil y orégano, el clásico para carnes a la parrilla.', NULL, '{"Chimichurri"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_009', 'Salsa de mostaza y miel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 95, 0, 8, 7, 4, true, true, '{"mostaza"}', '[{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Mezclar mostaza de dijon y miel en un bol hasta obtener una mezcla homogénea.","Añadir aceite de oliva en hilo fino mientras se bate sin parar hasta emulsionar.","Incorporar zumo de limón y mezclar hasta integrar.","Añadir sal y remover. Rectificar el punto de acidez o dulzor si es necesario."}', 'Salsa agridulce de mostaza y miel, clásica para pollo, pavo o carnes a la plancha.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_010', 'Romesco', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 35, 'normal', 'all', 160, 3, 6, 14, 4, true, true, '{"frutos_secos","gluten"}', '[{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Pimiento choricero (ñora)","amount":10,"unit":"g"},{"name":"Almendra tostada","amount":30,"unit":"g"},{"name":"Avellana tostada","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Sumergir pimiento choricero (ñora) en agua muy caliente hasta que se hidrate.","Colocar tomate maduro y ajo en una bandeja y hornear hasta que estén asados.","Retirar la ñora hidratada del agua y extraer la pulpa raspando con una cuchara.","Añadir el tomate asado, el ajo asado, la pulpa de ñora, almendra tostada, avellana tostada y pan frito al vaso de la batidora.","Incorporar aceite de oliva y vinagre al vaso.","Triturar todo hasta obtener una crema homogénea.","Añadir sal y triturar de nuevo hasta integrar.","Servir el romesco en un cuenco o directamente como acompañamiento."}', 'Romesco catalán de almendra, avellana y ñora: para pescado o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_011', 'Salsa tahini y limón', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 110, 3, 3, 10, 4, true, true, '{"sesamo"}', '[{"name":"Tahini","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":30,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Agua","amount":40,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino hasta obtener una pasta casi homogénea.","Verter tahini en un bol y añadir zumo de limón. Mezclar con unas varillas hasta que espese y se integre.","Añadir agua poco a poco sin dejar de remover hasta que la salsa tenga textura fluida y homogénea.","Añadir el ajo picado y sal. Mezclar bien hasta integrar.","Añadir un poco más de agua si la salsa ha quedado demasiado espesa y remover hasta conseguir la textura deseada.","Servir en un bol o salsera lista para acompañar."}', 'Crema de tahini y limón, para ensaladas, verduras asadas o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_012', 'Salsa de yogur, eneldo y pepino', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 60, 4, 3, 3, 4, true, true, '{"lactosa"}', '[{"name":"Yogur griego","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Ajo","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Rallar pepino con un rallador fino sobre un bol.","Escurrir el pepino rallado apretándolo con las manos hasta eliminar el exceso de agua.","Picar eneldo fresco fino con un cuchillo.","Rallar ajo o picarlo muy fino.","Mezclar yogur griego con el pepino escurrido, el eneldo picado y el ajo en un bol.","Añadir aceite de oliva y sal; remover hasta integrar.","Refrigerar la salsa tapada hasta que esté bien fría.","Servir la salsa fría como acompañamiento."}', 'Salsa fresca de yogur, pepino y eneldo, tipo tzatziki: para carnes blancas, pescado o ensaladas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_013', 'Miso y mantequilla', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 140, 2, 5, 12, 4, true, true, '{"soja","lactosa"}', '[{"name":"Miso blanco","amount":40,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Mirin","amount":15,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"}]'::jsonb, '{"Calentar mantequilla en un cazo pequeño a fuego suave hasta que se funda por completo.","Añadir miso blanco y remover con una espátula hasta que se disuelva sin grumos.","Incorporar mirin y agua y remover a fuego suave hasta que la salsa ligue y quede homogénea.","Retirar el cazo del fuego y reservar la salsa templada hasta el momento de servir."}', 'Glaseado de miso y mantequilla, untuoso y umami, para pescado o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL)
