insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('salsas_014', 'Gremolata', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 15, 1, 2, 0, 4, true, true, '{}', '[{"name":"Perejil fresco","amount":25,"unit":"g"},{"name":"Ralladura de limón","amount":5,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"}]'::jsonb, '{"Picar perejil fresco muy fino con un cuchillo.","Picar ajo muy fino.","Mezclar el perejil picado, el ajo picado y ralladura de limón en un bol hasta integrar.","Reservar la gremolata y espolvorear sobre el plato justo antes de servir."}', 'Gremolata italiana de perejil, limón y ajo: un toque fresco final para carnes, pescado o verduras.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('salsas_015', 'Anchoas, ajo y limón', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 130, 2, 1, 14, 4, false, true, '{"pescado"}', '[{"name":"Filetes de anchoa en aceite","amount":20,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino hasta obtener una pasta.","Picar perejil fresco fino y reservar.","Machacar filetes de anchoa en aceite junto con el ajo picado en un mortero hasta obtener una pasta homogénea.","Añadir aceite de oliva muy despacio sobre la pasta de anchoa y ajo, removiendo sin parar hasta emulsionar.","Añadir zumo de limón y remover hasta integrar por completo.","Añadir el perejil picado y remover. Probar antes de salar, ya que las anchoas aportan sal."}', 'Salsa untuosa de anchoas, ajo y limón, con mucho carácter: para pescado blanco o verduras.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_016', 'Harissa y yogur', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 70, 4, 4, 4, 4, false, true, '{"lactosa"}', '[{"name":"Harissa","amount":20,"unit":"g"},{"name":"Yogur griego","amount":120,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Mezclar yogur griego con harissa en un bol hasta integrar por completo.","Añadir zumo de limón y remover hasta homogeneizar.","Añadir sal y remover.","Refrigerar la salsa hasta el momento de servir.","Servir la salsa fría como acompañamiento."}', 'Yogur picante con harissa, para carnes a la plancha o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_017', 'Pistacho y albahaca', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 190, 4, 3, 18, 4, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Pistacho pelado","amount":40,"unit":"g"},{"name":"Albahaca fresca","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"},{"name":"Queso parmesano","amount":15,"unit":"g"},{"name":"Ajo","amount":3,"unit":"g"}]'::jsonb, '{"Rallar queso parmesano y reservar.","Introducir pistacho pelado, albahaca fresca y ajo en el vaso de la batidora.","Triturar los ingredientes del vaso hasta obtener una pasta homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura, hasta emulsionar la salsa.","Incorporar el queso parmesano rallado y triturar hasta integrarlo por completo.","Rectificar de sal al gusto y remover para homogeneizar la salsa antes de servir."}', 'Pesto de pistacho y albahaca, para ensaladas, pescado blanco o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_019', 'Beurre noisette y salvia', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 135, 0, 0, 15, 4, true, false, '{"lactosa"}', '[{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Salvia fresca","amount":3,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Separar las hojas de salvia fresca de los tallos y reservar.","Calentar mantequilla en un cazo a fuego medio hasta que se funda por completo.","Continuar calentando hasta que la mantequilla tome color avellana y desprenda aroma a frutos secos.","Añadir las hojas de salvia reservadas y freír hasta que crujan, sin apartar la vista.","Retirar el cazo del fuego y añadir zumo de limón para detener la cocción.","Servir templada sobre el plato elegido."}', 'Mantequilla avellanada con salvia crujiente, clásico italiano para pescado blanco o verduras.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('salsas_020', 'Naranja y jengibre', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'facil', 'all', 55, 0, 12, 0, 4, true, true, '{"soja"}', '[{"name":"Zumo de naranja","amount":100,"unit":"ml"},{"name":"Jengibre fresco rallado","amount":10,"unit":"g"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Maicena","amount":5,"unit":"g"}]'::jsonb, '{"Disolver maicena en 1 cucharada de agua fría hasta obtener una mezcla sin grumos. Reservar.","Verter zumo de naranja en un cazo pequeño y añadir jengibre fresco rallado.","Añadir miel y salsa de soja. Remover hasta integrar.","Llevar a ebullición a fuego medio, luego bajar a fuego suave y cocer 5 min hasta que reduzca ligeramente.","Añadir la mezcla de maicena reservada sin dejar de remover hasta que la salsa espese.","Retirar del fuego y servir caliente como acompañamiento."}', 'Glaseado de naranja y jengibre, agridulce, para pollo, pavo o pescado azul.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_021', 'Alioli de azafrán', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'normal', 'all', 180, 0, 1, 20, 4, false, true, '{}', '[{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar un poco de agua hasta que esté muy caliente, sin llegar a hervir.","Infusionar azafrán en hebras en el agua caliente durante 5 min hasta que suelte el color.","Pelar ajo y colocarlo en un mortero.","Añadir sal al mortero y machacar el ajo con la sal hasta obtener una pasta fina.","Incorporar aceite de oliva suave en hilo muy fino sobre la pasta de ajo, removiendo sin parar con el mortero.","Añadir el azafrán infusionado con su agua y zumo de limón a la emulsión mientras se remueve.","Remover hasta que la salsa esté homogénea y con un color dorado uniforme.","Servir el alioli en un bol o directamente como acompañamiento."}', 'Alioli con un toque de azafrán, para pescado blanco, marisco o arroz.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_023', 'Sésamo, soja y miel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 90, 2, 10, 4, 4, true, true, '{"soja","sesamo"}', '[{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Jengibre fresco rallado","amount":5,"unit":"g"}]'::jsonb, '{"Rallar jengibre fresco rallado con un rallador fino hasta obtener 5 g.","Picar ajo muy fino.","Verter salsa de soja en un cazo pequeño a fuego suave.","Añadir miel y aceite de sésamo al cazo y remover hasta integrar.","Añadir el ajo picado y el jengibre rallado al cazo y remover.","Calentar a fuego suave hasta que la salsa espese ligeramente, sin dejar de remover.","Retirar del fuego y añadir semillas de sésamo removiendo para distribuirlas."}', 'Aliño agridulce de sésamo, soja y miel, para ensaladas, pollo o pescado azul.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_024', 'Roquefort ligera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 95, 5, 3, 7, 4, false, true, '{"lactosa"}', '[{"name":"Queso roquefort","amount":40,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Leche","amount":20,"unit":"ml"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Desmenuzar queso roquefort con un tenedor hasta obtener migas finas.","Machacar las migas de roquefort con el tenedor hasta conseguir una pasta lo más homogénea posible.","Añadir yogur griego y leche a la pasta de roquefort.","Mezclar con el tenedor o una varilla hasta obtener una crema fluida y sin grumos.","Añadir pimienta negra y remover para integrar.","Refrigerar la salsa al menos 10 min antes de servir para que asiente el sabor.","Servir la salsa fría como acompañamiento."}', 'Crema ligera de roquefort, para carne roja a la plancha o ensaladas con fruta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_025', 'Mayonesa casera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 190, 1, 0, 21, 4, true, true, '{"huevo"}', '[{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Colocar huevo en el vaso de la batidora sin romper la yema.","Añadir sal y zumo de limón sobre el huevo.","Introducir el brazo de la batidora hasta el fondo del vaso sin moverlo.","Verter aceite de girasol despacio sobre el huevo, cubriéndolo por completo.","Batir a velocidad máxima sin mover el brazo hasta que emulsione la base.","Subir el brazo de la batidora muy despacio hasta que el aceite quede integrado.","Comprobar la textura: debe ser espesa y homogénea; batir 10 segundos más si no ha ligado.","Tapar el vaso y reservar en el frigorífico hasta el momento de servir.","Servir la mayonesa fría en un bol o directamente como acompañamiento."}', 'Mayonesa casera clásica, para pescado, marisco, ensaladas o huevos.', NULL, '{"Mayonesa"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_026', 'Salsa brava', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'facil', 'all', 45, 1, 5, 2, 4, false, true, '{"gluten"}', '[{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Cayena","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Harina","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír el ajo picado hasta que esté dorado sin quemarse.","Añadir harina y remover sin parar hasta que se tueste ligeramente.","Añadir pimentón picante, pimentón dulce y cayena, removiendo para integrar con la harina.","Incorporar tomate triturado y mezclar bien hasta obtener una salsa homogénea.","Cocer a fuego suave removiendo con frecuencia hasta que la salsa espese y los sabores se integren.","Triturar la salsa con una batidora hasta obtener una textura fina y sin grumos.","Servir caliente como acompañamiento."}', 'La clásica salsa brava española, picante, para patatas, huevos o verduras.', NULL, '{"Salsa brava"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_027', 'Pesto genovés', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 180, 4, 2, 18, 4, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Albahaca fresca","amount":30,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano con un rallador fino y reservar.","Pelar ajo y retirar el germen interior si lo tiene.","Introducir albahaca fresca, piñones y el ajo pelado en el vaso de la batidora o mortero.","Triturar los ingredientes del vaso hasta obtener una pasta gruesa.","Añadir aceite de oliva en hilo fino mientras se sigue triturando, hasta emulsionar.","Incorporar el queso parmesano rallado y mezclar a mano con una espátula, sin triturar."}', 'Pesto genovés clásico, para ensaladas, pollo a la plancha o pescado blanco.', NULL, '{"Pesto"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_028', 'Salsa holandesa', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'normal', 'all', 210, 2, 0, 23, 4, true, false, '{"huevo","lactosa"}', '[{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Agua","amount":15,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que esté completamente líquida, sin que llegue a dorarse.","Retirar la mantequilla fundida del fuego y reservar templada.","Llenar un cazo amplio con agua hasta la mitad y llevar a ebullición; bajar a fuego suave para mantener el vapor.","Colocar un bol resistente al calor sobre el cazo sin que toque el agua; verter yema de huevo y agua.","Batir las yemas con el agua al baño maría de forma continua hasta que la mezcla espese y deje trazo al levantar las varillas.","Retirar el bol del baño maría y colocarlo sobre una superficie estable.","Añadir la mantequilla templada en hilo muy fino sin dejar de batir hasta que la salsa emulsione y quede cremosa.","Añadir zumo de limón y sal; remover para integrar.","Servir de inmediato o mantener templada al baño maría tapada, sin superar 60 °C para que no se corte."}', 'Salsa holandesa clásica, para espárragos, verduras al vapor o pescado blanco.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('salsas_029', 'Bechamel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'facil', 'all', 90, 2, 6, 6, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":400,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Medir harina y reservar en un cuenco pequeño.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente líquida.","Añadir la harina reservada de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla esté seca y sin color.","Verter leche poco a poco, en 3 o 4 tandas, removiendo sin parar con la varilla después de cada adición.","Cocer a fuego suave, removiendo con frecuencia, hasta que la bechamel espese y cubra el dorso de una cuchara.","Añadir sal y nuez moscada, remover y retirar del fuego."}', 'Bechamel clásica, para gratinar verduras o napar huevos y croquetas.', NULL, '{"Bechamel"}', NULL, NULL, NULL, '{}', NULL),
  ('salsas_030', 'Salsa de Pedro Ximénez', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 25, 'normal', 'all', 140, 0, 18, 5, 4, false, true, '{"sulfitos","lactosa"}', '[{"name":"Vino Pedro Ximénez","amount":200,"unit":"ml"},{"name":"Chalota","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Picar chalota muy fina.","Calentar mantequilla en un cazo a fuego suave hasta que se funda.","Sofreír la chalota picada en la mantequilla fundida a fuego suave hasta que esté transparente y blanda.","Añadir vino pedro ximénez y subir a fuego medio.","Reducir a fuego medio hasta que la salsa espese y tenga textura de jarabe.","Añadir sal y remover para integrar.","Colar la salsa por un colador fino para obtener una textura más lisa.","Servir la salsa caliente sobre el plato elegido."}', 'Reducción de vino Pedro Ximénez, dulce y untuosa: la clásica salsa de solomillo.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('sopas_cremas_001', 'Crema de calabacín', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 168, 4, 14, 10, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Quesito en porciones","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar patata y cortar en dados de 2 cm aproximadamente.","Lavar calabacín y cortar en rodajas de 1 cm sin pelar.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min a fuego medio.","Añadir el calabacín y la patata a la olla y remover para mezclar con el sofrito.","Cubrir las verduras con agua fría hasta sobrepasarlas 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y el calabacín estén tiernos, unos 15 min.","Retirar del fuego y añadir quesito en porciones al caldo con las verduras.","Triturar el conjunto con una batidora de mano hasta obtener una textura fina y homogénea.","Servir la crema bien caliente en boles, ajustando la textura con un poco de agua si fuera necesario."}', 'Crema suave de calabacín con patata y quesito', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, añade el resto de verduras troceadas con agua o caldo y cocina a temperatura Varoma durante 20 minutos. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando el quesito al final."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla en la olla, añade el resto de verduras troceadas con agua o caldo. Cierra y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura hasta obtener una crema fina y añade el quesito."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_002', 'Sopa de fideos', 'sopas_cremas', 'none', 'pasta', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 182, 6, 28, 4, 2, true, true, '{"gluten"}', '[{"name":"Fideos finos","amount":80,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y rallar zanahoria con un rallador fino. Reservar.","Verter caldo de pollo en una olla y llevar a ebullición a fuego fuerte.","Añadir la zanahoria rallada al caldo cuando rompa a hervir. Remover.","Incorporar fideos finos y cocer a fuego medio hasta que estén tiernos, unos 5 min.","Picar perejil fino mientras cuecen los fideos.","Retirar la olla del fuego. Repartir la sopa en 2 boles.","Añadir aceite de oliva sobre cada bol y espolvorear el perejil picado. Servir."}', 'Sopa caliente de fideos finos en caldo de pollo', '[{"appliance":"thermomix","time":18,"difficulty":"facil","prepSummary":"Pica la zanahoria 3 seg/vel 5. Sofríe con aceite 3 min/120°C/vel 1. Añade el caldo y los fideos, cocina 12 min/100°C/giro inverso/vel cuchara. Sirve con perejil."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la zanahoria en la olla con aceite. Añade el caldo y los fideos, cierra la olla y cocina 3-4 minutos desde que sube la válvula. Despresuriza y sirve con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_003', 'Crema de calabaza', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 178, 3, 22, 8, 2, true, true, '{}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar calabaza y cortar en trozos de unos 3 cm.","Pelar patata y cortar en trozos similares a la calabaza.","Pelar zanahoria y cortar en rodajas de 1 cm.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada a fuego medio hasta que esté transparente, unos 4 min.","Añadir la calabaza, la patata y la zanahoria a la olla y remover para mezclar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","Tapar la olla y cocer a fuego suave hasta que la calabaza y la patata estén tiernas, unos 18 min.","Retirar la olla del fuego y escurrir parte del caldo, reservándolo en un bol aparte.","Añadir nuez moscada a las verduras y triturar con una batidora hasta obtener una textura cremosa y homogénea.","Incorporar el caldo reservado poco a poco hasta alcanzar la consistencia deseada y remover bien.","Servir la crema caliente en cuencos."}', 'Crema de calabaza con zanahoria y un toque de nuez moscada', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa las verduras troceadas con un chorrito de aceite de oliva en el horno precalentado a 200°C durante 30-40 minutos, hasta que estén muy tiernas y ligeramente doradas. Luego, tritura con caldo caliente hasta obtener una crema suave y con un sabor más profundo."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea las verduras en la Thermomix y sofríelas con aceite. Añade agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina las verduras troceadas en la vaporera hasta que estén muy tiernas (aproximadamente 25-30 minutos). Después, tritura con un poco del agua de cocción o caldo caliente y un chorrito de aceite de oliva para una crema ligera y nutritiva."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express con aceite. Añade agua o caldo, cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula. Libera la presión y tritura hasta obtener una crema homogénea en tiempo récord."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_004', 'Gazpacho andaluz', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 152, 3, 12, 10, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y reservar en el vaso de la batidora.","Pelar pepino, cortar en trozos y añadir al vaso.","Retirar las semillas de pimiento verde, cortar en trozos y añadir al vaso.","Pelar ajo y añadir al vaso.","Sumergir pan del día anterior en agua fría durante 2 min hasta que se ablande, escurrir y añadir al vaso.","Triturar todos los ingredientes del vaso a potencia máxima durante 2 min hasta obtener una crema fina y homogénea.","Añadir aceite de oliva y vinagre de jerez al vaso y triturar 30 segundos más hasta que estén integrados.","Pasar la crema por un colador fino presionando con una cuchara hasta que escurra todo el líquido; descartar los sólidos.","Refrigerar el gazpacho en la nevera hasta que esté muy frío, mínimo 30 min antes de servir.","Servir el gazpacho bien frío en cuencos o vasos."}', 'Sopa fría de tomate, pepino y pimiento al estilo andaluz', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el gazpacho. Introduce todos los ingredientes troceados y tritura a velocidad progresiva 1-10 durante 2-3 minutos hasta obtener una textura muy fina. Sirve bien frío."}]'::jsonb, '{"Gazpacho"}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_005', 'Salmorejo cordobés', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 10, 'facil', 'verano', 228, 5, 18, 16, 2, true, true, '{"gluten","huevo","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Jamón serrano","amount":20,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y reservar en el vaso de la batidora.","Cortar pan del día anterior en trozos y añadir al vaso junto con los tomates.","Añadir ajo, vinagre de jerez y triturar a máxima potencia hasta que la mezcla esté completamente lisa.","Añadir aceite de oliva en hilo fino y continuo mientras la batidora sigue funcionando a velocidad media, hasta que emulsione.","Refrigerar el salmorejo en la nevera hasta que esté bien frío.","Picar jamón serrano en trozos pequeños y reservar.","Picar huevo cocido en trozos pequeños y reservar.","Servir el salmorejo en cuencos y repartir por encima el jamón picado y el huevo cocido picado."}', 'Crema fría espesa de tomate y pan con jamón y huevo', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pan, ajo, vinagre y sal en el vaso y tritura a velocidad progresiva hasta obtener una crema muy fina. Añade el aceite en hilo mientras sigues batiendo a velocidad media para mezclar bien perfectamente."}]'::jsonb, '{"Salmorejo"}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_006', 'Crema de zanahoria', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 158, 3, 18, 8, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Jengibre fresco","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar patata y cortar en dados de 2 cm.","Pelar jengibre fresco y picar fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 3 min.","Añadir la zanahoria, la patata y el jengibre picado; remover 1 min para integrar.","Cubrir con agua fría hasta sobrepasar las verduras unos 2 cm y llevar a ebullición.","Tapar y cocer a fuego suave hasta que la zanahoria y la patata estén tiernas.","Retirar del fuego y triturar con un batidor de mano hasta obtener una crema lisa y homogénea.","Servir la crema en boles calientes."}', 'Crema suave de zanahoria con un toque de jengibre', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Asa las zanahorias, patatas y cebolla con el aceite y jengibre a 200°C durante 25-30 minutos para intensificar su sabor. Luego, hierve brevemente con agua o caldo y tritura hasta obtener una crema suave."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre con el aceite, añade las zanahorias y patatas, cubre con agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina al vapor las zanahorias, patatas, cebolla y jengibre hasta que estén muy tiernas, unos 25-30 minutos. Luego, tritura los vegetales con el aceite de oliva y un poco de agua o caldo hasta conseguir la textura deseada."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre en la olla, añade las zanahorias y patatas, cubre con agua o caldo. Cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema homogénea."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_007', 'Sopa castellana', 'sopas_cremas', 'huevo', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 248, 12, 22, 12, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Pelar ajo y laminar finamente.","Cortar jamón serrano en tiras o tacos pequeños.","Cortar pan del día anterior en rebanadas de 1 cm.","Calentar aceite de oliva en una cazuela de barro o olla a fuego medio.","Sofreír el ajo laminado hasta que se dore ligeramente; retirar si se dora demasiado rápido.","Añadir el jamón serrano y saltear 1 min hasta que suelte su grasa.","Retirar la cazuela del fuego, añadir pimentón y remover rápido para que no se queme.","Incorporar las rebanadas de pan y remover para que se impregnen bien del sofrito.","Verter caldo de carne caliente, llevar a ebullición y reducir a fuego suave.","Cocer a fuego suave, tapado, hasta que el pan se deshaga y la sopa espese.","Precalentar el horno a 200 °C con calor arriba y abajo.","Cascar huevo uno a uno sobre la sopa directamente en la cazuela apta para horno.","Hornear la cazuela a 200 °C hasta que la clara cuaje pero la yema quede ligeramente líquida.","Retirar del horno con cuidado y servir la sopa castellana directamente en la cazuela."}', 'Sopa de ajo con pan, jamón y huevo escalfado', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"En una cazuela apta para horno, sofríe el ajo y el jamón. Añade el pimentón y el caldo, luego hornea a 180°C durante 20 minutos para que los sabores se integren, añadiendo los huevos al final para que se escalfen con el calor residual."},{"appliance":"olla_express","time":22,"difficulty":"facil","prepSummary":"Sofríe el ajo y el jamón en la olla abierta. Añade el pimentón, el pan y el caldo, cierra la olla y cocina 5 minutos desde que suba la válvula. Despresuriza, abre y escalfa los huevos con el calor residual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_008', 'Vichyssoise', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'verano', 192, 4, 22, 10, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":250,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y cortar puerro en rodajas finas, desechando la parte verde más oscura.","Pelar y cortar cebolla en trozos medianos.","Pelar y cortar patata en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla en la olla hasta que estén blandos y transparentes, sin que se doren.","Añadir la patata a la olla y cubrir con agua fría hasta superar los ingredientes unos 2 cm.","Llevar a ebullición a fuego fuerte; cuando rompa a hervir, reducir a fuego medio y cocer hasta que la patata esté tierna.","Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema completamente fina.","Añadir nata a la crema y remover hasta que quede integrada de forma homogénea.","Dejar enfriar la crema a temperatura ambiente y después refrigerar en la nevera hasta que esté bien fría.","Servir la vichyssoise bien fría en boles o tazas."}', 'Crema fría de puerro y patata con nata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para la Vichyssoise, ya que sofríe, cocina y tritura en un solo recipiente. Sofríe las verduras 5 min a 120°C, luego añade patatas y agua, cocina 15 min a 100°C y tritura progresivamente hasta obtener una crema fina con la nata."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"La olla express reduce drásticamente el tiempo de cocción de las verduras. Sofríe los puerros y cebolla en la olla, añade las patatas y agua, cierra y cocina 7-10 minutos a presión, luego tritura con la nata hasta lograr una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_009', 'Crema de puerros', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 172, 4, 18, 8, 2, true, true, '{}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en dados de 2 cm.","Retirar la raíz y las hojas exteriores duras de puerro.","Cortar la parte blanca y verde claro del puerro en rodajas de 1 cm.","Pelar cebolla y picar en trozos medianos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla en el aceite caliente a fuego medio, removiendo de vez en cuando, hasta que estén blandos y transparentes.","Añadir los dados de patata a la olla y remover para integrar con el sofrito.","Cubrir las verduras con 400 ml de agua fría y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar la olla y cocer hasta que la patata esté tierna.","Retirar la olla del fuego y triturar el contenido con un túrmix hasta obtener una textura cremosa y homogénea.","Servir la crema caliente en boles."}', 'Crema caliente de puerros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas con aceite 5 min/120°C/vel 1. Añade agua o caldo y cocina 15 min/100°C/vel 1. Tritura progresivamente 1 min/vel 5-10 hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla con aceite. Añade agua o caldo hasta cubrir, cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_010', 'Sopa de cebolla', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'invierno', 218, 8, 22, 10, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Pan","amount":60,"unit":"g"},{"name":"Queso gruyère","amount":40,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Laminar cebolla en juliana fina.","Calentar mantequilla en una olla a fuego medio hasta que se funda.","Añadir la cebolla laminada a la olla y sofreír a fuego suave, removiendo con frecuencia, hasta que esté dorada y muy tierna.","Incorporar vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne, llevar a ebullición y cocer a fuego suave hasta que la sopa esté sabrosa y bien integrada.","Cortar pan en rebanadas y tostar en el horno a 180 °C hasta que estén doradas y crujientes.","Rallar queso gruyère finamente.","Distribuir la sopa en cazuelas individuales aptas para horno y colocar las rebanadas de pan tostado encima.","Cubrir la superficie de cada cazuela con el queso gruyère rallado y gratinar en el horno a 200 °C hasta que el queso esté fundido y dorado.","Servir las cazuelas inmediatamente, con cuidado de no quemarse."}', 'Sopa de cebolla caramelizada gratinada con queso', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Comienza caramelizando las cebollas lentamente en una olla a fuego medio-bajo. Luego, añade el vino y el caldo, y cocina a fuego suave. Sirve la sopa en cuencos individuales aptos para horno, cubre con el pan y el queso, y gratina a 200°C durante 5-10 minutos hasta que el queso esté fundido y dorado."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las cebollas y sofríelas con la mantequilla a 120°C, velocidad cuchara, durante 20 minutos. Añade el vino y el caldo, y cocina a 100°C, velocidad cuchara, durante 15 minutos. Sirve la sopa en cuencos aptos para horno, cubre con pan y queso, y gratina en el horno precalentado a 200°C durante 5-10 minutos hasta que el queso se funda y dore."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe las cebollas con la mantequilla en la olla express abierta a fuego medio hasta que estén bien caramelizadas (aprox. 15-20 min). Añade el vino y el caldo, cierra la olla y cocina a presión durante 10-12 minutos. Sirve la sopa en cuencos individuales, cubre con pan y queso, y gratina en el horno a 200°C durante 5-10 minutos hasta que el queso se funda y dore."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_011', 'Crema de verduras', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 148, 4, 16, 8, 2, true, true, '{}', '[{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Limpiar puerro y cortar en rodajas finas.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar patata y cortar en trozos medianos.","Cortar calabacín en trozos medianos, sin pelar.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el puerro en rodajas hasta que estén blandos y translúcidos, unos 5 min.","Añadir la zanahoria, la patata y el calabacín a la olla y remover para integrar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y la zanahoria estén tiernas, unos 15 min.","Retirar la olla del fuego y triturar todas las verduras con el caldo hasta obtener una textura fina y homogénea.","Servir la crema caliente en boles."}', 'Crema suave de verduras variadas con patata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras, sofríelas con el aceite, añade agua o caldo y cocina a 100°C durante 15-20 minutos. Luego, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas al vapor hasta que estén muy tiernas (aprox. 15-20 min). Luego, tritura con un poco de agua o caldo y el aceite de oliva hasta obtener una crema suave."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el puerro en la olla. Añade el resto de verduras, agua o caldo y cocina a presión alta durante 5-7 minutos. Libera la presión y tritura con el aceite de oliva."},{"appliance":"microondas","time":20,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-15 minutos a máxima potencia hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido de cocción."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_012', 'Crema de champiñones', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 186, 6, 12, 12, 2, true, true, '{"lactosa"}', '[{"name":"Champiñones","amount":300,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Limpiar champiñones y cortar en cuartos.","Pelar patata y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada en la olla hasta que esté transparente, unos 3 min.","Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","Incorporar los champiñones cortados y saltear a fuego fuerte hasta que suelten el agua y se doren, unos 3 min.","Añadir los dados de patata y cubrir con 400 ml de agua. Llevar a ebullición.","Tapar la olla y cocer a fuego suave hasta que la patata esté tierna, unos 15 min.","Calentar nata en un cazo pequeño a fuego suave hasta que esté caliente, sin que llegue a hervir.","Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema lisa.","Añadir la nata caliente a la crema y mezclar hasta integrar. Salpimentar al gusto.","Servir la crema en boles calientes."}', 'Crema de champiñones con nata y un toque de ajo', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina 15-20 min a 100°C. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando la nata al final."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina a presión alta durante 5-7 minutos. Libera la presión, añade la nata y tritura con una batidora de mano."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_013', 'Puré de patatas gratinado', 'sopas_cremas', 'none', 'patatas', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 228, 4, 30, 10, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Llevar a ebullición una olla con agua abundante a fuego fuerte.","Cocer los trozos de patata en el agua hirviendo a fuego medio hasta que estén tiernos, unos 20 min.","Calentar leche en un cazo a fuego suave hasta que esté caliente, sin que llegue a hervir.","Escurrir las patatas cocidas y aplastar con un pasapurés hasta obtener una textura lisa.","Añadir mantequilla y la leche caliente al puré y remover a fuego suave hasta integrar.","Añadir nuez moscada y remover hasta que el puré quede homogéneo.","Extender el puré en una fuente apta para horno y gratinar a 200 °C hasta que la superficie esté dorada, unos 5 min.","Retirar del horno y servir de inmediato en plato hondo o cuenco."}', 'Puré de patatas cremoso con mantequilla y nuez moscada', '[{"appliance":"horno","time":55,"difficulty":"facil","prepSummary":"Asa las patatas enteras a 200°C durante unos 45-55 minutos hasta que estén muy tiernas. Luego pélalas, machácalas y mezcla con la leche, mantequilla y nuez moscada para un puré más seco y con sabor concentrado."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas en el cestillo o varoma durante 20-25 minutos a temperatura Varoma, velocidad 1. Luego, tritúralas con la leche, mantequilla y nuez moscada a velocidad 4-5 hasta obtener la textura deseada."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Corta las patatas en trozos y cuécelas al vapor durante 25-30 minutos hasta que estén muy tiernas. Machácalas bien y luego incorpora la leche caliente, la mantequilla y la nuez moscada para un puré ligero y sabroso."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas con un poco de agua en la olla express durante 6-8 minutos desde que sube la válvula. Despresuriza, escurre y machaca, añadiendo luego la leche, mantequilla y nuez moscada para un puré muy rápido y cremoso."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Pincha las patatas enteras o trocéalas y cocínalas en el microondas a máxima potencia durante 10-12 minutos, volteando a mitad, hasta que estén muy tiernas. Luego machaca y mezcla con el resto de ingredientes para un puré exprés."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_014', 'Crema de espárragos', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 142, 5, 12, 8, 2, true, true, '{}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados de 1 cm aproximadamente.","Cortar cebolla en trozos pequeños y laminar ajo.","Retirar la parte leñosa de espárragos trigueros y cortar en trozos de 3 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo en el aceite caliente hasta que estén translúcidos, unos 4 min.","Añadir los espárragos y la patata a la olla y remover para integrar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas en 1 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que la patata esté tierna, unos 15 min.","Retirar del fuego y triturar el conjunto con un túrmix hasta obtener una crema fina.","Servir la crema caliente en boles."}', 'Crema de espárragos trigueros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los espárragos y patata troceados con agua o caldo. Cocina 12-15 minutos a 100°C, velocidad cuchara, luego tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora los espárragos, patata y líquido. Cierra y cocina a presión alta 5-7 minutos. Despresuriza y tritura con una batidora de mano hasta lograr una crema suave."},{"appliance":"vaporera","time":28,"difficulty":"facil","prepSummary":"Cocina los espárragos, patata, cebolla y ajo al vapor hasta que estén muy tiernos (aprox. 20-25 minutos). Transfiere a una batidora, añade el aceite de oliva y un poco de agua o caldo de la cocción, y tritura hasta obtener una crema suave."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-12 minutos a máxima potencia, hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido hasta obtener una crema fina."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_015', 'Ajoblanco', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 268, 8, 16, 20, 2, false, true, '{"gluten","frutos_secos","sulfitos"}', '[{"name":"Almendras crudas","amount":100,"unit":"g"},{"name":"Pan del día anterior","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Cubrir pan del día anterior con agua fría y dejar reposar hasta que esté completamente empapado.","Escurrir el pan remojado y reservar el agua de remojo.","Pelar ajo y retirar el germen central para suavizar el sabor.","Lavar uvas, pelarlas y reservarlas en frío hasta el momento de servir.","Introducir almendras crudas, el pan escurrido y el ajo en el vaso de la batidora.","Triturar a máxima potencia durante 2 min hasta obtener una pasta muy fina y homogénea.","Añadir aceite de oliva en hilo fino mientras sigue triturando, hasta que emulsione.","Añadir vinagre de jerez y triturar 30 segundos más hasta integrar.","Agregar agua fría del remojo poco a poco y triturar hasta lograr la consistencia deseada.","Refrigerar el ajoblanco en la nevera hasta que esté muy frío, mínimo 30 min.","Servir el ajoblanco en boles fríos y repartir las uvas peladas por encima."}', 'Sopa fría de almendras y ajo con uvas, típica de Málaga', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el ajoblanco. Tritura todos los ingredientes (almendras, pan, ajo, agua, aceite, vinagre y sal) a velocidad progresiva hasta lograr una crema muy fina y emulsionada. Sirve bien frío con las uvas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_016', 'Sopa de tomate', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 162, 3, 16, 10, 2, true, true, '{}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Cortar tomate maduro en trozos irregulares.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min más hasta que desprenda aroma.","Añadir el tomate troceado y orégano y remover para mezclar todo.","Tapar la olla y cocer a fuego suave hasta que el tomate esté muy tierno, unos 15 min.","Retirar del fuego y triturar la mezcla con una batidora hasta obtener una crema fina y homogénea.","Servir la sopa caliente en boles."}', 'Sopa caliente de tomate natural con orégano', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en la airfryer a 190°C durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Luego, tritúralos con un poco de agua o caldo y el orégano hasta obtener una sopa cremosa."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en el horno a 180°C durante 30-40 minutos hasta que estén bien tiernos y con un ligero tostado. Después, tritúralos con el aceite de oliva, orégano y un poco de agua o caldo hasta conseguir una sopa suave."},{"appliance":"thermomix","time":22,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo con el aceite. Añade los tomates troceados y el orégano, cocina a temperatura Varoma durante 15 minutos y finalmente tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla express. Incorpora los tomates y el orégano, cierra la olla y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura todo hasta lograr una sopa cremosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_017', 'Crema de brócoli', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'invierno', 152, 6, 12, 8, 2, true, true, '{}', '[{"name":"Brócoli","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños. Pelar ajo y picar fino. Pelar patata y cortar en trozos de unos 2 cm.","Separar brócoli en ramilletes medianos, desechando el tronco más grueso.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos y translúcidos, unos 3 min.","Añadir los ramilletes de brócoli y la patata cortada. Remover para mezclar con el sofrito.","Cubrir las verduras con agua hasta que queden justas sumergidas y llevar a ebullición a fuego fuerte.","Reducir a fuego medio y cocer hasta que la patata y el brócoli estén tiernos, unos 12 min.","Retirar del fuego y triturar con un batidor de mano hasta obtener una textura fina y cremosa.","Servir la crema caliente en boles."}', 'Crema de brócoli con patata, suave y nutritiva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, añade el resto de ingredientes y agua, cocina 18 min a 100°C, velocidad cuchara. Luego tritura 1 min a velocidad progresiva 5-10 hasta obtener una crema fina."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cocina el brócoli, la patata, cebolla y ajo al vapor durante 15-18 minutos hasta que estén tiernos. Luego, tritura los vegetales con el aceite de oliva y un poco del agua de cocción hasta lograr una crema suave."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Añade el brócoli, la patata y un poco de agua, cierra y cocina 5 minutos desde que sube la válvula. Libera la presión y tritura directamente en la olla hasta obtener una crema homogénea."},{"appliance":"microondas","time":18,"difficulty":"facil","prepSummary":"Coloca todos los vegetales troceados con un chorrito de agua en un recipiente apto para microondas. Cocina a máxima potencia durante 12-15 minutos hasta que estén muy tiernos. Luego, tritura con el aceite de oliva hasta obtener una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_018', 'Sopa de ajo', 'sopas_cremas', 'huevo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 212, 10, 18, 10, 2, false, false, '{"gluten","huevo"}', '[{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan del día anterior","amount":60,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Laminar ajo en láminas finas y uniformes.","Cortar pan del día anterior en rebanadas de aproximadamente 1 cm de grosor.","Calentar aceite de oliva en una olla a fuego suave hasta que esté caliente.","Añadir el ajo laminado y sofreír a fuego suave hasta que se dore ligeramente, sin que se queme.","Retirar la olla del fuego y añadir pimentón removiendo rápidamente para que no se queme.","Añadir las rebanadas de pan y remover para que se impregnen bien del aceite con pimentón.","Verter caldo de carne en la olla, llevar a ebullición a fuego fuerte y después bajar a fuego medio.","Cocer a fuego medio durante 10 min hasta que el pan se deshaga y la sopa espese.","Cascar huevo sobre la sopa con cuidado, uno a uno, sin romper la yema.","Tapar la olla y cocer a fuego suave durante 3 min hasta que la clara cuaje pero la yema quede líquida.","Servir la sopa en cuencos hondos calientes, con un huevo por ración."}', 'Sopa de ajo tradicional con pan, pimentón y huevo', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_019', 'Sopa juliana', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 128, 3, 14, 6, 2, true, true, '{}', '[{"name":"Puerro","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Nabo","amount":60,"unit":"g"},{"name":"Repollo","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Limpiar y laminar puerro en tiras finas de unos 3 mm.","Pelar y cortar zanahoria en tiras finas de juliana de unos 3 mm.","Despuntar y cortar judías verdes en tiras finas del mismo tamaño.","Pelar y cortar nabo en tiras finas de juliana.","Retirar las hojas exteriores y cortar repollo en tiras finas de juliana.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír el puerro, la zanahoria, las judías verdes, el nabo y el repollo en la olla durante 3 min, removiendo con frecuencia.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego suave, tapado, hasta que las verduras estén tiernas.","Servir la sopa bien caliente en boles hondos."}', 'Sopa ligera de verduras cortadas en tiras finas', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con el aceite y luego añade el caldo. Cocina a 100°C durante 20 minutos a velocidad cuchara con giro inverso, logrando una sopa perfectamente cocida y homogénea."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla con el aceite, añade el caldo y cierra la tapa. Cocina a presión durante 6 minutos desde que sube la válvula, obteniendo una sopa rápida y con verduras perfectamente tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_020', 'Crema de lentejas', 'sopas_cremas', 'legumbre', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 272, 14, 34, 8, 2, true, true, '{}', '[{"name":"Lentejas rojas","amount":150,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar zanahoria y cortar en rodajas de unos 5 mm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir la zanahoria cortada y sofreír 3 min hasta que empiece a ablandarse.","Añadir tomate triturado y comino y remover 2 min a fuego medio.","Añadir lentejas rojas y cubrir con 600 ml de agua fría.","Llevar a ebullición a fuego fuerte y bajar a fuego suave cuando rompa a hervir.","Tapar y cocer a fuego suave hasta que las lentejas estén completamente tiernas, unos 18 min.","Retirar del fuego y triturar con un túrmix hasta obtener una crema lisa y homogénea.","Servir la crema caliente en boles."}', 'Crema espesa de lentejas rojas con zanahoria y comino', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade las lentejas, tomate triturado, comino y agua. Cocina a temperatura Varoma/100°C y velocidad cuchara durante 25-30 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en la olla con aceite. Incorpora las lentejas, tomate triturado, comino y agua. Cierra la olla y cocina a presión durante 8-10 minutos desde que sube la válvula. Despresuriza, y tritura directamente en la olla con una batidora de mano hasta conseguir u"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_021', 'Gazpacho de bote mejorado con toppings', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 185, 7, 15, 11, 2, true, true, '{"huevo","gluten","sulfitos"}', '[{"name":"Gazpacho de bote","amount":500,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Pepino","amount":50,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer huevo en agua hirviendo durante 10 min.","Cortar pan en dados pequeños de 1 cm.","Picar pepino en dados pequeños para el topping.","Picar jamón serrano en taquitos finos.","Enfriar el huevo cocido en agua fría hasta que esté templado.","Pelar el huevo y picarlo en dados pequeños.","Calentar sartén a fuego fuerte con aceite de oliva virgen extra.","Freír los dados de pan hasta que estén dorados y crujientes.","Escurrir los picatostes sobre papel absorbente y reservar.","Verter gazpacho de bote en una jarra o bol grande y remover.","Servir el gazpacho bien frío en boles individuales.","Repartir por encima el huevo picado, el jamón serrano, los picatostes y el pepino."}', 'Gazpacho de bote con un remate casero de huevo duro, jamón y picatostes que lo convierte en plato completo.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_022', 'Crema de boletus con perejil frito', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 212, 5, 16, 14, 2, true, true, '{"lactosa"}', '[{"name":"Boletus","amount":300,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":15,"unit":"g"}]'::jsonb, '{"Limpiar boletus con un paño húmedo y laminar, reservando unas pocas láminas para el perejil frito.","Pelar y picar cebolla finamente.","Limpiar y picar puerro finamente.","Pelar patata y cortar en dados pequeños.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Sofreír el puerro picado y la cebolla picada a fuego medio hasta que estén blandos y transparentes.","Añadir los boletus laminados y sofreír hasta que suelten el agua y se doren ligeramente.","Incorporar los dados de patata y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté tierna.","Separar las hojas de perejil fresco reservadas para el perejil frito.","Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar por completo.","Calentar aceite abundante en sartén a fuego fuerte hasta que humee.","Freír las hojas de perejil en el aceite caliente unos segundos hasta que estén crujientes.","Escurrir el perejil frito sobre papel absorbente y reservar.","Servir la crema caliente en boles y coronar con el perejil frito crujiente."}', 'Crema aterciopelada de boletus con un crujiente de perejil frito que corona cada bol.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('sopas_cremas_023', 'Bisque de marisco', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 75, 'elaborada', 'all', 265, 15, 12, 17, 2, true, true, '{"marisco","lactosa","sulfitos"}', '[{"name":"Cáscaras y cabezas de langostinos","amount":300,"unit":"g"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Brandy","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Arroz","amount":30,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Agua","amount":800,"unit":"ml"}]'::jsonb, '{"Picar cebolla, zanahoria, puerro y ajo en trozos pequeños.","Calentar aceite de oliva en una olla a fuego fuerte.","Añadir cáscaras y cabezas de langostinos y saltear 5 min, aplastándolas con una cuchara hasta que estén bien tostadas.","Verter brandy sobre las cáscaras y flambear con cuidado hasta que se apague la llama.","Añadir la verdura picada a la olla y sofreír a fuego medio hasta que esté blanda.","Incorporar tomate triturado y pimentón dulce y remover hasta integrar.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir arroz y agua, llevar a ebullición y cocer a fuego medio hasta que el arroz esté tierno.","Triturar todo el conjunto, incluidas las cáscaras, con un túrmix hasta obtener una crema muy fina.","Colar la crema apretando con una cuchara para extraer todo el líquido y sabor.","Devolver la crema colada a la olla, añadir nata para cocinar y calentar a fuego suave sin que llegue a hervir.","Calentar un chorrito del aceite de oliva restante en sartén a fuego fuerte.","Saltear langostinos pelados 2 min por cada lado hasta que estén dorados y rosas.","Servir la bisque en boles y repartir los langostinos salteados por encima."}', 'Bisque cremosa de marisco, con todo el sabor extraído de las cáscaras y langostinos salteados de guarnición.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_024', 'Crema de calabaza y jengibre', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 165, 3, 20, 8, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jengibre fresco","amount":15,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar calabaza y cortar en dados de unos 3 cm.","Pelar patata y cortar en dados de unos 3 cm.","Picar cebolla finamente.","Rallar jengibre fresco.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","Añadir los dados de calabaza y patata a la olla y remover para integrar con el sofrito.","Verter caldo de verduras hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la calabaza y la patata estén tiernas.","Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar completamente.","Servir la crema bien caliente en boles."}', 'Crema de calabaza con un punto picante de jengibre que la despierta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_025', 'Gazpacho de sandía', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 112, 2, 17, 5, 2, true, true, '{"sulfitos"}', '[{"name":"Sandía","amount":500,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar sandía en trozos, retirando las pepitas y la corteza.","Pelar pepino y cortar en trozos.","Cortar tomate maduro en trozos.","Cortar pimiento verde en trozos.","Pelar ajo y retirar el germen central para que no repita.","Triturar la sandía, el tomate maduro, el pepino, el pimiento verde y el ajo hasta obtener una crema fina.","Añadir vinagre de jerez, aceite de oliva virgen extra y sal y triturar de nuevo hasta integrar.","Enfriar el gazpacho en la nevera hasta que esté bien frío.","Servir bien frío con un chorrito de aceite de oliva virgen extra por encima."}', 'Gazpacho rosado y refrescante que sorprende con el dulzor de la sandía.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_026', 'Salmorejo con jamón y huevo duro', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 232, 9, 22, 12, 2, true, true, '{"gluten","huevo","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pan del día anterior","amount":100,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar tomate maduro y cortar en trozos grandes, retirando el pedúnculo.","Trocear pan del día anterior y sumergir en agua fría hasta que se ablande.","Cocer huevo en agua hirviendo hasta que esté duro.","Escurrir el pan y reservar.","Enfriar el huevo cocido en agua fría hasta que esté templado, pelar y reservar.","Triturar el tomate troceado, el pan escurrido y ajo hasta obtener una crema fina.","Añadir aceite de oliva virgen extra en hilo fino mientras se sigue triturando hasta que la crema sea homogénea.","Añadir vinagre de jerez y sal, triturar de nuevo hasta integrar.","Enfriar el salmorejo en la nevera hasta que esté bien frío.","Cortar jamón serrano en taquitos pequeños.","Cortar el huevo cocido en taquitos pequeños.","Servir el salmorejo bien frío con el jamón y el huevo repartidos por encima."}', 'Salmorejo cordobés espeso, rematado con jamón y huevo duro picados.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_027', 'Crema de puerros y patata con beicon crujiente', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'facil', 'invierno', 232, 6, 20, 14, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Beicon en lonchas","amount":60,"unit":"g"}]'::jsonb, '{"Limpiar puerro retirando la capa exterior y las raíces, y cortar en rodajas finas usando la parte blanca y la verde clara.","Pelar patata y cebolla, y cortar ambas en dados medianos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro en la olla hasta que estén blandos y ligeramente dorados.","Añadir la patata y caldo de pollo a la olla y llevar a ebullición a fuego fuerte.","Cocer la olla tapada a fuego medio hasta que la patata esté tierna.","Calentar sartén a fuego fuerte sin aceite y disponer beicon en lonchas en una sola capa.","Dorar el beicon hasta que quede crujiente, dándole la vuelta a mitad.","Retirar el beicon de la sartén y escurrir sobre papel absorbente.","Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","Añadir nata para cocinar a la crema y triturar de nuevo hasta integrar.","Cortar el beicon crujiente en trozos pequeños.","Servir la crema caliente en boles y repartir el beicon troceado por encima."}', 'Crema suave de puerro y patata con el contraste crujiente del beicon dorado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_028', 'Crema de guisantes con menta', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'all', 175, 7, 16, 9, 2, true, true, '{"lactosa"}', '[{"name":"Guisantes congelados","amount":350,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"}]'::jsonb, '{"Picar cebolla fino.","Pelar patata y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir la patata en dados y caldo de verduras.","Llevar a ebullición y cocer hasta que la patata esté tierna.","Añadir guisantes congelados y cocer hasta que estén tiernos y mantengan el color verde vivo.","Retirar la olla del fuego.","Reservar unas hojas de menta fresca para el emplatado y añadir el resto a la olla.","Triturar el contenido de la olla con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Picar fino las hojas de menta reservadas.","Servir la crema caliente o templada espolvoreada con la menta picada."}', 'Crema de guisantes de un verde vivo, refrescada con menta fresca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_029', 'Velouté de champiñones', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'all', 215, 5, 14, 15, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Champiñones","amount":350,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina de trigo","amount":25,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo para retirar la suciedad.","Laminar los champiñones en láminas finas y uniformes.","Picar cebolla en trozos pequeños.","Fundir mantequilla en una olla a fuego medio hasta que esté derretida.","Sofreír la cebolla picada en la olla hasta que esté blanda y transparente.","Añadir los champiñones laminados y zumo de limón a la olla.","Saltear a fuego fuerte hasta que los champiñones suelten el agua y se doren.","Espolvorear harina de trigo sobre los champiñones y remover sin parar.","Verter caldo de pollo poco a poco sin dejar de remover hasta integrarlo.","Llevar a ebullición y cocer a fuego medio hasta que la sopa espese ligeramente.","Triturar la sopa con una batidora hasta obtener una crema fina y sedosa.","Añadir nata para cocinar y calentar a fuego suave sin que llegue a hervir.","Servir la velouté caliente en cuencos."}', 'Velouté sedoso de champiñones, con el aroma tostado del sofrito envolviendo cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_030', 'Sopa de cebolla gratinada', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'invierno', 310, 12, 26, 17, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Caldo de carne","amount":600,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Pan tostado","amount":60,"unit":"g"},{"name":"Queso gruyère rallado","amount":80,"unit":"g"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y laminar en juliana fina.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla y azúcar a la olla. Remover para integrar.","Sofreír la cebolla a fuego suave, removiendo de vez en cuando, hasta que esté muy dorada y caramelizada.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne y tomillo. Llevar a ebullición.","Cocer a fuego medio hasta que la sopa esté sabrosa y ligeramente reducida.","Precalentar el horno en modo grill a 220 °C.","Repartir la sopa en 2 cazuelitas individuales aptas para horno.","Colocar pan tostado sobre cada cazuelita, cubriendo la superficie.","Cubrir el pan tostado con queso gruyère rallado de forma generosa.","Gratinar en el horno con el grill hasta que el queso esté fundido y dorado.","Servir las cazuelitas muy calientes, con cuidado al manipularlas."}', 'Sopa de cebolla lentamente caramelizada, coronada de pan y queso fundido gratinado.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_031', 'Crema de coliflor asada', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 160, 5, 14, 9, 2, true, true, '{"lactosa"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Separar coliflor en ramilletes y cortar cebolla en trozos grandes.","Disponer los ramilletes de coliflor y la cebolla en una bandeja de horno junto con ajo entero con piel.","Regar con la mitad de aceite de oliva y salpimentar.","Hornear en el centro del horno hasta que la coliflor esté dorada en los bordes.","Retirar la bandeja del horno y dejar templar hasta que el ajo esté tibio.","Pelar el ajo asado presionando la base de cada diente para extraer la pulpa.","Poner la coliflor asada, la cebolla y el ajo pelado en una olla. Verter caldo de verduras.","Llevar a ebullición a fuego fuerte y, cuando rompa a hervir, cocer a fuego medio.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Ajustar de sal y servir con un hilo de aceite de oliva y pimentón dulce por encima."}', 'Crema de coliflor con el fondo tostado que deja el horno, más profunda que la versión hervida.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_032', 'Crema de espárragos con langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 200, 12, 12, 11, 2, true, true, '{"marisco","lactosa"}', '[{"name":"Espárragos verdes","amount":350,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"}]'::jsonb, '{"Lavar espárragos verdes, retirar la parte leñosa del tallo y reservar las puntas para decorar.","Cortar los espárragos (sin las puntas reservadas) en trozos de unos 3 cm.","Limpiar puerro y picar fino.","Pelar patata y cortar en dados pequeños.","Calentar la mitad de aceite de oliva en una olla a fuego medio.","Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","Añadir los trozos de espárragos y la patata en dados, y sofreír removiendo 3 min.","Verter caldo de verduras hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio-suave hasta que las verduras estén tiernas.","Calentar el resto del aceite de oliva en sartén a fuego fuerte.","Saltear las puntas de espárrago reservadas y langostinos pelados hasta que los langostinos estén rosados.","Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","Añadir nata para cocinar a la crema y triturar de nuevo hasta integrar por completo.","Servir la crema caliente repartida en boles, con los langostinos y las puntas de espárrago por encima."}', 'Crema fina de espárragos verdes coronada con langostinos salteados.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_033', 'Gazpacho de remolacha', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 132, 3, 17, 6, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Remolacha cocida","amount":250,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Trocear remolacha cocida en trozos grandes.","Pelar pepino y cortar en trozos grandes.","Cortar tomate maduro en trozos grandes.","Cortar pimiento verde en trozos grandes.","Sumergir pan del día anterior en agua fría hasta que esté bien empapado.","Escurrir el pan con las manos para retirar el exceso de agua.","Triturar la remolacha, el tomate, el pepino, el pimiento verde, ajo y el pan escurrido hasta obtener una crema fina.","Añadir vinagre de jerez, aceite de oliva virgen extra y sal y triturar de nuevo hasta que la mezcla esté homogénea.","Colar la crema a través de un colador fino presionando con una espátula hasta que esté completamente lisa.","Refrigerar el gazpacho en la nevera hasta que esté bien frío.","Servir el gazpacho bien frío en boles o vasos."}', 'Gazpacho de un magenta intenso, la vuelta de tuerca de la remolacha al clásico veraniego.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_034', 'Crema fría de pepino y yogur', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 120, 6, 8, 7, 2, true, true, '{"lactosa"}', '[{"name":"Pepino","amount":400,"unit":"g"},{"name":"Yogur griego natural","amount":200,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar pepino y partir por la mitad a lo largo para retirar las semillas con una cuchara.","Cortar el pepino pelado en trozos grandes y reservar.","Pelar ajo y retirar el germen central partiéndolo por la mitad.","Separar la mitad de menta fresca para triturar y reservar el resto para el emplatado.","Triturar el pepino, yogur griego natural, el ajo y la mitad de la menta fresca hasta obtener una crema fina.","Añadir zumo de limón y triturar de nuevo hasta integrar.","Añadir aceite de oliva virgen extra en hilo fino mientras se sigue triturando hasta emulsionar.","Añadir sal y triturar unos segundos más hasta integrar.","Colar la crema por un colador fino presionando con una cuchara hasta obtener una textura sedosa.","Tapar el recipiente y enfriar en la nevera hasta que la crema esté bien fría.","Picar fino el resto de la menta fresca reservada.","Servir la crema fría en boles, con un chorrito de aceite de oliva virgen extra y la menta picada por encima."}', 'Crema fría de pepino y yogur, ligera y refrescante para los días de más calor.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_035', 'Crema de castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 230, 5, 28, 10, 2, true, true, '{"lactosa"}', '[{"name":"Castañas cocidas y peladas","amount":300,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar puerro y cebolla fino.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Sofreír el puerro picado y la cebolla picada en la olla a fuego medio hasta que estén blandos y transparentes.","Añadir castañas cocidas y peladas y caldo de pollo a la olla.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las castañas estén muy tiernas.","Triturar la mezcla con la batidora hasta obtener una crema fina y untuosa.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Servir la crema caliente con un chorrito de aceite de oliva por encima."}', 'Crema de castañas con dulzor de otoño y un fondo suave de nata.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_036', 'Sopa fría de aguacate y lima', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 202, 4, 10, 17, 2, true, true, '{}', '[{"name":"Aguacate","amount":300,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Lima (zumo)","amount":30,"unit":"ml"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar aguacate y retirar el hueso.","Pelar pepino y cortar en trozos grandes.","Introducir el aguacate, el pepino, caldo de verduras, lima (zumo) y cilantro fresco en el vaso de la batidora.","Triturar hasta obtener una crema fina y homogénea.","Añadir aceite de oliva virgen extra y sal y triturar unos segundos más.","Probar y rectificar de sal o lima al gusto.","Enfriar en la nevera hasta que esté bien fría.","Servir bien fría con unas hojas de cilantro fresco y un chorrito de aceite de oliva virgen extra."}', 'Sopa fría cremosa de aguacate y lima, sin necesidad de nata para conseguir esa textura untuosa.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_037', 'Crema de zanahoria y jengibre', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 150, 3, 20, 6, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jengibre fresco","amount":15,"unit":"g"},{"name":"Caldo de verduras","amount":450,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de naranja","amount":30,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria, patata y cebolla y cortar en trozos medianos.","Rallar jengibre fresco finamente y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","Añadir la zanahoria y la patata y remover para integrar con el sofrito.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la zanahoria y la patata estén tiernas.","Retirar la olla del fuego y añadir zumo de naranja.","Triturar todo con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente en boles."}', 'Crema de zanahoria de un naranja brillante, con un punto picante de jengibre muy suave.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_038', 'Crema de brócoli y queso azul', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 245, 9, 12, 18, 2, false, true, '{"lactosa"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Separar brócoli en arbolitos pequeños.","Pelar patata y cortar en trozos de unos 2 cm.","Pelar cebolla y picar fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté blanda y transparente.","Añadir la patata troceada y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté casi tierna.","Añadir los arbolitos de brócoli y cocer hasta que estén tiernos pero de color verde vivo.","Retirar la olla del fuego.","Desmenuzar queso azul sobre la crema.","Añadir nata para cocinar y remover para integrar.","Triturar todo con la batidora hasta obtener una crema fina.","Servir la crema caliente en boles."}', 'Crema de brócoli con vetas de queso azul fundiéndose en cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_039', 'Caldo gallego', 'sopas_cremas', 'legumbre', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'normal', 'invierno', 320, 18, 30, 14, 4, true, true, '{}', '[{"name":"Patata","amount":500,"unit":"g"},{"name":"Grelos","amount":300,"unit":"g"},{"name":"Judías blancas cocidas","amount":400,"unit":"g"},{"name":"Chorizo","amount":150,"unit":"g"},{"name":"Lacón","amount":150,"unit":"g"},{"name":"Unto","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Agua","amount":1500,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos de unos 3 cm.","Lavar grelos bajo agua fría y trocear en trozos de unos 4 cm.","Cortar chorizo en rodajas gruesas y lacón en trozos generosos.","Pelar ajo y laminar finamente.","Colocar en una olla grande el lacón troceado, unto, el chorizo y agua fría.","Llevar a ebullición a fuego fuerte, retirando con una cuchara la espuma que suba.","Añadir el ajo laminado y pimentón dulce removiendo para integrarlo.","Bajar a fuego suave, tapar y cocer 30 min hasta que las carnes suelten su sabor.","Añadir la patata troceada a la olla.","Añadir los grelos troceados y tapar de nuevo.","Cocer a fuego suave 20 min hasta que la patata esté tierna y los grelos blandos.","Añadir judías blancas cocidas y cocer 10 min más para integrar todos los sabores.","Retirar el lacón y el chorizo de la olla y reservar en un plato.","Añadir sal con cuidado, teniendo en cuenta que el unto y el chorizo ya salan.","Servir el caldo muy caliente en cuencos hondos, repartiendo las carnes en cada uno."}', 'Caldo gallego contundente, con grelos, patata y todo el sabor del compango de cerdo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_040', 'Crema de calabacín con menta', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 140, 4, 10, 9, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Queso en porciones","amount":30,"unit":"g"}]'::jsonb, '{"Lavar calabacín y cortar en rodajas sin pelar.","Pelar patata y cebolla y cortar en trozos pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla a fuego medio hasta que esté transparente.","Añadir el calabacín y la patata y remover para integrar.","Cubrir con caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén tiernas.","Retirar del fuego y añadir queso en porciones.","Añadir la mitad de menta fresca a la olla.","Triturar todo con la batidora hasta obtener una crema fina.","Picar el resto de la menta fresca en tiras finas y reservar.","Servir la crema en boles y decorar con la menta picada."}', 'Crema muy ligera de calabacín, aromatizada con menta fresca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_041', 'Sopa de marisco', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 280, 22, 14, 15, 2, true, true, '{"marisco","moluscos","pescado","sulfitos"}', '[{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Langostinos","amount":200,"unit":"g"},{"name":"Rape","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Fumet de pescado","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las conchas y retirando las barbas.","Pelar langostinos, reservando las cáscaras y la mitad de los langostinos enteros para emplatar.","Cortar rape en trozos de bocado.","Picar cebolla, ajo y pimiento verde muy fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde picados hasta que estén blandos, unos 8 min.","Añadir tomate triturado y pimentón dulce y sofreír 2 min removiendo sin parar.","Verter vino blanco y cocer a fuego fuerte hasta que el alcohol se evapore, unos 2 min.","Añadir fumet de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio durante 10 min.","Añadir los mejillones limpios, tapar la olla y cocer hasta que se abran, unos 5 min.","Retirar los mejillones que no se hayan abierto.","Incorporar el rape y los langostinos y cocer a fuego medio hasta que estén hechos, unos 4 min.","Picar perejil fino.","Servir la sopa muy caliente repartiendo el marisco y el pescado, y espolvorear con el perejil picado."}', 'Sopa de marisco con un caldo rojizo intenso y piezas enteras de mejillón, pescado y langostino.', NULL, '{}', true, NULL, NULL, '{}', NULL),
  ('sopas_cremas_042', 'Crema de tomate asado', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 250, 4, 18, 18, 2, true, true, '{}', '[{"name":"Tomate maduro","amount":800,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar tomate maduro por la mitad.","Cortar cebolla en cuartos.","Disponer el tomate y la cebolla en una bandeja de horno junto con ajo entero y sin pelar.","Rociar aceite de oliva sobre las verduras.","Añadir sal y pimienta negra sobre las verduras.","Hornear a 200 °C durante 30 min, hasta que las verduras estén blandas y ligeramente tostadas por los bordes.","Retirar la bandeja del horno y dejar templar 5 min.","Pelar el ajo asado apretando cada diente para extraer la pulpa.","Triturar el tomate, la cebolla y la pulpa de ajo asados con caldo de verduras hasta obtener una crema fina.","Colar la crema por un chino para eliminar pieles y semillas hasta obtener una textura sedosa.","Calentar la crema en un cazo a fuego medio hasta que esté caliente, sin que llegue a hervir.","Añadir azúcar si la crema resulta muy ácida y remover hasta integrar.","Servir la crema en cuencos con hojas de albahaca fresca y un chorrito de aceite de oliva por encima."}', 'Crema de tomate asado al horno hasta caramelizar, de color rojo intenso y dulzor natural.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_043', 'Crema de tres quesos', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 485, 18, 22, 36, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Queso Emmental","amount":40,"unit":"g"},{"name":"Queso Gruyère","amount":40,"unit":"g"},{"name":"Queso crema","amount":40,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarla en dados pequeños.","Limpiar puerro, retirando la parte verde oscura y las capas externas, y picarlo fino.","Rallar queso emmental y queso gruyère y reservar.","Calentar mantequilla en una olla a fuego medio hasta que se funda.","Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","Añadir la patata en dados y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté tierna.","Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","Volver a calentar la crema a fuego suave y añadir nata para cocinar.","Añadir el queso Emmental rallado, el queso Gruyère rallado y queso crema.","Remover a fuego suave hasta que los quesos se fundan y la crema quede untuosa.","Añadir sal, pimienta negra y nuez moscada y remover.","Servir la crema bien caliente en boles."}', 'Crema untuosa y dorada de patata y puerro fundida con tres quesos, para los días de capricho.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_044', 'Sopa de pescado y marisco', 'sopas_cremas', 'pescado_blanco', 'patatas', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 370, 34, 22, 16, 2, false, true, '{"pescado","marisco","moluscos","sulfitos"}', '[{"name":"Merluza","amount":200,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Fumet de pescado","amount":500,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las valvas y retirando las barbas.","Pelar gambas y reservar las cáscaras por separado.","Pelar patata y cortar en dados de unos 2 cm.","Picar cebolla y pimiento verde en trozos pequeños.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír las cáscaras de gamba reservadas hasta que estén doradas, unos 2 min.","Retirar las cáscaras de gamba y desechar.","Sofreír la cebolla picada, el ajo picado y el pimiento verde picado en el mismo aceite a fuego medio.","Añadir tomate triturado y cocinar a fuego medio hasta que pierda el agua, unos 5 min.","Verter vino blanco y remover hasta que se evapore el alcohol, unos 2 min.","Incorporar los dados de patata, fumet de pescado y azafrán.","Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna, unos 15 min.","Cortar merluza en trozos de unos 3 cm.","Añadir los trozos de merluza y los mejillones limpios; tapar y cocer 5 min.","Incorporar las gambas peladas y cocer hasta que estén rosadas y los mejillones abiertos, unos 2 min.","Salpimentar con sal y espolvorear el perejil picado.","Servir la sopa bien caliente en cuencos hondos."}', 'Sopa de pescado y marisco en caldo dorado de azafrán, con trocitos de merluza, gambas y mejillones.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_045', 'Crema de tomate y albahaca', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 225, 3, 15, 17, 2, true, true, '{"lactosa"}', '[{"name":"Tomate maduro","amount":600,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Albahaca fresca","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar cebolla y zanahoria, y cortar en trozos pequeños.","Llevar agua a ebullición en una olla. Escaldar tomate maduro 30 segundos y retirar.","Pelar los tomates escaldados y cortar en trozos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria hasta que estén blandas.","Añadir el tomate troceado y remover a fuego medio durante 5 min.","Verter caldo de verduras y añadir azúcar. Remover y llevar a ebullición.","Cocer a fuego medio 15 min hasta que las verduras estén muy tiernas.","Retirar del fuego y añadir albahaca fresca, reservando unas hojas para decorar.","Triturar la mezcla hasta obtener una crema fina.","Añadir nata para cocinar y remover. Calentar a fuego suave sin que llegue a hervir.","Añadir sal y remover para integrar.","Servir la crema en boles y decorar con las hojas de albahaca reservadas."}', 'Crema fina de tomate maduro con nata y un toque fresco de albahaca.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_046', 'Gazpacho de fresas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 275, 3, 23, 19, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Fresas","amount":400,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar fresas y retirar el pedúnculo.","Cortar las fresas en trozos y reservar.","Lavar tomate maduro y cortar en trozos.","Pelar parcialmente pepino y cortar en trozos.","Retirar las semillas de pimiento rojo y cortar en trozos.","Pelar ajo, retirar el germen y cortar en trozos.","Sumergir pan en agua fría durante 5 min.","Escurrir el pan con las manos para eliminar el exceso de agua.","Triturar las fresas, el tomate, el pepino, el pimiento, el ajo y el pan hasta obtener una mezcla fina.","Añadir aceite de oliva y vinagre de jerez y triturar de nuevo hasta emulsionar.","Colar la mezcla por un chino o colador fino para eliminar pieles y semillas.","Añadir sal y remover para integrar.","Enfriar el gazpacho en la nevera durante al menos 60 min antes de servir.","Servir bien frío en cuencos o vasos."}', 'Gazpacho rosado de fresas y tomate, dulce y ácido a la vez, para servir bien frío.', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_047', 'Crema de alcachofas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 40, 'normal', 'all', 271, 5, 20, 19, 2, true, true, '{"lactosa"}', '[{"name":"Corazones de alcachofa","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta blanca","amount":1,"unit":"g"}]'::jsonb, '{"Cortar corazones de alcachofa en trozos y rociar con zumo de limón para evitar la oxidación.","Pelar patata y cortar en dados pequeños.","Picar puerro y cebolla fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego suave hasta que estén tiernos y transparentes.","Añadir los corazones de alcachofa troceados y la patata en dados y saltear 3 min a fuego medio.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las alcachofas y la patata estén muy tiernas.","Triturar el contenido de la olla con la batidora hasta obtener una crema fina y homogénea.","Calentar la crema a fuego suave y añadir nata para cocinar, removiendo sin que llegue a hervir.","Sazonar con sal y pimienta blanca y remover para integrar.","Servir la crema bien caliente en boles."}', 'Crema suave y elegante de alcachofas con patata y un toque de nata.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_048', 'Sopa de miso con verduras', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 123, 7, 8, 7, 2, true, true, '{"soja","sesamo"}', '[{"name":"Miso","amount":40,"unit":"g"},{"name":"Alga wakame","amount":5,"unit":"g"},{"name":"Tofu firme","amount":100,"unit":"g"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Agua","amount":600,"unit":"ml"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"}]'::jsonb, '{"Hidratar alga wakame en agua fría durante 5 min.","Escurrir el alga wakame y reservar.","Cortar tofu firme en dados de unos 1 cm.","Laminar champiñones en láminas finas.","Picar cebolleta en aros finos, separando la parte blanca de la verde.","Llevar agua a ebullición suave en una olla a fuego medio, sin que llegue a borbotón fuerte.","Añadir los champiñones laminados y la parte blanca de la cebolleta; cocer 3 min.","Retirar un cazo de caldo caliente a un bol aparte.","Disolver miso en el caldo del bol removiendo hasta integrar por completo.","Incorporar el miso disuelto a la olla fuera del fuego o a fuego muy suave, sin que hierva.","Añadir el tofu en dados y el alga wakame escurrida; calentar 2 min sin que llegue a hervir.","Añadir salsa de soja y aceite de sésamo; remover con suavidad.","Servir la sopa caliente en cuencos y decorar con los aros verdes de cebolleta."}', 'Sopa de miso japonesa con tofu, champiñones y algas, ligera y reconfortante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_049', 'Crema de garbanzos especiada', 'sopas_cremas', 'legumbre', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 35, 'facil', 'all', 388, 16, 45, 16, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Cúrcuma","amount":2,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en trozos finos.","Cortar zanahoria en trozos pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo hasta que estén transparentes.","Añadir la zanahoria y sofreír 3 min más a fuego medio.","Añadir comino molido, cúrcuma y pimentón dulce y remover 1 min para tostar las especias.","Añadir garbanzos cocidos y caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la zanahoria esté tierna.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir sal y remover para integrar.","Servir la crema caliente con un chorrito de aceite de oliva y una pizca de comino molido."}', 'Crema especiada de garbanzos con comino y cúrcuma, cálida y reconfortante.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_050', 'Sopa juliana con jamón', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 157, 8, 11, 9, 2, true, true, '{}', '[{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Judía verde","amount":60,"unit":"g"},{"name":"Nabo","amount":50,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar y cortar zanahoria en juliana fina.","Lavar y cortar puerro en juliana fina.","Lavar y cortar judía verde en juliana fina.","Pelar y cortar nabo en juliana fina.","Cortar jamón serrano en tiras finas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la zanahoria, el puerro, la judía verde y el nabo en juliana hasta que empiecen a ablandar.","Añadir el jamón serrano y sofreír hasta que suelte su aroma.","Verter caldo de pollo y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las verduras estén tiernas pero con algo de textura.","Añadir sal, teniendo en cuenta que el jamón ya aporta salinidad.","Servir bien caliente en boles individuales."}', 'Sopa juliana de verduras finas cortadas en tiras con jamón serrano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_051', 'Crema de espinacas con nata', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 223, 6, 16, 15, 2, true, true, '{"lactosa"}', '[{"name":"Espinacas frescas","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar espinacas frescas bajo el grifo para eliminar restos de tierra.","Pelar cebolla y picarla fina.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los dados de patata y sofreír 2 min removiendo para que no se peguen.","Verter caldo de verduras y llevar a ebullición a fuego medio.","Cocer tapado a fuego medio hasta que la patata esté tierna.","Añadir las espinacas lavadas y cocer hasta que reduzcan de volumen.","Retirar del fuego y triturar todo con la batidora hasta obtener una crema fina.","Volver a calentar la crema a fuego suave.","Añadir nata para cocinar y remover sin dejar que hierva.","Añadir nuez moscada y sal y remover para integrar.","Servir la crema bien caliente en cuencos."}', 'Crema de espinacas frescas con nata, verde intenso y muy suave.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_052', 'Sopa de tomate con albahaca fresca', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 222, 4, 20, 14, 2, true, true, '{"gluten"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan tostado","amount":40,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en una olla.","Escaldar tomate maduro en el agua hirviendo durante 30 segundos.","Retirar los tomates y pelarlos cuando estén fríos al tacto.","Cortar los tomates pelados en dados y reservar.","Picar cebolla finamente.","Picar ajo finamente.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos, sin que se doren.","Añadir los dados de tomate y remover a fuego medio durante 5 min.","Verter caldo de verduras y añadir azúcar.","Llevar a ebullición a fuego fuerte.","Cocer a fuego suave 15 min, aplastando el tomate con una cuchara hasta que se deshaga.","Trocear albahaca fresca a mano, reservando unas hojas enteras para emplatar.","Salpimentar con sal y retirar la olla del fuego.","Añadir la albahaca troceada a la sopa y remover.","Servir la sopa con pan tostado y las hojas de albahaca enteras por encima."}', 'Sopa ligera de tomate con hojas de albahaca fresca y picatostes.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_053', 'Crema de setas variadas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 240, 6, 18, 16, 2, true, true, '{"lactosa"}', '[{"name":"Setas variadas","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":350,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo, sin lavarlas bajo el grifo.","Laminar las setas limpias.","Pelar y picar cebolla fino.","Pelar y picar ajo fino.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo picados hasta que estén transparentes.","Añadir las setas laminadas y saltear a fuego fuerte hasta que suelten su agua y se doren ligeramente.","Retirar un puñado de setas salteadas y reservar en un plato para emplatar.","Añadir la patata en dados y caldo de verduras al resto de setas en la olla.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata esté tierna.","Añadir tomillo fresco y triturar con la batidora hasta obtener una crema fina.","Volver la crema al fuego suave y añadir nata para cocinar.","Salpimentar con sal y pimienta negra, y remover hasta integrar.","Servir la crema caliente y repartir las setas reservadas por encima."}', 'Crema de setas variadas con aroma a bosque y un fondo de nata.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_054', 'Vichyssoise de puerro y manzana', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'verano', 326, 4, 28, 22, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Manzana Golden","amount":150,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta blanca","amount":1,"unit":"g"}]'::jsonb, '{"Limpiar puerro retirando la parte verde más dura y las raíces.","Cortar el puerro limpio en rodajas de unos 5 mm.","Pelar patata y cortarla en dados de unos 2 cm.","Pelar manzana golden, descorazonarla y cortarla en trozos similares a la patata.","Fundir mantequilla en una olla a fuego suave hasta que esté líquida.","Sofreír el puerro en la mantequilla a fuego suave hasta que esté tierno sin que se dore.","Añadir la patata y la manzana a la olla y remover para integrar con el puerro.","Sofreír la patata y la manzana junto al puerro a fuego medio durante 2 min.","Verter caldo de verduras en la olla y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la patata esté muy tierna.","Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema muy fina.","Colar la crema por un colador fino presionando con un cazo para lograr una textura sedosa.","Añadir nata para cocinar, sal y pimienta blanca y remover hasta integrar.","Dejar enfriar la crema a temperatura ambiente antes de refrigerar.","Refrigerar la crema en la olla tapada hasta que esté bien fría.","Picar cebollino fino justo antes de servir.","Servir la vichyssoise fría en boles repartiendo el cebollino picado por encima."}', 'Vichyssoise fría de puerro y patata con un toque dulce de manzana.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_055', 'Crema de calabaza con castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'invierno', 334, 5, 38, 18, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":500,"unit":"g"},{"name":"Castañas cocidas","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar calabaza y cortar en dados de 2-3 cm.","Picar cebolla y puerro fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro a fuego suave hasta que estén blandos.","Añadir los dados de calabaza y saltear a fuego medio removiendo.","Reservar un puñado de castañas cocidas para el emplatado.","Añadir el resto de las castañas cocidas a la olla.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la calabaza esté muy tierna.","Triturar todo con la batidora hasta obtener una crema fina y homogénea.","Calentar la crema a fuego suave y añadir nata para cocinar.","Añadir nuez moscada y sal; remover hasta integrar.","Cortar las castañas reservadas en trozos gruesos.","Servir la crema caliente con los trozos de castaña por encima."}', 'Crema de calabaza asada con castañas, muy de otoño.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_056', 'Sopa fría de melón y jamón', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 221, 9, 17, 13, 2, true, true, '{"lactosa"}', '[{"name":"Melón","amount":500,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar melón, retirar las semillas y cortar la pulpa en trozos grandes.","Triturar los trozos de melón con yogur griego, aceite de oliva y sal hasta obtener una crema fina.","Añadir pimienta negra y triturar de nuevo unos segundos hasta integrar.","Refrigerar la crema tapada hasta que esté bien fría.","Cortar jamón serrano en virutas finas.","Separar unas hojas de menta fresca para decorar.","Repartir la sopa fría en boles individuales.","Decorar cada bol con las virutas de jamón serrano y las hojas de menta fresca. Servir de inmediato."}', 'Sopa fría de melón con virutas de jamón serrano, perfecta para el verano.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_057', 'Crema de pimientos asados', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 258, 4, 20, 18, 2, true, true, '{"sulfitos"}', '[{"name":"Pimiento rojo","amount":500,"unit":"g"},{"name":"Pimiento amarillo","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":5,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar cebolla en cuartos.","Disponer pimiento rojo y pimiento amarillo enteros en una bandeja de horno junto con la cebolla y tomate maduro.","Rociar con aceite de oliva y hornear a 200 °C durante 40 min, hasta que la piel de los pimientos esté arrugada y tostada.","Retirar la bandeja del horno y cubrir los pimientos con film o introducirlos en una bolsa cerrada.","Dejar sudar los pimientos tapados 15 min hasta que estén templados.","Pelar los pimientos y retirar las semillas, reservando la pulpa.","Triturar la pulpa de los pimientos junto con la cebolla asada, el tomate asado y caldo de verduras hasta obtener una crema fina.","Colar la crema por un colador fino hasta conseguir una textura sedosa.","Calentar la crema en un cazo a fuego medio hasta que esté bien caliente.","Añadir el resto del aceite de oliva, vinagre de jerez y azúcar, y remover para integrar.","Añadir sal y remover.","Servir la crema caliente o templada."}', 'Crema de pimientos asados, dulce y con un intenso color rojo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_058', 'Consomé con jerez', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 170, 'normal', 'invierno', 55, 6, 3, 2, 6, false, true, '{"huevo","sulfitos","apio"}', '[{"name":"Hueso de ternera","amount":400,"unit":"g"},{"name":"Morcillo de ternera","amount":200,"unit":"g"},{"name":"Hueso de jamón","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Apio","amount":50,"unit":"g"},{"name":"Agua","amount":2000,"unit":"ml"},{"name":"Jerez seco","amount":40,"unit":"ml"},{"name":"Clara de huevo","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar zanahoria, puerro, cebolla y apio en trozos grandes.","Colocar hueso de ternera, morcillo de ternera y hueso de jamón en una olla grande.","Añadir agua fría y llevar a ebullición a fuego fuerte.","Retirar la espuma que sube a la superficie con una espumadera hasta que el caldo quede limpio.","Añadir las verduras troceadas a la olla.","Bajar el fuego a suave y cocer sin que hierva con fuerza durante 120 min, espumando de vez en cuando.","Colar el caldo a través de un colador fino, desechando los huesos y las verduras.","Dejar templar el caldo colado hasta que esté tibio pero no caliente.","Batir ligeramente clara de huevo en un bol pequeño.","Incorporar la clara batida al caldo templado y remover suavemente para repartirla.","Llevar a ebullición suave a fuego medio sin remover hasta que la clara forme una costra en la superficie.","Colar de nuevo con cuidado a través de un paño fino, sin presionar, para obtener un caldo cristalino.","Añadir sal y jerez seco al consomé clarificado.","Calentar a fuego suave hasta que esté bien caliente sin que llegue a hervir.","Servir bien caliente en tazas de consomé."}', 'Consomé de ternera clarificado, aromatizado con un toque de jerez seco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_059', 'Crema de langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 60, 'elaborada', 'all', 420, 30, 12, 28, 2, true, true, '{"marisco","pescado","lactosa","sulfitos"}', '[{"name":"Langostinos","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"g"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Fumet de pescado","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar langostinos, reservando cáscaras y cabezas por separado. Guardar la carne en la nevera.","Picar cebolla, zanahoria y puerro en trozos pequeños.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee.","Sofreír las cáscaras y cabezas de langostino a fuego fuerte 5 min, presionándolas para que suelten todo su jugo.","Añadir la cebolla, la zanahoria y el puerro picados a la olla.","Sofreír las verduras a fuego medio hasta que estén blandas, unos 8 min.","Añadir tomate triturado y pimentón dulce y cocinar a fuego medio 3 min hasta que el tomate pierda el agua.","Añadir brandy y flambear acercando una llama, o subir el fuego fuerte, hasta que el alcohol se evapore por completo.","Añadir fumet de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio 20 min hasta que las cáscaras hayan cedido todo su sabor.","Triturar todo el conjunto, incluidas las cáscaras, con el túrmix o en batidora hasta obtener una pasta fina.","Colar la crema por un chino fino sobre la olla, presionando bien con una cuchara para extraer todo el sabor.","Calentar la crema colada a fuego suave, añadir nata para cocinar y remover hasta integrar sin que llegue a hervir.","Salpimentar con sal y remover.","Calentar un chorrito de aceite de oliva en sartén a fuego fuerte hasta que humee.","Saltear la carne de los langostinos reservada 2 min hasta que estén rosados y ligeramente dorados.","Servir la crema caliente en boles y colocar los langostinos salteados por encima."}', 'Crema untuosa de langostinos, todo el sabor del marisco en cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_060', 'Sopa de ajo con huevo escalfado', 'sopas_cremas', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 358, 14, 26, 22, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan duro","amount":100,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pan duro en rebanadas o taquitos finos.","Pelar y laminar ajo.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo laminado hasta que se dore ligeramente, sin que se queme.","Añadir el pan y saltear hasta que absorba el aceite y se dore ligeramente.","Retirar la cazuela del fuego y añadir pimentón dulce, removiendo rápido para que no se queme.","Verter caldo de pollo y llevar a ebullición a fuego fuerte.","Añadir sal y cocer a fuego medio hasta que el pan se deshaga parcialmente y espese el caldo.","Cascar huevo uno a uno en un hueco hecho en la sopa, separando cada uno.","Cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","Servir de inmediato en cazuela individual muy caliente."}', 'Sopa castellana de ajo con pimentón y un huevo escalfado en el centro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_061', 'Sopa de tomate con grilled cheese', 'sopas_cremas', 'none', NULL, ARRAY['cena','primero','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 517, 17, 38, 33, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tomate triturado","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Queso cheddar en lonchas","amount":80,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla fino.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","Añadir tomate triturado y azúcar.","Cocer a fuego medio durante 10 min, removiendo de vez en cuando.","Untar una cara de cada rebanada de pan de molde con mantequilla.","Colocar queso cheddar en lonchas entre 2 rebanadas, con la mantequilla hacia afuera.","Verter caldo de verduras en la olla y llevar a ebullición.","Cocer a fuego medio durante 10 min.","Calentar sartén a fuego medio.","Tostar los sándwiches hasta que estén dorados por un lado.","Dar la vuelta a los sándwiches y tostar hasta que estén dorados y el queso cheddar esté fundido.","Triturar la sopa hasta obtener una crema fina.","Añadir nata para cocinar y calentar a fuego suave sin que hierva.","Añadir sal y remover.","Cortar los sándwiches en tiras.","Servir la crema de tomate caliente con las tiras de sándwich al lado para mojar."}', 'Sopa de tomate casera para mojar tiras de sándwich de queso fundido.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_062', 'Crema de calabacín y queso azul', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 298, 9, 16, 22, 2, false, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":350,"unit":"ml"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picarla fina.","Pelar patata y cortarla en dados pequeños.","Lavar calabacín y cortarlo en rodajas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir la patata y el calabacín y saltear 3 min a fuego medio.","Añadir caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén tiernas.","Retirar del fuego y desmenuzar la mitad de queso azul sobre la olla.","Triturar todo con la batidora hasta obtener una crema fina.","Volver a calentar a fuego suave y añadir nata para cocinar.","Remover hasta integrar la nata por completo.","Salpimentar con sal y pimienta negra al gusto.","Servir la crema con el resto del queso azul desmenuzado por encima."}', 'Crema de calabacín con vetas de queso azul fundiéndose por encima.', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_063', 'Vichyssoise de coliflor', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'verano', 150, 5, 14, 9, 2, true, true, '{"lactosa"}', '[{"name":"Coliflor","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Puerro","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y laminar en rodajas finas, desechando la parte verde oscura.","Pelar cebolla y picar en trozos pequeños.","Separar coliflor en ramilletes pequeños y lavar bien bajo el grifo.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","Añadir la coliflor y la patata a la olla.","Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición.","Cocer a fuego medio hasta que la coliflor y la patata estén muy tiernas.","Retirar del fuego y triturar con la batidora hasta obtener una crema completamente fina.","Añadir nata para cocinar y remover hasta integrar por completo.","Dejar enfriar a temperatura ambiente antes de refrigerar.","Refrigerar la crema hasta que esté bien fría.","Servir la vichyssoise bien fría en cuencos."}', 'Vichyssoise blanca y sedosa de coliflor y puerro, más ligera que la clásica de patata', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_064', 'Crema de boniato y coco', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 230, 4, 30, 11, 2, true, true, '{}', '[{"name":"Boniato","amount":400,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Leche de coco","amount":200,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en dados de 2 cm.","Pelar cebolla y picar fino.","Pelar ajo y picar fino.","Pelar jengibre fresco y rallar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada, el ajo picado y el jengibre rallado hasta que estén fragantes.","Añadir los dados de boniato y remover para integrar con el sofrito.","Verter caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que el boniato esté muy tierno.","Añadir leche de coco y cocer 2 min más a fuego suave.","Triturar todo con la batidora hasta obtener una crema fina y untuosa.","Servir bien caliente."}', 'Crema naranja suave de boniato asado con leche de coco, cremosa sin necesitar nata', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_065', 'Gazpacho de pepino y aguacate', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 190, 5, 9, 15, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Pepino","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Yogur natural","amount":100,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Agua fría","amount":100,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortar en trozos grandes.","Cortar aguacate por la mitad y deshuesar.","Extraer la pulpa del aguacate con una cuchara y reservar.","Retirar las semillas de pimiento verde y cortar en trozos.","Picar cebolleta en trozos gruesos.","Pelar ajo.","Introducir el pepino, el aguacate, el pimiento verde, la cebolleta y el ajo en el vaso de la batidora.","Añadir yogur natural, zumo de lima, vinagre de jerez y agua fría.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar el gazpacho hasta que esté bien frío.","Servir inmediatamente en cuencos fríos."}', 'Gazpacho verde intenso de pepino y aguacate, muy refrescante en días de calor', NULL, '{}', NULL, true, NULL, '{}', NULL)
