insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id
) values
  ('sopas_cremas_066', 'Crema de guisantes y jamón crujiente', 'sopas_cremas', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 210, 12, 18, 9, 2, true, true, '{}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Caldo de pollo","amount":300,"unit":"ml"},{"name":"Jamón serrano en lonchas finas","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"}]'::jsonb, '{"Pelar cebolla y puerro, y picarlos en trozos pequeños.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro picados hasta que estén transparentes.","Añadir la patata en dados y caldo de pollo, y llevar a ebullición.","Cocer a fuego medio durante 10 min, hasta que la patata esté tierna.","Calentar el aceite de oliva restante en sartén a fuego fuerte.","Dorar jamón serrano en lonchas finas hasta que quede crujiente.","Retirar el jamón sobre papel absorbente y trocearlo en pedazos pequeños.","Añadir guisantes congelados a la olla y cocer 5 min hasta que estén tiernos y mantengan el color verde.","Añadir menta fresca a la olla y triturar la crema con la batidora hasta que quede fina y homogénea.","Servir la crema caliente en boles y repartir el jamón crujiente troceado por encima."}', 'Crema de guisantes verde vivo, coronada con virutas doradas de jamón crujiente', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_067', 'Sopa de tomate y pan (pappa al pomodoro)', 'sopas_cremas', 'none', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'verano', 260, 6, 32, 12, 2, true, true, '{"gluten"}', '[{"name":"Pan payés del día anterior","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar pan payés del día anterior en trozos irregulares de unos 3 cm.","Pelar y laminar ajo.","Calentar aceite de oliva en una olla a fuego suave.","Sofreír el ajo laminado hasta que esté fragante, sin que tome color.","Añadir tomate triturado y cocer a fuego medio, removiendo de vez en cuando.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Añadir el pan troceado y remover para que se empape bien del caldo de tomate.","Cocer a fuego suave aplastando el pan con una cuchara hasta obtener textura espesa y rústica.","Retirar del fuego y añadir albahaca fresca troceada con las manos.","Añadir el resto del aceite de oliva y remover suavemente para integrarlo.","Reposar la sopa 5 min antes de servir, tibia o a temperatura ambiente.","Servir en boles con un hilo de aceite de oliva por encima."}', 'Sopa rústica y espesa de tomate y pan al estilo italiano, con aceite de oliva por encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_068', 'Crema de puerros con almendra', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 210, 5, 18, 13, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Puerro","amount":350,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Almendras tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y cortar en rodajas finas, desechando la parte verde más dura.","Pelar cebolla y picar en trozos finos.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna.","Cortar almendras tostadas en trozos gruesos.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente con las almendras troceadas por encima."}', 'Crema blanca aterciopelada de puerro, con almendra tostada troceada por encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_069', 'Velouté de marisco con brandy', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'all', 270, 16, 10, 18, 2, false, true, '{"marisco","lactosa","gluten","pescado"}', '[{"name":"Gambas","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Fumet de pescado","amount":400,"unit":"ml"},{"name":"Tomate concentrado","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar gambas, separando las colas de las cáscaras y cabezas.","Picar cebolla, puerro y zanahoria en trozos finos.","Calentar aceite de oliva en una olla a fuego fuerte.","Saltear las cáscaras y cabezas de gamba hasta que tomen color.","Retirar las cáscaras y cabezas y reservar.","Sofreír la cebolla picada, el puerro picado y la zanahoria picada a fuego medio hasta que estén blandos.","Añadir tomate concentrado y remover a fuego medio durante 1 min.","Verter brandy y llevar a ebullición hasta que se evapore el alcohol.","Añadir fumet de pescado y las cáscaras y cabezas reservadas.","Cocer a fuego medio durante 15 min.","Colar el caldo con un colador, descartando cáscaras y verduras.","Fundir mantequilla en un cazo limpio a fuego medio.","Añadir harina y remover sin parar durante 1 min hasta obtener un roux liso.","Incorporar el caldo colado poco a poco, removiendo sin parar, hasta que la velouté espese.","Añadir las colas de gamba peladas y cocer a fuego medio hasta que estén rosadas.","Añadir nata para cocinar y remover hasta integrar.","Triturar la velouté con una batidora hasta obtener una textura sedosa.","Servir la velouté caliente en cuencos."}', 'Velouté naranja pálido de marisco, con el aroma que sube al flambear el brandy', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_070', 'Crema fría de guisantes, menta y langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'verano', 220, 17, 14, 11, 2, true, true, '{"marisco","lactosa"}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":250,"unit":"ml"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar ajo y reservar.","Llevar a ebullición caldo de verduras en un cazo a fuego fuerte.","Añadir guisantes congelados y el ajo pelado al caldo cuando rompa a hervir.","Cocer los guisantes y el ajo a fuego medio hasta que estén tiernos.","Calentar sartén a fuego fuerte con aceite de oliva.","Saltear langostinos pelados en la sartén caliente hasta que estén rosados.","Retirar los langostinos de la sartén y reservar en la nevera.","Escurrir los guisantes y el ajo cocidos, reservando el caldo de cocción.","Dejar enfriar los guisantes escurridos y el caldo reservado a temperatura ambiente.","Triturar los guisantes con el caldo reservado, menta fresca, yogur natural y el aceite de oliva hasta obtener una crema fina.","Colar la crema por un colador fino para lograr una textura más sedosa.","Refrigerar la crema en la nevera hasta que esté bien fría.","Servir la crema fría en boles con los langostinos reservados repartidos por encima."}', 'Crema fría de guisantes y menta, verde vivo con el rosa de los langostinos encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_071', 'Sopa de cebolla con queso gratinado y jamón', 'sopas_cremas', 'cerdo', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'invierno', 340, 18, 26, 18, 2, true, false, '{"lactosa","gluten","sulfitos"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Pan de baguette en rebanadas","amount":60,"unit":"g"},{"name":"Queso gruyère rallado","amount":80,"unit":"g"},{"name":"Jamón cocido en tiras","amount":60,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y cortarla en juliana fina.","Fundir mantequilla en una olla a fuego medio-bajo.","Añadir la cebolla y sofreír a fuego suave, removiendo de vez en cuando, hasta que esté dorada y caramelizada.","Verter vino blanco y subir a fuego fuerte hasta que evapore el alcohol.","Añadir caldo de carne y tomillo y llevar a ebullición.","Cocer a fuego suave durante 10 min.","Precalentar el horno en función gratinador a 220 °C.","Repartir la sopa en 2 boles aptos para horno.","Colocar pan de baguette en rebanadas sobre cada bol.","Repartir jamón cocido en tiras sobre el pan de cada bol.","Cubrir con queso gruyère rallado repartido a partes iguales entre los 2 boles.","Gratinar en el horno 4 min hasta que el queso esté fundido y dorado.","Servir de inmediato con cuidado, pues los boles estarán muy calientes."}', 'Sopa de cebolla caramelizada con queso fundido y dorado sobre el caldo oscuro, y jamón', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_072', 'Crema de calabaza asada con salvia frita', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'invierno', 230, 4, 22, 14, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":500,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Hojas de salvia fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y retirar las semillas.","Cortar la calabaza en dados de 3 cm.","Cortar cebolla en cuartos.","Colocar la calabaza y la cebolla en una bandeja de horno junto con ajo sin pelar.","Rociar con aceite de oliva y repartir bien por la bandeja.","Hornear a 200 °C durante 35 min hasta que la calabaza esté tierna y ligeramente dorada.","Retirar la bandeja del horno y dejar templar 5 min.","Pelar los dientes de ajo asados.","Poner la calabaza, la cebolla y el ajo en una olla.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio durante 5 min.","Añadir nata para cocinar y triturar con la batidora hasta obtener una crema fina.","Calentar el aceite de oliva restante en sartén a fuego fuerte.","Freír hojas de salvia fresca durante 1 min hasta que estén crujientes.","Retirar las hojas de salvia frita sobre papel absorbente.","Servir la crema caliente con las hojas de salvia frita por encima."}', 'Crema naranja profundo de calabaza asada, con hojas de salvia crujientes encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_073', 'Gazpacho verde de pepino y manzana', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 140, 2, 14, 9, 2, true, true, '{"apio"}', '[{"name":"Pepino","amount":250,"unit":"g"},{"name":"Manzana verde","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Apio","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Agua fría","amount":100,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortar en trozos grandes.","Descorazonar manzana verde y cortar en trozos, dejando la piel.","Retirar las semillas de pimiento verde y cortar en trozos.","Cortar apio en trozos y pelar ajo.","Introducir el pepino, la manzana verde, el pimiento verde y el apio en el vaso de la batidora.","Añadir el ajo, vinagre de manzana y agua fría al vaso.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar el gazpacho hasta que esté muy frío.","Servir el gazpacho muy frío en cuencos o vasos."}', 'Gazpacho verde brillante de pepino y manzana, dulce y ácido a la vez', NULL, '{}', NULL, true, NULL, '{}', NULL),
  ('sopas_cremas_074', 'Crema de apionabo con avellanas tostadas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 220, 5, 17, 14, 2, true, true, '{"apio","lactosa","frutos_secos"}', '[{"name":"Apionabo","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Avellanas tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar apionabo, retirando bien la piel gruesa, y cortar en dados de 2 cm.","Pelar patata y cortar en dados de 2 cm.","Pelar cebolla y picar fino.","Calentar aceite de oliva en una olla a fuego medio y sofreír la cebolla picada hasta que esté transparente.","Añadir el apionabo y la patata en dados a la olla.","Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las verduras estén muy tiernas.","Picar groseramente avellanas tostadas con un cuchillo.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente con las avellanas picadas por encima."}', 'Crema blanca suave de apionabo, con avellanas troceadas por encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_075', 'Sopa de tomate asado con burrata', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 260, 9, 14, 19, 2, true, false, '{"lactosa"}', '[{"name":"Tomate maduro","amount":600,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Burrata","amount":125,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar tomate maduro por la mitad.","Cortar cebolla en cuartos.","Disponer el tomate y la cebolla en una bandeja de horno junto con ajo entero y con piel.","Rociar con aceite de oliva y añadir sal por encima.","Hornear a 200 °C durante 30 min hasta que el tomate esté blando y ligeramente tostado.","Retirar la bandeja del horno y dejar templar hasta que se pueda manipular sin quemarse.","Pelar el ajo asado apretando cada diente para extraer la pulpa.","Triturar el tomate, la cebolla y el ajo asados con una batidora hasta obtener una crema fina.","Colar la crema por un colador fino presionando con una cuchara hasta que la textura sea sedosa.","Calentar la crema en una olla a fuego suave durante 5 min hasta que esté bien caliente.","Rectificar de sal al gusto y remover.","Verter la sopa caliente en boles.","Colocar burrata partida en trozos en el centro de cada bol.","Terminar con un chorrito de aceite de oliva y hojas de albahaca fresca por encima."}', 'Sopa de tomate asado rojo intenso, con el corte cremoso de la burrata en el centro', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_076', 'Crema de espárragos verdes con parmesano', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 180, 8, 12, 11, 2, true, true, '{"lactosa"}', '[{"name":"Espárragos verdes","amount":350,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Queso parmesano en virutas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar espárragos verdes y retirar la parte final dura del tallo.","Cortar los espárragos en trozos, reservando las puntas para emplatar.","Pelar y picar cebolla.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los dados de patata y los trozos de espárrago y saltear 2 min a fuego medio.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y los espárragos estén tiernos.","Calentar sartén a fuego medio con un chorrito de aceite de oliva.","Saltear las puntas de espárrago reservadas hasta que estén tiernas y ligeramente doradas.","Retirar la olla del fuego y triturar la crema con la batidora hasta que quede fina y homogénea.","Servir la crema caliente con las puntas salteadas y queso parmesano en virutas por encima."}', 'Crema verde vivo de espárragos, con virutas de parmesano flotando en la superficie', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_077', 'Vichyssoise con crujiente de jamón', 'sopas_cremas', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'verano', 240, 9, 22, 13, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":250,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Jamón serrano en lonchas finas","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y laminar en rodajas finas, desechando la parte verde oscura.","Pelar cebolla y picar fino.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla hasta que estén blandos y transparentes.","Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","Llevar a ebullición y cocer hasta que la patata esté tierna.","Calentar un chorrito de aceite de oliva en sartén a fuego medio.","Dorar jamón serrano en lonchas finas hasta que queden crujientes.","Retirar el jamón y dejar enfriar sobre papel absorbente.","Trocear el jamón en fragmentos pequeños y reservar.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema completamente fina.","Dejar enfriar la crema y refrigerar hasta que esté bien fría.","Servir la vichyssoise bien fría con el crujiente de jamón repartido por encima."}', 'Vichyssoise blanca y fría, con virutas doradas de jamón crujiente por encima', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_078', 'Crema de setas con castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 200, 6, 22, 9, 2, true, true, '{"lactosa"}', '[{"name":"Setas variadas","amount":300,"unit":"g"},{"name":"Castañas cocidas","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Cortar las setas en trozos regulares.","Pelar cebolla y puerro y picar ambos en trozos finos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro picados hasta que estén blandos y translúcidos.","Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten su agua y esta se evapore.","Añadir castañas cocidas y tomillo y remover para integrar.","Verter caldo de verduras y llevar a ebullición a fuego medio.","Cocer a fuego suave hasta que todos los ingredientes estén tiernos.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar el conjunto con la batidora hasta obtener una crema fina y homogénea.","Servir la crema bien caliente en cuencos."}', 'Crema marrón profunda de setas y castañas, con dulzor de otoño de fondo', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_079', 'Sopa fría de tomate y sandía', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 140, 2, 15, 8, 2, true, true, '{"sulfitos"}', '[{"name":"Tomate maduro","amount":300,"unit":"g"},{"name":"Sandía","amount":300,"unit":"g"},{"name":"Pepino","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Albahaca fresca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate maduro en trozos, retirando el pedúnculo.","Cortar sandía en trozos, retirando las pepitas si las hubiera.","Pelar pepino y cortar en trozos.","Pelar ajo.","Introducir el tomate, la sandía, el pepino y el ajo en el vaso de la batidora.","Añadir vinagre de jerez al vaso de la batidora.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar la sopa hasta que esté muy fría.","Picar albahaca fresca fina justo antes de servir.","Servir la sopa muy fría con la albahaca picada por encima."}', 'Sopa fría de tomate y sandía, rojo vivo y sorprendentemente refrescante', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
  ('sopas_cremas_080', 'Crema de zanahoria y naranja', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 170, 3, 24, 7, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Zumo de naranja","amount":150,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas.","Pelar cebolla y picar fino.","Pelar patata y cortar en dados pequeños.","Pelar jengibre fresco y rallar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el jengibre rallado hasta que estén fragantes.","Añadir la zanahoria y la patata y remover.","Verter caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén muy tiernas.","Añadir zumo de naranja y cocer 2 min más.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir un poco de agua si la crema ha quedado demasiado espesa y remover.","Servir caliente."}', 'Crema de zanahoria y naranja, naranja intenso por partida doble y muy suave', NULL, '{}', NULL, NULL, NULL, '{}', NULL),
